INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 1, 'Maqaa Rabbii Akkaan Mararfataa Akkaan Rahmata Godhaa Taheetiin.[1]', '[1] suuraan faatihaa tuni irra caaltuu suuraalee qur''aanaati. Nabiyyiin S.A.W. Abii sa''iidiin akkana jedhe "irra caaltuu suuraalee qur''aanaa sibeeysisa, isiin -Alhamdu lillaahi Rabbil aalamiin- jedheen. isiin torban deddeebituu taate, qur''aana guddaa ani isa kennames" jedheen. {bukhaariitu odeesse}.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 2, 'Faaruun hundi tan Rabbii Gooftaa aalamaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 3, 'Akkaan mararfataa akkaan rahmata godhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 4, 'Abbaa (mootii) guyyaa murtii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 5, 'Si qofa gabbarra; Si qofatti gargaarsifannas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 6, 'Daandii sirraawaatti nu qajeelchi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 7, 'Karaa warra isaan irratti tola ooltee; kan warra irratti dallanamee kanhintahin, kan jallattootaa (kan hintahin) (nu qajeelchi) [1] [2]', '[2] suuraan faatihaa tuni irra caaltuu suuraalee qur''aanaati. Nabiyyiin S.A.W. Abii sa''iidiin akkana jedhe "irra caaltuu suuraalee qur''aanaa sibeeysisa, isiin -Alhamdu lillaahi Rabbil aalamiin- jedheen. isiin torban deddeebituu taate, qur''aana guddaa ani isa kennames" jedheen. {bukhaariitu odeesse}.
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 1, 'Alif, Laam, Miim [1][2]', '[1] harfiiwwan maqaan waamamtu tana tan jalqaba suuraawwaniitti argamtu hundaa hiikkaa isii Rabbumaatu beeka jedhanii isatti irkisuu barbaachisa. (ibnu kasiir).
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 2, 'Kitaabni kuni [Rabbiin biraa ta’uu isaa keessatti] mamiin isa keessa hin jirreedha; warra Rabbiin sodaataniif qajeelfama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 3, 'Isaannan "Ghaybitti" (wantoota miiraan hin dhaqqabamnetti) amanan, kan salaata sirnaan salaataniifi waan Nuti isaaniif arjoomne irraa kennataniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 4, 'Ammas isaan warra waan gara keetti buufameefi waan si dura buufametti amananiifi isaan Aakhiraa dhugoomsaniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 5, 'Warri sun qajeelfama Rabbii isaanii biraa ta’e irra jiru. Ammas warri sun isaanumatu milkaawoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 6, 'Dhugumatti, isaannan kafaran isaan akeekkachiiftes isaan akeekkachiisuu baattes [lamaanuu] isaan irratti wal qixa; hin amanan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 7, 'Rabbiin onneewwan isaaniirrattiifi dhageettuu isaanii irratti cufe; agartuu isaanii irras haguuggiitu jira. Isaaniif azaaba guddaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 8, 'Namoota irraa nama "Rabbiifi Guyyaa Aakhiraatti amanne" jedhutu jira. ammoo isaan warra amanee miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 9, 'Rabbiifi warra amanan gowwoomsan [isaanitti fakkaata]; garuu lubbuu isaanii malee homaa hin gowwoomsanu. ammoo hinbeekan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 10, 'Onneewwan isaanii keessa dhukkuba [shakkiifi nifaaqaatu] jira. Rabbiinis dhukkuba isaaniif dabale. Waan kijibaa turaniif jechas adabbii laalessaa ta’etu isaaniif jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 11, 'Yeroo "Dachii keessatti badii hin raawwatinaa" isaaniin jedhame "nuti warra tolchu qofa" jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 12, 'Dhagayaa! Dhugumatti isaan isaanumatu warra badiiti. Garuu [haala gadhee isaanii kana] hin beekanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 13, 'Yeroo "akka namoonni amananitti amanaa" isaaniin jedhame "sila nuti akka warri gowwaan amananitti amannaa?" jedhu. Dhagayaa! dhugumatti isaan isaanumatu gowwoota Garuu isaan hin beekan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 14, 'Yeroo warra amanan qunnaman "nuti amanneerra" jedhuYeroo sheyxaanota (hoggantoota) isaanii waliin kophaa ba’an immoo " nuti isin waliin jirra; dhugumatti nuti isaanitti qishnuma (qoosaa) godhuuf [akkas goone]" jedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 15, 'Rabbiin [mindaa qishnaa isaaniitiif] isaanitti qishnaa godha; jallina isaanii keessatti isaan dhiisa odoo isaan dhama’anuu .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 16, 'Isaan warra jallina qajeelumaan bitataniidha. Daldalli isaaniis bu’aa dhabe. Isaanis warra qajeelan hin turre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 17, 'Fakkeenyi isaanii akka fakkii isa ibidda qabsiifatee, yeroma isheen waan naannoo isaa ibsitu Rabbiin ifaa isaanii adeemsisee dukkana keessatti haala hin argineen isaan dhiiseeti', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 18, '[Isaan] duudaa, arraba qabamaafi jaamaadha. Kanaafuu [gara karaa qajeelaa] hin deebi’anu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 19, 'Yookiin akka rooba cimaa samii irraa ta’ee kan isa keessa dukkanoonni, mandiisuufi hangaasuun jirtu, bakakkaa irraa quba gurra isaanii keessa kaa’atu, du''a sodaaf. Rabbiin kaafirootatti marsaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 20, 'Calanqichi ija isaanii butuutti dhiyaata. Dhawaata isaaniif ifuun isa keessa deemu, Yeroo isaan irratti dukkanaa’e immoo ni dhaabatu. Rabbiin odoo fedhee dhageettiifi agartuu isaanii ni deemsisa ture. Dhugumatti, Rabbiin waan hunda irratti danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 21, 'Isin Yaa namootaa! gooftaa keessan isa isiniifi warra isiniin duraa uume qofa gabbaraa! Akka Rabbiin sodaattaniif jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 22, '[Rabbiin] Isa dachii afata, samii immoo ijaarsa (gubbaa) isiniif taasisee, kan samii irraa bishaan buusee, ergasii isaan fuduraa irraa soorata isiniif baaseedha. Kanaafuu odoo [kan gabbaramuun malu Rabbiin qofa ta’uu] beektanuu Rabbiif shariikota hin godhinaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 23, 'Yoo waan Nuti gabricha keenya irratti buufne (Qur’aana) irraa mamii keessatti taatan, suuraa akka isaa [tokko] fidaatii ragoota (gargaartotaafi deeggartoota) keessan kan Rabbiin ala jiranis waamadhaa.yoo kan dhugaa dubbattan taatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 24, 'Yoo [amma] hin dalagin; fuuldurattis hin dalagdanu; kanaafuu ibidda qabsiisaan ishee namaafi dhagaa ta’e kan kaafirootaaf qopheeffamte sodaadhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 25, 'Isaan amananii, gaggaarii hojjatan, jannatoonni laggeen jala ishee yaatu isaaniif jira jechuun [isaan] gammachiisi. Dhawaatuma firii ishee irraa sooramaniin "kun soorata kana dura sooramneedha" jedhu. Wal fakkaataa ta''ee isaaniif kenname. Isaaniif ishee keessa haadholeen manaa qulqulleeffaman jiru. Isaan ishee keessatti hafoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 26, 'Dhugumatti Rabbiin bookees taatee waan ishee irra guddaa (yookiin xiqqaa) fakkeenya taasisuu hin saalfatu. Warri amanan akka inni dhugaa Gooftaa isaanii irraa ta’e ni beeku. Isaan kafaran immoo "Rabbiin fakkeenya kanatti maal fedhe?" jedhu. [Rabbiin] kanaan (namoota) baay’ee jallisee, (namoota) baay’ees qajeelcha. Finciltoota malees (kan biraa) ittiin hin jallisu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 27, '[Isaan] warra waadaa Rabbii erga kakuun jabeessanii booda diiganii, waan (firummaa) Rabbiin fufamuu isaatti ajaje muranii, dachii keessatti badii raawwataniidha. Warri sun hoonga’oon isaanuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 28, 'Sila akkamitti Rabbitti kafartan? ka isinii du’oo turtan isin jiraachisee, ergasii isin ajjeesee, ergasii isin jiraachisu. ergasii gara Isaatti kan deebifamtan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 29, 'Inni (Rabbiin) Isa waan dachii keessa jiru hunda isiniif uumee, ergasii gara samii ol ta’ee, samii torba isaan taasiseedha. Inni waan hunda akkaan beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 30, 'Yeroo Gooftaan kee malaa’ikootaan "dhugumatti, Ani (ilmaan namaa) dachii keessatti bakka bu’aa (khaliifaa) taasisuufan jira" jedhes [yaadadhu]. Isaanis ni jedhan: "Sila namoota ishee (dachii) keessatti badii dalagan, kan dhiiga (walii) dhangalaasan ishee keessatti taasiftaa?" odoo nuti galata keetiin si faarsinuufi si qulqulleessinuu". [Innis] ni jedhe: "Dhugumatti, Ani akkaan beekaa waan isin hin beekneti."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 31, 'Aadamiin maqoota hundaa isii isa barsiise. Ergasii malaa’ikoota irra isaan fideetiin "yoo kan dhugaa dubbattan taataniif maqoota wantoota kanneenii naaf odeessaa” jedhe', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 32, '[Malaa’ikoonnis] ni jedhan: "Ati qulqulloofte. Nu waan Ati nu barsiifte malee beekumsa hin qabnu; dhugumatti, Ati Simatu akkaan beekaa ogeessa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 33, '[Rabbiin] ni jedhe: "Yaa Aadam! maqoota isaanii isaanitti himi." Yeroma inni maqoota isaanii isaanitti himu [Rabbiin] ni jedhe: "Sila Ani akkaan beekaa wantoota fagoo kan samiifi dachiiti; ammas Ani akkaan beekaa waan isin ifa taasiftaniifi waan isin dhoksaa turtaniiti’ isiniin hin jennee?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 34, 'Yeroo Nuti malaa’ikootaan "Aadamiif sujuuda godhaa" jenne [yaadadhu]. Ibliis malee Isaan sujuuda godhan; [Inni] ni dide; ni boones, Kaafiroota irraa ta’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 35, 'Ni jennes: "Yaa Aadam! Atiifi haati manaa kee jannata keessa jiraadhaa. Ishee irraa bal''oo haala taateen iddoo feetanii nyaadhaa. Mukattii tanatti immoo hin dhiyaatinaa, Yoos miidhaa hojjattoota irraa taatu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 36, 'Shayxaannis ishee (jannata) irraa isaan mucucaachise. Waan isaan isa keessa turan irraas isaan baase. Nutis ni jenne: "gariin keessan gariif diina ta’aa gadi bu’aa. Isiniifis dachii keessa iddoo jireenyaatiifi waan itti fayyadamtan kan yeroo murtaa’eetu jira."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 37, 'Aadamis Gooftaa isaa irraa jechoota fudhatee, sana booda [Rabbiin] dhiifama isaaf godhe. Dhugumatti, Inni (Rabbiin) Isatu akkaan tawbaa qeebalaa, akkaan rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 38, 'Nuti ni jenne: "Hundi keessanuu ishee (jannata) irraa gadi bu’aa. Ergasii yoo Ana irraa qajeelfamni isiniif dhufe, namni qajeelfama kiyya hordofe, sodaan isaan irra hin jiru; isaan hin gaddanus."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 39, 'Warri kafaranii aayatoota keenya kijibsiisan, isaan sun warra ibiddaati, Isaan ishee keessatti hafoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 40, 'Yaa Ilmaan Israa’iil! qananii tiyya tan Ani ittiin isin qanansiise yaadadhaa. Waadaa kiyyas guutaa; Anis waadaa keessan nan guuta. Ana qofa sodaadhaa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 41, 'Waan Ani buuse kan mirkaneessaa waan isin bira jiruu (Tawraatiifi Injiil) ta’etti amanaa. Jalqaba warra isatti kafaruu hin ta’inaa. aayatoota kiyyaan maallaqa xiqqaa hin bitatinaa. Ana qofa sodaadhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 42, 'Dhugaa sobaan [walitti] hin makinaa; osoo beeytanuu haqa hin dhoksinaas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 43, 'Salaata seeraan salaataa; zakaas kennaa; warra rukuu’a godhan wajjinis rukuu’a godhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 44, 'Sila gaariitti nama ajajaa lubbuu keessan dagattanii! odoo kitaaba dubbiftanuu. hin xiinxaltanii!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 45, 'Obsaafi salaataan gargaarsa barbaadaa. Dhugumatti, isheen warra [Rabbiin] sodaatan irratti malee ulfaattuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 46, '[Isaan] warra Gooftaa isaanii qunnamuufi gara Isaatti deebi’uu mirkaneeffataniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 47, 'Yaa Ilmaan Israa’iil! qananii tiyya kan Ani isiniin qananiise yaadadhaa. ani aalama hunda irra isin caalchiseera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 48, 'Guyyaa lubbuun [takka] lubbuu (biraa) homaa hin fayyadne, kan jaarsummaan (araarsi) ishee irraa hin fudhatamneefi gumaanis ishee irraa hin fuudhamne, kan isaanis hin tumsamne san sodaadhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 49, 'Ammas yeroo Nuti ummata fir’awn jalaa nagaya isin baafne san (yaadadhaa). kan hamtuu adabbii isin dhandhamsiisaa turan, kan ilmaan dhiiraa keessan gorra’aniifi dubartoota keessan dhiisan.Sana keessa balaa guddaa Gooftaa keessan irraa ta’etu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 50, 'Yeroo bahra isiniif addaan baqaysine, ergasii nagaya isin baafnee, ummata fir’awnaa odoo isin argitanuu bishaaniin dhidhimsine sanis [yaadadhaa].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 51, 'Yeroo Muusaaf halkan afurtama beellamne [yaadadhaa]. Ergasii isin isa boodaa jibicha [gabbaramaa] taasifattanii warra of miidhe taatan .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 52, 'Ergasii sana booda dhiifama isiniif goone akka isin (Rabbi) galateeffataniif jecha .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 53, '|Yeroo Muusaaf kitaaba (Tawraatii)fi seera adda babaasaa dhugaafi kijibaa akka isin qajeeltaniif jecha kennines [yaadadhaa].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 54, 'Yeroo Muusaan ummata isaatiin jedhes [yaadadhaa] "yaa ummata kiyya! isin mirgoo [gabbaramaa] taasifachuun lubbuu keessan miitanii jirtan. Kanaaf gara [Rabbii] isin uumeetti deebi’aa, Lubbuu teessanis ajjeesaa, Sanatu Uumaa keessan biratti isiniif caala" (yaadadhaa). Ergasii [Rabbiin] dhiifama isinii godhe (tawbaa keessan qeebale) Dhugumatti, Inni akkaan tawbaa qeebalaa akkaan rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 55, 'Yeroo isin "yaa Muusaa! nuti hanga Rabbiin ifatti arginutti siif hin amannu" jettanii odoo isin argitanuu duuti isin qabattes [yaadadhaa].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 56, 'Ergasii du’a keessan booda isin kaafne akka isin (Rabbi) galateeffattaniif jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 57, 'Duumessa isin irratti gaaddiseessine. Manniifi (waan akka dayma adii) Salwiis (simbira xixiqqoo) isin irratti buufne, "Wantoota gaggaarii Nuti isiniif kennine irraa nyaadhaa" (isiniin jenne) Isaanis homaa nu hin miine; garuu lubbuulee isaanii kan miidhan turan', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 58, 'Yeroo Nuti "magaalattii tana seenaa; ishee irraas iddoo feetanii [nyaata] bal’aa nyaadhaa, Balbalichas sujuudaa seenaa"[Kadhaan keenyas badiin] nurraa harca''uudha" jedhaa, badii keessan isiniif araaramna, Warra toltuu hojjataniif [mindaa] dabaluuf jirra" jennes [yaadadhaa].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 59, 'Warri miidhaa hojjatan [jecha isaaniin jedhame] jecha isa isaaniin hin jedhaminitti jijjiiran. warra miidhaa hojjatan irratti azaaba samii irraa ta''e buufne, Waan isaan fincilaa turaniif jecha .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 60, 'Yeroo Muusaan ummata isaatiif dhugaatii (bishaan) barbaadee achumaan Nutis "ulee teetiin dhagicha dhayi" jenneen,[yaadadhaa] (innis nidhayee) achumaan burqituun kudha lama isarraa maddite, Namoonni hundi iddoo irraa dhugan beekanii jiru "hiree Rabbii irraa nyaadhaa, dhugaa; Dachii keessas badii hin babal’isinaa" [jenneen].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 61, 'Yeroo "Yaa Muusaa! nuti nyaata tokko irratti hin obsinuu, Gooftaa kee nuuf kadhu akka waan dachiin biqilchitu irraa, kudraa ishee irraa, dabaaqula ishee irraas, qamadii ishee irraas, misira ishee irraas, shunkurtii ishee irraas nuuf baasu " jettanis [yaadadhaa]. (Muusaanis) ni jedhe: "Sila isin isa gadi aanaa ta’etti isa caalaa ta’e jijjiirrattuu? Gara magaalaa gadi bu’aa; wanti gaafattan isiniif jira." Salphinaafi hiyyummaan isaan irratti haguugamtee, dallansuu Rabbi irraa ta’een deebi’an, Kun waan isaan aayatoota Rabbiitti kafaraa, nabiyyootas haqaan ala ajjeesaa turaniifi. Kun waan isaan fincilaa, daangaas dabraa turaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 62, 'Dhugumatti warri amanan, isaan yahuudoman, kiristaanonniifi saabi’oonni (isaan warra maleeykaa yookaa urjii gabbaru) [isaan irraa] namni Rabbiifi Guyyaa Aakhiraatti amanee toltuus hojjate, isaaniif mindaan Gooftaa isaanii biratti tahee jira. Sodaanis isaan irra hin jiru; Isaanis hin gaddanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 63, '[Yaa ilmaan Israa’iil!] Yeroo Nuti waadaa keessan qabanneefi [gaara] Xuuris isin gubbaatti ol kaafnee "waan Nuti isiniif kennine cimsaa qabadhaa, Akka Rabbiin sodaattaniif waan isa keessa jirus yaadadhaa’ isiniin jenne [yaadadhaa].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 64, 'Ergasii sana booda gara galtan, Odoo tolli Rabbiitiifi rahmanni Isaa isin irra jiraachuu baatee, silaa isin warra hoongaye irraa taatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 65, 'Dhugumatti isin warra isin irraa [dhimma] Sanbataa keessatti daangaa dabranii, "isin jaldeeyyii salphattoota ta’aa" isaaniin jenne beektanii jirtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 66, 'Kanaafuu Nuti ishee (adabbii sana) warra isaaniin duraatiifi isaaniin boodaatiif jiilchaa, warra Rabbiin sodaataniif immoo gorsa taasifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 67, 'Yeroo Muusaan ummata isaatiin "dhugumatti, Rabbiin sa’a qaluutti isin ajaja" jedhe [yaadadhaa], [Ummanni isaas] "sila ati qishnaa nu godhattaa?" jedhan, [Muusaanis] "ani warra wallaaloo [namatti qoosan]irraa ta’uu irraa Rabbittin maganfadha" jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 68, '[Ummanni isaas] "isheen maal akka taate ifa nuuf haa godhuu Gooftaa kee nuuf gaafadhu" jedhaniin, [Muusaanis] ni jedhe: "dhugumatti, Inni (Rabbiin) ‘isheen sa’a hin dulloomin, kan jabbiis hin ta’in giddu gala taate’ jedha, Waanuma ajajamtan dalagaa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 69, '[Ummanni isaas] "bifa ishee ifa nuuf haa godhuu Gooftaa kee nuuf gaafadhu" jedhan, [Muusaanis] "dhugumatti, Inni (Rabbiin) ‘isheen sa’a daalattii, bifti ishee akkaan daalattii daaw’attoota gammachiiftuudha'' jedha" jedheen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 70, '[Ummanni isaas] “ Gooftaa kee nuuf gaafadhu maalummaa ishee ifa nuuf haa godhuu Dhugumatti, sa’oonni nurratti wal fakkaataniiru; Nuti yoo Rabbiin fedhe qajeeluuf jirra" jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 71, '[Muusaanis] ni jedhe: "Inni (Rabbiin) ‘dhugumatti isheen sa’a dachii qotuufi oorruu (bishaan) obaasuu irratti hin leenjifamin, kan [hirdhuu qaamaa irraa] nagaa taateefi bifti makaan ishee keessa hin jirreedha’ jedha." [Ummanni isaas] "amma dhugaa fiddee jirta" jedhan.ishee nigorra''an Kan hojjachuuttis hin dhihaanne ta’anii turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 72, 'Yeroo lubbuu ajjeeftanii [waa’ee] ishee keessatti wal falmitan [yaadadhaa]. Rabbiin waan isin dhoksaa turtan ifa baasaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 73, '"Garii [qaama] isheetiin isa (reeffa isaa) dhawaa" jenne, akka kanatti Rabbiin du’aa jiraachisee mallattoolee Isaas isinitti agarsiisa Akka isin xiinxaltaniif jecha .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 74, 'Ergasii san booda onneewwan keessan ni gogde, Isheen [gogiinsa keessatti] akkuma dhagaati; yookiin goginaan ni caalti, Dhugumatti dhagoota irraa kan laggeen isarraa maddantu jiru, ishee (dhagoota) irraa kan dhodhooyee bishaan isa irraa ba’us ni jira, Ammas isaan irraa kan sodaa Rabbii irraa ka''ee gadi kufutu jira, Rabbiin waan isin dalagdan irraa dagataa miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 75, 'Sila! isiniif amanuu kajeeltuu? kan gareen isaan (Yahuudaa) irraa ta’e haasa’a Rabbii dhaga’anii eega hubatanii booda odoo beekanuu jijjiiran jiranuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 76, 'Yeroo warra amanan qunnaman "nuti amannee jirra" jedhan,Yeroo gariin isaanii garii waliin kophaa ba''an, "sila akka Rabbii keessan biratti ittiin isin falmanuuf waan Rabbiin isin beeksise isaanitti odeessituu! Sila hin xiinxaltanuu!" jedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 77, 'Sila isaan akka Rabbiin waan isaan dhoksaniifi waan isaan mul''isan beeku hin beekanuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 78, 'Isaan irraas wallaaltota hawwii sobaa malee kitaaba hin beeknetu jira. Isaan kan shakkan malee homaa miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 79, 'badiin mirkanaa''e! warra kitaaba harka isaaniitiin katabanii, ergasii isaan gatii xiqqaa bitachuuf jecha "kun Rabbiin biraa bu’e" jedhaniif. Waan harki isaanii barreessiteef jecha badiin isaaniif haa ta’u! Ammas waan isaan carraaqqataniif jecha badiin isaaniif haa ta’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 80, '"Ibiddi guyyaa lakkaa’amtuu malee nu hin tuuqxu" jedhan. jedhiin "Sila isin Rabbiin bira waadaa kaayattanii? [Yoo akkas ta’eef] Rabbiin waadaa isaa hin diigu; [miti] dhugaatti, waan hin beekne Rabbi irratti dubbattan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 81, '[Dubbiin akka isin jettan] miti! Namni hamtuu hojjatee hamtuun isaa isa marsite, isaan warra ibiddaati. Isaan ishee keessatti hafoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 82, 'Warri amananii, gaggaarii hojjatan isaan warra jannataati. isaan ishee keessatti hafanuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 83, 'Ammas yeroo Nuti Ilmaan Israa’iil waadaa qabanne [yaadadhaa] "Rabbiin malee [waan biraa] hin gabbarinaa; abbaafi haadhaaf tola oolaa, firootaafis, yatiimotaafis, hiyyeeyyiifis (tola oolaa). namootattis toltuu haasa’aa; salaatas gadi dhaabaa; zakaas kennaa" (jenneen). Ergasii garagaltan nama muraasa isin irraa ta’e malee, uf duuba deebi’oo taatanii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 84, 'Yeroo Nuti waadaa keessan qabanne [yaadadhaa]. "dhiigoowwan keessan wal hin dhangalaasinaa; lubbuulee teessan (namoota keessan) manneen keessan irraa hin baasinaa" (jechuun) , ergasii isin ni mirkaneessitan ragaa bahoo taatanii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 85, 'Ergasii isinuma kanneentu lubbuu keessan (walii) ajjeeftan. garee isin irraa ta’e manneen isaanii irraa baaftan; isaan irrattis badiifi diinummaan wal gargaartan. Yoo isaan booji’amtoota ta’anii isinitti dhufanii immoo isaan bilisoomsitan. inni dhoowwaadha isinirratti isaan baasuun. Sila garii kitaabaatti amantanii gariitti kafartuu? galanni nama isin irraa kana hojjatuu jireenya addunyaa keessatti salphina malee hin jiru. Guyyaa Qiyaamaa gara azaaba cimaa deebifamu. Rabbiin waan isin dalagdan irraa dagataa hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 86, 'Isaan warra jireenya addunyaa Aakhiraan bitataniidha. Kanaafuu azaabni isaan irraa hin salphifamu. Isaan hin gargaaramanus.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 87, 'Dhugumatti Nuti Muusaaf kitaaba kenniineerra, Isa boodas ergamtoota walitti aansuun hordofsiifnee jirra, Iisaa ilma Maryamiifis mallattoolee ifa ta’an kenninee jirra. "Ruuhul Qudsiin" (Jibriiliinis) isa jabeessinee jirra. Sila dhawaatyma ergamaan waan lubbuun teessan hin feeneen isinitti dhufuun boontani? garii kijibsiiftanii garii ajjeeftu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 88, '[Isaanis] "Onneewwan keenya cufamaadha" jedhan. dhugumatti sababa kufrii isaanii Rabbiin isaan abaare. xiqqoo amananu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 89, 'Yeroo kitaabni Rabbiin biraa ta’e kan waan isaanii wajjin jiru (Tawraatifi injiilin) dhugoomsu isaanitti dhufu, kan san dura akka warra kafaran irratti injifannoo argataniif [dhufaatii Nabi Muhammadiin SAW Rabbiin] kadhachaa turanii yeroo wanti isaan beekan isaanitti dhufu isatti kafaran. abaarsi Rabbii kaafiroota irra haa jiraatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 90, 'wanti isaan lubbuulee isaanii ittiin jijjiirratan waa fokkate, waan Rabbiin buusetti kafaruun, Rabbiin tola Isaa irraa gabroota Isaa gidduu nama fedhe irratti buusuu waanyuun (jibbuun) (kan kafaran), Kanaafuu dallansuu irratti dallansuudhaan deebi’an. Kaafirootaaf azaaba xiqqeessaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 91, 'Yeroo waan Rabbiin buusetti amanaa isaaniin jedhame "nuti waan nurratti buufametti amanna" jedhu. Waan isaan ala jiru itti kafaran, odoo inni dhugaa dhugoomsaa waan (kitaaba) isaaniin wajji jiruu ta’ee jiruu. (Yaa Muhammad! SAW) jedhiin: "Sila maaliif san dura nabiyyoota Rabbii ajjeeftu? yoo dhugaan mu’uminoota taatan"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 92, 'Dhugumatti Muusaanis ragaawwan ifa ta’aniin isinitti dhufee jira. Ergasii isin lubbuu keessan miidhoo taatanii isa booda (bakka inni hin jirretti) mirgoo [gabbaramaa] godhattan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 93, 'Yeroo Nuti waadaa keessan qabannee Gaara Xuurii isin gubbatti ol fuunee "Waan Nuti isiniif kennine ciminaan qabadhaa. [Jecha keenyas] dhagayaa" (jenne) [yaadadhaa]. Ni jedhan: "Dhageenyee dinne." Onneewwan isaanii keessa sababaa kufrii isaanitiin [jaalala] mirgoo [gabbaruu] obaafamanii jiru. jedhi "wanti iimaanni keessan itti isin ajaju waa fokkate" Yoo mu’uminoota taataniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 94, 'Jedhi: "Yoo manni Aakhiraa Rabbiin biratti isin qofaaf namoota biraatiin ala kophatti ta’e, mee du’a hawwaa yoo dhugaa kan dubbattan taataniif ."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 95, 'gonkumaa isa hin hawwanu waan harki isaanii dabarfatteef jecha, Rabbiin warra miidhaa dalaganu akkaan beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 96, 'Nama hunda irra jireenyaaf bololaa ta’uu isaanii argita. Mushrikoota irraallee [jireenyaaf bololu]. Tokkoon isaanii odoo waggaa kuma jiraachifamee jaalata jiraachifamuun isaa kan isa hin azaabarraa isa hinfageessine ta’ee jira, Rabbiin waan isaan dalagan akkaan argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 97, 'jedhi "Namni Jibriiliif diina ta’e, [dallansuu isaatiin haa du’u]”. inni (jibriil) fedha Rabbiitiin onnee kee irratti isa (Qur’aana) buuse. inni (qur''aanni) dhugoomsaa waan isa duraatiifi mu’uminootaaf qajeelchaafi gammachisaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 98, 'Namni Rabbiif, malaa’ikootaaf, ergamtootaaf, Jibriiliifi Miikaa’iiliif diina ta’e [kaafira]. Dhugumatti Rabbiin kaafirootaaf diina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 99, 'Nuti dhugumatti keeyyattoota ifa ta’an gara keetti buufnee jirra, Isaanitti kan kafaru finciltoota malee hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 100, 'Sila isaan dhawaata waadaa wahii seenaniin, gareen isaan irraa ta’e isa gataa (waadaa diigaa)? Dhugaatti irra hedduun isaanii hin amanan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 101, '| Yeroo ergamaan Rabbiin biraa dhugoomsaa waan isaan biraa ta’ee isaanitti dhufes, gareen warra kitaabni kennameef irraa ta’e akka waan hin beekiniitti kitaaba Rabbii dugda duuba isaaniitti of irraa darbu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 102, 'Waan shayxaanonni bara mootummaa Sulaymaan keessa qara’aa turan hordofan, Sulaymaan hin kafarre Garuu shayxaanonni nikafaran, sihrii nama barsiisan, waan malaa’ikoota lamaan Haaruutiifi Maaruut irratti Baabil keessatti buufames (nama barsiisan). Isaan (malaa’ikoonni) lamaan nama tokkos odoo "Nuti mokkoroof dhufnee hin kafarin" hin jedhin (sihrii) hin barsiisan. (Namoonnis malaa’ikoota) lamaan irraa waan ittiin dhirsaafi niitii addaan baasan baratu. Isaansun nama tokko hayyama Rabbiitin ala kan isasanin miidhan hin taane. Waan isaan miidhuu malee isaan hin fayyadne baratan. Dhugumatti, isaan (yahuudonni) akka warri isa (sihrii) bitate Aakhiratti qooda homaa hin qabaanne sirritti beekaniiru. wanti isaan lubbuulee isaanii itti gurguran waa fokkate! Odoo kan beekan ta’anii,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 103, 'Odoo isaan amananii Rabbiin sodaatanii, silaa mindaan isaan Rabbiin biraa argatan akkaan caalaa ture; odoo kan beekan ta’anii (silaa kan biraa hin filatanu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 104, 'Yaa warra amantan! (Ergamaa Rabbiitiin) "Raa’inaa" hin jedhinaatii "Unzurnaa" jedhaa; dhageeffadhaas. Kaafirootaaf azaaba laalessaa ta’etu jira', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 105, 'Abbootii kitaabaas ta’ee mushrikoota irraa warri kafaran Gooftaa keessan irraa toltuun isin irratti buufamuu hin jaalatanu. Rabbiin rahmata Isaatiin nama fedhe kophxeessa. Rabbiinis abbaa tola guddaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 106, 'Wanta keeyyata irraa jijjiirre yookiin si irraanfachiifne caaltuu ishee yookiin fakkaattuu ishee finna. Sila ati Rabbiin waa hunda irratti danda’aa ta’uu hin beektuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 107, 'Sila ati hinbeektuu Rabbiin mootummaan samiileefii dachii tan isaa tahuu? Isiniifis Rabbiin ala jaalalleefi gargaaraan hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 108, 'Dhugaatti isin ergamaa keessan gaafachuu feetu, akka muusaan kana dura gaafatame. Namni kufrii iimaanaan jijjiirrate, dhugumatti karaa sirrii irraa jallateera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 109, 'Hedduun warra kitaabaa irraa ta’an erga amantanii booda kaafiroota taatanii isin deebisuu (isin kafarsiisuu) jaalatu. waanyoo lubbuu isaanii irraa kan ka''e eega dhugaan ifa isaanii galee booda, dhiifama godhaa; irras dabraa Hanga Rabbiin ajaja Isaa fidutti, Dhugumatti, Rabbiin waan hunda irratti danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 110, 'Salaata gadi dhaabaa; zakaas kennaa,Toltuu irraa waan lubbuu keessaniif dabarfattan (kamillee) Rabbiin biratti isa argattu. Dhugumatti, Rabbiin waan isin hojjattan akkaan argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 111, '"Nama yahuudaa yookiin kiristaana ta’e malee jannata hin seenu” jedhan, Kun hawwii isaaniiti “Yoo kan dhugaa dubbattan taataniif ragaa keessan fidaa" jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 112, '(Dubbiin akka isin jettanii) miti; namni gaarii dalagaa fuula isaa Rabbiif kenne mindaan isaa Rabbii isaa bira isaaf jira; sodaan isaan irra hin jiru; isaan hin gaddanus.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 113, 'yahuudonni “kiristaanonni homaa irra (amantii sirrii ta’e hordofaa) hin jiranu” jedhu; Kiristaanonnis “yahuudonni homaa irra hin jiranu” jedhu,Oduma kitaaba qara’anuu, Akkuma san warri hin beekne fakkaataa jecha isaanii jedhan, Rabbiin Guyyaa Qiyaamaa waan isaan isa keessatti wal dhabaa turan irratti gidduu isaaniitti murteessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 114, 'Nama masjiidota Rabbii akka ihsee keessatti maqaan Rabbii hin faarfamne dhorgeefi onsuu isiitiif carraaqe caalaa namni miidhaa hojjate eenyu? Warri sun haala sodatoo tahaniin malee isii (masjiidota Rabbii) seenuun isaaniif hin ta’hu. Isaaniif addunyaa keessatti salphinatu jira. Ammas isaaniif Aakhiratti azaaba guddaa ta’etu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 115, 'Bahaafi Dhiitis kanuma Rabbiiti, Kanaafuu gara feetan yoo gara galtan Fuulli Rabbii achuma jira, Dhugumatti Rabbiin (rahmanni Isaa) bal’aadha; hunda beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 116, '"Raabbiin ilma godhate" jedhan, Inni (waan isaan jedhanirraa) ququllaa''e, Dhugaatti wanti samiileefi dachii keessa jiru (hundi) kan Isaati. Hunduu isaaf ajajamoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 117, '(Inni) argamsiisaa samiifi dachiiti, Yeroo dhimma wahii murteesses, wanti Inni isaan jedhu argamii qofa; yeroma san argama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 118, 'Warri (homaa) hin beekne: "maaliif Rabbiin nuun hin dubbanne yookiin maaliif mallattoon wahii nuuf hin dhufne? jedhu; akkasuma warri isaaniin duraa fakkaataa jecha isaanii jedhan, Onneen isaanii wal fakkaatte, Dhugumatti, Nuti namoota (amantii Rabbii) mirkaneeffataniif aayatoota (keenya) ifa taasifnee jirra', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 119, 'Nuti dhugaan gammachiisaafi akeekkachiisaa taasifnee si ergine. Ati warra ibiddaa irraa hin gaafatamtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 120, 'Yahuudotas ta’anii kiristaanonni hanga ati amantii isaanii hordoftutti sirraa hin jaalatanu, (Yaa Muhammad! SAW) "Dhugumatti qajeelfamni Rabbii isuma qofatu qajeelfama (sirriidha)" jedhi. Erga beekumsa irraa sitti dhufee yoo fedha lubbuu isaanii hordofte, Rabbi irraa jaalallees ta’ee tumsaan siif hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 121, 'Isaannan Nuti kitaaba isaaniif kennine qaraatii malu isa qara’u, Isaan isatti amanu, Namni isatti kafare isaan warra hoonga’oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 122, 'Yaa ilmaan Israa’iil! qananii tiyya tan Ani isin irratti tola oole san yaadadhaa; Ani Aalama irra isin caalchisuu kiyyaas [yaadadhaa].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 123, 'Guyyaa lubbuun tokko lubbuu biraa hin fayyanne sodaadhaa. kan gumaanis ishee irraa hin fuudhamne, kan araarri homaatuu ishee hin fayyannee, kan isaanis tumsa hin arganne .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 124, 'Yeroo Ibraahiimiin Gooftaan isaa jechootaan isa mokkoree (Ibraahiimis) isa guute [yaadadhaa], (Rabbiinis) " Ani ummataaf imaama (dursaan) si taasisa" jedhe, (Ibraahiim) ni jedhe:"Sanyii kiyya irraas (taasisi)." (Rabbiinis) ni jedhe: "Waadaan (nabiyyummaan) kiyya warra miidhaa hojjatan hin argatu"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 125, 'Yeroo Manicha (Ka’abaa) namootaaf iddoo deddeebiifi iddoo nagaa taasifnes [yaadadhaa], Maqaama Ibraahiim irraas iddoo salaataa taasifadhaa, (Nutis) Ibraahiimiifi Ismaa’iiliin mana Kiyya warra isa irra naanna’aniif, warra keessa taa’aniifi warra (isa keessatti) rukuu’aafi sujuuda godhaniif qulqulleessaa jechuun waadaa seensifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 126, 'Yeroo Ibraahiim jedhe "Gooftaa kiyya! Magaalaa kana (Makkaan) iddoo tasgabbii taasisi, Warra (jiraattota) isaas, namoota isaan irraa Rabbiifi guyyaa Aakhiraatti amaneef fuduraalee irraa soorata isaaniif kenni" jedhe [yaadadhaa], (Rabbiinis) "Nama kafares (niin nyaachisa); Ani xiqqoon isa qanansiisee ergasii gara azaaba ibiddaattin isa geessa, Iddoo deebii kan akkaan fokkateedha!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 127, 'Yeroo Ibraahiimiifi Ismaa’iil "Yaa Rabbi Ati dhagahaa beekaa dhaa! nurraa qeebali" jedhaa; bu’uura manaa (Ka’abaa) ol fuudhan (ummataaf himi).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 128, '"Gooftaa keenya! Nu lamaanuu siif ajajamoo nu taasisi; sanyii keenya irraas ummata Siif ajajamtoota (taasisi), Manaasika’ keenyas (sirnoota hajjiifi umraah) nutti agarsiisi, Tawbaa keenyas nurraa qeebali, Dhugumatti, Ati Situ akkaan tawbaa qeebalaa, akkaan rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 129, 'Gooftaa keenya! Ergamaa isaan irraa ta’e isaan keessatti ergi, kan keeyyattoota kee isaan irratti qara’u, kan kitaabaafi ogummaa isaan barsiisee isaanis qulqulleessu. Dhugumatti, Ati Situ akkaan injifataa, ogeessa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 130, 'Sila namni amantii Ibraahiim irraa gara galu eenyu? nama lubbuu isaa gowwoomse malee, dhugumatti addunyaa keessattis isa filannee jirra, inni Aakhiraa keessattis warra gaggaarii irraayyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 131, 'Yeroo Gooftaan isaa "(Rabbiin jala) butami" isaan jennaan, [Inni] "Gooftaa aalamaa jala butameera" jedhe [yaadadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 132, 'Ibraahiim ilmaan isaatiif ishee (Islaamummaa) dhaamee ture; Ya’aquubiis (sanuma dhaame); "Yaa ilmaan kiyya! Dhugumatti, Rabbiin amantii isiniif filee jiraa Muslimoota taatanii malee hin du’inaa" (jedhe).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 133, 'Sila yeroo Ya’aquubitti duuti dhufnaan ilmaan isaatiin "ana booda maal gabbartan?" jedhe isin bira jirtumoo? Isaanis ni jedhan: "Nuti Gooftaa kee, Gooftaa abboota kee Ibraahiim, Ismaa’iiliifi Isihaaq gabbaramaa tokkicha kan ta’e gabbarra, Nuti Isaaf ajajamtoota (Muslimoota)."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 134, 'Dhugumatti isheen sun ummata dabarte, Isheedhaaf mindaa waan oomishteetu jira; Isiniifis mindaa waan oomishtaniitu jira, Isinis waan isaan hojjataa turan irraa hin gaafatamtanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 135, '"Ni qajeeltuu Yahuudaa yookiin Kiristaanota ta’aa" jedhan, "Dhugaatti karaa Ibraahiim isa qajeelaa ta’e (hordofna); Inni mushrikoota irraa hin taane" jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 136, '(Mu’uminoonni) jedhaa: “Nuti Rabbitti amannee jirra; waan gara keenyatti buufamettis; waan gara Ibraahiim, Ismaa’iil, Isihaaq, Ya’aquubii fi Asbaaxitti buufametti (amannee jirra) Waan Muusaafi Iisaan kennamanittis, Waan nabiyyoonni Gooftaa isaanii irraa kennamanittis (amannee jirra), Isaan irraa gidduu nama tokkoos addaan hin baafnu, Nuti warra Isaaf butameedha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 137, 'Yoo fakkaataa waan isin itti amantaniititti amananiif dhugumatti qajeelaniiru,Yoo isa irraa gara galan immoo isaan faallessuu qofa keessa jiru, Rabbiinis isaan siif ga’a (sirraa dhorga), Inni akkaan dhagayaa, akkaan beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 138, 'Halluu Rabbii isa uumamaa (amantii Isaa) (qabadhaa), kan Rabbirra halleessuu tolchu eenyu? Nuti isaaf gabbaroodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 139, '(Yaa Muhammad) jedhi: waa’ee Rabbii keessatti nuun falmituu?“odoo Inni Gooftaa keenyaafi Gooftaa keessan ta’ee jiruu, nuufis dalagaan keenya, isiniifis dalagaan keessan tahee jira, Nuti (amantii) Isaaf qulqulleessoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 140, 'Sila Ibraahiim, Ismaa’iil, Isihaaq, Ya’aquubiifi Asbaax yahuudota yookiin kiristaanota turan jettuu? Sila isintu irra beekamoo Rabbi?” jedhiin. Sila nama ragaa Rabbirraa tahe kan isa bira jiru dhokse caalaa namni miidhaa hojjate eenyu? Rabbiinis waan isin dalagdan dagataa miti."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 141, 'Dhugumatti isheen sun ummata dabarte. Isheef waan oomishteetu jira; Isiniifis waan oomishtaniitu jira. Isinis waan isaan hojjataa turan irraa hin gaafatamtanu', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 142, 'Namoota irraa warri gowwaan "Sila qiblaa irratti tahan (Beytal-Maqdis) irraa maaltu isaan garagalche?" jedhu. "Bahaafi Dhihaas kanuma Rabbiiti. Inni nama fedhe gara karaa sirrii qajeelcha" jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 143, 'Akkasuma (akkuma isin qajeelchinetti)filatamtuu ummataa isin taasifne, namoota irratti ragaa akka taatanuufi ergamichis ragaa isin irratti ta’uuf jecha. Nuti qiblaa ati irra turtes nama ergamaa hordofuufi nama (amantii irraa) duubatti deebi’u eenyu akka ta’e beekuuf malee hin taasifne. Dhugumatti sun warra Rabbiin qajeelche irratti malee ulfaattuu turte. Rabbiin iimaana (salaata) keessan (kan gara Beytal-Maqdis gara galtanii sagadaa turtan) kan balleessu hin taane. Dhugumatti, Rabbiin namootaaf mararfataa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 144, 'Dhugumatti, gara samii deddeebi’uu fuula keetii arginee jirra. Gara qiblaa ati jaallattuu si deebisuuf jirra. (Ammuma) fuula kee gara Masjidal-Haraam (Ka’abaatti) gara galchi. Eessattillee yoo taatan fuula keessan gara isaa gara galchaa. Dhugumatti, warri kitaabni kennameef akka inni dhugaa Gooftaa isaanii irraa ta''e ni beeku. Rabbiinis waan isaan hojjatan irraa dagataa miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 145, '|Odoo warra kitaabni isaaniif kennametti mallattoo hundaan itti dhufteeyyuu qiblaa kee hin hordofan. Atis qiblaa isaanii kan hordoftu hin taane. Gariin isaaniis qiblaa garii isaanii kan hordofan hin taane. Dhugumatti, erga beekumsa irraa waa sitti dhufee booda odoo fedhiilee lubbuu isaanii hordoftee, ati yoos warra akkaan miidhaa hojjatanu irraa taata turte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 146, 'Warri Nuti kitaaba isaaniif kennine akkuma ilmaan ofii beekanitti isa (Ergamicha) beekan. Dhugumatti gareen isaan irraa ta’e odoo beekanuu dhugaa dhoksu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 147, 'Dhugaan Gooftaa kee irraayi, Kanaafuu warra shakkan irraa hin ta’in.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 148, 'Hawaasa hundaafuu kallattii isaan itti gara galantu jira, Toltuu irratti wal dorgomaa, Eessattillee yoo taatan Rabbiin (Guyyaa Qiyaamaa) hunda keessanuu ni fida. Dhugumatti, Rabbiin waan hunda irratti danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 149, 'Iddoma (imalaaf) baate kamirraayyuu fuula kee gara Masjidal Haraam gara galchi. Dhugumatti, inni dhugaa Gooftaa kee irraa ta’e, Rabbiin waan isin dalagdan dagataa hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 150, 'Iddoma (imalaaf) baate kamirraayyuu fuula kee gara Masjiidal Haraam gara galchi, Eessattillee yoo taatan fuulleen keessan gara isaa gara galchaa, akka namootaaf ragaan isin irratti hin jiraanneef,isaan irraa warra miidhaa hojjatan malee, isaan hin sodaatinaa Anuma qofa sodaadhaa. akka qananii kiyya isinirratti guutuuf, isin (gara haqaa) akka qajeeltaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 151, 'Akkuma ergamaa isin irraa ta’e, isin keessatti ergine, (inni sun) kan aayatoota keenya isin irratti qara’u, kan isin qulqulleessu, kan kitaabaafi hikmaa (hadiisa) isin barsiisuufi waan isin hin beeknes isin barsiisuun (isin qanansiifne).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 152, 'Na yaadadhaa, Anis isiniin yaadadhaa, Galata naaf galchaa, Natti hin kafarinaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 153, 'Yaa warra amantan! Obsaafi salaataan gargaarsa barbaadaa. Dhugumatti, Rabbiin warra obsan waliin jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 154, 'Nama karaa Rabbii keessatti ajjeefamuun du’aadha hin jedhinaa. Dhugumatti isaan jiratoodha, garuu isin hin beektanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 155, 'isin mokkorra wahii sodaafii beelarraa taheen, qabeenyaalee lubbuuleefii (oomisha) khuduraalerraa ir''isuunis (isin mokorra). obsitoota gammachiisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 156, 'Isaan warra yeroo balaan isaan tuqxe "Nuti kan Rabbiiti, nuti gara Isaatti deebi’oodha" jedhaniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 157, 'Isaan warra faaruufi tolli Gooftaa isaanii irraa ta’e isaan irratti taheedha. isaan sun isaanumatu qajeelfamoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 158, 'Dhugumatti, Safaafi Marwaan mallattoolee Rabbii (kan ibaadaan isaa itti hojjatamu) irraayyi. Namni Manichatti hajja’e yookiin umraa godhe isaan lamaan jidduu naanna’uun badiin isarra hin jiru. Namni fedhii isaatiin toltuu hojjates (ni mindeeffama), Rabbiin galateeffataa beekaadha', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 159, 'Dhugumatti, isaannan waan Nuti buufne -kan ragaawwan ifa ta’aniifi qajeelfama irraa ta’e erga kitaabicha (keenya) keessatti namootaaf addeessinee booda- dhoksan, warra san Rabbiin isaan abaara; warri abaarus isaan abaaru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 160, 'warra tawbatanii, hojii gaarii hojjatanii, (dhugaa dhoksan san) ifatti mul’isan malee. warra san tawbaa isaanii isaanirraan qeebala, Ani akkaan tawba-qeebalaa, akkaan rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 161, 'Dhugumatti, warri kafaranii kaafirtoota ta’anii du’an, sunniin abaarsi Rabbii, malaa’ikootaafi kan namoota hundaatuu isaan irratti jiraata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 162, 'Isii keessa yeroo hunda jiraatu, adabbiin isaan irraa hin salphifamu, Baallamnis isaaniif hin kennamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 163, 'Gabbaramaan keessan gabbaramaa tokkichaIsa, isa malee dhugaan gabbaramaan hin jiru. (Inni) akkaan mararfataa rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 164, 'Dhugumatti uumama samiileefi dachii, wal irraa bakka bu’uu halkaniifi guyyaa, doonii waan namoota fayyaduun galaana keessa yaatu, bishaan irraa waan Rabbiin samii irraa buusee isaan dachii erga isiin duutee booda jiraachiseefi lubbu-qabeeyyii hunda irraa isii keessa facaase, bubbisa qilleensaafi duumessa samiifi dachii giddutti (uumamootaaf) mijeeffamanii- keessatti ummata xiinxalaniif mallattooleetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 165, 'Namoota irraas nama Rabbiin ala gabbaramoota (biraa) kan akka Rabbiin jaallatanutti isaan jaallatan godhatantu jiru, Isaan amanan irra jajjaboo jaalalaan Rabbiif. Warri miidhaa hojjatanu yeroo adabbii argan akka humni hundi kan Rabbii ta’eefi Rabbiinis (abbaa) adabbii cimaa akka ta’e, odoo arguu kan danda’an ta’anii (silaa gabbaramaa biraa hin godhatanu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 166, 'Yeroo warri hordofaman warra hordofan irraa qulqullaayanii (isaan jallisuu waakkatan) fi (yeroo) azaaba argan, hariiroon isaanii hundi yeroo isaan jalaa citu (odoo beekanii gabbaramaa biraa hin godhatanu ture).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 167, 'Isaan hordofan ni jedhan: "odoo carraan (gara addunyaa) deebi’uu nuuf jiraatee, silaa akkuma isaan nurraa qulqullaayan nutis isaan irraa qulqulloofna turre." Akka kanatti Rabbiin hojiiwwan isaanii gaabbii (sheenaa) isaan irratti godhee isaanitti mul’isa, Isaan ibidda irraa bahoo miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 168, 'isinYaa namootaa! Waan dachii keessa jiru irraa halaala gaarii ta’e nyaadhaa,Tarkaanfiilee sheyxaanaa hin hordofinaa, Dhugumatti, inni isiniif diina ifa bahaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 169, 'kan inni itti isin ajaju hamtuu, waan fokkataafi Rabbi irratti waan hin beekne dubbachuu qofaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 170, 'Yeroo "waan Rabbiin buuse hordofaa" isaanin jedhame "Lakki nuti waan abbootii keenya irratti garre hordofna" jedhu, Sila odoo abbootiin isaanii kan homaa hin beekneefi karaa qajeelaa irra hin jirre ta’anilleemoo (numa hordofanii)?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 171, 'Fakkeenyi warra kafaranii (nama gara haqaatti isaan yaamuu) akka fakkeenya isa waan waamichaafi lallaba malee hin dhageenyetti (beyladatti) iyyuuti, (Isaan) duudaa, arraba qabamaafi jaamaadha; isaan hin xiinxalanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 172, 'Yaa warra amantan! Gaggaarii waan nuti isiniif kenninee irraa nyaadhaa, Rabbiif galata galchaa yoo kan Isa (qofa) gabbartan taatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 173, 'Kan Inni isin irratti dhorgamaa taasise baktii, dhiiga, foon booyyeetiifi waan (maqaan) Rabbiin malee (yeroo gorra''amu) isa irratti ol fuudhame qofa. Namni (nyaachutti) rakkifame shiftaafii daangaa dabraa tahuun maleetti badiin isarra hin jiru. Dhugumatti Rabbiin akkaan mararfataa rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 174, 'Dhugumatti, isaan kitaaba irraa waan Rabbiin buuse dhoksanii gatii xiqqaa isaan bitatan, isaan sun garaa isaanii keessatti ibidda malee hin nyaatanu, Rabbiin Guyyaa Qiyaamaa isaan hin dubbisu, isaan hin qulqulleessus, isaaniifis azaaba laalessaa ta’etu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 175, 'Isaan warra qajeelumaan jal’ina, araaramaan immoo azaaba bitataniidha, Sila maaltu ibidda irratti akkaan isaan obsisiise!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 176, '(Adabbiin) Sun sababa Rabbiin kitaaba dhugaan buusee (isaan itti kafaraniifi), warri kitaaba keessatti wal dhaban wal diddaa (haqarraa) fagoo keessatti ta’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 177, 'Dalagaan gaariin fuulleen keessan gara bahaafi dhihaa naannessuu miti; haa ta’u malee dalagaan gaariin nama Rabbitti amane, Guyyaa Aakhiraatti, malaa’ikootatti, kitaabattiifi nabiyyootatti (amanee), kan qabeenya kenne odoo jaallatuu firaaf, yatiimaaf, hiyyeeyyiif, kara deemaaf, kadhattootaafi gabra bilisoomsuuf (kennee), kan salaatas gadi dhaabe, zakaa kenne, warra yeroo waadaa seenan waadaa isaanii guutaniidha. warra rakkina, dhukkuba keessatti, yeroo lolanis obsaniidha. Isaan warra dhugaa qabatani, Isaan warra Rabbiin sodaataniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 178, 'Yaa warra amantan! Ajjeefamaa keessatti "qisaasni" (lubbuu lubbuun kafaluun)(seerri adabbii wal qixxeessuu) isin irratti barreeffameera. Bilisni bilisaan, gabrichi gabrichaan, dubartiin dubartiidhaan (ajjefamu). Namni (dhiiga) obboleessa isaa irraa wanti tokko isaaf dhiifame, toltuun hordofuufi (kaffaltiin gumaa dhiigaas) haala gaariin isaan (abbaa gumaatiin) gayuutu irra jira. Kun laaffisuufi rahmata Gooftaa keessan irraa ta’eedha. Namni sana booda daangaa dabre, isaaf azaab laalessaa ta’etu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 179, '"Qisaasa" keessa jiraachuutu (lubbuu du’a irraa baraaruutu) isiniif jira Yaa warra sammuu qabdan! Akka isin (ajjeechaa irraa) eeggattaniif (kana goone) .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 180, 'Yeroo duuti tokkoon keessanitti dhufe, yoo kan qabeenya (of duubatti) dhiise ta’e: abbaa haadhaafi firootaaf haala gaariin dhaamuun isin irratti murteeffameera, haqa warra Rabbi sodaatanirratti taateedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 181, 'Namni erga isa (dhaamsa) dhagayee booda isa jijjiire, badiin isaa warra isa jijjiiran irratti ta’a. Dhugumatti, Rabbiin dhagayaa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 182, 'Namni isa dhaamu san irraa jal’ina yookiin badii sodaatee gidduu isaanii araarse, badiin isa irra hin jiru. Dhugumatti, Rabbiin akkaan araaramaa rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 183, 'Yaa warra amantan! Soomni akkuma warra isin duraa irratti barreefametti (dirqama ta’etti) isin irrattis barreeffameeraو Akka isin Rabbiin sodaattaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 184, 'Guyyoota lakkaawamtuu (soomaa) Isin irraa namni dhukkubsataa yookiin karaa deemsarratti ta’e, guyyaa biraa irraa lakkaawwachuutu (isa irra jira) Warra isa (Soomuu) (osoo itti ulfaatuu uf dirqan) danda’an irratti kaffaltii (yoo soomana dhiisan) (fidyaa) hiyyeessa nyaachisuutu jira. Namni fedha isaatiin toltuu dabalatee hojjate, sun isaaf caalaadha. soomuutu isiniif caala Yoo kan beektan taataniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 185, '(yeroon akkasoomtan dirqama taasifame) Jiia Ramadaanaa isa Qur’aanni -namootaaf qajeelfamaafi ragaa ifa bahaa qajeelfamichaafi addaan baasaa (haqaafi kijibaa) irraa ta’e- keessa buufameedha. Namni isin irraa ji’a kana dhaqqabe isa haa soomu. Namni dhukkubsataa yookiin karaa deemsarratti ta’e, guyyaa biraa irraa lakkaawwachuutu (isa irra jira). Rabbiin isiniif laaffisuu fedha, isin irratti jabeessuu hin fedhu. Akka lakkoofsa (guyyaa isin irratti barreeffamee) guuttaniifi, waan isin qajeelcheef irratti akka Rabbiin guddiftaniif, akkasumas akka (Rabbiin) galateeffattaniif jecha (kana goone).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 186, 'Yeroo gabroonni kiyya Ana irraa si gaafatan “dhugumatti, Ani isaanitti dhihoodha” (jedhiin). Kadhaa kadhataatiif yeroo inni na kadhate nan owwaadha. naaf haa owwaatanu, nattis haa amananu, Akka qajeelaniif jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 187, 'Halkan soomaa gara dubartoota (niitiwwan) keessanii dhaquun (qunnamtii saalaa gochuun) isiniif hayyamameera. Isaan isiniif uffata; isiniis isaaniif uffata. Rabbiin akka isin lubbuu keessan ganaa turtan beekee tawbaa keessan isin irraa qeebalee, dhiifamas isiniif godhe. Amma isaan waliin qunnamtii saalaa godhaa; (ilmaan irraa) waan Rabbiin isiniif katabe barbaaddadhaa. Hanga barraaqa irraa jibriin adiin (bariisaa) jibrii gurraacha (dukkana halkanii) irraa adda bahutti nyaadhaa dhugaa, Ergasii hanga halkaniitti sooma guutaa. Odoo masjiidoota keessa i’itikaafa taa’aa jirtanuu isaan waliin qunnamtii saalaa hin raawwatinaa. Sun daangaawwan Rabbiitii isheetti hin dhihaatinaa.akka kanatti Rabbiin keeyyattoota Isaa namootaaf ibsa Akka isaan Isa sodaataniif jecha .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 188, 'Qabeenyaalee keessan gidduu keessanitti sobaan hin nyaatinaa.abbootii seeraatiifis malaan-maltummaan hin dhihaatinaa, Qabeenya namootaa irraa garii isaa odoo beektan cubbuun nyaachuuf jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 189, '(Yaa Muhammad!) Waa’ee baatii reefuu baatu irraa si gaafatu“Isheen namootaaf kan yeroo ibsituufi hajji (beeksiftuu) dha” jedhi. Dalagaan gaariin manneen boroo isaaniitiin seenuu keessanii miti, Garuu dalagaan gaariin (iimaana) nama Rabbiin sodaatuuti, Manneen balbaloowwauma isheetiin seenaa, akka milkooftaniif jecha Rabbiinis sodaadhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 190, 'Karaa Rabbii keessattis warra isiniin lolaniin lolaa, Daangaa hin dabrinaa, Rabbiin warra daangaa dabran hin jaalatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 191, 'Warra isiniin lolan) bakkuma isaan argitanitti isaan ajjeesaa, Iddoo isaan isin baasan irraas isaan baasaa, mokkoraat (Shirkiitu) ajjeechaa caalaa hamaadha, Masjidal-Haraam biratti,isin isaan hin waraaninaa, hanga isaan isa keessatti isin waraananitti, Yoo isaan isin waraanan, isinis isaan ajjeesaa, galanni kaafirootaa akkuma kana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 192, 'Yoo isaan dhoowwaman (waraana dhaabanii amantii seenan) Rabbiin akkaan mararfataa rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 193, 'Hanga jequmsi hin argamnettifii amantiin Rabbiif qofa ta’utti isaaniin lolaa, Yoo isaan dhoowwaman, warra miidhaa hojjatu irratti malee diinomuun hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 194, 'Baatiin kabajamaan baatuma sana keessa (galata galfama); kabajaan gamaa gamanaayi (yoo isaan baaticha san kabajan isiniis kabajju), Nama isin irratti daangaa dabre isinis fakkaatuma waan inni isin irratti daangaa dabreetiin isa irratti daangaa dabraa, Rabbiin sodaadhaa, beekaa Rabbiin warra Isa sodaatuu wajjiin ta’haadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 195, 'Karaa Rabbii keessattis kennadhaa, Harka keessaniin gara badiittis of hin darbinaa, Toltuu hojjadhaa; Dhugumatti, Rabbiin warra toltuu hojjatan ni jaalata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 196, 'Hajjiifi umraa Rabbiif jecha guutaa. Yoo dhorgamtan, horii wareegaa (hadyii) irraa kan isiniif laafe (qalaa), Hanga hadyiin iddoo (qalma) isaa ga’utti mataa keessan hin haaddatinaa, Namni isin irraa dhukkubsataa tahe yookiin mataa isaa irra rakkoon jiraate, (yoo mataa isaa haaddate) soomuun yookiin sadaqachuun yookiin qaluun ''fidyaa'' haa baasu. Yeroo nagaa taatan, namni umraadhaan hanga hajjiitti qanani''e hadyii irraa waan isaaf laafetu irra jira, Namni hin argatin, guyyaa sadi hajjii keessatti, (guyyaa) torba immoo yeroo deebitan (soomuu qabdu). Sun (guyyaa) kudhan guutuudha. (Hadyiin yookiin soomuun) sun nama maatiin isaa masjiidal-Haraam bira (jiraataa Makkaa) hin ta’iniif, Rabbiin sodaadhaa, beekaa Rabbiin kan adabbiin isaa cimaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 197, 'Hajjiin ji’oota beekamoodha. Namni isaan keessa hajjii ofitti murteesse (ihraama godhate), hajjii keessatti qunnamtii saalaa gochuu, finciluufi falmii gaggeessuu hin qabu,Toltuu irraa waan isin hojjattan Rabbiin ni beeka, Galaa guduunfadhaa; dhugumatti caalaan galaa sodaa Rabbiiti, Yaa warra qalbii qabdan Anuma sodaadhaa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 198, '(Yeroo hajjii keessa) tola Rabbii keessanii irraa yoo barbaaddattan badiin isin irra hin jiru, Yeroo Arafaa irraa dachaatan Mash’aral Haraam biratti Rabbiin faarsaa, Akkuma Inni isin qajeelchetti isa zakkaraa; sanaan dura warra jallatoorraa turtan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 199, '(Yaa Qurayshotaa!) ergasii bakka namoonni yaa''aniin yaa''aa, Rabbiin araarama kadhaa, Dhugumatti Rabbiin mararfataa rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 200, 'Yeroo hojii hajjii raawwattan, akkuma abbootii keessan faarsitanitti yookiin faaruu sana caalu Rabbiin zakkaraa, Namoota irraa kan “yaa Rabbii keenya addunyaa irratti (gaarii) nuuf kenni” jedhutu jira. Akhiratti qoonni wahiitu isaaf hintaane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 201, 'Isaan irraas nama "Gooftaa keenya! Duuniyaatti toltuu, Aakhirattis toltuu nuuf kenni, adabbii ibiddaa irraa nu baraari" jedhantu jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 202, 'Warra san isaaniif waan hojjatan irraa qoodatu jira, Rabbiin saffisaa qormaataati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 203, 'Guyyoota lakkaa’amtuu keessatti Rabbiin faarsaa. Namni guyyaa lama keessatti ariifate badiin isarra hin jiru, Namni booda aanes badiin isa irra hin jiru (Kun) nama (Rabbiin) sodaateefi. Rabbiin sodaadhaa beekaa isin gama isaatti oofamtanii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 204, 'Namoota irraa nijira kan jechi isaa addunyaa irratti si dinqisiisu. waan qalbii isaa keessa jiru irratti Rabbiin ragaa godhata, inni falmiidhaan jabaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 205, 'Yeroo gara gale
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 206, 'Yeroo "Rabbiin sodaadhu" isaan jedhame of tuulummaan badiitti isa kakaasa. Ga’aan Isaa jahannami, Afanni (jahannam ta’uun) waa fokkate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 207, 'Nama irraa kan jaalala Rabbii barbaachaaf lubbuu ofii gurgurutu jira. Rabbiin gabrootaaf akkaan mararfataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 208, 'Isin yaa warra amantan! Islaamummaa keessa guutuu guutuutti seenaa; tarkaanfilee shayxaanaa hin hordofinaa. Dhugumatti, inni (shayxaanni) isiniif diina ifa bahaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 209, 'Erga ragaawwan ifa ta’an isiniif dhufanii booda (daandii Islaamaa irraa) yoo mucucaattan, Rabbiin injifataa, ogeessaa beekaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 210, 'Sila Rabbiifi malaa’ikoonni, gaaddisa duumessa irraa ta’e keessaan isaanitti dhufuu malee waan biraa eeganii? 
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 211, 'Ilmaan israaiil gaafadhu Mallattoolee ifa ta’an meeqaatama akka isaaniif kennine. Namni erga isatti dhuftee booda ni’imaa Rabbii jijjiire (adaba cimaatu isa mudata). Dhugumatti Rabbiin irra cimaa adabaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 212, 'Isaan kafaraniif jireenyi addunyaa miidhagfameera; warra amananitti ni qoosu. Warri Rabbiin sodaatan immoo Guyyaa Qiyaamaa isaanii ol ta’u. Rabbiin nama fedheef (tola Isaa irraa) lakkoofsa malee hiree kenna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 213, 'Ilmi namaa tuuta takka (amantii tokkicha irra) turan; ergasii Rabbiin nabiyyoota gammachiiftotaafi akeekkachiiftota taasisee erge. Isaan waliin kitaaba dhugaan buuse. akka inni waan isaan isa keessatti wal dhaban gidduu namootaatti murteessuuf. Warra inni kennameef qofatu erga ragaawwan ifa ta’an isaaniif dhufanii booda wal jibbaa gidduu isaanii jiru irraa kan ka’e wal dhabe. Rabbiin fedha Isaatiin warra amanan gara dhugaa waan isaan irratti wal dhabanii qajeelche. Rabbiin nama fedhe gara karaa sirraawaa qajeelcha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 214, 'Sila odoo (mokkoroon) fakkaataa warra isin dura dabranii isinitti hin dhufin jannata seenuu yaadduu? Rakkinniifi dhukkubni hamtuun isaan tuqxee, hanga ergamaaniifi warri isa waliin amanan "sila tumsi Rabbii yoom (dhufa)?" jedhan tokkotti shororkeeffaman. Dhagayaa! Dhugumatti, tumsi Rabbii dhihoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 215, '(Yaa Muhammad!) maal akka sadaqatan si gaafatu jedhi 
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 216, 'Lolli isinirratti dirqama godhame Odoma inni isin biratti jibbamaa ta’uu. Odoo inni isiniif gaarii ta''uu waan tokko jibbuun keessan mirkanaa’e. Odoo inni isiniif hamtuu ta’uu waan tokko jaalachuun keessanis mirkanaa’e. Rabbumatu beeka; isin hin beektanu', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 217, 'Ji’oota kabajamoo keessa loluu irraa si gaafatu. Jedhi: "Isa keessa loluun (yakka) guddaadha. Karaa Rabbii irraa (namoota) deebisuun, Isatti kafaruun, (namoota) Masjidal Haraam (irraa dhorguun) jiraattota isaa achi irraa baasuutu Rabbiin biratti irra guddaadha. Mokkoraatu (Shirkiitu) ajjeechaa irra (badiin isaa) guddaadha. Yoo danda’an hanga diinii keessan irraa isin deebisanitti isiniin loluu irraa hin deeman. Namni isin irraa diinii isaa irraa garagalee kaafira ta’ee du’e, warri sun addunyaafi Aakhiraattis dalagaaleen isaanii baddee jirti. Ammas warri sun warra ibiddaati; isaan achi keessatti hafoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 218, 'Dhugumatti, warri amananiifi warri godaananii, karaa Rabbii keessatti qabsaa’an, isaan sun rahmata Rabbii ni kajeelu. Rabbiinis araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 219, 'Dhugaatii macheessaniifi qumaara irraa si gaafatu. Jedhi: "Dilii guddaafi faayidaawwantu namootaaf isaan keessa jira. Diliin isaan lamaanii faayidaa isaan lamaanii irra guddaadha." Ammas maal akka arjoomanu si gaafatu “Isa dhimma keessan irraa hafe” jedhiin. Akka xiinxaltaniif jecha Rabbiin akka kanatti keeyyattoota isaa isiniif ibsa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 220, 'Duuniyaafi Aakhiraa keessatti (haa xiinxaltaniifi). Waa’ee yatiimotaa irraas si gaafatu“Isaaniif tolchuutu caalaadha” jedhi. Yoo isaanitti makamtanis isaan obboleeyyan keessani. Rabbiinis nama balleessu isa tolchu irraa adda baasee beeka. Rabbiin odoo fedhee, isin rakkisuu danda’a. Dhugumatti, Rabbiin akkaan injifataa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 221, 'dubartoota mushrikaa hin fuudhinaa hanga isaan amananitti. Odoma isheen isin dinqisiifteeyyuu gabrittii mu’umintittiitu mushriktittirra caalti. dhiira mushrikootaatti hin heerumsiisinaa hanga amananitti. Odoma (inni) isin dinqisiiseeyyuu gabricha mu’uminaatu mushrika irra caala. Warri sun gara ibiddaatti waamu; Rabbiin immoo heyyama isaatiin gara jannataafi araaramaatti waama. Haa gorfamaniif jecha aayatoota isaa namootaaf ibsa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 222, 'Dhiiga laguu (haydii) irraas si gaafatu jedhi Inni (iddoon isaa) xuriidha; kanaafuu yeroo dhiiga xurii keessa dubartoota irraa fagaadhaa. Hanga isaan qulqullaa’anittis isaanitti hin dhihaatinaa. Yeroo isaan qulqulleeffatan, bakka Rabbiin isin ajajeeniin isaan bira dhaqaa. Dhugumatti Rabbiin warra gara Isaa tawbataniifi qulqulleeffatan ni jaalata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 223, 'Niitiiwwan keessan isiniif oyruudha. Oyruu keessan akkaataa feetaniin itti dhaqaa. Lubbuu keessaniif gaarii dabarfadhaa. Rabbiin sodaadhaa; Isa qunnamuu keessanis beekaa. Mu’uminoota gammachiisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 224, 'Rabbiin kakachuu keessan sababa hingodhatinaa Akka toltuu hin hojjanne, Rabbiin hin sodaanneefi gidduu namootaatti araara hin buufne Rabbiin dhagayaa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 225, 'Rabbiin dogoggoraaf isin hinqabu kakuu keessan keessatti.Garuu waan onneenneewan keessan hojjataniif isin qaba. Rabbiin araaramaa, obsaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 226, 'Warra jaartiiwwan isaanii irraa kakataniif ji’oota afur eeguutu isaan irra jira. Yoo irraa deebi’an dhugumatti Rabbiin akkaan araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 227, 'Yoo hiikkaa irratti muratan, dhugumatti Rabbiin dhagayaa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 228, 'Dubartoonni hiikaman xurii laguu sadi ofii isaaniitiif eeguu qabuYoo Rabbiifi Guyyaa Aakhiraatti kan amanan ta’an waan Rabbiin gadaamessa isaanii keessatti uume dhoksuun isaaniif halaala miti. (Yeroo) san keessatti yoo tolchuu fedhan isaan deebifachutti dhirsota isaaniittu irra haqa qaba. Isaaniifis (mirga) fakkaataa akka (dirqama) isaan irra jiruutu haala gaariin isaaniif jira. Dhiironni isaan irra sadarkaa qabu. Rabbiin hunda injifataa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 229, 'Hiikkaan (eega isaatii deebifatamu) yeroo lama. Sana booda haala gaariin qabachuu yookiin bifa tolaan gadi lakkisuudha. Isin (dhiironni) waan isaaniif kennitan (mahrii) irraa isaan lamaanuu daangawwan Rabbii sirreessuu dhabuu yoo sodaatan malee homaa fudhachuun isiniif hin hayyamamu. Yoo isaan lamaan daangawwan Rabbii hin sirreessanu jechuu sodaattan, waan isheen ittiin of baafte fudhachuu keessatti isaan lamaan irra badiin hin jiru. Kun daangawwan Rabbiitii isaan hin dabrinaa; namni daangaawwan Rabbii dabre, isaan sun isaanumatu miidhaa hojjatoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 230, 'Yoo (hiikkaa sadaffaa) ishee hiike, sana booda hanga dhirsa biraatti heerumtutti isaaf hin heyyamamtu. Yoo inni (dhirsi boodaa) ishee hiike, daangawwan Rabbii eeguu isaanii beeknaan isaan lamaan yoo walitti deebi’an badiin isaan irra hin jiru. 
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 231, 'Yeroo dubartoota hiiktanii beellama isaanii gayan. bifa gaariin isaan qabadhaa yookiin bifa gaariin isaan gaggeessaa. Rakkisuudhaan akka daangaa isaanitti dabartaniif isaan hin qabatinaaNamni sana hojjate, dhugumatti lubbuu ofii miidheeraKeeyyattoota Rabbiis qishinaa hin taasifatinaaNi’imaa Rabbii kan isin irra jirtuufi kitaaba (Qur’aana)fi hikmaa (Sunnaa) irraas waan Inni isin irratti buuse kan ittiin isin gorsu yaadadhaaRabbiin sodaadhaasAkka Rabbiin waan hunda beekaa ta’es beekaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 232, 'Yeroo dubartoota hiiktanii beellama isaanii gayan,dhirsoota isaanii heerumuu irraa isaan hin dhorginaa yoo jidduu isaaniitti karaa gaariin walii galan, Sana isin irraa nama Rabbiifi Guyyaa Aakhiraatti amanutu ittiin gorfama. Sun isiniif irra gaariifi irra qulqulluudha. Rabbitu beekaa; isin hin beektanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 233, 'haadholiin ilmaan isaanii waggaa lama guutuu hoosisu,Nama hoosisaa guutuu fedheef.nama ilmi isaaf dhalate (abbaa) Soorataafi uffata isaanii (haadholeef) haala gaariin (kennuun) isarra jira. Lubbuun kamiiyyuu dandeettii isheetii ol hin dirqisiifamtu. Haati sababaa ilma isheetiin hin rakkifamtu; namni ilmi isaaf dhalates (abbaanis) sababaa ilma isaatiin (hin rakkifamu). Nama (abbaa) dhaalu irras fakkaataa sanaatu jira. Yoo isaan lamaan fedha isaaniitiifi wal mariin guusisuu fedhan, badiin isaan irra hin jiru. Yoo ilmaan keessaniif (hoosiftuu gootanii) hoosisiisuu feetan,badiin isin irra hin jiru yoo waan kennitan akkaataa gaariin kennitan, Rabbiin sodaadhaa, Rabbiin waan isin dalagdan argaa ta’uu beekaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 234, 'Isin irraas isaannan du’anii niitiiwwan (uf duubatti) dhiisan, isaan (niitiiwwan tun) ji’oota afuriifi guyyaa kudhan kophaa isaanii turuu qabu. Yeroo beellama isaanii gayan, waan isaan karaa gaariin lubbuulee isaanii keessatti hojjatan keessa badiin isin irra hin jiru. Rabbiin waan isin hojjattan keessa beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 235, 'badiin isinirratti hintaane waan riqoon dubbattan irratti dubartoota (iddaa du''a jaarsaa keessa jiran) qaadhimachuu keessatti, yookiin (waan) onneewwan keessan keessatti dhoksitan keessatti. Akka isin isaan dubbatuuf jirtan Rabbiin beekeera. Garuu iccitiidhaan waadaa isaaniif hin seeninaa yoo jecha beekamaa jettan malee. nikaah hidhuu hin murteessinaa Hanga beellamni yeroo isaa ga’utti. Rabbiin waan lubbuulee keessan keessa jiru beekaa ta''uu beekaa; Isa sodaadhaa. Rabbiin araaramaa, obsaadhaa beekaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 236, 'Badiin isin irra hin jiru yoo Dubartoota odoo isaan hin tuqin yookiin mahrii isaanii isaaniif hin murteessin hiiktan, kennaa itti fayyadaman isaaniif kennaa. Qabaatarratti akkaatuma dandeettii isaatiin, Hiyyeessarrattis akkaatuma dandeettii isaatiin bifa gaariin kennaa (isaan itti fayyadamanu kennuu qaba). Kuni warra toltuu hojjatan irratti dirqama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 237, 'Odoo mahrii isaaniif murteessitanii jirtanuu isaan tuquun dura yoo isaan hiiktan, walakkaa waan murteessitaniitu (isheef jira), garuu yoo isaan (duubartoonni) dhiisan yookiin inni hidhaan nikaa harka isaa jiru (dhirsi) dhiise (walakkaan dirqamaa miti). Isin dhiisuutu sodaa (Rabbiitti) irra dhiyoodha. Tola giddu keessanii hin irraanfatinaa; Rabbiin waan isin hojjattan argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 238, 'Salaatowwan irratti,tikfadhaa keessattuu salaatattii giddu galeessaa irratti. Haala Rabbiif ajajamoo taataniin dhaabbadhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 239, 'Yoo (diina) sodaattan, miilaan deemaa yookiin yaabbatoo ta''aa (sagadaa). Yeroo tagabbooytan, Rabbiin yaadadhaa akkuma waan (san dura) isin beekoo hintahin isin barsiisetti .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 240, 'Isin irraa isaannan du’anii, niitiiwwan (of duubatti) dhiisan, niitiiwwan isaaniitiif haadhaamanii. (qabeenya dhiisanii du’an irraa) waan odoo mana isaanii irraa hin baafamne hanga waggaa tokkoo isaan itti fayyadaman. Yoo isaan (niitiiwwan fedha isaanitiin) bahan,badiin isin irra hin jiru, waan beekamaa irraa isaan lubbuu isaanii keessatti hojjataniif. Rabbiinis injifataa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 241, 'Dubartoonni hiikaman haala beekamaan qananiifamuu qaban. (Kun) warra Rabbiin sodaatan irratti haqa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 242, 'Akkanatti Rabbiin keeyyattoota Isaa isiniif addeessa Akka isin xiinxaltaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 243, 'Sila warra manneen isaanii irraa du’a sodaatanii kumaatama ta’anii ba’anii (qalbiin) hin ilaallee? Rabbiin “du’aa!” isaaniin jedhee, sana booda isaan jiraachise. Dhugumatti, Rabbiin namoota irratti abbaa tola (guddaa)ti. Garuu irra hedduun namaa hin galateeffatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 244, 'Karaa Rabbii keessatti lolaa. beekaa Rabbiin dhagayaa, beekaadhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 245, 'Namni liqii gaarii Rabbiif liqeessee Inni dachaa baay’ee isaaf baay’isu eenyuma! Rabbiin nama fedhe (rizqii) irraa qabata; kan fedhe immoo itti baldhisa. gara Isaatti deebifamtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 246, 'Sila gara qondaaltota Ilmaan Israa’iil irraa ta’an kan booda Muusaa,hin ilaallee? yeroo isaan nabiyyii isaaniitiin "hogganaa nuuf godhi karaa Rabbii keessatti lollaa" jedhan. [Inni] "Sila yoo lolli isin irratti murteeffame loluu dhabuu keessan hin sodaattamuu?" jedhe. "Odoo manneeniifi ilmaan keenya irraa baafamnee jirruu maaltu nuuf jiraayyi karaa Rabbii keessatti hin lolle?" jedhan. Yeroma lolli isaan irratti murteeffame namoota muraasa isaan irraa ta’an malee irraa gara galan. Rabbiin miidhaa raawwattoota ni beeka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 247, 'Nabiyyiin isaaniis isaaniin jedhe: "Dhugumatti, Rabbiin Xaaluutiin mootii godhee isiniif ergeera." [Isaan] nijedhan akkamiin nurratti mootummaan isaaf ta’a? nuutu isarra haqa mootomutti, bal''inna qabeenyarraa tahes hinkennamne. Ni jedhe: "Dhugumatti, Rabbiin isin irratti isa file, beekumsaafi qaama keessattis bal''ina isaaf dabale. Rabbiin mootummaa Isaa nama fedheef kenna. Rabbiin (arjummaan isaa) bal’aa, beekaadha."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 248, 'Nabbiyyiin isaaniis isaaniin ni jedhe: "Dhugumatti, mallattoon mootummaa isaa sanduuqni isinitti dhufuudha.kan isa keessa tasgabbiin Gooftaa keessan irraa ta’ee jiru. kan hanbaan waan maatiin Muusaafi maatiin Haaruun dhiisan irraa ta’e isa keessa jiru. malaa’ikoonni isa baadhatan (isinitti dhufuudha), Dhugumatti,kana keessa mallattootu isiniif jira yoo mu’uminoota taataniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 249, 'Xaaluut yeroma waraana (isaa) tiin achi bahe ni jedhe: "Dhugumatti, Rabbiin laga wahiitiin isin mokkoraadha.namni isa irraa dhuge anarraayii miti, Namni isa hin dhandhamin immoo anarraayy, Nama harka isaatiin hammaarrii tokkittii hammaarrate malee.isa irraa dhugan nama Muraasa isaan irraa ta''e malee. Yeroma isaafii warri isaa wwajjin amanan isa qaxxaamuran, (warri dhugan) ni jedhan: "Har''a Jaaluutiifi waraana isaa irratti dandeettiin nuuf hin jiru." Warri Rabbiin wal qunnamoo ta''uu isaanii dhugoomsan ni jedhan: "Garee muraasa heddutu hayyama Rabbiitiin garee baay’ee injifate." Rabbiinis warra obsan wajjin jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 250, 'Yeroma Jaaluutiifi waraana isaatiif dirreetti bahan ni jedhan: “Gooftaa keenya! Obsa nurratti dhangalaasi, Faana keenya gadi dhaabi; ummata kaafirootaa irrattis nu tumsi."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 251, 'Hayyama Rabbiitiin isaan injifatani. Daawuudis Jaaluutiin ajjeesee, Rabbiin mootummaafi ogummaa isaaf kennee, waan fedhe irraa isa barsiise. Odoo nama garii gariin deebisuun Rabbii jiraachuu baatee, silaa dachiin badde. Garuu Rabbiin aalama (hunda) irratti abbaa tola (guddaati).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 252, 'tun keeyyattoota Rabbiiti Dhugaadhaan ishee sirratti dubbifna. Ati dhugumatti ergamtoota irraayyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 253, 'Ergamoota kana garii isaanii garii irra caalchifne. Isaan irraa nama Rabbiin ittiin dubbatetu jira. Garii isaaniis sadarkaa heddu ol kaase. Iisaa ilma Maryamiif ragaawwan ifa ta’an kenninee jirra. Ruuhii qulqulluun (Jibriiliin) isa jajjabeessine. Odoo Rabbiin fedhee, warri booda isaanii erga ragaawwan ifa taate isaanitti dhuftee booda wal hin lolan turan. Garuu isaan wal dhabani. Isaan irraa namni amane ni jira; isaan irraas kan kafare ni jira. Odoo Rabbiin fedhee, wal hin lolan. Garuu Rabbiin waan fedhe hojjata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 254, 'Isin Yaa warra amantan! waan Nuti isiniif kennine irraa kennadhaa Odoo guyyaan (bittaa) gurgurtaan, jaalalleefi manguddummaan isa keessa hin jirre hin dhufin duratti. Kaafiroonni isaanumatu miidhaa raawwattoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 255, 'Rabbiin Isa malee haqaan gabbaramaan hin jiru; (Inni) jiraataadha; waan hundaan dhaabbataadha. Mugaatiis ta’ee hirribni Isa hin qabu. Wanti samiilee keessa jiruufi wanti dachii keessa jiru (hundi) kan Isaati. Inni hayyama Isaatiin malee Isa biratti araarsu eenyuma? Waan fuuldura isaaniitiifi waan duuba isaaniis ni beeka. Beekumsa Isaa irraa waan Inni fedhetti malee hin marsanu. Kursiin Isaa samiifi dachii irra bal’ateera. Isaan lamaan tiksuun Isa hin dadhabsiisu, Inni ol ta’aa, guddaadha.[1]', '[1] Aayanni tuni aayatul kursiyyii jedhamti, irra caaltuu aayatoowwan qur''aanaati. ganamaafii galgala, hirriiba dura qarauun barbaachisaa tahuun hadiisaan ibsame.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 256, 'Amantii keessa dirqisiisuun hin jiru. Dhugumatti, qajeelumni jallina irraa ifa ta''eera. Namni xaaghuutatti kafaree, Rabbitti amane, dhugumatti haada jabaa citiinsi isiif hintahin qabateera. Rabbiin dhagayaa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 257, 'Rabbiin gargaaraa warra amananiiti, Dukkanoota irraa gara ifaatti isaan baasa. Warri kafaran gargaartonni isaanii xaaghuuta; Ifa irraa gara dukkanootaatti isaan baasu. Isaan sun warra ibiddaati; isaan ishee keessatti hafoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 258, 'Sila gara isa Rabbiin mootummaa isaaf kenninaan (waa’ee) Gooftaa isaa keessatti Ibraahiimiin mormee hin ilaallee? Yeroo Ibraahiim "Gooftaan kiyya Isa jiraachisuufi ajjeesu sani" jedhu. "Anis nan jiraachisa; nan ajjeesas" jedhe (mootichi). Ibraahiim "Dhugumatti, Rabbiin aduu Baha irraa fida; ati immoo Dhiha irraa fidi" jedhe. Achumaan inni kafare dhama''e, Rabbiin miidhaa hojjattoota hin qajeelchu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 259, 'Yookiin akka isaa ganda irra dhufee haala (manneen ishee) mataa ishee irratti kukkuftee jirtuun "akkamumatti Rabbiin du’a ishee booda ishee kana jiraachisa!" jedhee (gara isaa hin ilaallee?). Rabbiin isa ajjeesee waggaa dhibba (tursiise). ergasii isa kaasee "hangam turte?" jedheen. "Guyyaa tokko, yookiin garii guyyaan ture" jedhe. (Rabbiiniis) ni jedhe: "miti waggaa dhibba turte, Mee gara nyaataafi dhugaatii keetii ilaali; hin jijjiiramne, Gara harree keetiis ilaali! Namootaaf mallattoo si taasisuuf (kana goone). gara lafeelee ilaali Akkamitti akka isii walitti qabnuufi ergasii foon itti uffifnu ." Yeroma ifa isaaf ta’u "Rabbiin waan hunda irratti danda’aa ta’uu nan beeka" jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 260, 'Yeroo Ibraahiim "Gooftaa kiyya! Akkamitti du’aa akka jiraachiftu natti agarsiisi" jedhe [yaadadhaa]. (Rabbiiniis) "Sila ati hin amannee?" jedhe. (Ibraahiimis): "Lakkii (amaneera), Garuu akka onneen kiyya tasgabbaa’uufi" jedhe. "Simbira irraa afur qabi, gara keetti fuudhii (isaan kukkuti), Sana booda muraa isaanirraa tahe gaara hunda irra kaayi, Ergasii isaan waami; daddafanii sitti dhufu.” Rabbiin injifataa, ogeessaa beeki jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 261, 'Fakkeenyi warra qabeenyaalee isaanii karaa Rabbii keessatti arjoomanii, akka fakkeenya firii sootalloo (mataa) torba baasteeti, sootalloo hunda keessa firiin dhibbi jiruuti. Rabbiin nama fedheef dachaa taasisa. Rabbiin (kenni isaa) bal’aa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 262, 'Warri qabeenyaalee isaanii karaa Rabbii keessatti kennatanii, ergasii waan arjooman dhaaddannaafi rakkisuu hin hordofsiisin, isaaniif mindaan isaanii Gooftaa isaanii bira jira. Sodaanis isaan irra hin jiru; isaan hin gaddanus.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 263, 'Jecha gaariifi dhiifamatu sadaqaa rakkisuun isa hordofu irra caala. Rabbiin dureessa, obsaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 264, 'Isin Yaa warra amantan! dhaaddannaafi (nama) rakkisuudhaan Sadaqaalee keessan hin balleessinaa, akka isa qabeenya isaa garsiifannaa namaatiif arjoomuu, kan Rabbiifi guyyaa Aakhiraattis hin amannee. Fakkeenyi isaa akka fakkeenya dhagaa diriiraa biyyeen isa irra jiruu, kan bokkaan cimaan isa tuqee (biyyee irraa dhiquun) duwwaa isa dhiiiseeti, Isaan waan horatan irraa homaa irratti dandeettii hin qaban. Rabbiin ummata kaafirootaa hin qajeelchu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 265, 'Fakkeenyi warra qabeenyaalee isaanii jaalala Rabbii barbaaduufi lubbuulee isaanii raggaasisuuf arjoomanii, akka fakkeenya ashaakiltii lafa ol fuudhamaa irra jiruu, bokkaan cimaan itti roobee oomisha ishee dachaan kennitee, yoo bokkaan guddaan ishee hin argatinis tiifuun (isiif gayuuti). Rabbiin waan isin dalagdan argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 266, 'Sila tokkoon keessan isaaf ta''uu ni jaalataa? ashaakiltiin Nakhliifi Inaba irraa ta’e, kan laggeen jala ishee yaatu, kan ishee keessa fuduraaleen hundi isaaf jiru, odoo ilmaan dadhabduu qabuu kan dullumti isa qabde, bubbeen ibiddi ishee keessatti tahe ishee tuqee gubatte. Akka isin xiinxaltaniif jecha akka kanatti Rabbiin keeyyattoota Isaa isiniif addeessa', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 267, 'Isin Yaa warra amantan! gaggaarii waan carraaqqattaniifi waan Nuti dachii irraa isiniif baafne irraa kennadhaa.isa irraa kennachuudhaan Waan fokkataa hin yaadinaa, (Odoo isiniif kennamee) Isa keessatti ija dunuunfattanii malee kan hin fudhanne taatan, Rabbiin dhugumatti dureessa, faarfamaa ta’uu beekaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 268, 'Shayxaanni hiyyummaan isin sodaachisa, hamtutti isin ajaja, Rabbiin araaramaafi tola Isa biraa ta’e waadaa isiniif seena. Rabbiin (kenni isaa) bal’aa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 269, 'Inni hikmaa (ogummaa) abbaa fedheef kenna, Namni hikmaa kenname, dhugumatti toltuun baay’een isaaf kennameera. Warra sammuu qaban malee eenyullee hin gorfamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 270, 'Kenna irraa waan isin kennattan yookiin qodhaa (nazrii) irraa waan nazartanis, Rabbiin isa beeka. Miidhaa hojjattootaaf tumsitoonni wahiitu hin jiranu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 271, 'Sadaqaa yoo mul’iftanii (kennattan) isheen waa tolte; yoo ishee dhoksitanii hiyyeeyyiif kennitan isatu isiniif caala. Hamtuuwwan keessanis isin irraa harcaasa. Rabbiin waan isin dalagdan keessa beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 272, 'Qajeelchuun isaanii (dirqama) sirratti hin taane. Garuu Rabbiin nama fedhe ni qajeelcha. Qabeenya irraas wanti isin kennattan lubbuma keessaniifi. Fuula Rabbii barbaachaaf malee hin kennattanu. Qabeenya irraa wanti isin kennattan isiniif guutamee galfama isin hinmiidhamtan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 273, '(Sadaqaan) hiyyeeyyii karaa Rabbii keessatti hidhamaniif (kennamti), warra dachii keessa deemuu hin dandeenye, kan kadhaa irraa of qabuu isaanii irraa wallaalaan dureeyyii isaan se’u, mallattoolee isaaniitiin beekta. namoota hinkadhatan, hin hifachiisan, Qabeenya irraa waan isin kennattan dhugumatti Rabbiin isa beeka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 274, 'Warra qabeenyaalee isaanii halkaniifi guyyaa, dhoksaafi ifatti mul’isanii arjooman, isaaniif mindaan isaanii Gooftaa isaanii bira jira. Sodaanis isaan irra hin jiru; isaan hin gaddanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 275, 'Warri dhala nyaatan (Guyyaa Qiyaama) hinkaafaman akka isa shayxaanni maraatummaa irraa isa kukuffisu dhaabbatuutti malee hin dhaabbatanuKunis waan isaan "bittaa gurgurtaan akkuma dhalaati" jedhaniifiRabbiin immoo bittaa gurgurtaa hayyamee dhala dhorgeNamni gorsi Gooftaa isaa irraa itti dhufee (dhala nyaachuu irraa) dhorgame, wanti (dhorgaan dura) darbe kanuma isaatiDhimmi isaas (waan dhufu keessatti) gara RabbiitiNamni (itti) deebi’e immoo isaan warra ibiddaati; isaan ishee keessatti hafoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 276, 'Rabbiin dhala (keessaa barakaa) ni haqa; sadaqaawwan immoo ni guddisa. Rabbiin warra akkaan kafaraa, dilaawaa hunda hin jaalatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 277, 'Dhugumatti, isaannan amananii gaggaariis hojjatanii, salaatas gadi dhaabanii, zakaas kennan, warri sun mindaan isaanii gooftaa isaanii bira isaaniif jira. Sodaanis isaan irra hin jiru; isaan hin gaddanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 278, 'Yaa warra amantan! Rabbiin sodaadhaa; yoo mu’uminoota taataniif dhala irraa waan (nama irratti) hafe dhiisaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 279, 'Yoo (kana) hin hojjatin, lola Rabbiifi ergamaa Isaa irraa ta’e beekkadhaa! Yoo tawbattan mataan qabeenya keessanii isinumaaf (haqa). Hin miitanus; hin miidhamtanus.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 280, 'Yoo (kan deyniin irra jirtu) rakkataa tahe hanga argatutti eeggachuutu (isin irra jira), (Isaanitti) saddaqachuutu irra isiniif caala. Yoo kan beektan taataniif (sadaqadhaa).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 281, 'Guyyaa sodaadhaa kan isa keessa gara Rabbii deebifamtan, ergasii lubbuun hundi waan hojjatteen galata galfamtu, isaan hinmiidhaman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 282, 'Yaa warra amantan! Hanga beellama beekamaatti liqii yoo walii liqeessitan isa barrreessaa, Barreessaan gidduu keessanitti haqaan haa barreessu, Barreessaanis akka Rabbiin isa barsiisetti barreessuu hin didin. Haa barreessu; Inni liqiin isa irra jiru haa dubbisuu, Allaah gooftaa isaa haa sodaatu. Isa irraas homaa hin hir’isin. Yoo inni liqiin isa irra jiru gowwaa yookiin dadhabaa yookiin inni kan dubbisuu hin dandeenye ta’e firri isaa haqaan haa dubbisu, Ragaa lama dhiirota keessan irraa ragsiifadhaa. Yoo dhiirri lama hin argamin, dhiira tokkoofi dubartii lama, dagachuu ishee tokkoofi yaadachiisuu ishee birootiif jecha, ragoolee namoota isin jaallattan irraa haala ta’aniin ragaa godhaa. Ragoonnis yeroo waamaman hin didin. Xiqqaas ta’ee guddaa, hanga yeroo isaatti, isa barreessuu hin hifatinaa. Kanatu Rabbiin biratti irra haqa; ragummaafis irra mirkanaa’aadha; akka isin hin shakkineefis irra dhihoodha. yoo daldala bakkuma sanitti gidduu keessanitti raawwattan taate malee, ishee barreessuu dhabuudhaan badiin isin irra hin jiru. Yeroo bittanii walitti gurgurtanis ragaa godhaa. barreessaafii raga bahaan miidhamuu hin qabu. Yoo raawwattan, dhugumatti inni fincila (ajaja Rabbii diduu) keessani. Rabbiin sodaadhaa; Rabbiin isin barsiisa. Rabbiin waan hunda beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 283, 'Yoo imala irra jiraattanii barreessaa hin argatin, qabdii fuudhamtuu taatetu (qabadhaa). Yoo gariin keessan garii amane immoo, inni amaname amaanaa isaa haa dhaqqabsiisu; Rabbii Gooftaa isaa haa sodaatu. Ragaa hin dhoksinaa, Namni ishee dhokse, dhugumatti inni onneen isaa dilaawaadha. Rabbiinis waan isin hojjattan beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 284, 'Wantoonni samiileefi dachii keessa jiran kan Rabbiiti. Waan lubbuulee teessan keessa jiru yoo ifatti mul’iftan yookiin yoo isa dhoksitan Rabbiin ittiin isin qorata; nama fedheef ni araarama; nama fedhe immoo ni adaba. Rabbiin waan hunda irratti danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 285, 'Ergamaan (kiyya) waan Gooftaa isaa irraa gara isaatti buufametti amaneera; mu’uminoonnis. Hundumtuu Rabbitti, malaa’ikota Isaa, kitaabota Isaafi ergamtoota Isaatti amananiiru. "Nuti ergamtoota Isaa irraa jidduu tokkoos adda hin baafnu" (jedhan). "Nuti dhageenye; ajajamnes. Gooftaa keenya! Araarama kee (barbaanna). Deebiinis garuma keeti" jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 286, 'Rabbiin lubbuu tokkos dandeettii isheetiin malee hin dirqisiisu. (Toltuu irraa) wanti isheen carraaqqate isheedhumaafi; (hamtuu irraa) wamti isheen carraaqqattes ishee irratti (ta’a). "Gooftaa keenya! Yoo daganne yookiin dogoggorre nu hin qabin. Gooftaa keenya! Ba’aa guddaa akka warra nuun duraa irratti baachifte nurratti hin baachisin. Gooftaa keenya! Waan isatti dandeettiin nuuf hin jirre nu hin baachisin. Irras nuuf dabri; nuuf araaramis Rahmatas nuuf godhi. Ati gargaaraa keenya, Ummata kaafirootaa irrattis nuuf tumsi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 1, 'Alif Laam Miim', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 2, 'Rabbiin gabbaramaan dhugg isa malee hin jiru. [Inni] jiraataa, waan hundaan dhaabbataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 3, 'Kitaaba dhugaadhaan sirratti buuse.Waan isaan duraa kan dhugoomsu haala ta''een. Tawraatiifi Injiiliinis buuse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 4, '[Qur’aana] dura namootaaf qajeelfama godhee [isaan buuse]. (Dhugaafi soba) adda baasaas ni buuse. Dhugumatti, warri keeyyattoota Rabbiitti kafaran isaaniif adabbii cimaatu jira. Rabbiin injifataa, abbaa haaloo bayannaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 5, 'Rabbiin dhugumatti homtuu isa jalaa hindhokatu, dachii keessattiifii samii keessattis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 6, 'Inni Isa gadaamessaawwan keessatti akka fedhetti isintolchu.Haqaan gabbaramaan isa malee hin jiru. [Inni] injifataa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 7, 'Inni isa kitaaba sirratti buuse. Isa irraa keeyyata ifaatu jira. Isaan bu’uura kitaabaatiKan biraa immoo wal fafakkaattuudhaWarri onnee isaanii keessa jal’inni jiru fitnaa barbaachaaf yookiin hiika isa dhokataa barbaachaaf jecha isa wal fafakkaataa hordofuHiika isaa isa dhokataa Rabbiin malee homtuu hin beekuWarri beekumsa keessa fagaatan immoo “hundinuu Rabbii keenya biraayyii itti amanne” jedhuWarra sammuu qabu malee namni biroo hin gorfamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 8, '[Isaanis ni jedhu]: Gooftaa keenya! Erga nu qajeelchitee booda onnee keenya [dhugaa irraa] hin jal''isin. Rahmata Si biraa ta’e nuuf kenni. Dhugumatti Ati akkaan kennaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 9, 'Gooftaa keenya! Ati guyyaa isa keessa mamiin hin jirreef nama walitti qabuuf jirta. Dhugumatti Rabbiin beellama hindiigu [jedhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 10, 'Dhugumatti isaannan kafaran qabeenyaaleefi ilmaan isaanii Rabbirraa (adaba Isaa irraa) homaa isaan hin duroomsitu. warri sun qoraan ibiddaati', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 11, '[Haalli isaanii] akka haala namoota Fir’awniifi warra isaan dura turaniiti. Keeyyattoota keenya kijibsiisan. Rabbiin badiilee isaanitiin isaan qabe. Rabbiin abbaa adabbii cimaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 12, 'Isaan kafaraniin jedhi: fuulduratti ni injifatamtu; gara jahannamittis ni oofamtu. Waa fokkatee iddoon qubannichaa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 13, 'Dhugumatti, mallattoon isiniif tahe gareewwan (waraanaa) lamaan [guyyaa Badrii] wal qunnaman keessatti. Gareen tokko karaa Rabbii keessatti lolti. Isheen biraa immoo kaafira. Isaan (kaafiroonni) ilaalcha ijaatiin (lakkoofsa Muslimootaa) dachaa isaanii ta’anii isaan argu. Rabbiin nama fedhe tumsa Isaatiin isa deeggara. Dhugumatti warra sammuu qabaniif kana keessa gorsatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 14, 'Namootaaf miidhagfame jaalalli wantoota lubbuun feetuu kan dubartootaafi ilmaan irraa, kuusaa warqeefi meeta kuufame irraa, faradoo malateeffamtee (miidhagfamte), beelladaafi oorruu qonnaa irraa ta’e (miidhagfamee). Kun meeshaa jireenya addunyaati. Rabbiin immoo Isa bira deebii bareedaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 15, 'Jedhi: “Sila waan sana caalu isiniif odeessuu? Isaan Rabbiin sodaataniif Gooftaa isaanii bira jannata laggeen ishee jala yaatu kan yeroo hunda ishee keessa jiraatantu isaaniif jira. Ammas niitolii qulqulleeffamaniifi jaalala Rabbiin biraa ta’etu [isaaniif jira]. Rabbiin gabroota argaadha."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 16, 'Isaan warra “Gooftaa keenya! Dhugumatti, nuti amanneerra; kanaaf badiilee keenya nuuf araarami; adabbii ibiddaas nu baraari” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 17, 'Obsitoota, dhugaa dubbattoota, [Rabbiif] ajajamtoota, kennattootaafi warra obboroo keessa dhiifama kadhatanin [faarsa].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 18, 'Rabbiin akka Isa malee dhugaan gabbaramaan hin jirre ragaa ba’e; maleeykonniifi warri beekumsaas (ragaa ba’aniiru) haqaan dhaabbataa ta’ee,isa malee haqaan gabbaramaan hin jiru. injifataa, ogeessa .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 19, 'Dhugumatti amantiin Rabbiin biratti [fudhatama qabu] Islaama qofa. Isaan kitaabni kennameef erga beekumsi isaaniif dhufee booda jibbaa gidduu isaanii jiruuf jecha malee [san dura] wal hin dhabne. Namni keeyyattoota Rabbiitti kafare dhugumatti Rabbiin ariifataa qormaataati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 20, 'Yoo isaan siin falman: “fuula kiyya Rabbiif sirreesse (kan ajaja rabbi jala butamu taasise); namni ana hordofes [akkasuma]” jedhi. Warra kitaabni isaaniif kennameefi wallaaltotaanis “sila islaamoftaniittuu?” jedhi. Yoo islaama''aniif dhugumatti qajeelaniiru. Yoo irraa garagalan wanti sirra jiru ergaa geessisuu qofa. Rabbiin gabroota argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 21, 'Dhugumatti isaan keeyyattoota Rabbiitti kafaranu, karaan ala nabiyyoota ajjeesanuufi namoota irraas warra haqatti ajajanis ajjeesanu, adabbii laalessaan isaan gammachiisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 22, 'Isaan warra dalagaaleen isaanii addunyaafi Aakhirattis jalaa baddeedha. Isaaniif tumsitoonni hin jiran.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 23, 'Sila gara isaan kitaaba irraa qoodni wahii isaaniif kennamee hin ilaallee? Akka jidduu isaaniitti murteessuuf gara kitaaba Rabbii waamamanii ergasii gareen isaan irraa ta’e didaa ta’ee gara gala.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 24, 'Kun waan isaan “ibiddi guyyoota lakkaa’amtuu malee nu hin tuqxu” jedhaniifi. Kijibni isaan [of biraa] uumaa turan amantii isaanii keessatti isaan gowwoomse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 25, 'Sila yeroo Nuti guyyaa mamiin isa keessatti hinjirreef walitti isaan qabnee lubbuun hundi waan hojjatte guutuutti argatte akkam ta’u? isaan hin miidhamanu (hin zallamaman).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 26, '[Yaa Muhammad!] jedhi: "yaa Rabbii abbaa mootummaa taate! Mootummaa nama feeteef kennita; nama feete irraa immoo mootummaa mulqita, Nama feetes ni jabeessita, Nama feetes ni xiqqeessita, Toltuun hundi harka kee jira. Dhugumatti Ati waan hunda irratti danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 27, 'Halkan guyyaa keessa seensifta. Guyyaas halkan keessa seensifta. Du’aa irraas jiraa baafta, Jiraa irraas du’aa baafta, Nama feete herrega malee hiree hirtaaf" [jedhi]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 28, 'Mu’uminoonni mu’uminoota malee kaafiroota jaalallee hin godhatin. namni kana dalage, [diinii] Rabbii irraa homaa keessa hin jiru, Yoo eeggannaa wahii isaan irraa eeggachuuf ta’e malee, Rabbiin nafsii Isaa isin sodaachisa. Deebiinis garuma Rabbiiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 29, 'jedhi “Yoo waan qoma keessan keessa jiru dhoksitan yookiin isa mul’iftanis Rabbiin isa beeka. [Inni] waan samii keessa jiruufi waan dachii keessa jiru ni beeka. Rabbiin waan hunda danda’aadha” .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 30, 'Guyyaa lubbuun hundi toltuu irraa waan hojjatte dhiyaataa ta''ee argitu [yaadadhu]Hamtuu irraa waan hojjatte immoo odoo jidduu isheetiifi jidduu isaa fageenyi dheeraan jiraatee hawwiti, Rabbiin nafsii Isaa isin sodaachisa. Rabbiin gabroota akkaan mararfataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 31, 'jedhi ”Yoo kan Rabbiin jaallattan taataniif na hordofaa Rabbiin isin jaallata; badii keessan isiniif araarama. Rabbiin araaramaa, rahmata godhaadha”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 32, 'jedhi ”Rabbiifi ergamaaf ajajamaa” jedhi. Yoo irraa garagalaniif [kafaraniiru]. Dhugumatti Rabbiin kaafiroota hin jaalatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 33, 'Dhugumatti Rabbiin Aadam, Nuuh, maatii Ibraahimiifi maatii Imraan aalama hunda irra filateera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 34, 'Sanyii gariin ishee garii irraa taate san [filate]. Rabbiin dhagayaa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 35, 'Yeroo niitiin Imraan jette “Gooftaa kiyya! ani waan garaa kiyya keessa jiru (ulfa) bilisa godhee siif nazareeraa narraa qeebali Dhugumatti Ati simatu dhagayaa, beekaadha.” [yaadadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 36, 'Yeroma ishee deesses “Gooftaa kiyya! ani dubran daye" jette. Rabbiin irra beekaa waan isheen deesseeti. “Dhiirri akka durbaa hin taane. Ani Maryam ishee moggaaseera. Ani sheyxaana abaaramaa irraa isheefi sanyii ishees siinan tiksa” [jette].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 37, 'Gooftaan ishee qeebaltii gaarii ta’een ishee qeebale. Guddina gaarii ishee guddise. Zakariyyaan ishee guddise. Zakariyyaan dhawaatuma ishee irratti mihraaba seenuun soorata ishee biratti arga. “Yaa maryam kun eessaa siif dhufa?” jedhe. “Inni Rabbiin biraayyi” jette. Dhugumatti Rabbiin nama fedhe herrega malee soora.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 38, 'Bakka sanatti Zakariyyaan Rabbii isaa kadhate “Gooftaa kiyya! Ati Suma biraa ilmaan gaarii naaf kenni. Dhugumatti Ati dhagayaa kadhaati" jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 39, 'Malaa’ikoonnis isaa mihraaba keessa dhaabbatee sagadaa jiruu isa yaamte “Dhugumatti Rabbiin Yahyaadhaan si gammachiisa, dhugoomsaa jecha Rabbi irraa ta''e, caalaa, qunnamtii saalaa irraa eegamaafi nabiyyii gaggaarota irraa ta’een " (jettee isatti lallabde).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 40, '[Innis] nijedhe “yaa Gooftaa kiyya! akkamitti ilmi naaf taha? osoo dhugaatti dullumni na qabee jiruufi niitiin tiyyas maseena taatee jirtuu " jedhe. [Rabbiinis] “Akka kanatti Rabbiin waan fedhe hojjata” jedheen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 41, '[Innis] “yaa Gooftaa kiyya! mallattoo naaf taasisi” jedhe. (Rabbiinis) nijedhee "mallattoon kee Guyyoota sadii akeekkiin malee namootatti dubbachuu dhabuu keeti.Gooftaa kee baay’inaan faarsi.Galgalaafi ganamas Isa qulqulleessi”( jedheen.)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 42, 'Yeroo Malaa’ikoonni jette “Yaa Maryam! Dhugumatti Rabbiin si filateera. Si qulqulleesseeras. Dubartoota aalama hundaa irra si filateera” [yaadadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 43, '”Yaa Maryam! Gooftaa keetiif akkaan ajajami. Sujuudas godhi. Warra gadi jedhan waliinis gadi jedhi (rukuu’a godhi)."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 44, 'Kun oduuwwan fagoo irraa kan Nuti gara keetti isa beeksifnuudha. Yeroo ‘isaanirraa eenyu Maryamiin akka guddisu hixaalee isaanii darban ati isaan bira hin jirtu. Yeroo isaan wal falmanis ati isaan bira hin turre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 45, 'Yeroo malaa’ikoonni jette “yaa Maryam! dhugumatti Rabbiin jecha Isa biraa ta’een sigammachiisa, kan maqaan isaa Al-Masiih Iisaa ilma Maryam (jedhamu), kan addunyaafi Aakhiraattis kabajamaafi warra Rabbitti dhiheeffaman irraa ta’e” [yaadadhu]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 46, 'Daa’imummaafi dargaggummattis namaan dubbata. Warra gaggaarii irraayyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 47, '[Maryamis] nijette “yaa Gooftaa kiyya! Odoo namni tokkollee ana hin tuqne akkamitti ilmi naaf argama?” [Rabbiinis] “Akka kanatti Rabbiin waan fedhe uuma. Inni yeroo waan tokko murteesse ‘ta’i!’ qofa isaan jedha; yeroma san ta’a” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 48, '(Rabbiin) Barreeffama, ogummaa, Tawraatiifi Injiiliinis isa barsiisa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 49, 'Gara ilmaan Israa’iilitti ergamaa [isa godha] “Ani dhugumatti Gooftaa keessan irraa raajiidhaanan isinitti dhufe. Ani dhoqqee irraa waan akka allaattiin isiniif uuma; isa keessattis nan afuufa; eeyyama Rabbiitiin allaattii ni ta’a. Eeyyama Rabbiitiin jaamaafi lamxii nan fayyisa. Eeyyama Rabbiitiin du’aas nan jiraachisa. Waan isin nyaattaniifi waan isin manneen keessan keessa ol kaayattanis isinittin hima. Dhugumatti kana keessa muimintoota taataniif mallattootu isiniif jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 50, 'Waan na dura ture Tawraatirraa kanan dhugoomsu ta''ee, garii wantoota dhorgaa isin irratti taasifamanii halaala isiniif taasisuuf jechan ragaa Gooftaa keessan irraa ta’een isinitti dhufe. Rabbiin sodaadhaatii anaaf ajajamaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 51, 'Dhugumatti Rabbiin Gooftaa kiyyaafi Gooftaa keessan; kanaafuu Isa gabbaraa. Kun karaa qajeelaadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 52, 'Iisaan yeroma kufrii isaan irraa ittidhagayame “ tumsitoonni kiyya gara Rabbiitti eenyu?” jedhe. Hawaariyyoonni “nutu tumsitoota Rabbiiti. Rabbitti amanneerra. Akka nuti Muslimoota taanes ragaa nuuf ba’i” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 53, '“Yaa Gooftaa keenya! Nuti waan Ati buuftetti amanneerra. Ergamicha (Iisaas) hordofne; kanaafuu warra [Rabbiin malee Gooftaan biraa akka hin jirre] ragaa ba’an wajjin nu barreessi” [jedhan].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 54, 'Isaanis tooftaa baasani; Rabbiinis tooftaa baase. Rabbiin immoo irra caalaa warra tooftaa baasuuti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 55, 'Yeroo Rabbiin jedhes [yaadadhu]:“Yaa Iisaa! Ani si fudhataadha, Gara kiyyattis ol si fuudhaadha, Isaan kafaran irraa si qulqulleessaadha. Isaan si hordofanis hanga Guyyaa Qiyaamatti warra kafaran irratti ol taasisaadha. Ergasii deebiin keessan gara kiyya; waan isin isa keessatti wal dhabaa turtan keessattis gidduu keessanitti nan murteessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 56, 'Isaan kafaran addunyaafi Aakhiratti adabbii cimaan isaan adaba; tumsaan isaaniif hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 57, 'Warra amananii gaggaarii dalagan immoo mindaalee isaanii ni guutaafi. Rabbiin miidhaa raawwattoota hin jaal’atu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 58, 'Kana keeyyattootaafi gorsa ogummaa irraa ta’e sirratti dubbifna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 59, 'Dhugumatti, fakkeenyi Iisaa Rabbiin biratti akka fakkeenya Aadami. Biyyee irraa isa uume, Ergasii (nama) ‘ta’i’ isaan jedhe, Innis yeroma san ta’e', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 60, 'Dhugaan Gooftaa kee biraayyi; shakkitoota irraa hin ta’in.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 61, 'Nama erga beekumsi sitti dhufee booda isa keessatti siin falmeen “Kottaa; ilmaan keenyaafi ilmaan keessan, dubartoota keenyaafi dubartoota keessan, lubbuulee keenyaafi lubbuulee keessan haa waamnu. Ergasii du''aa''iitti jabaannee abaarsa Rabbii kijibdoota irra haa goonu” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 62, 'Dhugumatti kun isumatu seenaa dhugaati. Rabbiin malee dhugaan gabbaramaan hin jiru. Dhugumatti Rabbiin Isatu injifataa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 63, 'Yoo [dhugaa] irraa gara galan, Rabbiin beekaa balleessitootaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 64, 'Jedhi: “yaa warra kitaabaa! Gara jecha nuufi isin gidduutti wal qixa taateetti kottaa. [Isheenis] akka Rabbiin malee waan biraa hin gabbarre; Isattis waan biraa akka hin qindeessine, gariin keenyas garii Rabbiin alatti gabbaramaa akka hin taasifanneedha. Yoo isaan [kana] irraa gara galan “akka nuti Muslimoota taane ragaa ba’aa” jedhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 65, 'Yaa warra kitaabaa! Maaliif waa’ee Ibraahiim keessatti falmitu? Tawraatiifi Injiil isa booda malee hin buufamne; sila hin xiinxaltanuu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 66, 'Dhaga’aa! isin warri kun waan beekumsi isaa isiniif jiru keessatti falmitaniittu! Maaliif waan beekumsi isaa isiniif hin jirre keessatti wal falmitu? Rabbiin ni beekaa isin hin beektanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 67, 'Ibraahiim yahuudas kiristaanas hin taane, Garuu inni Muslima qajeelaa ture, Inni mushrikoota irraas hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 68, 'Namoonni Ibraahiimitti irra aanan: isaan isa hordofan, nabiyyii kanaafi warra amananiidha. Rabbiin gargaaraa mu’uminootaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 69, 'Gareen warra kitaabaa irraa taate tokko isin jallisuu jaalatte, Lubbuu isaanii malee homaa hin jallisanu; garuu isaan hin beekanu', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 70, 'Yaa warra kitaabaa! odoo beektanuu maaliif keyyattoota Rabbiitti kafartu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 71, 'Yaa warra kitaabaa! maaliif dhugaa sobaan walitti maktan, (maalif) odoo beektanuu dhugaa dhoksitu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 72, 'Gareen warra kitaabaa irraa taate ni jette: “jalqaba guyyaa isa warra amanan irratti buufametti (qur''aanatti) amanaa. dhuma guyyaa immoo itti kafaraa. Akka isaan [Islaama] irraa deebi’aniif jecha .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 73, 'warra amantii keessan hordofeef malee hin amaninaa (ifa hin baasinaa)(Yaa Muhammad SAW) jedhi “qajeelfamni qajeelfama Rabbiiti" “Tokkoon namaa fakkii waan isin fudhattanii fudhachuu yookiin kan Rabbii keessan biratti ittiin isin falmun (akka hin argamne beekkomsa isin bira jiru muslimootatti hin mul''isinaa)".(waliin jedhan). jedhi "Tolli harka Rabbiiti (tahe); abbaa fedheef isa kenna” Rabbiin (kenni isaa) bal’aa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 74, 'Inni nama fedhe rahmata Isaatiif (nabiyyummaadhaaf) filata. Rabbiin abbaa tola guddaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 75, 'Warra kitaabaa irraas nama yoo ati qabeenya guddaan isa amante isa siif deebisutu jira. Isaan irraas nama yoo diinaaraan isa amante hanga yeroo dheeraa isaaf eegdutti isa siif hin deebifnetu jira. Kun waan isaan “wallaaltota (qabeenya isaanii nyaachuu) keessatti badiin nurra hin jiru” jedhaniifi. odoo beekanuu Rabbi irratti kijiba odeessaniifi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 76, 'Eeyyeen! (badiin isaan irra ni jira). namni waadaa isaa guuteefi (Rabbiin) sodaate, dhugumatti Rabbiin warra (Isa) sodaatanu ni jaalata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 77, 'Dhugumatti, isaan waadaa Rabbiifi kakuu isaanii gatii xiqqaan jijjiirratan, isaan Aakhiratti qoodni homaatuu isaaniif hin jiru. Rabbiin Guyyaa Qiyaamaa isaan hin dubbisu; gara isaaniis hin ilaalu; isaan hin qulqulleessus. adabbiin laalessaan isaaniif jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 78, 'Isaan irraa garee arraboowwan isaanii kitaabaan micciirantu jira, akka isin kitaaba irraayi jettanii isa yaaddaniif jecha, inni kitaabarraayii miti.inni Rabbiin biraayi jedhu. inni Rabbiin biraayii miti. Rabbirratti kijiba Odoma beekanuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 79, 'Ilma namaa tokkoof Rabbiin kitaaba, hukmii (beekumsaafi hubannoo seera amantii)fi nabiyyummaa isaaf kennee, ergasii namootaan “Rabbii gaditti gabroota naaf ta’aa” jechuun (isaaf) hin malu. Garuu (kan inni isaaniin jedhu) waan kitaaba barsiisaa turtaniifi waan qu''ataa turtaniif jecha beektota beekumsa isaaniitiin hojjatan ta’aa jechuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 80, 'Maleykotaafi nabiyyoota gabbaramtoota taasifachuutti isin ajajuun isaaf hin malu. Sila erga isin Muslimoota taatanii booda kufritti isin ajajaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 81, 'Yeroo Rabbiin nabiyyoota irraa waadaa fuudhe “waan ani kitaabaafi ogummaa irraa isiniif kennee, ergasii ergamaan waan isinii wajjin jiru dhugoomsu isinitti dhufe, akka isatti amantaniifi isa tumsitanu” ((jechuun) waadaa qabate) [yaadadhu]. (Rabbiinis) "mirkaneessitanii? Sana irrattis waadaa kiyya qabdanii?" jedhe. [Isaan] "mirkaneessine" jedhan; (Rabbiinis) “Ragaa bahaa; anis warra isinii wajjin ragaa bahan irraayi” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 82, 'Namni sana booda garagale, warri sun isaantu finciltoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 83, 'Sila amantii Rabbii malee kan biraa barabaadanii? odoo wantoonni samiifi dachii keessaa hunduu fedhaan yookiin dirqamaan isaaf (Rabbiif) ajajamee jiruu. gara isaatti deeffaman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 84, '(Yaa Muhammad SAW) jedhi “Rabbitti amanne, Waan nurratti buufametti, Waan Ibraahiim, Ismaa’iil, Isihaaq, Ya’aquub, asbaax, (ilmaan Ya’aquub) (irratti buufametti), waan Muusaa, keennametti, Iisaafi nabiyyoonni Gooftaa isaanii irraa (kennamanittis) amannee jirra. Isaan irraa gidduu nama tokkoos addaan hin foonu. Nuti isaaf ajajamtoota”(jedhi).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 85, 'Namni Islaamaan alatti amantii barbaade isarraa hin qeebalamu. Aakhiraattis inni warra hoonga’an irraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 86, 'sila Rabbiin akkamitti qajeelcha? ummata amanuu isaanii booda kafaran, kan ergamaan Rabbii dhugaa ta’uu ragaa ba’an. kan ragoonni ifa ta’an isaanitti dhufan. Rabbiin miidhaa hojjattoota hin qajeelchu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 87, 'Warri sun galanni isaanii abaarsi Rabbii, kan maleeykotaafi namoota hundaa isaan irra jiraachuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 88, 'Ishee (ibidda) keessatti hafoodha. Azaabni isaan irraa hin salphifamu. Yeroonis isaaniif hin kennamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 89, 'Garuu isaan sana booda tawbatanii toltuu hojjatan (isaaniif ni dhiifama) Dhugumatti Rabbiin araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 90, 'Warra iimaana isaanii booda kafaranii ergasiis kufrii dabalatan tawbaan isaanii hin qeebalamtu. Isaan isaanumatu jallattoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 91, 'Dhugumatti isaan kafaranii, kaafiroota ta’anii du’an, warqee dachii guutuun, odoma ittiin of bituu fedheeyyuu tokkoon isaanii irraa hin qeebalamu. Sunniin isaaniif adabbii laalessaa ta’etu jira. Isaaniif tumsitoonnis hin jiran.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 92, 'Hanga waan jaalattan irraa kennattanitti toltuu hin argattan. Wanta isin wahirraa (qabeenya irraa) kennattan Rabbiin isa beeka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 93, 'nyaanni hunduu Ilmaan Israa’iiliif halaala tahe ture, Waan Israa’iil odoo Tawraat hin bu’in dura lubbuu isaa irratti haraama taasise malee. (Yaa Muhammad) jedhiin "Tawraatiin fidaa isii dubbisaa yoo kan dhugaa dubbattan taatan ”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 94, 'Namni sana booda Rabbi irratti kijiba uume, warri sun isaantu miidhaa hojjattoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 95, 'jedhi “Rabbiin dhugaa dubbateera; karaa amantii Ibraahiim qajeelaa ta’e hordofaa. Innis mushrikoota irraa hin taane"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 96, 'Dhugumatti manni jalqaba ilma namaatiif kaayame isa Bakkaan (Makkaan) jiruudha. haala barakeeffamaafi qajeelfama aalama hundaaf ta’een.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 97, 'Isa keessa mallattoolee ifa ta’an dhaabbata Ibraahiimtu jira. Namni isa seene nagaa ta’a. Rabbiif nama irratti,manicha hajja''uutu dirqamni jira. kan gara isaa deemuu danda''e irratti, Namni kafare, dhugumatti Rabbiin aalama irraa duroomaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 98, '“Yaa warra kitaabaa! maaliif keeyyattoota Rabbiitti kafartu?” jedhi. Rabbiin waan isin dalagdan irratti ragaadha (nibeeka).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 99, 'jedhi “Yaa warra kitaabaa! Sila maaliif karaa Rabbii irraa nama amane debiftan? jallina ishee barbaachaaf odooragaa baatanuu Rabbiin waan isin dalagdan irraa dagataa miti".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 100, 'Yaa warra amantan! Yoo garee warra kitaabni kennameef irraa ta’ee tole jettan, erga amanuu keessanii booda gara kufriitti isin deebisu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 101, 'Sila odoo keeyyattoonni Rabbii isin irratti qara’amaniifi ergamaan Isaa isin keessa jiruu akkamitti kafartu? Namni Rabbiin of tikse dhugumatti karaa sirraawaatti qajeelfameera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 102, 'Yaa warra amantan! Dhugaa sodaa isaa Rabbiin sodaadhaa; Muslimoota taatan malee hin du’inaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 103, 'Haada Rabbiis (Qur’aana) hunda ta''aa qabadhaa; adda adda hin ba’inaa. Ni’imaa Rabbii kan yeroo isin diinota walii taatanii turtan, Inni onnee keessan wal simsiisuun ni’imaa Isaatiin obboleeyyan taatan san,(yaadadhaa), isin irra jiruufi (yeroo) isin qarqara boolla ibiddaa irra turtanii ishee irraa isin baraarse yaadadhaa.Rabbiin akka kanatti keeyyattoota Isaa isiniif addeessa Akka isin sirrooftaniif jecha .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 104, 'Isin irraa ummanni gara khayrii waamtuufi tan gaariitti ajajju badii irraa dhorgitu haa jiraattu. Warri sun isaantu milkaa’oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 105, 'Akka warra erga ragoota ifa ta’an isaanitti dhufee booda addaan faca’aniifi wal dhabanii hin ta’inaa, Warra san isaaniif adabbii laalessaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 106, 'Guyyaa fuulleen gariin addaataniifi fuulleen gariin gurraacha’an (adabamu) (dubbadhu). Warri fuulleen isaanii gurraachofte immoo “sila erga amanuu keessaniitii booda kafartanii? Waan kafaraa turtaniif adabbii dhandhamaa” (isaaniin jedhama).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 107, 'Warri fuulleen isaanii addaatte immoo rahmata Rabbii keessa ta’u; Isaan ishee keessatti hafoodha', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 108, 'Isheen sun, keeyyattoota Rabbiiti, ishee sirratti qaraana, Rabbiin aalama hundaafuu miidhaa kan fedhu hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 109, 'Wantoonni samiifi wantoonni dachii keessa jiran (hundi) kan Rabbiiti. Wantoonni hunduu gara Rabbiitti deebifamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 110, 'Isin caaltuu ummata namaaf mul''ifamtee taataniittuToltutti ajajju; hamtuu irraas ni dhorgitu; Rabbitti ni amantu. Odoo abbootiin kitaabaa amananii, silaa gaarii isaaniif ta’a ture. Isaan irraa mu''uminoonnis ni jiru; garuu irra hedduun isaanii finciltoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 111, 'Rakkisuu malee isin hin miidhanu. yoo isiniin lolan duuba isinitti deebi’u (isin dheeysu). Ergasii tumsa hin argatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 112, 'bakkuma isaan jiran hundatti salphinni isaan irra kaayamteetti, Yoo waadaa Rabbirraa ta’eefi waadaa nama irraa ta’een (eegaman) malee, Dallansuu Rabbirraa ta’eenis deebi’an; hiyyummaanis isaan irra kaayamte. Kun waan isaan keeyyattoota Rabbiitti kafaraa turaniifi karaan ala nabiyyoota ajjeesaa turaniifi. Kun waan isaan ajaja Rabbii didaniifi daangaa dabraa turaniifi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 113, 'Isaan wal qixa miti, Abbootii kitaabaa irraa namoota dhugaaf dhaabbatan, kan sujuudaa sa’aatii halkanii keeyyattoota Rabbii qara’antu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 114, 'Rabbittiifi guyyaa Aakhiraatti amanu; toltuuttis ni ajaju; hamtuu irraas ni dhorgu; toltuu keessattis ni arifatu, Isaan sun warra gaggaarii irraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 115, 'Toltuu irraa wanta hojjatan kamillee hin dhorgatamanu.Rabbiin warra (Isa) sodaatan beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 116, 'Dhugumatti isaannan kafaran, qabeenyiifi ilmaan isaanii (adabbii) Rabbii irraa homaa isaan hin deebiftu. Sunniin warra ibiddaati. Isaan ishee keessatti hafoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 117, 'Fakkeenyi waan isaan jiruu addunyaa tana keessatti sadaqatanii akka fakkeenya bubbee qorri hamaan isii keessa jirtuu, kan ooyruu warra lubbuu isaanii miidhanii tuqxee, isa balleessiteeti. Rabbiin isaan hin miine; garuu isaantu lubbuullee isaanii miidhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 118, 'Yaa warra amantan! namoota isin irraa hin ta’in jaalalloo iccitii hin godhatinaa, Isin balleessuu irraa duubatti hin deebi’anu, Rakkina keessan hawwani, Dhugumatti, jibbaan afaanoowwan isaanii irraa mul’atte, Wanti qomni isaanii dhoksitu immoo irra guddaadha, Yoo kan xiinxaltan taataniif aayatoowwan ifa isiniif taasifnee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 119, 'Dhaga''aa! isin warri kun isaan jaallattu; isaan immo isin hin jaalatanu, Isin kitaabota hundatti ni amantu, Yeroo isin qunnaman “nuti amannee jirra” jedhu, Yeroo kophaa ba’an immoo dallansuu irraa kan ka''e quba isaanii isin irratti ciniinu, “Dallansuu keessaniin du’aa" jedhi, Dhugumatti Rabbiin beekaa waan qoma keessa jiruuti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 120, 'Yoo toltuun isin tuqxe, isaan gaddisiisti, Yoo hamtuun isin tuqxe immoo isheetti gammadu, Yoo isin obsitanii (Rabbiin) sodaattaniif malli isaanii homaa isin hin miidhu. Dhugumatti Rabbiin waan isaan dalagan (beekumsa Isaatiin) itti marsaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 121, 'Yeroo ati mu’uminoota iddoowwan lolaa kan qubsiiftu taatee maatii kee irraa ganamaan baatu [yaadadhu]. Rabbiin dhagayaa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 122, 'Yeroo gareen lamaan isin irraa ta''an lunnoomuu yaadan [yaadadhaa]. Rabbiin gargaaraa isaan lamaaniiti. Mu’uminoonni Rabbi qofarratti haa irkatanii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 123, 'Dugumatti haala isin xiqqoo taataniin, (dirree) Badriitti Rabbiin isinii tumseera. Akka galateeffattaniif jecha Rabbiin sodaadhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 124, 'Yeroo ati mu’uminootaan [yaadadhaa]. “sila Gooftaan keessan maleeykota kuma sadii (samii irraa) buufamoota ta''aniin isin gargaaruun isinii hin ga''uu?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 125, 'Eeyyeen; yoo obsitaniifi Rabbiin sodaattan, yoo (mushrikoonnis) battaluma isaanii kanatti isinitti dhufan; Gooftaan keessan maleeykota mallatteeffamoo ta’an kuma shaniin isin gargaara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 126, 'Isin gammachiisuufi onneewwan keessan ittiin haa tasgabbooftuuf malee Rabbiin (waan biraatiif) isa hin taasifne. Tumsi Rabbii injifataa, ogeessa ta’e irraa malee hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 127, 'Isaan kafaran irraa garii muruuf (balleessuuf) yookiin isaan salphisuuf, Akka xiqqaatanii deebi’aniif (kana godhe).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 128, 'siif murtiin homaayyuu hin jiru, yooka Rabbiin toobaa isaanii qeebala yookiin isaan adaba, isaan miidhaa raawwattoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 129, 'Wantoonni samii keessa jiraniifi wantoonni dachii keessa jiran (hundi) kan Rabbiiti (Inni) nama fedheef ni araarama; nama fedhe immoo ni adaba Rabbiinis araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 130, 'Yaa warra amantan! dhala dachaalee dachaafamaa ta''e hin nyaatinaa, Akka milkooftaniif jechas Rabbiin sodaadhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 131, 'Ibidda kaafirootaaf qopheeffamte san sodaadhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 132, 'Akka mararfatamtaniif jecha Rabbiifi ergamichaaf ajajamaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 133, 'Gara araarama Gooftaa keessan irraa ta’eefi jarjaraa,(akkasuma gara) jannata bal’inni ishee akka samiifi dachii taateetti (jarjaraa) warra Rabbiin sodaataniif qophooftee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 134, '(Isaan) warra yeroo bal''innaafiifi rakkinaa arjooman; kan dallansuu liqimsaniifi namootaaf dhiifama godhaniidha. Rabbiin toltuu hojjattoota jaalata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 135, '(Isaan) warra yeroo waan fokkataa hojjatan yookiin lubbuulee isaanii miidhan Rabbiin yaadatanii, badiilee isaaniitiif araarama kadhataniifi Rabbiin malee kan badii araaramu hin jiru, haala (badii ta’uu isaa) beekaniin waan hojjatan irra hin turreedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 136, 'Isaan sun mindaan isaanii araarama Gooftaa isaanii biraa ta’eefi jannata laggeen ishee jala yaatuudha. Isaan ishee keessatti hafoodha. Mindaan hojjattootaa (jannata ta''uun) waa tole!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 137, 'Dhugumatti, isiniin dura karaaleen darbiteetti, Dachii keessa deemaatii booddeen (xumurri) kijibsiiftotaa akkam akka ta’e ilaalaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 138, 'Kun namootaaf ibsa; qajeelfamaafi warra (Rabbiin) sodaataniif gorsa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 139, 'hin laafinaa; hin gaddinaas isintu irra aanoodha Yoo mu’uminoota taatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 140, 'Yoo madaan isin tuqe, dhugumatti ummatas (diinotas) madaan fakkaataan isaan tuqeera. Guyyoota sana gidduu namaatti nanaannessina. Rabbiin isaan amanan beekuufi (addabaasuufi) isin irraas wareegamtoota taasifachuuf (kana godhe). Rabbiin miidhaa hojjattoota hin jaalatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 141, 'Rabbiin warra amanan qulqulleessuufi kaafiroota immoo balleessuf (kana godhe).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 142, 'Sila odoo Rabbiin isin irraa warra qabsaa’aniifi warra obsan hin hinbeekin (adda hinbaasin) jannata seenuu yaadduu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 143, 'Dhugumatti isin isa qunnamuu keessan dura du’a hawwaa turtan Dhugaatti (amma) kan laaltan taatanii isa argitaniittu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 144, 'Muhammad waa hintaane ergamaa dhugumatti ergamoonni isa dura dabran malee. Sila yoo inni du’e yookiin ajjeefame of duuba deebituu? Namni faana isaa irra of duuba deebi’e Rabbiin homaa hin miidhu. Rabbiin galateeffattootaaf galata galcha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 145, 'Lubbuu kamiifuu eeyyama Rabbiitiin ala du''uun isheef hin taane. Murtee barreefamaa (baallamamaa) (Rabbiin murteesseedha). Nama mindaa addunyaa fedhe ishee irraa isaaf kennina. Nama mindaa Aakhiraa fedhes, ishee irraa isaaf kennina. Galateeffattoota fuulduratti galata galchina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 146, 'Nabiyyoota irraa kan beektonni heddu isaa wajjin lolan baay''eedha, Waan karaa Rabbii keessatti isaan tuqeef hin laafne; hin dadhabnes; (diinaafis) hin jilbiiffanne, Rabbiin obsitoota jaallata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 147, 'Jechi isaanii waa hintaane jechuu malee “Gooftaa keenya! badii keenyaafi dhimmoota keenya keessatti daangaa dabriinsa keenya nuuf araarami; faana keenya gadi nudhaabi; ummata kaafirootaa irratti nu tumsi”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 148, 'Rabbiin mindaa addunyaatiifi gaarii mindaa Aakhiraa isaaniif kenne. Rabbiin toltuu hojjattoota ni jaalata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 149, 'Yaa warra amantan! Yoo warra kafaraniif ajajamtan faana keessan irra (of duuba) isin deebisan. hoonga’oota taatanii duubatti deebitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 150, 'Dhugaatti Rabbiin gargaaraa keessani, Inni irra caalaa tumsitootati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 151, 'onnee warra kafaranii keessatti fuulduratti sodaa darbina Waan isaan wantoota inni ragaa qabatamaa ittiin hin buusin Rabbitti qindeessaniif jecha, Teessoon isaanii ibiddaTeessoon miidhaa raawwattootaa waa fokkate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 152, 'Rabbiin waadaa Isaa isiniif dhugoomseera yeroo isin eeyyama Isaatiin isaan ajjeeftan. hanga yero isin lunnoomtanii ajaja keessattis wal dhabdanii, faallessitan (Rabbiinis isinii tumsuu dhiise), Erga (Rabbiin) waan jaalattan isin agarsiise baada, Isin irraa nama addunyaa fedhutu jira. Isin irraa nama Aakhiraa fedhutu jira. Ergasii isin qormaatuuf jecha isaan irraa isin deebise. Dhugumatti Rabbiin irra isiniif dabreera. Rabbiin mu’uminoota irratti abbaa tolaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 153, 'yeroo (baqaaf) tabba ol baatan [yaadadhaa] namtokkollee kan hin millanne, Odoo ergamaan duuba keessanii isin waamuu, gadda irraan gadda isinitti buuse, Akka isin waan isin jala dabreefi waan isin tuqe irratti hin gaddineef jecha Rabbiin waan isin dalagdan akkaan beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 154, 'Ergasii cinqaa booda tasgabbii, hirriba garee isin irraa ta’e haguugu, isin irratti buuse. Garee biraa immoo dhugumatti lubbuuleen isaanii isaan yaachifteetti. Waan dhugaa hin ta’in, yaada jaahiliyyaa, Rabbi irratti yaadu. “Sila nuti dhimmicha irraa qooda wahii qabnaa?” jedhu. (Yaa Muhammad!) jedhi: “Dhugumatti dhimmichi hundi isaatuu kan Rabbiiti." Waan siif hin mul’ifne lubbuulee isaanii keessatti dhoksu. “Odoo dhimmicha irraa waan tokko qabaannee silaa asitti hin ajjeefamnu turre” jedhu. Jedhi “odoma manneen keessan keessa taataniiyyuu, warri duuti isaan irratti barreeffame gara iddoo itti du’anii ni bahu turan." Rabbiin waan qomoota keessan keessa jiru qormaatuufi waan (badii) onneelee keessan keessa jiran mul''isuuf (kana godhe). Rabbiinis waan qomoota keessaa beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 155, 'Dhugumatti warri isin irraa guyyaa gareewwan lamaan wal qunnaman duubatti deebi’an, sababaa garii wantoota isaan hojjataniitiif kan isaan mucuceesse sheyxaanuma. Dhugumatti Rabbiin dhiifama isaaniif godheera. Rabbiin araaramaa, obsaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 156, 'Yaa warra amantan! akka warra kafaranii hin ta’inaa, kan obboleeyyan isaaniitiin, yeroo isaan dachii keessa deeman yookiin loltoota ta''an “odoo nu bira ta’anii silaa hin du’anu; hin ajjeefamanus” jedhanii. Rabbiin kana onneewwan isaanii keessatti gaabbii gochuuf (kana jedhan). Rabbiin ni jiraachisa; ni ajjeesas. Rabbiin waan isin dalagdan argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 157, 'Yoo karaa Rabbii keessatti ajjeefamtan yookiin duutan, araaramaafi rahmata Rabbi irraa ta’etu waan isaan walitti qaban irra caala.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 158, 'Yoo duutan yookiin ajjeefamtanis, dhugumatti isin garuma Rabbiitti walitti qabamtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 159, '(Yaa Muhammad!) rahmata Rabbi irraa ta’een isaaniif laafte, Odoo ati nama haala gadheefi qalbii gogaa taatee silaa si biraa faca’u, Irra isaaniif dabri; isaaniif araarama kadhu; dhimmoota (adda addaa) keessatti isaan mari’achiisi, Yeroo murattes Rabbirratti hirkadhu. Dhugumatti, Rabbiin warra (Isa) irratti hirkatan ni jaalata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 160, 'Yoo Rabbiin isin gargaare, injifataan isiniif hin jiru. Yoo Inni isin xiqqeesse immoo, inni booda isaatii isin gargaaru sun eenyu? Mu’uminoonni Rabbuma irratti haa hirkatanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 161, 'Nabiyyii kamiifuu (boojuu) dhokfachuun hin taane. Namni boojuu irraa miliqfate, Guyyaa Qiyaamaa waan miliqfate qabatee dhufa. Ergasii lubbuun hundi mindaa waan hojjattee guutuutti argatti. Isaan hin miidhamanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 162, 'Sila namni jaalala Rabbii hordofe akka nama dallansuu Rabbirraa taheen deebi’ee manni isaa jahannama taheetii? (miti) Deebiin isaa waa hammaate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 163, 'Isaan Rabbiin biratti sadarkaa adda addaa qabu. Rabbiinis waan isaan dalagan argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 164, 'Dhugumatti Rabbiin mu’uminoota irratti tola ooleera, yeroo ergamaa isaan irraa ta’e isaan keessatti ergu, kan keeyyattoota Isaa isaan irratti qara’u, kan (badii) irraas isaan qulqulleessu, kan kitaabaafi sunnaa (hikmaa) isaan barsiisu. Dhugaatti sana dura isaan jallina ifa bahaa keessa turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 165, 'Sila yeroma rakkoon isin mudatte kan isin fakkaataa ishee lama (injifannoo) argattan “kun eessaa nutti dhufe” jettuu? “Inni lubbuulee teessan biraayyi" jedhi. Dhugumatti, Rabbiin waan hunda irratti danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 166, 'Wanti guyyaa gareewwan lamaan wal qunnaman isin tuqe hayyamuma Rabbiitiini (Rabbiin) mu’uminootas (ittiin) ifa baasuuf (akkas godhe).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 167, 'Isaan munaafiqoomaniakka beekuufi (ifa baasuufi) kan isaaniin jedhame “kottaa; karaa Rabbii keessatti lolaa; yookiin ofirraa ittisaa”. nijedhan “nuti odoo lola beeknee silaa isin hordofna turre”. Isaan guyyaa san iimaana caalaa kufriitti irra dhihaatoodha. Waan onneelee isaanii keessa hin jirre afaanoowwan isaaniitiin jedhu. Rabbiin beekaa waan isaan dhoksaniiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 168, '(Isaan) warra taa’anii (duularraa hafanii) obboleeyyan isaaniitiin “odoo nuuf ajajamanii silaa hin ajjeefamanu turan” jedhaniidha. “Yoo kan dhugaa dubbattan taataniif du’a lubbuu keessan irraa deebisaa” jedhi', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 169, 'Warra karaa Rabbii keessatti ajjeefaman du’aatti hin yaadin. Dhugumatti isaan jiraatoodha Gooftaa isaanii biratti ni sooramu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 170, 'Isaan waan Rabbiin tola Isaa irraa isaaniif kenneen gammadoo ta''anii (sooramu). Warra isaan boodaa kan isaan hin dhaqqabiniin nigammachiifaman. waan sodaan isaan irra hin jirreefi isaanis hin gaddineef jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 171, 'nigammachiifaman qananiifi tola Rabbirraa ta’een. Rabbiin mindaa mu’umintootaa hin balleessuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 172, '(Isaan) warra erga madaan isaan tuqee booda Rabbiifi ergamaaf awwaataniidha. Isaan irraa warra toltuu hojjataniifi Rabbiin sodaataniif mindaa guddaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 173, '(Isaan) warra “Namoonni isiniif (isin waraanuuf) walitti qabanii jiruu sodaadhaa”namoonni isaaniin jennaan, iimaana isaaniif dabalee. “ga’aan keenya Rabbii, isarratti hirkachuun waatolee” jedhaniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 174, 'Ni’imaa Rabbi irraa ta’eefi tola isaatiin deebi’an, hamtuun isaan hintuqne, jaalala Rabbiiti hordofan. Rabbiin abbaa tola guddaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 175, 'Inni sun sheyxaana; jaalalloo isaa (isin) sodaachisaa, isaan hin sodaatinaatii anuma sodaadhaa yoo mu’umina taataniif .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 176, 'Isaan kufrii keessatti ariifatan si hin gaddisiisin. Isaan Rabbiin homaa hin miidhanu. Rabbiin akka isaaniif Aakhiratti qooda homaatuu hin taasifne fedha. Isaaniif azaaba guddaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 177, 'Dhugumatti isaan iimaanaan kufrii jijjiirratan, Rabbiin homaa hin miidhanu.isaaniif azaaba laalessaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 178, 'Warri kafaran (adabbii) isaaniif tursiisuun gaarii lubbuulee isaaniif ta''uu hin sehin. Kan Nuti isaaniif tursiifnuuf akka badii dabalataniif qofa. isaaniif adabbii xiqqeessaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 179, 'Rabbiin waan isin irra jirtan irratti kan mu’uminoota dhiisu hin taane Hanga fokkataa gaarii irraa adda baasutti, Rabbiin beekkomsa fagoo irratti kan isin mullisu (isin beeysisu) hin taane. Garuu Rabbiin ergamtoota Isaa irraa nama fedhe filata. Rabbiifi ergamaa Isaatti amanaa. Yoo amantanii (Rabbiin) sodaattan, galata guddaatu isiniif jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 180, 'Warri waan Rabbiin tola Isaa irraa isaaniif kenneen don’oomanu inni isaaniif gaarii ta''uu hin yaadin. Dhugumatti inni isaaniif hamaadha. Fuulduratti wanti isaan ittiin don’ooman Guyyaa Qiyaamaa (bofa ta’ee) isaanitti fannifama. Dhaalli samiileefi dachii kanuma Rabbiiti. Rabbiin waan isin dalagdan beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 181, 'Dhugumatti Rabbiin jecha warra “Rabbiin hiyyeessa; nuti dureeyyiidha” jedhanii dhagayeera. Waan isaan jedhaniifi ajjeechaa isaan nabiyyoota irratti haqaan ala raawwatanis ni barreessina. “Adaba (ibidda) gubaa dhandhamaa” isaaniin jenna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 182, 'Sun sababaa waan harkoowwan keessan dabarfatteefi, Rabbiin gabroota kan miidhu hintaane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 183, '(Isaan) warra jedhani “akka ergamaa kamittiyyuu hin amanne Rabbiin nu ajajeera, hanga inni kennaa (qurbaana) ibiddi nyaattuun nutti dhufutti”. jdhi “Dhugumatti ana dura ergamtoonni ragoota ifa ta’aniifi isa isin jettaniinis isinitti dhufanii jiru. maaliif isaan ajjeeftan? Yoo kan dhugaa jettan taataniif”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 184, 'Yoo si kijibsiisaniif, ergamtoonni si duraa kijibsiifamanii jiru, kan ragoota ifa ta’an, xalayaafi kitaaba ibsaa ta''een dhufan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 185, 'Lubbuun hundi du’a dhandhamtuudha, Mindaawwan keessan guutummaatti kan kennamtan Guyyaa Qiyaamati. Namni ibidda irraa fageeffamee jannata seensifame, dhugumatti milkaayeera. Jireenyi addunyaa waa hintaane meeshaa daguu malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 186, 'Isin dhugumatti ni qormaatamtu qabeenyaalee keessaniifi lubbuulee keessan keessatti, Warra isin dura kitaabni kennameef irraafi warra (Rabbitti) qindeessan irraayis rakkisaa baay’ee dhageessu, Yoo obsitanii, (Rabbiin) sodaattan, dhugumatti kun gocha cimaa irraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 187, 'Yeroo Rabbiin warra kitaaba kennaman irraa waadaa kakuun jabeeffame fuudhe [yaadadhu] “namootaaf akka isa ibsitan; akka isa hin dhoksine” (jedheenii). Isaan garuu dugda duuba isaaniitti isa darbani. gatii xiqqaattis isa gurguratan. Wanti isaan bitatan waa fokkate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 188, 'Warra waan hojjatanitti gammadanii, waan hin dalagin irratti galateeffatamuu jaalatan (nagaya bahan) hin sehin; adabbii irraa baraaramuu isaaniis hin sehin. Isaaniif adabbii laalessaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 189, 'Mootummaan samiileefii dachii kan Rabbiiti. Rabbiin waan hunda irratti danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 190, 'Uumuu samiileefi dachii; wal bakka bu’uu halkaniifi guyyaa keessa warra sammuu qabaniif mallattooleetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 191, '(Isaan) warra dhaabatanii, taa’anii, cinaachoowwan isaanii irrattis Rabbiin faarsanii, uumama samiileefi dachii keessattis xiinxalaniidha, “yaa Gooftaa keenya! Ati kana taphaaf hin uumne, qulqulloofte, adabbii ibiddaa irraas nu baraarsi" jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 192, '(Ammas) "Gooftaa keenya! Ati nama ibidda seensifte, dhugumatti isa salphiftee jirta. Miidhaa hojjattootaaf gargaaraan hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 193, 'Gooftaa keenya! dhugumatti nuti lallabaa ‘Gooftaa keessanitti amanaa’ jechuun iimaanaaf lallabu dhageenyee amannee jirra, Gooftaa keenya! badiilee keenya nuuf araarami; hamtuuwwan keenya nurraa harcaasi; warra qulqulluu wajjin nu ajjeesi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 194, 'Gooftaa keenya! Waan ergamtoota kee irratti waadaa nuuf seente nuuf kenni. Guyyaa Qiyaamaa nu hin salphisin. Dhugumatti Ati waadaa hin faallessitu" (jedhaa xiinxalanii dha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 195, 'Gooftaan isaanii isaaniif awwaate “Ani dalagaa dalagataa isin irraa tahee kan dhiiraas ta’ee dhalaa hin balleessu, Gariin keessan garii irraayyi" (jedhe). Isaannan godaananii; manneen isaanii irraa baafamanii, karaa kiyya keessatti rakkifamanii, fi lolaniifi ajjeefaman, dhugumatti hamtuuwwan isaanii isaan irraa harcaasa, jannatoowwan laggeen jala ishee yaatu isaan seensisa. Mindaa Rabbiin biraa ta’e (mindeffaman). Rabbiin isa bira mindaa gaariitu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 196, 'Dachii keessa garagaggaluun warra kafaranii si hin gowwoomsin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 197, '(Kun) qananii muraasa, Ergasii teesson isaanii jahannami, Afatichi waa hammaatee!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 198, 'Garuu isaan Gooftaa isaanii sodaatan isaaniif ashaakiltiilee laggeen ishee jala yaatutu jira, ishee keessatti hafoodha. Affeerraa Rabbiin biraa ta’e (affeeraman). Waan Rabbin biraatu qulqullootaaf caalaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 199, 'Warra kitaabaa irraa warra Rabbiitti amanantu jiru, waan gara keessanitti buufameefi waan gara isaaniitti buufamettis. Rabbiif of gadi qaban, Keeyyattoota Rabbii maallaqa xiqqaan hin jijjiirratan. Warri sun isaaniif mindaan isaanii Gooftaa isaanii bira jira. Dhugumatti, Rabbiin daddafsiisaa qormaataati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 200, 'Yaa warra amantan! Obsaa; obsaan (diinota keessan) injifadhaa; karaa Rabbii keessattis of hidhaa.[1] Rabbiin sodaadhaa Akka milkooftaniif.', '[1] dirree lolaatti kaarra eegaa yookaa wardiyyaa dhaabbadhaa.jechuudha.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 1, 'Yaa namootaa! Gooftaa keessan sodaadhaa, Isa lubbuu takka (Aadam) irraa isin uumee, ishee irraa cimdii ishee (Hawwaa) uumee, isaan lamaan irraa dhiirotaafi dubartoota baay’ee tamsaase. Rabbii isa ittiin wal kadhattaniifi firummaa (muruu) sodaadhaa. Dhugumatti, Rabbiin isin to’ataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 2, 'Yatiimotaaf qabeenyaalee isaanii kennaa. Gaggaarii gadheedhaan hin jijjiiratinaa. Qabeenya isaanii gara qabeenya keessaniitti (makuun) hin nyaatinaa. Dhugumatti inni badii guddaa ta''eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 3, 'Yoo yatiimota (fuuchuu) keessatti wal hin qixxeessinuu sodaattan, dubartoota irraa isaan isinitti bareedan lama lama, sadi sadi, afur afur fuudhaa. Yoo wal hin qixxeessinuu sodaattan immoo tokkittii (fuudhaa); yookiin waan (gabrittii) harki keessan horatte (fuudhaa). Haqa dabsuu dhabuuf Kanatu irra dhihoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 4, 'Dubartootaaf mahriiwwan isaanii kenna jaalalaan ta''e kennaafii. Yoo isaan jaalala lubbuu isaaniitiin isa irraa isiniif kennan, halaala gaarii haala ta''een isa nyaadhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 5, 'Qabeenyaalee keessan kan Rabbiin dhaabbata (jireenyaa) isiniif taasise gowwootatti hin kenninaa. Ishee irraas soorata isaaniif kennaa; isaan uffisaas, jechoota beekamaas isaaniin jedhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 6, 'Yatiimota hanga isaan umrii gaa''ilaa ga’anitti qoradhaa. Yoo isaan irraa qajeeluma argitan, qabeenyaalee isaanii gara isaaniitti deebisaa. (Sodaa) guddachuu isaanii ariifatoo taatanii balleessuuf jecha ishee hin nyaatinaa. Namni dureessa ta’e, (irraa) of haa qabu. Namni hiyyeessa ta’e immoo beekamaadhaan haa nyaatu.Yeroo qabeenya isaanii gara isaaniitti deebiftan isaan irratti ragaa godhaa. qorataa tahuuf Rabbiinuu gahaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 7, 'Dhiirotaaf Waan haadhaa abbaafi firoonni dhiisan irraa qoodatu jira. Dubartootaafis waan haadhaa abbaafi firoonni dhiisan irraa qoodatu jira. Waan isa irraa xiqqaateefi guddate irraas; Qooda murteeffamaa (Rabbiin isa qoodeera).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 8, 'Yeroo firoonni, yatiimonniifi hiyyeeyyiin (bakka) qoodaa dhufan isa irraa isaaniif kennaa; jecha gaariis isaaniin jedhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 9, 'Warri odoo duuba isaaniitti ilmaan dadhaboo dhiisaanii (du''anii) isaan irratti sodaatanu, (yatiima miidhuu) haa sodaatanu. Rabbiin sodaatanii jecha haqaa haa jedhanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 10, 'Dhugumatti isaan qabeenyaalee yatiimotaa miidhuudhaan nyaatan, wanti isaan garaalee isaanii keessatti gadi nyaatanu ibidduma. Fuulduratti ibidda boba’aa seenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 11, 'Rabbiin (dhaalmaya) ilmaanii keessan keessatti isiniif dhaama. Dhiiraaf fakkaataa qooda durba lamaatu jira. Yoo dubartii lamaafi sanaa ol ta’an, lama sadaffaa waan inni dhiiseetu isaaniif jira. Yoo takka qofa taate walakkaatu isheef jira. Yoo isaaf (nama du’eef) ilmaan jiraate, abbaafi haadha isaatiif waan inni dhiise irraa tokko tokkoon isaaniitiif tokko jahaffaatu jira. Yoo ilmi isaaf hin jiraatin, abbaafi haati isaa isa dhaalan, haadha isaatiif tokko sadaffaatu jira. Yoo obboleeyyan isaaf jiraatan immoo haadha isaatiif tokko jahaffaatu jira. (Kun hundinuu kan qoodamu) booda dhaamsa inni dhaammate yookiin dayniitiiyyi. Abbootiin keessaniifi ilmaan keessan eenyuu isaaniitu bu''aa isiniif buusuutti irra dhihoodhaa hin beektan. Murtii Rabbi irraa ta''e (Rabbiin murteesseera). Rabbiin beekaa, ogeessa ta''e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 12, 'walakkaa waan haati manaa keessanii dhiisaniitu isiniif jira. Yoo ilmoon isaaniif hin jiraatin Yoo ilmoon isaaniif jiraate immoo tokko arfaffaa waan isaan dhiisaniitu isiniif jira (Kun) booda dhaamsa isaan dhaammatanii yookiin dayniitiiyyi. Yoo ilmoon isiniif hin jiraatin tokko arfaffaa waan isin dhiiftaniitu isaaniifis jira. Yoo ilmoon isiniif jiraate immoo tokko saddeetaffaa waan isin dhiiftaniitu isaaniif jira. (Kun) booda dhaamsa isin dhaammatanii yookiin dayniitiiyyi. Haala obboleessa yookiin obboleettii qabuun yoo dhiirri kan abbaa haadhaafi ilmaan hin qabne ta''ee dhaalamu argame yookiin dubartiinis tokko tokkoon isaaniitiif tokko jahaffaatu jira. Yoo sanaa ol ta''an immoo isaan tokko sadaffaa keessatti hirmaattota. (Kun) haala miidhamuun hin argaminiin booda dhaamsa dhaamamtee yookiin dayniitiiyyi. Dhaamsa Rabbi irraa ta’e (isiniif dhaame) Rabbiin beekaa, obsaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 13, 'Isheen kun daangawwan Rabbiiti. Namni Rabbiifi ergamaa Isaatiif ajajame jannattoota jala ishee laggeen yaatu keessatti hafoo ta''anii isaan seensisa.Kun milkii guddaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 14, 'Namni Rabbiifi ergamaa Isaa faallessee, daangaawwan Isaas dabre kan ishee keessatti hafu ta''ee (Rabbiin) ibidda isa seensisa. Isaafis adabbii xiqqeessaa ta’etu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 15, 'Dubartoota keessan irraas isaan hojii fokkataa (qunnamtii seeraan alaa) raawwatan, namoota afur kan isin irraa ta’an isaan irratti ragaa baasaa. Yoo isaan ragaa ba’an hanga duuti isaanitti dhufutti yookiin (hanga) Rabbiin karaa (biraa) isaanii godhutti manneen keessatti isaan qabaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 16, 'Isin irraa namoonni lamaan (dhiiraafi dubartii) sagaagalummaa hojjatan isaan lamaanuu akkaan rakkisaa. Yoo isaan tawbatanii hojii gaarii hojjatan, isaan (rakkisuu) irraa gara galaa. Dhugumatti, Rabbiin akkaan tawbaa qeebalaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 17, 'Tawbaan qeebaltiin isii Rabbirratti taate warra wallaalumaan hamtuu hojjatanii ergasii dhihootti tawbataniifi, Warra san Rabbiin tawbaa isaanii irraa qeebala, Rabbiinis beekaa, ogeessa ta''eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 18, 'Tawbaan hintaane warra badiilee hojjatanii hanga tokkoon isaaniitti duuti dhufutti "ani amma tawbadhe" jedhaniifi. isaannan kaafiroota ta’anii du’aniifis (qeebalamtuu hin taane). Warra san Nuti azaaba laalessaa isaaniif qopheessinee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 19, 'Isin Yaa warra amantan! dubartii dirqamaan dhaaluun isiniif hin eeyyamamu.garii waan (mahrii) isaaniif kennitanii fudhachuuf (heeruma) isaan hin dhorginaa, Yoo balleessaa mul''ataa taheen dhufan (hojjatan) malee; Akkaataa gaariin isaan horadhaa. Yoo isaan jibbitan (obsaa); waan tokko isin jibbitanii Rabbiin isa keessa khayrii baay’ee godhuun ni kajeelama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 20, 'yoo niitii tokko bakka ishee biraa jijjiirrachuu barbaaddan Haala tokkoo isaaniitiif (tan hiikuu barbaaddaniif) qabeenya guddaa kennitanii jirtanuun, isa irraa homaa hin fudhatinaa. Sila haala miidhaafi dilii ifaa ta’ee jiruun fudhattuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 21, 'Sila akkamitti isa (mahrii isheef kennitan) fudhattu? bifa gariin keessan gara garii ga''ee jiruun kan isaanis isin irraa waadaa jabaafi ulfaataa fudhatanii jiranuun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 22, 'Dubartoota irraa isaan abbootiin keessan fuudhan hin fuudhinaa. waan dabre malee, Dhugumatti inni fokkataa, jibbamaafi karaan isaa hamaa ta''ee jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 23, 'Haadholeen keessan (fuudhuun) isinirratti haraama godhamte, dubarri keessans, obboleettiwwan keessans, adaadowwan keessans, haboowwan (obboleettii haadhaa) keessans, shamarran obboleessaas, shamarran obboleettiis, haadholeen keessan kan isin hoosisanis, obboleettiiwwan keessan kanneen hoosisa irraa ta’anis, haadholee niitiiwwan keessaniis, shamarran isin guddiftanii gola keessan keessa jiran kan niitiiwwan keessan itti seentan irraa dhalatanis (fuuchuun isin irratti haraama godhamteetti); yoo isaan irra kan hin seenne taatan immoo badiin isin irra hin jiru. Niitiiwwan ilmaan keessan kanneen dugdoowwan keessan irraa ta''anis, jidduu obboleettiiwwan lamaa walitti qabuunis (akkasuma haraama).waan dabre malee. Dhugumatti Rabbiin araaramaa, rahmata godhaa tahee jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 24, 'Dubartoota irraayis isaan (dhiiraan) tikfaman kan harki keessan dhuunfatte malee (dhorgamaa dha). Heera Rabbiin isin irratti murteesse (qabadhaa)Warra kanneeniin ala jiran of tiksaa sagaagalummaa irraa fagaataa taatanii qabeenya keessaniin barbaaduun isiniif eeyyamameeraIsaan irraa (warra qunnamtii saalaa waliin raawwachuun) ittiin qananiitan mahriiwwan isaanii haala dirqama ta''een isaanii kennaaWaan erga mahriin murtaa’ee booda ittiin wal jaalattan keessa badiin isin irra hin jiruDhugumatti Rabbiin beekaa, ogeessa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 25, 'Isin irraa namni (dubartoota) tikfamoo mu’umina ta’an fuuchuu qabeenyaan hin danda’in, shamarran keessan kan mu’uminaa kan harki keessan dhuunfatte (gabroottan) irraa (haa fuudhanu). Rabbiin iimaana keessan beekaadha. Gariin keessan garii irraayyi. Eeyyama warra isaaniitiin isaan fuudhaa. Mahrii isaanii haala gaarii ta’een isaaniif kennaa. Tikfamtoota ta''anii, sagaagalummaa kan hin raawwanneefi kan hiriyaa dhiiraa hin qabne ta''anii (fuudhaa). Yoo yeroo heeruman hojii fokkataa raawwatan, adabbii irraa walakkaa kan isaan walaba ta’an irra jiruutu isaan irra jira. Kun isin irraa nama zinaa sodaateefi; obsuutu immoo isiniif caala. Rabbiin araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 26, 'Rabbiin (waan eeyyamamaafi dhorgamaa ta’an) isiniif ibsuu barbaada, karaalee warra isin dura turanii isin qajeelchuufi tawbaa keessan qeebaluu (barbaada). Rabbiin beekaa, ogeessasi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 27, 'Rabbiin tawbaa keessan qeebaluu fedha. Warri fedha lubbuu isaanii hordofan immoo isin jallina guddaa jallachuu fedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 28, 'Rabbiin isin irraa salphisuu fedha. Ilmi namaa dadhabaa ta’ee uumame.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 29, 'Yaa warra amantan! qabeenya keessan gidduu keessanitti kijibaan hin nyaatinaa, Yoo daldala jaalala keessan irraa taateen tahe malee, Lubbuulee keessan hin ajjeesinaa. Dhugumatti Rabbiin isin mararfataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 30, 'Namni daangaa dabruufi miidhaaf kana dalage, fuulduratti ibidda isa seensifna. Kun Rabbirratti salphaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 31, 'Yoo badii gugurdoo irraa dhoowwamtantanirraa fagaattan, badiilee (xixiqqaa) keessan isin irraa haqna, seensa kabajaa isin seensifna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 32, 'Wantoota Rabbiin garii keessan garii irra ittiin caalchise hin hawwinaa. Dhiirotaaf qooda waan isaan hojjatan irraa ta’etu jira. Dubartootaafis qooda waan isaan hojjatan irraa ta’etu jira. Rabbiin tola Isaa irraa kadhaa. Dhugumatti Rabbiin waan hunda beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 33, 'Hunda isaaniitiif (dhiiraafi dubartiif) waan abbaa haatiniifi firoonni dhiisan irraa dhaala taasifnee jirra. Isaan kakuun keessan (firummaan) hiites qooda isaanii isaaniif kennaa. Dhugumatti Rabbiin waan hunda irratti ragaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 34, 'Dhiironni dhimma dubartootatiin dhaabbatoodha; (kunis) waan Rabbiin garii isaanii garii irra caalchiseefi, qabeenyaalee isaanii irraas waan kennaniifi. Dubartoonni gaggaariin (Rabbiifi dhirsa isaaniitiif) ajajamoodha; fagoottis waan Rabbiin isaan eegsise tiksitoota. Isaan finciluu isaanii sodaattan immoo isaan gorsaa; (itti aansun) ciisa keessatti isaaniin oodaa; (dhuma irratti yoo sirraa''uu didan) isaan tumaa. Yoo isaan isiniin ajajaman isaan irratti karaa hin barbaadinaa. Dhugumatti Rabbiin ol ta’aa, guddaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 35, 'Yoo gidduu isaan lamaaniitti waldhabbii beektan araarsaa tokko warra isaa irraa, araarsaa tokko immoo warra ishee irraa ergaa. Yoo isaan lamaan araara fedhan, Rabbiin gidduu isaani waliigalcha. Dhugumatti Rabbiin beekaa, keessa beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 36, 'Rabbiin gabbaraa; Isatti homaa hin qindeessinaas. Abbaa haadhatti tola oolaa, firootaafs, yatiimotaafs, hiyyeeyyiifs, ollaa firooma qabuufs, ollaa firooma hin qabneefs, hiriyaa maddii keessan jiruufis, kara deemaafis, (gabroota) mirgi keessan dhuunfateefis (tola oolaa). Dhugumatti Rabbiin nama boonaa dhaaddataa ta’e hin jaalatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 37, 'Isaannan donnoomanii, namootas donnummatti ajajaniifi waan Rabbiin tola Isaa irraa isaaniif kenne dhoksan (hin jaalatu). Kaafirootaaf adabbii salphisaa qopheessinee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 38, 'Isaannan qabeenya isaanii akka namoonni isaan arganuuf arjooman, kan Rabbiifi Guyyaa Aakhiraattis hin amanne, (isaan hiriyoota sheyxaanati). Namni sheyxaanni hiriyaa isaaf ta’e, hiriyummaan isaa waa fokkate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 39, 'Sila odoo Rabbiifi Guyyaa Aakhiraatti amananiifi waan Rabbiin isaaniif kenne irraa kennatanii maaltu isaan irra jira? Rabbiin isaan beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 40, 'Dhugumatti Rabbiin hanga madaala atomii tokkoo hin miidhu, Yoo isheen dalagaa gaarii taate dachaa ishee taasisa; mindaa guddaa Isa biraa ta’es (dabalaan) ni kenna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 41, 'Sila yeroo Nuti ummata hunda irraa ragaa fidneefi sillee warra kana irratti ragaa goonee si fidne (haalli isaanii) akkam ta’a?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 42, 'Guyyaa san warri kafaraniifi ergamicha faallessan odoo dachiin isaan irratti wal qixxaattee jaalatu. Isaani haasawa Rabbiin hindhoksan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 43, 'Yaa warra amantan! salaatatti hin dhihaatinaa Haala machaahaa taataniin hanga waan dubbattanu beektanitti, yoo janaabawoo taatanis hanga dhiqattanutti, karaa dabraaf malee. yoo dhukkubsattootaa taatan, yookaa imala irra jiraattan, yookiin tokkoon keessan mana fincaaniitii (iddoo itti udaanuu) dhufe. yookiin dubartootaan wal tuqxanii bishaan dhabdan biyyee qulqulluun tayammumadhaa; fuulleen keessaniifi harkoowwan keessan haxaa’aa. Rabbiin irra dabraa araaramaa tahee jira. [1]', '[1] kuni laaffisiinsa islaamaati garsiisa. namni tokko yoo bishaan dhabe yookaa dhukkubsatee bishaanitti fauuadamuu dadhabe biyyeen tayamuma godhatee salaata.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 44, 'Sila gara warra kitaaba irraa qoodni isaaniif kennamee hin ilaallee? (Isaan) jallina bitu; isin karaa jallachuus ni barbaadu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 45, 'Rabbiin diinota keessan beekaadha. Eegumsaaf Rabbiin qofti ga’aa dha! Tumsaafis Rabbiin qofti ga’aadha', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 46, 'Isaan yahuudoman irraa (warra) jechoota iddoo isaanii (kan sirrii) irraa jijjiirantu jira. Ni jedhus: “dhageenye; faallessines. Dhagayamuun maletti dhaga''i." Arraboowwan isaanii micciiruufi amantii arrabsuuf jecha ''raa’inaa'' jedhu. Odoo isaan “nuti dhageenye; toles jenne; atis dhagayi; nu mil’adhus (unzurnaa)” jedhanii, silaa santu isaaniif caalaafi sirrii ture. Garuu Rabbiin sababaa kufrii isaanitiin isaan abaare. Kanaaf isaan xiqqoo malee hin amananu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 47, 'isin Yaa warra kitaaba kennamtan! waan nuti buufne kan isa isin biraa dhugoomsutti amanaa, odoo nuti fuulleen haqnee duuba isheerratti hin deebisin yookiin akka warra sanbataa abaarretti hin abaarin dura (amanaa). Ajajni Rabbii raawwatamaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 48, 'Dhugumatti Rabbiin Isatti waa qindeeffamuu hin araaramu. Waan sanaa gadii nama fedheef ni araarama. Namni Rabbitti qindeesse dhugumatti cubbuu guddaa kijibaan uumeera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 49, 'Sila gara isaan lubbuulee isaanii qulqulleessanii hin ilaallee? Lakki; Rabbiin nama fedhe (qofa) qulqulleessa. Hanga kirrii qola Timiraa hin miidhamanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 50, 'Akkamitti akka isaan Rabbirratti kijiba odeessan ilaali. Cubbuu ifa bahaa ta’uuf inninuu ga’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 51, 'Sila gara warra kitaaba irraa qooda kennamanii hin ilaallee? Isaan sihriifi xaaghuutatti amanu. Isaan kafaraniin ni jedhu: “Warra kanatu isaan amanan (Muslimoota) caalaa karaa qajeelaadha."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 52, 'Isaan Warra Rabbiin isaan abaare. Nama Rabbiin abaare gargaaraa isaaf hin argitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 53, 'Sila mootummaa irraa qoodni isaaniif jira moo? Yoggus hanga tuqaa (ija (killee) timiraa irra jiru) namaaf hin kennanu ture.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 54, 'Moo sila waan Rabbiin tola Isaa irraa namootaaf kenne irratti isaan waanyu? Dhugumatti Nuti maatii Ibraahiimiif kitaabaafi ogummaa kenninee jirra. Mootummaa guddaas isaaniif kenninee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 55, 'Isaan irraa nama isatti (Muhammaditti) amanetu jira. Isaan irraas nama isa irraa garagalee (namas irraa dhoowweetu) jira. Gubaatii (isaaniitiif) jahannam ga’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 56, 'Dhugumatti warra keeyyattoota keenyatti kafaran, Nuti ibidda isaan seensifna. Dhawaata gogaaleen isaanii gubatuun,gogaalee isheen alaa isaaniif jijjiirra, akka isaan adabbii dhandhamaniif jecha. Dhugumatti Rabbiin injifataa'' ogeessa ta''e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 57, 'Isaannan amananii gaggaarii hojjatan, Nuti jannata laggeen ishee jala yaatu isaan seensifna. Ishee keessatti yeroo hunda hafoodha. Achi keessa isaaniif niitiiwwan qulqulleeffamtuutu jiru. Gaaddisa gaaddiddeessaas isaan seensifna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 58, 'Dhugumatti, Rabbiin amaanawwan gara abbootii isiitti geessuufi yeroo nama gidduutti murteessitanis haqaan murteessuu isin ajaja. Dhugumatti, wanti Rabbiin ittiin isin gorsu (barsiisu) waa tolee. Rabbiin dhagayaa, argaa ta''e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 59, 'Yaa warra amantan! Rabbiif ajajamaa; ergamichaafi warra isin irraa abbootii taaytaa ta’aniifis ajajamaa. Yoo waan tokko keessatti wal mormitan, gara Rabbiifi ergamaa (Isaa) deebisaa; yoo Rabbiifi Guyyaa Aakhiraatti kan amantan taatan (gara san deebisaa). Kun caalaafi hiikaafis bareedaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 60, 'Sila gara warra waan gara keetti buufameefi waan si dura buufametti amanne jedhanii hin ilaallee? Odoo isatti kafaruu ajajamanii jiranuu gara xaaghuutaatti murteeffachuu barbaadu. Sheyxaanni jallina fagoo ta’e isaan jallisuu fedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 61, 'Yeroo “gara waan Rabbiin buuseefi gara Ergamaa kottaa” isaaniin jedhame, kan munaafiqoonni gara galiinsa sirraa gara galan argita.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 62, 'akkam ta’u laata? yeroo balaan sababaa waan harkoowan isaanii durfatteen isaan tuqee, ergasii Rabbitti kakataa “nuti toltuufi wal ta’iinsa malee waan biraa hin feene” (jedhaa) sitti dhufan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 63, 'Isaan warra waan onneewwan isaanii keessa jiru Rabbiin beekuudha.Isaan irraa gara gali. Isaan gorsi. Jecha hoonga gahaa lubbuu isaanii keessatti isaaniin jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 64, 'Nuti ergamaa irraa akka eeyyama Rabbiitiin ajajni isaa fudhatamuuf malee hin ergine. Odoo isaan yeroo lubbuu isaanii miidhan, sitti dhufanii Rabbiin araara kadhataniifi Ergamaanis araara isaaniif kadhatee, silaa Rabbiin araaramaa, rahmata godhaa ta’eeti argatu turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 65, 'Lakki; Rabbii keetiinin kakadhaa! isaan hin amananu hanga waan gidduu isaaniitti irratti wal dhaban keessatti si murteessisaniitti, ergasii waan ati murteessite irratti odoo lubbuulee isaanii keessatti dhiphina hin argin fudhannaa (garaa guutuu ta’een) fudhatanitti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 66, 'Odoo Nuti isaan irratti “Lubbuu keessan ajjeesaa yookiin manneen keessan irraa ba’aa” (jennee) katabnee silaa warra muraasa isaan irraa ta’an malee (baay’een isaanii) isa hin dalaganu. Odoo isaan waan itti gorfaman kana dalaganii silaa sanatu isaaniif caalaadha. Akkaan (amantii isaanii) raggaasisas ture.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 67, 'Silaa yeroo san dhugumatti nu biraa mindaa guddaa isaaniif kennina turre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 68, 'Silaa dhugumatti karaa sirraawaa isaan qajeelchina turre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 69, 'Namni Rabbiifi Ergamaadhaaf ajajame isaan sun warra Rabbiin qanansiise waliin ta’u, nabiyyoota, dhugoomsitoota, shahiidotaafi warren gaggaarii (wajji tahu). Warra kanaan hiriyoomuun waa tole!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 70, 'Tolli kun Rabbi irraayyi, Rabbiin gayaadha beekaa tahutti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 71, 'Yaa warra amantan! Of eeggannoo keessan qabadhaa. Gareen duulaa yookiin dimshaashan duulaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 72, 'Dhugumatti, isin irraa nama (duula irraa) duubatti jedhutu jira. Kanaaf yoo balaan wahii isin tuqxe “Dhugumatti, Rabbiin na qananiisee jira. yeroo akka ani isaan waliin (duula irratti) argamu hin taasisin " jedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 73, 'Yoo tolli Rabbirraa ta''e wahii isin tuqe immoo -silaa dhugumatti inni akka waan gidduu keessaniifi gidduu isaa jaalalli wahii hin turinii- “yaa hawwii kiyya! Odoo isaan waliin ta’ee, silaa milkii guddaa milkaaya ture” jedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 74, '(Mu’uminoonni) isaan jireenya addunyaa isa Aakhiraatti gurguratan karaa Rabbii keessatti haa lolani.Namni karaa Rabbii keessatti lolee ergasii ajjeefame yookiin injifate, Nuti ganaa mindaa guddaa isaaf kennina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 75, 'Sila maaltu isiniif jiraatee karaa Rabbii keessatti, kan hinlolle? kan warri dadhaboo dhiirota, dubartoota, ijoollee irraa ta’an, jedhan “Gooftaa keenya! Magaalattii jiraattonni ishee miidhaa raawwattoota ta''an kana irraa nu baasi; gargaaraa Si biraa ta’es nuuf taasisi; tumsaa Si biraa ta’es nuuf taasisi” (jedhaniif jettanii hin lolle?)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 76, 'Warri amanan karaa Rabbii keessatti lolu. Isaan kafaran immoo karaa xaaghuutaa keessatti lolu. jaalalleewwan sheyxaanatiin lolaa. Dhugumatti tooftaan sheyxaanaa dadhabaa ta''e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 77, 'Sila gara isaan harka keessan (lola irraa) qabadhaa; salaatas gadi dhaabaa; zakaas kennaa jedhamanii hin ilaallee? Yeroma lolli dirqama isaan irratti taasifamu yoma san gareen isaan irraa ta’e sodaa akka Rabbiin sodaatanii yookiin sodaa san caalu namoota sodaatan. “Yaa Gooftaa keenya! Maaliif lola dirqama nurratti taasifte? Odoo yeroo gabaabaa nu tursiiftee (maal qaba)?” jedhan. Jedi “Qananiin addunyaa xiqqaadha; Aakhiraan nama (Rabbiin) sodaatuuf caalaadha. Hanga qajjiisaa (qola killee) Timiraa hin miidhamtan" .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 78, '“Eessallee yoo taatan duuti isin dhaqqaba. Odoo gamoowwan ciccimoo keessa taatanillee (isin irraa hin hafu). Yoo toltuun wahii isaan tuqu immoo “kun Rabbiin biraayi” jedhu. Yoo hamtuun wahii isaan tuqu immoo “(yaa Muhammad!) kun si biraayi" jedhu. “Hunduu Rabbiin biraayyi" jedhi. Ummanni kun maaltu isaaniif jiraayyi dubbii homaayyuu hubachuutti hin dhihaanne?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 79, 'Toltuu irraa wanti si tuqe kamillee Rabbirraayyi. Hamtuu irraa wanti si tuqe kamillee lubbuu kee irraayi. Namootaaf ergamaa taasifneetiin si ergine. Ragummaaf Rabbiin qofti ga’adha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 80, 'Namni ergamichaan tole jedhe dhugaatti Rabbiin tole jedhe. Nama gara gale immoo isaan irratti eegaa taasifnee si hin ergine', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 81, '(Yaanni keenya siif) ajajamuudha” jedhu. Yeroo si biraa bahan, gareen isaan irraa taate faallaa waan dura jettee bulfatan. Rabbiin waan isaan bulfatan ni barreessa. Isaan irraa gara gali; Rabbi irratti irkadhu. Irkoo ta’uu irratti Rabbiin ga’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 82, 'Sila isaan Qur’aana hin xiinxalanuu? Odoo Rabbi malee kan biroo biraa ta’ee, silaa isa keessatti wal dhabbii baay’ee argu turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 83, 'Yeroo tasgabbii yookiin sodaa irraa dhimmi wahii isaaniitti dhufe, (namoota keessatti) isa facaasu. Odoo gara Ergamaatiifi gara abbootii taaytaa isaan irraa ta’anii isa deebisanii, silaa isaan irraa warri isa qoratan (xiinxalan) isa beeku turan. Odoo ni’imaan Rabbiitiifi rahmanni Isaa isin irra jiraachuu baatee, silaa isin muraasa (keessan) malee sheyxaana hordoftu turtan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 84, 'Karaa Rabbii keessattis loli; lubbuu kee malee hin dirqisiifamtu. Mu’uminootas kakaasi. Rabbiin rakkoo warra kafaranii (sirraa) qabuun ni kajeelama. Gama lolaatiin Rabbitu irra cimaadha; jiilchaanis irra cimaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 85, 'Namni araarama gaarii araarse, ishee irraa qoodni (mindaan) isaaf ta’a. Namni araarama gadhee araarses, ishee irraa qoodni (hamaan) isaaf ta’a. Rabbiin waan hunda irratti danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 86, 'Yeroo kabajaa wahiitiin kabajamtan,(salaamataan isiniin jedhame) ishee irra gaariidhaan kabajaa; yookiin isuma deebisaa. Dhugumatti, Rabbiin waan hunda irratti qorataadha', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 87, 'Rabbiin dhugaan gabbaramaan isa malee hin jiru. Dhugumatti, Guyyaa Qiyaamaa keessa walitti isin qaba; isa keessa mamiin hin jiru. Eenyutu Rabbiin caalaa haasa’a dhugaa dubbata?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 88, 'Sila maaltu isiniif jiraannaan dhimma munaafiqootaa keessatti garee lamatti qoodamtan?odoo Rabbiin sababaa waan isaan hojjataniitiin duuba isaan deebisee jiruu, Sila isin nama Rabbiin jallise qajeelchuu barbaadduu? nama Rabbiin jallise karaa (ittiin qajeelu) isaaf hin argitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 89, 'Odoo isin akkuma isaan kafaran kafartanii isaan waliin wal qixa taatanii jaalatu. Hanga karaa Rabbii keessatti godaananitti isaan irraa jaalallee hin qabatinaa. Yoo isaan gara galan, isaan qabaatii bakka argitanitti isaan ajjeesaa.Isaan irraas jaalalleefi gargaaraa hin godhatinaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 90, 'Warra hidhata qaban malee orma jidduu keessaniifi gidduu isaaniitti walii galteen (nagaa) jiru wajjin. yookiin kanneen qomni isaanii isiniin loluu irraa dhiphattee, orma isaaniitiinis lolurraa (dhiphattee) isinitti dhufan malee. Rabbiin odoo fedhee isaan isin irratti ol taasisee isiniin lolu turan. Yoo isaan isin irraa fagaatanii isin hin loliniifi nagaa isiniif kennan Rabbiin (akka loltan) isaan irratti karaa isiniif hin goone.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 91, 'Warra biraas kan tasgabbii isin irraafi tasgabbii ummata isaanii irraa barbaadan fuuldura ni argitu. Dhawaata gara shirkiitti deebifamaniin ishee keessa cuuphamu. Yoo isaan isin irraa hin fagaatin, nagaa gara keessan hin dhaqqabsiisiniifi harkoowwan isaanii hin qabin, isaan qabaa, bakka isaan argitanitti isaan ajjeesaa. Warra kana, Nuti isaan irratti (lola akka deemsiftan) ragaa ifa ta’e isiniif goonee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 92, 'Mu’umina ajjeesuun Mu’uminaaf hin ta''u.Yoo dogoggoraan ta’e malee, Namni mu’umina dogoggoraan ajjeese, gabra mu’uminaa bilisoomsuufi ''diyaa'' (gumaa dhiigaa) gara maatii isaa (nama du’ee) kennamutu (baasuun isarra jira) yoo isaan (maatiin nama ajjeefamee) dhiifama godhaniif malee. Yoo inni (namni ajjeefame) haala mu’umina ta’een ummata diinota keessan irraa ta’ee gabra mu’uminaa bilisoomsuutu irra jira. Yoo inni ummata gidduu keessaniifi gidduu isaanii walii galteen (nagaa) jiru irraa ta’e, gumaa dhiigaa gara maatii isaa kennamuufi gabra mu’uminaa bilisoomsuutu (isarra jira). Namni (gabra bilisoomsu) hin argatin ji’a lama walitti aantuu soomuutu (irra jira). Tawbaa Rabbi irraa ta''e (haa toobatu). Rabbiin beekaa, ogeessa ta''eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 93, 'Namni odoo beekuu mu’umina ajjeese, galanni isaa, jahannami achi keessatti hafa,Rabbiin isa irratti dallanee, isa abaaree jiraa. azaaba guddaa isaaf qopheesse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 94, 'Yaa warra amantan! Yeroo karaa Rabbii keessa deemtan (dubbii) adda baafadhaa. nama salaamtaa isiniin jedheen “ati Mu’uminaa miti" hin jedhinaa, meeshaa addunyaa barbaaduuf, Boojuun baay’een Rabbi bira jirtii, Duraan isinis akkasuma turtanii Rabbiin isin irratti tola oolee. dubbii adda baafadhaa. Rabbiin waan isin hojjattan keessa beekaa ta''eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 95, 'Mu’uminoota irraa warri (jihaada irraa) taa’an, warra miidhama qaban malee, warra qabeenyaaleefi lubbuulee isaaniitiin karaa Rabbii keessatti qabsaa’aniin wal qixa hin ta’anu. Rabbiin warra qabeenyaaleefi lubbuulee isaaniitiin qabsaa’an isaan taa’an irra sadarkaa caalchisee jira. Rabbiin hundaafuu jannata waadaa seeneefii jira. Rabbiin warra qabsaa’an isaan taa’an irra mindaa guddaan caalchisee jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 96, 'Sadarkaawwan Isa irraa ta’an, araaramaafi rahmataan (isaan caalchise). Raabbiin araaramaa, rahmata godhaa ta''eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 97, 'Warri haala lubbuu isaanii miidhoo ta''aniin malaykaan isaan ajjeefte, (malaykonni) “maaluma keessa turtan?” jedhan. “Dachii keessatti hacuucamoo turre” jedhu, “Sila dachiin Rabbii bal’oo hin taanee akka ishee keessa godaantaniif?” jedhan. Jarri sun qubsumni isaanii jahannami, Deebiin waa hammaatte!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 98, 'Isaan dadhaboo malee. dhiiraa, dubartootaafi ijoollee irraakan ta’an, kan mala baafachuu hin dandeenyeefi karaa hin qajeelle (deemsa hindandeenye) (malee).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 99, 'Warra kana Rabbiin irra isaaniif dabruun nikajeelama. Rabbiin akkaan irra dabraa, akkaan araaramaa ta''eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 100, 'Namni karaa Rabbii keessatti godaane, dachii keessatti iddoo godaansaa hedduufi bal''ina argata. Namni mana isaa irraa gara Rabbiitiifi ergamaa Isaa godaanuuf ba’ee ergasii duuti isa dhaqqabe, dhugumatti mindaan isaa Rabbiratti isaa mirkanaa’e, Rabbiin araaramaa, rahmata godhaa ta''eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 101, 'Yeroo dachii keessa deemtan,badiin homaatuu isin irra hin jiru salaata irraa gabaabsuu keessaniin, yoo warri kafaran isin rakkisuu sodaattan, Dhugumatti, kaafiroonni isiniif diinota mul''ataa ta''aniiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 102, 'Yeroo isaan keessa jiraattee salaata isaaniin dhaabde, gareen isaan irraa taate takka si waliin haa dhaabbattuu; meeshaalee isaaniis haa qabatanu, Yeroo sujuudanii ka''an, duuba keessan irraan haa ta''anu. Gareen biraa isaan hin salaatin dhufanii sii waliin haa salaatanu. Of eeggannoo isaaniifi meeshaa isaaniis haa qabatanu. Warri kafaran odoo isin meeshaa waraanaa keessaniifii meeshaa keessan irraa dagattanii dabiinsa tokkicha isin irratti dabanii jaalatu. Yoo rakkoon bokkaa irraa ta''e isin mudate yookiin dhukkubsataa taatan meeshaalee lolaa keessan lafa kaayachuun badiin isin irra hin jiru. Of eeggannoo keessan qabadhaa. Dhugumatti, Rabbiin kaafirootaaf azaaba salphisaa qopheessee jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 103, 'Yeroo salaata raawwattan, dhaabbataa, taa''aafi cinaachoowwan keessan irra haala taataniin Rabbiin faarsaa. Yeroo tasgabbooftan salaata dhaabaa. Dhugumatti, salaanni mu’uminoota irratti dirqama yeroon isaa murtaa’e ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 104, 'Ummata (diinaa) barbaacha keessatti hin laafinaa; Yoo kan laalattan taatan isaanis akkuma isin laalattanitti laalatu, Rabbi irraa waan isaan hin kajeelle kajeeltu. Rabbiin beekaa, ogeessa ta''eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 105, 'Nuti kitaabicha haqaan gara keetti buufnee jirra, akka waan Rabbiin sitti agarsiiseen gidduu namootaatti murteessituuf jecha. Gantootaaf falmaa hin ta''in.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 106, 'Rabbiin araarama kadhu. Dhugumatti Rabbiin akkaan araaramaa, akkaan rahmata godhaa ta''eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 107, 'Isaan lubbuulee isaanii ganan irraas hin falmin. Dhugumatti Rabbiin nama akkaan ganaa dilaawaa ta’e hin jaalatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 108, 'Nama irraa ni dhokatu;Rabbi irraa hin dhokatanu, inni yeroo isaan jecha irraa waan inni hin jaalanne bulfatan isaanii wajjin jira. Rabbiin waan isaan dalagan (beekumsa Isaatiin) marsaa ta''eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 109, 'Dhaga''aa! Isin warri kun jireenya addunyaa keessatti isaan irraa falmitanii, Guyyaa Qiyaamaa immoo eenyutu isaan irraa falma? Yookiin eenyutu isaan irratti tiksaa ta''a?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 110, 'Namni hamtuu hojjatee yookiin lubbuu isaa miidhee ergasii Rabbiin araarama kadhate, Rabbiin araaramaa, rahmata godhaa ta’uu arga.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 111, 'Namni badii oomishes, kan inni isa oomishu lubbuma isaa irratti. Rabbiin beekaa, ogeessa ta''eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 112, 'Namni dogoggora yookiin badii oomishee ergasii nama qulqulluu isaan darbate (arrabse), inni dhugumatti cubbuufi badii ifa ta’e baateera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 113, 'Odoo tolli Rabbiitiifi rahmanni Isaa sirra jiraachuu baatee, silaa gareen isaan irraa taate tokko si jallisuuf yaaddeetti. Lubbuulee isaanii malee homaa hin jallisanu. Homaa si hin miidhanus. Rabbiin kitaaba (Qur’aanaa)fi ogummaa (hadiisa) sirratti buuse; waan ati kabeektu hintahin si barsiise, Tolli Rabbiin sirratti oolu guddaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 114, 'hedduu maqoo isaanii keessa toltuun hin jiru.Nama sadaqaatti yookiin gaggaaritti yookiin gidduu namaa araarsutti ajaje malee, Namni jaalala Rabbii barbaaduuf kana hojjate, fuulduratti galata guddaa isaaf kennina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 115, 'Namni erga qajeelloon ifa isaaf ta’ee booda ergamicha faallesseefi karaa mu’uminootaa kantahin hordofe, waan inni moo''e (jallina) irratti isa moosifna; jahannamiinis isa seensifna. Deebittiin waa fokkattee!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 116, 'Dhugumatti Rabbiin Isatti qindeeffamuu hin araaramu. Waan sanaa gadii nama fedheef ni araarama. Namni Rabbitti qindeesse dhugumatti jallina fagoo ta’e jallateera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 117, 'Isaa (Rabbii) gaditti dhaltuuwwan malee homaa hin gabbaranu; shayxaana darbamaa malees homaa hin gabbaranu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 118, 'Rabbiin isa abaareera. Innis ni jedhe: “Ani gabroota kee irraa qooda murtaa’e nan qabadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 119, 'Isaanis nan jallisa; isaan nan hawwisiisas; isaanis nan ajajaa gurra beeyladaa ni tarsaasu; isaan nan ajajaa uumama Rabbii ni jijjiiru." Namni Rabbiin malee sheyxaana jaalallee godhate, inni dhugumatti hoongoo ifa ta’e hoonga’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 120, 'Isaaniif waadaa seena; isaanis ni hawwisiisa. Shayxaanni gowwoomsaa malee isaaniif waadaa hin galu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 121, 'Warri sun qubsumni isaanii jahannami; ishee irraa gara itti dabanis hin argatanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 122, 'Isaannan amananii, gaggaarii hojjatan, jannata laggeen ishee jala yaatu isaan seensifna. Yeroo hunda achi keessatti hafu. Rabbiin waadaa seenee dhugaa isa godhe. Namni dubbiidhaan Rabbirra dhugaa eenyu? (Hin jiru).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 123, 'Hawwii keessaniifi hawwii abbootii kitaabaatiin hin taane; namni hamtuu hojjate isaan mindeeffama; Rabbii gaditti jaalalleefi gargaaraas isaaf hin argu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 124, 'Dhiiraafi dhalaa irraa namni mu’umina ta’ee hojii gaggaarii hojjate, isaan sun jannata seenu; hanga tuqaa temiraas hin miidhamanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 125, 'Eenyutu irra tole amanatiin nama haala bareechaa ta''een fuula isaa Rabbiif bulchee caalaa? kan amantii Ibraahiim qajeelaa haala ta''een hordofe. Rabbiin Ibraahiimiin jaalallee godhateera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 126, 'Wantoonni samiifi dachii keessa jiran (hundi) kan Rabbiiti. Rabbiin waan hundatti (beekumsaan) marsaa ta''e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 127, 'Waa''ee dubartootaa keessatti si gaafatu jedhi "Waa''ee isaanii keessatti Rabbiin isiniif ibsa, Wanti kitaaba keessatti isin irratti dubbifamutu. waa''ee dubartoota yatiimaa keessatti kan isin waan isaaniif barreeffame isaaniif hin kenninefi isaan fuuchuu jibbitaniifi dadhabdoota ijoollee irraa ta''aniifi yatiimotaafis haqaan dhaabbachuu (Rabbiin isiniif ibsa). Toltuu irraa waan isin hojjattan kamillee dhugumatti Rabbiin isa beekaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 128, 'Yoo dubartiin tokko dhirsa ishee jibbaa yookiin irraa gara galiinsa sodaatte, gidduu isaaniitti walii galtee uumuun badiin isaan irra hin jiru.araaratu caala. Lubbuuleen don’ummaa kennamte. Yoo tolchitanii (badii irraa) eeggattan, dhugumatti Rabbiin waan isin hojjattan (hunda) keessa beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 129, 'Odoma bololtaniillee gidduu dubartootaa wal qixxeessuu hin dandeessanu; (Gara ishee tokkoo) dabiinsa hunda dabdanii (ishee kaan) akka rarraafamtuutti hin dhiisinaa. Yoo tolchitanii (Rabbiin) sodaattan, dhugumatti Rabbiin araaramaa, rahmata godhaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 130, 'Yoo isaan lameen adda ba’an, Rabbiin hundaayyuu tola Isaa irraa ni duroomsa. Rabbiin (kenni isaa) bal''aa, ogeessa ta''eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 131, 'Wantoonni samii keessaafi wantoonni dachii keessaa kan Rabbiiti. Dhugumatti warra isin dura kitaaba kennamaniifi isiniifis Rabbiin sodaadhaa jechuu dhaamnee jirra. Yoo kafartan Wantoonni samiilee keessaafi wantoonni dachii keessaa kan Rabbiiti. Rabbiin dureessa, faarfamaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 132, 'Wantoonni samiifi dachii keessaa hundi kan Rabbiiti. Hirkoodhaaf Rabbiin ga’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 133, 'isin Yaa namootaa! (Rabbiin) yoo fedhe isin deemsisee warra biraa fida. Rabbiin kana irratti danda’aa ta''eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 134, 'Namni mindaa addunyaa kan fedhu ta''e, mindaan addunyaafi Aakhiraa Rabbiin bira qofa jira. Rabbiin dhaga’aa, argaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 135, 'isin Yaa warra amantan! haqaan dhaabbattoota Rabbiif ragaalee ta’aa odoma lubbuu keessan yookiin abbaa haadha keessaniifi firoota keessan irrattis ta’eeyyuu. Yoo dureessa yookiin hiyyeessa ta’e Rabbitu irra isaanitti aana. Haqa irraa dabuuf fedha lubbuu keessanii hin hordofinaa. Yoo (ragaa) dabsitan yookiin (ragaa bahuu irraa) gara galtan, dhugumatti Rabbiin waan isin dalagdan hunda beekaa ta''eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 136, 'isin Yaa warra amantan! Rabbitti amanaa, ergamaa Isaattis, kitaaba ergamaa Isaa irratti buufamettis kitaaba Inni sana dura buusettis (amanaa). Namni Rabbitti kafare maleeykota Isaattis, kitaabota Isaattis, ergamtoota Isaattis,ifi Guyyaa Aakhiraatti (kafare), inni dhugumatti jallina fagoo jallateera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 137, 'Dhugumatti isaan amananii ergasii kafaran, ergasii amananii ergasii kafaran, ergasiis kufrii daddabalatan, Rabbiin kan isaaniif araaramuufi kan karaa isaan qajeelchu hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 138, 'munaafiqoota gammachiisi. Adabni laalessaan isaaniif jira jechuudhaan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 139, '(Isaan) warra mu’uminootaa gaditti kaafiroota jaalallee godhataniidha. Sila jabeenya isaan bira barbaaduu? Dhugumatti, jabeenyi hundi kan Rabbiiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 140, 'Dhugumatti, kitaaba keessatti (Rabbiin) isin irratti buuseera “yeroo keeyyattoota Rabbii kan isaanitti kafaramuufi isaanitti qoofamu dhageessan,isaan waliin hin taa’inaa hanga isaan haasa’a biraa keessa seenanitti ” jechuun. Yoos isinis fakkaattota isaaniiti. Dhugumatti, Rabbiin munaafiqootaafi kaafiroota jahannam keessatti walitti qabaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 141, '(Isaan) warra hamtuu isinitti eeganuudha. Yoo injifannoon Rabbi irraa isiniif ta’e “nuti isinii wajjiin hin turree?” jedhu. Yoo carraan kaafirootaf ta’e immoo “sila nuti isin irratti akkaan hin hoggannee? Mu’uminoota isin irraa hin dhorginee?” jedhu. Rabbiin Guyyaa Qiyaamaa gidduu keessanitti ni murteessa. Rabbiin kaafirootaaf mu’uminoota irratti karaa hin godhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 142, 'Dhugumatti munaafiqoonni Rabbiin ganu. Innis (mindaa dalagaa isaaniitiif) ganaa isaaniiti. Yeroo gara salaataa ka''anis, taatiyaahaa (hifataa) dhaabbatu, nama argisiifatan . Xiqqoo malee Rabbiin hin faarsanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 143, 'Gidduu kanatti dhama''oo ta''anii gara isaan kanaas miti; gara isaan sanaas miti. Nama Rabbiin jallise, karaa (qajeelumaa) isaaf hin argitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 144, 'isin Yaa warra amantan! Mu’uminootaa gaditti kaafiroota jaalallee hin taasifatinaa. Sila isin irratti Rabbiif ragaa ifa ta’e taasisuu feetuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 145, 'Dhugumatti, munaafiqoonni ibidda irraa sadarkaa gadii keessa ta''u. Tumsaas isaaniif hin argitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 146, 'Isaan tawbatanii, tolchanii, Rabbiin qabataniifi amantii isaanii Rabbiif qulqulleessan malee. Warri kun mu’uminoota waliin ta’u. Rabbiinis mu’uminootaaf mindaa guddaa ni kenna', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 147, 'Yoo isin (Isa) galateeffattanii (Isatti) amantan Rabbiin adabbii keessan irraa maal godha? Rabbiin galateeffataa, beekaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 148, 'Yoo nama miidhame ta’e malee Rabbiin jecha irraa hamaa ifa baasuu hin jaalatu. Rabbiinis dhagayaa, beekaa ta''eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 149, 'Yoo toltuu ifa gootan yookiin isa dhoksitan yookiin hamtuu irraa dhiifama gootan, dhugumatti Rabbiin akkaan dhiifama godhaa, danda’aa ta''eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 150, 'Dhugumatti, isaan Rabbiifi ergamtoota Isaatti kafaran, gidduu Rabbiitiifi ergamtoota Isaa adda baasuu fedhan, “garii Isaatti ni amanna; garii Isaatti ni kafarra” jedhan, gidduu sanitti karaa godhachuu fedhan,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 151, 'Isaan warra dhugaan kafaraniidha, kaafirootaaf azaaba xiqqeessaa qopheessinee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 152, 'Isaan Rabbiifi ergamtoota Isaattis amanan, gidduu tokkoon isaan irraa ta''ees adda hin baasin, isaan san (Rabbiin) mindaa isaanii isaaniif kenna. Rabbiin araaramaa, rahmata godhaa ta''eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 153, 'Abbootiin kitaabaa samii irraa kitaaba isaan irratti buusuu si gaafatu. Muusaas waan kana irra guddaa gaafataniiru. “Rabbiin ifatti nu agarsiisi” jedhani. Sababaa miidhaa isaaniitiin gaggabbiin (duuti) isaan qabde. Sana booda erga ragaawwan isaanitti dhufanii jibicha (gabbaramaa) godhatan. Sanas irra isaaniif dabrine. Muusaaf ragaa ifa ta’e kennine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 154, 'Waadaa isaan galchuuf gaara isaan irratti ol kaafnee, “sujuuda godhaa balbalicha seenaa” isaaniin jenne, “Sanbata keessattis daangaa hin tarinaa" isaaniin jenne, Waadaa ulfaataa isaan irraa fuune.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 155, 'Sababa isaan waadaa isaanii diiguutiin, keeyyattoota Rabbiitti kafaruutiin, nabiyyoota haqaan ala ajjeesuu isaaniitiifi “onneen keenya haguugamtee jirti” jechuu isaaniitiin (isaan abaarre). Dhugumatti Rabbiin sababaa kufrii isaaniitiif ishee (onnee isaanii) irratti haguuge; muraasa malee hin amananu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 156, 'Sababaa kufrii isaaniitiifi Maryam irratti kijiba guddaa odeessuu isaanitiif (isaan abaarre).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 157, 'Ammas waan isaan “nuti Masiih Iisaa ilma Maryam, ergamaa Rabbii, ajjeefnee jirra” jedhaniif (isaan abaarre), Isaaniitti fakkeeffame malee isa hin ajjeefne; hin fannisnes, Dhugumatti, isaan isa keessatti wal dhaban isa irraa shakkii keessa jiru, sehaa hordofuu malee isa irratti beekumsa homaatuu hin qaban, Qabatamaatti isaan isa hin ajjeefne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 158, 'Dhugumatti Rabbiin gara isaatti ol isa fuudhe. Rabbiin injifataa, ogeessa ta''e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 159, 'Abbootiin kitaabaa kamillee odoo hin du''in dura isatti amanu malee hin hafu, Guyyaa Qiyaamaa isaan irratti ragaa ta’a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 160, 'Sababaa miidhaa warra yahuudomaniifi gaggaarii halaala isaaniif ta’ee ture haraama isaan irratti taasifne, sababaa isaan (namoota) baay’ee karaa Rabbii irraa deebisaniif .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 161, 'Dhalas odoo dhugumaan irraa dhorgamanii jiranuu fudhachuu isaaniitiin, horii namaa karaa malee waan nyaataniif (isaan abaarre), Kaafiroota isaan irraa ta''aniif adabbii laalessaa qopheessineerra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 162, 'Garuu isaan irraa warri beekumsa gadi fagoo qabaniifi mu’uminoonni waan gara keetti bu’eefi waan si dura bu’etti ni amanu; warra salaata dhaabanin (faarsa). Warri zakaa kennaniifi, Rabbiifi Guyyaa Aakhiraattis amanan, isaan sana mindaa guddaa isaaniif kennina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 163, 'Nuti gara keetti beeksisa goonee jirra akkuma gara Nuuhiifi nabiyyoota isa boodatti beeksisa goone, Gara Ibraahiim, Ismaa’iil, Isihaaq, Ya’aquub, asbaax (ilmaan Ya’aquub), Iisaa, Ayyuub, Yuunus, Haaruuniifi Suleymaanittis beeksisa goonee jirra. Daawuudiif ‘Zabuur’ kennineerra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 164, 'Ergamtoota san dura seenaa isaanii siif himneefi kan seenaa isaanii siif hin himiniis (erginee jirra). Rabbiin Muusaa haasofsiise haasofsiinsa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 165, 'Gammachiisoofi dinniinoo taasifnee ergamtoota (ergine.), Akka Ergamtoota booda Rabbi irratti namaaf ragaan hin argamneef Rabbiin injifataa, ogeessa.tahee jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 166, 'Garuu Rabbiin waan gara keetti buuse irratti ragaa ba’a, Beekumsa Isaatiin isa buuse, Malaa’ikoonnis ragaa ba’u, Ragaadhaaf Rabbiin ga’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 167, 'Dhugumatti, warri kafaranii karaa Rabbii irraa (namoota) deebisan, dhugumatti isaan jallina fagoo ta’e jallataniiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 168, 'Dhugumatti, isaan kafaranii miidhaa hojjatan, Rabbiin kan isaaniif araaramuufi karaa isaan qajeelchu hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 169, 'karaa jahannam malee, ishee keessa zalaalam jiraatoodha, Kun Rabbi irratti laafaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 170, 'isin Yaa namootaa! Dhugumatti, ergamaan Gooftaa keessan irraa ta’ee dhugaan isinitti dhufeeraa; isatti amanaa caalaa isiniif (ta''aa). Yoo kafartan, wantoonni samiifi dachii keessaa kan Rabbiiti. Rabbiin beekaa, ogeessa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 171, 'Yaa abbootii kitaabaa! amantii keessan keessatti daangaa hin dabrinaa; Rabbi irrattis dhugaa malee hin haasa’inaa. Ilmi Maryam, Masiih, Iisaan ergamaa Rabbiiti; jecha Isaa (ta''i jedhu) kan Inni gara Maryam darbeedha. Ruuhii (uumaa) isaa irraa ta''eedha. Rabbiifi ergamtoota Isaattis amanaa. “Rabbiin sadihi” hin jedhina. Isarraa dhorgamaa; isiniif caalaa (ta''aa). Rabbiin dhugaan gabbaramaa tokkicha qofa. Inni ilmi Isaaf ta’uu irraa qulqullaa’e. Wantoonni samiilee keessaafi wantoonni dachii keessaa kan Isaati. Hirkoodhaaf Rabbiin qofti ga’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 172, 'Masiih Rabbiif gabricha ta’uu irraa hin nuffu; Malaa’ikoonni dhihoonis (hin nuffanu). Namni Isa gabbaruu irraa nuffeefi boone, Inni hunda isaanii gara Isaatti walitti isaan qaba.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 173, 'Isaannan amananiifi gaggaarii hojjatan, mindaalee isaanii isaaniif guuta,Tola Isaa irraas isaaniif dabala. Isaannan nuffaniifi boonan adabbii laalessaa isaan adaba. Isaaniifi Rabbii gaditti jaalallees ta’ee tumsaa hin argatanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 174, 'isin Yaa namootaa! Dhugumatti ragaan Gooftaa keessan irraa ta''e isinitti dhufeera. Ifa mul’ataa gara keessanitti buufnee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 175, 'Isaannan Rabbitti amananii, Isa qabatan immoo, fuulduratti rahmata Isa irraa ta’eefi tola keessa isaan seensisa. Gara isaatti karaa qajeelaa isaan qajeelcha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 176, 'Si gaafatu, Jedhi: “Rabbiin waa''ee ‘kalaalah’ (nama jalaafi gubbaan kan isa dhaalu hin qabne) keessatti isiniif ibsa. Yoo namtichi du''e kan ilmi isaaf hintahin kan obboleettiin isaaf taate, isheedhaaf walakkaa waan inni dhiisetu jira. Innis yoo isheen ilma hin qabaatin ishee dhaala. Yoo isaan (obboleettiiwwan) lama ta’an, isaaniif dhaala inni dhiise irraa lama sadaffaatu jira. Yoo obbolaan dhiirotaafi dubartoota ta''an immoo dhiiraaf fakkii qooda dubartii lamaatu jira. Rabbiin akka isin hin jallanneef isiniif ibsa. Rabbiin waan hunda beekaadha."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 1, 'Isin Yaa warra amantan! Waadaa guutaa; beelladoonni isiniif halaala godhamteetti wanti isin irratti dubbifamu qofti odoo hafuu. (Hajjiifi umraa) kan hidhattan taatanii adamsuu halaala haala hin godhatiniin. Rabbiin waan fedhe murteessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 2, 'Yaa warra amantan! Mallattoolee Rabbii,halaala hin godhatinaa, ji''a kabajamos, horii wareegaaf dhufanis, horii (wareega hajjiitiif) morma isaanii irratti mallattoon fannifames,fi warra tolaafi jaalala Gooftaa isaanii barbaacha gara mana kabajamaa fedhanuus (halaala hin godhatinaa). Yeroo ihraama (hajjii yookiin umraa) raawwattan adamsadhaa. Waan masjida kabajamaa irraa isin deebisaniif jibbaan ummata (Makkaa) daangaa dabruutti isin hin kakaasin. Toltuufi sodaa Rabbii irratti wal gargaaraa. Badiifi daangaa dabruu irratti wal hin gargaarinaa. Rabbiin sodaadhaa, Dhugumatti Rabbiin adabbiin isaa akkaan cimaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 3, 'Isinirratti haraama godhamte Baktiin, dhiignis, foon booyyees, waan (maqaan) Rabbiin alaa isa irratti ol fuudhames, hudhamtee tan duutes, tumamtee tan duutes, konkolaattee tan duutes, tan gaafaan waraanamtee duutes, wanti bineensi nyaates waan (odoo inni hin du’in dura dhaqqabtanii) gorraatan malee, wanti taabota irratti gorra’ames, xiyyaan carraa ilaallachuunis, (isin irratti haraama godhamteetti). Kuni fincila, Har''a warri kafaran amantii keessan irraa abdii muratanii jiru. Isaan hin sodaatinaa; Anuma (qofa) sodaadhaa. Har''a Amantii keessan isiniif guuteera, ni’imaawwan kiyyas isin irratti guuteera. Amantiis Islaama isiniif jaaladheera. Namni beela keessatti rakkifame, kan gara badii hindabin (isaaf dhiifama). Rabbiin araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 4, 'Maaltu akka isaaniif halaal tahe si gaafatu. "Gaggaariin (hunduu), halaal isiniif tahe, wanti isin leenjiftoota taatanii carraaqxota irraas barsiiftan kan waan Rabbiin isin barsiise irraa barsiiftan,(isiniif hayyamameera). Waan isaan isiniif qaban irraa nyaadhaa. Maqaa Rabbiis isa irratti dubbadhaa. Rabbiin sodaadhaa. Dhugumatti, Rabbiin qormaanni (Isaa) saffisaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 5, 'Har''a gaggaariin hundi isiniif eeyyamameera. Nyaanni abbootii kitaabaas isiniif eeyyamamaadha. Nyaanni keessanis isaaniif hayyamamaadha. Tikfattoonni dubartoota mu’uminoota irraa ta’aniifi tikfattoonni dubartoota warra isiniin dura kitaaba kennaman irraa ta''anii fuudhoo, kan sagaagala hin dalagneefi sanyoo (jaalallee dhoksaa) hin qabanne taatanii (isiniif eeyyamama). Namni iimaana irraa gara gale, dhugumatti dalagaan isaa bade. Inni Aakhiraatti warra hoonga’an irraa ta’a', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 6, 'Yaa warra amantan! Yeroo salaataaf kaatan, fuulleen keessan dhiqadhaa, harkoowwan keessanis hanga ciqileetti, (dhiqadhaa). Mataawwan keessaniis haxaa''aa; Lukkeen keessanis hanga koronyoo lameeniitti (dhiqaa). Yoo janaabawoo taatan (bishaan saalaa isin irraa dhangala’e) qulqulleeffadhaa (dhiqadhaa). Yoo dhukkubsatoo taatan yookiin imala irra jiraattan yookiin tokkoon keessan mana fincaanii irraa dhufe, yookiin yoo dubartiin wal tuqxanii (qunnamtii saalaa gootanii), ergasii bishaan hin argatin dachii (biyyee) qulqulluu barbaaddadhaa (tayammuma godhadhaa). Isa irraas fuulleen keessaniifi harkoowwan keessan haxaa''aa. Rabbiin rakkina tokkollee isin irra fiduu hin fedhu. Garuu isin qulquleessuufi ni’imaa Isaa isin iraatti guutuu fedha, akka isin galateeffattaniif jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 7, 'Yaadadhaa ni''imaa Rabbii kan isin irra jiru, waadaa Isaa kan yeroo isin "dhageenye; awwaannes" jettan Inni isiniif gales yaadadhaa. Rabbiin sodaadhaa. Dhugumatti, Rabbiin beekaa waan qomoowwan keessaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 8, 'Yaa warra amantan! Rabbiif gadi dhaabbataa ta’aa; haqaan ragaa ba’aa ta''aa. Jibbaan ummataa haqa dalaguu dhiisuu irratti isin hin kakaasin. Haqa hojjadhaa; isatu sodaa Rabbiitti irra dhihoodha. Rabbiin sodaadhaa. Dhugumatti, Rabbiin waan isin hojjattan hunda beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 9, 'Rabbiin isaan amananii gaggaarii hojjatan, isaaniif araaramaafi mindaa guddaatu jira (jechuun) waadaa seeneera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 10, 'Isaan kafaranii keeyyattoota keenyas sobsiisan, isaan warra ibiddaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 11, 'Yaa warra amantan! Ni’imaa Rabbii kan isin irratti tahe yaadadhaa, yeroo ‘ummanni harkoowwan isaanii gara keessan diriirsuu yaadanii, (Rabbiin) harkoowwan isaanii isin irraa qabe’ (yaadadhaa). Rabbiin sodaadhaa. Mu’uminoonni Rabbi irratti haa irkatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 12, 'Dhugumatti, Rabbiin waadaa Ilmaan Israa’iil qabee jira. Isaan irraas qondaalota kudha lama kaafnee jirra. Rabbiin "Ani isin waliinin jira, Yoo isin salaata dhaabdanii zakaa kennitanii, ergamoota kiyyatti amantanii, isaan gargaartanii, Rabbiif liqaa bareedaa liqeessitan, dhugumatti Ani hamtuuwwan keessan isin irraa harcaaseeti, Jannata laggeen ishee jala yaatu isin seensisa. Isin irraa namni san booda kafare, inni dhugumatti karaa qajeelaa irraa jallateera" jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 13, 'Sababaa isaan waadaa isaanii diiganiif, isaan abaarree, onneewwan isaaniis gogduu taasifne, Iddoowwan isaanii (kan sirrii) irraa jechoota jijjiiru, Waan ittiin gorfaman irraa qooda wahii dagatan. Isaan irraa nama muraasa malee gantuu isaan irraa taate arguurraa hin deemtu. Dhiifama isaaniif godhi; irras dabri. Dhugumatti, Rabbiin tolchitoota jaalata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 14, 'Isaan nuti Kiristaanota jedhan irraallee waadaa isaanii fuunee, waan ittiin gorfaman irraa qooda wahii dagatan. Hanga Guyyaa Qiyaamatti gidduu isaanitti diinummaafi jibbaa buufne. Rabbiin waan isaan dalagaa turan fuula dura isaanitti hima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 15, 'Yaa warra kitaabaa!Dhugumatti, Ergamaan keenya isinitti dhufeera, kan irra hedduu kitaabaa irraa waan isin dhoksaa turtan isiniif ibsuufi baay’ee isaa immoo dhiifamaan irra isiniif dabru. iftaanifi kitaabni mul''ataan Rabbi irraa isiniif dhufeera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 16, 'Rabbiin nama jaalala Isaa hordofe isaan (kitabdichaan) karaa nagaa qajeelcha, Dukkanoowwan irraa gara ifaatti eeyyama Isaatiin isaan baasa. Gara karaa sirriitti isaan qajeelcha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 17, 'Warri “Rabbiin isumatu Masiih ilma Maryami” jedhan dhugumatti kafaraniiru. Jedhi: " sila eenyutu Rabbi irraa tiksa? yoo Inni Masiih ilma Maryam, haadha isaatiifi namoota dachii irra jiran hunda balleesuu fedhe " Mootummaan samii, dachiifi wantoota gidduu isaan lamaanii jiran hundaatuu kan Rabbiiti. Waan fedhe uuma. Rabbiin waan hunda irratti danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 18, 'Yahuudonniifi Kiristaanonni "nuti ilmaan Rabbiitiifi jaalalleewwan Isaati" jedhan. (Ati) jedhi: " maaliif badiilee keessaniin isin adaba? Dhugumatti isin nama Inni uume irraayi. (Inni) nama fedheef ni araarama; nama fedhe immoo ni adaba. Mootummaan samii, dachiifi wantoota gidduu isaan lamaanii kan Rabbiiti. Deebiin garuma Isaatti" (jedhi).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 19, 'Yaa abbootii kitaabaa!ergamaan keenya kan (waan hunda) ifa isiniif taasisu, eega wal irraa citiinsi ergamootaa argamee booda isinitti dhufeera Akka isin gammachiisaafi dinniinaanis nutti hin dhufne hin jenneef, Dhugumatti gammachiisaafi akeekkachiisaan isinitti dhufeera Rabbiin waan hunda irratti danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 20, 'Yeroo Muusaan ummata isaatiin jedhe [yaadadhaa]: "yaa ummata kiyya! Ni’imaa Rabbiin isin irratti oole yaadadhaa. yeroo nabiyyota isin keessa taasisee, moototas isin godheefi waan aalama irraa namtokkoofillee hin kennin isiniif kennee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 21, 'Yaa ummata kiyya! Dachii qulqulleeffamtuu Rabbiin isiniif barreesse (Filisxeeniin) seenaa Dugdoowwan keessan duubatti hin deebi’inaa. (Yoo akkas gootan) hongaa’oo taatanii deebitu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 22, 'Nijedhan "Yaa Muusaa! Dhugumatti, ishee keessa ummata of tuultotatu (gara jabeeyyiitu) jira. Nuti hanga isaan ishee keessaa ba’anitti gara ishee hin seennu. Yoo isaan ishee irraa ba’an, nuti seenoodha".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 23, 'Namoota (Rabbiin) sodaatan, kan Rabbiin ni’imaa Isaatiin isaan qanansiise irraa dhiirotiin lama ni jedhan: "balbala isaan irratti seenaa. Yeroo isa seentan isin injifattoota. Yoo mu’uminoota taataniif Rabbi qofarratti hirkadhaa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 24, 'Ni jedhan: "Yaa Muusaa! Hanga isaan ishee keessa jiranutti, nuti gonkumaa ishee hin seennu, Atiifi Gooftaan kee deemaa lolaa, nuti as tattaa''oodha".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 25, '(Muusaan) ni jedhe: "Yaa Gooftaa kiyya! Ani lubbuu tiyyaafii obboleessa kiyya irratti malee taaytaa hin qabu. Nuufi orma finciltootaa gidduu addaan baasi."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 26, '(Rabbiin) ni jedhe: "isheen (dachittii seenuun) waggoota afurtamaaf isaan irratti haraamfamtuudha; Dachii keessa dhama’u, Ummata finciltoota irratti hin gaddin."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 27, 'Oduu ilmaan Aadam lamaanii haqaan isaanirratti dubbisi. yeroo isaan waan Rabbitti isaan dhiheessu (qurbaana) dhiyeessan, isa tokko irraa qeebalamee isa kaan irraa qeebalamuu dide. (Inni lamuu isa duraatiin) ni jedhe: "Ani dhugumatti sin ajjeesa. " (Inni duraas) ni jedhe: "Rabbiin kan qeebalu warra Isa sodaatan irraayyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 28, 'Yoo ati na ajjeesuuf harka kee gara kiyyatti diriirsites, ani si ajjeesuuf harka kiyya gara keetti hin diriirsu. Ani Rabbii Gooftaa aalamaan sodaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 29, 'Ani ati badii kiyyaafi badii keetiin deebitee warra ibiddaa irraa ta''uun fedha. Kunis mindaa miidhaa hojjattootaati."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 30, 'Lubbuun isaa obboleessa isaa ajjeesuu isaaf miidhagsite, isa ajjeese. Warra hoonga’an irraas ta’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 31, 'Rabbiin harraagessa dachii haadhu erge Akkamitti akka reeffa obboleessa isaa dhoksu (awwaalu) isa argisiisuuf. yaa gaabbiitoo! "Sila ani Reeffa obboleessa kiyyaa dhoksuuf akka harraagessa kanaa ta’uun dadhabee?" jedhe. gaabbitoota irraa tahe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 32, 'Sababa kanaan Ilmaan Israa’iil irratti barreesine "namni lubbuu tokko lubbuu biraatiin alatti yookiin dachii keessa balleessuun alatti ajjeese akka waan nama hunda ajjeeseti; namni ishee jiraachise akka waan nama hunda jiraachiseeti" jechuu (murteessine). Dhugumatti, ergamoonni keenya ragaawwan ifa ta’aniin isaanitti dhuftee jirti. Ergasii irra hedduun isaanii sana booda dachii keessatti daangaa dabroodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 33, 'Dhugumatti mindaan warra Rabbiifi ergamaa Isaatiin lolanii, dachii keessa balleessaa deemanii, ajjeefamuu yookiin fannifamuu yookiin harkoowwaniifi miilleen isaanii faallaan irraa ciramuu, yookiin biyya irraa ari’amuudha. Kun addunyaatti isaaniif salphina. Aakhiraatti immoo isaaniif adabbii guddaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 34, 'Isaannan odoo isin isaan irratti hin danda''in dura toobatan malee; beekaa Rabbiin araaramaa mararfataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 35, 'Yaa warra amantan! Rabbiin sodaadhaa. Waan gara Isaatti dhihaattaniin barbaadaa.karaa Isaa keessattis qabsaa’aa. Akka milkooftaniif jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 36, 'Dhugumatti, isaan kafaran odoo wanti dachii keessa jiru hundiifi fakkaatan isaas isa waliin isaaniif ta’ee isaan adabbii Guyyaa Qiyaamaa irraa of bituu fedhanii isaan irraa hin qeebalamu. Isaaniif adabbii laalessaa ta’etu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 37, 'Ibidda irraa ba’uu fedhu. Isaan ishee irraa kan ba’anii miti. Isaaniif adabbii itti fufaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 38, 'Hattichaafii hattittii harkoowwan isaan lamaanii muraa galata waan isaan dalaganiif, jiilchaa Rabbi irraa ta''eef jecha. Rabbiin injifataa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 39, 'Namni miidhaa (raawwachuu) isaa booda toobatee tolche, dhugumatti Rabbiin tawbaa isaa irraa qeebala. Rabbiin akkaan araaramaa, akkaan rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 40, 'Sila ati Rabbiin mootummaan samiileefi dachii kan Isaa ta’uu hin beeknee! Nama fedhe ni adaba; nama fedheef ni araarama. Rabbiin waan hunda irratti danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 41, 'Ati Yaa ergamichaa!warri kufrii keessatti ariifatan si hin gaddisiisin Isaan afaanoowwan isaaniitiin amanne jedhanii onneewwan isaanii hin amanin irraa, Isaan yahuudoman irraas, kan kijibaaf dhaggeeffatanu, ummata biraa kan gara kee hin dhufiniif dhaggeeffatantu jiru. Jechoota bakka isaa irraa jijjiiru. "Yoo kana kennamtan isa qabadhaa; yoo isa hin kennamin immoo eeggadhaa" jedhu. Nama Rabbiin mokkoroo isaa fedhe Rabbi irraa waan tokko isaaf hin deebiftu. Sunniin warra Rabbiin onneewwan isaanii qulqulleessuu hin fedhini. Addunyaa kanatti salphinatu isaaniif jira; Aakhiraatti immoo adabbii guddaa ta’etu isaaniif jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 42, 'Kijiba akkaan dhaggeeffattoota, haraama akkaan nyaatoodha. Yoo isaan sitti dhufan, gidduu isaaniitti murteessi; yookiin isaan irraa gara gali. Yoo ati isaan irraa gara galte homaa si hin miidhanu. Yoo murteessite haqaan gidduu isaaniitti murteessi. Rabbiin warra haqaan murteessan jaalata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 43, 'Sila akkamitti si murteessisiifatu odoo Tawraat kan murteen Rabbii ishee keessa jiru isaan bira jirtuu? Ergasii san booda gara galu. Jarri sun mu’uminootaa miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 44, 'Dhugumatti, Nuti Tawraatiin kan ishee keessa qajeelfamaafi ifaan jiru taasifnee buufnee jirra. Nabiyyoonni warri fedha Rabbiitiif bulan warra yahuudomaniif isheedhaan murteessu. Qeesonniifi beektonnis waan kitaaba Rabbii irraa eegsifamaniniifi ishee irratti ragaa ta''aniin (murteessu). Namoota hin sodaatinaa; Ana sodaadhaa. Keeyyattoota kiyya gatii xiqqaan hin gurguratinaa. Namni waan Rabbiin buuseen hin murteessin, isaan sun kaafiroota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 45, 'Isaanirratti barreessine Ishee keessatti "Lubbuun lubbuudhaan, ijji ijaan, funyaan funyaaniin, gurri gurraan, ilkaan ilkaaniin, madaan gumaadha" (jechuun isaan irratti barreessinee) jirra. Namni isa sadaqate (gumaa dhiise) inni isaaf (badii) harcaasaadha. Namni waan Rabbiin buuseen hin murteessin, isaan sun miidhaa raawwattoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 46, 'Faana isaanii irratti Iisaa ilma Maryam hordofsiifne, haala waan isaan duraa Tawraat irraa ta''ee dhuga''oomsaa taheetiin. Injiiliin isaaf kennine, kan isa keessa qajeelfamniifi ifti jiru, dhugoomsaa waan isaan duraa Tawraat irraa ta''ee. qajeelfamaafi gorsa (Rabbi) sodaattotaaf', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 47, 'Warri Injiil waan Rabbiin isa keessatti buuseen haa murteessanu; Namni waan Rabbiin buuseen hin murteessin, isaan sun finciltoota', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 48, 'Nuti kitaaba (Qur’aana) haqaan gara keetti buufneerra. kan kitaaba irraa waan isa duraatiif dhugoomsaafi isa irratti tiksaa ta''ee. Waan Rabbiin buuseen gidduu isaaniitti murteessi. Dhugaa waan sitti dhufe irraa (dabuun) fedha lubbuu isaanii hin hordofin. Hundumaafuu seera shari’aatiifi karaa ifa ta’e taasifnee jirra. Rabbiin odoo fedhee ummata tokko isin taasisa ture. Garuu waan isiniif kenne keessatti isin qormaatuuf (addaan isin baase). Hojii gaarii keessatti wal dorgomaa. Hunda taatanii deebiin keessan gara Rabbiiti, Waan isin isa keessatti wal dhabaa turtan isinitti hima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 49, 'Ammas "gidduu isaaniitti waan Rabbiin buuseen murteessi. Fedhii lubbuu isaanii hin hordofin. Garii waan Rabbiin gara keetti buusee irraas akka si hin deebifne isaan eeggadhu. " (jechuudhaan buufne). Yoo isaan (sirraa) gara galan, Rabbiin garii badii isaaniitiin isaan tuquu (adabuu) barbaada jechuu beeki. Dhugumatti, hedduun namoota irraa ta''e finciltoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 50, 'Sila murtii ''jaahiliyyaa barbaaduu? Ummata hubannoo amantii qabaniif wanti Rabbi irra murtiin isaa miidhagaa hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 51, 'Yaa warra amantan! Yahuudotaafi Kiristaanotas jaalallee keessoo hin godhatinaa. Gariin isaanii jaalallee gariiti, Isin irraa namni jaalallee isaan godhate, inni isaanuma irraayyi. Dhugumatti, Rabbiin ummata miidhaa hojjattoota hin qajeelchu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 52, 'Isaan onneewwan isaanii keessa dhukkubni (munaafiqummaa) jiru, isaan (gargaaruu) keessatti kan ariifatan agarta. "naannawaan rakkinaa tokko nu tuquu sodaanna" jedhan, Rabbiin injifannoo yookiin murtii isa biraa ta’e fidee, waan lubbuu isaanii keessatti gadi qabatan irratti gaabbitoota ta''uun isaanii mirkanaa''eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 53, 'Isaan amanan ni jedhu: "isaan nuti isinii wajjin jirra jedhanii kakuu cimaa Rabbiin kakatan isaan kanaa mitii?" (jedhu). Dalagaaleen isaanii badde. Hongaa''oo ta''an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 54, 'Yaa warra amantan! Isin irraa namni amantii isaa (Islaama) irraa gara gale, Rabbiin namoota isaan jaalatuufi isaanis Isa jaalatan fuulduratti ni fida, kan mu’uminootaaf gadi of qabanii kaafiroota irratti ciman, kan karaa Rabbii keessatti qabsaa’aniifi komii warra isaan komatuu kan hin sodaanne (fuulduratti ni fida). Kun tola Rabbiiti. Nama fedheef isa kenna. Rabbiin (kenni isaa) bal''aa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 55, 'Dhugumatti, jaalalleen keessan Rabbiifi ergamaa Isaati Ammas isaan amanan, kanneen salaata dhaabaniifi kan rukuu''a godhan ta''aa zakaa kennaniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 56, 'Namoonni Rabbiin, ergamaa Isaatiifi warra amanan jaalallee taasifatan (isaan garee Rabbiiti). Dhugumatti gareen Rabbii isaanumatu injifattoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 57, 'isin Yaa warra amantan! Warra amantii keessan qishinaafi tapha taasisan kan isaan isin dura kitaaba kennamaniifi kaafiroota irraa ta’an jaalallee hin taasifatinaa, Yoo mu’uminoota taataniif Rabbiin sodaadhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 58, 'Yeroo gara salaataa lallabdan (azaana gootan), qishinaafi tapha ishee godhatu. Kun waan isaan ummata hin xiinxalle ta’aniifi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 59, 'jedhi "Yaa warra kitaabaa! Sila waan nurraa jibbitan niqabdanii nuti Rabbitti amanuu keenya malee? waan gara keenya buufamettis, waan kana dura buufamettis (amanuu keenya malee).irra hedduun keessan finciltoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 60, 'Jedhi: "Sila kan adabbiin isaa Rabbiin biratti san caalaa badaa ta’e isiniif himuu? (inni sun) Nama Rabbiin isa abaareefi isa irratti dallane, kan isaan irraa jaldeessaafi booyye taasise, isaan xaaghuuta (gabbaramtoota Rabbiin alaa) gabbaran, isaan sun warra (Aakhiratti) iddoon isaanii badaa ta''ee, irra jallatoowwani karaa qajeelarraa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 61, 'yeroo isinitti dhufan "nuti amanne" jedhu, Isaan odoma dhugumatti kufrii wajjin seenaniifi isaan dhugumatti isumaa wajjin ba’anii jiranuu. Rabbiin irra beekaa waan isaan dhoksaa turaniiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 62, 'Baay’ee isaan irraa ta''e kan badii, daangaa dabruufi wantoota dhorgaman nyaachuu isaanii keessatti ariifatan argita. Wantoonni isaan hojjataa turan waa fokkate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 63, 'Sila maaliif qeesonniifi beektonni isaan hin dhorgine? jechoota isaanii kan badiitiifi wantoota dhorgaman nyaachuu isaanii irraa. Wanti isaan dalagaa turan waa fokkate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 64, 'Yahuudonni "harki Rabbii hidhamtuu dha" jette. Harkoowwan isaanii hidhamtee, waan jedhaniin abaaramaniiru, Lakki! Harki Isaa lamaan diriiroodha. Akka fedhetti kenna. Dhugumatti, irra hedduu isaaniitiif wanti Gooftaa kee irraa gara keetti buufame daangaa dabruufi kufrii dabala. Diinummaafi wal jibbaa hanga Guyyaa Qiyaamatti gidduu isaaniitti darbine. Dhawaata isaan ibidda lolaaf qabsiisaniin Rabbiin ishee dhaamsa. Isaan badii dachii keessa facaasuuf fiigu. Rabbiin badii hojjattoota hin jaalatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 65, 'Odoo warri kitaabaa amananii Rabbiin sodaatanii, silaa hamtuuwwan isaanii isaan irraa haqna, jannata qananii isaan seensifna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 66, 'Odoo isaan Tawraatiin, Injiiliifi waan Gooftaa isaanii irraa gara isaanitti buufametti hojjatanii, silaa gubbaa isaanitiifi miiloowwan isaanii jalaa nyaatu turan. Isaan irraa ummata giddu galeessa ta''antu jira. Hedduun isaan irraa ta’e immoo hojiin isaanii waa fokkate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 67, 'Yaa Ergamichaa! Waan Gooftaa kee irraa sirratti buufame geessi. Yoo (kana) hin dalagin, ati ergaa Isaa hin geessifne. Rabbiin namoota irraa si eega. Dhugumatti, Rabbiin ummata kaafiraa hin qajeelchu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 68, 'Jedhi: "Yaa warra kitaabaa! Isin hanga Tawraatiin, Injiiliifi waan Gooftaa keessan irraa gara keessanitti buufametti hojjattanitti homaa irra hin jirtan.". Dhugumatti, wanti Gooftaa kee irraa gara keetti buufame daangaa dabruufi kufrii irra hedduu isaaniitiif dabala. Ummata kaafiraa irratti hin gaddin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 69, 'Isaannan amanan, isaan yahuudoman, saabi’oonnii fi kiristaanonnis, namni Rabbiifi guyyaa Aakhiraatti amanee, gaggaarii dalage, isaan irra sodaan hin jiru; isaan hin gaddanis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 70, 'Dhugumatti, Nuti waadaa Ilmaan Israa’iil irraa fuunee ergamootas gara isaanitti erginee jirra. Dhawaata ergamaan waan lubbuuleen isaanii hin feeneen isaanitti dhufuun garii isaanii kijibsiisanii; garii isaanii immoo ajjeesan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 71, 'Adabbiin (mokkoraan) hin jirtuu yaadan. Kanaafuu jaamanii duudan, Ergasii Rabbiin tawbaa isaanii irraa qeebale, Ergasii irra hedduun isaanii jaamanii duudan. Rabbiin waan isaan dalagan argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 72, 'Isaan "Rabbiin Masiih Ilma Maryami" jedhan dhugumatti kafaranii jiru. Masiih ni jedhe: "Yaa Ilmaan Israa''iil! Rabbii Gooftaa kiyyaafi Gooftaa keessan ta’e gabbaraa. Dhugumatti, namni Rabbitti qindeesse, Rabbiin isa irratti jannata haraama taasiseera. Teessoon isaas ibidda, Miidhaa raawwattootaaf tumsitoonni hin jiranu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 73, 'Isaan "Rabbiin sadaffaa sadeeniiti" jedhan dhugumatti kafaraniiru. Gabbaramaa tokkicha malee haqaan gabbaramaan biraa hin jiru. Yoo waan jedhan (kana) irraa hin dhorgamin, dhugumatti warra isaan irraa kafaran adabbii laalessaa ta’etu tuqa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 74, 'Sila gara Rabbiitti tawbatanii araarama Isa hin kadhatanuu? Rabbiin araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 75, 'Masiih Ilma Maryam ergamaa isa dura ergamoonni dabran malee hintaane. Haati isaas akkaan dhugoomsituudha. Lamaanuu nyaata kan nyaatan turan. Akkamitti akka keeyyattoota ifa isaaniif taasifnu ilaali. Ergasiis akkamitti akka isaan (dhugaa irraa) garagalan ilaali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 76, 'Jedhi: "Sila isin Rabbiin alatti waan miidhaafi faayidaa isiniif hin qabne gabbartuu? Rabbitu Isa hunda dhagayaa, hunda beekaadha."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 77, 'Jedhi: "Yaa warra kitaabaa! amantii keessan keessatti dhugaan ala (waan biraatti amanuun) daangaa hin dabrinaa. Fedhii ummata duraan jallatanii dabranii, (namoota) heddus jallisaniifi karaa qajeelaa irraa jallatanii hin hordofinaa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 78, 'Isaan Ilmaan Israa’iil irraa kafaran arraba Daawuudiifi Iisaa Ilma Maryam irratti abaaramaniiru. Kun waan isaan (Rabbiin) faallessaniifi kan daangaa dabran turaniifi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 79, 'Hamtuu hojjatan irraa kan wal hin dhorgine turan. Wantoonni isaan hojjataa turan waa fokkate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 80, 'Hedduu isaan irraa ta’e kan warra kafaran jaalallee godhatan argita. Rabbiin isaan irratti waan dallaneef wanti lubbuun isaanii isaaniif dabarsite waa fokkate! Isaan adabbii keessattis hafoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 81, 'Odoo kan Rabbitti, nabiyyittiifi waan gara isaatti bu’etti amanan ta’anii, silaa isaan jaalallee hin godhatanu turan. Garuu isaan irraa (namoonni) hedduun finciltoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 82, 'Dhugumatti namoota diinummaan warra amananiif akkaan cimaa ta''an yahuudotaafi mushrikoota ta’uu argita. Dhugumatti, namoota jaalalaan isaan amananitti irra dhihoo ta’an warra "nuti kiristaanota" jedhan ta’aniitiin agarta. Kun waan isaan irraa qeesonniifi monokseewwan jiraniifi isaan hin boonan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 83, ')Kiristaanonni) yeroo waan gara ergamichaa buufame dhagayan, sababaa dhugaa beekaniif jecha kan ijji isaanii imimmaan dhangalaatu argita. Ni jedhu: "(Yaa) Gooftaa keenya! Nuti amannee ragoota wajjin nu barreessi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 84, 'Sila maaltu nuuf jiraayyi Rabbiifi dhugaa irraa waan nutti bu’etti amanuu dhabna? Gooftaan keenya ummata gaggaarii wajjin nu seensisuus ni kajeella" (jedhu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 85, 'Sababaa waan isaan jedhaniitiin Rabbiin jannatoota laggeen ishee jala yaatu,isaan mindeesse, ishee keessatti hafoodha, Kuni mindaa warra tolchitootaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 86, 'Isaan kafaranii keeyyattoota keenya kijibsiisan, sunniin warreen ibiddaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 87, 'Yaa warra amantan! gaggaarii waan Rabbiin isiniif hayyamee haraama hin taasisinaa. Daangaa hin dabrinaa; Dhugumatti, Rabbiin warra daangaa dabranu hin jaalatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 88, 'Waan Rabbiin isiniif hire irraa nyaadhaa, Halaalaafi gaarii haala ta’aniin. Rabbii Isa isin itti amantan sodaadhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 89, 'Rabbiin isin hin qabu kakuu keessan kan osoo itti hin yaadin kakattaniin keessatti, Garuu waan kakuuf murteeffattanii (kakattaniin) isin qaba. adabbiin isaa hiyyeeyyii kudhan giddu gala waan maatii keessan nyaachiftan irraa nyaachisuu, yookiin isaan uffisuu, yookiin gabra bilisoomsuudha. Namni hin argatin, guyyaa sadi soomuu qaba. kuni adabbii kakuulee keessaniiti yogguu kakattan. Kakuulee keessan tiksaa. Akka isin galateeffattaniif jecha Rabbiin akka kanatti keeyyattoota Isaa isiniif ibsa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 90, 'Isin Yaa warra amantan! dhugumatti farsoon (kamriin), qumaarri, taaghuunni, xiyyaan hixaa (carraa) ilaallachuun (raaggachuun) najasa dalagaa sheyxaanaa irraayyii isa irraa fagaadhaa.akka milkooftaniif jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 91, 'Wanti sheyxaanni fedhu gidduu keessanitti diinummaafi wal jibbaa dhugaatii macheessaniifi qumaaraan buusuudha. Rabbiin yaadachuufi salaata irraa isin dhorguudha. Sila isin hin dhorgamtanuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 92, 'Rabbiif ajajamaa. Ergamaafis ajajamaa (Wantoota dhorgaman kanneen irraa) eeggadhaa, Yoo irraa gara galtan immoo dhugumatti ergamaa keenya irra karaa ifa ta’een (ergaa keenya) geessuu malee wanti biraa akka hin jirre beekaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 93, 'warra amananii gaarii hojjatanirra badiin hinjiru, Waan (dur) nyaatan keessatti, yeroo (Rabbiin) sodaatanii (Isatti) amananii gaggaarii hojjatan, ergasii (Rabbiin) sodaatanii (Isatti) amanan; ammas (Rabbiin) sodaatanii (dalagaa) tolchan. Rabbiin toltuu hojjattoota jaalata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 94, 'Yaa warra amantan! Rabbiin waan adamsoo irraa harkoowwan keessaniifi waraanneen keessan argatteen isin mokkora. nama ghaybiitti Isa sodaatu mul’isuuf jecha. Namni kana booda daangaa dabre isaaf adabbii laalessaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 95, 'Yaa warra amantan! odoo (hajjiifii umraa) hidhattanii jirtanuu bineensa bosonaa hin ajjeesinaa. Namni isin irraa odoo beekuu ajjeese, adabbiin isaa beeylada irraa fakkii waan ajjeeseeti. isinirraa namni haqaa lama isa haamurteessuu. haala wareega taateen kan ka’abaa geeffamtu, yookiin hiyyeeyyii nyaachisuu, yookiin qixxee kanaa soomuudha. (Kunis) akka adabbii hojii isaa dhandhamuufi. Waan (dhorgamuun dura) dabre Rabbiin irra isiniif dabreera. Nama (gara badichaa) deebi’e Rabbiin haaloo irraa ba’ata. Rabbiin injifataa, abbaa haaloo ba’annaati.[1]', '[1] hiikkaan isaa namni hajjiifii umratti jiru, akkasuma daangaa makkaa keessatti bineensa bosonaa ajjeesuun dhoowwaadha. yoo ajjeese ni adabama. adabni isaa 1-bineensa inni ajjeesee san kafakkatu beyladarraa kaibaa makka keessatti qalee miskiinaa qooda. fakkeenyaaf yoo gadamsa ajjeese horii, yoo borofa ajjeese hoolaa, yoo kuruphoo ajjeese re''ee qala. 2- yookaa gatii beeyladaan kuni baasuun midhaan bitee qooda. miskiina tokkoof walakkaa sugudaa. 3- yookaa nisoomana walakkaa sugudaarraa soomana guyyaa tokko akkasitti herregee. kana namoota hayyuma qaban lamatu taa''ee shalagee itti murteessa.(tafsiirul muyassar).');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 96, 'Isiniif eeyyamameera AdamSoon galaanaafi nyaanni isaas, itti fayyadama keessaniifi daldaltootaatiif jecha. Waan hidhannaa Hajjii keessa jirtanuun adamSoon lafa irraa isin irratti haraama godhame. Rabbii isa gara Isaatti oofamtanu sodaadhaa. [1]', '[1] kana jechuun yeroo hajjiifii umraa hidhatan bineensa barraa lafarra jiraatu ajjeesuun dhoowwaadha, garuu waan bishaan keessa jiraatu ajjeesanii nyaachuun hayyamamee jira jechuudha.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 97, 'Rabbiin Ka’abaa mana kabajamaa,namootaaf gadi dhaabbii (jireenya) taasiseera ji’a kabajamaas, horii wareegaas, horii wareegaaf mallattoon morma irratti godhames. Kun akka Rabbiin wantoota samii keessa jiraniifi wantoota dachii keessa jiranis hunda kanbeeku tahe beektaniifi, ammas akka Rabbiin waan hunda beekaa ta’uu beektaniifi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 98, 'Beekaa! Dhugumatti Rabbiin (abbaa) adabbii cimaati. Dhugumatti Rabbiin araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 99, 'Ergamicha irra dhaqqabsiisuu malee homaa hin jiru. Rabbiin waan isin mul’iftaniifi waan isin dhoksitan ni beeka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 100, 'Jedhi: "fokkataaniifi gaariin wal hin qixxaatanu, Odoma baay’inni wantoota fokkataa si dinqisiiseeyyuu". Yaa warra qalbii qabdan akka milkooftaniif jecha Rabbiin sodaadhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 101, 'Yaa warra amantan! waan yoo ifa isiniif taasifamte isin hammeessitu irraa hin gaafatinaa. Yoo yeroo Qur’aanni buufamu ishee irraa gaafattan, ifa isiniif taasifamti. Rabbiin ishee irra dabreera. Rabbiin araaramaa obsaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 102, 'Ummanni isiniin duraa dhugumatti ishee gaafatanii, ergasii sababaa isheetiin kaafiroota tahan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 103, 'Mootichis ni jedhe: “lubbuu kootiifan isa dhuunfadhaa isaan natti kottaa. Yeroma isa (Yuusufiin) hasofsiisu, “Ati har’a nu biratti mijjeeffataa amanamaadha” jedheen. [1]', 'ما شرع الله للمشركين ما ابتدعوه في بهيمة الأنعام مِن تَرْك الانتفاع ببعضها وجعلها للأصنام، وهي: البَحيرة التي تُقطع أذنها إذا ولدت عددًا من البطون، والسائبة وهي التي تُترك للأصنام، والوصيلة وهي التي تتصل ولادتها بأنثى بعد أنثى، والحامي وهو الذكر من الإبل إذا وُلد من صلبه عدد من الإبل
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 104, 'Yeroo "gara waan Rabbiin buuseefi gara ergamichaa kottaa" isaaniin jedhame "wanti nuti abbootii keenya irratti argine nuuf ga’aadha" jedhu. Sila odoo abbootiin isaanii homaa kan hin beekneefi karaa hin qajeelle ta’aniis (isaanuma hordofuu)?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 105, 'Yaa warra amantan! Lubbuu keessan (qabuun) isinirra haajiraatu, Yeroo isin qajeeltan namni jal’ate isin hin miidhu. Deebiin keessan hundaatuu gara Rabbiiti. Waan isin dalagaa turtan isinitti hima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 106, 'Yaa warra amantan! Yeroo tokkoo keessanitti duuti dhufe ogga dhaamsaa jidduu keessanitti ragaan (isin irratti dirqama). nama haqaa lama kan isin irraa ta’e, yookin nama lama kan isiniin alaa irraa tahe, yoo isin dachii keessa deemtanii balaan du’aa isin mudate (ragaan isin irratti dirqama). Yoo shakkitan booda salaataatii isaan lamaan dhaabdanii Rabbiin kakatu "odoma fira dhihoo ta’eeyyuu isaan (ragaa keenyaan) maallaqa hin jijjiirrannu; ragaa Rabbiis hin dhoksinu; nuti yeroo sana warra dilaawaa irraayyi" jedhanii .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 107, 'Yoo isaan lamaan badii haqa godhachuun beekame, fira warra (dhaala) haqa godhate irraa namni lama bakka isaan lamaanii dhaabatanii "ragaan keenya ragaa isaan lamaanii irra dhugaadha; nuti daangaas hin dabrine; yeroo san nuti miidhaa raawwattoota irraayyi" (jedhanii) Rabbiin kakatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 108, 'Ragaan bifa sirriin dhufuufi eega kakuu isaaniitii kakuun deebifamuu sodaachuuf kanatu irra dhihoodha. Rabbiin sodaadhaatii (ajaja isaas) dhaga''aa. Rabbiin finciltoota hin qajeelchu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 109, 'Guyyaa Rabbiin ergamoota (Isaa) walitti qabee "deebii maaliitu isiniif deebi’e" jedhu [yaadadhu]. [Isaan] "nuti beekkomsi nuuf hintaane; Ati situ akkaan beekaa fagooti" jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 110, 'yeroo Rabbiin jedhe (dubbadhu) “Yaa Iisaa ilma Maryam! qananii tiyya tan ani siifi haadha tee irratti oole yaadadhu.yeroo Ani ruuhii qulqulluudhaan si jabeesse, haala ati daa’imummaafi ga’eessummaan nama dubbiftuun" Ammas (yeroo) Ani kitaaba, ogummaa, Tawraatiifi Injiiliin si barsiise. yeroo heyyama kiyyaan dhoqqee irraa waan akka allaattii uumtee afuura keessatti afuuftee heyyama kiyyaan allaattii taatu; yeroo heyyama kiyyaan jaamaafi shoolii (barasa) fayyiftu, yeroo heyyama kiyyaan du’aa kaaftu, yeroo (si ajjeesuu barbaadnaan) banii Israa’iil sirraa deebise, yeroo ati ragaa ifa ba’aan isaanitti dhufnaan isaan irraa warri kafaran “kuni sihrii ifa galaadha” jedhan, " [yaadadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 111, 'Yeroo ani gara hawaariyyootaa beeksisee "Anaafi ergamaa kiyyatti amanaa" jechuu, isaanis "Nuti amanne; akka nuti Muslimoota taane ragaa ba’i" jedhan [yaadadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 112, 'Yeroo hawaariyyoonni "Yaa Iisaa Ilma Maryam! Sila Gooftaan kee maaddii (qorii) samii irraa nuuf buusuu danda’aa?" jedhanu [yaadadhu]. (Iisaanis) "Yoo mu’uminoota taataniif Rabbiin sodaadhaa" jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 113, '(Isaanis) "Nuti ishee irraa nyaachuu feena jedhan. onneewwan teenya tasgabbaa’uus,ati dhugaa nutti dubbattee mirkaneeffachus (feena) nuti san irratti warra ragaa ba’an irraa ta’uu (feena)" (jedhan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 114, 'Iisaa Ilma Maryam ni jedhe: "Yaa Allaah! Gooftaa keenya! samii irraa maaddii nurratti buusi, tan ayyaana (guyyaa gammachuu) nuuf taatu, dura keenyaafii booda keenyaafis, tan mallattoo sirraa (buute) nuuf taatu, nu soori. Ati caalaa warra rizqii kennuuti."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 115, 'Rabbiin ni jedhe: "Ani ishee isinirratti buusaadha. Isin irraa namni san booda kafare, Ani adabbii aalama irraa tokkollee hin adabnen isa adaba."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 116, 'Yeroo Rabbiin "Yaa Iisaa Ilma Maryam! sila situ namootaan anaafi haadha tiyya Rabbii gaditti gabbaramaa lama taasifadhaa jedhee?" jedhu [yaadadhu]. [Inni] ni jedhe: "Ati qulqulloofte! Ani waan dhugaa naaf hin taane jechuun anaaf hin ta''u. Yoo ani isa jedheera ta''eef, ati dhugumatti isa barteetta. Waan lubbuu kiyya keessaa ni beekta. Ani waan nafsii kee keessaa hin beeku. Dhugumatti, ati akkaan beekaa waan fagooti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 117, 'Waan ati itti na ajajje malee waan biraa isaaniin hin janne, (sun) ‘Rabbiin, Gooftaa kiyyaafi Gooftaa keessan gabbaraa'' (jechuudha). Hangan isaan keessa turetti isaan irratti ragaan ture. Erga ol nafuutee booda ati isaan irratti tiksaa taate. Ati waan hunda irratti ragaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 118, 'Yoo isaan adabde, isaan gabrootuma keeti. Yoo isaaniif araaramte, ati simatu injifataa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 119, 'Rabbiin ni jedhe: "Kun guyyaa warra dhugaa dubbatan dhugaan isaanii isaan fayyaduudha. Isaaniif ishee keessatti yeroo hunda hafaa ta''anii jannatoota jala ishee laggeen yaatutu jira. Rabbiin isaan irraa jaalateera. Isaanis Isarraa jaalataniiru. Kun milkii guddaadha."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 120, 'Mootummaan samii, dachiifi wantoota isaan keessaa kan Rabbiiti. Inni waan hunda irratti danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 1, 'Faaruun hundi kan Rabbii isa samiifi dachii uumee, dukkanaafi ifa argamsiiseeti. Ergasii isaan kafaran Rabbii isaaniitti qindeessu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 2, 'Inni isa dhoqqee irraa isin uumee ergasii beellama (du''aa) murteesseedha. Beellamni beekamaan (Qiyaamaan) immoo Isa bira jira. Ergasii isin ni shakkitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 3, 'Inni samiileefii keessattiifi dachii keessattis gabbaramaadha. Iccitii keessaniifi ifa bahaa keessanis ni beeka. Waan isin hojjattanis ni beeka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 4, 'Keeyyanni keeyyattoota Gooftaa isaanii irraa ta''e isaanitti dhufee yoo kan isaan ishee irraa gara galan ta''e malee hin hafu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 5, 'Dhugumatti, isaan yeroma dhugaan isaanitti dhufu sobsiisaniiru. Oduun waan (adabbii) isaan itti qoosaa turanii fuulduratti isaanitti dhufa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 6, 'Sila isaaniin dura jaarraa (ummata) irraa heddu balleessuu keenya hin ilaalanuu? kan dachii keessatti hanga isiniif hin mijeessin isaaniif mijeessine. Rooba wal hordofaa ta''ee isaan irratti buufne. Laggeenis jala isaanii akka yaatu goone. Badiilee isaaniitiin isaan balleessinee. booda isaaniitii jaarraa biraa uumne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 7, 'Odoo kitaaba waraqaa irratti barreeffame sirratti buufnee silaa harka isaanitiin isa tuqanii warri kafaran "kun sihrii ifa bahe malee hintaane" jedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 8, 'Ni jedhu: "Maaliif Maleykaan isa irratti hin buufamin? " Odoo Maleykaa buufnee silaa dhimmichi ni murteeffama; Ergasii hintursiifaman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 9, 'Odoma (nabiyyicha) maleykaa isa gooneeyyuu dhugumatti silaa (nama) dhiira isa taasifneeti waan isaan walitti fakkeessan isaan irratti wal fakkeesina turre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 10, 'Dhugumatti, ergamoota si dura turanitti qoosamee ture. Isaan irraa warra qoosanitti wanti isaan itti qoosaa turan isaanitti marse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 11, 'Jedhi: "dachii keessa deemaa; ergasii booddeen warra dhugaa kijibsiisee akkam akka ta’e ilaalaa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 12, '"Wantoonni samiileefi dachii keessa jiran hundi kan eenyuuti?" jedhi. “Kan Rabbiiti” jedhi. Lubbuu Isaa irratti rahmata barreessee jira. Dhugumatti, Guyyaa Qiyaamaa mamiin isa keessa hin jirreef walitti isin qaba. Isaan lubbuulee isaanii hoongessan, isaan hin amananu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 13, 'Wanti halkaniifi guyyaa keessa callises kan isaati. Inni dhagayaa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 14, 'Jedhi "Sila Rabbiin malee gabbaramaa biraa godhadhaa? (inni) uumaa samiifi dachiiti, inni ni nyaachisa hin nyaatu". jedhi "Ani jalqaba nama Rabbiif bulee ta''uuttin ajajame. Mushrikoota irraas hin ta''in (naan jedhame)".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 15, '"Ani yoon Gooftaa kiyyatti dilaaye adabbii guyyaa guddaan sodaadha" jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 16, 'Namni guyyaa san isa (adabicha) irraa deebifame, dhugumatti (Rabbiin) isa mararfateera. Kun milkii guddaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 17, 'Yoo Rabbiin miidhaan si tuqe, Isa malee deemsisaan isaaf hin jiru. Yoo toltuudhaan si tuqe, Inni waan hunda irratti danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 18, 'Inni gabroota Isaa irratti mo’ataadha. Inni ogeessa, keessa beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 19, 'jedhi "Sila ragaadhaaf waan hunda irra maaltu guddaadha?" jedhi. "Rabbiin Gidduu kiyyaafi gidduu keessanitti ragaadha. Qur’aanni kuni akkan ittiin isiniifi nama inni bira ga’u dinniinuuf gara kiyyatti beeksifame. Sila isin dhugumatti Rabbii wajjin gabbaramtoonni biraa jiraachuu ragaa baatuu?". jedhiin "Ani ragaa (akkasii) hin ba’u". jedhi "Dhugumatti, Inni dhugaan gabbaramaa tokkicha. Anis waan isin qindeessitan irraa qulqulluudha" (jedhi).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 20, 'Warri kitaaba isaaniif kennine akka ilmaan isaanii beekanitti isa (muhammadiin) beeku. Warri lubbuulee isaanii hoongessan, isaan hin amananu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 21, 'Nama Rabbirratti kijiba uume yookiin keeyyattoota Isaa kijibsiise caalaa namni miidhaa hojjate eenyu? Dhugumatti, miidhaa hojjattoonni hin milkaayanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 22, 'Guyyaa hunda isaanii walitti qabnee, ergasii isaan qindeessaniin "gabbaramtoonni keessan kan himaa turtan eessa jiru?" jennuun san [yaadadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 23, 'Ergasii mokkaramuun (deebiin) isaanii "Allaaha Rabbii keenyaan kakannee! nuti mushrikoota hin taane" jechuu malee hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 24, 'Laali Akka itti isaan lubbuulee isaaniirratti kijiban. wanti isaan sobaan odeessaa turan akka itti isaan irraa bade (mee ilaali!).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 25, 'Isaan irraas nama gara kee dhageeffatutu jira. Akka isaan isa hin hubanne onneewwan isaanii irratti haguuggaa, gurra isaanii irratti immoo duudina taasifnee jirra. Odoma mallattoowwan hundaa arganiiyyuu, isheetti hin amananu. hanga kan sitti falman ta''anii sibira dhufanitti, Warri kafare (Qur’aanni) kun ogbarruu warra durii malee waan biraatii miti" jedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 26, 'Isaan isa (Muhammadiin) irraa dhorgu; Isa irraa fagaatan. Lubbuullee isaanii malee homaa hin balleessan; garuu hin beekanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 27, 'Yeroo isaan ibidda irra dhaabaman osoo argitee nijedhan "yaa gaabbii keenya! odoo (addunyaatti) deebifamnee aayatoota Rabbii keenyaas kijibsiisuu dhiifnee mu''umina irraas taanee" (waan rifachiisaa argita ture)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 28, 'Dhugumatti wanti isaan kana dura dhoksaa turan isaaniif mul’ate. silaa Odoo deebifamanii waan irraa dhorgamanitti deebi’u. Isaan kijibdoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 29, 'Ni jedhan."Isheen jireenya keenya kan addunyaati malee waan biraa miti, nuti (du’a booda) hin kaafamnu"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 30, 'Yeroo isaan Gooftaa isaanii fuulduratti dhaabaman odoo argitee (waan rifachiisaa argita ture) "Sila inni kun dhugaa mitii?" jedhe. "Eeyyeen; Gooftaa keenyaan kakannee! dhugaa dha" jedhan. "Waan kafaraa turtaniif (amma) adabicha dhandhamaa!" jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 31, 'Isaan wal qunnamtii Rabbii kijibsiisan dhugumatti hoonga’aniiru. hanga Qiyaamattiin tasa isaanitti dhuftetti nijedhan "Waan ishee (addunyaa) keessatti hanqifneef yaa gaabbii keenya!" isaan badiilee isaanii dugdoowwan isaanii irratti baatan. Dhagayaa! Ba’aan isaanii waa fokkate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 32, 'Jireenyi addunyaa taphaafi qoosaa malee waan biraa miti. Dhugumatti ganda Aakhiraatu caala warra (Rabbiin) sodaataniif. Sila isin hin xiinxaltanuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 33, 'Dhugumatti wanti isaan jedhan si gaddisiisuu ni beekna. Isaan (onnee isaatiin) si hin kijibsiisanu. Garuu miidhaa raawwattoonni keeyyattoota Rabbii mormu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 34, 'Dhugumatti, ergamoonni si duraas kijibsiifamaniiru. Waan kijibsiifaman irrattis ni obsan. Hanga tumsi keenya isaaniif dhufuttis ni rakkifaman. Jechoota Rabbiitiif jijjiiraan hin jiru. Dhugumatti, oduu ergamootaa irraa (hangi tokko) sitti dhufeera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 35, 'Yoo (sirraa) garagaluun isaanii sitti ulfaate, mallattoon isaanitti dhufuuf yoo qaawwa dachii keessa barbaaduu yookiin kortoo samii keessaa dandeesse (raawwadhu). Rabbiin odoo fedhee, (hunda isaanii) qajeeluma irratti walitti isaan qaba. Wallaalaa irraa hin ta’in.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 36, 'Kan owwaatu warruma dhaga’u qofa. Du''aawwan immoo Rabbiin isaan kaasa. Ergasii gara Isaatti deebifamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 37, '"Maaliif mallattoon Gooftaa isaa irraa isa irratti hin buufamne?" jedhu. "Dhugumatti, Rabbiin mallattoo buusuu irratti danda’aa dha" jedhi. Garuu irra hedduun isaanii hin beekanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 38, 'Deddeemtuu dachii keessaas ta''ee simbirroon koola isaa lamaaniin bararus ummatoota akka keessanii malee hin taane. Kitaaba keessatti Nuti homaa hin dhiifne. Ergasii gara Gooftaa isaanii oofamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 39, 'Isaan keeyyattoota keenya kijibsiisan duudaafi arraba qabamaa dukkanoowwan keessa jiraniidha. Rabbiin nama fedhe isa jallisa; nama fedhe immoo karaa qajeelaa irra isa godha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 40, 'Jedhi: mee naaf himaa! "Sila yoo adabbiin Rabbii isinitti dhufe yookiin Qiyaamaan isinitti dhufte, yoo kan dhugaa dubbattan taataniif, waan Rabbiin alaa ni kadhattuu?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 41, 'Dhugumatti Isa qofa kadhattu, yoo fedhe waan isin gara isaatti kadhattan san isin irraa kaasa. Waan qindeessitan ni irraanfattu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 42, 'Dhugumatti, gara ummattoota siin duraatti erginee jirra. Akka isaan (Rabbitti) watwaataniif hiyyummaafi dhukkubaan isaan qabnee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 43, 'Maaliif yeroo adabbiin keenya isaanitti dhufe (Rabbitti) hin watwaatin. Garuu onneewwan isaanii ni gogde. Sheyxaanni waan isaan dalagaa turan isaaniif miidhagse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 44, 'Yeroma isaan waan ittiin gorfaman dagatan, balbaloowwan waan hundaa isaanitti banne; hanga isaan waan kennamaniin gammadanitti odoo hin beekne dafxaa (adabaan) isaan qabne. Isaan yoosuu abdii murattoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 45, 'Booddeen ummata isaan miidhaa hojjatanii murame. Faaruun kan Rabbii Gooftaa aalamaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 46, 'Jedhi: “Mee naaf himaa! Yoo Rabbiin dhageettiifi argituuwwan keessan fudhatee, onneewwan keessan irratti cufe, gabbaramaan Rabbiin alaa isa isiniif fidu eenyu?” Akkamitti keeyyattoota akka ibsinuufi ergasii akkamitti akka isaan gara galan ilaali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 47, 'Jedhi: "Mee naaf himaa! Yoo adabbiin Rabbii tasa yookiin ifatti isinitti dhufe, sila ummata miidhaa hojjattoota malee ni balleeffama?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 48, 'Nuti ergamoota gammachiisoofi dinniinoo taasifnee malee hin erginu. Warri amananiifi toltuu hojjatan sodaan isaan irra hin jiru; isaan hin gaddanus.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 49, 'Isaan keeyyattoota keenya kijibsiisan, waan isaan fincilaa turaniif azaabni isaan tuqa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 50, 'Jedhi: "Kuusaaleen Rabbii ana bira jira isiniin hin jedhu; fagoos hin beeku; ani Maleykaa dhas isiniin hin jedhu. Waan gara kiyya buufame malee hin hordofu. Sila jaamaafi argaan wal qixxaataa? Sila hin xiinxaltanii?" (jedhi).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 51, 'isaan (Qur’aanaan) dinniini warreen gara Gooftaa isaaniitti walitti qabamuu sodaatan, isa (Rabbiin) malee jaalalleefi araarsaan isaaniif hintaane, akka isaan (Rabbiin) sodaataniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 52, 'Warra ganamaafi galgala fuula Isaa barbaaduuf Gooftaa isaanii kadhatan hin ari’in. qormaata isaanii irraa waa tokko sirra hin jiru; qormaata kee irraas waa tokko isaan irra hin jiru, Isaan ariitee miidhaa raawwattoota irraa akka taatuufuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 53, 'Akkasuma garii isaanii gariin mokkorre. Akka isaan jedhaniif. "isaan kana Rabbiin nu gidduudhaa tola itti oolee?". Sila Rabbiin galateeffattoota akkaan beekaa hin taanee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 54, 'Yeroo warri keeyyattoota keenyatti amanan sitti dhufan jedhi "Nageenyi isin irra haa jiraatu. Gooftaan keessan lubbuu Isaa irratti rahmata barreesseera: ‘namni isin irraa wallaalumaan hamtuu hojjatee ergasii isa booda gara Rabbii deebi’ee tolche, dhugumatti Inni (isaaf) araaramaa, (isaaf) rahmata godhaa dha" (jedhi).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 55, 'Akkasumas akka (dhugaan mirkanaa''uu fi) karaan yakkamtootaas ifa ta’uuf jecha keeyyattoota addeessina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 56, '"Ani warra isin Rabbiin ala gabbartan gabbaruu irraa dhorgameera" jedhi. "Ani fedha lubbuu keessanii hin hordofu, yoos dhugumatti ani jalladhe; warra qajeelan irraahii miti" jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 57, 'Jedhi: "Ani ragaa ifa ta’e kan Gooftaa kiyya irraa tahe irran jira. Isin isa kijibsiiftani. Wanti isin arifachiifattan ana bira hin jiru. Murtiin Rabbiif malee hin taane. Inni dhugaa murteessa. Inni irra caalaa murteessitootaati."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 58, 'Jedhi: "Odoo wanti isin arifachiifattan ana bira jiraatee, silaa dhimmichi gidduu kiyyaafi gidduu keessanitti ni murtaa’a ture. Rabbiin miidhaa hojjattoota akkaan beekaadha."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 59, 'Furtuuwwan fagoo (ghaybii) Isa biratti tahe. Isa malee (tokkolleenuu) ishee hin beeku. Inni waan dachii (goggoyduu) keessa jiruufi waan bahra keessa jirus ni beeka. Baala (mukaa) irraa tokkollee inni beeku malee hin buutu. Firiin dukkana dachii keessaa, jiidhaafi gogaanis kitaaba ifa ta’e keessa tahu malee hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 60, 'Inni Isa halkan isin ajjeesuudha (isin raffisuudha); Waan isin guyyaa carraaqxanis ni beeka. Ergasii akka beellamni murtaa''aan dhumuuf isa (guyyaa) keessa isin kaasa. Ergasii deebiin keessan gara Isaati. Ergasii waan isin hojjachaa turtan isinitti hima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 61, 'Inni gabroota Isaa gubbaa ta''ee, hundaa injifataadha. Isin irrattis tiksitoota erga. hanga duuti tokkoon keessanitti dhufe ergamoonni keenya isaan kan (ajaja) hin hanqifne ta''anii isa ajjeesu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 62, 'Ergasiis gara Gooftaa isaanii dhugaa ta''e, gara Rabbii deebifamu. Dhagayaa! murtiin kan Isaa qofa. Innis irra arifataa qorattootaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 63, 'Jedhi: "Sila eenyutu isin baraarsa? dukkanoowwan dachiifi bahraa irraa. kan isin isa waammattan mul''iftaniifi iccitiin ‘yoo kana irraa nu baraarseef, nuti galateeffattoota irraa taana’ (jettanu)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 64, 'Jedhi: "Rabbumatu isheefi rakkoo hunda irraa isin baraarsa. Ergasii isin ni qindeessitu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 65, 'Jedhi: "Inni danda''aadha adabbii gubbaa keessan irraa yookiin miilleen keessan jalaa isin irratti erguu, yookiin garee haala taataniin isin walitti makee garii keessan lola garii dhandhamsiisuu irratti (danda’aadha)." Akka isaan hubataniif jecha akkamitti keeyyattoota akka ibsinu ilaali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 66, 'Odoo inni dhugaa ta''ee jiruu ummanni kee isa kijibsiisan. "Ani isin irratti tiksaa miti" jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 67, 'Oduu hundaaf yeroo itti mirkanaa’utu jira. Fuula dura beektu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 68, 'Yeroo warra keeyyattoota keenya keessa seenan (itti qoosan) argite, irraa garagali, hanga isaan dubbii sanaan alaa keessa seenanitti. Yoo sheyxaanni si dagachiise, yaadannoo booda ummata miidhaa raawwattoota wajjin hin taa’in.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 69, 'Warra (Rabbiin) sodaatan irra dilii isaanii irraa homaayyuu hin jiru. Garuu akka isaan eeggataniif jecha gorsatu (isaaniif jira).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 70, 'Warra amantii isaanii taphaafi qoosaa godhatanii jireenyi addunyaa isaan gowwoomsite isaan dhiisi. Akka lubbuun waan hojjatteen hin banne isaan (Qur’aanaan) gorsi. Rabbii gaditti jaalalleefi araarsaan isaaniif hin taane. Lubbuun hundi odoo kafaltii hunda kafalteeyyuu ishee irraa hin fuudhamu. Isaan sun warra waan hojjataniin balleeffamani. Isaaniif dhugaatii bishaan danfaa irraa ta’eefi adabbii laalessaa ta’etu jira waan kafaraa turaniif jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 71, 'Jedhi: "Sila nuti Rabbii gaditti waan nu hin fayyanneefi nu hin miine gabbarraa? Erga Rabbiin nu qajeelchee booda uf duuba deebinaa? akka isa dhama''aa ta''ee sheyxaanni dachii keessa isa fuudhee, kan isaaf hiriyoonni ''gara keenya kottu'' (jechuun) gara qajeelumaa isa waaman jiranu (kan isaan hin hordofnee san)". Dhugumatti, qajeelfamni Rabbii isatu qajeelfama (sirrii)ti. Nuti Gooftaa aalamatiif akka tole jennu ajajamnee jirra" jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 72, 'Salaata gadidhaabaa, isa sodaadhaa, Innis Isa gara Isaatti walitti qabamtaniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 73, 'Inni Isa samiileefi dachii dhugaan uume. Guyyaa ‘ta’i’ jennaan achumaan ta’u san [yaadadhu]. Jechi Isaa dhugaadha.mootummaan isaaf tahe. Guyyaa xurumbaan afuufamu. Inni beekaa fagoo (gheybii)fi dhihooti. Inni ogeessa, keessa beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 74, '(Yaadadhu) Yeroo Ibraahiim abbaa isaa Azaariin jedhe "sila ati taabotowwan gabbaramoota godhattaa? Dhugumatti, ani siifi ummata kee jallina ifaa keessattiin argaara".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 75, 'Akka kanatti Ibraahiimiin mootummaa samiileefi dachii agarsiifne. Akka (beekee) mirkaneeffattoota irraa tahuuf.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 76, 'Yeroo halkan isa irratti dukkanaa’e, urjii argeetiin "kun Gooftaa kiyya" jedhe. Yeroo inni seenu ani seentota hin jaaladhu" jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 77, 'Yeroma ji’as ba’aa ta''ee argu "kuni Gooftaa kiyya" jedhe. Yeroo inni seenus "odoo Gooftaan kiyya na qajeelchuu baatee silaa ani ummata jallattoota irraan ta’a" jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 78, 'Yeroma aduu tan baate taatee argu "kun Gooftaa kiyya; kanatu irra guddaa dha" jedhe. Yeroo isheen seentu "yaa ummata kiyya! ani waan isin qindeessitan irraa qulqulluudha" jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 79, 'Dhugumatti, ani fuula kiyya qajeelaa haalan ta’een gara Isa samiileefi dachii uumee deebiseen jira; Ani mushrikoota irraa miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 80, 'Ummanni isaas isaan falme [Inni] ni jedhe: "Sila dhugumatti odoo Inni na qajeelchee jiruu isin (waa’ee) Rabbii keessatti na falmituu? Waan isin Isatti qindeessitan hin sodaadhu. Yoo Gooftaan kiyya wahi fedhe malee (homtuu narra hin ga’u) Gooftaan kiyya beekumsa Isaatiin waan hunda waliin ga’eera. Sila hin gorfamtanuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 81, 'Ani akkamittin waan isin qindeessitan sodaadha? Odoo isin waan Inni ragaa isaa isin irratti hin buusin kan qindeesitan hin sodaanne taatanuu, garee lamaan keessaa isa kamtu tasgabbii haqa godhata? Yoo kan beektan taataniif (jedhi).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 82, 'Isaannan amananii, iimaana isaanii shirkiidhaan hin makin isaaniif tasgabbiitu jira. Isaan qajeelfamoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 83, 'Isheen tun ragaa keenya. Ibraahiimiif ummata isaa irratti kenninee jirra. Nama feenes sadarkaawwan keessatti ol fuuna. Dhugumatti, Gooftaan kee ogeessa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 84, 'Isihaaqiifi Ya’aquubiin isaaf kennine. Hundaahuu ni qajeelchine, Sana duras Nuuhiin qajeelchinee jirra. Sanyii isaa irraas Daawuud, Sulaymaan, Ayyuub, Yuusuf, Muusaafi Haaruunin (qajeelchinee jirra). Akka kanatti toltuu hojjattoota mindeessina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 85, 'Zakariyyaa, Yahyaa, Iisaafi Ilyaasiinis (ni qajeelchine). Hundinuu gaggaarii irraayyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 86, 'Ismaa’il, Yasa’i, Yuunusiifi Luuxiinis (qajeelchine). Hundaayyuu aalamoota irra caalchifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 87, 'Abbootii isaanii, ilmaan isaaniifi obboleeyyan isaanii irraas (qajeelchine). Isaan fillee, gara karaa qajeelaa isaan qajeelchinee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 88, 'Kun qajeelloo Rabbiiti. Gabroota isaa irraa nama fedhe isaan qajeelcha. Odoo isaan qindeessanii silaa wanti isaan dalagaa turan isaan jalaa bada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 89, 'Isaan warra nuti kitaaba, ogummaafi nabiyyummaa isaaniif kennineedha, Yoo isaan kun (warri Makkaa) isheetti kafaran, dhugumatti Nuti namoota isheetti kafaroo hintahin isheef qopheessineerra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 90, 'Isaan warra Rabbiin qajeelcheedha. Qajeelfama isaanii hordofi. jedhi Ani isa irratti mindaa isin hin gaafadhu, Inni aalamootaaf yaadannoo malee waanbiraatii miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 91, 'Guddina Isaaf malu Rabbiin hin guddifne. Yeroo "Rabbiin nama irratti homaa hin buufne" jedhan.kitaaba Muusaan ittiin dhufe eenyutu buuse? jedhi. "Ifaafi namootaaf qajeelfama haala ta''een. kan isin waraqaalee heddu isa gootan (Kan feetan) ishee mul''iftu, Heddu immoo ni dhoksitu, Waan isiniifi abbootiin keessan hin beekne beeksifamtanii jirtan" jedhi. "(Kan isa buuse) Rabbuma" jedhi. Ergasii haala isaan dhara isaanii keessa taphataniin isaan dhiisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 92, 'Kunis kitaabanuti isa buufne kan barakaa qabu kan (kitaabota) isa duraa dhugoomsu, (jiraattota) haadha magaalotaa (Makkaa)fi namoota naannoo ishee jiran akka ittiin dinniinuuf. Warri Aakhiratti amanan isatti ni amanu. isaan salaata isaanii irratti tikfatoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 93, 'Nama Rabbi irratti kijiba odeesse caalaa namni miidhaa hojjate eenyu? yookiin odoo wahyiin homaatuu isatti hin beeksifamin "wahyiin gara kiyyatti bu’eera" jedheefi, nama "anis fakkaataa waan Rabbiin buuseetiin buusa" jedhe. Odoo yeroo miidhaa hojjattoonni haguuggaa du’aa keessa ta’an argitee, kan malaykonni harkoowwan isaanii diriirsanii "lubbuu keessan baasaa; har''a isin waan Rabbi irratti dhugaan alaa jedhaa turtaniifi keeyyattoota Isaa irraa boonaa turtaniif, adabbii salphisaa galata galfamtu" (jedhanu argitee dubbii rifachiisaa argita ture).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 94, 'Dhugumatti isin kophaa taatanii gara keenya dhuftaniittu, akkuma yeroo jalqabaa isin uumnetti Wantoota Nuti isiniif kennine hunda dugdoowwan duuba keessanitti dhiiftanii. Nuti manguddoota (taabota) keessan kan isin “kun warra Rabbiin waliin gabbarru” jedhaa turtan isin wajjiin hin arginu. (Hariiroon) gidduu keessanii dhugumatti citeera. Wanti isin himataa turtan isin jalaa badeera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 95, 'Rabbiin baqaqsaa fireetiifi ija tamriiti. (Inni) du’aa irraa fayyaa baasa. Fayyaa irraas du’aa baasaadha. Kun Rabbii keessani. Isin akkamumatti gara galturee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 96, '(Inni) baqaqsaa bariiti, Halkan (yeroo) boqonnaa, aduufi ji’a lakkoofsa (yeroo ittiin beekuuf) godhe. Kun qideessuu (Rabbii) injifataa, beekaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 97, 'Inni (Rabbiin) Isa akka dukkanoowwan dachiifi bahraa keessa isaaniin qajeeltaniif urjiiwwan isiniif godhe sani. Dhugumatti, Nuti keeyyattoota ummata beekaniif addeessinee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 98, 'Inni (Rabbiin) Isa lubbuu takka irraa isin uumeedha. Bakka ragga''iinsaa (gadaamessaa)fi bakka qubsumaa (dugdatu isiniif jira). Dhugumatti, Nuti namoota hubataniif keeyyattoota addeessineerra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 99, 'Inni Isa samii irraa bishaan buuse, Isaanis biqilaa waan hundaa baafnee, isa irraahis magariisa baafne, Isa irraa firii wal koraa, muka Timiraa irraa, daraaraa ishee irraa yudoo dhihoo taate, ashaakiltii inaba irraa ta''e, zaytuuna, rummaana wal fakkaataafi wal fakkaataa hin taane baafna. Mee gara oomisha isaa yeroo inni fireesseefi (gara) bilchina isaas ilaalaa. Dhugumatti, kana keessa ummata amananiif mallattoowwantu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 100, 'Odoo inni isaanis uumee jiruu jinnoota Rabbiif shariikoowwan taasisan; isaan beekumsaan maleetti ilmaan dhiiraafi dhalaa Isaaf (Rabbiif) kijibaan (uuman), Inni wantoota isaan kijibaan Isatti maxxansan irraa qulqulluufi ol ta’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 101, 'Jalqabaa uumama samiileefi dachiiti.Niitii kan hin qabne ta''ee akkamitti ilmoon isaaf ta’a? Waan hundaa uumee, Inni waan hunda beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 102, '(Kan akkana hojjate) kun Rabbii keessani, Isa malee dhugaan gabbaramaan hin jiru, (Inni) uumaa waan hundaatii, Isa (qofa) gabbaraa, Inni waan hunda tiksaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 103, '(Addunyaatti) agartuun (ijji) Isa hin agartu, Inni immoo agartuu hunda ni arga, Inni mararfataa, beekaadha. [1]', '[1] adduniyatti Rabbiin arguun hindandayamu. aakhiratti ammoo mu''imintoonni isa ni argu, kuni qur''aanaafii hadiisaanis mirkanaayee jira.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 104, 'Dhugumatti, Gooftaa keessan irraa ragaawwan ifa ta’an isinitti dhufeera. Namni (ragaawwan kanniin) arge lubbuma isaatiif (itti fayyadama). Namni jaame isheedhuma irratti (miidhaa geessisa). Anii isin irratti tiksaa miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 105, 'Akkanatti keeyyattoota addeessina, qu''ate akka jedhaniifi, ummata beekaniif isa ibsuuf.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 106, 'Waan Gooftaa kee irraa sitti beeksifame hordofi. Isa malee dhugaan gabbaramaan hin jiru; mushrikoota irraas garagali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 107, 'Odoo Rabbiin fedhee, silaa (isatti) hin qindeessanu ture, Isaan irratti tiksaa si hin goone, Ati isaan irratti moosifamaa miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 108, 'Warra isaan Rabbii gaditti gabbaran hin arrabsinaa, Beekumsa maleetti jibbaadhaan Rabbiin arrabsuu, Akka kanatti ummata hundaaf dalagaa isaanii miidhagsine. Ergasii deebiin isaanii gara Gooftaa isaaniiti; waan isaan dalagaa turan isaanitti hima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 109, 'kakuulee isaanii cimaa Rabbitti kakatan "Odoo mallattoon wahii isaanitti dhuftee, silaa isitti amanna" jedhanii, "Mallattoowwan Rabbuma biraayi" jedhi. Yeroo isheen (raajiwwan) dhufte isaan hin amananuu maaltu isin beeksise? (Rabbitu beeka malee isin hin beektanu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 110, 'Onneewwan isaaniitiifi agartuuwwan isaanii gara gaggalchina, Akkuma isaan yeroo jalqabaa isatti hin amanin. Kan dhama''an ta''anii jallina isaanii keessatti isaan dhiifna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 111, 'Odoo Nuti malaykota gara isaaniitti buufnee, du’aawwanis isaaniin haasa''anii, waan hundayyuu isaan duratti walitti qabnellee, isaan yoo Rabbiin fedhe malee kan amananii miti. Garuu irra hedduun isaanii ni wallaalu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 112, 'Akka kanatti nabiyyii hundaafuu diina shayxaana namaafi jinnii irraa ta’an,godheera. kan gowwoomsuuf jecha gariin isaanii gara gariitti jecha miidhagaa beeksisan. Odoo Gooftaan kee fedhee silaa san hin raawwatanu ture. Isaaniifi kijiba isaan uumanis dhiisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 113, 'Akka onneewwan warra Aakhiratti hin amaninii gara isaa dabaniifi, akka isas jaalataniifi (adaba irraa) waan raawwachaa jiranis akka raawwataniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 114, '" Rabbiin alatti murteessaa barbaaddadhaa?, innni kitaaba addeeffamaa gara keessanitti buusee jira " (jedhi). Warri kitaaba isaaniif kennine akka inni dhugaan Gooftaa kee irraa buufame ni beeku. Warra maman irraa hin ta’in.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 115, 'Jechi Gooftaa keetii dhugaafi haqa haala ta''een xumurameera. Jechoota Isaatiif jijjiiraan hin jiru. Inni dhagayaa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 116, 'Yoo irra hedduu namoota dachii keessaa tole jette, karaa Rabbii irraa si jallisu. Isaan shakkii malee homaa hin hordofan. Isaan kijiboo malee homaa hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 117, 'Dhugumatti, Gooftaan kee Isumatu nama karaa Isaa irraa jallatu irra beeka; warra qajeelanis Isumatu beeka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 118, 'Yoo keeyyattoota Isaatti kan amantan taataniif, waan maqaan Rabbii irratti dubbatame irraa qofa nyaadhaa.[1]', '[1] beyladaa yeroo gorra''amtu bismillaah itti jedhame irraa nyaadhaa jechuudha.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 119, 'Sila maaltu isiniif jiraayyi waan maqaan Rabbii irratti dubbatame nyaachuu dhiiftan? dhugumatti, Inni wantoota isin irratti dhorgamaa godhe isiniif addeesseera,Wanti gara isaatti rakkifamtan odoo hafuu. Dhugumatti, (namoonni) baay’een beekumsaan malee fedha lubbuu isaaniitiin jallatu. Dhugumatti, Gooftaan kee Isaatu irra beekaa warra daangaa dabraniiti.', 'abraniiti.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 120, 'Badii ifa bahaafi dhokataa isaas dhiisaa. Dhugumatti, isaannan cubbuu hojjatan waan kijiba uumaniif fuuldura galata galfamu (ni adabamu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 121, 'Waan maqaan Rabbii isarratti hin dubbatamin hin nyaatinaa. Dhugumatti, inni fincila. Dhugumatti, shayxaanonni akka isiniin falmanuuf gara jaalallee isaanii hasaasu. Isin yoo isaaniif ajajamtan dhugumatti isin mushrikoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 122, 'Sila namni du’aa turee ergasii isa jiraachifnee ifaa isaaf goone, kan isaan nama keessa deemu, akka fakkii nama dukkanoowwan keessa jiru, kan ishee irraa hin baanee ta''aa? Akka kanatti kaafirootaaf wanti isaan dalagaa turan miidhagfame.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 123, 'Akkasumas magaalota hunda keessatti gugurdoo jallattoota ishee akka ishee keessatti dhara karoorsaniif goone. Hin beekanu malee, lubbuu isaanii irratti malee dhara hin karoorsanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 124, 'Yeroo mallattoon isaanitti dhufte "hanga fakkaataan waan ergamoonni Rabbii kennamanii nuuf kennamutti hin amannu" jedhu. Rabbiin ergaa Isaa eessa akka kaayu akkaan beeka. Warra badii hojjatan Rabbiin biratti xiqqeenyaafi adabbii cimaa ta’etu (isaan) tuqa.waan isaan dhara karoorsaa turaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 125, 'Namni Rabbiin isa qajeelchuu fedhe, qoma Isaa Islaamaaf bal’isa. Nama isa jallisuu fedhe immoo qoma isaa akkaan dhiphaa, rakkataa akka nama samii keessa ol koruu taasisa. Akka kanatti Rabbiin adabbii warra hin amanne irratti godha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 126, 'Kun qajeelaa haala ta’een karaa Gooftaa keetiiti. Ummata gorfamaniif mallattoo dhugaadhaan adda baafneerra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 127, 'Isaaniif Gooftaa isaanii bira ganda nagayaatu jira. Innis waan isaan dalagaa turaniif jecha gargaaraa isaaniiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 128, 'Guyyaa hunda isaanii walitti qabee "Yaa garee jinnootaa! Namoota daneeffattanii jirtu" (jedhuun yaadadhu). Jaalalleen isaanii kan namoota irraa ta’an "Gooftaa keenya! gariin keenya gariitti qanani''e; beellama keenya Ati nuuf beellamte geenyee jirra" jedhu. "Hanga Rabbiin fedhe malee Ibiddi qubannaa keessani isii keessatti hafoodha" jedha. Dhugumatti Gooftaan kee ogeessa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 129, 'Akka kanatti garii miidhaa hojjattoota garii irratti moosifna. Waan isaan hojjataa turaniif jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 130, '"Yaa garee jinniifi namaa! Sila ergamoonni isin irraa ta’an kan keeyyattoota kiyya isin irratti qara’aniifi qunnamtii guyyaa keessanii kana kan isin dinniinanu isinitti hin dhufnee?" (jedhamu). "Nuti lubbuulee keenya irratti ragaa baanee jirra" jedhan. Jireenyi addunyaa isaan gowwoomsite. Dhugumatti isaan kaafiroota akka turan lubbuulee isaanii irratti ragaa ba’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 131, 'Kun waan Gooftaan kee ganda tokko haala warri ishee dagataa ta''een, badii (isheetiif jecha) kan balleessu hin ta''iniifi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 132, 'Hundaafuu waan hojjattan irraa sadarkaaleetu jira. Gooftaan kee waan isaan dalagan irraa dagataa miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 133, 'Gooftaan kee dureessa, abbaa rahmataati, yoo fedhe, isin adeemsiseeti (dhabamsiiseti) isin booda waan fedhe bakka buusa. Akkuma isin sanyii ummata biraa irraa argamsiise,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 134, 'Dhugumatti, wanti waadaa isiniif galame dhufaadha. Isin kan (adabbii jalaa) dadhabsiisoo hintaane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 135, 'Jedhi. "Yaa ummata kiyya! Akkaataa adeemsa keessanii irratti dalagaa; Anis dalagaadha, Namni manni booddee isaaf ta’u eenyuun akka ta’e fuulduratti ni beektu, Dhugumatti, miidhaa hojjattoonni hin milkaa’anu"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 136, 'Oyruufi beyladoota inni uumerraa qooda Rabbiif godhan. yaaduma isaaniitiin "kun kan Rabbiiti, kun immoo kan gooftolee keenyaati" jedhan. Wanti gabbaramtoota isaaniitiif ta’e gara Rabbiitti hin ga’u; wanni Rabbiif ta’e immoo gara gabbaramtoota isaaniitti ni ga’a, Wanti isaan murteessan waa fokkate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 137, 'Akka kanatti shariikonni isaanii hedduu mushrikoota irraa ta''aniif ajjeechaa ilmaan isaanii miidhagseef, isaan balleessuufi amantii isaanii isaan irratti walitti makuuf jecha. Odoo Rabbiin fedhee hin raawwatanu ture. isaan dhiisi waan isaan kijibanis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 138, 'Nijedhan Yaada isaaniitiin kun horiifi oyruu dhorgamtuudha; Nama nuti feene malee ishee hin nyaatu, (kun) horii dugdi ishee (yaabbii irraa) dhorgamteedha; (kun immoo) horii maqaa Rabbii isii irratti hin dubbannee dha" (jedhan), Rabbi irratti kijiba uumuuf (kana hojjatan). Rabbiin waan isaan kijibaa turaniin fuulduratti galata isaanii galcha (isaan adaba)..', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 139, 'Ni jedhan: "Wanti garaalee horii kanneen keessaa dhiirota keenya qofaaf (hayyamamtuudha); dubartoota keenya irratti immoo dhorgamoodha, Yoo du’aa ta’e, isaan (hunduu) isa keessatti shariika" Ibsa isaaniitiin (kijiba Rabbi irra kaa''aniin) (adabbiin) galata isaanii galcha. Inni ogeessa, beekaadha', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 140, 'Dhugumatti hoonga’aniiru Warri doofummaan beekumsaan amalee ilmaan isaanii ajjeesan, Rabbiin irratti kijiba maxxansuun waan Rabbiin isaaniif kenne haraama taasisan, Isaan jallataniiru; qajeeloo hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 141, 'Rabbiin isa ashaakiltii sireen godhamuufiifi sireen hin godhamneef uumeedha. Muka timiraa, sanyii, dhandhamni wal dhabaa ta''e, Zaytuunaafi Rummaana wal fakkaataniifi wal hin fakkaannes (kan uumee dha). Firee isaa irraa yeroo inni fireesse nyaadhaa; guyyaa haamama isaas haqa isaa (zakaa) kennaa. (Kennaan) daangaa hin dabrinaa. Inni warra daangaa dabran hin jaalatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 142, 'beeyladoota irraa isaan fe’isaaf oolaniifi fe’isaaf hin oolle (uume). Waan Rabbiin isiniif kenne irraa nyaadhaa; tarkaanfiilee shayxaanaas hin hordofinaa. inni isiniif diina ifa bahaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 143, 'Qindiiwwan saddeeti (uumne): hoolaa irraa lama (kormaafi dhalaa), Re’ee irraas lama (kormaafi dhalaa). "Sila (Rabbiin) korma lamaan haraam godhe moo dhaltuu lamaani? Moo waan gadaamessi dhaltuu lamaanii of keessaa tti qabatte? Yoo kan dhugaa dubbattan taataniif, beekumsaan naaf himaa" jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 144, 'Gaala irraas lama, Loon irraas lama (kormaafi dhalaa uume). jedhi "Sila (Rabbiin) korma lamaan dhorge moo dhaltuu lamaani? Moo waan gadaamessi dhaltuu walitti qabatte? Moo yeroo Rabbiin kanatti isin ajaju hirmaataa turtani? Nama beekumsa malee namoota jallisuuf jecha Rabbiin irratti kijiba odeesse caalaa namni miidhaa hojjate hin jiru. Dhugumatti, Rabbiin ummata miidhaa hojjattoota hin qajeelchu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 145, 'Jedhi: "Ani waan gara kiyyatti wahyii godhame keessatti nama isa nyaatu irratti dhorgamaa hin argu yoo du’aa (baktii) yookiin dhiiga dhangala’aa yookiin foon Booyyee, inni najisa, yookiin fincila waan Rabbiin alaatiif gorra’ame malee ." Namni halaalaa jiruu haraamatti darbuufi nyaata keessatti daangaa dabruun maletti rakkifame dhugumatti, Gooftaan kee araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 146, 'Warra yahuudoman irratti abbaa qeensaa hunda haraama taasifnee jirra. Sa''aa, busaa''ee (re’eefi hoolaa) irraas cooma isaan lamaanii, isaan irratti haraama taasifnee jirra, waan dugdi isaaniitiifi marrimaan isaanii baatte (malee) yookiin waan lafeetti makame malee. Kana daangaa dabruu isaaniitiif isaanii galata galchine (isaan adabne). Nuti dhugaa dubbatoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 147, 'Yoo isaan si kijibsiisan "Gooftaan keessan abbaa rahmata bal’aati, adabbiin Isaaa ummata yakkamaa irraa hin deebifamu" jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 148, 'Isaannan qindeessan fuulduratti ni jedhu "odoo Rabbiin fedhee, silaa nutis ta’ee abbootiin keenya hin qindeessinu turre, Wanta tokkos haraama hin taasifnu turre. Akkasuma warri isaan dura turan hanga adabbii keenya dhandhamanitti kijibsiisan. jedhi "Sila beekumsa irraa inni isin nuuf baasuu (fiduu) dandeessan isin bira ni jiraa? Shakkii malee homaa hordofaa hin jirtanu, Isin kijiboo malee hin taane".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 149, 'Jedhi "Ragaan guutuun kan Rabbiiti, Inni odoo fedhee, silaa hunda keessan ni qajeelcha ture" .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 150, 'Jedhi: "Mee ragoota keessan kan akka Rabbiin waan kana haraama taasise ragaa ba’an fidadhaa, Yoo isaan ragaa ba’an, ati isaan waliin ragaa hin ba’in, Fedha lubbuu warra keeyyattoota keenya kijibsiisanii,hin hordofin, warra Aakhiraatti hin amanneefi isaan (qaamota biraa) Gooftaa isaanii wajjin wal qixxeessan (hin hordofin)"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 151, 'Jedhi: "Kottaa! Waan Gooftaan keessan isin irratti haraama godhen isin irratti qara’a: Isatti waa qindeessuu dhiisuu, abbaafi haadhatti tola ooluu, ilmaan keessan beelaaf jecha hin ajjeesinaa, Nutu isiniifi isaanis soora; wantoota fokkatoo ta’an kan mul’ates ta’ee waan dhokate itti hin dhihaatinaa; lubbuu Rabbiin (ajjeesuu) haraama godhes haqaan maleetti hin ajjeesinaa, Isa san isa isiniif dhaame akka xiinxaltaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 152, 'Qabeenya yatiimaa yoo toltuudhaan ta’e malee hanga inni umrii cimina isaa ga’utti itti hin dhihaatinaa; safaraafi miizaana haqaan guutaa, Nuti lubbuu tokkos dandeettii isii malee hin dirqisiifnu, yeroo jettan (ragaa kennitan), haqa dalagaa Odoma fira dhihoo ta’ellee. Waadaa Rabbiis guutaa. Kana akka isin yaadattaniif isinii dhaama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 153, 'Dhugumatti, kun karaa kiyya Isa qajeelaa dhaa, isa hordofaa, karaalee (jallinaa) hin hordofinaa Karaa Rabbii irraa isin baasanii, Kana akka isin sodaattaniif isa isiniif dhaama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 154, 'Eegasii muusaaf kitaaba kennine Isaan toltuu hojjatan irratti (ni’imaa keenya) guutuuf, waan hunda addeessuuf, qajeelfamaafi rahmata gochuuf, akka isaan qunnamtii Gooftaa isaanitti amananiif .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 155, 'Kun kitaaba Nuti buufne kan barakeeffameedha, Kanaafuu isa hordofaa, (Rabbiin) sodaadhaa, Akka rahmanni isiniif godhamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 156, 'Akka isin hin jenneefi (Arabni amantii hin qabne) "kitaabichi kan buufame garee lamaan nu duraa irratti, nuti qo’annoowwan isaanii irraa wallaaloodha" .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 157, 'Yookiin akka isin hinjenneefi "nuti odoo kitaabni nurratti buufamee dhugumatti silaa isaan (yahuudotaafi kiristaanota) caalaa qajeella turre" (hin janneefi), Dhugumatti, ragaan ifa ta’e (Qur’aanni), qajeelfamaafi rahmanni Gooftaa keessan irraa isiniif dhufeera. Nama keeyyattoota Rabbii kijibsiiseefi ishee irraa gara gale caalaa namni miidhaa hojjate eenyu? Nuti warra keeyyattoota keenya irraa gara galan sababaa isaan gara galaa turaniif adabbii hamaa isaanii galata galchina (adabna)..', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 158, 'Sila ni eeganii malaaykonni isaanitti dhufuu malee, yookiin Gooftaan kee dhufuu, yookiin gariin mallattoolee Gooftaa keetii dhufuu (malee). Guyyaa gariin mallattoolee Gooftaa keetii dhufu lubbuu tokko iimaanni ishee homaa ishee hin fayyadu tan san dura hin amanin, yookiin iimaana ishee keessatti toltuu hin hojjatin,"Isin eegaa; Nuti eegoo dha" jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 159, 'Dhugumatti, warri amantii isaanii qoqqoodaniifi garee garee ta''an, ati waan tokko keessattillee isaan irraayii miti, Dhimmi isaanii gara Rabbiiti, ergasii Inni waan isaan dalagaa turan (hunda) isaanitti hima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 160, 'Namni toltuun dhufe, isaaf (toltuu) fakkaattuu ishee kudhantu jira. Namni hamtuun dhufe, inni fakkaattuu ishee malee hin galateeffamu, Isaan hin miidhamanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 161, 'Jedhi "Dhugumatti, ani Gooftaan kiyya na qajeelchee jira gara karaa qajeelaa, amantii sirrii kan karaa Ibraahiim, ‘haniifa’ (Rabbii tokkicha gabbaruu) ta’etti, Inni mushrikoota irraa hin turre".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 162, 'Jedhi: "Dhugumatti salaanni kiyya, ibaadaan kiyya, jireenyi kiyyaafi duuti kiyyas Rabbii Gooftaa aalama qofaafi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 163, 'Shariikni isaaf hin jiru; isuma kanattin ajajame; ani jalqaba Muslimootati."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 164, 'Jedhi: "Sila ani Rabbiin ala Gooftaa biraa barbaadaa odoo Inni Gooftaa waan hundaa ta’ee jiru? Lubbuun hundi isheedhuma irratti malee (badii) hin hojjattu. (Lubbuun) ba’aa (badii) baadhattu takka ba’aa tan biraa hin baadhattu, Ergasii gara Gooftaa keessaniiti deebiin keessan, Wantoota isin isa keessatti wal dhabaa turtan (hunda) isinitti hima."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 165, 'Rabbiin Isa dachii keessatti bakka bu’oo isin godhe; sadarkaa keessatti garii keessan garii irra ol fuudhe isin qormaatuuf jecha waan isinii kenne keessatti, Dhugumatti, Gooftaan kee daddafsiisaa adabbiiti; ammas Inni araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 1, 'Alif Laam Miim Saad', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 2, '(Kun) kitaaba gara keetti buufame,Isa (geessuu) irraa qoma kee keessa dhiphinni hin jiraatin, Akka isaan akeekkachiiftuufi mu’uminootaaf gorsa ta’uuf (buufne)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 3, 'Waan Gooftaa keessan irraa gara keessanitti buufame hordofaa, Jaalalleewwan (biraa) isaa gaditti hin hordofinaa, Xiqqoo qofa gorfamtu', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 4, 'Magaalota irraa kan Nuti balleessinee meqaa meeqa (hedduudha), kan adabbiin keenya halkan yookiin guyyaa isaanii rafuutti jiruu isheetti dhufe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 5, 'Yeroo adabbiin keenya isaanitti dhufu jechi isaanii "nuti miidhaa raawwattoota turre" jechuu malee waan biraa hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 6, 'Dhugumatti, isaan (ergamaan) gara isaaniitti ergame ni gaafanna; ergamootas ni gaafanna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 7, 'Dhugumatti, (guutuu seenaa isaanii) beekumsaan isaan irratti odeessina, Nuti (kana irraa) fagoo hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 8, 'Madaalli guyyaa san dhugaadha. Namni madaalli (hojii gaarii) isaa ulfaatte, isaan sun isaanumatu milkaayoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 9, 'Namni madaalli (hojii gaarii) isaa salphatte immoo, isaan sun warra waan keeyyattoota keenya miidhaa turaniif lubbuu isaanii hoongessaniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 10, 'Dhugumatti, dachii keessa isinii mijeessinee ishee keessas waan ittiin jireenyaa isiniif gooneerra; Galateeffannaan keessan xiqqoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 11, 'Dhugumatti, isin uumneerra, Ergasiis isin bocne, Ergasiis maleykotaan "Aadamiif sujuudaa" jenne, Achumaan sujuudani; Ibliis malee, Inni warra sujuudan irraa hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 12, '(Rabbis) "Yeroo ani si ajaju, sujuuduu irraa maaltu si dhorge?" jedhe, (Ibliis) "Anatu isa caala; Ibidda irraa na uumteetiin isa dhoqqee (biyyee) irraa uumte" jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 13, '(Rabbiinis) "ishee irraa bu’i; Ishee keessatti boonuun siif hin taane; bahi ati warra salphattoota irraayi" jedheen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 14, '(Ibliis) "Hanga guyyaa isaan kaafamaniitti na tursiisi" jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 15, '(Rabbiin) "Ati warra tursiifaman irraayi" jedheen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 16, '(Ibliis) ni jedhe: "Waan ati na jallifteef, Dhugumatti, karaa kee qajeeloo irran isaaniif taa’a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 17, 'Ergasii fuuldura isaanii, duuba isaanii, mirgaawwan isaaniitiifi bitaawwan isaanii irraan isaanitti dhufa. Irra hedduu isaaniis galateeffattoota ta''anii hin argitu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 18, '(Rabbiinis) ni jedhe: "Ishee irraa arrabsamaa, fageeffamaa haala taateen ba’i, Isaan irraa namoota si hordofe, isin hunda irraan Jahannama guuta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 19, 'Yaa Aadam! Atiifi niitiin kee jannata keessa taa''aa; iddoo feetan irraas nyaadhaa. Miidhaa raawwattoota irraa taatu mukattii tanatti immoo hin dhihaatinaa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 20, 'Shayxaanni isaan lamaanitti hasaase isaanitti mul’isuuf waan isaanirraa dhokate qaama saalaa isaanii irraa; nijedhe "Rabbiin keessan mukattii kana irraa waa isin hindhoorgine akka isin lamaan malaykota hin taaneef malee, yookiin akka isin lamaan hafoo hin taaneefi malee".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 21, '"Dhugumatti, ani isiniif warra toltuu yaadan irraayi" (jechuun) isaan lamaaniif kakate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 22, 'Gowwoomsuun isaan jallise, Yeroma isaan mukattii dhandhaman, qaamni saalaa isaanii isaanitti mul''atte; isaanis qaama isaanii baala jannataatiin haguuguutti seenan, Gooftaan isaanii isaanitti lallabe "Sila Ani mukattii tana irraa isin hin dhorginee; shayxaanni isin lamaanif diina ifa ta’e isiniin hin jennee?" (jedheen).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 23, '"Gooftaa keenya! lubbuu keenya miinee jirra. Yoo ati nuuf hin araaramneefi rahmata nuuf hin goone, nuti Dhugumatti, warra hoonga’an irraa taana" jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 24, '(Rabbiin) ni jedhe: "Gariin keessan gariif diina haala taataniin bu’aa, Isiniif dachii irra qubsumaafi qananii hanga yeroo murtaa’ee ta''eetu jira."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 25, '"Isheedhuma keessa jiraattu; ishee keessattis duutu; ishee irraas baafamtu" jedheen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 26, 'Yaa ilmaan Aadam! Nuti uffata qaama saalaa keessan haguuguufi faaya isin irratti buufnee jirra. Uffata sodaa Rabbii, saniitu caala. Kun mallattoowwan Rabbii irraayi; akka isaan yaadataniif (isaaniif himne).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 27, 'Yaa ilmaan Aadam! akka shayxaanni isin hin mokkorre, Akka abbaafi haadha keessan jannata irraa baasetti, uffata isaanii isaan irraa mulqee qaama saalaa isaanii isaanitti mul’isuuf. Dhugumatti, inniifi gosti isaa iddoo isin isaan hin agarre irraa isin argu. Nuti isaan hin amanneef shayxaanota jaalallee goonee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 28, 'Yeroo waan fokkattuu hojjatan "abbootii keenya ishee irratti agarre; Rabbiinis isheetti nu ajaje" jedhu. "Rabbiin fokkatuuwwanitti hin ajaju, Sila isin waan hin beekne Rabbi irratti jettuu?" jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 29, 'Jedhi "Gooftaan kiyya haqatti ajaje. Masjida hunda biratti fuulleen keessan (ibaadaaf gara isaa) sirreessaa. Amantii keessan isaaf qulqulleessaa haala taataniin isa gabbaraa, Akkuma isin jalqabetti deebitu"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 30, 'Garee tokko ni qajeelche; garee biraa immoo jallinni isaan irratti mirkanaa’e, Dhugumatti, isaan Rabbii gaditti shayxaanota jaalalleewwan taasifatan, Isaan qajeeltota uf sehan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 31, 'Yaa ilmaan Aadam! Masjida hunda birattuu bareechifannaa (uffata) keessan qabadhaa. Nyaadhaa, dhugaa, daangaa hin dabrinaa, Inni daangaa dabritoota hin jaalatu.[1]', '[1] yeroo salaataa hunda uffata gayaa barbaachisaa uffadhaa jechuudha.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 32, '"Namni bareechifannaa (uffata) ishee Rabbiin gabroota Isaatiif baaseefi soorata irraas gaggaarii dhorge eenyu?" jedhi. Isheen jiruu addunyaa keessatti warra amananiifi Guyyaa Qiyaamaa dhuunfaa isaaniiti" jedhi, Akka kanatti keeyyattoota ummata beekaniif addeessina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 33, 'Jedhi: "wanti Gooftaan kiyya haraama godhe gochaalee fokkatoo, isherraa waan mul''ateefii waan dhokate, dilii, haqaan maletti roorrisuu, waan inni ragaa isaaf hin buusin Rabbitti qindeessuufi Rabbi irratti waan hin beekne jechuudha."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 34, 'Ummata hundaafuu yeroo murtaa’etu jira. Yeroo beellamni isaanii dhufe sa’aatii tokko booda hin aanfamanu; duras hin dabranu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 35, 'Yaa ilmaan Aadam! Yoo ergamoonni isin irraa ta’an isinitti dhufan kan keeyyattoota kiyya isin irratti qara’an, namni (Rabbiin) sodaatee toltuu hojjate, sodaan isaan irra hin jiru; isaan hin gaddanus.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 36, 'Warri keeyyattoota keenya kijibsiisanii ishee irraa boonan, sunniin warra ibiddaati; isaan ishee keessatti hafoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 37, 'Nama Rabbiin irratti kijiba uume yookiin keeyyattoota Isaa kijibsiise caalaa namni miidhaa hojjate eenyu? (tokkolleenuu hinjiru). Sunniin qoodni isaanii kitaaba irraa haala ta''een isaan dhaqqaba; Ergamoonni keenya lubbuu isaanii kan fuudhan ta''anii yeroo isaanitti dhufan "Warri Rabbii gaditti gabbaraa turtan eessa jiru?" jedhu. "Nurraa badaniiru" jedhu. Isaan kaafiroota tahuu lubbuu isaanii irratti ragaa ba’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 38, '(Rabbiin) ni jedha: "Isin ummatoota isin dura dabran keessa seenaa kan jinnootaafi namoota irraa ta’an ibidda keessatti (tahaa). " Ummanni wahii dhawaata seentuun obboleettii ishee (kan ishee jallifte) abaarti, Yeroo hundi isaanii ishee keessatti walitti qabamanitti isheen boodaa ishee duraatiin "Gooftaa keenya! Isaan kun nu jallisanii jiru, Kanaaf adabbii dachaa ta’e ibidda irraa isaaniif kenni" jette, (Rabbiinis) "Hundaafuu dachaatu jira, Garuu isin hin beektanu" jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 39, 'Warri jalqaba isaanii warra booda isaaniitiin ni jette "isiniif nurra caaliinsi wahii hin taane; Waan hojjachaa turtaniif jecha adabbii dhandhamaa".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 40, 'Dhugumatti, isaan keeyyattoota keenya kijibsiisaniifi ishee irraa boonan, balballan samii isaaniif hin banamtu. Hanga gaalli qaawwa lilmoo keessa seenutti jannatas hin seenanu. Akka kanatti yakkamtoota (adabbiin) galata galchina..', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 41, 'Isaaniif Jahannam irraa firaashiitu jira, gubbaa isaaniitii immoo haguuggiitu (jira). Akka kanatti miidhaa raawwattoota (adabaan) galata galchina..', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 42, 'Isaannan amananii, gaggaarii hojjatan, Nuti lubbuu takkas dandeettii ishee malee hin dirqisiifnu; isaan sun warra jannataati, Isaan ishee keessatti hafoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 43, 'Jibbaarraa waan qomoota isaanii keessa jirus ni baafne, Laggeen jala (gamoo) isaanii yaati, "Faaruun kan Rabbii kanaaf nu qajeelcheeti, Odoo Rabbiin nu qajeelchuu baatee hin qajeellu turre; ergamoonni Rabbii keenyaa dhugaadhaan dhufteetti" jedhan. nilallabaman "Jannata tana dhaalchifamtan sababa waan hojjataa turtaniitiif".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 44, 'Warri jannataa warra ibiddaatti lallabu "Nuti Dhugumatti, waan Gooftaan keenya waadaa nuuf gale dhugaa haala ta’een arganneerra. Isin waan Gooftaan keessan waadaa isiniif gale haala dhugaa ta’een argattanii jirtuu?" (jedhaniin). "Eeyyeen" jedhan. Lallabaan gidduu isaaniitti ta’e nilallabe "Abaarsi Rabbii miidhaa hojjattoota irra haa jiraatu" (jedhe).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 45, '(Isaan) warra karaa Rabbii irraa deebisaniifi akka isheen jallattu fedhaniidha, Isaan Aakhiratti kafaroodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 46, 'Gidduu isaanii haguuggaatu jira, ''A’araaf'' irras dhiirota hundayyuu mallattoo isaanitiin beekantu jiru, Warra jannataatti lallabu "nageenyi isin irratti haa jiraatu" jechuun. Isaan (warri a’araaf) haala kan ishee kajeelan ta''aniin ishee hin seenne. [1]', '[1] A''iraaf jechuun jogolla jannataafii azaaba jiddutti taheedha. isarra ummata toltuufii hamtuun isaanii walqixxaatteetu taa''a. isan warra ibiddaatiifii jannataatis ni argan, mallattoo isaaniitiin beekan, jannata hinseenne garuu nikajeelan.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 47, 'Yeroo ijji isaanii gara warreen ibiddaa deebifamte "Gooftaa keenya! Ummata miidhaa hojjattoota wajjiin nu hin taasisin" jedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 48, 'Warri a’araaf dhiirota mallattoo isaanitiin beekanitti lallaban, "(Qabeenya) walitti qabuun keessaniifi wanti isin boonaa turtan waa isin hin fayyanne" jedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 49, 'Sila isaan kun warra Rabbiin rahmataan isaaniif hin godhu jettanii kakattaniidhaa? Jannata seenaa, sodaan isin irra hin jiru; isinis kan gadditanu hin taane (jedhamu)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 50, 'Warri ibiddaa warra jannataatti lallabu "Bishaan irraa yookiin waan Rabbiin isinii hire irraa nurratti dhangalaasaa" jedhu, "Dhugumatti, Rabbiin isaan lamaan kaafiroota irratti haraama taasiseera" jedhaniin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 51, '(Isaan) warra amantii isaanii qoosaafi tapha godhatanii jireenyi addunyaa isaan gowwoomsiteedha, Akkuma isaan walqunnamtii guyyaa isaanii kana irraanfataniifi keeyyattoota keenya mormaa turan guyyaa har''aa isaan irraanfanna (dhiifna)..', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 52, 'Dhugumatti, Nuti kitaaba beekumsaa wajjiin isa addeessineen isaanitti dhufnee jirra, haala qajeelumaafi rahmata ummata amananiif ta''een. [1]', '[1] kitaabni suni qur''aana kabajamaadha.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 53, 'Sila isaan xumura isaa malee maal eegaaru? Guyyaa xumurri isaa dhufu warri san dura isa dagatan nijedhu "Dhugumatti, ergamoonni Gooftaa keenyaa dhugaan dhufteetti, Sila araarsonni nuuf araarsan nuuf jiraa? Yookiin dalagaa isa hojjataa turreen alaa hojjachuuf (gara addunyaatti) deebifamnaa?" (jedhu), Dhugumatti, lubbuulee isaanii hoongessanii jiru. Wanti isaan kijibaan uumaa turan isaan jalaa badeera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 54, 'Dhugumatti, Gooftaan keessan Rabbii Isa samiifi dachii guyyoota jaha keessatti uumee, ergasii Arshii irratti (ol ta’iinsa isaaf malu) ol ta’eedha. Haala ariitiidhaan isa barbaada ta''een halkaniin guyyaa haguugsisa. Aduu, ji’aafi urjiiwwan kan ajaja Isaatiin laaffifaman ta''anii (isaan uume). Dhagayaa! Uumuuniifi ajajnis kan Isaati. Rabbiin Gooftaa aalamaa ta’e barakaan isaa baay’ate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 55, 'Gooftaa keessan gadi of qabuufi dhoksaadhaan kadhaa. Inni daangaa dabritoota hin jaalatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 56, 'Dachii irrattis erga isheen toltee booda hin balleessinaa. Sodaafi kajeellaadhaan Isa kadhaa. Dhugumatti, rahmanni Rabbii warra toltuu hojjatanutti dhihoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 57, 'Inni Isa bubbeewwan gammachiisaa taasisee rahmata Isaa dura erguudha. Yeroo isheen duumessa ulfaataa baadhatte gara biyya duuteetti oofna; bishaan isatti buusuun fuduraalee hunda isaan baafne, akka kanatti du’aa (awwaala irraa) kaafna.Akka isin gorfamtaniif jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 58, 'Biyyi gaariin biqilaan isaa hayyama Gooftaa isaatiin baha, Inni bade immoo (biqilaan isaa) dadhabbiidhaan malee hin bahu, Akka kanatti keeyyattoota namoota galateeffataniif addeessina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 59, 'Dhugumatti, Nuti Nuuhiin gara ummata isaatti erginee "Yaa ummata kiyya! Rabbiin qofa gabbaraa Isa malee gabbaramaan biraa isiniif hin jiru, ani adabbii guyyaa guddaan isin irratti sodaadha" jedheen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 60, 'Qondaalonni ummata isaa irraa ta’an "Dhugumatti, nuti jallina ifa galaa keessatti si argina" jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 61, '(Nuuhis) ni jedhe: "Yaa ummata kiyya! Ani jallinni homaatuu natti hin jiru, Garuu ani ergamaa Gooftaa aalamaa irraa ta’eedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 62, 'Ergaalee Gooftaa kiyyaan isin dhaqqabsiisa; toltuus isiniifin yaada, Rabbi irraa waan isin hin beeknen beeka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 63, 'sila ni dinqisiifattanii gorsi Rabbii keessan irraa ta’e isinitti dhufuu, nama isin irraa ta’e tokko irratti,akka isin akeekkachiisuuf, akka Rabbiin sodaattaniifi akka mararfatamtaniif (isaaniin jedhe).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 64, 'Isa kijibsiisan, Isaafi warra doonii keessa isa waliin ta’an ni baraarsine, Isaan keeyyattoota keenya kijibsiisan immoo bishaaniin dhidhimsine, isaan ummata jaamaa turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 65, 'Gara Aad obboleessa isaanii Huud (erginee) "Yaa ummata kiyya! Rabbiin qofa gabbaraa; Isa malee gabbaramaan biraa isiniif hin jiru, Sila hin sodaattanuu?" jedheen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 66, 'Ummata isaa irraas qondaalonni warra kafaranii "Dhugumatti, nuti gowwummaa keessatti si argina, Dhugumatti, kijibdootaa irraa ta''uu kees yaanna" jedhaniin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 67, '(Huudis) ni jedhe: "Yaa ummata kiyya! Ani gowwummaan homaatuu natti hin jiru, Garuu ani ergamaa Gooftaa aalama hundaa irraa ta''eedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 68, 'Ergaalee Gooftaa kiyyaan isin dhaqqabsiisa, Anis isiniif tola yaadaa, amanamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 69, 'sila nidinqisiifattanii gorsi Rabbii keessan irraa tahe isinitti dhufuu nama isin irraa ta''e irratti (bu''ee) akka isin diyniinuuf jecha. yaadadhaa Yeroo Inni ummata Nuuh booda bakka bu’oota isin taasiseefi uumama keessattis bal''ina isiniif dabale (yaadadhaa).qananiilee Rabbii yaadadhaa Akka milkooftaniif jecha ."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 70, 'nijedhan "sila nutti dhuftee Akka nuti Rabbiin tokkicha Isaa gabbarruufi, wantoota abbootiin keenya gabbaraa turanakka dhiifnuuf?waan ittiin nu sodaachiftu san nutti fidi Yoo warra dhugaa dubbatu irraa taateef "', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 71, 'nijedhe "Dhugumatti, adabniifi dallansuun Gooftaa keessan irraa isin irratti bu’eera, Sila isin maqaalee keessatti na mormituu kan isiniifi abbootiin keessan ishee moggaaftan, kan Rabbiin isheedhaan ragaa hin buusin? Eegaa; ani isin wajjin warra eegan irraayii".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 72, 'Isaafi warra isa waliin turan rahmata nurraa ta’een nagaa baafne, Warra keeyyattoota keenya kijibsiisaniifi hundee isaanii murre.isaan mu’uminootas hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 73, 'Gara Samuuditti obboleessa isaanii Saalihiin (erginaan) ni jedhe: "Yaa ummata kiyya! Rabbiin qofa gabbaraa. Isa malee gabbaramaan biraa isiniif hin jiru. Dhugumatti, Gooftaa keessan irraa mallattoon ifaa taate isinitti dhuftee jirti. Kun haala mallattoo isiniif taateen gaala Rabbiitii, ishee dhiisaa dachii Rabbii keessa haa nyaattu, Hamtuun ishee hin tuqinaa adabbii laalessaatu isin qabata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 74, 'Yeroo Inni Aadiin booda bakka bu’oota isin taasiseefi dachii keessa isin jiraachise yaadadhaa. Dirree ishee irraa gamoowwan ijaarrattu; gaarreen irraas qottaniitin manneen taasiftu. qananiilee Rabbii yaadadhaa; badii raawwataa taatanii dachii keessa hin balleessinaa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 75, 'nijedhe qondaalonni warri boonan ummata isaarraa warra hacuucaman irraa warra amananiin "sila Saalih Rabbii isaa biraa ergamuu ni beektuu?". "(Eeyyeen) Nuti waan inni ittiin ergametti amanoodha" jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 76, 'Isaannan boonan "Dhugumatti, nuti isa isin itti amantan sanatti kafarreerra" jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 77, 'Yeroma san gaalattii waraanan; ajaja Gooftaa isaanii irraa bahanii "Yaa Saalih! Yoo ergamtoota irraa taateef waan ittiin nu sodaachiftu nutti fidi" jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 78, 'Yeroma san sochiin (kirkirri) dachii isaan qabatte; manneen isaanii keessatti jilbeenfatanii (dhumanii) bariisifatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 79, '(Saalihis) isaan irraa gara galee "Yaa ummata kiyya! Dhugumatti, ani ergaa Gooftaa kiyyaa isin dhaqqabsiiseera; tolas isiniif yaadeera, Garuu isin nama toltu isiniif yaadu hin jaalattanu" jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 80, 'Luuxiinis, yeroo inni ummata isaatiin jedhe [yaadadhaa]: "Sila isin badii fokkataa aalama irraa (namni) tokkoyyuu isheedhaan isin hin dursin raawwattuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 81, 'Dhugumatti, isin fedhii saalaatiif dubartii dhiiftanii dhiiratti dhuftuu! Dhugumatti, isin ummata daangaa dabroodha."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 82, 'Deebiin ummata isaas "magaalaa keessan irraa isaan baasaa; isaan Dhugumatti, ummata qulqulleeffatanuu dha" jechuu malee homaa hin turre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 83, 'Isaafi maatii isaa nagaya baasne. Niitiin isaa malee isiin warra (adabbii keessatti) hafan irraa taate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 84, 'Rooba (adabaas) isaan irratti roobsifne, Booddeen yakkamtootaa akkam akka ta’e ilaali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 85, 'Gara Madyan obboleessa isaanii Shu’aybiin (erginee) ni jedhe: "Yaa ummata kiyya! Rabbiin qofa gabbaraa, Isa malee gabbaramaan biraa isiniif hin jiru. Dhugumatti, ragaan ifa taate Rabbii keessanirraa isiniif dhuftee jirti, Safaraafi madaalas guutaa, Namoota wantoota isaanii jalaa hin hir’isinaa. Dachii keessatti erga toluu isheetii hin balleessinaa, sanatu isiniif caala Yoo mu’uminoota taatan .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 86, 'Karaa hunda irraa hin taa’inaa Namoota sodaachisuufi karaa Rabbii irraas namoota isatti amanan deebisuun, akka isheen jallattu kan barbaaddan taatanii. yaadadhaa yeroo xiqqoo turtanii isin baay’esse. Booddeen warra badii raawwatanii akkam akka ta’e ilaalaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 87, 'Yoo gareen isin irraa ta’e tokko waan ani ittiin ergametti amananii gareen biraa immoo hin amanin hanga Rabbiin gidduu keenyatti murteessutti obsaa, Innis irra caalaa warra murteessaniiti" (isaaniin jedhe).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 88, 'Nijedhan ummata isaa irraa qondaalonni warra boonanii "Yaa Shu’aybi! nuti dhugumatti, siifi isaan si waliin amananis magaalaa teenya irraa ni baafna; yookiin isin (hunduu) gara amantii keenyaa deebi’uu qabdu" jedhan"Sila odoo kan jibbinus taanee moo!" jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 89, '" Dhugumatti Rabbiin irratti kijiba uumnee jirra yoo gara amantii keessanii deebine, erga Rabbiin ishee irraa nu baraarsee booda,ishee keessatti deebi’uun nuuf hin taane yoo Rabbiin Gooftaan keenya fedhe malee. Gooftaan keenya beekumsaan waan hunda bal''atee jira, Rabbi irratti hirkannee jirra, (Yaa) Gooftaa keenya! Gidduu keenyaafi gidduu namoota keenyaatti dhugaan murteessi; Ati irra caalaa warra murteessaniiti" (jedhe).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 90, 'nijedhan Ummata isaa irraa qondaalonni warra kafaranii "isin yoo Shu’aybiin hordoftan, Dhugumatti, isin yeroo san hoonga’oo dha".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 91, 'Sochiin (kirkirri) dachii isaan qabatte; manneen isaanii keessatti jilbeenfatoo ta''anii (du''anii) bariisifatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 92, 'Warri Shu’aybiin kijibsiisan akka waan ishee keessa hin turree ta’an, Warri Shu’aybiin kijibsiisan isaan hoonga’oo ta’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 93, '(Shu’ayb) isaan irraa gara galee nijedhe "yaa ummata kiyya! Ani ergaalee Gooftaa kiyyaa isin dhaqqabsiiseera. Toltuu isiniif dhaameera. Kanaafuu ani ummata kafaran irratti akkamittiin gadda!".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 94, 'Nuti gara magaalaa tokkoo nabiyyii kamuu erginee (yoo ummanni sun ajaja isaa fudhachuu didan), jiraattota ishee hiyyummaafi dhibeen isaan qabnee malee hin hafne akka isaan gadi of qabaniif jecha,.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 95, 'Ergasii bakka hamtuu toltuutti jijjiirre, hanga isaan baay’atanii jedhanitti "Dhugumatti, abbootii keenyas rakkinniifi toltuun tuqxee jirti (kun waanuma yeroon fiduu dha)" Achumaan tasa isaan qabne, odoo isaan hin beekne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 96, 'Odoo warri magaalattii amananii (Rabbiin) sodaatanii, silaa Dhugumatti, Nuti samiifi dachii irraa barakaawwan isaaniif banna turre, Garuu isaan ni sobsiisan. Kanaafuu waan isaan kan hojjata tahaniif isaan qabne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 97, 'Sila jiraattonni magaalattii isaanii rafaa jiranuu adabbiin keenya halkan isaanitti dhufuu (irraa) of amanuu (sodaa dhabanii)?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 98, 'Yookiin jiraattonni magaalattii isaanii taphatanuu adabbiin keenya waaree isaanitti dhufuu of amanuu (sodaa dhabanii)?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 99, 'Sila tooftaa Rabbii amanuu? Tooftaa Rabbii ummata hoonga’aa malee eenyullee hin amanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 100, 'Sila isaannan dachii (dhumiinsa) warra ishee boodaan dhaalanuuf ifa hin taanee nuti odoo feenee diliilee isaaniitiin kan isaan adabnu ta’uun keenya? Onneewwan isaanii irratti cufaa goonaa, isaan hin dhaga’anu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 101, 'Magaalota kana (kan Nuuh irraa hanga ummata Shu’aybitti jiru) [1] seenaalee isaanii irraa siif odeessina. Dhugumatti, ergamoonni isaanii ragaawwan ifa ta’aniin isaanitti dhufaniiru, Waan san dura kijibsiisanitti kan amanan hin taane, Akka kanatti Rabbiin onnee kaafirootaa irratti cufa.', '[1] isaan magaalota nuuh, huud, saalih, luux, shu''eybiiti.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 102, 'Irra hedduu isaanii waadaa isaanii irra kan gadi dhaabbatan hin argine; irra hedduu isaanii finciltoota ta’uu argine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 103, 'Ergasii isaan booda mallattoowwan keenyaan Muusaa gara Fir’awniifi qondaalota isaatti erginee jirra, Isaan fudhachuu didan, Booddeen (itti galli) balleessa hojjattootaa akkam akka ta’e ilaali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 104, 'Muusaan ni jedhe: "Yaa Fir’awna! Dhugumatti, ani ergamaa Gooftaa aalamootaa irraa ta’eedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 105, 'Rabbi irratti dhugaa malee dubbachuu dhiisuun koo dhugaadha; dhugumatti, ani ragaa ifa galaa Gooftaa keessan irraa ta’een isinitti dhufeera, Kanaafuu Ilmaan Israa’iil na wajjiin gadi dhiisi."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 106, '(Fir’awni) "Yoo mallattoon kandhufte taate, ishee fidi, yoo warra dhugaa dubbatan irraa taateef" jedheen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 107, 'Ulee isaa darbate; isheen yeroma san bofa mul''ataa (guddaa) taate', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 108, 'Harka isaa ni baase; isheen yoosuu warra ilaalaniif adii (calaqqisaa) taate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 109, 'Qondaalonni ummata Fir’awni irraa ta''an ni jedhan: "Inni kun Dhugumatti, saahiree (falfalaa) beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 110, 'Dachii keessan irraa isin baasuu fedha; maal ajajjuree?" (jedheen).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 111, '[Isaan] ni jedhan: "isaafi obboleessa isaa tursiisi, Magaalota keessa walitti qabdoota ergi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 112, 'Falfalaa beekaa hundaan sitti dhufu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 113, 'Saahiroonni gara Fir’awni dhufanii "yoo nuti kan injifannu taane mindaan nuuf jiraa?" jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 114, '[Inni] "Eeyyeen Isin warra (natti) dhiyeeffamu irraayi" jedheen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 115, '"Yaa Muusaa! yookaa ati darbachuu yooka nuti darbattoota tahuu " jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 116, '"Darbadhaa" jedhe, Yeroma (funyoo isaanii) darbatan ija namootaa falfalanii isaan shoorarkeesan, Sihrii guddaan dhufan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 117, 'Gara Muusaatti "ulee kee darbi" (jechuun) beeksisa goone, Achumaan isheen waan isaan kijiban ni liqimsiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 118, 'Dhugaan ni mirkanaa’e; wanti isaan hojjataa turan ni bade.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 119, 'Achitti ni injifataman; salphattoota ta’anii deebi’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 120, 'Saahiroonni (Rabbiif) kan sujuudan ta''anii kufan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 121, 'Ni jedhan: "Gooftaa aalamootaatti amanneerra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 122, 'Gooftaa Muusaafi Haaruunitti."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 123, 'Fir’awnis ni jedhe: "odoo ani isiniif hin hayyamin isatti amantuu? Dhugumatti, kun tooftaa isin magaalattii keessatti mari’attaniidha jiraattota ishee isii irraa baasuuf jecha. Fuulduratti beekuuf jiraattu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 124, 'Dhugumatti,ninmura harkoowwan keessaniifi miilleen keessan wal faallessuunan, eegasii hunda keessaniiyyuu nan fannisa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 125, 'Isaanis "Nuti Dhugumatti, gara Gooftaa keenyaa deebi’oo dha" jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 126, '"Mallattooleen Gooftaa keenyaa yeroma nutti dhuftu itti amanuu (keenya) malee wanti nurraa haaloo bahattu hin jiru, Gooftaa keenya! obsa nurratti dhangalaasi, Muslimoota godhii nu ajjeesi" (jedhan)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 127, 'Ummata Fir’awni irraas qondaalonni nijedhan "sila ati Muusaafi ummata isaa akka dachii keessa balleessanii (Muusaanis) sihiifi gabbaramtoota keetis akka dhiisuuf (isaan) dhiiftaa?". ni jedhe: "Nuti ilmaan dhiiraa isaanii ni ajjeefna, Dubartoota isaanii immoo ni jiraachifna, (nidhiifna). nuti isaan irratti moo’attoota."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 128, 'Muusaan ummata isaatiin nijedhe "Rabbiin gargaarsifadhaa; obsaa, Dhugumatti, dachiin tan Rabbiiti, Gabroota Isaa irraa nama fedhe ishee dhaalchisa, Booddeen tan warra Rabbiin sodaataniiti".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 129, 'Nijedhan "Nuti rakkifamnee jirra odoo ati nutti hin dhufin duraafi erga nutti dhuftee boodas ". nijedhe " nimala Gooftaan keessan diinota keessan balleessee, dachii keessatti bakka isin buusee, ergasii akkam akka dalagdan isin ilaaluun".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 130, 'Dhugumatti, Nuti ummata Fir’awni caama waggootaaf tureefi hir’ina oomishaatiin isaan qabne. akka isaan gorfamaniif jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 131, 'Yeroo toltuun wahii isaanitti dhufte "kun nuuf malti" jedhu, Yoo hamtuun isaan tuqxe immoo Muusaafi namoota isa waliinii irratti hooddatu, Dhagayaa! Dhugumatti,hooddannaan isaanii Rabbiin bira jira. Garuu irra hedduun isaanii hin beekan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 132, 'Isaan (Muusaan) ni jedhan: "Yoo ati raajii irraa waan feeteen isheedhaan sihrii nutti godhuuf nutti dhufte, nuti siif kan amannu hin taane."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 133, 'Achumaan nuti lolaa (bishaan) dachii walga’e, awaannisa, injiraan, raachaafi dhiiga mallattoowwan addeeffamaa haala ta''aniin isaan irratti erginee jirra. Isaan garuu ni boonan, (Isaan) ummata yakkamtoota turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 134, 'Yeroo adabichi isaan irratti bu''u ni jedhan: "yaa Muusaa! Gooftaa kee nuuf kadhu waan Inni si biraa waadaa qabuun , yoo ati adabicha nurraa deebifte, Dhugumatti, nuti siif amanna; Ilmaan Israa’il si waliin ergina."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 135, 'yeroma nuti isaan irraa adabicha Hanga beellama isaan dhaqqabanuutti deebifnu achumaan isaan waadaa isaanii diigu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 136, 'galaana keessatti isaan dhidhimsinee haaloo isaan irraa ba’anne, Sababa isaan keeyyattoota keenya sobsiisanii ishee irraayis dagattoota ta’aniif .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 137, 'Nuti namoota hacuucamaa turan Bahaafi Dhiha dachii dhaalchifne, ishee barakaa keessa goonee. jechi Rabbii keetii toltuun Banii Israa’iil irratti guutamte Sababa isaan obsaniif. Waan Fir’awniifi ummanni isaa dalagaa turaniifi waan isaan ijaaraa turanis ni barbadeessine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 138, 'Ilmaan Israa’iilin bahara ceesifne, ummata taabota isaanii (gabbaruu) irra taa’aa jirutti dhufanii "yaa Muusaa akkuma isaan waan gabbaramu qaban nuufis waan gabbaramu godhi" jedhan, [Inni] ni jedhe: "Isin ummata wallaaloodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 139, 'Isaan kun wanti isaan keessa jiran mancaafamaadha. Wanti isaan dalagaa turanis kufaadha."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 140, '"Sila ani Rabbiin ala gabbaramaa biraa isiniif barbaadaa odoo Inni aalama hunda irra isin caalchisee jiruu?" jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 141, 'Yeroo Nuti namoota (adabbii) ummata Fir’awni irraa nagaa isin baafnes [yaadadhaa] kan hamtuu adabaa isin dhandhamsiisan, kan ilmaan keessan ajjeesanii dubartoota keessan jiraachisan. Kana keessas balaa guddaa Gooftaa keessan irraa ta’etu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 142, 'Muusaaf halkan soddoma waadaa seenne. Kudhaniin ishee guunne. Beellamni Gooftaa isaa halkan afurtama guute. Muusaan obboleessa isaa Haaruunin ni jedhe: "Bakka na bu’i ummata kiyya keessatti tolchi, Karaa warra balleessaa hojjatanii hin hordofin."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 143, 'Yeroo Muusaan beellama keenyaaf dhufee Rabbiin isaa isaan dubbatu "Yaa gooftaa kiyya (uf) na argisiisi sin ilaalaa!" jedhe. (Rabbiin) "Nan argitu; garuu gara gaaraa ilaali; yoo bakka isaatti ragga''eef Na argitaa" jedhe. Yeroo Rabbiin isaa gaaraaf mul’atu caccaphaa isa godhe. Muusaan of wallaalee kufe, Yeroma bayyanatu nijedhe "ati qulqulloofte; ani gara keetti deebi’e, anis jalqaba mu’uminootaati".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 144, '(Rabbiin) ni jedhe: "Yaa Muusaa! Ani ergaa kiyyaafi haasa’a kiyyaan namoota irra si filadheera, Waan Ani siif kenne qabadhu, Galateeffattoota irraa ta’i."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 145, 'Loohiwwan keessatti waan hunda irraa gorsaafi ibsa waan hundaa isaaf barreessine. "Ishee ciminaan qabadhu, ummata keetis akka toltuu ishee qabatan ajaji. Ani biyya finciltootaa fuuldurattin isinitti agarsiisa" (jedheen).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 146, 'Ani warra haqaan ala dachii keessatti boonan keeyyattoota kiyya irraa garan galcha, Yoo mallattoolee hunda arganis isatti hin amananu, Yoo karaa qajeelaa argan isa karaa hin godhatanu, Yoo karaa jallinaa argan isa karaa godhatu, Kun waan isaan keeyyattoota keenya kijibsiisaniifi ishee irraas dagatoo turaniifi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 147, 'Warri keeyyattoota keenyaafi qunnamtii Aakhiraa kijibsiisan, dalagaaleen isaanii badde, Sila waan hojjataa turan malee mindeeffamuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 148, 'Ummanni Muusaa (deemsa) isaa booda faaya isaanii irraa jibicha qaama sagaleen (akka koqiinsaa) isaaf taate tolfatan, Sila akka inni isaanitti hin dubbanneefi gara karaa (sirriis) isaan hin qajeelchine hin arganuu? (Gabbaramaa) isa godhatan; miidhaa hojjattootas ta’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 149, 'Yeroo gaabbanii jallachuu isaaniis argan, (tawbataniitin) jedhan: "odoo Gooftaan keenya rahmata nuuf godhuu baateefi nuuf hin araaramnee, dhugumatti silaa nuti hoonga’oo irraa taana ture."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 150, 'Muusaan yeroma dallanaa gaddaa gara ummata isaa deebi’u "wanti isin ana booda na bakka buuftan waa fokkate; sila ajaja Gooftaa keessanii jarjarfattani moo?" jedhe. Loohiiwwan darbee mataa obboleessa isaa qabe, kan ufitti harkisu ta''ee. (Obboleessis) nijedhe "Yaa ilma haadha tiyyaa! Ummanni na hacuucanii na ajjeesuuf dhihaatani, Kanaafuu diina natti hin gammachiisin, Ummata miidhaa raawwattoota wajjinis na hin godhin" jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 151, '(Muusaan) nijedhe "Gooftaa kiyya! Anaafi obboleessa kiyyaaf araarami, Rahmata kee keessas nu seensisi, Ati irra rahmata godhaa warra rahmata godhaniiti".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 152, 'Dhugumatti, isaannan mirgoo (gabbaramaa) godhatan, Gooftaa isaanii irraa dallansuufi salphinni jireenya addunyaa tanaa keessatti isaan argata፣ Akka kanatti kijiba uumtota (adabaan) galata galchina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 153, 'Isaannan dilii heddu hojjatanii sana booda tawbataniifi amanan, Dhugumatti, Gooftaan kee sana booda araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 154, 'Yeroma dallansuun Muusaa irraa qabbanaa’u loohiwwan fuudhe, Barreefama ishee keessa qajeelfamaafi rahmatatu warra Gooftaa isaanii sodaataniif jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 155, 'Muusaan ummata isaa irraa namoota torbaatama beellama keenyaaf filate, Yeroo sochiin (kirkirri) lafaa isaan qabattu, (Muusaan) ni jedhe: "Gooftaa kiyya! Odoo feetee kana dura isaaniifi anas ni balleessita ture, Sila waan gowwoonni nurraa ta’an dalaganiin nu balleessitaa? Isheen (fitnattiin) mokkoroodhuma keeti malee homaa miti, Isheedhaan nama feete jalliftee nama feete immoo qajeelchita, Ati gargaaraa keenya, Nuuf araarami, Rahmatas nuuf godhi, Ati caalaa araaramtootaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 156, 'Jireenya addunyaa kana keessattiifi kan Aakhiraa keessattis toltuu nuuf katabi, Nuti gara kee deebineerra." (Rabbiin) ni jedhe: "(kun) azaaba kiyya; naman fedhen isaan tuqa, Rahmanni kiyya waan hundaaf ballatte, Ishee fuulduratti nin barreessa warra Rabbiin sodaataniif, zakaa kennaniifi warra keeyyattoota keenyatti amananiifin."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 157, '(Isaan) warra ergamaa, nabiyyii hin barreessineefi hin dubbifne hordofani, isa isaan biratti Tawraatiifi Injiiliin keessatti barreeffamee isa argan, kan toltutti isaan ajajuufi hamtuu irraa isaan dhorgu, kan gaggaarii halaala isaaniif taasisu, fokkataawwan immoo haraama isaan irratti taasisu, kan ba’aa isaaniitiifi hidhaa isaan irra ture isaan irraa lafa kaayu. (hordofaniidha). Isaannan isatti amananii isa kabajan, kan isa gargaaraniifi ifa isa waliin bu’e hordofan, isaan isaanumatu warra milkaa’oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 158, 'Jedhi: "Yaa namootaa! Dhugumatti, ani ergamaa Rabbii Isa mootummaan samiifi dachii kan Isaa ta’e irraa gara hunda keessaniitti (ergamee dha). Isa malee dhugaan gabbaramaan hin jiru, Ni jiraachisa; ni ajjeesas, Rabbiifi ergamaa Isaa, kan nabiyyii hin dubbifneefi hin barreessine ta’eetti amanaa,kan Rabbiifi jechoota Isaatti amanu sanitti, isa hordofaa akka qajeeltaniif jecha."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 159, 'Ummata Muusaa irraa ummata dhugaan qajeelaniifi ittiin haqa murteessantu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 160, 'Ummata gosa kudha lama goonee isaan qoqqoodne, Gara Muusatti yeroo namoonni isaa dhugaatii isa gaafatan "Ulee teetiin dhagaa dhayi" jechuu beeksifne, Isa irraas burqituu kudha lamatu maddite, Namoonni hunduu iddoo irraa dhugan ni beekan, Duumessa isaan irratti gaaddiseessine, Mannii''fi ''salwiis'' isaan irratti buufne: "Gaggaarii waan nuti isiniif kenninee irraa nyaadhaa" (jenneen). Isaan Nu hin miine; garuu isaan lubbuu isaanii miidhaa turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 161, 'Yeroo isaaniin jedhame [yaadadhaa] "magaalattii tana keessa jiraadhaa; ishee irraa bakka feetanii nyaadhaa, (kan nu feenu Badiin nurraa) harca''uudhas'' jedhaa, Balbalas sujuuda godhaa seenaa, Badiiwwan keessan isiniif dhiifna,(galata) warra toltuu hojjataniis ni daballa"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 162, 'Isaan irraa warri miidhaa hojjatan jecha isaanin jedhameen ala isa biraa jijjiiran,azaaba samii irraa isaan irratti ergine Waan miidhaa hojjataa turaniif jecha.[1]', '[1] jecha jirhiiruun isaanii kan Rabbiin araarama kadhataa seenaa isaaniin jedhe isaan habbatun fii sha''iiratin (firii garbuu barbaanna) jechaa seenan. akkasuma kan sujuudaa seenaa isaaniin jedhame taa''aa isaaniitiin lafarra shorroqaa seenan.saniif Rabbiin itta dallanee azaaba samirraa itti buuse. [ tafsiira saidii/ teysiir].');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 163, 'isaan gaafadhu Waa’ee magaalattii galaanicha cinaa jirtuu, yeroo isaan sanbata keessatti daangaa dabran, yeroo qurxummiin isaanii guyyaa sanbataa mul’attuu taatee isaanitti dhuftu; guyyaa isaan hinsanbateessine (hin guddifne) (guyyaa biroo) isaanitti hin dhuftu,akka kanatti isaan qormaanna waan isaan fincilaa turaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 164, '(yaadadhu) Yeroo ummanni isaan irraa taate jette "ummata Rabbiin isaan balleessuuf yookiin adabbii cimaa isaan adabuuf jiru maaliif gorsitu?" (Gorsitoonn) nijedhan "Gooftaa keessan biratti sababa nuuf haa ta''uufi akka isaan Rabbiin sodaataniifi" jedhan. [1]', '[1] kuni wanni ibsu namni gorsu yoo ummanni irratti dides gorsa isaa hindhaabuu ittuma fufa jechuudha.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 165, 'Yeroma isaan waan ittiin gorfaman dagatan, isaan hamtuu irraa (namoota) dhorgan nagaa baafnee, isaan miidhaa hojjatan immoo adabbii hamaan isaan qabne waan isaan fincilaa turaniif jecha. [1]', '[1] hubadhaa daiwaan (ummata islaamummatti yaamuun) azaaba jalaa nagaya nama baafti.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 166, 'Yeroma isaan daangaa wantoota irraa dhorgamanii dabran isaanin jenne "jaldeessa salphattoota ta’aa".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 167, 'Yeroo Gooftaan kee hanga Guyyaa Qiyaamatti isaan irratti nama adabbii laalessaa isaan dhandhamsiisu akka isaan irratti ergu beeksise (yaadadhu.) Dhugumatti, Gooftaan kee adabbiin isaa arifataadha; Inni akkaan araaramaa, akkaan rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 168, 'Nuti (Ilmaan Isaraa’iil) dachii keessatti ummatoota adda addaa taasifnee isaan kukkunnee jirra, Isaan irraas gaggaariitu jira, Isaan irraa sanaan alatu jira, toltuuwwaniifi hamtuuwwaniin isaan qormaannee jirra Akka isaan deebi’aniif jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 169, 'bakka bu’an booda isaaniitii bakka bu’oonni badaan kitaaba dhaalan. Meeshaa dhihoo (hoosa) kana fudhataa, "fuulduratti nuuf dhiifama" jedhu, Yoo meeshaan san fakkaatu isaanitti dhufe ni fudhatu, Sila waadaan kitaabaa akka isaan Rabbiin irratti dhugaa malee hin dubbanne isaan irraa hin fuudhamnee? Waan isa keessa jirus hin dubbifnee? Manni Aakhiraa isaan Rabbiin sodaataniif caalaadha, Sila isin hin xiinxaltanuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 170, 'Isaannan kitaabicha qabatanii, salaata sirnaan dhaaban, Dhugumatti, Nuti mindaa tolchitoota hin balleessinu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 171, 'Yeroo Nuti gaara xuur gubbaa isaanii irratti akka gaaddisaa ta’ee ol fuunee, isaan isaanirratti kufa jechuu dhugoomsanii "Waan nuti isiniif kennine ciminaan qabadhaa, Akka (Rabbiin) sodaattaniif jecha waan isa keessa jiru qhubadhaa" (jenne yaadadhu)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 172, 'Yeroo Gooftaan kee ilmaan Aadam irraa, dugdaalee isaanii irraa sanyiilee isaanii baase, lubbuulee isaanii irratti ragaa isaan godhe [yaadadhu] "Ani Gooftaa keessanii mitii?" jecheen, Isaanis "Eeyyeen; ragaa baanee jirra" jedhan, Kunis akka isin Guyyaa Qiyaamaa "Dhugumatti, nuti kana irraa daguu keessa turre" hin jenneefi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 173, '“Yookiin abbootii keenyatu duraan (Rabbitti) qindeessani; nutis sanyii isaaniin boodaa turre, Sila waan balleessitoonni hojjataniin nu balleessitaa?” akka isin hin jenneef (ragaa isin goone).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 174, 'Akka isaan (yaadanii)fi deebi’aniif jecha akka kanatti keeyyattoota keenya addeessina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 175, 'isaan irratti dubbisi oduu isa keeyyattoota keenya isaaf kenninee, ishee irraa luqqa''e, sheyxaana isa hordofsiise, jallattoota irraa ta’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 176, 'Odoo feenee, isheedhaan (keeyyattoota keenyaan) ol isa fuuna ture, Garuu inni gara dachiitti gadi dide; fedhii lubbuu isaa hordofe, Fakkeenyi isaa akka fakkii sareeti yoo ariite arraba baasee harganu, yoo dhiiftes arraba baasee harganuuti, Kuni fakkeenya ummata keeyyattoota keenya kijibsiisaniiti, seenaalee odeessi akka isaan xiinxalaniif jecha .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 177, 'Fakkeenyi ummata keeyyattoota keenya kijibsiisanii waa fokkate! lubbuulee isaanii kan miidhan ta’anii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 178, 'Namni Rabbiin qajeelche, isatu qajeelaadha, Namni Inni jallise immoo, isaan warra hoonga’oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 179, 'Dhugumatti, Nuti jahannamiif jinnootaafi namoota irraa heddu uumnee jirra, Isaaniif onneewwantu tahe, isiin hinhubatan. isaaniif ijoowwantu tahe, isiidhaan hinargan.isaaniif gurroowwantu tahe, isiin hindhagayan. Warri sun akka beyladootaati, Inumaa jarri irra jallatoodha, Isaan isaanumatu dagattoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 180, 'Rabbiif maqaalee gaggaariitu jiru, Isheedhaan Isa kadhaa, Warra maqaalee Isaa keessatti jallisan dhiisaa, Waan dalagaa turan fuulduratti galata galfamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 181, 'Namoota Nuti uumne irraa, ummata dhugaan qajeelaniifi isaanis haqa murteessantu jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 182, 'Isaannan keeyyattoota keenya kijibsiisan, Nuti karaa isaan hin beekne irraan suuta suutaan isaan qabna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 183, 'Yeroo isaaniifin kenna; Dhugumatti, tooftaan kiyya cimaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 184, 'Sila isaan saahiba (Nabiyyii) isaaniitti (muhammaditti) maraatummaan akka hinjirre hin xiinxalanuu? Inni akeekkachiisaa ifa galaa malee waan biraatii miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 185, 'Sila mootummaa samiileefii dachiifi, keessatti hinlaalanii? waan Rabbiin wantoota hunda irraa uumes, akkasumas beellamni (yeroon du’a) isaanii Dhugumatti kan dhihaate ta’uu (hin ilaalanuu?). Sila booda isaatii (Qur’aanaatii) haasa’a kamitti amanu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 186, 'Nama Rabbiin jallise, qajeelchaan isaaf hin jiru, Jallina isaanii keessatti dhama''oota ta''anii isaan dhiisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 187, 'Waa’ee Qiyaamaa irraa yoomi dhaabbatiinsi isii (dhufti isii) (jedhanii) si gaafatu, jedhi "Beekumsi ishee Gooftaa kiyya bira qofa. Isa malee homtuu yeroo isheetiif ishee hin ibsu, Samiileefi dachii keessatti ulfaatte, Isheen tasa (daguutti) malee isinitti hin dhuftu" (jedhi). Akka waan ati ishee sirritti beektuutti si gaafatu, jedhi Beekumsi ishee Rabbiin bira qofa jira, Garuu irra hedduun namootaa hin beekan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 188, 'Jedhi "Ani lubbuu kiyyaaf faayidaas ta’ee miidhaa fiduu hin danda''u waan Rabbiin fedhe malee, Odoon kanin fagoo (ghaybii) beeku ta''ee, silaa toltuu irraan baay''ifadha; hamtuun na hin tuqu ture, Ani ummata amananiif akeekkachiisaafi gammachiisaa malee hintaane".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 189, 'Inni Isa lubbuu takka irraa isin uumee ishee irraa qindii isii taasisee, akka isheetti booharuuf (mukuu bahuuf). Yeroo inni ishee qunnamu ulfa salphaa ulfoofte, (salphina isaa irraa bakka feete) ittiin deemte, Yeroma isheen ulfaattu Rabbiin Gooftaa isaanii kadhatan "yoo Ati (ilma) gaarii nuuf kennite, dhugumatti, nuti warra Si galateeffatan irraa taana" (jechuun) .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 190, 'Yeroo Inni (ilma) gaarii isaaniif kennu waan Inni isaaniif kenne (maqaa) keessatti Isaaf shariika taasisan, Rabbiin waan isaan Isa waliin gabbaran irraa ol ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 191, 'Sila warra waa tokko uumuu hin dandeenye Rabbitti qindeessuu? kan ofiifuu uumamoo ta’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 192, 'Isaan gargaaruu hin danda’an, lubbuulee isaaniis hingargaaran.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 193, 'Yoo isin gara qajeelumaa isaan waamtan isin hin hordofan, Isaan waamtanus yookiin cal’iftoota taatanus isin irratti walqixa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 194, 'Dhugumatti, isaan isin Rabbii gaditti gabbartan gabrootuma fakkiiwwan keessaniiti, mee isaan kadhaa isiniif haa awwaatanuu Yoo kan dhugaa dubbattan taataniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 195, 'Sila isaaniif miiloowwantu tahee kan isiidhaan deeman? moo isaaniif harkoowwantu taheekan isiidhaan qabatan? moo isaaniif ijoowwantu kan isiidhaan argan? moo isaaniif gurroowwantu tahee kan isiidhaan dhagayan? jedhi " shariikota keessan (warra Rabbii waliin gabbartan) waamadhaa, Ergasii tooftaa natti baasaa, Yeroos naaf hin kenninaa (isaan hin sodaadhu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 196, 'Jaalalleen kiyya Rabbii Isa kitaaba buuseedha, Inni warra toltuu hojjatan ni gargaara" (jedhiin).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 197, 'Warri isin Isaa gaditti gabbartan isin gargaaruu hindandayan, lubbuulee isaaniitis hingargaaranu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 198, 'Yoo gara qajeelumaa isaan waamtan hin dhaga''anu. Kan isaan gara kee ilaalanu argita isaan hinargan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 199, 'Haala (namootaa irraa isa) laafaa qabadhu; toltuutti ajaji; wallaaltota irraa gara gali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 200, 'Yoo garagalchaan shayxaana irraa ta’e tokko (ajaja Rabbii irraa) si bute Rabbitti maganfadhu, Inni dhagayaa, argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 201, 'Isaan Rabbiin sodaatan yeroo naanna''aan shayxaana irraa ta’e isaan tuqe, (Rabbiin) yaadatu, Achumaan isaan argoodha..', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 202, 'Obboleeyyan isaanii jallina isaaniif dabalu, Ergasii (jallisuu irraa) hin gabaabbatanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 203, 'Yeroo ati raajii wahiitiin isaanitti hin dhufin "Maaliif ishee hin finne (hin uumne)?" jedhu. jedhi "Wanti ani hordofu waan Gooftaa kiyya biraa gara kiyyatti beeksifame qofa, (Qur’aanni) kun ragaa ifa bahaa Gooftaa keessan irraa ta''e, qajeelfamaafi rahmata ummata amananiif ".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 204, 'Yeroo Qur’aanni qara’ame isaaf dhageeffadhaa; cal’isaa akka rahmanni isiniif godhamuuf .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 205, 'Gooftaa kee faarsi lubbuu tee keessatti gadi of qabaafi sodaataa, sagalee ol hin fuudhaminiin ganamaafi galgala. Dagattoota irraa hin ta’in.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 206, 'Dhugumatti, isaannan Gooftaa kee bira jiran Isa gabbaruu irraa hin boonanu; Isa qulqulleessu; Isaaf sujuuda godhu. [1]', '[1] bakka tanatti namni qur''aana qarau sujuuda tokko godha. sujuuda tilaawaa (qaraatii qur''aanaa) jedhama. sunnaa jaalatamaadha. inni qur''aana keessa bakka 15 jira.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 1, 'Boojuu irraa si gaafatu, jedhi “Boojuun kan Rabbiifi ergamaa Isaati, Rabbiin sodaadhaa. Hariiroo gidduu keessan jiru tolchaa.Rabbiifi ergamaa Isaatiif ajajamaa Yoo mu’uminoota taatan".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 2, 'Mu’umintoonni (dhugaa) warra yeroo (maqaan) Rabbii dubbatamu onneewwan isaanii rifattu, kan yeroo keeyyatoonni Isaa isaan irratti dubbifamtu Iimaana isaaniif dabaltuu, kan Gooftaa isaanii irratti irkataniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 3, 'Isaannan salaata (seera ishee guutanii) dhaabani, waan nuti isaaniif kennine irraas kennitaniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 4, 'Isaannan kun isaan qofatu dhugumatti mu’uminoota, Gooftaa isaanii biratti sadarkaa hedduuisaaniif jira, araaramaafi soorata gaarii ta’etu (jannatatu) (isaaniif jiraaf).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 5, 'akkuma Rabbiin kee mana kee irraa dhugaan si baaseeti. gariin mu’uminootarraa nijibban.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 6, 'Siin falmu Dhugaa irratti, erga inni ifa ta’ee booda, akka waan odoo argan gara du’aa oofamaaraniitti .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 7, 'Yeroo tokkoon gareewwan lamaanii isiniif ta’uu Rabbiin waadaa isiniif galee, isinis isheen abbaa lolaa hin ta’in (gareen daldaalaa) isiniif ta’uu jaallattan, Rabbiin nifedha jechoota (waadaa) Isaatiin dhugaa mirkaneessuu. hidda kaafirootaa muruu (fedha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 8, '(Wanti kana hojjateef) akka dhugaa mirkaneessee soba barbadeessuufi odoo kaafiroonni jibbanillee .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 9, 'Yeroo isin Rabbii keessan irraa birmannaa barbaaddanii isiniif awwaate “Ani maleykoota kumaa wal hordofoo ta’an isiniif gargaarsa godhaadha” (jeche) [yaadadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 10, 'Rabbiin gammachuu (keessanii)fi akka onneewwan keessan ittiin tasgabbooftuuf malee waan biraatiif isa hin goone, Injifannoon Rabbiin biraa malee hin taane. Rabbiin injifataa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 11, '[yaadadhaa]. Yeroo Inni hirribaan isin haguuge tasgabbii Isa biraa ta’ee (adda waraanaatti).samii irraa yeroo bishaan isin irratti buuse (roobse), isaan isin qulqulleessuf, waswaasa sheyxaanaa isin irraa deemsisuuf, onneewwan keessanirratti (obsaan) jabeessuuf, faanowwan (keessanis cirracha irratti) ittiin gadi dhaabuuf jecha (isiniif roobse).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 12, 'Yeroo Gooftaan kee gara maleykotaatti beeksisa godhe [yaadadhu] “Ani (gargaarsaan) isin waliin jiraa, isaan amanan (miila isaanii) gadi dhaabaa, Ani onneewwan isaan kafaranii keessa sodaan buusa; Mormoowwan (isaanii) gubbaa rukutaa, Isaan irraas quba hunda rukutaa” (jedhee).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 13, 'Kun waan isaan Rabbiifi ergamaa Isaa faallessaniifi, Namni Rabbiifi ergamaa Isaa faallesse, (Rabbiin isa adaba) Rabbiin adabbiin isaa cimaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 14, 'Kun (adaba keessanii), isa dhandhamaa, Dhugumatti kaafirootaaf adabbii ibiddaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 15, 'Yaa warra amantan! (waraanaaf) kan walitti qabaman ta’anii yeroo warra kafaran qunnamtan, duuba keessan isaanitti gara hin galchinaa (hin baqatinaa).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 16, 'Namni guyyaa san duuba isaa isaaniitti garagalche, yoo mijjeeffannaa lolaatiif yookiin gara hoomaa (isaa) siquuf ta’e malee, inni dhugumatti dallansuu Rabbi irraa ta’een deebi’ee jira, Teessoon isaas jahannami, Deebiin (isaanii jahannam) waa fokkate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 17, 'Isin isaan hin ajjeefne Garuu Rabbitu isaan ajjeese. Ati hin darbanne Yeroo darbatte Garuu Rabbiitu darbate. Mu’uminootaafis tola gaarii isa biraa ta’e akka kennuuf (kana hojjate). Rabbiin dhagahaa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 18, 'Kun (dhugaadha) Rabbiin dadhabsiisaa tooftaa kaafirootati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 19, '(Yaa warra kafartan!) Yoo murtii barbaaddan, dhugumatti murtiin isiniif dhufee jira. Yoo (badii irraa) dhorgamtan inni isiniif caalaadha. Ammas yoo isin (waraanatti) deebitan, nutis (tumsa keenyaan) ni deebina.Tuunni keessan odoo baay’attellee homaa isin hin fayyadanu. Rabbiin (gargaarsaan) mu’uminoota waliin jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 20, 'Yaa warra amantan! Rabbiifi ergamaa Isaatiif ajajajamaa, Odoo dhageessanuu Isa irraa gara hin galinaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 21, 'Akka isaan “dhageenyee jirra” jedhanii hin ta’inaa haala isaan hin dhageenyeen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 22, 'Dhugumatti, irra badaan lubbu qabeeyyii Rabbiin biratti duudaa, arraba qabamaa, isaan aqlii hin qabneedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 23, 'Rabbiin odoo isaan keessatti toltuu beekee, silaa isaan dhageessisa ture. Odoo isaan dhageessisee, silaa isaan kan garagalan ta’anii irraa baqatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 24, 'Yaa warra amantan! Rabbiif awwaadhaa, Ergamaa Isaatiifis; yeroo inni waan isin jiraachisutti isin waame (awwaadhaa). beekaa Rabbiin gidduu namichaatiifi onnee isaa nigolga. isin gara Isaatti walitti qabamtan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 25, 'Rakkoo (Fitnaa) isin irraa warra miidhaa hojjatan qofa kophaatti hin tuqne sodaadhaa. Rabbiin adabbiin isaa cimaadhaa beekaa', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 26, 'Yaadadhaa yeroo isin muraasa, dachii keessattis hacuucamoo, namoonni (saamichaafi ajjeechaan) isin bubbutuu sodaattan, (Rabbiin) isin qubsiisee, tumsa Isaatiin isin gargaare,gaggaarii irraa isin soore akka isin galateeffattaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 27, 'Yaa warra amantan! Rabbiifi ergamaa Isaa hin ganinaa, amaanaa keessanis hin ganinaa odoo beektanii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 28, 'beekaa qabeenyaaleen keessaniifi ilmaan keessanis (fitnaa) mokkoroodha. Rabbiin mindaan guddaan Isa bira jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 29, 'Yaa warra amantan! Yoo Rabbiin sodaattan, addaan baasaa (dhugaafi dharaa) isiniif godha. Badiilee teessan isin irraa harcaasa, Isiniif araaramas, Rabbiin abbaa tola guddaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 30, 'Yeroo isaan kafaran shira sirratti baasan [yaadadhu], si hidhuuf yookiin si ajjeesuf yookiin (biyya irraa) si baasuuf. Isaan shira baasu; Rabbiinis shira baasa (shira isaanii isaan irratti deebisa), Rabbiin irra caalaa warra tooftaa baasuuti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 31, 'Yeroo keeyyatoonni keenya isaan irratti qara’amtu nijedhan “Nuti (ishee) dhageenyee jirra, odoo feenee fakkaataa kanaa ni jenna; kuni ogbarruu warra duriiti malee waan biraatii miti”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 32, 'Yeroo isaan jedhan yaadadhu “Yaa Allaah! Yoo kuni dhugaa si biraa (bu’e) ta’e, samii irraa dhagaa nurratti roobsi; yookiin adabbii laalessaa nutti fidi”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 33, 'Rabbiinis odoo ati isaan keessa jirtuu kan isaan adabu hin taane, Ammas Rabbiin odoo isaan araarama kadhatanuu kan isaan adabu hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 34, 'maaltu isaaniif tahe kan Rabbiin isaan hin adabneef, Haala isaan masjiida kabajamaa irraa (namoota) dhoorganiin. isaan itti gaafatamtoota isaa hintaane.itti gaafatamtoonni isaa Warra Rabbiin sodaatan malee kan biraa hin taane; garuu irra hedduun isaanii hin beekanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 35, 'Salaanni isaanii mana (Ka’abaa) biratti fiiysuu (siiksuu) fi harka dhahuu (shubbisuu) malee waan biraa hin taane, adabbii dhandhamaa Sababa kufrii keessaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 36, 'Dhugumatti, isaan kafaran (namoota) karaa Rabbii irraa dhorguuf jecha qabeenya isaanii kennu, Fuula duras ishee kennu, Sana booda isaan irratti gaabbii taati, Ergasii ni injifatamu; isaan kafaran gara jahannamitti walitti qabamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 37, 'Rabbiin fokkataa gaarii irraa adda baasuufi, fokkataa garii isaa garii gubbaatti taasisa, hunda isaanii walitti tuulee, ergasii jahannam keessatti isaan taasisuuf (walitti qabamu). Warri sun isaanumatu hoonga’oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 38, 'Isaan kafaraniin jedhi, yoo (kufrii irraa) dhorgaman wanti dabre isaaniif araaramama, Yoo (itti) deebi’an immoo dhugumatti, karaan (adabbiin) warra duraanii dabritee jirti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 39, 'Hanga “fitnaan” (shirkiin) hin argamneefi amantiin hundi isaa Rabbiif ta’utti isaaniin lolaa; (kufrii irraa) yoo dhorgaman, dhugumatti, Rabbiin waan isaan dalagan argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 40, 'Yoo isaan irraa gara galan, dhugumatti Rabbiin “gargaaraa keessanii beekaa, Tiksaan (Isa ta’uun) waa tole; tumsaan (Isa ta’uunis) waa tole.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 41, 'Beekaa wanti isin boojitan kumiyyuu, tokko shanaffaan isaa Rabbiifi, ergamaa Isaatiifi, firoota dhihootiifi, yatiimotaafi, hiyyeeyyiifi, kara deemaaf taha; yoo kan Rabbiifi waan Nuti gabricha keenya irratti guyyaa addaba’iinsaa (dhugaafi soba addaan baafne), guyyaa (Badrii kan) tuutti lamaan wal qunnaman buufnetti kan amantan taatan (sana beekaa), Rabbiini waan hunda irratti danda’aadha', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 42, 'Yeroo isin moggaa (Madiinaatti) dhihootti taatanii, isaan moggaa fagootti ta’an, daldaltoonni immoo jala keessan ta’an (waan ta’e yaadadhaa). Odoo waliif beellamtanii, silaa beellama keessatti wal dhabdu turtan, Garuu Rabbiin dhimma (beekumsa isaa keessatti) raawwatamaa ta’e raawwachuuf, namni bades ragaa ifa ta’e booda akka baduuf, namni jiraatus ragaa ifa ta’e booda akka jiraatuuf (beellama malee walitti isin qabe). Dhugumatti Rabbiin dhaga’aa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 43, 'Yeroo Rabbiin abjuu kee keessatti xiqqoo ta’uu isaanii sitti argisiise [yaadadhu], Odoo baay’ee ta’anii isaan sitti agarsiisee, silaa luynoomtanii, dhimmicha keessatti wal mormitu turtan. Garuu Rabbiin nagaya (isin) godhe. Dhugumatti, Inni beekaa waan qoma keessa jiruuti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 44, 'Yeroo walitti dhuftanii (yeroo) isaan isin agarsiise ijoowwan keessan keessatti xiqqoo taasisee, isin ijoowwan isaanii keessatti kan xiqqeessu ta’e [yaadadhu]. Rabbiin dhimma (beekumsa Isaa keessatti) raawwatamaa ta’e galmaan ga’uuf jecha (kana hojjate), Wantoonni gara Rabbii deebifamti', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 45, 'Yaa warra amantan! Yeroo garee (diinaa) wahii qunnamtan, gadi dhaabbadhaa; (faaruu) baay’ee Rabbiin faarsaa akka milkooftaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 46, 'Rabbiifi ergamaa Isaatiifis ajajamaa; wal hin morminaa; luynoomtanii humni keessan (isin irraa) deemtii; obsaa, Dhugumatti, Rabbiin obsitoota wajjin jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 47, 'Akka isaan manneen isaanii irraa bahanii hin ta’inaa boonaa, namootatti argisiifataa. kan karaa Rabbii irraa (namoota) dhorgan, (hiintahinaa). Rabbiin waan isaan dalaganitti marsaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 48, '[yaadadhu] Yeroo sheyxaanni dalagaalee isaanii (gadhee) miidhagsee, nijedhe “har’a nama irraa injifataan isiniif hin jiru, Ani isiniif gargaaraadha”. Yeroma gareen lamaan wal argan, of duuba deebi’ee nijedhe “ani isin irraa qulqulluudha; ani waan isin hin agarren argaa, Ani Rabbiinin sodaadha, Rabbiin adabbiin Isaa cimaadha”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 49, 'Yeroo munaafiqoonniifi warri onneewwan isaanii keessa dhukkubni (kufrii) jiru jedhan (yaadadhu) “warra kana amantii isaaniitu isaan gowwoomse”. Namni Rabbi irratti hirkate (ni moo’ata), Rabbiin injifataa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 50, 'odoo gartee Yeroo maleeykonni warra kafaran fuuleen isaaniitiifi duuydoowwan isaanii rukutaa lubbuu fuudhan “azaaba gubu dhandhamaa” (jedhaaniin) (dubbii cimaa argita).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 51, '”Kun waan harkoowwan keessan dabarfatteefi (waan) Rabbiin gabroota miidhaa hin ta’iniifi” (isaaniin jedhama)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 52, '(Haalli ummata kanaa) Akkuma haala warra Fir’awniifi warra isaan dura turaniiti. keeyyattoota Rabbiitti kafaranii Rabbiin badiiwwan isaaniitiin isaan qabeeti. Rabbiin jabaa, adabbiin Isaa cimaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 53, 'Kun waan Rabbiin tola ummata irratti oole tokko hanga isaan waan lubbuulee isaaniitti jiru jijjiiranitti kan jirjiiru hintahiniifi. Rabbiin dhagayaa beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 54, 'Akka haala namoota Fir’awnaafi warra isaan duraati. keeyyattoota Gooftaa isaanii kijibsiisan, ergasii badiiwwan isaaniitiin isaan balleessine; ummata Fir’awnaa bishaaniin dhidhimsine; hundumtuu miidhaa hojjattoota turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 55, 'Irra badaan lubbu qabeeyyii Rabbiin biratti warra kafarani; isaan hin amananu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 56, '(Isaan) warra ati waadaa isaan irraa fuutee, yeroo (waadaa seenan) hunda ahdii isaanii nidiigan, isaan Rabbiin hin sodaatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 57, 'Yoo lola irratti isaan argite namoota isaan boodaa isaaniin addaan facaasi, akka isaan gorfamaniif jecha .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 58, 'Garuu yoo namoota irraa ganiinsa sodaatte ifaan ifatti (waadaa isaanii) gara isaanitti darbi, Rabbiin warra (waadaa)gantoota hin jaalatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 59, 'Isaan kafaran (adaba Rabbii jalaa) miliqanii hin yaadin, isaan (Nu) hin dadhabsiisanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 60, 'Humnaafi faradoo hidhaman irraas ta’ee waan dandeessan isaaniif qopheessaa, kan ittiin diina Rabbii fii diina keessan sodaachiftan. (akkasuma kan) ummattoota biraa kan isaan hin tahin, kan isin isaan hin beekne, Rabbiin isaan beeku, ittiin akka sodaachiftaniif. Wanti karaa Rabbii keessatti (isin) arjoomtan kamillee (mindaan isaa) isiniif kennama, Isin hin miidhamtanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 61, 'Yoo gara araaraatti daban, atis gara isheetti dabi; Rabbi irratti irkadhu, Inni dhaga’aa, argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 62, 'Yoo isaan si ganuu fedhan, dhugumatti ga’aan kee Rabbuma, Inni Isa si jabeesse tumsa Isaatiifi mu’uminootaan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 63, 'Gidduu onneewwan isaanii wal taasise. odoo (wal taasisuuf) waan dachii keessaa hunda arjoomteeyyuu, gidduu onneewwan isaanii wal taasisuu hin dandeessu, Garuu Rabbitu gidduu isaanii wal taasise. Inni injifataa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 64, 'Yaa nabiyyii (kiyya)! Rabbiin siif gahaadha, mu’uminoota irraa namoota si hordofaniifis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 65, 'Yaa nabiyyii (kiyya)! Mu’uminoota lola irratti kakaasi, Isin irraa obsitoonni digdamni yoo argame, dhibba lama haa injifatanu, Isin irraa dhibbi tokko yoo argame isaan kafaran irraa kuma haa injifatanu, waan isaan ummata hin hubanne ta’aniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 66, 'Amma Rabbiin isin irraa laaffiseera, Isin keessa dadhabbiin akka jirus beekeera, Isin irraa obsitoonni dhibbi tokko yoo argame, dhibba lama haa injifatu, Isin irraa kumni tokko yoo argame,kuma lama haa injifatu, hayyama Rabbiitiin. Rabbiin obsitootaa wajjin jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 67, 'Nabiyyii kamiifuu booji’amtoonni isaaf ta’uun isaaf hin malu, hanga lafa irratti injifatutti (ajjeechaa isaanii bakkaan gahutti). Isin meeshaa (faa’idaa) addunyaa feetu; Rabbiin immoo Aakhiraa (isiniif) fedha, Rabbiin injifataa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 68, 'Odoo murtiin Rabbi irraa dabre ta’uu baatee, silaa waan isin fudhattan keessatti adabbiin guddaan isin mudata ture.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 69, 'Haala hayyamamaafi gaarii ta’een waan boojitan irraa nyaadhaa, Rabbiin sodaadhaa, Rabbiin araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 70, 'Ati Yaa nabiyyicha Booji’amtoota irraa namoota harka kee keessa jiraniin jedhi: “yoo Rabbiin onneewwan keessan keessatti toltuu wahii beekee, waan isin irraa fudhatame waan caalu isiniif kenna, isiniifis ni araarama, Rabbiin araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 71, 'Yoo isaan si ganuu fedhan, dhugumatti kana duras Rabbiin gananii jiru; isaan irraa (ajjeesuufi booji’uun) (siif) mijjeessee jira, Rabbiin beekaa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 72, 'Isaan amananii godaananii, karaa Rabbii keessattis qabeenyaafi lubbuulee isaanitiin qabsaa’aniifi isaan (isin) qubsiisanii, gargaarsas (isiniif) godhan, warri sun gariin isaanii jaalallee gariiti, Isaan amananii hin godaanin immoo hanga godaananitti jaalala isaanii irraa homtuu isiniif hin taane, Yoo amantii keessatti gargaarsa isin gaafatan,isaan gargaaruun isin irratti dirqama, -namoota gidduu keessaniifi gidduu isaanii waadaan jiru irratti (yoo ta’e) malee- Rabbiin waan isin hojjattan argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 73, 'Isaan kafaran gariin isaanii jaalallee gariiti. Yoo isin isa (mu’uminoota jaallattanii kaafiroota jibbuu) hojjachuu baattan dachii keessatti balaa (shirkii)fi badii guddaatu argama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 74, 'Isaan amananii, godaananii, karaa Rabbii keessatti qabsaa’aniifi isaan (isin) qubsiisanii, gargaarsa (isiniif) godhan, warri sun isaanumatu mu’uminoota dhugaati, Isaaniif araaramaafi hiree gaariitu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 75, 'Warri sana booda amananii, godaananiifi isin waliin qabsaa’an, isaan isin irraayyi. (Dhaala ilaalchisee) warri firaa gariin isaanii garii (dhaaluu)tti irra caalaadha,kitaaba Rabbii keessatti, Rabbiin waan hunda beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 1, '(Isheen kun) Qulqullina Rabbiifi ergmaa Isaa irraa taate kan gara warra mushrikoota irraa (lola dhiisuuf) waadaa walii galtaniitti (qaqqabduudha). [1]', '[1] suuraan tawbaa tuni bismillaa hinqabdu, usmaan binu affaan yeroo qur''aana barreessan akkanumatti bismillaa malee barreessan. suuraalee qur''aanaa 114n keessaa tan bismillaa hinqabne isii tana qofa.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 2, 'Ji’oota afuriif dachii keessa deemaa, Isin Rabbiin dadhabsiisoo akka hin ta’in beekaa. Rabbiin salphisaa kaafirootaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 3, '(Kuni) labsii Rabbiifi ergamaa Isaa irraa gara namaatti guyyaa hajji guddaa keessatti tahe, “Rabbiin qindeessitoota irraa qulqulluudha; Ergamaan Isaas (akkasuma), Yoo tawbattaniif, inni isiniif caalaadha, Yoo garagaltan immoo isin Rabbiin dadhabsiisoo akka hin ta’in beekaa” jechuudhaan. Warra kafaran adabbii laalessaadhaan gammachiisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 4, 'Garuu qindeessitoota irraa Warri waadaa walii seentanii sana booda homaa isin hin hirdhisiniifi (nama) tokkollee isin irratti hin gargaarin, malee, hanga beellama isaaniitti waadaa isaanii isaaniif guutaa, Dhugumatti Rabbiin sodaattota (isaa) ni jaalata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 5, 'Yeroo ji’oonni kabajamoon dabran, mushrikoota bakka isaan argitanitti ajjeesaa; isaan booji’aa; isaan marsaa; karaa hunda irra isaaniif taa’aa, Yoo tawbatanii, salaata gadi dhaabanii, zakaa kennan karaa isaanii isaaniif gadi dhiisaa, Rabbiin araaramaa, rahmata godhaadha.[1]', '[1] Ji’oonni kabajamoon ji’oota afran guyyaa labsii irraa kaasee jiru, kan mushrikootaaf isaan keessa nagaan socho’uun eeyyamamee dha.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 6, 'Yoo tokkoon qindeessitoota irraa ta’e nagaya gochuu sirra barbaade,nagaya isaaf godhi hanga inni jecha Rabbii (qur''aana) dhagahutti, Sana booda iddoo nagaya isaatiin isa ga’i, Kun waan isaan ummata hin beekne ta’aniifi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 7, 'Qindeessitootaaf waadaan Rabbiin biraafi ergamaa Isaa bira akkamitti jiraataaf? isaan masjiida kabajamaa biratti waadaa walii seentan malee, hanga isaan (waadaadhaan) isiniif dhaabbatanitti isinis isaaniif dhaabbadhaa, Dhugumatti Rabbiin warra Isa sodaatan jaalata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 8, 'Odoo isin irratti injifannoo argatanii, firummaafi waadaas isin keessatti kan hin eegganne ta’anii, akkamitti (waadaan isaaniif ta’a)? Afaanoowwan isaaniitiin isin jaallachiisu; Onneewwan isaanii immoo ni diddi. Irra hedduun isaaniis finciltoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 9, 'Keeyyattoota Rabbiitiin bu’aa xiqqaa bitatanii karaa Isaa irraas (namoota) dhorgan, Dhugumatti isaan wanti isaan dalagaa turan waa fokkate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 10, 'Mu’umina keessatti, firummaas ta’ee waadaa hin eeggatanu, Warri sun isaanumatu daangaa dabritoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 11, 'Yoo tawbatanii, salaata gadi dhaabanii, zakaa kennan (isaan) amantii keessatti obboleeyyan keessani, keeyyattoota keenya ni addeessina Ummata xiinxalaniif .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 12, 'Yoo erga waadaa seenanii booda waadaa isaanii diiganii amantii keessan xiqqeesan,hoggantoota kufriitin lolaa isaan waadaan isaaniif hin jiruu, akka dhorgamaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 13, 'Sila ummata waadaa isaanii diiganii, ergamaa (Rabbii) biyya irraa baasuuf barbaadan, isaan dursanii kan isin (miidhuu) jalqaban odoo ta’anii jiranuu maaliif isaaniin hin lolle? Sila isaan sodaattuu?Rabbitu isin Isa sodaachuu irra haqa godhata Yoo mu’uminoota taatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 14, 'Isaaniin lolaa, Rabbiin harkoowwan keessaniin isaan adaba; isaan salphisa; isaan irratti isinii tumsa; qalbii warra mu’uminootaa ni fayyisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 15, 'Dallansuu onneewwan isaaniis ni deemsisa; Rabbiin nama fedhe irra toowbaa qeebala, Rabbiin beekaa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 16, 'Sila odoo Rabbiin isin irraa namoota qabsaa’aniifi kan -Rabbiin, ergamaa isaatiifi mu’uminootaan- ala jaalalloo hin godhatin adda hin baafne dhiifamtu seetuu? Rabbiin waan isin dalagdan keessa beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 17, 'mushrikootaaf hin malu masjiidota Rabbii jiraachisuun, Odoo lubbuu isaanii irratti kufrii ragaa ba’anii. Isaan dalagaaleen isaanii badde. Isaan ibidda keessa yeroo hunda jiraatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 18, 'Masjiidota Rabbii kan jiraachisu nama Rabbiifi Guyyaa Qiyaamaatti amane, kan salaata gadi dhaabe, zakaa kenneefi Rabbiin malee homaa hin sodaanne qofa, Warri kun isaan karaa sirrii qabatan irraa ta’uun mirkana’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 19, 'Sila warra hajja’u obaasuufi masjiida kabajamaa jiraachisuu akka (imaana) nama Rabbiifi Guyyaa Qiyaamaatti amanee, karaa Rabbii keessatti qabsaa’ee gootuu? Rabbiin biratti wal hin qixxaa’an. Rabbiin ummata midhaa hojjatoota hin qajeelchu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 20, 'Isaan amananii, godaananiifi karaa Rabbii keessatti qabeenyaaleefi lubbuulee isaaniitiin qabsaa’an; Rabbiin biratti sadarkaadhaan irra guddatoodha. Isaan sun isaanumatu milkaa’oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 21, 'Gooftaan isaanii isaan gammachiisa rahmata isarraa taheen, jaalalaafi jannatoowwan ishee keessa qananiin yeroo hundaa isaaniif jirtuun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 22, 'Yeroo hunda ishee keessa kan jiraatan ta’anii (isaan gammachiisa); Dhugumatti, Rabbiin Isa bira mindaa guddaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 23, 'Yaa warra amantan! Abbootii keessaniifi obboleeyyan keessan yoo isaan iimaana irra kufrii jaallatan, jaalallee hin taasifatinaa, Isin irraa namni jaalallee isaan taasifate, warri sun isaanumatu midhaa raawwatoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 24, 'jedhiin “Yoo abbootin keessan, ilmaan keessan, obboleeyyan keessan, niitiwwan keessan, firoonni keessan, qabeenyi isin ishee horattan, daldalli isin hir’achuu ishee sodaattaniifi manneen isin jaallattan Rabbi, ergamaa Isaatiifi karaa Isaa keessatti qabsaa’uu irra gara keessanitti (yoo) jaalatamaa ta’e, hanga Rabbiin murtii Isaatiin dhufutti eegaa” (jedhi). Rabbiin ummata finciltoota hin qajeelchu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 25, 'Dhugumatti, Rabbiin iddoo baay’eetti isin tumseera. Guyyaa (lola) Hunayni, yeroo baay’inni keessan isin dinqisiise, kan homaa isin irraa hin deebisin, dachiin bal’ina ishee wajjin isinitti dhiphattee, sana booda yeroo baqa duubatti garagaltan (waan ta’e yaadadhu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 26, 'Ergasii Rabbiin ergamaa Isaatiifi mu’uminoota irratti tasgabbii Isaa buuse. Waraana isin hin argines buusee, Isaan kafaran adabe. Kun galata kaafirootaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 27, 'Rabbiin sana booda nama fedhe irraa tawbaa isaa qeebala. Rabbiin araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 28, 'Yaa warra amantan! Mushrikoonni najisa; waggaa isaanii kana booda masjiidicha kabajamatti akka hin dhiyaanne. Yoo beela sodaattan Rabbiin yoo fedhe tola Isa irraa ta’een isin duroomsa. Dhugumatti, Rabbiin beekaa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 29, 'Isaan Rabbiifi Guyyaa Dhumaatti hin amannen lolaa, kan waan Rabbiifi ergamaan Isaa haraam godhe haraam hin godhin, kan amantii haqaa hin fudhanne, warra kitaabni kennameef irraa kan ta’an hanga isaan salpatoo ta’anii gibira harkatti kennanitti (loolaani).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 30, 'Yahuudonni “Uzayr ilma Rabbiiti” jedhan. Kiristaanonni “Masiih ilma Rabbiiti” jedhan. Kun jecha isaanii kanuma afaanoowwan isaaniiti. Jecha isaan duraan kafaraniitti ni fakkeessu. Rabbi isaan haa abaaru, akkamitti (dhugaa irraa) garagalu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 31, 'Hayyoota isaaniitiifi molokseewwan isaanii Rabbiin alatti gabaramtoota godhatan; Masiih ilma Maryamis (gabbaramaa godhatan). Gooftaa tokkicha gabbarutti malee hin ajajamne, Isa malee gabbaramaan haqaa hin jiru, Inni waan isaan itti qindessan irraa qulqullaa’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 32, 'Isaan (kaafiroonni) ifaa Rabbii afaanoowwan isaaniitiin dhaamsuu fedhu, Rabbiin ifaa Isaa guutuu malee (fedhii isaanii) ni dida, Oduma kaafirtoonni jibbanuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 33, 'Inni (Rabbiin) Isa ergamaa Isaa qajeelumaafi amantii haqaatiin ergeedha,amantii hundarra ol taasisuuf jecha, odoma mushrikoonni jibbanuu,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 34, 'Yaa warra amantan! Dhugumatti irra hedduun hayyootaafi moloksootaa qabeenya namootaa haqaan malee nyaatan; karaa Rabbii irraa (namoota) deebisu, Isaan meetaafi warqee kuusatan, kan karaa Rabbii keessatti ishee hin sadaqanne adabbii laalessaan isaan gammachiisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 35, 'Guyyaa ibidda jahannam keessatti ishee irratti ho’ifamu, kan addawwan isaanii, cinaachowwan isaaniitiifi dugdoowwan isaanii isheen gubamu (kawuyeeffamu), “Kun waan isin lubbuulee keessaniif kuusaattani; waan kuusaa turtan dhandhamaa” (jedhamu)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 36, 'Lakkoofsi ji’ootaa Rabbi biratti ji’a kudha lamaI, kitaaba Rabbii keessatti, gaafuma samiifi dachii uume. saan keessaa afur kabajamoodha. Sanatu amantii sirriiti. Isaan keessatti lubbuulee keessan hin miidhinaa. Mushrikoota tokko ta’aatii lolaa akkuma isaan tokko ta’anii isiniin lolan; Rabbiin warra isa sodaatan wajjin ta’uu beekaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 37, 'Kabajaa ji’a tokkoo gara ji’a birootti siqsuun kufrii irratti (kufrii) dabaluudha, Warri kafaran isaan jallifamu, Waggaa tokko (keessa) hayyamamaa isa godhu; waggaa biraa immoo dhorgamaa isa godhu, Akka lakkoofsa wanta Rabbiin dhorgamaa godhee qunnamaniif jecha, waan Rabbiin dhorgamaa godhe hayyamamaa godhu, Fokkataan hojii isaanii isaaniif miidhagfame, Rabbiin ummata kaafira hin qajeelchu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 38, 'Yaa warra amantan! Maaltu isiniif jiraayyi yeroo karaa Rabbii keessatti (lolaaf) bahaa isiniin jedhame gara lafaatti rinciccu? Sila jireenya Addunyaa Aakhiraa irra jaalatanii? Qananiin jireenya Adunyaa Aakhiraa biratti xiqqo malee hintaane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 39, 'Yoo isin (jihaadaaf) hin bahin, (Rabbiin) adabbii laalessaa isin adaba; Ummata isiniin alaa bakka keessan buusa; isin homaa Isa hin miitan, Rabbiin waan hunda irratti danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 40, 'Yoo isin isaaf tumsuu baattan, dhugumatti Rabbiin isaaf tumseera -yeroo warri kafaran lammaffaa nama lamaa ta’ee isa (Makkaarraa) baasan, yeroo isaan lamaanuu goda keessa ta’an, yeroo inni saahiba isaatiin “hin gaddin Rabbiin nu waliin jiraa; ” jedhu san- (Rabbiin isaaf tumseera). Rabbiin tasgabbii Isa irraa ta’e isa irratti buuse; waraana isin ishee hin arginiinis isa jabeesse, Jecha warra kafaranii gad aantuu taasise, Jechi Rabbii isheedhumatu ol aantuudha, Rabbiin injifataa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 41, 'Salphoo taatanii yookiin ulfaatoo[] taataniis duulaaf bahaa; Qabeenyaaleefi lubbuulee keessaniin karaa Rabbii keessatti lolaa. kanatu isiniif caalaadha, Yoo kan beektan taatan.[1]', '[1] Salphoofi ulfaatoo jechuun: Haala hunda keessattuu dargaggeessas taatanii jaarsa, qabaataas taatanii dhabaa, dadhabaas taatanii danda’aa, dhukkubsataas taatanii fayyaa jechuudha. Kuni yeroo jalqabaatiif ture; booda garuu keeyyata “warra hin dandeenye irra badiin hin jiru” jedhuun shaarameera.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 42, '(Wanti ati itti isaan waamtu) odoo bu’aa dhihoofi imala giddu galeessa ta’ee silaa si hordofu turan. Garuu imalatu isaanitti fagaate, “Odoo dandeenyee silaa isin wajjiin baana turre” (jedhanii) Rabbiin kakatu. Lubbuulee isaanii balleessu. Rabbiin nibeeka kijibdoota ta’uu isaanii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 43, '(Yaa Muhammad!) Rabbiin dhiifama siif godhee,(lola irraa hafuu) maalif isaaniif hayyamte? hanga isaan dhugaa dubbatan ifa siif ta’anii warra soban beektutti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 44, 'Isaan Rabbiifi Guyyaa Aakhiraatti amanan qabeenyaaleefi lubbuulee isaaniitiin qabsaa’uu irraa (hafuuf) hayyama si hin gaafatanu. Rabbiin warra Isa sodaatu beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 45, '(Lola irraa hafuuf) hayyama kan si gaafatu isaan Rabbiifi guyyaa aakhiraatti hin amanin kan onneewwan isaanii shakkiteedha; Isaanis shakkii isaanii keessa deddeebi’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 46, 'Odoo (lolaaf) bahuu fedhanii silaa qophii isaaf qophaa’u turan, Garuu Rabbiin bahuu isaanii jibbee duubatti isaan hanbise; “warra taa’uu[1] wajjiin taa’aa” jedhame.', '[1] Warra taa’u jechuun ijoollee, dubartootaafi dhukkubsataa wajjiin jechuu dha.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 47, 'Odoma isinii waliin ba’aniiyyuu badii malee homaa isiniif hin dabalanu. Rakkoo kan isinitti barbaadan ta’anii, jeequmsaan gidduu keessan fiigu turan, Isin keessas namoota isaaniif dhaggeeffatantu jiru. Rabbiin miidhaa hojjattoota ni beeka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 48, 'isaan duraanis rakkoo barbaadanii dhimmoota siif gara gaggalchanii turan, hanga dhugaan dhufee murtiin Rabbii ifa ba’utti osomaa isaan jibbanuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 49, 'Isaan irraa nama “(hafuuf) naaf hayyami; nas hin qormaatin” jedhuutu jira, Dhagayaa! (isaan) qormaata keessatti kufaniiru. Dhugumatti Jahannam kaafirootatti marsituudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 50, 'Yoo toltuun si mudatte, isaan gaddisiifti, Yoo balaan si mudatte immoo “nuti dursinee of eeggannoo keenya qabannee jirra” jedhan; kan gammadan ta’anii duuba deebi’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 51, '“Waan Rabbiin nuuf barreesse malee homaa nu hin mudatu. Inni tiksaa keenya” jedhi, Mu’uminoonni Rabbuma (qofa) irratti haa hirkatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 52, 'Jedhiin “Sila tokkoo toltuu lamaanii malee waan biraa nutti eegduu? Nuti Rabbiin adabbii Isa biraa ta’een yookiin harkoowwan keenyaan isin tuquu eegna. Isinis eegaa; nutis isin wajjiin eegoodha” (jedhi).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 53, '“Kan jaallattanis ta’aatii yookiin kan jibbitan ta’aa arjoomaa; isin irraa hin qeebalamu, Dhugumatti, isin ummata finciltoota turtan” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 54, 'wanti sadaqaan isaanii isaan irraa qeebalamuu dhorge hin jiru Rabbiifi ergamaa isaatti kafaruu,isaanii malee, (akkasuma) salaata hifatoo ta’anii malee kan hin dhufneefi, kan jibban ta’anii malee arjoomuu dhabuu (isaanii malee). .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 55, 'Qabeenyaaleen isaaniitiifi ilmaan isaanii si hin ajaa’ibsiisin, Dhugumatti, wanti Rabbiin fedhu jireenya Addunyaa keessatti isheedhaan isaan adabuufi kaafiroota ta’anii lubbuun isaanii bahuu fedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 56, 'Isaan dhugumatti isin irraayyi jechuun Rabbiin kakatu; isaan isin irraayii miti, Garuu isaan ummata sodaatanuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 57, 'Odoo iddoo itti baqatan yookiin goda wahii yookiin iddoo seenan (qaawwa wahii) argatanii silaa kan fiigan ta’anii gara isaatti deebi’u turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 58, 'Isaan irraas nama (qooda) sadaqaa keessatti maqaa si xureessutu jira, Yoo ishee irraa kennaman ni jaallatu; yoo ishee irraa hin kennamne immoo yoosan isaan ni jibbu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 59, 'Odoo isaan waan Rabbiifi ergamaan Isaa isaaniif kenne jaalatanii “Rabbiin nuuf ga’aadha, Rabbiin fuula dura tola Isaa irraa nuuf kenna, Ergamaan Isaas (akkasuma). nuti gara Rabbii kajeeloodha” jedhanii (silaa isaaniif caalaa ture).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 60, 'Zakaawwan (kan qoodamtu) dhabeeyyiif, hiyyeeyyiif, warra ishee irratti hojjataniif, warra onneewwan isaanii (Islaamummaa) barsiifamtuuf, gabra bilisoomsuuf, warra idaan irra jiruuf, karaa Rabbii keessattiifi kara deemaadhaaf, (qofa). Dirqama Rabbi irraa ta’e (qabadhaa). Rabbiin beekaa, ogeessa', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 61, 'Isaan irraas warra Nabiyyii rakkisantu jiru; “Inni gurra” jedhu, Jedhiin: “(Eeyyeen inni) gurra isiniif gaarii ta’eedha; Rabbitti ni amana, Mu’uminootas ni dhugoomsa. Isin irraa warra amananiifis rahmata.” Isaan ergamaa Rabbii rakkisan, isaaniif adabbii laalessaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 62, 'Isin gammachiisuf Rabbiin isiniif kakatu;Rabbiifi ergamaa Isaatu isaan isa gammachiisuu irra haqa godhata yoo mu’uminoota ta’an .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 63, 'Sila isaan hin beeknee? nama Rabbiifi ergamaa Isaa faallesse, ibidda jahannamtu ishee keessatti kan hafu ta’ee isaaf jira jechuu. Kun salphina guddaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 64, 'Munaafiqoonni suuraan waan onneewwan isaanii keessa jiru isaanitti odeessitu isaan irratti buufamuu sodaatu. Jedhiin: “qishnaa godhaa. Rabbiin waan isin sodaattan (ifa) baasaadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 65, 'Yoo isaan gaafatte “Nuti haasawatti kan seennuufi kan taphannu qofa turre” jedhu. “Sila Rabbitti, keeyyattoota Isaatiifi ergamaa Isaatti qishnaa kan gootan taatanii? jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 66, 'Rakkoo hin himatinaa! Dhugumatti isin erga amanuu keessaniitii booda kafartanii jirtu. Yoo garee isin irraa ta’eef irra dabarre, garee biraa ni adabna, waan isaan yakkamtoota ta’aniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 67, 'Munaafiqoonni dhiiraatiifi munaafiqoonni dubartii gariin isaanii garii irraayi. Waan jibbamaatti ni ajaju; waan gaarii irraa immoo ni dhorgu; harkoowwan isaanii (kenna irraa) ni deeffatu; Rabbiin dagatan; Innis isaan dhiise. Dhug munaafiqoonni isaanumatu finciltoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 68, 'Rabbiin munaafiqoota dhiiraa, munaafiqoota dubartiifi kaafirootaafis ibidda jahannam beellamee jira, ishee keessatti kan hafoodha, isheen isaaniif geessuudha, Rabbiin isaan abaareera. Isaaniif adabbii itti fufaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 69, '(Isin) akkuma warra isin dura dabraniiti; Isaan humnaan isin irra jajjaboo turan, qabeenyaafi ilmaaniinis isin irra baay’ee turan, Isaan qooda isaaniitiin ni qanani’an, akkuma warri isin dura (dabran) qooda isaanitti qanani’an isiniis qooda keessanitti qananiitan. Akkuma isaan (tapha) keessa seenan isinis (tapha) keessa seentan. Warri sun Addunyaafi Aakhiraattis dalagaaleen isaanii baddee jirti. Warri sun isaanumatu hoonga’oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 70, 'Sila oduun warra isaan duraa isaanitti hin dhufnee? (Oduun) ummata Nuuh, Aad, Samuud, ummata Ibraahiim, jiraattota Madyaniifi (gandattii) garagalfamtuu (isaanitti hin dhufnee)? Ergamtoonni isaanii ragaa ifa ta’een isaanitti dhufanii jiru. Rabbiin kan isaan miidhu hin taane. Garuu isaan lubbuulee isaanii kan miidhan turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 71, 'Mu’uminoonni dhiiratiifi Mu’uminoonni dubaraa gariin isaanii jaalallee gariiti. Toltutti ajaju; hamtuu irraas ni dhorgu, salaata gadi dhaabu; Zakaa ni kennu; Rabbiifi ergamaa Isaatiifis ni ajajamu. Warri sun Rabbiin fuula dura rahmata isaaniif godha. Rabbiin injifataa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 72, 'Rabbiin mu’uminoota dhiiraatiifi dubartootaatiifis jannata laggeen ishee jala yaatu,waadaa galee, ishee keessatti kan hafan ta’anii manneen gaggaarii jannata qubsumaa keessa taates (waadaa galee jira). Jaalalli Rabbiin irraa ta’e (hunda) irra guddaadha. Kun milkii guddaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 73, 'Yaa Nabiyyichaa! kaafirootaafi munaafiqoota irratti qabsaa’i; isaan irratti jabeessi. Teesson isaanii jahannami. Deebiin isaanii (jahannam) waa fokkatee!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 74, 'Homaa hin jenne jedhanii Rabbiin kakatu. Dhugumatti isaan jecha kufrii jedhaniiru; Erga Islaamummaa isaaniitii kafaraniiru; Waan itti hin geenye yaadaniiru; Rabbiifi ergamaan isaa tola Isa irraa ta’een isaan duroomsuu malee waan biraa hin jibbine. Yoo tawbatan caalaa isaaniif ta’a; yoo (irraa) garagalan immoo Rabbiin Addunyaafi Aakhiraattis adabbii laalessaan isaan adaba. Dachii keessatti jaalalleefi tumsaan isaaniif hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 75, 'Isaan irraas namoota “Yoo (Rabbiin) tola Isaa irraa nuuf kenne, silaa dhugumatti ni arjoomna; Gaggaarii irraas ni taana turre” (jechuun) Rabbiif waadaa seenantu jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 76, 'Yeroma (Rabbiin) tola Isaa irraa isaaniif kenne, ittiin doynoomani; kan garagalan ta’anii dugda duuba deebi’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 77, 'Munaafiqummaa onnee isaanii keessatti isaan dhaalchise, hanga guyyaa Isaan wal qunnamaniitti. waan Rabbiin waadaa isaa faallessaniifi waan sobaa turaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 78, 'Sila Rabbiin iccitii isaaniitiifi maqoo isaaniis kan beeku ta’uufi Rabbiin wantoota fagoo hundas akkaan beekaa ta’uu hin beeknee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 79, '(Isaan) warra mu’uminoota irraa warra arjoomuu keessatti tola oolaniifi isaan waan dandeettii isaanii malee hin arganne maqaa xureessaniidha; Isaan isaanitti qishinu. Rabbiin isaanitti qishina (isaan adaba). Isaaniif adabbii laalessaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 80, 'Araarama isaaniif kadhadhus yookiin araarama isaaniif kadhachuu dhiisis; yoo yeroo torbaatama araarama isaaniif kadhattes, Rabbiin isaaniif hin araaramu. Kun waan isaan Rabbiifi ergamaa Isaatti kafaraniifi. Rabbiin ummata finciltoota hin qajeelchu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 81, 'Isaan (duula irraa) hafan, booda ergamaa Rabbiitii taa’uu isaaniitti gammadan; qabeenyaaleefi lubbuulee isaaniitiin karaa Rabbii keessatti qabsaa’u ni jibban; “ho’a keessa duulaaf hin bahinaa” jedhan. “Odoo beekanii ibidda jahannamtu ho’atti irra cimaadha” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 82, 'xiqqoo kolfanii baay’ee haa boo’an. Galata waan kan hojjatan tahaniitiif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 83, 'Yoo Rabbiin gara garee isaan irraa ta’eetti si deebisee, (duulaaf) bahuuf hayyama si gaafatan,jedhiin. “Ana wajjiin gonkumaa hin baatanu; Ana wajjinis diinaan hin loltanu, Isin dhugumatti yeroo jalqabaa taa’umsa jaalattanii jirtu. Kanaafuu warra (mana) taa’an wajjin taa’aa”(jedhiin).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 84, 'Isaan irraa nama du’e tokkollee irratti hin sagadin, Qabrii isaa irras hin dhaabbatin, Dhugumatti isaan Rabbiifi ergamaa Isaattis kafaran. finciltoota ta’anii du’aniiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 85, 'Qabenyi isaaniitiifi ilmaan isaanii si hin ajaa’ibsiisin. Rabbiin isheedhaan addunyaa keessatti isaan adabuu fedha, isaan kaafiroota ta’anii lubbuun isaanii bahuu (fedha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 86, 'Yeroo suuraan Rabbitti amanaa ergamaa Isaa wajjiinis qabsaa’aa isaaniin jettu tokko buufamte, isaan irraa warri qabeenya qaban si hayyamsiifatu“Nu dhiisi; nuti warra taa’an wajjin taanaa” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 87, 'Warra (duula irraa) hafan wajjiin ta’uu jaalatan. Onneewwan isaanii irratti cufameera, isaan hin hubatanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 88, 'Garuu ergamichiifi warri isaa wajjin amanan, qabeenyaaleefi lubbuuwwan isaaniitiin qabsaa’anii jiru. Warri sun toltuu baay’eetu isaaniif jira. Warri sun isaanumatu milkaa’oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 89, 'Rabbiin jannata laggeen ishee jala yaatu, Isaan ishee keessatti kan hafan ta’anii, isaaniif qopheessee jira. Kuni milkii guddaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 90, 'Tikfattoota baadiyyaa irraa warri rakkoo himatan akka hayyamni isaaniif godhamuuf jecha dhufan. Isaan Rabbiifi ergamaa Isaa kijiban ni taa’an. Isaan irraa warra kafaran fuula dura adabbii laalessaatu isaan mudata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 91, 'Dadhaboota, dhukkubsattootaafi isaan waan kennatan hin arganne irratti diliin hin jiru, yoo Rabbiifi ergamaa Isaatiif toltuu yaadan (duuluu baatanis). Toltuu raawattoota irra karaan (komii) hin jiru. Rabbiin araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 92, 'Isaan akka waan yaabbatan isaaniif kennitu yeroo sitti dhufan, ati “waan yaabbattan isiniif arguu hin danda’u” jetteen, waan sadaqatan dhabuu irraa gaddaan ijji isaanii imimmaan yaasaa deebi’an irras (komiin) hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 93, 'Karaan (Komii) kan jiru warra dureeyyii ta’anii hayyama si gaafatan qofa irra. Warra hafan waliin ta’uu jaalatan; Rabbiin onnee isaanii irratti cufe; kanaafuu, isaan homaa hin beekan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 94, 'Yeroo gara isaanii deebitan rakkina kara keessan dhiheeffatu. jedhiin “rakkina hin himatinaa; Nuti isiniif hin amannu. Dhugumatti, Rabbiin oduu keessan irraa nuuf himee jira. Rabbiifi ergamaan Isaas hojii keessan arguuf jiru. Sana booda gara isa waan mul’atuufi hin mul’anne beekuutti deebifamtu. Waan isin dalagaa turtan isinitti hima” (jedhiin).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 95, 'Yeroo isin gara isaanii deebitan akka isin isaan irraa gara galtaniif Rabbiin isiniif kakatu; isaan irraa gara galaa; isaan najisa.teesson isaanii jahannama galata waan dalagaa turaniitiif .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 96, 'Akka isin isaan irraa jaalattaniif isiniif kakatu, Yoo isin isaan irraa jaalattanis, Rabbiin dhugumatti ummata finciltoota irraa hin jaalatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 97, 'Horsiisee bultoonni kufriifi munaafiqummaatti irra cimoodha; daangaawwan waan Rabbiin ergamaa Isaa irratti buusee beekuu dhabuutti irra dhihoodha. Rabbiin hunda beekaa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 98, 'Horsiisee bultoota irraa namoota waan (karaa Rabbii keessatti) arjoomu akka idaatti qabatujjira. naannoowwan (rakkinaa) isinitti eega. Naannoon hamtuu isaan irratti haa ta’u. Rabbiin dhaga’aa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 99, 'Ammas tikfattoota baadiyyaa irraa nama Rabbiifi Guyyaa Aakhiraatti amanee waan (karaa Rabbii keessatti) arjoomus Rabbiin biratti dhiheenyaafi kadhaa ergamichaa godhatutu jira. Dhagayaa! dhugumatti isheen isaaniif dhiheenya. Rabbiin fuula dura rahmata Isaa keessa isaan seensisa. Dhugumatti Rabbiin araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 100, 'Muhaajirootaafi Ansaarota irraas dursitoonni jalqabdoota ta’aniifi warri toltuudhaan isaan hordofanis, Rabbiin isaan irraa jaalateera. Isaanis Isa irraa jaalatanii jiru. Jannata ishee jala laggeen yaatu kan ishee keessatti abad hafan ta’anii isaaniif qopheessee jira. Kun milkii guddaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 101, 'Tikfattoota baadiyyaa irraa gariin warra naannoo keessan jiruu munaafiqoota. Warra Madiinaa irraas (namoota) munaafiqummaa irratti ragga’an jiru, ati isaan hin beeknetu. Nuti isaan ni beekna. Fuula dura yeroo lama[1] isaan adabna. Ergasii isaan gara adabbii guddaa deebifamu.', '[1]Adabbiin lama: tokkoffaan komii addunyaati. Inni lammaffaa immoo adabbii qabriiti.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 102, 'Warri biroo immoo kan badiilee isaanii fudhatan, dalagaa gaariifi fokkataa biraa walitti makantu jiru; Rabbiin tawbaa isaanii irraa qeebaluun nikajeelama, Rabbiin araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 103, 'Qabeenya isaanii irraa sadaqaa isheedhaan isaan qulqulleessituufi isaaniif dabaltuun fuudhi. Rabbiinis isaaniif kadhu; kadhaan kee isaaniif tasgabbiidha. Rabbiin dhagayaa, beekadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 104, 'Sila isaan ‘Rabbiin Isatu gabroota Isaa irraa tawbaa qeebalaafi sadaqaas fudha’ jechuu hin beeknee? Ammas dhugumatti ‘Rabbiin isatu tawbaa qeebalaafi rahmata godhaa dha’ jechuus (hin beeknee?).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 105, 'Hojjadhaa jedhiin, Rabbiin, ergamaan Isaatiifi mu’uminoonnis fuula dura dalagaa keessan ni argu, Gara beekaa wantoota hin mul’anneefi wantoota mul’ataniis fuula dura ni deebitu, Waan isin dalagaa turtanis isinitti odeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 106, 'Warri biroo immoo kan murtii Rabbii (eeguuf) booda aanfamantu jiru. Yookiin isaan adaba, yookiin immoo tawbaa isaan irraa qeebala. Rabbiin beekaa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 107, 'Warri (mu’uminoota) rakkisuuf,masjiida tolfatan, akkasuma kufrii (babal’isuuf), gidduu mu’uminootaa addaan baasuufi, nama duraan Rabbiifi ergamaa Isaatiin loleef eegumsa godhuuf, (jecha masjiida tolfatanis isaanuma irraayyi). Dhugumatti kakatu “Nuti toltuu malee homaa hin feene” jedhanii. Rabbiin isaan kijibdoota tahuu ragaa baha.[1]', '[1] aayanni kuni wanni ibsu:-munaafiqootaatu ganda keessatti masgiidaa seeraan alaa jaaran, muimina addaan qoqqooduufii addawwii akka achi qubattu godhuuf qopheessan, maqaan isaa masgiida diraar (rakkoo) jedhama. nabiin namoota itti ergee diigamee gubame.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 108, 'Gonkumaa isa (masjiidicha) keessa hin dhaabbatin. masjiida guyyaa jalqabaa irraa sodaa (Rabbii) irratti bu''ureeffametu ati isa keessa dhaabbachuu haqa godhata. Isa keessa namoota qulqulleeffachuu jaalatantu jiru. Rabbiin qulqulleeffattoota jaalata. [1]', '[1] masgiinni sodaa Rabbiirratti bu''ureeffame masgiida qubaati. moggaa madiinaatti argama sadarkaa guddaa qaba.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 109, 'Sila nama jaarmaya isaa sodaa Rabbi irraa ta’eefi jaalala (Isaa) irratti bu’uurse moo, nama jaarmaya isaa afaan boollaa kan cituutti dhiyaate irratti bu’uuressee, ibidda jahannam keessatti isaan kufetu caala? Rabbiin ummata miidhaa hojjattoota hin qajeelchu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 110, 'Ijaarsi isaanii inni isaan ijaaran onneewwan isaanii keessatti (munaafiqummaafi) shakkii ta’uu irraa hin deemu.yoo onneewwan isaanii ciccitte malee. Rabbiin beekaa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 111, 'Rabbiin mu’uminoota irraa jannanni isaaniif ta’uudhaan lubbuuleefi qabeenyaalee isaanii biteera. Karaa Rabbii keessatti lolu; ni ajjeesu; ni ajjeefamus. Kun Tawraat, Injiiliifi Qur’aana keessatti waadaa Isa irratti mirkanaa’eedha. Namni Rabbi irra waadaa isaa guutu eenyu? Kanaafuu gurgurtaa keessan isa gurgurttaniin gammadaa. Sunis isatu milkii guddaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 112, '(Isaan) tawbattoota, gabbartoota, faarsitoota, soomtoota, warra rukuu’a godhan, warra sujuuda godhan, warra toltuutti ajajan, warra hamtuu irraa dhorganiifi warra daangaalee Rabbii eeganiidha. Mu’uminootas (jannataan) gammachiisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 113, 'Nabiyyichaafi warra amananiif, mushrikootaaf (Rabbiin) araarama kadhachuun kan malu hin taane, odoo firoota dhihoo ta’anillee, erga warra jahannam ta’uun ifa isaaniif ta’ee booda, .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 114, 'Araarama abbaa isaatiif kadhachuun Ibraahiim waadattii ishee isaaf seene sana (guutuu) irraayyi malee waan biraa hin turre. Yeroma inni diina Rabbii ta’uun ifa isaaf ta’u isa irraa qulqullaa’e, Dhugumatti, Ibraahiim akkaan Rabbi kadhataadha, obsaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 115, 'Rabbiin ummata tokko erga isaan qajeelchee booda hanga waan isaan eeggachuu qaban isaaniif ibsutti kan (isaan) jallisu (yakkamaa godhu) hin taane, Dhugumatti, Rabbiin waan hunda beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 116, 'Dhugumatti, Rabbiin mootummaan samiileefi dachii kan Isaati. Ni jiraachisa; ni ajjeesas. Rabbiin alatti tiksaafi tumsaan tokkollee isiniif hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 117, 'Dhugumatti Rabbiin nabiyyicha, muhaajirootaafi ansaarota itti araarame. warra yerottii rakkoo keessa isa hordofan, erga onneen garee isaan irraa ta’anii jallachuutti dhihaatee booda. Sana booda Rabbiin tawbaa isaanii qeebaleera, inni isaaniif mararfataa rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 118, 'Warra sadeen booda aanfaman (irraa Rabbiin tawbaa qeebale) kaneen hanga dachiin bal’ina ishee wajjin isaan irratti dhiphattee, lubbuun isaaniis isaan irratti dhiphattee, Rabbi irraas gara Isaatti malee iddoon itti baqatan hin jiruu hanga mirkaneeffatanitti (booda aanfaman irraas) (Rabbiin tawbaa qeebaleera). Sana booda akka isaan tawbataniif jecha tawbaa isaan irraa qeebale. Dhugumatti, Rabbiin Isatu araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 119, 'Yaa warra amantan! Rabbiin sodaadhaa; warra dhugaa wajjiiniis ta’aa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 120, 'Warra Madiinaatiifi tikfattoota baadiyyaa irraa warra moggaa isaaniitti argamaniif ergamaa Rabbii irraa duubatti hafuufi lubbuu isaaniis lubbuu isaa irra jaalachuun isaaniif hin malu ture. Sunis sababa hojiin gaariin ittiin isaaniif barreeffamu malee karaa Rabbii keessatti dheebuun, dadhabbiifi beellis kan isaan hin mudanne ta’ee akkasumas iddoo ejjannaa kaafiroota dallansiisu tokkoos hin ejjanneefi diina irraas (ajjeesuufi booji’uun) qaqqabiinsa tokkos kan hin qaqqabne (waan) ta’eefiDhugumatti, Rabbiin mindaa toltuu raawwattootaa hin balleessu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 121, 'Kennaa xiqqoos ta’ee guddaa hin kennan; laga tokkos hin qaxxaamuran, yoo isaaniif barreeffame malee, Rabbiin gaarii waan isaan dalagaa turanii isaanii galata galchuuf jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 122, 'Mu’uminoonni (nabiyyii wajjin yoo ta’e malee) dimshaashatti duulatti bahuun isaaniin hin malu. Sila maaliif garee hunda irraa muraasni tokko hin lolle? (Warri biroo immoo) akka amantii keessatti hubannoo godhatanii yeroo gara isaaniitti deebi’an, akka isaan dinniinaniif (gorsaniif) jecha (maaliif hin hafne). Akka isaan (hamtuu) eeggataniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 123, 'Yaa warra amantan! Kuffaara irraa warra isinitti aananiin lolaa. Isin keessattis jabeenya haa arganu. Rabbiinis warra Isa sodaatan wajjin jiraachuu beekaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 124, 'Yeroo suuraan tokka buute isaan irraa nama “eenyuu keessaniif isheen tun iimaana dabalte?” jedhutu jira. Egaa isaan amananiif kan gammadanu ta’anii iimaana isaaniif dabalte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 125, 'Isaan onneewwan isaanii keessa dhukkubni jiru immoo najisa isaanii irratti najisa isaaniif dabalte. Isaan kaafiroota ta’anii du’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 126, 'Sila isaan waggaa hunda keessa yeroo tokko yookiin yeroo lama mokkoramuu isaanii hin arganuu? Ergasii hin tawbatanii? Isaanis hin gorfamanuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 127, 'Yeroo suuraan (isaan saaxiltu) takka buufamte, gariin isaanii gara garii isaanii ilaala “namni tokko sila isin argaa jiraa?” jedhaa. Sana booda garagalanii deemu. Rabbiin onneewwan isaanii garagalche Waan isaan ummata hubannoo hin qabne ta’aniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 128, 'Dhugumatti, iisinitti dhufe ergamaan isin irraa ta’e, kan rakkinni keessan isa irratti jabaatu, kan isiniif (akka amantanuuf) bololu, mu’uminootaaf immoo mararfataa, rahmata godhaa ta’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 129, 'Yoo isaan (sirraa) garagalan, jedhi “Rabbiin naaf gahaadha. Isa malee haqaan Gabbaramaan hin jiru. Isa qofa irrattin irkadhe; Innis Gooftaa arshii guddaati”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 1, 'Alif Laam Raa Sunniin keeyyattoota kitaabicha ogummaan guutameeti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 2, 'Sila gara nama isaan irraa ta’ee “nama akeekkachiisi; warra amanes toltuun dabre Rabbii isaanii bira isaaniif jiraachuudhaan gammachiisi” jechuun wahyii godhuun keenya namootatti dinqii ta’eeraa? Kaafirtoonni: “Dhugumatti, inni kun falfalaa ifa bahaadha” jedhan', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 3, 'Dhugumatti, Gooftaan keessan Allaah Isa samiifi dachii guyyoota jaha keessatti uumee, ergasii Arshii irratti (ol ta’iinsa isaaf malu) ol ta’eedha. Waan hundaa garagaggalcha. Araarsaan homaatuu hayyama Isaatiin booda malee hin jiru. Kun Rabbi Gooftaa keessani. aKanaafuu Isa qofa gabbaraa. Sila isin hin gorfamtanuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 4, 'Deebiin hunda keessanii gara Isaati. Waadaa Rabbiin (beellamee dha)Dhugaa gochuus (isa godhe). Isatu uumuu jalqabee, ergasiis isa deebisa. Isaan amananii, toltuu dalaganiif haqaan mindaa isaaniif kennuuf (akkas godhe). Isaan kafaran waan kafaraniif jecha isaanif dhugaatii danfaa irraa ta’eefi adabbii laalessaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 5, 'Inni Isa aduu madda ifaa, baatiis ifa taasisee, akka lakkoofsa waggootaafi herregaa beektaniif jecha bakka isaaf (Ji’aaf) godheedha. Rabbiin kana dhugaan malee hin uumne. (Rabbiin) keeyyattoota namoota beekaniif addeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 6, 'Dhugumatti, bakka wal bu’uu halkaniifi guyyaa keessa, waan Rabbiin samiileefi dachii keessatti uume keessaas namoota (Rabbiin) sodaataniif mallattooleetu jira', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 7, 'Dhugumatti, isaan qunnamtii keenya hin sodaanne, kan jireenya addunyaa qofa fedhanii, isheetti gammadaniifi isaan keeyyattoota keenya irraa dagatoo ta’an,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 8, 'Isaan sun waan hojjachaa turaniif jecha teessoon isaanii ibidda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 9, 'Dhugumatti, isaan amananii, gaggaarii hojjatan Gooftaan isaanii iimaana isaanitiin isaan qajeelcha. Jannatoota qananii keessa laggeen isaan jala yaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 10, 'Kadhaan isaanii ishee keessatti (yeroo waan tokko fedhan) “yaa Allaah! Qulqulliini keeti” jechuudha. Kabajaan isaaniis ishee keessatti “nagayaa” jechuudha. Kadhaan isaanii kan boodaas “faaruun hundi kan Rabbii gooftaa aalamaati” jechuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 11, 'Odoo Rabbiin namaaf akka isaan gaarii (argachuuf) jerjerfatanitti hamtuu isaaniif jerjersee, silaa beellamni (adabbii) isaanii, isaaniif raawwatama ture. Isaan wal ga’ii keenya hin sodaanne, jallina isaanii keessa dhama’oo taasifnee isaan dhiifna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 12, 'Ilmi namaa yeroo rakkinni wahii isa tuqe, cinaacha isaa irratti yookiin taa’eetis yookiin dhaabbateetis Nu kadhata. Yeroo Nuti rakkina isaa isa irraa fuune akka waan rakkina isa tuqeef Nu hin kadhatiniitti (kufrii isaa) itti fufa. Akka kanatti daangaa dabartootaaf wanti isaan hojjachaa turan miidhagfame.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 13, 'Dhugumatti, dhaloota isin duraa irraa, yeroo isaan lubbuu isaanii miidhanii, ergamtoonni isaanii raajii dirree taa’uun isaanitti dhufanii hin amanin balleessinee jirraAkka kanatti ummata badii raawwattoota ta’aniif galata galchina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 14, 'Ergasii isaan booda akkam akka dalagdan ilaaluuf jecha dachii keessatti bakka bu’oota isin taasifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 15, 'Yeroo keeyyattoonni keenya ifa ta’anii isaan irratti dubbifaman, isaan qunnamtii keenya hin sodaanne “Qur’aana kana hin ta’iniin nutti kottu; yookiin isa jijjiiri” jedhu. “Ani of biraa isa jijjiiruun naaf hin ta’u. Waan gara kiyyatti wahyii godhamu malee hin hordofu. Dhugumatti, ani yoon ajaja Gooftaa kiyyaa dide, adabbii guyyaa guddaan sodaadha” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 16, '“Odoo Rabbiin fedhee, silaa ani isa isin irratti hin dubbisu. Innis (Rabbis) isa isin hin beeksisu. Dhugumatti, ani isa duras yeroo dheeraa isin keessa jiraadheera. Sila isin sammuu hin qabdanii?” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 17, 'Nama Rabbi irratti kijiba uume yookiin kan keeyyattoota Isaa sobsiise caalaa namni miidhaa hojjate eenyu? Dhugumatti, badii raawwattoonni hin milkaa’anu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 18, 'Rabbiin ala waan isaan hin miineefi hin fayyadne gabbaranii “Isaan kun Rabbiin biratti manguddoota keenya” jedhu. “Sila isin waan Inni samiifi dachii keessatti hin beekne Rabbitti himtuu? Inni (Rabbiin) waan isaan Isa waliin gabbaran irraa qulqullaa’e, olis ta’ee jira” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 19, 'Ilmi namaa ummata tokko malee hin turre. Booda irra wal dhaban. Odoo jechi Gooftaa kee irraa ta’e dursee dabruu baatee, silaa waan isaan irratti wal dhaban keessatti gidduu isaaniitti ni murteeffama ture.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 20, '“Mallattoon Gooftaa isaa irraa maaliif isa irratti hin buufamin?” jedhu. “Wanti fagoo hundi Rabbumaafi. Isinis eegaa; Anis isin wajjin warra eegan irraayi” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 21, 'Yeroo namoota erga rakkoon isaan tuqee booda rahmata isaan dhandhamsiifne, yeroma san keeyyattoota keenya keessatti shira baasuun isaaniif ta’aadha. “Rabbitu tooftaatti isaan irra akkaan jarjaraadha” jedhi. Dhugumatti, ergamtoonni keenya (maleykonni) shira isin baaftan ni barreessu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 22, 'Inni Isa dachiifi bishaan keessas isin deemsisu. Yeroo dooniwwan keessatti taatanii qilleensa gaarii keessa isaaniin deemanii, isheetti gammadan, qilleensi bubbisaan isitti dhufa; danbaliin bakka hunda irraa isaanitti dhufa; isaanitti marfamuu yaadan. Rabbiin qofa kadhatan, ibaadaa Isaaf qulqulleessanii, "Yoo Ati (balaa) kana irraa nagaa nu baafte, nuti dhugumatti, warra (si) galateeffatan irraa taana” (jedhan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 23, 'Yeroma Inni nagaa isaan baase, isaan yoosuu haqaan ala dachii keessatti daangaa dabru. Yaa namootaa! Daangaa dabriinsi keessan lubbuulee keessan irratti. Qananii jireenya addunyaa (xiqqoo qananiitu), Sana booda deebiin keessan gara keenyattii, Nuti waan isin dalagaa turtan isinitti himna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 24, 'Dhugumatti, fakkeenyi jireenya addunyaa, akka bishaan Nuti samii irraa isa buufnee, ergasii biqiltuuwwan dachii kan waan ilmi namaatiifi horiin nyaatan irraa ta’an isaan wal makamanii, yeroo dachiin faaya ishee qabattee, miidhagdee, abbootiin ishee ishee irratti danda’oo ta’uu yaadan, adabbiin keenya halkan yookiin guyyaa isheetti dhufee, akka waan kaleessa achitti hin ta’iniitti (hin jirreetti) haamamaa ishee goone. Akka kanatti mallattoolee ummata xiinxalaniif adda baafna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 25, 'Rabbiin gara mana nagayaatti waama. Nama fedhe gara karaa qajeelaati qajeelcha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 26, 'Isaan toltuu hojjataniif (mindaa) gaariifi dabalataatu jira. Gurraachinniifi salphinni homaatuu fuula isaanii hin haguugu. Isaan sun warra jannataati. Isaan ishee keessatti hafoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 27, 'Isaan hamtuu hojjatan mindaan hamtuu fakkaatuma isheetiin ta’a. Salphinni isaan haguugdi. Rabbi irraa wanti isaan tiksu isaaniif hin jiru. Fuulli isaanii akka waan kutaa halkan dukkaneessaa ta’e irraa ta’een hagoogamanii fakkaatti. Isaan sun warra ibiddaati. Isaan ishee keessatti hafoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 28, 'Guyyaa isaan hunda walitti qabnus, (dubbadhu). Ergasii isaan Nutti qindeessaniin ni jenna: “Isiniifi warri isin Nu waliin gabbaraa turtanis iddoo jirtan dhaabadhaa!” Sana booda gidduu isaanii addaan baafne. Warri isaan Nu waliin gabbaraa turaniis: “Isin nu gabbaraa hin turre” jedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 29, 'Rabbumatu ga’aadha. ragaa ta’uuf “Gidduu keenyaafi gidduu keessanitti Dhugumatti, nuti isin gabbaruu irraa dagatoo taanee turre.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 30, 'Achitti lubbuun hundi waan dabarsite ni beekkatti, Gara Rabbii Gooftaa isaanii kan dhugaa deebifamu. Sobni isaan uummachaa turan isaan irraa bada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 31, 'jedhiin “Eenyutu samiifi dachii irraa isin soora? Yookiin dhageettiifi argituulee eenyutu dhuunfata? Ammas eenyutu jiraataa du’aarraa baasa, du’aa jiraatarraa baasa? Eenyutu waan hunda gara gaggalchas?” (jedhi). ‘Rabbuma’ jedhu. “Sila Rabbiin hin sodaattanii?” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 32, 'Sun Allaah, Gooftaa keessan, kan dhugaati. Dhugaa booda jallina malee maaltu jira? Akkamitti irraa gara galfamtu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 33, 'Akka kanatti jechi Gooftaa keetii, warra fincilan irratti mirkanoofte. isaan hin amanana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 34, 'Jedhi.“Sila warra isin Rabbii wajjiin gabbartan irraa warri uumama jalqabee, ergasii isa deebisu jiraa?”. jedhi “Rabbiin uumama jalqabeeti, ergasiis deebisa. Akkamumatti gara galfamtu?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 35, 'Jedhi.“Sila warra isin Rabbii wajjin gabbartan irraa warri gara haqaatti qajeelchu jiraa?”. jedhi Rabbiin gara haqaatti qajeelcha. Sila Isa gara haqaatti qajeelchutu hordofamuu haqa godhatamoo isa yoo qajeelfame malee, qajeeluu hin dandeenyee dha? Sila isin maaltu isinii jiraaf akkuma feetan murteessitu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 36, 'Irra hedduun isaanii shakkii malee hin hordofan, shakkiin dhugaa irraa homaa hin duroomsu, Rabbiin beekaa waan isaan hojjataniiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 37, 'Qur’aanni kun Rabbii gaditti sobaan kan uumamu hin taane. Garuu dhugoomsaa (kitaabota) isa dura turaniitiifi addeessaa (seeraati) kitaabaati, mamiin isa keessa hin jiru, Gooftaa aalamaarraa irraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 38, 'Moo sila isaan “isatu (Muhammadtu) of irraa isa uume” jedhu? jedhi suuraa tokko kan isa fakkaattu fidaa, Rabbii gaditti nama dandeessan (gargaarsaaf) waamadhaa, Yoo kan dhugaa dubbattan taatan (jedhi).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 39, 'Garuu isaan waan beekumsa isaatiin hin marsiniifi waan hiikkaan isaa amma dura itti hin dhufiniyyi kijibsiisu, Warri isaan duraas akkuma kanatti kijibsiisan, Booddeen miidhaa raawwattootaa akkam akka ta’e ilaali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 40, 'Isaan irraa namoota isatti amanantu jira. Isaan irraas namoota isatti hin amannetu jira. Gooftaan kee badii hojjattoota akkaan beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 41, 'Yoo si kijibsiisan jedhi.“Anaaf dalagaa kiyyatu jira; isiniif dalagaa keessantu jira. Isin waan ani dalagu irraa qulqullaa’oodha; anis waan isin dalagdan irraa qulqulluudha”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 42, 'Isaan irraa namoota gara kee dhageeffatantu jira. Sila ati namoota gurri duude,dhageessiftaa? odoo isaan sammuu hin qabnellee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 43, 'Isaan irraas namoota gara kee ilaalantu jira. Sila ati jaamaa qajeelchitaa? odoo isaan hin argine tahanillee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 44, 'Rabbiin namoota homaa hin miidhu, Garuu namoonni ofiif lubbuulee isaanii miidhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 45, 'Guyyaa (Rabbiin) walitti isaan qabu [yaadadhu]. Haala akka waan sa''aa takka guyyarraa taate malee hin turin itti fakkaatuun, gidduu isaaniitti wal beekan. Dhugumatti, warri qunnamtii Rabbii sobsiisan hoonga’aniiru; qajeeloo hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 46, 'Garii waan waadaa isaaniif gallee yoo sitti argisiifne (toleera); yookiin yoo si ajjeefnes deebiin isaanii garuma keenya ta’a. Ergasii Rabbiin waan isaan dalagan irratti ragaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 47, 'Ummata hundaaf ergamaan (ergamee) jira. Yeroo ergamaan isaanii dhufe jidduu isaaniitti haqaan murteeffama isaan hin miidhaman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 48, 'Nijedhan “waadaan kun yoomi Yoo kan dhugaa dubbattan taataniif ?”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 49, 'Jedhi “ ani lubbuu kiyyaaf miidhaas ta’ee bu’aas fiduu hin danda’u Waan Rabbiin fedhe malee, Ummata hundaaf beellamatu jira. Yeroo beellamni isaanii dhufe, sa’aatii tokkos booda hin aanan; duras hin dabran.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 50, 'Jedhi “Mee naaf himaa! yoo adabbiin Isaa halkan yookiin guyyaa isinitti dhufe, badii raawwattoonni isa irraa maal jarjarfatu?”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 51, '“Sila ogga inni argamee booda isatti amantuu? Sila odoo duraan jarjarfataa turtanii amma amantuu?” (jedhamaan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 52, 'Ergasii isaan miidhaa hojjataniin ni jedhama: “Azaaba turaa dhandhamaa! Sila waan hojjataa turtaniin malee ni mindeeffamtuu?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 53, '“Sila inni (Guyyaan Qiyaamaa) dhugaa dhaa?” (jechuun) si odeeffatu. “Eeyyeen! Gooftaa kiyyatti kakadhee! Inni dhugaadha, Isin (Rabbiin) dadhabsiisoo hintaane” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 54, 'Odoo lubbuu miidhaa raawwatte hundaaf wanti dachii keessa jiru (hundi) ta’eefii isaan of furti, Yeroo azaabicha argan sheenaa ni dhooyfatu, Gidduu isaaniitti haqaan murteeffama isaan hinmiidhaman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 55, 'Dhagayaa! Dhugumatti, wanti samiileefi dachii keessa jiru kan Rabbiiti. Dhagayaa! Dhugumatti, waadaan Rabbii dhugaadha. Garuu irra baay’een isaanii hin beekan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 56, 'Inni ni jiraachisa; ni ajjeesas; gara Isaatitti deebifamtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 57, 'Yaa namootaa! Dhugumatti, gorsi Gooftaa keessan irraa taate isinitti dhufte, qorichi waan qomoowwan keessaas, qajeelfamaafi rahmanni mu’uminootaas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 58, 'Jedhi “Tola Rabbiitiifi rahmata Isaatiin (dhufte), isa sanitti haa gammadanu, Waan isaan walitti qaban irra isatu caalaa”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 59, 'Mee naaf himaa jedhi “ waan Rabbiin isiniif buuse,Soorata irraa isin ergasii isa irraa dhorgamaafi hayyamamaa taasiftan san“, Sila Rabbitu isiniif hayyamemoo, Rabbi irratti kijiba uumtanii odeessitu?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 60, 'Sila isaan Rabbi irratti kijiba odeessan Guyyaa Qiyaamaa maal yaadu? Dhugumatti, Rabbiin namoota irratti abbaa tola (guddaa)ti. Garuu irra hedduun isaanii hin galateeffatanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 61, '(Yaa Muhammad!) Hojii kamillee keessatti hin taatu, Qur’aana irraas isa hin dubbiftu, dalagaa irraa waan tokkos hin hojjattan, yeroo isin isatti seentan Nuti isin irratti ragaalee taanu malee hin hafu. Wanti hanga atomii dachii keessattis ta’ee, samii keessattis Rabbii kee irraa hin fagaatu. Wanti san irra xiqqaas ta’ee guuddaan kitaaba addeessaa ta’e keessatti jiraatu malee hin hafu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 62, 'Dhagayaa! Dhugumatti, jaalalleewwan Rabbii sodaan isaan irra hin jiraatu; isaan hin gaddanis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 63, 'Isaan warra amananii, (Rabbiin) sodaachaa turaniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 64, 'Isaaniif jireenya addunyaa keessatti ta’ee kan Aakhiraa keessatti gammachuutu jira. Jechoota Rabbii jijjiiraan hin jiru. Sun isumatu milkii guddaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 65, 'Jechi isaanii si hin gaddisiisin. Dhugumatti, jabeenyi hunduu kan Rabbiiti. Inni dhaga’aa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 66, 'Dhagayaa! Dhugumatti, wanti samii keessa jiruufi wanti dachii keessa jiru kan Rabbiiti. Isaan Rabbiin ala wantoota biraa gabbaran, dhugaatti qindiifamoota hin hordofanu. hinhordofan mamii malee. isaan kijiba qofa uumanii odeessoo malee hintaane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 67, 'Inni (Rabbiin) Isa halkan akka isa keessa boqattan, isiniif taasiseedha, guyyaas immoo kan ibsu. Dhugumatti, kana keessa namoota dhagayaniif mallattooleetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 68, '“Rabbiin ilma godhate” jedhu. Inni (kana) irraa qulqullaa’ee jira. Inni durreessa, Wanti samiilee keessa jiruufi wanti dachii keessa jiru kan Isaati, Kanatti ragaa homaatuu hin qabdan. Sila waan hin beekne Rabbi irratti jettuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 69, '“Dhugumatti, isaan Rabbi irratti kijiba uumanu hin milkaa’anu” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 70, '(Kun) qananii addunyaa keessatti taateedha. Ergasii deebiin isaanii gara keenyatti qofa ta’a, Ergasii waan isaan kafaraa turaniif adabbii cimaa isaan dhandhamsiifna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 71, 'Oduu Nuuh isaan irratti dubbisi, Yeroo inni ummata isaatiin jedhe “yaa ummata kiyya! Yoo (isin waliin) turuun kiyyaafi keeyyattoota Rabbiitiin (isin) yaadachiisuun kiyya isinitti guddate, ani Rabbi irratti hirkadhee, tooftaalee keessaniifi qindeeffamoota keessan walitti qabadhaa; ergasii dharti keessan isin irraa dhokataa hin ta’in; ergasii narratti raawwadhaa yeroo naaf hin kenninaatii ”(jedhe).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 72, '“Yoo gara galtan, mindaa homaatuu isin hin gaafadhu. Mindaan kiyya Rabbi irratti malee hin taane. Ani Muslimtoota irraa ta’uuttiin ajajame.”(jedhi).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 73, 'Isaan isa kijibsiisani, ergasii Nuti isaafi namoota isaa waliin jiranis doonii keessatti nagaya baafne. Bakka bu’oo isaan gooneeti warra keeyyattoota keenya sobsiisan bishaaniin dhidhimsiifne. Booddeen dinniinamtootaa akkam akka ta’e ilaali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 74, 'Ergasii isa booda ergamtoota gara ummata isaanii ni erginee, mallattoowwan ifa ta’aniin isaanitti dhufan. Isaan waan san dura kijibsiisan sanatti kan amanan hin taane. Akka kanatti onnee daangaa dabritootaa irratti cufna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 75, 'Ergasii isaan booda Muusaafi Haaruuniin gara Fir’awnaafi qondaalota isaa aayatoota keenyaan erginee jirra. Isaan boonaniiti, badii raawwattoota irraa ta’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 76, 'Yeroo dhugaan Nu biraa isaanitti dhufu “dhugumatti, kun falfala ifa ba’aadha” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 77, 'Muusaan ni jedhe “sila dhugaan isinitti dhufnaan (kana) jettuu? Sila inni kun falfalaa? Falfaltoonni hin milkaa’an.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 78, 'Isaan ni jedhan: “Sila ati waan abbootii keenya isa irratti argine irraa nu garagalchitee ol aantummaanis dachii keessatti akka isin lamaaniif taatuuf nutti dhuftee? Nuti isin lamaaniif hin amannu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 79, 'Fir’awna ni jedhe: “Cufa falfalaa beekaatiin natti koottaa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 80, 'Yeroo falfaltoonni dhufan, Muusaan isaaniin ni jedhe: “isin Waan darbitan darbaa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 81, 'Yeroo isaan darban Muusaan ni jedhe: “Wanti isin isaan dhuftan falfalaa, dhugumatti, Rabbiin isa balleessuuf jira. Dhugumatti, Rabbiin dalagaa badii hojjattootaa hin tolchu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 82, 'Odoo badii raawwattoonni jibbanillee, Rabbiin dhugaa jechoota Isaatiin mirkaneessa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 83, 'Muusaaf hin amanne, Dhaloota ummata isaa irraa ta’e malee, Fir’awnaafi qondaaltonni isaa isaan jallisuu sodaachuun wajji, Dhugumatti, Fir’awn dachii keessatti of tuulaadha. Ammas inni daanga dabritoota irraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 84, 'Muusaanis ni jedhe: “Yaa ummata kiyya! Yoo kan Rabbitti amantan taatan, Isuma irratti hirkadhaa; yoo Muslimoota taatan.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 85, 'Isaanis ni jedhan: “Nuti Rabbi irratti hirkannee jirra. Yaa Gooftaa keenya! Ummata miidhaa raawwattootaaf sababaa jallinnaa nu hin taasisin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 86, 'Namoota kaafirootaa jalaas Rahmata keetiin nagaa nu baasi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 87, 'Muusaafi obboleessa isaatti wahyii goone: “Isin lachanuu ummata keessaniif Misratti manneen qopheessaa; manneen keessan iddoo ibaadaa taasisaa; salaata dhaabaa; mu’uminoota gammachiisi” jechuun .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 88, 'Muusaanis ni jedhe: “Gooftaa keenya! Ati dhugumatti Fir’awniifi qondaalota isaatiif jireenya addunyaa keessatti miidhaginaafi qabeenya kennitee jirta, (yaa) Gooftaa keenya! Karaa kee irraa akka (namoota) jallisaniif jecha. Gooftaa keenya! Qabeenya isaanii mancaasi; onneewwan isaanii irratti jabeesi. Isaan hanga adabbii laalessaa arganitti hin amanan.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 89, '(Rabbiin) ni jedhe: “Dhugumatti, kadhaan keessan lamaanii qeebalamtee jirti, Karaa qajeelaa irratti gadi dhaabbadhaa; karaa warra hin beeknee hin hordofinaa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 90, 'Ilmaan Israa’iil galaana ceesifneeti, Fir’awniifi waraanni isaas jibbaafi diinummaaf isaan hordofan; yeroo bishaaniin nyaatamuun isa dhaqqabu “dhugumatti, Isa Ilmaan Israa’iil itti amanan malee haqaan gabbaramaan biraa hin jiruu amaneera. Ani Muslimtoota irraayi” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 91, 'Sila odoo duraan dilooytee, balleessitoota irraa taatee jirtuu amma (amantaa)!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 92, 'Har’a qaama keetiin (reeffa kee) akka ati namoota si boodaatiif mallattoo taatuuf si baafna. Dhugumatti, hedduun namoota irraa ta’an mallattoolee keenya irraa dagatoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 93, 'Nuti dhugumatti, Ilmaan Israa’iil iddoo kabajamaa (Shaamiifi Misraan keessa) isaan qubachiifnee jirra. Wantoota gaggaarii irraas soorata isaanif kenninee jirra. Hanga beekumsi isaanitti dhufutti wal hin dhabne. Dhugumatti, Gooftaan kee guyyaa Qiyaamaa gidduu isaaniitti ni murteessa, waan isaan keessatti wal dhabaa turan keessatti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 94, 'Yoo waan Nuti gara keetti buufne irraa shakkii keessa jiraatte, isaan si dura kitaaba dubbisaa turan gaafadhu. Dhugumatti, haqni Gooftaa kee irraa sitti dhufee jiraa, shakkitoota irraa hin ta’in.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 95, 'Isaan keeyyattoota Rabbii kijibsiisan irraas hin ta’in; hoongoftoota irraa taataa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 96, 'Dhugumatti, warri jechi Gooftaa keetii isaan irratti mirkanoofte hin amanan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 97, 'Odoo mallattoon hundi isaanitti dhufanillee hanga adabbii laalessaa arganitti (hin amanan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 98, 'Sila magaalaan (erga adabbii Rabbii argitee) amantee ergasii iimaanni ishee ishee fayyade ummata Yuunus malee maaliif hin jiraatini? (Hin jiru jechuu dha). Isaan amannaan jireenya addunyaa keessatti adabbii salphisaa ta’e isaan irraa saaqne, hanga yeroo murtaa’eetti isaan qanansiifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 99, 'Gooftaan kee odoo fedhee namni dachii keessa jiru hundi isaanii marti ni amana ture. Sila ati hanga isaan mu’uminoota ta’anitti namoota dirqisiiftaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 100, 'Lubbuu kamiifuu hayyama Rabbiitiin ala amanuun hin taane. Isaan sammuu hin qabne irrattii najisa (adabbii) taasisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 101, '“Mee wantoota samiileefi dachii keessa jiran (hunda) ilaalaa” jedhi. Mallattooleefi akeekkachiiftonni namoota hin amanne irraa homaa hin deebisanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 102, 'Sila ni eeganii fakkaataa guyyoota warra isaan dura dabranii malee? “Egaa, anis isin waliin eegdota irraayi” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 103, 'Ergasii ergamtoota keenyaafi isaan amananis nagaa baafna! Akka kanatti mu’uminoota nagaa baasuun Nu irratti haqa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 104, '“Yaa namootaa! Yoo amantii kiyya irraa shakkii keessa taatan, isaan isin Rabbii gaditti gabbartan san ani hin gabbaru; garuu Rabbii isa isin ajjeesun gabbara. Ani mu’uminoota irraa ta’uuttin ajajame” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 105, '“Fuula kee qajeelaa taasisii guutumatti amantiitti gara galchi; mushrikoota irraa hin ta’in” (naanjedhame).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 106, 'Rabbii gaditti waan si hin fayyadneefi si hin miine hin gabbarin. Yoo (akkas) hojjatte, dhugumatti ati yoos miidhaa hojjattoota irraa taata.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 107, 'Yoo Rabbiin rakkinaan si tuqe, Isa malee kan isa fuudhu hin jiru; yoo toltuun si fedhees, tola Isaa kan deebisu hin jiru. Isaan (tola saniin) gabroota Isaa irraa nama fedhe tuqa. Inni araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 108, '“Yaa namootaa! Dhugumatti, Gooftaa keessan irraa dhugaan isinitti dhufee jira. namni qajeele, kan inni qajeelu lubbuma isaatiifi. Namni jallates, kan inni jallatu ishee irratti. Ani isin irratti ramadamaa miti” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 109, 'Waan gara keetti wahyii godhame hordofi. Hanga Rabbiin murteessutti obsi. Inni irra caalaa murteessitootaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 1, 'Alif Laam Raa (Qur’aanni kun) kitaaba keeyyatoonni isaa sirriitti qindeeffamtee, eegasii addaan baafamtee, (Rabbii) ogeessa, keessa beekaa ta’e biraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 2, '“Rabbiin malee waan biraa hin gabbarinaa” jechuun (addaan baafamte). Ani isiniif Isa irraa akeekkachiisaafi gammachiisaadha', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 3, '“Gooftaa keessan araarama kadhadhaa; ergasii gara Isaatti tawbaa deebi’aa,qananii bareedaa isin qanansiisa, hanga beellama beekamaatti. Abbootii tolaa hundaafis tola (mindaa) isaa ni kenna” jechuun (addaan baafamte). Yoo (irraa) gara galan, ani adabbii guyyaa guddaan isin irratti sodaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 4, 'Deebiin keessan gara Rabbiitti. Inni waan hunda irratti danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 5, 'Dhagayaa! Dhugumatti, isaan Isa jalaa dhokachuuf qoma isaanii maru. Dhagayaa! yeroo isaan uffata isaanii haguuggatan, (Rabbiin) waan isaan dhoksaniifi waan isaan mul''isanis ni beeka. Inni beekaa waan qoma keessa jiruuti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 6, 'Lubbu qabeeyyiin dachii keessatti tokkollee sooranni ishee Rabbi irratti ta’u malee hin taane. Iddoo qubannoota isheetiifi iddoo du’a ishees ni beeka. Hundumtuu kitaaba ifa ta’e keessa jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 7, 'Inni (Rabbiin) Isa samiifi dachii guyyoota jaha keessatti uumeedha. Arshiin Isaas bishaan gubbaa ture. Eenyuu keessantu dalagaan isaa irra gaarii ta’uu isin qormaatuuf (isaan uume). Yoo ati “Dhugumatti isin du’a booda kaafamoodha” jetteen, isaan kafaran nijedhu “kun sihrii ifa ta’e malee waan biraatii miti”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 8, 'Adabicha yoo hanga beellama lakkaawamaa ta’eetti isaan irraa tursiifne, “maaltu isa tursiise?” jedhu. Dhagayaa! guyyaa inni isaanitti dhufu isaan irraa deebifamaa miti. Wanti isaan ittiin qishinaa turan isaanitti bu''a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 9, 'Yoo Nuti rahmata Nu biraa ta’e Nama dhandhamsiifnee ergasii ishee isa irraa mulqine, (abdii muratee itti kafara). Dhugumatti inni akkaan abdii murataa, akkaan kafaraadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 10, 'Yoo Nuti eega rakkoon isa mudatee booda qananiiwwan isa dhandhamsiifne, dhugumatti “hamtuuwwan narraa deeme” jedha. Dhugumatti, inni akkaan gammadaa, akkaan dhaaddataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 11, 'Garuu isaannan obsaniifi toltuuwwan dalagan malee, warri sun araaramaafi mindaa guddaatu isaaniif jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 12, 'Garii waan gara keetti buufamee dhiisuun, isattis onneen kee dhiphachuun, sirratti sodaatama “Maaliif qabeenyi guddaan isa irratti hin buufamne, yookiin maleykaan isa waliin hin dhufne” jechuu isaanii sodaachuuf jecha. Ati akeekkachiisaa qofa. Rabbiin wanta hunda irratti tiksaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 13, '“Inumaayyuu isatu (Qur’aana) of biraa uume” jedhuu? jedhiin "suuraa kudhan kan (isin biraa) uumamtuu taate kan isa fakkaattu fidaa Rabbiin ala waan dandeessan waamadhaatii,“yoo kan dhugaa dubbattan taatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 14, 'Yoo isaan isiniif hin awwaatin, beekaa inni (Qur’aanni kun) kan buufame beekumsa Rabbiitiin akka ta’eefi Isa malees gabbaramaan haqaa akka hin jirre. Sila isin Muslima hin taatanuu? (Muslima ta’aa jedhiin).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 15, 'Namni jireenya Addunyaatiifi miidhagina ishee fedhe, Nuti dalagaalee isaanii ishee keessatti guunnee isaaniif kennina. Isaanis ishee keessatti hin hir’ifamanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 16, 'Isaan sun warra Aakiraatti ibidda malee homtuu isaaniif hin jirreedha. Wanti isaan ishee keessatti dalaganis ni bade. Wanti isaan dalagaa turanis badaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 17, 'Sila namni ragaa mul’ataa Gooftaa isaa biraa ta’e irra jiru, kan ragaan Isa (Allaah) irraa ta’e isa hordofuufi isa duras kitaabni Muusaa kan hogganaafi rahmata ta’ee (ragaa isaaf ba’e) (akka nama jiruu addunyaa fedhuu ni ta’aa)? Warri sun isatti (Qur’aanatti) ni amanu. Ahzaabota irraas warra isatti kafare ibiddi itti gala isaati. Isa irraa shakkii keessatti hin ta’in. Dhugumatti, inni dhugaa Gooftaa kee irraa ta’eedha. Garuu irra hedduun namootaa hin amananu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 18, 'Isa Rabbi irratti kijiba uume irra namni of miidhe eenyu? Warri sun Gooftaa isaanii irra fidamu. Ragoonni nijedhu “isaan kun warra Gooftaa isaanii irratti sobaniidha”. Dhagayaa! Abaarsi Rabbii miidhaa hojjattoota irra haa jiraatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 19, 'Isaan warra karaa Rabbii irraa (namoota) deebisaniifi dabiinsa ishees fedhaniidha. Isaan isaanumatu Aakhiraatti kafaroodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 20, 'Warri sun dachii keessatti (Rabbiin) dadhabsiisoo hin turre. Rabbii alattis gargaaraan tokkolleen isaaniif hin taane. Adabichi dachaa isaaniif godhama. (Haqa) dhagahuu kan danda’an hin turre; kan arganis hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 21, 'Warri sun isaan lubbuulee isaanii hoonga’anii wanti isaan ofirraa (kijibaan) uumanii (gabbaraa) turanis jalaa badeedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 22, 'shakkiin hinjiru isaan Aakiraatti isaanumatu hoonga’oota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 23, 'Isaan amananii gaggaarii hojjatanii, Rabbii isaaniitiif gadi jedhan isaan sun warra jannataati. Isaan ishee keessatti hafoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 24, 'Fakkeenyi gareewwan lamaanii akka jaamaa, duudaafi argaa, dhagayaati. Sila fakkeenyatti isaan lamaan wal qixxaa’uu? Sila isin hin gorfamtanii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 25, 'Dhugumatti, Nuti Nuuhiin gara ummata isaa erginee jirra. (Innis ni jedhe): “Ani isiniif akeekkachiisaa ifa bahaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 26, 'Rabbiin malee (waan biraa) hin gabbarinaa; Ani adabbii guyyaa laalessaan isin irratti sodaadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 27, 'Ummata isaa iraa qondaaltonni isaannan kafaranii nijedhan “nama fakkii keenya taatee malee si hin agarru. Gadi aantota keenya warra yaada gadhee (yartuu) malee kan si hordofes hin agarre. Isiniifis nurratti caalmaya tokkollee hin agarre. Inumaayyuu sobdoota ta’uu keessan shakkina” (jedhan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 28, 'Inni ni jedhe: “Yaa ummata kiyya! Mee naaf himaa; yoo ani ragaa ifa bahaa Gooftaa kiyya irraa ta’e irra jiraadhee, Innis rahmata Isa biraa ta’e (nabiyyummaa) naaf kennee, isin jalaa dhokate, sila nuti odoo isin isheedhaaf jibbitoota taatan dirqamaan isin fudhachiifnaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 29, 'Yaa ummata kiyya! Ani isa (ergaa qaqqabsiisuu) irratti mindaa isin hin gaafadhu. Mindaan kiyya Rabbiin qofa irra jira. Ani ari’aa warra amananiitii miti. Dhugumatti, isaan Gooftaa isaanii qunnamoodha. Garuu ani ummata wallaalaa ta’uun isin arga.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 30, 'Yaa ummata kiyya! (adabbii) Rabbii jalaa eenyu na baraarsa? Yoo ani isaan ari’e. Sila hin gorfamtanuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 31, 'Ani kuusaan qabeenya Rabbii ana bira jira isiniin hin jedhu. Gaybii (wanta fagoo) hin beeku. Ani maleeykaa dhas isiniin hin jedhu. Isaannan ijoonni keessan tuffattu (xinneessituu)nis Rabbiin toltuu isaaniif hin kennu hin jedhu. Rabbiin waan lubbuulee isaanii keessa jiru irra beekaadha. Yoo san, ani dhugumatti warra miidhaa hojjatan irraayyi”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 32, '[Isaan] nijedhan “yaa Nuuh! Ati dhugumatti nu mormitee jirta. Mormiiwwan keenyas baay’essitee jirta. waan nuun sodaachiftu sana nutti fidi, Yoo warra dhugaa dubbatan irraa taate”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 33, 'Nijedhe "Isa kan isinitti fidu Rabbuma qofa Yoo fedhe. (ni ariifachiisa) Isin dadhabsiisoo hin taane”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 34, '“gorsi koo isin hin fayyadu Yoo an isin gorsuu fedhe, yoo Rabbiin isin jallisuu fedha ta’e, Inni Gooftaa keessani, Garuma isaa qofa deebitu”(jedhe).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 35, 'Sila “(Muhammad) isa (Qur’aana) of irraa uume” jedhuu?. jedhi “Yoo ani of irraa isa uume, badiin kiyya anuma irra jira, Ani badii isin hojjattan irraa qulquulluudha”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 36, 'Gara Nuuhitti (akkana jechuun) beeksisa godhame: “Dhugumatti, warra kana dura amanan malee ummata kee irraa kana booda homtuu hin amanu; Kanaaf waan isaan hojjatanitti hin gaddin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 37, 'Doonis laalchota (tika) keenyaafi beeysisa keenyaan hojjadhu. Warra miidhaa dalagan keessatti natti hin dubbatin. isaan bishaanin dhidhimfamoodha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 38, 'Innis (Nuuh) doonii hojjata (ture), Dhawaatuma qondaalonni ummata isaa irraa ta’an isa irra qaxxaamuraniin, isatti qishinu. Innis ni jedhe: “Yoo isin nutti qishnitanis nutis akkuma isin qishnitan isinitti qishinuuf jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 39, 'Beekuuf jirtu Namni adabbiin isa salphisu itti dhufuufi adabbiin itti fufaan isa irra qubatu eenyu akka ta’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 40, 'Yeroma ajajni keenya dhufee, badaa ibiddaa (keessaa bishaan) burqe “Wantoota hunda irraa (saala) lama lama (kormaafi dhalaa), maatii keetis nama jechi (adabaa) isa irratti dabre malee, namoota amananis ishee keessatti fe’i” isaan jenne, Isa waliin namoota muraasa malee (baay’een) hin amanne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 41, 'Nijedhe ishee yaabbadhaa “Haala deemsi isheetiifi dhaabbatiinsi ishees maqaa Rabbiitiin taa’een. Rabbiin kiyya araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 42, 'Isheen danbalii akka gaarotaa keessa isaanin adeemti. Nuuh ilma isaa (doonittii irraa) fagoo ture niyaame “Yaa ilma kiyya! Nu waliin yaabbadhu, Warra kafaran wajjinis hin ta’in” jedheen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 43, '(Ilmi isaa) ni jedhe: “Ani gara gaara bishaan jalaa na baraarsuun qubadha.” (Nuuh) ni jedhe: “Har’a wanti ajaja Rabbii jalaa nama baraarsu hin jiru; nama Rabbiin rahmata isaaf godhe malee” . Danbaliin gidduu isaanii haguuge. Inni warra bishaaniin nyaataman irraa ta’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 44, 'Ni jedhame: “Yaa dachii! Bishaan kee liqimsi, Yaa samii! (Bokkaa kee) qabadhu.” Bishaan xuuxamee hir’ate. Murtiin Rabbiis (adabichis) ni raawwatame. Isheen tabba juudiyyi jedhamu irra dhaabbatte. Ni jedhame: “(rahmata Rabbii irraa) Fageenyi ummata miidhaa hojjattoota irra haa jiraatu!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 45, 'Nuuh Gooftaa isaatti lallabee, nijedhe “Gooftaa kiyya! dhugumatti, ilmi kiyya maatii kiyya irraayi. Waadaan kee dhugaadha. Ati irra haqa murteessaa abbootii murtiiti”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 46, '(Rabbiin) nijedhe “Yaa Nuuh! dhugumatti, inni maatii kee irraa miti. Inni hojii gaarii hin ta’iniidha. waan beekumsa itti hin qabne na hin gaafatin. Ani akka ati wallaaltota irraa hin taanen si gorsa”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 47, '(Nuuh) nijedhe “Gooftaa kiyya! Ani waan beekumsa itti hin qabne si gaafachuu irraa sittin maganfadha. Yoo Ati naaf araaramtee, rahmatas naaf hin godhin, warra hoonga’an irraan ta’a”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 48, 'Nijedhame “Yaa Nuuh nageenyaa Nurraa ta’eefi barakaa siifi garii ummata si wajjin jiran irratti ta’een, (doonittii irraa) gadi bu’i. (Sanyii isaanii irraas) ummata yeroof isaan qanansiifnee san booda Nu biraa adabbiin laalesaan isaan tuqutu jira”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 49, 'Isheen tun oduu fagoo kan gara keetti beeksisa goonu irraayi. Sis ta’ee ummanni keetis kana dura kan ishee beektan hin turre. Obsi Dhugumatti, booddeen (gaariin) kan warra (Rabbiin) sodataniiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 50, 'Gara Aadittis obboleessa isaanii Huudiin (erginee jirra). Innis ni jedhe: “Yaa ummata kiyya! Rabbiin gabbaraa. Gabbaramaan (haqaa) Isa malee isiniif hin jiru. Isin kijiba uumoo malee waa biraa hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 51, 'Yaa ummata kiyya! Ani isa (ergaa qaqqabsiisuu) irratti mindaa isin hin gaafadhu. Mindaan kiyyas Isa na uume irratti malee hin taane. Sila isin hin xiinxaltanii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 52, 'Yaa ummata kiyya! Gooftaa keessan araarama kadhaa, ergasii gara Isaatti tawbaa deebi’aa. Bokkaa walitti dhaabbataa godhee isinirratti ergaa. Humna keessan irratti humna isiniif dabalaa. Yakkamtoota taatanii irraa gara hin galinaa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 53, 'Nijedhan “Yaa Huud! Ati ragaan nutti hin dhufne. Nuti jecha keetiif jennee gabbaramtoota keenya kan dhiifnu hin taane. Nuti siif amanoo miti”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 54, 'Garii gabbaramtoota keenyaatu hamtuun si tuqee malee homaa hin jennu. (Huudis) ni jedhe: “Ani Rabbiinin ragaa godha; isinis ‘ani waan isin qindeessitan irraa qulqulluu ta’uu’ ragaa ba’aa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 55, 'Isaa gaditti (waan gabbartan irraa ani qulqulluudha, Yoo dandeessan) shira natti baasaa haala huda taataniin; eegasii yeroo naaf hin kenninaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 56, 'Ani Rabbii Gooftaa kiyyaafi Gooftaa keessan ta’e irratti irkadheera. lubbu qabaan tokkos Inni sammuu isaa qabu malee hintaane. Gooftaan kiyya karaa qajeelaa irra jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 57, 'Yoo gara galtan, dhugumatti ani waanin ittiin gara keessanitti ergame isintti dhaqqabsiiseera, Gooftaan kiyyas ummata isin hin ta’in bakka buusa. Homaa Isa hin miitan. Gooftaan kiyya waan hunda irratti eegaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 58, 'Yeroo ajajni keenya dhufe, Huudiifi warra isa waliin amanan rahmata Nurraa ta’een nagaa baafne, adabbii cimaa ta’e irraa nagaa isaan baafne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 59, 'Isheen sun (ummata) Aadi Mallattoowwan Gooftaa isaanii mormanii, ergamtoota Isaas didan; ajaja of tuulaa, haqa mormaa ta’e hundaa hordofan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 60, 'Addunyaa kana keessatti abaarsaan hordofsiifaman; Guyyaa Qiyaamaas (akkasuma). Dhagayaa! Dhugumatti, Aad Gooftaa isaaniitti kafaraniiru. Dhagayaa! Ummata Huud kan ta’an Aadiif (rahmata irraa) fageenyi haa ta’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 61, 'Gara Samuudis obboleessa isaanii Saalihiin (erginee jirra). Ni jedhe: “Yaa ummata kiyya! Rabbiin gabbaraa, Isa malee dhugaan gabbaramaan biraa isiniif hin jiru, Inni dachii irraa isin uumeeti, ishee keessa isin jiraachise. araarama Isa (qofa) kadhaa; ergasii gara Isaatti tawbaa deebi’aa. Dhugumatti, Gooftaan kiyya (beekumsa Isaatiin) dhihaataa, awwaataa dha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 62, 'Ni jedhan: Yaa Saalih! Ati kana dura nu keessatti nama kajeelamaa turte. Sila ati waan abbootiin keenya gabbaraa turan gabbaruu irraa nu dhorgitaa? Nuti waan ati itti nu waamtu irraa shakkii keessatti jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 63, '(Saalih) ni jedhe: “Yaa ummata kiyya mee naaf himaa! Yoo ani ragaa ifa ba’aa Gooftaa kiyya irraa ta’e irra jiraadhee, Innis rahmata Isa biraa ta’e (nabiyyummaa) naaf kenne, yoo ani Isatti dilaaye Rabbiin jalaa eenyutu na tumsa? Isin hoongeessuu malee homaa naaf hin dabaltanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 64, 'Yaa ummata kiyya! Isheen tun gaala Rabbiiti, isiniif mallattoodha. Dachii Rabbii keessa haa nyaattuu ishee dhiisaa, Hamtuudhaan ishee hin tuqinaa. (Yoo akkas gootan) adabbiin dhihoo ta’e isin tuqa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 65, 'Ishee ni waraanan, Inni nijedhe “Manneen keessan keessa guyyoota sadihiif qanani’aa. Kun waadaa (adabbii) hin kijibsiifamneedha”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 66, 'Yeroma ajajni keenya dhufe, Saalihiifi warra isa wajjiin amanan rahmata Nurraa ta’een nagaa (isaan) baafne; xiqqeenya guyyaa sanii irraas (isaan baraarsine). Dhugumatti, Gooftaan kee isatu jabaa, injifataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 67, 'Iyyansi hamaan miidhaa hojjattoota qabatee, manneen isaanii keessatti kan jilbeenfatan ta’anii (du’anii) tahanii bariisifatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 68, 'Akka waan ishee keessa hin jiraatinii ta’an. Dhagayaa! Samuud Gooftaa isaaniitti kafaranii jiru. Dhagayaa! fageenyi Samuudiif haa ta’u!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 69, 'Dhugumatti, ergamtoonni keenya Ibraahiimitti oduu gammachiisaan dhufan, nijedhan “nagaa (sirratti buufna)” Innis nijedhe “nagaan (isin irra haa jiraatu)”. Odoo hin turre jibicha waadamaan dhufe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 70, 'Yeroma harkoowwan isaanii gara isaa (nyaatichaa) kan hin geenye ta’uu argu, isaan morme; isaan irraas sodaa dhokfate, nijedhaniin “Hin sodaatin; nuti gara ummata Luux ergamnee”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 71, 'Niitiin isaa dhaabattuu taatee nikolfite, Nuti Isihaaqiin ishee gammachiifne, Isihaaq boodas Ya’aquubiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 72, 'Ni jette: “Yaa badii kiyya! Sila odoo ani dullattii, ta''e jiruu da''aa? dhirsi kiyya kunis dullachaa. Dhugumatti, kun waan dinqisiisaa dha!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 73, 'Ni jedhan: “Sila murtii Rabbii irraa dinqisiifattaa? Rahmanni Rabbiitiifi barakaan Isaa isin irra haa jiraatu;Yaa warra manichaa! Inni faarfamaa, guddaadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 74, 'Yeroma Ibraahiim irraa sodaan deemee gammachuun isatti dhuftu, inni ummata Luux keessatti Nuun falmuu eegale.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 75, 'Dhugumatti, Ibraahiim obsaa, Rabbitti booyaa, deebi’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 76, 'Yaa Ibraahiim! (Falmii) kana irraa gara gali. Dhugumatti, ajajni Gooftaa keetii dhufee jira. Isaan adabbiin hin deebifamne isaanitti dhufa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 77, 'Yeroma ergamtoonni keenya Luuxitti dhufan, inni isaanitti gadde; qomti isaas isaaniif dhiphate “Kun guyyaa hamaadha” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 78, 'Ummanni isaas gara isaatti kan ariifatan ta’aa isatti dhufan, Sana duras gocha fokkataa kan hojjatanu turan, (Luux) ni jedhe: “Yaa ummata kiyya! Isaan kun shamarran kiyyaIsaan (yoo seeraan fuutan)isaantu isiniif qulqulluudha. Rabbiin sodaadhaa; keessummaa kiyya keessatti na hin xiqqeessinaa. Sila isin irraa namni qajeelaan tokkolleen hin jiruu?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 79, 'Isaan ni jedhan: “Dhugumatti, ati akka nuti ijoollee dubaraa kee irraa dhimma hin qabne beektee jirta, dhugumatti ati waan nuti barbaannu nibeekta.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 80, 'Ni jedhe: “Ani odoon humna isin irratti qabaadhee yookiin gara lammii jabduu hirkadhee (isinin adaba ture).”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 81, '(Isaan) ni jedhan: “Yaa Luux! Dhugumatti, nuti ergamtoota Gooftaa keetiiti; Isaan gara keetti hin ga’anu. Maatii kee qabadhuu kutaa halkan irraa taate keessa deemi, Isin irraa eenyullee of duuba akka hin mil’anne, Niitii tee malee. Dhugumatti, wanti isaan tuqu ishee tuqaadha. Beellamni isaaniis bariidha. Sila bariin dhihoo mitii?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 82, 'Yeroo ajajni keenya dhufu, gubbaa ishee (magaalattii) jala ishee taasifnee, Ishee irratti dhagaa dhoqqee gubamaa irraa tahe wal hordofaa roobsifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 83, '(Dhagattiin) Gooftaa kee biratti kan mallatteeffamte taatee (ishee roobsine), Isheen miidhaa hojjattoota irraa fagoo miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 84, 'Gara Madyanis obboleessa isaanii Shu’aybiin (erginee jirra) nijedhe “Yaa ummata kiyya! Rabbiin gabbaraa, Isa malee dhugaan gabbaramaan biraa isiniif hin jiru, Safaraafi madaala hin hir’isinaa, Ani qabeenya keessattin isin argaara, Dhugumatti ani adabbii guyyaa marsaa ta’een isin irratti sodaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 85, 'Yaa ummata kiyya! Safaraafi madaalas haqaan guutaa, Namoota jalaa wantoota isaanii hin hirdhisinaa; dachii keessattis balleessitoota taatanii badii hin facaasinaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 86, 'waan Rabbi isiniif hambisetu isiniif caala;Yoo mu’uminoota taataniif, Ani isin irratti eegaa miti.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 87, 'Ni jedhan: “Yaa Shu’ayb! Sila salaata keetu waan abbootiin keenya gabbaraa turan akka dhiifnu yookiin akka nuti qabeenya keenya irratti akka feene hin dalagne si ajajjii? Dhugumatti, ati simatu obsaa, qajeelaa dha!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 88, 'Ni jedhe: “Yaa ummata kiyya! Mee naaf himaa; yoon ragaa ifa ba’aa Gooftaa kiyya irraa ta’e irra jiraadhee, innis kennaa gaarii Isa biraa ta’e naaf kenne, (sila qabeenya karaan alaatiin walitti makuun qabaa), Ani waanin irraa isin dhorge (hojjachuun) isin faallessuu hin fedhu, Ani hangan danda’een (isin) tolchuu malee hin fedhu, Haqa qunnamuun kiyyas Rabbi irraa malee hin taane, Isa irratti hirkadhe; garuma isaan deebi’a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 89, 'Yaa ummata kiyya! ana faallessuun akka fakkaataa waan ummata Nuuh yookiin ummata Huud yookiin ummata Saalih tuqee isin tuquu irratti isin hin kaasne, Ummanni Luux isin irraa fagoo miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 90, 'Gooftaa keessan araarama kadhaa, Ergasii gara Isaa deebi’aa, Dhugumatti, Gooftaan kiyya rahmata godhaa, jaallataadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 91, 'nijedhan “Yaa Shu’ayb! Irra hedduu waan ati jettuu nuti hin hubannu, Nu keessatti dadhabaa taateetiin si argina, Odoo gosti kee jiraachuu baatee, silaa dhagaan tumnee si ajjeefna turre, Ati nurratti jabaa miti”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 92, 'Ni jedhe: “Yaa ummata kiyya! Sila gosa kiyyatu Rabbi irra isinitti jabaataa? Duuba keessan irraan gara dugdaa Isa gootan, Dhugumatti, Gooftaan kiyya waan isin dalagdanutti marsaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 93, 'Yaa ummata kiyya! Isin sadarkaa keessaniin hojjadhaa; Ani hojjataadha, Nama adabbiin isa xiqqeessu isatti dhufuufi nama isa kijibaa ta’e fuula dura beektu, Isin eegaa! Anis isin waliin eegaadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 94, 'Yeroma ajajni keenya dhufu, Shu’aybiifi warra isa waliin amanan rahmata Nu biraa ta’een nagaa baafnee, warra miidhaa hojjatan iyyansi cimaan ni qabde, Manneen isaanii keessatti jilbeenfatoo ta’anii (du’anii) bariisifatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 95, 'Akka waan ishee keessa hin jiraatinii ta’an. Dhagayaa! akkuma Samuud fagaatte! Madyaniif fageenyi haa ta’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 96, 'Dhugumatti, Muusaa mallattoota keenyaafi ragaa ifa ta’een erginee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 97, 'Gara Fir’awniifi qondaalota isaa (ergine), Ajaja Fir’awni hordofan, Ajajni Fir’awni sirrii miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 98, 'Guyyaa Qiyaamaa ummata isaa dursee, ibidda isaan seensisa, (Inni) seensa seenamaa (ta’uun isaa) waa fokkate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 99, 'Addunyaa kana keessatti abaarsaan hordofsiifaman, Guyyaa Qiyaamaas (akkasuma), Badhaasni badhaafaman waa fokkate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 100, 'Kun oduu magaalotaa irraayi; isa sirratti odeessina, Ishee irraa dhaabbataafi haamamaatu jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 101, 'Nuti isaan hin mine; Garuu isaan lubbuulee isaanii miidhan. gabbaramtoonni isaanii kan isaan Rabbii gaditti gabbaraa turan homaa isaan hin fayyadne Yeroo ajajni Gooftaa keetii dhufu. Hoongessuu malees homaa isaaniif hin daballe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 102, 'akkuma kana Qabaan Gooftaa keetii yeroo magaalota miidhaa hojjattuu taate qabe, Dhugumatti, qabaan Isaa laalessaa, jabaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 103, 'Dhugumatti, kana keessa namoota adabbii Aakiraa sodaataniif mallattootu jira. Sun guyyaa namoonni isaaf walitti qabamaniidha; sun guyyaa dhufamaadhas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 104, 'Beellama lakkaa’amaaf malee isa hin tursiifnu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 105, 'Guyyaa inni dhufu lubbuun kamillee hayyama Isaatiin malee hin dubbattu. Isaan irraas warra hoonga’aafi milkaa’aatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 106, 'Isaan hoonga’an ibidda keessa ta’u, Ishee keessatti iyyansaafi himimsaatu isaaniif jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 107, 'Hanga samiifi dachiin turan ishee keessa kan turan ta’anii (ibidda keessa jiraatu) Waan Gooftaan kee fedhe malee, Gooftaan kee waan fedhe hojjataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 108, 'Isaan milkeeffaman immoo Jannata keessa jiraatu Waan hanga samiifi dachiin turtu ishee keessatti kan hafan ta’anii (jannata keessa jiraatu) waan Gooftaan kee fedhe malee. Kennaa addaan hin cinne (kennaman).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 109, '(Yaa Muhammad!) waan warri sun gabbaran irraa shakkii keessatti hin tahin, (Isaan) akkuma abbootiin isaanii duraan gabbaran malee hin gabbaranu, Nuti qooda isaanii odoo hin hir''ifamne guunnee isaaniif kennina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 110, 'Dhugumatti, Muusaaf kitaaba kennineerra; isa keessattis wal dhabame, Odoo jechi Gooftaa kee biraa dabruu baatee silaa gidduu isaaniitti murteeffama ture, Dhugumatti, isaan isa irraa shakkii cimaa keessa jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 111, 'Dhugumatti hunda isaaniitiif Gooftaan kee dalagaa isaanii isaaniif guuta, Dhugumatti, Inni waan isaan dalagan beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 112, 'Akka ajajamtetti gadi dhaabbadhu. Isaan tawbatanis si waliin (gadi haa dhaabbatanii), Daangaas hin dabrinaa, Dhugumatti, Inni waan isin dalagdan argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 113, 'Gara warra miidhaa hojjatanii hin dabinaa (Yoo akkas gootan) ibiddi isin tuqa፣ Rabbiin malees jaalallee biraa hin qabdan, Ergasii hin tumsamtanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 114, 'Qaccee lamaan guyyaatiifi yeroo halkan irraa ta’e salaata dhaabi, Toltuuwwan hamtuuwwan ni deemsisu, Kun warra gorfamaniif gorsa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 115, 'Obsi! Dhugumatti, Rabbiin mindaa toltuu hojjattootaa hin balleessu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 116, 'Maaliif jaarraawwan isiniin duraa irraa warri hanbaa gaariin kan dachii keessatti badii irraa dhorgan hin jiraatin? xiqqoo warra nuti nagaya baafnee malee. Isaan miidhaa hojjatan immoo waan isa keessatti qanansiifaman hordofee yakkamtoota irraa ta’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 117, 'Gooftaan kee magaalaa kamillee,miidhaan kaballeessu hintaane odoo jiraattonni ishee warra toltuu hojjatu ta’anii jiranuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 118, 'Gooftaan kee odoo fedhee, silaa nama hunda ummata tokko taasisa ture. Wal dhaboo ta’uu irraa hin deemanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 119, 'Nama Gooftaan kee rahmata godheef malee (waldhabuu irraa hin deman), Kanumaaf isaan uume. Jechi Gooftaa keetii guutamteetti “dhugumatti jahannamiin walii gala jinnootaafi namootaa irraa ta’aniin nan guuta”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 120, 'Oduulee ergamtootaa irraa waan ittiin onnee kee raggaasifnu hunda sirratti odeessina. Ishee kana keessatti dhugaa sitti dhufe, gorsaafi yaadachiifni mu’uminootaaf ta’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 121, 'Isaan hin amanneeni jedhi: “sadarkaa keessaniin dalagaa, Nuti dalagoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 122, 'Isinis eegaa! Nutis eegoodha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 123, 'Iccitiin samiifi dachii keessaa kanuma Rabbiiti, Dhimmi hundi gara Isaatti deebifama, Isa gabbari, Isa irratti hirkadhu, Gooftaan kee waan isin hojjattan irraa dagataa miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 1, 'Alif Laam Raa Kun keeyyattoota kitaaba ibsaa ta’eeti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 2, 'Nuti isa buufne Qur’aana Arabiffaa ta’e, akka isin xiinxaltaniif jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 3, 'Nuti seenaa gaggaarii sirratti odeessina Qur’aana kana gara keetti beeksisuudhaan, Ati isa dura dagattoota irraa taate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 4, 'Yeroo Yuusuf abbaa isaatin jedhe “Yaa abbaa kiyya! Ani (abjuudhaan) urjiiwwan kudha tokko, aduufi ji’a argeera; kan anaaf sujuuda godhan ta’anii isaan argeen jira” [yaadadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 5, '(Abbaan isaas) ni jedhe: “Yaa ilma kiyya! abjuu kee obboleeyyan keetti hin himin shira sirratti shiruu, Dhugumatti, sheyxaanni namaaf diina ifa bahaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 6, 'Akka kanatti Gooftaan kee si filata; hiikkaa manaamaas si barsiisa; ni’imaa Isaas sirrattiifi maatii Ya’aquub irrattis ni guuta, akkuma kana dura abbootii kee Ibraahiimiifi Isihaaq irratti guute. Dhugumatti, Gooftaan kee beekaa, ogeessa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 7, 'Dhugumatti, (seenaa) Yuusufiifi obboleeyyan isaa keessa warreen gaafataniif mallattooleetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 8, 'Yeroo (obboleeyyan Yuusuf) jedhan: “Dhugumatti, Yuusufiifi obboleessi isaa nurra gara abbaa keenyaatti jaalatamoodha,odoo nuti garee taanee jirru, Dhugumatti, abbaan keenya dogoggora ifa bahaa keessa jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 9, 'Yuusufiin ajjeesaa; yookiin dachii (fagootti) isa gataa; fuulli abbaa keessanii isiniif dhuunfaa ta’a, Sana booda ummata gaggaarii taatu” (waliin jedhan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 10, 'Isaan irraa jedhaan tokko ni jedhe: “Yuusufiin hin ajjeesinaa, hundee boollaa (eela) keessatti isa darbaa. akka gariin daldaltoota karaa deemu isa fudhatu, yoo kan dalagdan taataniif”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 11, 'Ni jedhan: “Yaa abbaa keenya! Sila ati maaliif Yuusuf irratti nu hin amanne? Nuti isaaf tola yaadoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 12, 'Boru nu waliin isa ergi, Haa bashannanuu, haa taphatuu; dhugumatti, nuti isaaf tiksitoota.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 13, '(Ya’aquub) ni jedhe: “Isa fuutanii deemuun keessan na gaddisiisa, yeyyiin isa nyaachuun sodaadha, Isin isa irraa dagatoo taatanii .”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 14, '[Isaan] ni jedhan: “yoo yeyyiin isa nyaatte Odoo nuti garee taanee jirruu , dhugumatti nuti yeroo san hoongoftoota.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 15, 'Yeroma isaan deemanii boolla gadi fagoo keessatti isa gatuutti walii galan (isa darban). Nuti gara isaatti beeksifne “dhugumatti, ati dhimma isaanii kana isaanitti himta odoo isaan (si) hin beekin ” jechuun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 16, '(Isaanis) abbaa isaanii bira dhufan galgala booyaatiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 17, 'Nijedhan “Yaa abbaa keenya! Nuti wal dorgomuuf deemne, Yuusufiin meeshaa keenya biratti dhiifnee, yeyyiin isa nyaate, ati nuuf kan amantuu miti Odoma nuti warra dhugaa dubbatan taaneeyyuu”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 18, 'Qamisa isaa irratti dhiiga sobaatiin dhufan, (Yaaquub) ni jedhe: “Lakkisaa; Lubbuulee keessantu dubbii (sobaa) isiniif miidhagsite, (Obsi kiyya) obsa gaariidha, Waan isin jettan kana irratti gargaarsifatamaan Rabbi qofa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 19, 'Kara deemtonni (daldaaltoonni) dhuftee, bishaan waraabuduu isaanii erganii baaldii isaa (eela keessa) gadi buuse, “Yaa gammachuu! Kuni mucaa (bareedaadha)” jedhe, Meeshaa godhanii isa dhoksan, Rabbiin waan isaan hojjatan beekaadha. [1]', '[1] yuusuf obboleeyyan isaa eelatti darban, isumaa achi keessa jiru, daldaltoonni bishaan waraabbatuuf baaldii haadaan harkifamu eelatti gadi darban, yuusuf baaldii san qabtee namtichi bishaan sehee harkisee olbaase, akkasitti irraa gammadee fudhatanii deemaniin.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 20, 'Gatii xiqqaa, maallaqa lakkaa’amtuutti, isa gurguran, Isa keessattis danta dhaboota irraa ta’an. [1]', '[1] obboleeyantu daldaltoota eelaa baasan sanitti rakishatti gurguratan.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 21, 'Inni Misra irraa isa bites niitii isaatiin ni jedhe:(iddoo) qubsuma isaa kabaji “nu fayyaduun yookiin ilma isa taasifachuun keenya ni kejeelamaa", akka kanatti Yuusufiif dachii keessa mijjeessine, (Akka bulchaa isa goonuu) fi hiikoo manaamaas isa barsiifnuuf jecha. Rabbiin dhimma Isaa irratti injifataadha, Garuu irra hedduun namaa hin beekanu.[1]', '[1] daldaltoonni fuudhanii deemaniinii misra geessanii angaawaa achii tokkotti gurguratan, isaatu yeroo bitu jaartii isaatti akka jabeesitu dhaammate.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 22, 'Yeroo inni (dargaggoomee) jabummaa isaa ga’u, ogummaafi beekumsa isaaf kennine, Akka kanatti toltuu hojjattootaaf galata galchina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 23, 'Isheen inni mana ishee keessa jiru (qunnamtii saalaatiif) lubbuu isaa irraa isa abaabalte, Hulaalee ni cuccufte, nijette siif qophaa’eeraa kottu, nijedhe Ani Rabbitti maganfadha! Inni (dhiirsi kee) gooftaa kiyya; jireenya koo naaf tolchee jira, Dhugumatti, miidhaa hojjattoonni hin milkaayanu”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 24, 'Dhugumatti, isheen isatti yaadde, innis isheetti yaade, Odoo ragaa Gooftaa isaa arguu baatee. Akka kanatti hamtuufi hojii fokkataa isa irraa deebisuuf (ragaa keenya isa agarsiifne). Dhugumatti, inni gabroota keenya qulqulleeffamoo irraayyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 25, '(Isaan lamaan) gara balbalaa wal dorgoman, Isheen qamiisa isaa gara duubatiin dhoofte, Lamaanuu balbala biratti gooftaa (dhirsa) ishee argan, Isheen ni jette: “galanni nama warra (niitii) keetti hamtuu yaadee hidhamuu yookiin adabbii laalessaa malee hin taane.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 26, 'Inni (Yuusuf) ni jedhe: “Isheetu (qunnamtii saalaatiif) lubbuu kiyya irra na barbaadde, Ragaa ba’aan maatii ishee irraa ta’e tokkos (akkana jechuun) ragaa ba’e: “Yoo qamiisni isaa gara duraatiin baqaqfame, isheen dhugaa jettee inni kijibdoota irraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 27, 'Yoo qamiisni isaa gara duubaatiin baqaqfame, isheen ni sobdee inni dhugaa dubbattoota irraayi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 28, 'Yeroma qamiisni isaa gara duubatiin kan baqaqfame ta’uu argu, (dhirsi ishee) ni jedhe: “Dhugumatti, inni kun tooftaa keessan (dubartootaa) irraayyi. Dhugumatti, tooftaan keessan guddaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 29, 'Yuusuf kana irraa garagali. Ati (dubartittiin) immoo badii keetiif araarama kadhu. Dhugumatti, ati warreen dogoggoran irraa taatee jirta.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 30, 'Dubartoonni magaalattii keessa jiranis ni jedhan: “Niitiin mootichaa gabra ishee (qunnamtii saalaatiif) lubbuu isaa irraa isa abaabalti, Jaalalli isaas onnee ishee seenee jira. Dhugumatti, nuti jallina ifa ta’e keessatti ishee agarra.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 31, 'Yeroma hamii isaanii dhageessu, gara isaaniitti ergite, makaddaa (fiiNyaata) isaaniif qopheessite, Tokko tokkoon isaaniitiif hablee (billaa) ni kenitte. “Isaan irratti gadi bahi” jette, Yeroma isa argan isa dinqisiifatan Harkoowwan isaaniis mummuran, nijedhan “Rabbiin qulqulaa’ee, inni kun namaa miti, Inni kun maleykaa gaariidha malee waan biraatii miti”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 32, '(Isheenis) ni jette: “kun isa isin isa irratti na komattaniidha. Anatu (qunnamtii saalaatiif) lubbuu isaa irraa isa abaabbale, ni dide. Yoo inni waan ani isa ajaju dalaguu dide Dhugumatti ni hidhama; Salphattoota irraas ni ta’a”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 33, '[Inni] nijedhe “Gooftaa kiyya! Hidhaatu waan isaan itti na waaman irra ana biratti jaalatamaadha. Yoo Ati tooftaa isaanii narraa deebifte malee, ani gara isaaniin daba; wallaaltota irraa ta’a”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 34, 'Gooftaan isaa isaaf awwaatee tooftaa isaanii isarraa deebise. Dhugumatti, Inni (Rabbiin) Isatu dhaga’aa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 35, 'Sana booda erga mallattoowwan (qulqullummaa isaa mul’isu) arganii, yeroo murtaa’eef isa hidhuutu isaaniif mul’ate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 36, 'Isa waliin dargaggeessi lama mana hidhaa seenan. Tokkoon isaan lamaanii ni jedhe: “ani (abjuudhaan) kanin farsoo cuunfun of arge”. Inni biraa immoo ni jedhe: “ani mataa kiyya gubbaatti daabboo baadhee kan allaattiin isa irraa nyaattun arge, hiika isaa nutti himi. Gaarii hojjattoota irraa ta’uu kee arginaa ”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 37, '(Yuusuf) ni jedhe: “nyaanni isin isa nyaattan odoo inni isinitti hin dhufin dura hiika isaa isin lamaanitti himu malee isinitti hin dhufu; Kun wantoota Gooftaan kiyya na barsiise irraayyi. ani amantii (karaa) ummata Rabbitti hin amannee dhiise. isaan Aakiraatti kaafiroota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 38, 'Amantii abboota kiyya Ibraahiim, Isihaaqiifi Ya’aquubis hordofeera. Waan tokkos Rabbitti qindeessuun nuuf hin taane. Kuni tola Rabbii kan nuufi namoota (hunda) irratti tahe. Garuu irra hedduun namootaa (Rabbiin) hin galateeffatanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 39, 'Yaa hiriyoota kiyya lamaan kan mana hidhaa! Sila gooftota adda addaa (baay’ee) moo Rabbii tokkicha hunda mo’ataa ta’etu caala?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 40, 'Maqoota isiniifi abbootiin keessan moggaaftan malee Rabbii gaditti waan biraa gabbaraa hin jirtanu. Rabbiin ishee (gabbaruu) tti ragaa tokkos hin buufne; murtiin Rabbiif malee eenyuufuu hintaane. Isa malee akka hin gabbarre ajajeera. Kun amantii gadi dhaabbataadha. Garuu irra hedduun namaa hin beekanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 41, 'Yaa hiriyoota kiyya kan mana hidhaa! Egaa isin lamaan keessaa tokko gooftaa (mootii) isaa farshoo obaasa, Inni biraa immoo fannifameeti allaattiin mataa isaa irraa nyaatti, Dhimmi inni isin isa keessatti hiika gaafattan murtaa’ee jira.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 42, 'Issaan lamaan keessaa isa (nagaa) baha jedhee yaadeen “Gooftaa kee biratti na dubbadhu” jedheen, Gooftaa isaatti dubbachuu sheyxaanni isa dagachiise, Waggaa muraasa mana hidhaa keessa ture.[1]', '[1] yuusuf namticha hidhaa bahutti dhaammate, badii malee hidhamuu kiyya mootichatti naahimi akka nahiiku jedheen, garuu namticha sheyxaanni dagachiise, hinhimneef, saniin yuusuf hidhaa keessa ture.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 43, 'Mootichis ni jedhe: “Dhugumatti, ani sa’oota gabbataa ta’an torba kan (sa’oonni) huqqatoo ta’an torba nyaatan, akkasumas sootalloo (mataa midhaanii) magariisa torbaafi kan biraas gogaa (torba) abjuu keessatti argeera. Yaa qondaaltota (kiyya)! yoo kan manaama hiiktanu taataniif manaama kiyya kana naaf hiikaa”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 44, '“(Kuni) bursusa (yaacoo) manaamaati. Nutis hiika bursusaa beektota hin taane” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 45, 'Inni isaan lamaan (mana hidhaa keessa turan) irraa nagaa ba’eefi yeroo dheeraa booda (Yuusufiin) yaadatee ni jedhe: “Anatu hiika isaa isinitti himaa na ergaa.” (Gara Yuusuf ni deeme).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 46, '(Innis ni jedhe): “Yaa Yuusufii dhugaa dubbataa taate! Sa’oota gabbatoo torba kan (sa’oonni) huqqatoon torba isaan nyaataniifi sootalloo (mataa midhaanii) magariisaa torbaafi kan biraas gogaa (torba) hiika (abjuu kanaa) akka beekanuuf gara ummataa deebi’ee isaanitti himuun koo ni kajeelamaa nuuf himi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 47, 'Ni jedhe: “Waggaa walitti aanan torbaaf akkuma barametti facaafattu. waan oomishtan sootalloo isaa keessatti isa dhiisaa Xiqqoo waan irraa nyaattan malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 48, 'Ergasii san booda, waggoota rakkinaa torbatu dhufa waan isin isaaniif keessan hunda kan nyaatanu, xiqqoo waan kuuftanii malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 49, 'Ergasii sana booda waggaa isa keessa ummanni rooba argataniifi isa keessas (inaba) cuunfatantu dhufa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 50, 'Mootichis Isa natti fidaa jedhe. Yeroma ergamaan (mootichaa) isatti dhufu, (Yuusuf) ni jedhe: “Gara gooftaa keetii deebi’ii ‘waa’een dubartoota harka isaanii mummuranii maali’ (jedhii) isa gaafadhu. Dhugumatti Gooftaan kiyya shira isaanii beekaadha.” [1]', '[1] mootichi yuusuf hidharraa baasaa naafidaa jedhee itti erge, garuu yuusuf dubbiindubartoota harka ufmuranii sun qulqullooytu malee hinbahu jedhee ergaa mootichatti deebise,');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 51, '(Mootichis) “Yeroo Yuusufiin (qunn-amtii saalaatiif) lubbuu isaa irra isa abaabbaltan haalli keessan maal ture” jedheen. (Dubartoonni) ni jedhan: “Rabbiin qulqullaa’ee hamtuu tokkollee isa irratti hin beeknu”. Niitiin mootichaa nijette “Amma dhugaan ifa ta’eera, Anatu (qunnamtii saalaatiif)lubbuu isaa isa abaabbale, Dhugumatti, inni warreen dhugaa dubbatan irraayyi”.[1]', '[1] mooticha fuulduratti dubartoonni gaafatamanii qulqullummaa yuusf ragaa bahan, jaartiin mootichaatis yuusuf qulqulluu tahuufii tan badii hojjachuuf yaalte isii tahuu amante.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 52, '“kun (gooftaan kiyya) fagootti (bakka inni hin jirretti) akka an isa hin ganin akka beekuufi, Rabbiin tooftaa gantootaa hinqajeelchu”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 53, '“Lubbuu tiyyas hin qulqulleessu, Dhugumatti, lubbuun hamtuutti ajajjuudha nama Gooftaan kiyya rahmata godheef malee, Gooftaan kiyya araaramaa, rahmata godhaadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 54, 'Mootichis ni jedhe: “lubbuu kootiifan isa dhuunfadhaa isaan natti kottaa. Yeroma isa (Yuusufiin) hasofsiisu, “Ati har’a nu biratti mijjeeffataa amanamaadha” jedheen. [1]', '[1] booda mootichi yuusuf hidhaa baasanii akka isatti fidhan ajajee yuusuf hidha bahee mooticha bira dhaqee wajji haasayee, hojittis ramadame. rakkoon isaa achitti Rabbiin irraa guute. namni badirraa fagaatee Rabbi sodaate yeroof yoo rakkatellee obsa booda bal''inatti Rabbiin isa baasa. galata guddas Rabbirraa argata.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 55, '(Yuusufis) “kuusaa dachii irratti (itti gaafatamaa) na taasisi; ani isa irratti eegaa beekaadha” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 56, 'Akka kanatti Yuusufiif dachii keessatti mijjeessine, ishee irraa bakka fedhe kan qubatu ta’ee. Rahmata keenyaan nama feene tuqna. Mindaa warreen toltuu hojjataniis hin balleessinu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 57, 'Dhugumatti, isaannan amananii (Rabbiin) sodaattota ta’aniif mindaa Aakiraatu caala.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 58, 'Obboleeyyan Yuusuf gara isaa dhufanii isa irratti ol seenan, inni isaan beeke isaan isa wallaaloodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 59, 'Yeroma waan geggeessaa isaanii isaaniif qopheesse ni jedhe: “Obboleessa keessan kan karaa abbaatiin ta’een natti kottaa.sila safara guutuu koo hin argitanuu? ani caalaa keessummeessitootaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 60, 'Yoo isaan natti dhufuu baattan safarri na bira isiniif hin jiru, Nattis hin dhiyaatinaa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 61, '[Isaan] nijedhan “Nuti waa’ee isaa abbaa isaa ni gaafanna, Dhugumatti, nuti (dhimma kana) raawwatoodha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 62, 'Gabroota isaatiin nijedhe “akka yeroo gara maatii isaanii deebi’an ishee beekanii deebi’aniif maallaqa isaanii fe’isa isaanii keessa kaa’aa”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 63, 'Yeroma gara abbaa isaanii deebi’an ni jedhan: “Yaa abbaa keenya! safarri (midhaanii) nurraa dhorgameera. Obboleessa Kenya nuu wajjiin ergi. Ni safaranna. Nuti dhugumatti isaaf tiksoodha”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 64, '(Ya’aquub) ni jedhe: “Sila akkan duraan obboleessa isaa irratti isin amane malee isa irratti isin amanaa? Rabbiin eegaa ta’uutti caalaadha. Inni irra rahmata godhaa warreen rahmata godhaniiti.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 65, 'Yeroma meeshaa isaanii bananii maallaqa isaanii kan isaaniif deebi’e ta’uu arganis ni jedhan: “Yaa abbaa keenya! (kana caalaa) maal barbaanna? Isheen kuni maallaqa keenya; gara keenya deebifamte. Maatii keenyaaf nishammadanna, Obboleessa keenyas ni tiksina, Fe’iinsa (ba’aa) gaalaa tokkoos ni dabalanna, Kun (mooticha biratti) safara xiqqoodha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 66, '(Ya’aquub) ni jedhe: “isa isin wajjiin hin ergu hanga akka isa deebiftanii naaf fiddanutti kakuu Rabbi irraa ta’e naaf kennitanitti, Yoo (diinaan) marfamtan malee .” Yeroma isaan kakuu isaanii isaaf kennan “Rabbiin waan nuti jennu irratti ragaadha” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 67, 'Ni jedhe: “Yaa ilmaan kiyya! balbala tokkoon hin seeninaa, Balbaloota adda addaatiin seenaa, Ani (murtii) Rabbii irraa homaa isin irraa hin duroomsu, Dhugumatti, murtiin Rabbiif malee hin malu. Isa (qofa) irratti hirkadhe, Hirkattoonni isuma (qofa) irratti haa hirkatani.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 68, 'Yeroma isaan akkaataa abbaan isaanii isaan ajajeen seenani, (murtii) Rabbii irraa homaa kan isaan duroomsu hin taane. Garuu dhimma lubbuu Ya’aquub keessa jiru ishee raawwateera. Dhugumatti inni waan isa barsiifne irratti abbaa beekumsaati. Garuu irra hedduun namaa hin beekanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 69, 'Yeroma isaan Yuusuf irratti seenan obboleessa isaa (Ben-yaamiiniin) ofitti dhiheessee, “ani anatu obboleessa keetii, waan isaan kan hojjachatan tahanitti hin gaddin” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 70, 'Yeroma meeshaa isaanii isaaniif qopheessu, safartuttii meeshaa obboleessa isaa keessa kaa’e, Sana booda lallabaan ni lallabe “isin yaa daldaaltoota dhugumatti isin hattoota” (jedheen).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 71, 'Isaanis, gara isaanii gara galuun, “Maal dhabdan?” jedhaniin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 72, 'Ni jedhan: “Nuti safartuu mootii dhabnee; nama isa fideef (badhaasa) (midhaan) fe’aa gaalaa tokkotu isaaf jira. Ani kana irratti waadaa galaadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 73, 'Isaanis ni jedhan: “Rabbitti kakannee! Akka nuti dachii keessatti badii raawwachuuf hin dhufin isinis beektaniittu, Nuti hattootas hin taane.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 74, '“Yoo sobdoota taataniif adabbiin isaa maal ta’a?” jedhaniin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 75, 'Ni jedhan: “Adabni isaa namni inni meeshaa isaa keessatti argame isumatu (fuudhamuutu) adabbii isaati, Nuti akka kanatti isaan miidhaa (hanna) raawwatanu adabna.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 76, '(Sakkatta’uus) qalqalloo obboleessa isaa dura qalqalloo isaaniitiin jalqabe, eegasii meeshaa obboleessa isaa keessaa ishee baase. Akka kanatti Yuusufiif tooftaa baafne, obboleessa isaa seera mootichaa keessatti kan fudhatu hin turre Odoo Rabbiin Fedhuu baatee. Nama feene sadarkaalee hedduu ol fuuna. Abbootii beekumsaa hundaa olittuu beekaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 77, 'Isaanis (obboleeyyan Yuusufis) ni jedhan: “Yoo hates, obboleessi isaas (Yuusufis) kana dura hatee ture.” Yuusuf ishee of keessa dhokse, Isaaniif ishee hin ibsine (Of keessattis) ni jedhe: “Isinumatu sadarkaan keessan gadheedha. Rabbiin waan isin jettan irra beekaadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 78, 'Isaanis ni jedhan: “Yaa mootichaa! Dhugumatti, isaaf abbaa jaarsa manguddoo ta’etu jira. Kanaaf bakka isaa tokkoon keenya fudhadhu. Nuti gaggaarii irraa ta’uu kee si argina.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 79, 'Inni ni jedhe: “Nuti nama meeshaa keenya isa biratti argine malee fudhachuu irraa Rabbitti maganfanna. Dhugumatti, nuti yeroo san miidhaa hojjattoota.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 80, 'Yeroma isa irraa abdii muratan, kan maryatan ta’anii kophaa ba’an, Guddaan isaanii ni jedhe: “Sila dhugumatti abbaan keessan kakuu Rabbi irraa ta’e isin irratti qabachuufi kana duras Yuusuf irratti waan daangaa dabartan hin beektanuu? Kanaaf ani hanga abbaan kiyya naaf hayyamutti yookiin (hanga) Rabbiin dhimma kana naaf murteessutti dachii kana gadi hin dhiisu. Inni irra caalaa murteessitootaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 81, 'Gara abbaa keessanii deebi’aatii jedhaanii: “Yaa abbaa keenya! ilmi kee ni hate, Nuti waan beekneen malee ragaa hin baane. Nuti waan fagoo tiksitoota hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 82, '(Namoota) magaalaa nuti ishee keessa turreefi daldaaltota nuti isaan wajjin dhufnes gaafadhu, Nuti dhugaa dubbatoodha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 83, '(Ya’aquub) ni jedhe: “Lakkisaa; lubbuulee keessantu waan tokko isiniif midhaagsite (isa hojjattan); (Obsi koo) obsa bareedaadha, Rabbiin hunda isaan (sadeenuu) naaf deebisuun ni kajeelama. Inni Isumatu beekaa, ogeessa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 84, 'Isaan irraas gargalee “Yaa gadda kiyya! Yuusuf irratti” jedhe, gaddarraa irraa ijji isaa lamaanis addaatte; inni yaadaan guutamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 85, 'Nijedhan “Rabbitti kakannee! ati hanga manguddoo dadhabaa taatutti yookiin warra du’an irraa taatutti Yuusufiin dubbachuu irraa hin deemtu!”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 86, '(Ya’aquub) ni jedhe: “Ani yaaddoofi gadda kiyyas Rabbuma qofattin himadha, Rabbirraa waan isin hin beeknen beeka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 87, 'Yaa ilmaan kiyya! deemaa Yuusufiifi obboleessa isaa irraa odeeffadhaa. Rahmata Rabbii irraa abdii hin muratinaa. Dhugumatti rahmata Rabbii irraa eenyullee abdii hin kutu ummata kaafiroota malee.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 88, 'Yeroma isa (Yuusuf) irratti seenan isaan jedhan Ati Yaa mootichaa! nuufi maatii keenyas rakkoon mudateera. Mallaqa tuffatamtuun dhufnee, safara nuuf guutii, nurrattiis sadaqadhu, Dhugumatti, Rabbiin warreen sadaqatan mindeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 89, '(Yuusuf) nijedhe “Sila waan Yuusufiifi obboleessa isaa irratti yeroo wallaaloo turtan hojjattan beektuu?”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 90, '[Isaan] nijedhan “Sila dhugamatti ati sumaatu Yuusufii?”, [Inni] nijedhe “Ani Yuusufi; inni kunis obboleessa kiyya, Dhugumatti Rabbiin tola nutti ooleera. Dhugumatti, namni (Rabbiin) sodaateefi obse, Rabbiin mindaa toltuu hojjattootaa hin balleessu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 91, '[Isaan] nijedhan “Rabbitti kakannee! Dhugumatti, Rabbiin nurra si filatee jira. Dhugumatti nuti dogoggortoota turre”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 92, '(Yuusufis) ni jedhe: “Har’a komiin isin irra hin jiru; Rabbiin isiniif araarama. Inni irra rahmata godhaa warra rahmata godhaniiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 93, 'Qamisii kiyya kanaan deemaatii fuula abbaa kiyyaa irratti darbaa. [Inni] argaa ta’ee dhufa, Maatiiwwan keessan hundaan natti kottaa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 94, 'Yeroma daldaltoonni (Misraan) gadi dhiiftee (gara galaa deemte), abbaan isaanii nijedhe “ani foolii yuusufin argaa, Odoo isin totorra’aatti na yaaduu dhabdanii ”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 95, '[Isaan] “Rabbitti kakannee! Dhugumatti, ati jallinuma kee kan durii keessa jirta” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 96, 'Gammachiisaan Yeroma dhufu fuula isaa (Ya’aquub) irratti isa darbe. Innis kan argu ta’e (ijji nibanamteef) “Ani Rabbi irraa waan isin hin beeknen beeka isiniin hin jennee?” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 97, '[Isaan] “Yaa abbaa keenya! (Rabbiin) araarama nuuf kadhu badiilee keenyaaf. nuti dogoggortoota taanee jirraa” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 98, '(Ya’aquubis) “Ani fuul-duratti Gooftaa kiyya araarama isiniifin kadha. Inni Isatu araaramaa, rahmata godhaadha” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 99, 'Ergasii yeroo Yuusufiin bira seenan, haadhaafi abbaa isaa gara ofiitti qubsiise, nijedhe “Yoo Rabbiin fedhe nagayaan Misraan seenaa”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 100, 'Abbaafi haadha isaa siree irratti ol fuudhe, Isaan sujuuda isaaf bu’an, [Inni] ni jedhe: “Yaa abbaa kiyya! kun hiika manaama kiyyaa kan duraaniiti. Gooftaan kiyya dhugaa ishee taasiseera. Gooftaan kiyya tola natti oolee jira. yeroo mana hidhaa irraa na baasee, isin baadiyaa irraa isinfidhe, Erga shayxaanni anaafi obboleeyyan kiyya gidduutti diinummaa uumee booda, Dhugumatti, Gooftaan kiyya nama fedheef mararfataadha, Inni Isa qofatu beekaa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 101, 'Gooftaa kiyya! dhugumatti mootummaa irraa naaf kennitee jirta, Hiika manaamotaa irraas na barsiiftee jirta, (Yaa) Uumaa samiifi dachii! Ati Duuniyaafi Aakhiraattis gargaaraa kiyya. Muslima taasisii na ajjeesii, Warra gaggaarittis na dhaqqabsiisi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 102, 'Kun oduulee fagoo irraayyi, Gara keetti isa beeksifna, ati isaan bira hin turre Yeroo isaan kan (Yuusufitti) shira baasan ta’anii dhimma isaanii waliin qindeessan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 103, 'Irra hedduun namootaa (amanuu isaaniitiif) odoo bololtees kan amananii miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 104, 'Ati isa irratti mindaa wahii isaan hin gaafattu, Inni (Qur’aanni) aalamaaf gorsa malee waan biraatii miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 105, 'Samiileefi dachii keessa mallattoo kan isaan ishee irraa gara galan ta’anii ishee irra taran heddutu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 106, 'Irra hedduun isaaniis qindeessitoota ta’anii malee Rabbitti hin amananu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 107, 'Sila tasa haala isaan hin beekneen Rabbi irraa haguugduun adabbii Rabbii irraa taate isaanitti dhufuu yookiin Qiyaamaan isaanitti dhufuu of amanuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 108, '“Kun karaa kiyya Aniifi namni na hordofes beekumsa irratti haala ta’een gara Rabbiitti waama. Rabbiin qulqullaa’e Ani Mushrikoota irraayyii miti” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 109, 'Si duras dhiirota warra gandaa irraa wahyii gara isaaniitti buufne malee hin ergine. Sila dachii keessa deemanii booddeen warra isaaniin dura turanii akkam akka ta’e hin ilaalanuu? Dhugumatti, isaan (Rabbiin) sodaataniif mana Aakhiraatu caala. Sila hin xiinxaltanuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 110, 'Yeroma Ergamoonni abdii murataniifi dhugumatti kijibsiifamuu beekanitti tumsi keenya isaaniif dhufee namni feene baraarame. adabbiin keenyas ummata yakkamtoota irraa hin deebifamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 111, 'Dhugumatti, seenaalee isaanii keessa warra sammuu qabaniif gorsatu jira. Inni (Qur’aanni) oduu lafaa kaafamee odeeffame hin taane. Garuu dhugoomsaa (kitaabban) isa duraati. Addeessaa wantoota hundaati; ummata amananiif qajeelfamaafi rahmata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 1, 'Alif Laam Miim Raa tun keeyyattoota kitaabaati, Inni Gooftaa kee biraa gara keetti buufame dhugaadha. Garuu irra hedduun namaa hin amananu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 2, 'Rabbiin Isa samii (torban) utubaa malee uumeedha; isin ishee ni agartu. eegasii Arshii irratti (akka Isaaf maluun) ol ta’e. Aduufi baatiis ni laaffise, Hundinuu hanga beellama murtaa’eetti yaa’u, Wantoota hunda gara gaggalcha. 
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 3, 'Inni Isa dachii diriirsee ishee keessatti gaarreeniifi laggeeniis godheedha. Fuduraalee hunda irraas gosoota lama lama ishee keessatti godheera. Halkan guyyaa haguugsisa, Dhugumatti, kana keessa namoota xiinxalaniif mallattooleetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 4, 'Dachii keessas kutaalee walitti olloomantu jira, ashaakiltii Inaba irraa ta’an, sanyiiwwan faca’aniifi muka Timiraa damee qabaniifi damee hin qabne, kan bishaan tokkoon obaafamantu (jira). Dhandhama keessatti garii isaanii garii irra caalchifneerra. Dhugumatti, kana keessa ummata xiinxalaniif mallattooleetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 5, 'Yoo dinqisiifatte dinqisiisaadha jechi isaanii “sila yeroo biyyee taane nuti uumama haaraa keessatti (taanaa)?”. Isaan warra Gooftaa isaaniitti kafaraniidha. Isaan sun sakaallaaleen mormoowwan isaanii keessa jira. Isaan warra ibiddaati, Isaan ishee keessatti hafoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 6, 'Hamtuudhaan toltuu dura si ariifachiifatu, Odoo isaan dura adabbiin hedduun dabartee jirtuu, Dhugumatti, Gooftaan kee namaaf miidhaawwan hojjachuu isaaniitii wajjiin abbaa araaraati, Gooftaan kee abbaa adabbii cimaati', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 7, 'Isaannan kafaran nijedhan “Maaliif mallattoon wahii Gooftaa isaa biraa isa irratti hin buufamne?”. Ati dinniinuma qofa, Ummata hundaaf qajeelchaan jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 8, 'Rabbiin waan dhalaan hundi (garatti) baattu nibeeka, waan gadaamessaaleen hir’iftuufi waan dabaltus ni beeka. Wanti hundinuu Isa biratti hangaan murtaa’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 9, '(Rabbiin) Beekaa waan fagoofi dhihoo, guddaa, ol ta’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 10, 'Isin irraa namni jechaan (sagalee) gadi qabeefi ol fuudhes waluma qixa. namni halkan dhokateefi guyyaa ifatti ba’es (waluma qixa).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 11, 'Isaaf (tokko tokkoo namaatiif) maleeykota wal tareeffatoo ta’an fuuldura isaatiifi duuba isaa irraa ajaja Rabbiitiin isa eegantu jiru. Dhugumatti, Rabbiin waan ummatatti tahe hinjirjiiru, hanga isaan waan isaan waan lubbuulee isaanii keessa jiru jijjiiranitti. Yeroo Rabbiin ormatti hamtuu fedhe, deebisaan isaaf hin jiru; Isaaniif Isaa gaditti gargaaran hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 12, 'Inni Isa hangaasuu isin agarsiisuudha kan sodaattaniifi kan kajeeltan taatanii. Duumessa ulfaataas ni uuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 13, 'Mandiisuun (kakawweennis) faaruu Isaatiin (Isa) qulqulleessa. Maleeykonnis sodaa Isaa irraa (Isa qulqulleessu). Bakakkaalee nierga, isheedhaan nama fedhe dhawa. isaan (kaafiroonni) Rabbiin keessatti wal falman,Inni humni isaa cimaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 14, 'Waamichi dhugaa kan Isaati, Warri isaan Isa (Rabbii) gaditti waammatan, waatakkalleen isaaniif hin awwaatan. Akka (owwaannaa) nama ganaa isaa lamaan gara bishaanii hiixatuu (diriirsuu) malee,inni afaan isaatti haa ga’uuf inni isatti gayaa hintaane. Kadhaaleen kaafirootaa hoongoo keessa malee hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 15, 'Wantoonni samiileefi dachii keessa jiran Rabbiif sujuuda godhu. kan jaalataniifi kan jibban ta’anii, Gaaddidduuwwan isaaniis ganamaafi galgala keessatti.[1]', '[1] bakka kanatti sujuuda tilaawaa (qaraatii qur''aanaa) sujuuduu barbaachisa. inni qur''aana keessa bakka 15 jira.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 16, '“Gooftaan samiifi dachii eenyu?” jedhiin. “Allaahdha” Jedhi. “Sila Isaa gaditti jaalallee lubbuu isaaniitiif bu’aas ta’ee miidhaa hin argamsiifne taasifattanii?” jedhiin. “Sila jaamaafi namni argu wal qixaatuu? moo dukkanootaafi ifnis wal qixaatuu? jedhiin. moo isaan Rabbiif shariikowwan uumama akka Isaa uumanii uumamni isaan irratti wal fakkaate godhanii? “Rabbiin uumoo waan hundaati; Inni tokkicha injifataadha” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 17, 'Samii irraa bishaan (rooba) buusee laggeen hanga isheetiin ni yaate; lolaanis hoomacha ol fuudhamaa baadhate; waan isaan faayaafi meeshaa barbaaduuf jecha ibidda irratti qabsiisan irraas hoomacha (xurii) akkasiitu jira. Akka kanatti Rabbiin dhugaafi soba fakkeenya godha; hoomachi goggogaa ta’ee deema. Wanti nama fayyadu immoo dachii keessa taa’a. Akka kanatti Rabbiin fakkeenya godha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 18, 'Isaan Gooftaa isaaniitii awwaataniif jannatatu jira. Isaan Isaaf hin awwaatin immoo, odoo wanti dachii keessa jiru hundiifi fakkaataan isaas (isaaniif argamee) silaa isaan of bitu. Warri sun isaaniif qormaata hamaatu jira. Teessoon isaaniis jahannami (Inni) afata ta’uun waa fokkataa dha!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 19, 'Sila namni wanti Gooftaa kee irraa gara keetti bu’e dhugaa ta’uu isaa beeku akka nama jaamaatii? kangorfamu warreen sammuu qaban qofa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 20, '(Isaan) warra waadaa Rabbii guutaniifi waadichas hin diigneedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 21, 'Ammas warra waan Rabbiin akka inni maxxanfamu ajaje maxxansani. Gooftaa isaaniis sodaataniifi hamaa qormaataa sodaataniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 22, 'Isaan fuula Gooftaa isaanii barbaacha obsan, kan salaatas dhaabanii, waan Nuti isaaniif kennine irraa dhoksaniifi mul’isanii arjooman, kan waan gadhee waan gaariin deebisaniidha. Warri sun gandi boodaa isaaniif ta’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 23, '(Isheen) Jannata qubsumaa kan isaan ishee seenanuudha; Abbootii isaanii, niitiwwan isaanii, ilmaan isaanii irraas namni gaarii hojjate (ishee seena). Maleeykonnis balbala hundaan isaanitti seenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 24, '“Waan obsitaniif nageenyi isin irratti haa jiraatu; gandi boodaa waa tole!” (jedhu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 25, 'Isaan waadaa Rabbii erga jabaachuu isaatii booda diiganiifi waan Rabbiin akka fufamu ajaje kutan, kan dachii keessatti badii raawwatan, warri sun abaarsi isaaniif jira; isaaniif ganda hamaa ta’e (jahannamtu) jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 26, 'Rabbiin nama fedheef hiree bal’isa; (nama fedhe) itti dhiphisa. Isaan jireenya addunyaa kanaatti gammadani. Jireenyi addunyaa jireenya Aakhiraa biratti qananii yeroo gabaabaa malee hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 27, 'Isaan kafaran nijedhan “Sila maaliif Gooftaa isaa biraa mallattooleen wahii isarratti hin buufamin?". jedhi “Dhugumatti, Rabbiin nama fedhe ni jallisa; nama deebi’e immoo gara Isaatti qajeelcha”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 28, '(Isaan) warra amananii, onneewwan isaanii zikrii Rabbiitiin tasgabboofti. Dhaga’aa! zikrii (faaruu) Rabbiitiin onneewwan tasgabboofti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 29, 'Isaan amananii, gaggaarii hojjatan, isaaniif jiruu gaariifi deebii miidhagaa ta’etu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 30, 'Akka kanatti gara ummata ishee dura ummatoonni biraa dabrite keessatti si ergine. akka isa gara keetti buufne isaan irratti dubbiftuuf, isaan ‘Rahmaanitti’ kafaran. (Yaa Muhammad!) jedhi “Inni Gooftaa kiyya, Isa malee gabbaramaan haqaa hin jiru, Isa irratti hirkadheera. Garuma Isaatti deebiin”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 31, 'Odoo Qur’aanni gaarreen (iddoo isaanii irraa) isaan deemanii, yookiin dachiin isaan ciccittee, yookiin du’aan isaan dubbifameeyyuu (hin amananu). Amriin hunduu Rabbumaafi. Sila isaan amanan akka Rabbiin odoo fedhee namoota hunda qajeelchu hin beekanuu? Isaan kafaran waan isaan dalaganiin qalbi dhooftuun isaan tuqxu ta’uu irraa yookiin manneen isaaniitti dhihoo qubachuu irraa hin deemtu, hanga waadaan Rabbii dhufutti. Dhugumatti, Rabbiin waadaa hin diigu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 32, 'Ergamoota si duraattis qishnaan itti godhameera; isaan kafaraniif beellama godheen sana booda isaan qabe. adabbiin kiyya akkam ta’e ree!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 33, 'Sila Inni (Rabbiin) lubbuu hunda irratti waan isheen hojjatteen (tiksuun) dhaabbataa ta’e (akka gabbaramaa akkas hin ta’iniitii?). Isaan Rabbiif hiriyoota (shariikoowwan) taasisan. jedhi “Isaan maqaa dhahaa”. Sila waan Inni dachii keessatti hin beekne Isatti himtumoo jecha mul’ataa (kan sobaa dubbattu)? ”Dhugumatti isaan kafaraniif shirri isaanii isaaniif miidhagfamee, karaa qajeelaa irraa deebifamaniiru. Nama Rabbiin isa jallise qajeelchaan isaaf hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 34, 'Isaaniif jireenya addunyaa keessatti adabbiitu jira. adabbiin Aakhiraa immoo akkaan jabaadha. Ammas isaaniif (adabbii) Rabbii irraa ittisaan hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 35, 'Fakkeenyi jannata warri (Rabbiin) sodaatan waadaa galamanii, jala ishee laggeentu yaa’a; nyaanni ishee walitti dhaabbataadha; gaaddisni ishees (akkasuma). tun booddee warra Rabbiin sodaataniiti. Booddeen kaafirootaa immoo ibidda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 36, 'Warri nuti kitaaba isaaniif kennine, waan gara keetti buufametti ni gammadu. Ahzaaba irraa nama garii isaa mormutu jira. jedhi “Kan ani ajajames Rabbiin qofa gabbaruufi Isatti homaa qindeessuu dhabuudha”. Gara Isaa qofattin waama; deebiin kiyyas gara Isaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 37, 'Akka kanatti murtii Arabiffaa ta’ee isa (Qur’aana) buufne. Ati odoo fedha lubbuu isaanii hordoftee erga beekumsa irraa (wanti siif kenname) sitti dhufee booda, (adabbii) Rabbii irraa tumsaafi tiksaan siif hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 38, 'Dhugumatti, Nuti si duras ergamtoota erginee jirra. Niitiiwwaniifi ilmaan isaaniif taasifnee jirra. Ergamaan tokkos yoo hayyama Rabbiitin ta’e malee mallattoo (raajii) tokkos fiduu hin danda’u. beellama hundaafuu galmeetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 39, 'Rabbiin waan fedhe ni haqa; (waan fedhe immoo) ni mirkaneessa. Isa bira haadha kitaabaattu (Lawhal Mahfuuztu) jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 40, 'Yoo garii waan ittiin isaan sodaachifnee si argisiifne (tolte). Yookiin yoo si ajjeefnes (komiin sirra hin jiru). Wanti sirra jiru geessuu qofa; qormaanni immoo Nurra jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 41, 'Sila akka Nuti dachii moggaalee ishee irraa hir’isaa dhufnu hin ilaalanii? Rabbiin ni murteessa; murtii isaas wanti duubatti deebisu hin jiru. Inni saffisiisaa qormaataati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 42, 'Dhugumatti, warri isaaniin duraa mala baasanii jiru. Malli hundi kan Rabbiiti. Waan lubbuun hundi hojjattu ni beeka. Kaafiroonni booddeen gaariin eenyuuf akka ta’e beekuuf jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 43, 'Isaan kafaran “ati ergamaa miti” Siin jedhu. “Gidduu kiyyaafi gidduu keessanitti ragummaaf Rabbiin ga’aadha. namoonni beekumsi kitaabaa isaan bira jirus" jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 1, 'Alif Laam Raa (Inni) kitaaba gara keetti isa buufneedha. akka ati nama hayyama Gooftaa isaanitiin dukkana (kufrii) irraa gara ifaa (Islaamaa), gara karaa (Rabbii) injifataa, faarfamaa ta’ee baaftuuf.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 2, 'Rabbiin Isa wanti samii keessa jiruufi wanti dachii keessa jiru hundi kan Isaa ta’eedha. Badiin azaaba cimaa irraa ta’e kaafirootaaf ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 3, 'Isaan warra jireenya addunyaa kanaa isa Aakhiraa irra jaalatanii, karaa Rabbii irraa (namoota) deebisaniifi jallina ta’uu ishee barbaadaniidha. Isaan sun jallina fagoo keessa jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 4, 'Nuti ergamaa irraa tokkos afaan ummata isaatiin malee hin ergine. akka inni (ergaa keenya) isaaniif addeessuf jecha. Rabbiin nama fedhe jallisa; nama fedhe qajeelcha. Inni injifataa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 5, 'Nuti dhugumatti Muusaa raajiwwan keenyaan ergine “Ummata kee dukkanoowwan irraa gara ifaatti baasi, Guyyoota Rabbiitiin isaan yaadachiisi” jechuun. Dhugumatti, kana keessa warra akkaan obsanii, cimsanii galateeffatan hundaaf mallattooleetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 6, 'Yeroo Muusaan ummata isaatiin jedhes [yaadadhu] :“Ni’imaa Rabbii kan isin irratti tahe yaadadhaa. kan yeroo ummata Fir’awni irraa isin baraarse, kan adabbii laalessaa isin dhandhamsiisaa; ilmaan keessan qaqqalaa; dubartoota keessan akka jiraatan dhiisan, Kana keessa mokkoroo guddaa Gooftaa keessan irraa ta’etu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 7, 'Ammas yeroo Gooftaan keessan lallabee: “Yoo na galateeffattan, (ni’imaa kiyya irraa) isiniifin dabala. yoo natti kafartan, dhugumatti adabbiin kiyya akkaan hamaadha” (jedhe yaadadhaa).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 8, 'Muusaan nijedhe Yoo isiniifi namoonni dachii irra jiran hundi kafartan (Rabbiin homaa hin miitan) dhugumatti Rabbiin dureessa, faarfamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 9, 'Sila oduun warra isin dura turanii isin hin geenyee? (Oduun) Kan ummata Nuuh, Aad, Samuudiifi warra isaan boodaa kan Rabbiin malee homtuu isaan hin beekne (isin hin geenyee)? Ergamoonni isaanii ragaawwan ifa ta’aniin itti dhufanii harkoowwan isaanii afaanoowwan isaanii keessatti deebisani “Dhugumatti, nuti isa isin ittiin ergamtanitti kafarree jirra. Ammas nuti isa isin itti nu waamtan irraa mamii dhamaasaa keessa jirra” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 10, 'Ergamoonni isaanii ni jedhan: “Sila Rabbii uumaa samiifi dachii ta’e, kan badii keessan irraa isiniif araaramuufi hanga yeroo murtaa’ee isin tursiisuuf isin waamu (jiraachuu isaa) keessa shakkiin jiraa?”. [Isaan] “Isin namuma akka keenyaa malee hintaane, waan abbootiin keenya gabbaraa turan irraa nu dhorguu barbaadan. mee ragaa ifa ta’een nutti kottaa” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 11, 'Ergamoonni isaanii isaanin ni jedhan: “Nuti nama fakkaataa keessanii malee hin taane. Garuu Rabbiin gabroota Isaa irraa nama fedhe irratti tola oola. Nuti hayyama Rabbiitiin malee taaytaa (ragaa) tokkoonis isinitti dhufuun nuuf hin taane. Mu’uminoonni Rabbi (qofa) irratti haa hirkatanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 12, 'Sila dhugumatti odoo Inni karaa keenya nu qajeelchee jiruu maaltu nuuf jiraayyi Rabbi irratti hin hirkanne! Dhugumatti rakkoo isin nurrraan geessan irratti ni obsina. Hirkattoonni Rabbi irratti haa hirkatu.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 13, 'Warri kafaran ergamtoota isaaniitiin nijedhan “dhugumatti, nuti dachii keenya irraa isin baafna yookiin gara amantii keenyaa akka deebitan” jedhan. Rabbiin isaanii “Nuti dhugumatti miidhaa hojjattoota ni balleessina” jechuu beeksisa gara isaanitti godhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 14, '“Dhugumatti isaan booda dachittii irra isin qubsiifna. Kun nama Na dura dhaabbachuu sodaateefi dinniina kiyyas sodaateefi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 15, '(Ergamoonnis Rabbi irraa) deeggarsa barbaadan. (gargaarsa ni argatan) Of tuulaan, mormaan hundi ni hoonga’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 16, 'Fuuldura isaa jahannamtu jira. Bishaan malaa irraa obaafama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 17, 'Liqimsuuf yaala; gadi isa liqimsuutti hin dhiyaatu (hin danda’u). Duuti kallattii hunda irraa isatti dhufa. Inni kan du’uu miti. Fuuldura isaa azaaba guddaa ta’etu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 18, 'Fakkeenyi warra Rabbii isaaniitti kafaranii, dalagaaleen isaanii akka daaraa guyyaa bubbee cimaa qilleensi itti hammaatteeti, Waan hojjatan irraa homaattuu (fayyadamuu) hin danda’an. Kun isatu jallina fagoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 19, 'Sila dhugumatti Rabbiin samiileefii dachii dhugaan uumuu hin argituu? (Rabbiin) yoo fedhe isin adeemsiseetiin uumama haaraa fida.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 20, 'Kuni Rabbi irratti jabaataa miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 21, 'Hunda ta’anii Rabbiif mul’atan. dadhaboonni isaan boonaniin nijedhan “dhugumatti, nuti isiniif hordoftoota taane, sila isin adabbii Rabbii irraa homa tokko nurraa deebisoo dhaa?" (Isaan boonan) nijedhan “Odoo Rabbiin nu qajeelchee, silaa nutis isin qajeelchina turre. (Har’a) obsinus obsuu baannus nurratti waluma qixa. Iddoon baqannaa tokkos nuuf hin jiru”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 22, 'yeroma dhimmichi murteeffamu sheyxaanni ni jedhe: “Dhugumatti, Rabbiin waadaa dhugaa isiniif seene; anis waadaa isiniif seenee isin gane. isin irratti anaaf aangoon tokkollee hin taane. Isin waamnaanuma naaf owwaattan malee.ana hin komatinaa, lubbuulee teessan komadhaa malee. Ani isiniif birmataa miti; isiniis naaf birmatoo miti. Ani waan isin duraan (Rabbitti) na qindeessitan waakkadhe” Dhugumatti, miidhaa raawwattoonni adabbii laalessaatu isaaniif jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 23, 'Isaan amananii gaggaarii hojjatan jannata laggeen ishee keessa yaatu seensifaman. ishee keessatti kan hafan ta’anii hayyama Gooftaa isaaniitiin. waldubbisaan isaanii ishee keessatti ‘salaam’ (jechuu dha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 24, 'Sila akkamitti akka Rabbiin fakkeenya godhe hin arginee? jechi gaariin akka muka gaarii hundeen ishee gadi dhaabbataa ta’ee, dameen ishee samii keessatti ta’eetti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 25, 'Firii ishee ni kenniti (nidhalti) Yeroo hunda hayyama Gooftaa isheetiin. Rabbiin fakkeenya namootaaf godha Akka isaan gorfamanuuf jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 26, 'Fakkeenyi jecha fokkataa akka muka fokkataati. kan gubbaa dachii irraa buqqifamtee isheedhaaf gadi dhaabannaan hin taaneeti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 27, 'Warra amanan jecha gadi dhaabbataadhaan Rabbiin gadi (isaan) dhaaba. jireenya addunyaafi Aakhiraa keessattis. Rabbiin miidhaa hojjattoota ni jallisa. Rabbiin waan fedhe hojjata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 28, 'Sila gara isaan ni’imaa Rabbii kufriin jijjiiranii hinlaallee?,kan ummata isaanii ganda badii qubsiisan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 29, 'Jahannamiin ishee seensifaman, qubannaa waa fokkate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 30, 'Karaa Isaa irraa (namoota) jallisuuf Rabbiif hiriyoota godhan. “(yeroo xiqqoof) qanani’aa Dhugumatti deebiin keessan gara ibiddaati” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 31, '(Yaa Muhammad!) gabroota kiyya warreen amananiin jedhi “salaata ni dhaaban, waan Nuti isaaniif kennine irraas kan dhoksaniifi mul’isan ta’anii ni arjoomu (sagadaa, arjoomaa) odoo guyyaan bittaa gurgurtaafi jaalalleen isa keessa hin jirre hin dhufin dura”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 32, 'Rabbiin Isa samiifi dachii uumee samiiwwan irraas bishaan (rooba) buusee ittiin fuduraa irraa soorata isiniif baaseedha. Dooniis akka ajaja Isaatiin galaana keessa deemtu isiniif laaffise; laggeenis isiniif laaffise.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 33, 'Aduufi ji’as walitti fufuun kan deeman ta’anii isiniif laaffisee halkaniifi guyyaas isiniif laaffise.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 34, 'Waan isin Isa kadhattan hunda irraa isiniif kenne. qananii Rabbii odoo lakkooftani ishee fixuu hin dandeessanu. Dhugumatti, namni daran miidhaa hojjataa daran kafaraadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 35, 'Yeroo Ibraahiim jedhu [yaadadhu]:“Gooftaa kiyya! Biyya kana (Makkaan) nagaya taasisi. Anaafi ilmaan kiyyaas taabotoota gabbaruu irraa nu fageessi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 36, 'Gooftaa kiyya! isaan nama hedduu jallisanii jiru; Namni na hordofe, inni anarraayyi. Nama na dide Ati araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 37, 'Gooftaa keenya! Ani garii maatii kiyya irraa ta’e bowwaa (laga) qonna hin qabne, mana kee kabajamaa biratti dhiiseen jira. Gooftaa keenya! Akka salaata gadi dhaabaniif jecha. nama irraas onneewwan (isaanii) kan gara isaanii hawwitu taasisi;fuduraalee irraas isaan soori Akka isaan Si galateeffataniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 38, 'Gooftaa keenya! Ati waan nuti dhoksinuufi waan nuti ifa goonu ni beekta. Rabbi irratti dachii keessattis ta’ee samii keessatti homtuu hin dhokatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 39, 'Faaruun (hundi) kan Rabbii manguddummaa irratti Ismaa’iiliifi Isihaaqiin naaf kenneeti. Dhugumatti, Gooftaan kiyya kadhaa dhaga’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 40, 'Gooftaa kiyya! Kan salaata dhaabu na godhi. Ilmaan kiyya irraas (akkasuma). Gooftaa keenya! kadhaa kiyyas narraa qeebali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 41, 'Gooftaa keenya! naaf araarami, haadhaafi abbaa kiyyaafis mu’uminoota hundaafis guyyaa qormaanni godhamu (guyyaa qiyaamaa) san.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 42, 'Rabbiin Waan zaalimtoonni hojjatanirraa dagataa hin sehin. Kan Rabbiin booda isaan aansuuf guyyaa isa keessa ijoowwan banamtee ol fuudhamtuufi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 43, '(Gara waamichaatti) daddafoodha, mataalee isaanii kan ol kaasan ta’anii (ijji isaanii ol kaati), Ijji isaanii gara isaaniitti hin deebi''u, Qalbiileen isaaniis duwwaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 44, 'Ilma namaa akeekkachiis guyyaa adabichi isaanitti dhufee, warri miidhaa hojjatan nijedhan “Gooftaa keenya! hanga beellama dhihootti booda nu aansi; waamicha Kee awwaannee ergamoota keetis hordofna”. (isaaniin jedhama) “Sila isin kanaan dura (addunyaa irraa) deemsi isiniif hinjirurratti kakachaa hin turree?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 45, 'Manneen warra lubbuulee isaanii miidhanii keessa jiraattan. Akkam akka isaanitti hojjannes ifa isiniif ta’eera. Fakkeenya hedduus isiniif gooneerra” (jedhamaan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 46, '(Isaan) dhugumatti mala isaanii malaniiru. Malli isaanii (galanni isaa) Rabbiin bira jira. Tooftaan isaanii kan gaarri isa irraa bakka deemtuu miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 47, 'Rabbiin waadaa Isaa kan ergamtoota Isaatiif gale diigaa ta’uu hin yaadin. Dhugumatti, Rabbiin injifataa, abbaa haaloo bahannaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 48, 'Guyyaa dachiin dachii biraatti jijjiiramtee samiileenis (akkasuma taatee), Rabbii tokkicha, injifataa ta’eef (uumamni hundi) walitti qabamanii mul’atan [yaadadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 49, 'Guyyaa san badii hojjattoota sakaallaalee keessatti kan walitti qindaa’an ta’anii argita.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 50, 'Qamiisni isaaniis “qanxiraana” (reenjii) irraayyi. Ibiddi fuula isaanii ni haguugdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 51, 'Rabbiin lubbuu hunda waan isheen dalagdeen mindaa galchuuf (kana godhe). Dhugumatti, Rabbiin herregni isaa saffisaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 52, '(Qur’aanni) kun ergaa gayaa ilma namaati, akka ittiin akeekkachiifamanuuf, Inni (Rabbiin) gabbaramaa haqaa tokkicha ta’uu akka beekaniifi warri sammuu qaban akka ittiin gorfamaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 1, 'Alif Laam Raa tun keewwattoota kitaabichaatiifi Qur’aana (waan hunda) ifa baasaa ta’eeti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 2, 'Isaan kafaran (Guyyaa Qiyaamaa) odoo Muslimoota ta’anii baay’ee hawwu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 3, 'Isaan dhiisi Haa nyaatanii; Haa qanani’anii; hawwiin (sobaa) isaan haa daguu, (Itti gala isaanii) fuula duratti ni beeku.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 4, '(Warra) gandaa tokkollee hin balleessine beellamni beekamaan isheef jiraatu malee .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 5, 'Ummanni tokkollee beellama ishee hin dursitu, boodas hin aansamanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 6, 'Nijedhan “Yaa isa zikriin (Qur’aanni) isa irratti buufame! dhugumatti ati maraataadha”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 7, 'Maaliif maleeykotaan nutti hin dhufne Yoo warra dhugaa dubbattoota irraa taate?” (jedhan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 8, 'Nuti maleeykota dhugaan (adabaan) malee hin buufnu, Yoosan yeroon isaaniif kan kennamu hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 9, 'Nuti Zikrii (Qur''aana) Numatu buuse, Numatu isaaf tiksoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 10, 'Dhugumatti, Nuti siin duratti ummattoota duraanii keessatti (ergamtoota) erginee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 11, 'Ergamaan tokkos isatti dhufee kan isatti qishinan ta’anii malee hintaane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 12, 'Akka kanatti onnee yakkamtootaa keessa isa (sobsiisuu) seensifna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 13, 'Isatti hin amananu, Dhugumatti, gochi (adabbiin) warra duraanii dabartee jirti (wanti isaan tuqe isaan kanas ni tuqa).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 14, 'Odoo balbala samii irraa ta’e isaan irratti bannee, ishee keessa kan ol ba’an ta’anii;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 15, 'Silaa nijedhan “ijootuma keenyatu cufame, Inumaa nuti ummata sihriin itti godhameedha”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 16, 'Nuti dhugumatti samii keessatti urjiilee gugurdaa taasifnee, namoota ilaalaniif ishee miidhagsinee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 17, 'Sheyxaana darbatamaa hunda irraa ishee tiiksine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 18, 'Isa dhageettii hatee malee qaanqee mul''ataatu isa hordofe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 19, 'Dachii Nuti ishee diriirsinee jirra, Gaarreen ishee keessati goonee jirra, Wanta madaalamaa ta’e hunda irraas ishee keessatti magarsinee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 20, 'Ishee keessatti waan ittiin jiraattaniifi waan isin isaan hin soorre (beyladoota) isiniif goone.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 21, 'Wanti tokkos hin taane;Kuusaaleen isaa Nu biratti ta’u male, Hanga beekaamaadhaan malee isa hin buufnu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 22, 'Bubbeewwan ergine Baadhattuuwwan (duumessaa) taasifnee, Samii irraa bishaan buufnee isa isin obaafnee jirra, (Nutu isiniif kuusa malee) isin isa (kuusuu irratti) danda’oo hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 23, 'Nuti dhugumatti (lubbuu) Numatu jiraachisee ajjeesa, Numatu dhaaltota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 24, 'Dhugumatti Nuti isin irraa warren darban beekneerra, Warren boodaas dhugumatti beeknee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 25, 'Dhugumatti Gooftaan kee Isumatu walitti isaan qaba; Inni ogeessa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 26, 'Dhugumatti Nuti nama (Aadamiin) suphee dhoqqee jijjiiramaa ta’e irraa uumne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 27, 'Jinnii (Ibliisiin) immoo duraan ibidda boba’aa irraa isa uumne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 28, 'Yeroo Gooftaan kee maleeykotaan jedhe [yaadadhu]:“Ani nama suphee (faara) dhoqqee jijjiiramarraa ta’e irraa uumaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 29, 'Yeroo Ani isa sirreessee ruuhii (uumaa) kiyya irraa ta’e isa keessatti afuufe, sujuuddota ta’aatii isaaf kufaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 30, 'Maleeykonni hundi walumaa galatti sujuuda bu’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 31, 'Ibliis malee inni warra sujuuda bu’an wajji ta’uu dide.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 32, '(Rabbiin) “Yaa Ibliis! Maaliif warra sujuuda bu’an wajji ta’uu didde?” jedheen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 33, '[Inni] nijedhe “Ani nama Ati suphee (faara) dhoqqee jijjiiramaa ta’e irraa uumteef kan sujuudu hintaane”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 34, '(Rabbiinis)nijedheen “ishee irraa ba’i; Ati darbamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 35, 'Dhugumatti hanga Guyyaa Murtiitti abaarsi sirratti jiraata.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 36, '“Gooftaa kiyya! Hanga guyyaa kaafamaatti na tursiisi” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 37, '(Rabbiinis) “Dhugumatti, ati tursiifamtoota irraayi” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 38, '“Hanga guyyaa yeroo beekaamaatti.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 39, '(Ibliis) ni jedhe: “Gooftaa kiyya! na jallisuu keetiin kakadhee, dhugumatti dachii keessatti (karaa jallinaa) isaaniif miidhagseen hunda isaanii isaan jallisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 40, 'isaan irraa Gabroota kee qulqulleeffamoota malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 41, '(Rabbiin) ni jedhe: “Kun karaa qajeelaa (isa eeguun) narratti ta’eedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 42, 'Dhugumatti, gabroota kiyya irratti dandeettiin tokkoyyuu siif hin jiru. Jallattoota irraa warra si hordofan malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 43, 'Dhugumatti jahannam (isaafi hordoftoota isaatiif) beellamamaa isaan hundaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 44, 'Isheedhaaf balbala torbatu jira. Tokko tokkoo balbalaatiif isaan irraa qooda ramadamaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 45, 'Warri (Rabbiin) sodaatan ashaakiltiiwwaniifi burqaawwan keessa jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 46, '“Nagaan tasgabbaa’aa ishee seenaa” (jedhamaan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 47, 'Jibbaa irraa waan qomoota isaanii keessa jiru baafne, Obboleeyyan sireewwan irratti walitti garagaggalan ta’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 48, 'Ishee keessatti dadhabbiin isaan hin tuqu. Isaan ishee irraa baafamoo hintaane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 49, 'Gabroota kiyyatti odeessi Ani Anumatu araaramaa, rahmata godhaadhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 50, '“Adabni kiyyas isatu adabbii laalessaadha” (jeechuus itti himi.)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 51, 'Keessummaa Ibraahiim irraas isaanitti odeessi', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 52, 'Yeroo isa irratti seenanii, salaam jedhan (nagaa gaafatan) [Inni] “Dhugumatti, nuti isin irraa sodaatoodha” jedheen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 53, '“Hin sodaatin, Nuti ilma beekaa ta’een si gammachiifnaa” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 54, '“Sila dullumni na tuquu wajjin na gammachiiftuu? Maaliin na gammachiiftu?” jedheen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 55, '“(Nuti) dhugamaan si gammachiifne; Abdii kutattoota irraa hin ta’in” jedhaniin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 56, '“Jallattoota malee Rahmata Gooftaa isaa irraa eenyutu abdii murata?” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 57, '“Isin yaa warra ergamtootaa! Dhimmi (haalli) keessan maali?” jedheen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 58, '“Nuti dhugumatti, gara ummata yakkamtootaatti ergamne” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 59, '“Maatii Luux malee dhugumatti, nuti hunduma ta’anii isaan baraarsoodha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 60, '“Niitii isaa malee; Nuti (adaba keessatti) haftoota irraa ta’uu ishee murteessine.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 61, 'Yeroma ergamtoonni maatii Luuxitti dhufanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 62, '“Isin ummata wallaalamoodha” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 63, '“nuti waan isaan isa keessatti shakkaa turaniin sitti dhufne” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 64, '“Dhugaadhaan sitti dhufne, Dhugumatti nuti dhugaa dubbattoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 65, 'Cittuu halkan irraa taateen maatii keetiin deemi; Duubaawwan isaanii hordofi, Isin irraa namni tokkos of duuba hin mil’atin; gara iddoo ajajamtanii deemaa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 66, 'Ajaja sanas "xumurri warra sanii bariifattoota ta’anii muramaadha” jechuun gara isaatti murteessine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 67, 'Jiraattonni magaalaa kan wal gammachiisan ta’anii dhufan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 68, '(Luuxis ni jedhe): “isaan kun keessumoota kiyyaa, nan xiqqeessinaa” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 69, '“Rabbiin sodaadhaa; nan xiqqeessinaa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 70, '(Namoonni magaalattii) “Sila nuti aalama (keessummeessuu) irraa si hin dhorginee?” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 71, '(Luux) ni jedhe: “kun shamarran kiyya, Yoo kan raawwattan taataniif (isaan fuudhaa).”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 72, '(Yaa Muhammad!) Jireenya keetti kakadhee! Dhugumatti, isaan machii isaanii kessa dhama’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 73, 'Iyyattiin isaan qabatte aduu baasifatootahanii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 74, 'Gubbaa ishee jala ishee taasifnee (gara galchine), dhagaa xuubii (dhoqqee gubame) irraa ta’e isaanitti roobsine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 75, 'Dhugumatti, kana keessa xiinxaltootaaf mallattooleetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 76, 'Isheen (magaalattiin) daandii (guddaa) qajeelaa irra jirti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 77, 'Dhugumatti, kana keessa mu’uminootaaf mallattootu jirti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 78, 'warri eeykaa (bosonaa) dhugumatti miidhaa raawwattoota ta’an.[1]', '[1] isaan ummata nabi shu''eybi itti ergameedha.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 79, 'Haaloo isaan irraa ba’anne. Dhugumatti, isaan lamaanuu daandii ifa ta’e irra jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 80, 'Dhugumatti jiraattonni Hijris ergamtoota kijibsiisaniiru.[1]', '[1] warra laga hijrii jiraatu. isaan samuud jedhaman, nabi saalihtu itti ergame. nikijibsiisan.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 81, 'Mallattoolee keenyas isaaniif kenninee, isaan irraa garagaloo ta’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 82, 'Of amanoo ta’anii gaarreen irraa manneen isaanii urataa turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 83, 'Bariifatoo ta’anii iyyansi isaan qabatte', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 84, 'Wanti isaan hojjataa turan isaan irraa homaa hin deebifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 85, 'Samiileef dachiifi wantoota gidduu isaan lamaanii dhugaadhaan malee hin uumne. Dhugumatti Qiyaamaan dhuftuudha. Irraa gara galuu gaarii ta’e gara gali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 86, 'Rabbiin kee isatu akkaan uumaa, beekaadha', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 87, 'Dhugumatti Nuti dorban deddeebi''aa fii Qur’aana guddaa siif kenninee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 88, 'Gara waan nuti garee isaan (kaafiroota) irraa ta’an ittiin qanansiifnee ija kee lamaan hin diriirsin; Isaan irratti hin gaddin; kooluu kee Mu’uminootaaf gadi qabi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 89, '“Dhugumatti ani, anatu sodaachisaa ifa galaadha” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 90, 'Akkuma qoqqooddattoota irratti buufne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 91, 'Isaan Qur’aana garee taasisan (gariitti amananii garitti kafaran).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 92, 'Gooftaa keetti kakannee! dhugumatti hunda isaanii ni gaafanna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 93, 'Waan isaan dalagaa turan irraa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 94, 'Waan itti ajajamte ifatti labsi; Mushrikoota irraa garagali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 95, 'Nuti qishnitoota siif geenyeerra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 96, '(Isaan) warra Rabbii wajjiin gabbaramaa biraa godhan; fuulduratti beeku.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 97, 'Dhugumatti waan isaan jedhanuun qomti kee rakkachuu ni beekna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 98, 'Gooftaa kee faarsuu wajjin Isa qulqulleessi, Warra sujuudan irraa ta’i.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 99, 'Hanga dhugaan (duuti) sitti dhufutti Gooftaa kee gabbari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 1, 'Ajajni Rabbii (Guyyaan Qiyaamaa) dhufee, kanaafuu isa hin jarjarfatinaa, (Rabbiin) waan isaan Isatti qindeessan irraa qulqullaa’ee ol ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 2, 'Maleeykota wahyiidhaan eeyyama Isaatiin gabroota Isaa irraa nama fedhe irratti buusa, “(kaafiroota adabaan) akeekkachiisaa, Dubbiin, Gooftaan dhugaan gabbaramu Ana malee hin jiru; Anuma sodaadhaa” jechuun (malaykaa buusa).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 3, 'Samiifi dachii dhugaadhaan uumeera, Inni waan isaan (Isatti) qindeessan irraa ol ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 4, 'Bishaan hormaataa xiqqoo irraa nama uume, Yoma san inni (Aakiraa sobsiisuun) mormaa ifa bahaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 5, 'Beyladas isiniif ishee uume. Isaan keessatti isiniif ho’ifannaafi bu’aalee birootu jira. Ishee irraa ni nyaattus.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 6, 'Yeroo (gara mooraa) galchitaniifi yeroo bobbaaftan (gadi yaaftan) ishee keessa bareedumatu isiniif jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 7, 'Ba’aa keessan ulfaataa gara biyya isin ifaajee (rakkina) lubbuuleetiin malee isa gahoo hin taaneetti baadhatti. Dhugumatti, Gooftaan keessan mararfataa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 8, 'Farda, gaangewwaniifi harrootas akka yaabbattaniifi miidhaginaaf jecha (isiniif uume), Wantoota isin hin beeknes ni uuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 9, '(Tola isaatiin) karaa qajeelaa ibsuun Rabbuma irra jira. Ishee irraa jallaatu jira. (Rabbiin) odoo fedhee hunda keessan isin qajeelcha ture.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 10, 'Inni Isa samii irraa bishaan buuse. Isiniif isa irraa dhugaatiitu jira. Isa irraas muka isin ishee keessatti (beyladoota) tikfattantu (marga).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 11, 'Isaan sanyii midhaanii, Zeytuuna, mukkeen Timiraa, Inaboowwaniifi fuduraalee hunda irraa isiniif magarsa. Dhugumatti, kana keessa ummata xiinxalaniif mallattootu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 12, 'Halkan, guyyaa, aduufi ji’as isiniif laaffise. Urjiiwwanis ajaja Isaatiin laaffifamoodha. Dhugumatti, kana keessa namoota hubannoo qabaniif mallattooleetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 13, 'Bifti isaanii adda adda ta’ee wantoota dachii keessatti isiniif uumes (isiniif laaffise). Dhugumatti, kana keessa namoota gorfamaniif mallattootu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 14, 'Inni Isa galaana isiniif laaffise akka isa irraa foon haarawa nyaattaniifi faaya ishee uffattanis isa irraa baafattaniif jecha. Dooniwwan isa (galaana) keessa baqaqsituu taatee (kan deemtu) argita. Akka tola isaa irraa barbaaddaniifi akka galateeffattaniif jecha (kana godhe).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 15, 'Gaarreen akka isiniin hin sochooneef dachii keessatti godhe. Laggeeniifi karaalees akka qajeeltaniif (godhe).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 16, 'Mallattoolees (isiniif godhe). Urjiidhaan isaan (karaa) qajeelu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 17, 'Sila Inni (waan hunda) uumu akka isa (waan tokkos) hin uumneetii? Sila isin hin gorfamtanuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 18, 'Tola Rabbii yoo lakkooftan ishee waliin gahuu hin dandeessanu. Dhugumatti, Rabbiin araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 19, 'Rabbiin waan isin gadi qabattaniifi waan ol qabattanis ni beeka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 20, 'Warri isaan Rabbii gaditti gabbaranu homaa hin uumanu. Isaanumtuu ni uumamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 21, '(Isaan) du’aawwan jiraataa hin taaneedha. Yoom akka kaafamaniis hin beekanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 22, 'Dhugumatti gabbaramaan keessan gabbaramaa tokkicha. Isaan Aakhiraatti hin amanne, onneewwan isaanii (tokkichummaa Rabbii) mormituudha; isaan boontota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 23, 'Rabbiin waan isaan dhoksaniifi waan isaan mul’isanis beekaa ta’uutti shakkiin hin jiru. Inni boontota hin jaallatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 24, 'Yeroo “Gooftaan keessan (Muhammad irratti) maal buuse” isaaniin jedhame, “(inni) afoola (ogbarruu) warra duriiti” jedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 25, 'Akka Guyyaa Qiyaamaa guutuu taatee badii isaaniitiifi badii warra beekumsa malee jallisanii irraa baadhatanuuf (kana jedhu). Dhagahaa! Wanti isaan baadhatan waa fokkate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 26, 'Dhugumatti, warri isaan dura turan tooftaa baasaniiru, (adabbiin) Rabbii bu’uura irraan manneen isaaniitti dhufee (ishee diige) Ijoon (gubbaan manaa) gubbaa isaaniitiin isaan irratti kufe. Adabni karaa isaan hin beekneen isaanitti dhufe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 27, 'Sana booda Guyyaa Qiyaamaa isaan salphisa, nijedhaan “Hiriyoonni kiyya kan (dhimma) isaanii keessatti (mu’uminoota) faallessaa turtan eessa jiru?”. Isaan beekumsa kennaman “dhugumatti har’a salphinaafi hamtuun kaafiroota irratti ta’eera” jedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 28, '(Isaan) warra lubbuulee isaanii miidhoo ta’anii maleeykonni isaan ajjeesaniidha. Hamtuu tokkollee kan dalagnu hin turre jechuun ajajamoo ta’uu isaanii (sobaan) ibsu. Lakkisaa dhugumatti, Rabbiin waan isin hojjachaa turtan beekaadha (isaaniin jedhama).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 29, 'Ishee keessatti kan haftan ta’aatii balbala Jahannam seenaa, (isaaniin jedhama). Dhugumatti, teessoon boontotaa waa fokkate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 30, 'Isaan (Rabbiin) sodaataniin “Gooftaan keessan (Muhammad irratti) maal buuse?” jedhame, “Gaarii (buuse)” jedhan. Warra toltuu hojjataniif addunyaa kana keessatti (jiruu) gaariitu jira. Manni Aakhiraa immoo irra caalaadha. Gandi warra (Rabbiin) sodaatanii waa tole!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 31, '(Isheen) Jannata qubsumaati ishee niseenan. jala ishee laggeentu yaa''a. Ishee keessa wanti isaan fedhan isaaniif ta’aadha. Akka kanatti Rabbiin sodaattota (Isaa) mindeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 32, '(Isaan) warra gaggaarii ta’anii maleykonni ruuhii isaanii baaftuudha. nijedhaniin “nageenyi isin irratti haa jiraatu; jannata seenaa waan hojjachaa turtaniin”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 33, 'Sila (kaafiroonni) maleeykonni isaanitti dhufuu yookiin ajajni Gooftaa keetii isaanitti dhufuu malee (waan biraa) ni eeguu? Warri isaaniin duraas akkuma kana dalaganiiru. Rabbiin isaan hin miine. Garuu isaan lubbuulee isaanii kan miidhan turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 34, '(Adabni) hamtuuwwan isaan hojjatanii isaan tuqe. Wanti isaan itti qishinaa turanis isaanitti bu''e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 35, 'Isaan (Rabbitti waan biraa) qindeessan ni jedhan: “odoo Rabbiin fedhee, nutis ta’ee abbootiin keenya Isaa gaditti waan biraa hin gabbarru turre(. Ajaja) Isaatiin alas homaa haraama hin goonu turre.”. Warri isaaniin duraas akkuma kana dalagan. Sila ergamtoota irra (ergaa) ifatti geessuu malee wanti biraa jiraa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 36, 'Dhugumatti, Nuti ummata hunda keessatti ergamaa erginee jirra “Rabbiin gabbaraa; taabota (gabbaruu) irraas fagaadhaa” (jechuun). Isaan irraa nama Rabbiin isa qajeelchetu jira. Ammas isaan irraa nama jallinni isa irratti mirkanaa’etu jira. Dachii keessa deemaatii booddeen sobsiiftotaa akkam akka ta’e ilaalaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 37, 'Yoo qajeeluma isaanii irratti bololtes (qajeelchuu hin dandeessu). Dhugumatti Rabbiin namoota jallisu hin qajeelchu; tumsitoonni isaaniif hin jiran.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 38, 'Kakaa isaanii kan daangaa gahe “Rabbiin nama du’e hin kaasu” jechuun Rabbiin kakatan. Lakkisaa (isin kaasaa); Waadaa isa irratti dhugaa ta’e (Rabbiin seeneera). Garuu irra hedduun namaa hin beekanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 39, '(Sababni du’a irraa isaan kaasuuf) akka waan isaan isa keessatti wal dhaban isaaniif ibsuufi akka warri kafaran kijiboota ta’uu isaanii beekaniifi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 40, 'Wanta kamillee (ta’uu) isaa yoo feene, jechi keenya isaan ‘ta’i’ (jechuu) qofa. Achumaan ta’a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 41, 'Isaan erga miidhamanii booda (karaa) Rabbii keessatti godaanan, dhugumatti addunyaa keessatti (qubannaa) gaarii ta’e isaan qubsiifna. mindaa Aakhiraatu irra guddaadha Odoo kan beekan ta’anii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 42, '(Isaan) warra obsanii, Gooftaa isaanii (qofa) irratti hirkataniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 43, 'Nuti si dura dhiirota wahyii gara isaaniitti goone malee (waan biraa) hin ergine. Yoo kan hin beekne taatan, abbootii beekumsaa gaafadhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 44, 'Mallattoolee ifa ta’aniifi kitaabotaan (isaan ergine).Qur’aana gara keetti buufne. Akka namootaaf waan gara isaaniitti buufame ibsituufi akka isaan xiinxalaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 45, 'Sila isaan tooftaa badaa baasan hin sodaatanuu? ‘Rabbiin dachii isaaniin gadi kutuu yookiin iddoo isaan hin beekne irraa adabbiin isaanitti dhufuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 46, 'Yookiin deddeebi’uu isaanii keessatti (Rabbiin) isaan qabuu (hin sodaatanuu)? Isaan dadhabsiisoo hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 47, 'Yookiin sodaa (isaanii) irratti (Rabbiin) isaan qabuu (hin sodaatanuu)? Dhugumatti Gooftaan keessan mararfataa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 48, 'Sila wantoota irraa gara waan Rabbiin uumee hin ilaalanii? kan gaaddisoonni isaa gara mirgaafi bitaawwanitti dabu xiqqaatoo ta’anii Rabbiif sujuudan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 49, 'Rabbiif sujuuda godhu Wanti samiilee keessa jiraniifi Wanti dachii keessa jiran, Lubbu qabeeyyii irraafii maleeykonnis. Isaan hin boonanus.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 50, 'Gubbaa isaanii irratti Gooftaa isaanii sodaatu; waan itti ajajamaniis ni dalagu.[1]', '[1] asitti sujuuda qaraatii qur''aanaa (sujuudu ttilaawaa) sujuuduu barbaachisa. kuni nama qara''uufii kan dhaggeefatuufis, salaata keessaafii salaataan alas barbaachisaadha.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 51, 'Rabbiin nijedhe “gabbaramoota lama hin godhatinaa, Dhugumatti, Inni Gooftaa tokko qofa. Anuma qofa sodaadhaa”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 52, 'Wantoonni samiifiileefii dachii keessa jiran hundi kan Isaati. Amantiinis walitti fufaa ta’ee kan Isaati. Sila waan Rabbiin ala jiru sodaattuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 53, 'Ni’imaa irraa wanti isin bira jiru Rabbuma irraayyi. Ergasii yeroo miidhaan isin tuqe, garuma Isaatti waywaattu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 54, 'Ergasii yeroo Inni miidhaa san isin irraa kaasu, yeroma san gareen isin irraa ta’e Gooftaa isaaniitti (wanta biraa) qindeessu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 55, 'Waan Nuti isaaniif kenninetti kafaruuf (Isatti qindeessu). Qanani’aa; fuula dura (waan isin mudatu) ni beektuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 56, 'Waan Nuti isaaniif kennine irraa waan hin beekneef qooda taasisu. Rabbitti kakadhee! waan (sobaan) odeessaa turtan irraa ni gaafatamtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 57, '(Maleykaa irraa) Rabbiif shamarran taasisu. Qulqullina isaa (qulqullaa’e), Isaaniif immoo waan fedhan (dhiirota) taasisu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 58, 'Tokkoon isaanii yeroo dubaraan gammachiifame,fuulli isaa gurraacha ta’a, haala gaddaan kan guutame ta’een .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 59, 'Namoota irraa dhokata Fokkina waan ittiin gammachiifamee irraa “Sila salphina irratti ishee qabata moo? biyyee keessatti ishee awwaala?” (jechuun kan dhama’e ta’ee). Dhagahaa! Wanti isaan murteessan waa fokkate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 60, 'Isaan Aakhiraatti hin amanneef fakkii fokkataatu jira. Rabbiif immoo sifaata ol ta’aatu jira. Inni injifataa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 61, 'Odoo Rabbiin namoota miidhaa isaaniitiin qabee, silaa dugda ishee (dachii) irratti lubbuu qabeeyyii tokkoyyuu hin dhiisu ture. Garuu hanga beellama murtaa’eetti isaan tursiisa. Yeroo beellamni isaanii ga’e, sa’aatii tokkollee hin tursiifamanu; duras hin bu’anu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 62, 'Waan ofii jibban Rabbiif taasisu Arraboonni isaanii kijiba dubbatti,“Toltuun (Jannanni) isaaniifi” (jechuun).akka Ibiddi isaaniif ta’e shakkiin hin jiru. isaan (gara ishee) jalqaba oofamoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 63, 'Rabbitti kakadhee! Dhugumatti, Nuti gara ummatoota si duraa (ergamtoota) erginee jirra. Sheyxaanni dalagaalee isaanii isaaniif miidhagsee jira. Inni (sheyxaanni) har’a jaalallee (gargaaraa) isaaniiti. Isaaniif adabbii laalessaa ta’etu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 64, 'Nuti kitaaba sirratti hin buufne akka waan isaan isa keessatti wal dhaban isaaniif ibsituuf malee. (inni) qajeelumaafi rahmata ummata amananiif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 65, 'Rabbiin samii irraa bishaan buusee, dachiis erga isheen duute booda isaan jiraachise. Dhugumatti kana keessa ummata dhaga’aniif mallattootu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 66, 'Dhugumatti beeylladoota keessas xiinxalatu isiniif jira, Waan garaalee isaa keessa jiru irraa cumaafi dhiiga gidduu aannan qulqulluu isin obaafna, kan dhugdootaaf gadi liqimfamaa ta’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 67, 'Firiilee mukkeen Tamiriitiifi Inabaa irraa dhugaatii macheessuufi soorata gaggaarii godhattu. Dhugumatti kana keessa namoota hubannoo qabaniif mallattootu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 68, 'Gooftaan kee gara kanniisaatti beeksisa godhe “gaarreen, mukaafi waan isaan ijaaran irraa mana godhadhu” (jechuun).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 69, '“Ergasii firiilee hunda irraa nyaadhuu, karaalee Gooftaa keetii seeni laafaa haala ta’een.” Garaalee ishee irraa dhugaatii bifti isaa gara gara ta’eetu (daymaatu) baha, kan isa keessa namaaf fayyaan (dawaan) jiru. Dhugumatti kana keessa namoota xiinxalaniif mallatootu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 70, 'Rabbiin isin uume, Ergasii isin ajjeesa, Isin irraas nama gara umrii gadi aanaa (dullumaa) deebifamutu jira, Beekumsa booda akka homaa hin beekneef, Rabbiin beekaa, danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 71, 'Rabbiin hiree keessatti garii keessan garii irra caalchiseera. Isaan caalchifaman qabeenya isaanii gara waan (gabroota) harki isaanii dhuunfattee deebisanii isaanis isa keessati kan wal qixxaatanu hin taane. Sila qananii Rabbii mormuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 72, 'Rabbiin lubbuulee keessan irraas niitiiwwan isiniif godhe. jaartiiwwan keessan irraa ilmaaniifi ilmaan ilmaaniis isiniif godhe. gaggaariiwwan irraa isin soore. Sila isaan sobatti amananii tola Rabbiitti kafaruu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 73, 'Rabbiin gaditti wantoota samiifi dachii irraa soorata isaaniif hin kennineefi (waan tokko) hin dandeenye gabbaru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 74, 'Rabbiif fakkeenyota hin godhinaa. Rabbiin ni beeka; isin hin beektanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 75, 'Rabbiin gabricha horatamaa, kan homaa irratti dandeettii hin qabneefi nama Nuti nu biraa soorata gaarii isaaf kennine, inni isa irraa dhoksaafi ifattis kan arjoomu (isaafi wantoota isaan alaatiif) fakkeenya taasiseera. Sila isaan wal qixa ta’uu? Faaruun kan Rabbiiti. Dhugumatti irra hedduun isaanii hin beekanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 76, 'Rabbiin namoota lama (mu’uminootaafi kaafirootaaf) fakkeenya taasiseera: tokkoon isaan lamaanii arraba hidhamaadha; homaa irratti dandeettii hin qabu; inni mootii isaa irratti ba’aadha; bakkuma inni isa erge hunda irraayyuu waan gaariin hin dhufu. Sila inniifi namni karaa qajeelaa irra jiraatee haqatti ajaju, wal qixa ta’aa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 77, 'Iccitiin fagoo samiileefi dachii (hunduu) kan Rabbiiti. Waa’een Qiyaamaa akka libsuu ijaa malee hin taane; yookiin inni isa irra dhihoodha. Dhugumatti, Rabbiin waan hunda irratti danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 78, 'Rabbiin isinii homaa hin beekne garaalee haawwan keessanii irraa isin baase. dhageettii, argituuleefi onneewwan isiniif godhe. Akka galateeffattaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 79, 'Sila gara allaattii hin ilaallee? hawaa samii keessa (kufuu irraa) Rabbiin malee wanti biraa kan ishee hin qabne taatee (bararuuf) laaffifamtuu taatee. Dhugumatti, kana keessa namoota amananiif mallattooleetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 80, 'Rabbiin manneen keessan irraa iddoo teessumaa isiniif godhe. Gogaa beyladaa irraa manneen guyyaa imala deemtaniifi guyyaa dhaabbannaa keessaniis salphifattan isiniif taasiseera. suufa hoolaa, rifeensa gaalaafi rifeensa re’ee irraa meeshaafi faa’idaalee hanga yerootiif (isiniif godheera).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 81, 'Rabbiin wantoota uume irraa gaaddisawwan isiniif godhe. Gaarreen irraas iddoo dhokannaa (isinii godhe). Uffatawwan ho’aa (fi qorra) isin irraa dhorgitus isiniif godhe; uffatawwan balaa waraanaa irraa isin tiksitus, akka kanatti (Rabbiin) tola Isaa isin irratti guuta Akka isin (isaaf) ajajamtaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 82, 'Yoo (haqa irraa) garagalaniif, dhugumatti wanti sirra jiru (ergaa) qaqqabsiisuu ifa ta’e qofa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 83, 'Tola Rabbii ni beeku Ergasii ishee mormu, Ira hedduun isaanii kaafiroota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 84, 'Guyyaa ummata hunda irraa ragaa kaafnu [yaadadhaa]. Sana booda isaan kafaraniif (akka haasa’an) hayyamamu, (Komii dhiifama qabus) hin komatamanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 85, 'Isaan miidhaa dalagan yeroo azaaba argan, isaan irraa hin salphifamu; Yeroonis isaaniif hin kennamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 86, 'Isaan (Rabbitti waan biraa) qindeessan yeroo qindoolee isaanii argan nijedhan “Gooftaa keenya! Isaan kun qidoolee keenya warra nuti siin ala kadhachaa turreedha”. (Gabbaramtoonnis) “dhugumatti isin kijiboodha” (jedhuun) jecha gara isaanii darbatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 87, 'Isaan guyyaa san ajajamoo ta’uu gara Rabbiitti dhiyeessu. Wanti isaan sobaan uumaa turanis isaan irraa bade.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 88, 'Isaan kafaranii karaa Rabbii irraas (namoota) deebisan, adabbii irratti adabbii isaaniif daballa. waan isaan balleessaa turaniif jecha,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 89, 'Guyyaa Nuti ummata hunda keessatti lubbuma isaanii irraa ragaa isaan irratti baafnuufi sis (yaa Muhammad SAW) isaan kana irratti ragaa goonee si fidnu [yaadadhu]. Kitaaba (Qur’aana) sirratti buufne, Waan hunda addeessuuf jecha, Muslimootaaf qajeeluma, rahmataafi gammachuu goonee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 90, 'Dhugumatti, Rabbiin haqatti, toltuu hojjachuufi firootaaf (gargaarsa) kennuutti ajaja. Wantoota fokkatoo, waan jibbamaadhaafi miidhaa irraas ni dhorga. Akka gorfamtaniif jechas isin gorsa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 91, 'Yeroo waadaa seentan waadaa Rabbii guutaa. Kakuu eega ishee jabeessitanii booda hin diiginaa dhugumatti Rabbiin kan ragaa of irratti gootan taatanii. Dhugumatti Rabbiin waan isin hojjattan ni beekaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 92, 'Akka ishee jibrii ishee erga footee jabeessitee booda diiginsa diigdee hin ta’inaa, kakuu keessan gidduu keessanitti (wal ganuuf) seensa hingodhatinaa, Ummanni tokko ummata biraa irra sababa baay’achuutiin. Rabbiin kanaan isin qormaatuuf (kana godhe). Guyyaa Qiyaamaas waan isa keessatti wal dhabaa turtan dhugumatti isiniif addeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 93, 'Rabbiin odoo fedhee ummata tokko isin taasisa ture. Garuu nama fedhe ni jallisa; nama fedhes ni qajeelcha. Waan dalagaa turtan irraa dhugumatti ni gaafatamtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 94, 'Kakuu keessan gidduu keessanitti (wal ganuuf) seensa hin godhatinaa. Faanti erga lafa qabattee booda akka hin mucucaanneef. sababaa karaa Rabbii irraa (namoota) deebiftaniif hamtuu akka hin dhandhamneef. (Oggas) isiniif adabbii guddaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 95, 'Waadaa Rabbii maallaqa xiqqaatti hin gurguratinaa. dhugumatti, wanti Rabbiin bira jiru, isatu isiniif caalaadha. Yoo kan beektan taatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 96, 'Wanti isin biraa ni dhuma, Wanti Rabbiin biraa immoo hafaadha. Isaan obsaniif mindaa isaanii irra gaarii waan isaan dalagaa turaniitiin isaan mindeessina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 97, 'Dhiiras ta’ee dubartii irraa nama mu’umina ta’ee dalagaa gaarii hojjate, dhugumatti jireenya gaarii isa jiraachifna; mindaa isaaniis irra gaarii waan isaan dalagaa turaniitiin isaan mindeessina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 98, 'Yeroo Qur’aana qaraatu sheyxaana darbatamaa irraa Rabbitti maganfadhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 99, 'Dhugumatti, inni warra amananii Gooftaa isaanii irratti hirkatan irratti aangoon isaaf hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 100, 'Aangoon isaa warruma jaalalloo isa godhataniifi warra Isatti qindeessoo ta’an (qofa) irratti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 101, 'Yeroo keeyyata tokko bakka keeyyata biraa jijjiirre, Rabbiin waan buusu akkan beekaadha; “Ati (yaa Muhammad!) soba of biraa uumaa malee kan biraa miti” jedhu. Dhugumatti irra baay’een isaanii hin beekanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 102, 'Jedhi ruuhul qudus (Jibriil) Gooftaa kee irraa dhugaan isa (Qur''aana) buuse, Akka warra amanan (haqa irra) gadi dhaabuuf, Muslimootaaf qajeelumaafi gammachuu ta’ee (buuse).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 103, 'Nuti dhugumatti “kan (Qur’aana) isa barsiisu nama malee waan biraa miti” jechuu isaanii ni beekna. Qooqni inni isaan gara isaatti jallisanii ‘Ajamii’dha, (Qur’aanni) kun immoo qooqa Arabiffaa ifa bahaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 104, 'Dhugumatti isaan keeyyattoota Rabbiitti hin amanne, Rabbiin isaan hin qajeelchu; isaaniifis adabbii laalessaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 105, 'Dhugumatti kan kijiba uumu isaan keeyyattoota Rabbiitti hin amanne qofa. Warri sun isaanumatu kijibdoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 106, 'Namni eega amanuu isaatii Rabbitti kafare (Adaba laalessaatu isaaf jira), Nama odoo qalbiin isaa Iimaana irratti ragga’ee jiruu (kufriitti) dirqisiifame malee, Garuu namni qoma isaa kufriif bal’ise dallansuu Rabbi irraa ta’etu isaan irra jira; Isaaniif adabbii guddaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 107, 'Kun waan isaan jireenya addunyaa Aakhiraa caalaa jaalataniifi Rabbiin ummata kaafirootaa hinqajeelchu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 108, 'Isaan warra Rabbiin onneewwan isaanii, dhageettii isaaniifi agartuuwwan isaanii irratti cufeedha. Isaan sun isaanumatu dagattoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 109, 'Shakkiin hin jiru isaan Aakhiraatti isaanumatu hoonga’oota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 110, 'Ergasii Gooftaan kee isaan erga rakkifamanii booda godaananii, ergasii qabsaa’anii, obsaniif (araaramaa, rahmata godhaa dha); dhugumatti Gooftaan kee booda isheetii (rakkifamuutii) araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 111, 'Guyyaa lubbuun hundi kan ofirraa mormitu taatee dhuftuufi, kan lubbuun hundi waan dalagdeen mindeeffamtu [yaadadhu]. Isaan hin miidhaman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 112, 'Rabbiin magaalattii nagaa tasgabbooftuu turte,(nama tola isaatti kafareef) fakkeenya taasise. kan sooranni ishee iddoo hunda irraa baay’inaan isheetti dhufu, kan qananiilee Rabbiitti kafartee. Rabbiin waan isaan hojjachaa turaniin uffata beelaafi sodaa ishee dhandhamsiise.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 113, 'Dhugumatti ergamaan isaan irraa ta’e isaanitti dhufee, isas sobsiisani; odoo isaan miidhaa hojjatoota ta’anii jiranuu adabbiin isaan qabate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 114, 'Waan Rabbiin isiniif kenne irraa nyaadhaa. Hayyamamaa, gaarii haala ta’een. tola Rabbii kan isinirratti tahe galateeffadhaa Yoo kan Isa gabbartan taatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 115, 'Wanti (Rabbiin) isin irratti haraama (dhorgamaa) godhe baktii, dhiiga, foon booyyeetiifi waan wantoota Rabbiin alaatiif (yeroo gorra''an) sagaleen irratti olfuudhameedha. Namni rakkifame fincilaa tahuun maletti daangaa dabruun maletti (yoo nyaate)(badiin isarra hin jiru). Rabbiin araaramaa, rahmata godhaadha', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 116, 'waan arrabni keessan kijiba dubbatuun “kun hayyamamaadha; kun immoo dhorgamaadha” hin jedhinaa.Rabbirratti kijiba uumuuf jettanii, Dhugumatti isaan Rabbirratti soba odeessan hin milkaa’anu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 117, '(Isaaniif) qananii xiqqootu jira. (Aakhiraatti immoo) isaaniif adabbii laalessaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 118, 'Isaan yahuudota ta’an irratti waan kana dura sirratti odeessine dhorgaa taasifnee jirra. Nuti waa isaan hin miinee, garuu isaan lubbuulee isaanii kan miidhan turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 119, 'San booda Gooftaan kee isaan wallaalumaan hamtuu dalaganii sana booda tawbatanii (hojii isaanii) tolchan, dhugumatti Gooftaan kee ishee booda araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 120, 'Dhugumatti Ibraahiim ogganaa Rabbiif ajajamaa, qajeelaa ture. Mushrikoota irraa hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 121, 'Tolawwan Isaatiif galatoomfataa ture. (Rabbiin) isa filatee gara karaa sirrii isa qajeelche.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 122, 'Addunyaa keessatti toltuu isaaf kenninee jirra. Dhugumatti inni Aakhiraa keessattis gaggaarii irraayyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 123, 'Ergasii “karaa Ibraahiim qajeelaa ta’e hordofi” (jechuun) beeksisa gara keetti goone. Inni (Ibraahiim) mushrikoota irraa hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 124, 'Sanbatni (dhorgaa) kan godhame warruma isa keessatti wal dhaban qofa irratti. Dhugumatti Gooftaan kee guyyaa qiyaamaa waan isaan isa keessatti wal dhabaa turan keessatti gidduu isaanitti nimurteessa..', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 125, 'Gara karaa Gooftaa keetii ogummaafi gorsa bareedaan waami, Ishee (falmii) irra gaarii taateen isaan falmi, Dhugumatti Gooftaan kee nama karaa Isaa irraa jallate ni beekaa. Inni qajeeltotas beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 126, 'Yoo haaloo bahattan fakkaatuma waan miidhamtaniitiin bahadhaa. Yoo obsitan immoo obsitootaaf isatu caalaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 127, 'Obsi; obsuun kee (si dandeessisuu) Rabbiitiin malee hin taane, Isaan irratti hin gaddin, Tooftaa isaan baasan irraa dhiphina keessatti hin ta’in.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 128, 'Dhugumatti, Rabbiin warra Isa sodaataniifi warra isaan tolchitoota tahan wajjin jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 1, 'Inni gabricha Isaa halkan masjida kabajamaa (Makkaa) irraa gara masjida fagoo, kan moggaa (naannoo) isaa barakaa gooneetti deemsise qulqullaa’e, mallattoowwan keenya irraa akka itti argisiifnuuf, Dhugumatti, Inni Isumatu dhaga’aa, argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 2, 'Muusaaf kitaaba kenninee Ilmaan Israa’iilif qajeelfama isa goone “anaa gaditti hirkoo hin godhatinaa”(jechuun).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 3, '(Yaa) sanyii namoota Nuuh wajjin (doonii) yaabbachiifne! Dhugumatti, inni gabricha galatoomfataa ture.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 4, 'Gara Ilmaan Israa’iil kitaaba keessatti beeksisa goonee jirra “dhugumatti isin dachii keessatti yeroo lama badii dalagdu; of tuulummaa guddaa of tuuluuf jirtu” (jechuun).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 5, 'Isaan lamaan irraa waadaan jalqabaa yeroo dhufe, gabroota Nuuf ta’an kan lolatti cimaa isin irratti ergine. Isaan manneen keessa ni deddeebi’an (nisakatta''an). (Waadichis) waadaa raawwatamaa ta’eera', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 6, 'Ergasii isaan irratti dabaree injifannoo isiniif deebifnee, qabeenyaaleefi ilmaanis isiniif daballe, Gama gosaatiinis baay’ee isin taasifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 7, 'Yoo toltuu hojjattan lubbuma keessaniif toltuu hojjattu. Yoo hamtuu hojjattan isuma irratti. Yeroo waadaan lamaffaa dhufe, akka (diinotiin keessan) fuuleen keessan hammeessan, akka masjiidicha (Aqsaa) akkuma yeroo duraa isa seenanitti seenaniifi, akka waan irratti injifatan barbadeessuu barbadeessan (isin irratti ergina).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 8, 'Gooftaan keessan rahmata isiniif gochuun ni kajeelama. Yoo isin (badiitti) deebitan, Nutis (isin adabuutti) ni deebina. Jahannamiin kaafirootaaf mana hidhaa taasifnee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 9, 'Dhugumatti, Qur’aanni kun (karaa) ishee irra (haqaafi) qajeeltuu taatetti qajeelcha. Mu’uminoota warra gaggaarii hojjatan dhugumatti mindaan guddaan isaaniif jiraachuudhaan gammachiisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 10, 'Isaan aakhiraatti hin ammanne immoo adabbii laalessaa ta’e isaaniif qopheessinee jirra (jechuun gammachiisa).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 11, 'Ilmi namaa (yeroo aarii) hamtuu akkuma toltuu kadhatutti (Rabbiin) kadhata. Ilmi namaa jarjaraa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 12, 'Halkaniifi guyyaa mallattoo lama taasifnee jirra. Mallattoo halkanii (dukkanaan) haguugnee, mallattoo guyyaa immoo ifa goone, Akka tola Gooftaa keessan irraa ta’e barbaaddaniifi, akka lakkoofsa waggootaafi herregas beektaniif (kana goone). Waan hunda addaan baafnee isa addeessinee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 13, 'Nama hundayyuu hojii isaa morma isaatti rarraafnee jirra, Guyyaa Qiyaamaa kitaaba isaaf baafna. banamaa tahee inni isa argata..', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 14, 'Kitaaba kee dubbisi, Hardha ati mataan kee sirratti herregaa ta’uuf ga’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 15, 'Namni qajeele, kan inni qajeelu lubbuu isaatiifii, Namni jallates, kan inni jallatu ishemarratti, Lubbuun ba’aa baadhattu kamilleen ba’aa lubbuu biraa hin baadhattu, Hanga ergamaa erginutti kan adabnu hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 16, 'Yeroo magaalaa takka balleessuu feene, namoota qanani’oo ishee (akka Rabbiin sodaatan) ajajna. Isaan ishee keessatti ajaja Rabbii didu; kanaaf jechi (adabaa) isaan irratti mirkanaa’a. Ishee barbadeessuu barbadeessine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 17, 'Nuuhiin booda magaalota irraa meeqaatama balleessine! Gooftaan kee ga’aadha Badii gabroota Isaa beekaa argaa ta’uutti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 18, 'Nama (addunyaa) jerjertuu kan fedhu tahe, ishee keessatti nama feeneef waan feene jerjersina. Ergasii (Ibidda) jahannam isaaf goona. isii ni seena arrabsamaa, darbamaa ta’ee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 19, 'Nama Aakhiraa fedhee haala dhugoomsee jiruun hojii ishee isiif hojjate, warra san hojiin isaanii galateeffatamaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 20, 'Hundaayyuu kennina, isaan kanaafi isaan sanas, kennaa Gooftaa keetii irraa (isaaniif kennina). Kennaan Gooftaa keetii dhorgatamaa miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 21, 'Akkamitti garii isaanii garii irra akka caalchifne ilaali. (Haa ta’u malee) Aakhiraatu sadarkaafi caalchisuuttis irra guddoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 22, 'Rabbii wajjin gabbaramaa biraa hin taasisin; (yoo waliin gabbarte) balaaleffatamaa, salphataa taatee teessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 23, 'Gooftaan kee akka isin Isa malee homaa hin gabbarreefi haadhaa abbaa keessanitti tola ooltan murteessee jira. Yoo sibiratti tokkoon isaanii yookiin lamaanuu sadarkaa dullummaa irra ga’an, ish (jecha hifannaafii tuffii) isaaniin hin jedhin. Isaaniin hin lolin. Jecha kabajaa isaaniin jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 24, 'Isaaniif koola (qoochoo) xiqqeenyaa rahmatarraa kantahe isaaniif gadi qabi. “Gooftaa kiyya! Akkuma isaan anaa xiqqaa ta’ee na guddisan Atis rahmata isaaniif godhi” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 25, 'Gooftaan keessan waan lubbuulee keessan keessa jiru akkaan beeka. Yoo namoota gaggaarii taataniif Inni warra akkaan gara Isaatti deebi’aniif araaramaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 26, 'Firaaf,hiyyeeyyiifi kara deemaafis haqa isaa kenni, qisaasuu (bazzaruu) hin qisaasin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 27, 'Dhugumatti, qisaastonni obboleeyyan sheyxaanotaa ta’aniiru. Sheyxaanni Gooftaa isaatti akkaan kafaraa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 28, 'Yoo kennaa Gooftaa kee irraa ta’e kan isii kajeeltu barbaaduuf jecha isaan irraa gara galte, jecha laafaa isaaniin jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 29, 'Harka keeti gara morma keetiitti sakaalamaa hin godhin. Diriirinsa hundas isa hin diriirsin. Komatamaa, sheena’aa taatee teessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 30, 'Dhugumatti Gooftaan kee hiree nama fedheef ni bal’isa; (nama fedhe irratti) ni dhiphisas. Dhugumatti, Inni gabroota Isaa beekaa, argaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 31, 'Ilmaan keessan sodaa hiyyummaatiif jecha hin ajjeesinaa. Isaaniifi isinis Nutu soora. Dhugumatti, isaan ajjeesuun badii guddaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 32, 'Sagaagalummaattis hin dhihaatinaa. Dhugumatti, inni (hojii) fokkataafi ta’ee jira, waa hammaatee karaa tahuun isaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 33, 'Lubbuu Rabbiin (ajjeessuu) haraama godhe haqaan ala hin ajjeesinaa. Nama roorroon ajjeefame nama isa dhaaluuf aangoo (dhiiga gaafachuu isaaf) kenninee jirra. Ajjeechaa keessatti daangaa hin dabrin. Dhugumatti, inni tumsamaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 34, 'Qabeenya yatiimaa, kaayyoo gaariif malee hanga inni cimina isaa ga’utti itti hin dhihaatinaa. Waadaa guutaa. Dhugumatti, waadaan gaafatamaa ta’ee jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 35, 'Yeroo safartanis safara guutaa. Madaala qajeelaa ta’eenis madaalaa. Kun waan gaariidha; booddeen isaas bareedaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 36, 'Waan beekumsa isaa hin qabne hin hordofin. Dhugumatti, dhageettiin argaaniifi onneenis, kun hundinuu isa irraa gaafatamaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 37, 'Dachii keessas boonaa hin deemin. Dhugumatti, ati dachii hin urtu; dheerinnaanis gaarreen hin geessu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 38, 'Kun hundi yakki isaa Gooftaa kee biratti jibbamaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 39, 'Kuni beekumsa irraa waan Gooftaan kee gara keetti wahyii godheedha. Rabbii wajjin gabbaramaa biraa hin taasisin. (Yoos) jahannam keessatti darbamta komatamaa fageeffamaa taatee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 40, 'Sila Gooftaan keessan isiniif ilmaan dhiiraa fileeti ofiif maleeykota irraa ilmaan dubaraa godhatee? Dhugumatti, isin jecha (badii) ulfaataa jettu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 41, 'Dhugumatti, Nuti Qur’aana kana keessatti akka (isaan) gorfamaniif deddeebinee ifa goonee jirra. Baqa malee homaa isaaniif hin dabalu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 42, 'Jedhi: “Odoo akka isaan jedhan Isa waliin gabbaramtoonni biraa jiraatanii, silaa gara abbaa Arshiitti karaa barbaaddatu turan”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 43, 'Inni (Rabbiin) waan isaan jedhan irraa qulqulluufi ol ta’iinsa guddaas ol ta''eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 44, 'Samiin torbaniifi Dachiin, wanni isaan keessa jiran hundi Isa faarsu. Wanti tokkos kan odoo faaruu Isaatiin Isa hin qulqulleessin hafu hin jiru. Garuu isin faaruu isaanii hin beektanu. Inni obsaa, araaramaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 45, 'Yeroo Qur’aana dubbiftu gidduu keetiifi gidduu warra Aakhiraatti hin amannee haguuggii dhokataa taasifna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 46, 'Akka isaan isa (Qur’aana) hin hubannes onneewwan isaanii irratti haguuggii, gurra isaanii keessatti immoo duuchaa goonee jirra. Yeroo Qur’aana keessatti Gooftaa kee kophaa Isaa dubbatte, baqataa dugda galu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 47, 'Nuti waan isaan isa dhageeffataniif ni beekna. yeroo isaan gara kee dhaggeeffatan, yeroo isaan maqoo (iccitii) hasaasan, yeroo miidhaa raawwattoonni jedhan “namticha sihriin tuqame malee waan biraa hin hordoftanu”(nibeeyna).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 48, 'Fakkeenya akkamii akka siif taasisan ilaali. Isaan jallatanii jiru; karaa (sirrii argachuus) hin danda’anu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 49, 'Ni jedhan “sila nuti erga (duunee) lafeefi bututaa (tortoraa) taanee booda uumama haarawa taanee kaafamoo dhaa?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 50, '(Yaa Muhammad!) jedhiin: “Dhagaa yookiin sibiila ta’aa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 51, 'Yookiin uumama qomoowwan keessan keessatti (kaafamuun) guddatus ta’aa. (kaafamuun keessan hin hafu)". Ergasiis “Eenyutu nu deebisa” jedhu“. Isa yeroo jalqabaa isin uumeedha” jedhi. Mataa isaanii sitti raasuuf jiru, Ni jedhus: “Inni sun yoomi ree?” “Dhihoo ta’uun mirkanaa’aadha” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 52, 'Guyyaa Inni isin waamnaan, isin Isa faarsaa owwaattan. yeroo gabaabaa malee turuu dhabuu yaaddan (ta’uun mirkanaa’e).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 53, 'Gabroota kiyyaan jedhi “isitti (jecha) gaggaarii dubbadhaa. sheyxaanni gidduu isaanii balleessa. sheyxaanni ilma namaatiif diina ifa bahaadha”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 54, 'Gooftaan keessan akkaan isin beekaadha. Yoo fedhe rahmata isiniif godha; yookiin yoo fedhe isin adaba. Nuti isaan irratti itti gaafatamaa goonee si hin ergine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 55, 'Gooftaan kee waan samiileefi dachii keessa jiru beekaadha. Nuti dhugumatti garii nabiyyoota garii irra caalchifnee jirra. Daawudiif zabuur kennineerra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 56, 'Jedhiin “Warra Isa (Rabbii) gaditti (gabbaramaadha) jettan san waammadhaa. (Isaan) miidhaa isin irraa fuudhuus ta’ee naannessuu hin danda’an”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 57, 'Warri isaan yaammatan sun gara Rabbii isaaniitti dhiheenya barbaadu.eenyuu isaaniitu gara Rabbiitti irra dhihaataadhaan. [1] Rahmata isaas ni kajeelu. adabbii isaa ni sodaatu. Dhugumatti, adabbiin Rabbii keetii sodaatamaa ta’ee jira.', '[1]Yaanni aayatichaa ‘warri gara Rabbiitti irra dhiheenya qabanuyyuu dhiheenya barbaaduu! Warri biraa immoo sanaa ol Rabbirra barbaaduu qabu!’ jechuudha.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 58, 'Magaalota (kafarte) kamiyyuu Guyyaa Qiyaamaatiin dura ishee balleessinu yookiin adabbii cimaa ishee adabnu malee hin haftu. Sun kitaabicha keessatti barreeffamaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 59, 'Mallattoolee erguu wanti Nu dhorge hinjiru warri duraa ishee kijibsiisuu malee. Samuudiif gaalattii mallattoo ifa galtuu kenninee jirra. Isheetti kafaranii (isii miidhan) (halaakamani). Nuti sodaachisaaf malee mallattooleen hin erginu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 60, 'Yeroo “dhugumatti, Gooftaan kee namootaan marseera” siin jenne [yaadadhu]. Arginsa kee ishee (halkan Israa’ii) si argisiifne san, namoota ittiin mokkoruuf qofa malee waan biraatiif hin goone. Mukattii Qur’aana keessatti abaaramtes (mokkoroof malee hin goone). Nuti isaan sodaachifna; inni jallinna guddaa malee waan biraa isaaniif hin dabalu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 61, 'Yeroo maleeykotaan “Aadamiif sujuuda godhaa” jenne [yaadadhu]. Ibliis malee isaan sujuuda godhan. Inni (Ibliis) “sila ani nama Ati dhoqqee (biyyee) irraa uumteefin sujuuda godhaa?” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 62, '(Ibliis) ni jedhe: “Mee naaf himi! Isa Ati ana caalaa kabajje kana, yoo hanga Guyyaa Qiyaamaatti na tursiifte, sanyii isaa muraasa malee garan jallinaa harkisa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 63, '(Rabbiin) ni jedhe: “Deemi! Namni isaan irraa si hordofe dhugumatti, jahannam galata keessan galata guutamaa ta’eedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 64, 'Isaan irraa nama dandeesses sagalee keetiin kakaasi. Yaabbattoota keetiifi lafoo keetiinis isaan irratti gulufsiisi. Qabeenyaafi ilmaan keessattis isaanitti qindaa’ii. waadaas isaaniif gali. Sheyxaanni gowwoomsuu malee homaa waadaa isaaniif hin galu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 65, 'Dhugumatti, gabroota kiyya, isaan irratti aangoon siif hin jiru. Hirkoo ta’uuf Rabbiin kee ga’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 66, 'Gooftaan keessan Isa doonii galaana keessa isiniif deemsisuudha. akka tola Isaa irraa barbaaddattaniif, Dhugumatti, Inni isiniif rahmata godhaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 67, 'Yeroo rakkoon wahii galaana keessatti isin tuqe, Isa malee wantoonni isin kadhachaa turtan (hundi) ni badu. Yeroma Inni gara dachiitti isin baase (Isa irraa) gara galtan. Namni akkaan kafaraa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 68, 'Sila sodaa dhabdanii? (Rabbiin) cinaa dachii isiniin kutuu, yookiin bubbee cirrachaa isin irratti erguu, ergasii isiniif hirkoo hin argattan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 69, 'Moo sodaa dhabdanii yeroo biraa isa (galaana) keessatti isin deebisee, qilleensarraa hobonboleettii isinitti ergee, bishaaniin isin dhidhimsuu sababa isin kafartaniif. ergasii isaan (adaba sanaan) isiniif Nu irratti hordofaa argachuu dhabuu keessan (hin sodaattanuu?)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 70, 'Dhugumatti, Nuti ilmaan Aadam kabajneerra, Dachiifi galaana keessattis isaan yaabbachiifneerra, Wantoota gaggaarii (halaala) irraas isaaniif hirreera. Irra hedduu wanta uumnee irra caalchisuu isaan caalchifnee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 71, 'Guyyaa nama hunda imaamota isaaniitiin waamnu [yaadadhaa]. Namni galmeen (kitaabni) isaa mirga isaatiin kennameef, warri sun kitaaba isaanii ni dubbisu; hanga qajjiisa (baqaqaa firii timiraa keessaa)llee hin miidhamanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 72, 'Namni (addunyaa) tana keessatti jaamaa (qalbii) ta’e,inni aakhiraa keessattis jaamaadha; karaadhaanis irra jallataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 73, 'Dhugumatti, isaan waan Nuti gara keetti wahyii goone irraa si jallisuutti dhiyaatanii turan. akka ati soba isaan ala ta’e Nu irratti uumtuuf jecha. Oggas jaalallee si taasifatu ture.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 74, 'Odoo Nuti gadi si dhaabuu baannee, silaa ati waan xiqqoo gara isaanii dabuutti dhihaattee turte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 75, 'Oggas Nuti (adabbii) dachaa kan jireenyaatiifi (adabbii) dachaa du’aa si dhandhamsiifna ture. Ergasii ati Nurraa tumsaa hin argattu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 76, 'Dhugumatti, isaan dachii keessatti si shororkeessuutti dhihaatanii jiru akka ishee irraa si baasaniif, Yoos, si booda xiqqoo malee hin turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 77, 'Karaa ergamtoota keenya kan sidura erginee (karaa siif goone).Karaa keenyaaf jijjiirama hin argitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 78, 'Aduun dabuu irraa hanga dukkana halkaniitti salaata (ulaagaa ishee guutii) gadi dhaabi. qur''aana (Salaata fajriis) (sagadi). qur''aanni (Salaanni) fajrii (maleykaadhaan) dhufamaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 79, 'Halkan irraa isaan (Qur’aanaan) haala (salaata) dabalataa siif taateen sagadi. Gooftaan kee iddoo faarfamaa ta’e si dhaabuun mirkanaa’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 80, 'Jedhis: “(yaa) Gooftaa kiyya! Seensa gaarii naseensisi, Ba’iinsa gaariis na baasi, Si biraa ragaa na gargaaru naaf taasisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 81, 'Jedhi “Dhugaan dhufe; sobni dhabame, sobni dhabamaa ta’eera”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 82, 'Nuti Qur’aana irraa nibuufna waan inni qorichaafi rahmata mu’uminootaaf ta’e. zaalimtootaaf hoongoo malee hindabalu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 83, 'Yeroo ilma namaa ni’imaa keenyaan qanansiifne, garagaleeti cinaa isaatiin (dhugaa) irraa fagaata. Yeroo hamtuun isa tuqe abdii murataa ta’a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 84, 'Jedhi: “Hunduu karaa isatti fakkaateen dalaga. Gooftaan kee nama karaan isaatti qajeelaa ta’e beekaadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 85, 'Ruuhii irraa si gaafatu, jedhi “Ruuhiin amrii gooftaa kiyyaati. Beekumsa irraa waan xiqqoo malee isin hin kennamne”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 86, 'Odoo feenee isa gara keetti wahyii goone ni deemsifna turre. Ergasii siif Nurraa isa (deebisu) itti gaafatamaa hin argattu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 87, 'Garuu rahmata Gooftaa kee irraa ta’eef (isa eegne), tolli Isaa si irratti guddaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 88, 'Jedhi: “odoo ilmi namaatiifi jinnoonnis fakkaataa Qur’aana kanaatiin dhufuu irratti walitti qabamanii, fakkaataa isaatiin hin dhufan odoo gariin isaanii gariif gargaaraa ta’aniis”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 89, 'Dhugumatti, Nuti Qur’aana kana keessatti fakkeenyota hunda irraa namootaaf addeessinee jirra. Irra hedduun namootaa kafaruu malee didan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 90, 'Ni jedhan: “Hanga burqituu dachii keessaa nuuf maddisiiftutti siif hin amannu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 91, 'Yookiin (hanga) oyruu muka timiraatiifi Inabaa irraa siif tahutti, ergasii isa keessa laggeen yaasiinsa yaaftutti (hin amannu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 92, 'Yookiin (hanga) akka jettetti cittuu samii irraa taate nu irratti buuftutti, yookiin (hanga) Rabbiifi maleeykota fuuldura keenya fiddutti (hin amannu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 93, 'Yookiin (hanga) manni faaya warqee irraa ta’e siif ta’utti yookiin (hanga) samii keessa ol korttutti; ol ba’iinsa keettis hanga kitaaba dubbifnu nurratti buuftutti hin amannu”. (jedhu)“Gooftaan kiyya qulqullaa’ee jira. Sila ani nama ergamaa (Rabbii) ta’ee ergame malee waan biraa nintahee?” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 94, 'Ilma namaa amanuu waa hindhoowwine yeroo qajeelfamni (Rabbii) isaanitti dhufe, jechuu isaanii malee “sila Rabbiin nama ergamaa taasisee ergaa?”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 95, '“Odoo dachii keessa maleykonni tasgabbaa’anii deeman kan jiraatan ta’ee, silaa maleykaa samii irraa ergamaa taasifnee isaan irratti buufna turre” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 96, '“Gidduu kiyyaafi gidduu keessanitti ragaaf Rabbiin ga’aadha, Dhugumatti, Inni gabroota Isaa beekaa, argaa ta’eera” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 97, 'Namni Rabbiin qajeelche, isumatu qajeelaadha, Nama Inni jallise, isaaniif Isaa gaditti gargaartota hin argituuf, Guyyaa Qiyaamaas fuulleen isaanii irratti, jaamaa, arrabaa qabamaafi gurraa duudaa ta’anii isaan kaafna.Teessoon isaanii jahannami, Dhawaata isiin gadi laaftuun gubaa isaaniif daballa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 98, 'kun mindaa isaaniiti. Waan isaan keeyyattoota keenyatti kafaraniif. nijedhan “sila yeroo lafeefi biyyee taane, nuti uumama haara’a taanee kaafamoodhaa?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 99, 'Sila isaan hin ilaallee (hinbeeynee) akka Rabbiin inni samiifi dachii uume fakkaataa isaanii uumuu irratti danda’aa ta’ee. beellama isa keessa shakkiin hin jirre isaaniif taasise. Miidhaa dalagdoonni (Rabbitti) kafaruu malee ni didan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 100, 'Jedhi: “odoo isin dilbii rahmata Gooftaa kiyyaa dhuunfattanii, yoggus silaa dhumuu sodaaf (of biratti) qabattu turtan.” Ilmi namaa akkaan don’a ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 101, 'Dhugumatti, Muusaaf mallattoolee ifa ta’an sagal kennineefii jirra. Ilmaan Israa’iil gaafadhu yeroo inni isaanitti dhufe Fir’awni “yaa Muusaa! Ani dhugumatti sihriin qabamaa ta’uun si yaada” isaan jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 102, '(Muusaanis) ni jedhe: “Ati dhugumatti isaan kana haala ragaa ifa ba’aa ta’aniin Gooftaa samiileefii dachii malee homtuu hin buusin sirritti beektee jirta. Ani yaa Fir’awn! Dhugumatti, ati halaakamaa ta’uun si yaada.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 103, 'Dachii (Misraa) irraa isaan baasuu fedhe. Isaafi namoota isa waliin turan hunda bishaan isaan nyaachifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 104, 'Nutis isa booda ilmaan Israa’iiliin ni jenne: “dachii keessa jiraadhaa. Yeroo beellamni boodaa (Qiyaamaan) dhufe, haala walitti qabamoo taataniin hunda keessaniin dhufna.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 105, 'Nuti dhugaan isa (Qur’aana) buufne; innis dhugaan bu’e. Gammachiisaafi sodaachisaa goonee malee Nuti si hin ergine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 106, 'Qur’aana akka ati suuta suutaan namoota irratti isa dubbiftuuf isa qoqqoodne; buusiinsas isa buufne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 107, 'Jedhi: “Isatti amanaa yookiinis hin amaninaa; dhugumatti, isaan isa dura beekumsa kennaman, yeroo inni isaan irratti dubbifame fuula isaaniitiin sujuuda bu’u.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 108, 'Ni jedhu: “Gooftaan keenya qulqullaa’eera. Dhugumatti, waadaan Gooftaa keenyaa raawwatamaadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 109, 'Fuula isaanii irratti booyaa sujuuda bu’u. Innis sodaa isaaniif dabala. [1]', '[1] asittis sujuuda qaraatii qur''aanaattu jira.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 110, 'Jedhi: “Allaah kadhaa yookiin Rahmaaniin kadhaa; kamiinuu yoo kadhattan Isaaf maqoota babbareedaa ta’antu jira. Salaata kee keessatti (baay’ee) sagalee kee ol hin fuudhin; (baay’ee) gadis hin qabatin. Giddu (lamaan) sanitti karaa barbaadadhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 111, '”Faaruun hundi kan Rabbii ilma hin godhatiniiti, kan mootummaa keessatti hiriyyaa hin qabneefi kan sababa salphinaa irraa gargaaraan isaaf hin jirreeti” jedhi. Guddisuu Isa guddisi', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 1, 'Faaruun kan Rabbii gabricha Isaa irratti kitaaba buuseeti. kan isa keessatti daba hin godhiniiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 2, 'Qajeelaa (godhee) akka adabbii cimaa Isa biraa ta’e ittiin sodaachisuuf, mu’uminoota gaggaarii hojjatan ‘mindaan bareedaan isaaniif jiraachuudhaan’ gammachiisuuf (buuse).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 3, 'Isa keessa yeroo hunda jiraatoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 4, 'Isaan “Rabbiin ilma qaba” jedhan sodaachisuuf (isa buuse).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 5, 'Isaaniifi abbootii isaaniitiifis isa irratti beekumsi hin jiru. Jechi afaan isaanii irraa baatu waa guddatte! Soba malee homaa hin haasa’anu.[1]', '[1] Wanti aayanni kun itti fedhe yeroo Rabbiin ilmoo qaba jedhanu beekumsas ta’ee ragaa homaatuu hin qabanu; yaaduma isaaniitiin dubbatan jechuudha.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 6, 'Yoo isaan haasa’a kanatti amanuu baatan gaddaan faana isaanii irratti lubbuu kee balleessuutu siif sodaatama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 7, 'Dhugumatti, Nuti waan dachii irra jiru (hunda) isheef miidhagina taasifne, isaan irraa eenyu akka irra tolchee hojjatu mul’isuuf.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 8, 'Dhugumatti, Nuti wantoota ishee (dachii) irra jiran hunda dirree duwwaa biqilaa hin qabne taasisoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 9, 'Sila (seenaan) warra holqaafi gabatee mallattoolee keenya irraa dinqisiisaa ta’uu yaaddee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 10, 'Yeroo dargaggoonni gara godaa galanii “(yaa) Gooftaa keenya! Si biraa rahmata nuuf kenni; dhimma keenya irraas karaa qajeelaa nuuf mijeessi” jedhan (waan ta’e yaadadhu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 11, 'Holqa keessatti waggoota lakkaa’amaniif dhageettii isaanii irratti (hirriba) darbine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 12, 'Ergasii Nuti isaan dammaqsine, kamii gareewwan lamaaniitu dheerina yeroo turanii irra hubataa beekuuf jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 13, 'Nuti oduu isaanii dhugaan siif odeessina, Dhugumatti, isaan dargaggoota Gooftaa isaaniitti amananii, qajeeluma isaaniif daballeedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 14, 'Nuti onneewwan isaanii irratti (iimaana) jabeessinee jirra. yeroo isaan dhaabbatanii “Gooftaan keenya Gooftaa samiileefi dachiiti Nuti Isa malee gabbaramaa biraa hin waammannu. Dhugumatti, (yoo kana raawwanne), haasa’a (kufrii keessa) daangaa dabre dubbanne jirra” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 15, '“Ummanni keenya kun Isaa gaditti gabbaramoota biraa taasifataniiru, Sila Maaliif ragaa ifa ta’e isaan irratti hin fidanne? Nama Rabbi irratti soba uume caalaa namni miidhaa hojjate eenyu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 16, '(Dargaggoonnis ni jedhan): “Yeroo isaaniifi wantoota isaan Rabbiin ala gabbaran irraa fagaattan, gara holqaa galaa, Gooftaan keessan rahmata Isaa irraa isiniif bal’isa. dhimma keessan irraas laafina isiiniif qopheessa”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 17, 'Aduu yeroo baatu holqa isaanii irraa kan gara mirgaatti dabdu argita. Yeroo dhiitu, haala isaan bal’ina isa (goda) irraa ta’e keessa jiraniin gara bitaatti isaan dhiifti. Kun mallattoolee Rabbii irraayi. Namni Rabbiin (isa) qajeelche, isumaatu qajeelaadha. Nama Inni jallise immoo gargaaraa isa qajeelchu isaaf hin argitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 18, 'dammaqoo isaan seeta isaanii rafu. gara Mirgaafi gara bitaatti isaan garagaggalchina, Sareen isaanii dhundhumma isaa lamaan moggaa (holqaatti) diriirsaadha. Odoo isaan argitee dhugumatti, silaa baqannaan isaan irraa garagalta; isaan irraas sodaa guutamta turte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 19, 'Akkuma kana isaan dammaqsine akka gidduu isaanitti wal gaafataniif jecha. Jedhaan isaan irraa ta’e tokko nijedhe “Yeroo hangam (as) turtan?” nijedhan “Guyyaa tokko yookiin garii guyyaa turre”. Ni jedhan: “Yeroo hangam akka (as) turtan Gooftaa keessan (qofatu) beeka, Tokkoo keessan maallaqa teessan tanaan gara magaalaa ergaa. kamii isiittu irra gaarii nyaataatii haalaaluu, soorata isaa irraa isiniif haa fidu. Haa dhokatu; waa’ee keessan nama tokkos akka hin beeksifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 20, 'Isaan yoo isin argan, dhagaan isin tumu yookiin amantii isaaniitti isin deebisu, Yoo san gonkumaa hin milkooftan.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 21, 'Akka kanatti isaan irratti mul’ifne. akka isaan beellamni Rabbii dhugaa ta’uu beekaniifi Qiyaamaa shakkiin ishee keessa hinjiruu (akka beekaniif), yeroo isaan gidduu isaaniitti waa’ee isaanii (warra holqaa) keessatti wal dhaban, Ni jedhan: ijaarsa isaan irratti ijaaraa Gooftaa isaaniitu isaan beekaa,.” Warri dhimma isaanii irratti injifatan immoo nijedhan “Nuti dhugumatti, masjida isaan irratti godhanna”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 22, 'nijedhu “Isaan sadihi afraffaan isaanii saree isaaniiti”. nijedhu “Isaan shani jahaffaan isaanii saree isaaniiti” shalaggii fagootii. nijedhu “Isaan torba saddeettaffaan isaaniis saree isaaniti”. (Yaa Muhammad!) jedhi “Lakkoofsa isaanii Gooftaa kiyyatu beeka, (namoota) muraasa malee isaan hin beeku”. Kanaafuu waa’ee isaanii keessatti hin falmin mormii ifa ta’e malee, Waa’ee isaanii keessatti isaan irraa nama tokkos hin gaafatin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 23, 'Waan tokkonis hinjedhin Ani waan san borun hojjataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 24, '“Yoo Rabbiin fedhe” (jettu) malee, yeroo dagatte Gooftaa kee yaadadhu. Gooftaan kiyya gara karaa kana irra qajeelumatti dhihoo ta’ee na qajeelchuun ni kajeelama” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 25, 'Holqa isaanii keessa waggoota dhibba sadi turanii sagalis dabalatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 26, 'Jedhi Rabbumatu beekaa Hanga isaan turan, (Beekumsi) fagoo kan samiileefi dachii Isumaafi. Akkam arga! Akkam dhagayas! Isaaniif Isa malee gargaaraan hin jiru, Murtii Isaa keessatti tokkollee hin hinqindeessu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 27, 'Waan kitaaba Gooftaa keetii (Qur’aana) irraa gara keetti beeksisa godhame dubbisi, Jechoota Isaatiif jijjiiraan hin jiru. Isa malee iddoo itti dabdan hin argattu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 28, 'Lubbuu kee hidhi isaan Gooftaa isaanii ganamaafi galgala waammatanii wajjiin Fuula Isaa barbaachaaf. ija kee lamaan isaan irra hin qaarsin Miidhagina jireenya addunyaa barbaachaaf. Nama onnee isaa yaadannoo keenya irraa cufnef hin ajajamin. kan fedha lubbuu isaa hordofe, dhimmi isaa daangaa darbaa ta’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 29, 'Jedhi: “Dhugaan Gooftaa keessan irraayi, Namni fedhe haa amanu; namni fedhes haa kafaru, Dhugumatti, Nuti miidhaa hojjattootaaf ibidda dallaan ishee isaanitti marse qopheessinee jirra, Yoo birmachiifatan bishaan akka rajaa (siicoo) zeytii danfeetti fuulleen wadditu isaaniif kennama. Dhugaatichi waa fokkatee! Hirkannaanis akkaan fokkate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 30, 'Warreen amananii, gaggaarii hojjatan, (galata guddaa argatu) Nuti mindaa nama dalagaa tolchee hin balleessinu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 31, 'Warra san isaaniif jannata qubsumaa kan laggeen isaan jala yaatuutu jira. ishee keessatti isaan gumeewwan warqee irraa ta’een miidhagfamu, Uffata magariisa hariira haphiifi furdaa irraa tahanis uffatu, Ishee keessatti sireewwan girdoo qaban irratti hirkatanii (taa’u), Mindaan waa tole! Hirkannaanis waa bareedde!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 32, 'Fakkeenya isaaniif godhi. namoota lama kan tokkoo isaaniittiif oyruu lama tan inaboota irraa taate taasifnee, isaan lamaanuu muka timiraatiin marsinee, gidduu isaaniittis midhaan (facaafamu) taasifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 33, 'Oyruun sun lamaanuu firii isii odoo homaa isarraa hin hirdhisin kennite; gidduu isaaniitii laga maddisiifne (san fakkeenya godhiif)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 34, 'Isaaf midhaan godhatee hiriyaa isaatiin odoo itti haasa’uu nijedhe “Anatu qabeenyaan sirra hedduudha, gosaanis sirra jabaadha”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 35, 'Haala lubbuu isaa miidhaa ta’een oyruu isaa seenee ni jedhe: “Isiin kun gonkumaa ni baddii hin yaadu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 36, 'Qiyaamaanis ni dhaabbattii hin yaadu, Dhugumatti, yoon gara Gooftaa kiyyaa deebifameef, iddoo deebii kan isa caaluun argadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 37, 'Hiriyyaan isaas kan isaan haasa’u ta’ee ni jedhe: “Sila ati Isa biyyee irraa si uumetti kafartee?, ergasii bishaan saalaa irraa, ergasii nama guutuu si godhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 38, 'Ani garuu Inni, Allaah’n Gooftaa kiyya; ani Gooftaa kiyyatti tokkollee hin qindeessu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 39, 'Maaliif Yeroo oyruu tee seentu “waan Rabbiin fedhetu (ta’a); Rabbiin malee humni (naaf) hin jiru” jechuu dhiifte!, Yoo ana qabeenyaafii ilmaaniiniis sirra xiqqaa ta’uu na agartes;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 40, 'Gooftaan kiyya waan oyruu kee irra caalu naaf kennuun nikajeelama, ishee (kee) irratti immoo samii irraa bakakkaa buusee, dirree duwwaa ta’uun ishee (ni mala).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 41, 'Yookiin bishaan ishee gadi lixaa tahee ati isa barbaaduu dadhabuun (ni mala).”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 42, 'Midhaan isaattis ni marfame (ni bade), waan isii keessatti baaserratti ganaa (shanacha) isaa lamaan gara gaggalchutti seene. isheen mogoleewwan (jirma) ishee irratti kukkufte, nijedhe “yaa gaabbii koo! Odoon Gooftaa kiyyatti waa tokko qindeessuu baadhee”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 43, 'Gareen Rabbii gaditti isa tumsitus isaaf hin jirtu. Inni tumsamaa hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 44, 'Achittii (Qiyaamaa) mootummaan kan Rabbii haqa ta’eeti, Inni mindeessuutti Isumatu caala; booddee tolchuttis Isumatu caalaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 45, 'Fakkeenya jiruu addunyaa isaaniif godhi, (sun) akka bishaan samii irraa buufnee, biqiltuuwwan dachii isaan walitti makamanii, goggogaa caccabaa bubbeewwan isa faffacaaftu ta’e. Rabbiin waan hunda irratti danda’aa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 46, 'Qabeenyiifi ilmaan faaya jirreenya addunyaati, Gaggaarii haftuu taatetu Gooftaa kee biratti mindaadhaan irra caala; gama abdiittis irra caalaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 47, 'Guyyaa Nuti gaarreen deemsifnee dachii dirree ta’uu argitee, isaan walitti qabnu [yaadadhu]. Isaan irraas tokkollee hin hanbifnu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 48, 'Hiriiroo tahanii Gooftaa kee irra fidaman; “dhugumatti, akka yeroo jalqabaa isin uumnetti nutti dhuftan, Nuti waadaa isiniif godhuu dhabuu yaaddu turtan” (jedhaman).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 49, 'kitaabni kaa’amee, badii raawwattoota waan isa keessa jiru irraa sodaatoo ta’anii isaan agarta. Ni jedhus: “Yaa badii keenya! Kitaabni kun maaltu isaaf tahe kan xiqqoofi guddoos ishee walitti qabu malee hin dhiifne.” Waan hojjatan dhiyaataa ta’ee argu. Gooftaan kee tokkollee hin miidhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 50, 'Yeroo maleeykotaan “Aadamiif sujuuda godhaa” jenne [yaadadhu], Ibliis malee sujuuda godhan, (inni) jinnii irraa ta’ee ajaja Gooftaa isaa irraa fincile. Sila Ana dhiiftanii isaafi sanyii isaa jaalallee godhattuu? isaan isiniif diinoota. (Ibliis) miidhaa raawwattootaaf jijjiirraa ta’uun akkaan fokkate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 51, 'Ani uumaminsa samiifii dachii isaan hin hingarsiifne, uumaminsa lubbuulee isaaniitis, Ani jallistoota gargaartota godhataa hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 52, 'Guyyaa Inni “(warra) hiriyyoota Kiyya kan kijibaan dubbattan san waamaa” jedhu [yaadadhu]. Isaanis ni waamanii, garuu isaaniif hin owwaatan. gidduu isaaniitti hallayyaa (jahannam) taasifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 53, 'Yakkamtoonni ibidda ni argan,Ishee keessa bu’oo ta’uu isaanii yaadan, Karaa ishee jalaa ittiin ba’an hin argatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 54, 'Nuti dhugumatti Qur’aana kana keessatti fakkeenyota hunda irraa (namootaaf) ibsinee jirra. Namni baay’isaa wahii falmii ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 55, 'Namoota wanni amanuu dhoowwe waa hinjiru, yeroo qajeelumni isaanitti dhufe, Gooftaa isaanii araara kadhachuu irraas, karaan (dhumiinsi) warra durii isaanitti dhufuu yookiin adabbiin fuulduraa isaanitti dhufuu (eeguu) malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 56, 'Nuti ergamtoota gammachiiftotaafi dinniintoota goonee malee hin erginu, Warri kafaran sobaan falmu isaan haqa deemsisuuf jecha.; keeyyattoota kiyyaafi waan dinniinamanis qishnaa godhatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 57, 'Nama keeyyattoota Gooftaa isaatiin yaadachiifamee ergasii ishee irraa garagaluufi waan harki isaa lamaan dabarfatte dagate- caalaa namni miidhaa hojjate eenyu? Nuti dhugumatti akka isaan isa (Qur’aana) hin hubanne onneewwan isaanii irratti qadaaddaafi gurreen isaanii keessattis duudiinsa taasifnee jirra. Yoo gara qajeellumaa isaan waamte, isaan yoo san gonkumaa hin qajeelan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 58, 'Gooftaan kee akkaan araaramaa, abbaa rahmataati. Odoo waan isaan hojjataniin isaan qabee, silaa dhugumatti, adabbii isaaniif jerjersa ture. Garuu isaaniif beellamaatu jira, ken isa malee gara itti deebi’an hin arganne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 59, '(Warra) magaalotaa san isaan miidhaa hojjanaan isaan balleessine. halaakamiinsa isaaniitiif beellama goone..', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 60, 'Yeroo Muusaan dargaggoo isaatiin “hangan iddoo galaanni lamaan itti wal qunnaman ga’utti yookiin deemsa irratti waggoota (hedduu) fixutti (deemuu) hin dhiisu” jedhe [yaadadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 61, 'Yeroma isaan lamaan iddoo wal ga’iinsa galaana lamaanii ga’an, qurxummii isaanii ni dagatan. Inni (qurxummiin) karaa isaa galaana keessa baqaqaa godhate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 62, 'Yeroma isaan lamaan (iddoo san) qaxxaamuran, (Muusaan) dargaggicha isaatiin ni jedhe: “Laaqana keenya nuuf fidi Dhugumatti, nuti imala keenya kana irraa dadhabbii guddaa qunnamnee jirra.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 63, '(Dargaggichi isaa) ni jedhe: “Argitee? Sila yeroo nuti gara dhagaa hirkanne, dhugumatti, ani qurxummii irraanfadheera. Wanti akka isa hin yaadanne na irraanfachiises sheyxaana malee hin jiru. Innis karaa isaa galaana keessa dinqisiisaa godhate.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 64, '(Muusaan) ni jedhe: “Sun waan nuti barbaadaa turreedha.” Faanoowwan isaanii irra hordafaa gara duubaa deebi’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 65, 'Gabricha gabroota keenya irraa ta’e, argan, kan Nuti nu biraa rahmata isaaf kennineefi beekumsa Nubiraa ta’e isa barsiifne.[1]', '[1] namni isaan itti dhufan kuni maqaan isaa khadar jedhama, aalima nama Rabbiin ilmii guddoo barsiise. tanaaf muusaan irraa barachuu barbaadee dubbise.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 66, 'Muusaan isaan nijedhe “sila waan barsiifamte kan qajeelaa ta’e irraa akka na barsiiftuuf si hordofuu danda’aa?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 67, '(Namichi) ni jedhe: “ati ana wajjiin obsuudhaaf hin dandeessu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 68, 'Sila waan beekumsa isaa hin qabnee irratti akkamitti obsita?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 69, '(Muusaanis) “Yoo Rabbiin fedhe obsaa ta’uu na argita, Ajaja keetis hin didu” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 70, '(Namichi) yoo na hordofte, waan tokkoyyuu hanga ani waa’ee isaa siif himutti homaa irraa na hin gaafatin” jedheen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 71, 'Isaan lamaanuu hanga doonii tokko keessa yaabbatanitti ni deeman, Inni (namichi) ishee ure (Muusaan) ni jedhe: “Sila namoota ishee keessa jiran bishaan nyaachisuuf ishee urtee? Dhugumatti, ati waan guddaa fidde!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 72, '(Namichis) ni jedhe: “Sila ani ati ana wajjiin obsuudhaaf hin dandeessu hin jennee?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 73, '(Muusaan) ni jedhe: “Waanan irraanfadheef na hin qabin, Dhimma kiyya irraas rakkoo na hin baachisin.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 74, 'Hanga mucaa tokkotti dhufanitti deemanii achumaan isa (mucicha) ajjeese, (Muusaan) “Sila ati lubbuu qulqulluu lubbuu (ajjeesuun) ala ajjeeftaa? Dhugumatti, ati waan fokkataa hojjatteetta” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 75, '(Namichi) ni jedhe: “Sila ani ati ana wajjiin obsuudhaaf hin dandeessu siin hin jennee?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 76, '(Muusaan) ni jedhe: “Yoon ishee kana booda waan tokko irraas si gaafadhe, natti hin miiltomiin (natti hin shariikin), Dhugumatti, ana biraa dhiifama (dhumaa) irra geessee jirta.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 77, 'Ergasii isaan lamaan nideeman hanga warra magaalattii tokkoo bira dhufanii, jiraattota ishee nyaata gaafatan, isaan keessummeessuu didan. Ergasii dhaaba mana jiguu fedhuu tokko argan. (namichi) ol kaasee isa dhaabe (Muusaan): “Odoo feetee isa irratti mindaa fudhachuu ni dandeessa” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 78, '(Namichi) ni jedhe: “Kun addaan ba’iinsa gidduu kiyyaafi gidduu keetiiti. Ani hiikkaa wantoota ati irratti obsuu dadhabdee sittiin hima.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 79, 'Doonittiin tan namoota hiyyeeyyii galaana keessa dalaganii turte.ishee fokkisuu fedhe. isaan fuula duratti mootiin dooniwwan (fayyaa) hunda saamee fudhatu tokkootu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 80, 'Mucichi immoo, haadhaafi abbaan isaa mu’uminoota. Nutis (yoo guddate) jallinaafi kufriidhaan isaan haguuguu sodaanne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 81, 'Gooftaan isaanii (ilma) qulqullinaan isa irra caaluufi rahmatattis irra dhihoo ta’e bakka isaaniif buusu feene.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 82, 'Dhaabni manichaa immoo kan ijoollee yatiimota ta’an lama magaalattii keessa jiraataniiti ture. Isa jala immoo qabeenya awwaalame kan isaan lamaaniitu jira. Abbaan isaanii nama gaarii ture. Gooftaan kee (ijoollen lamaan) umrii ciminaa irra ga’anii qabeenya isaanii kan lafa jalatti awwaalame rahmata Gooftaa kee irraa ta’een akka baafatan fedhe. Anis kana (hunda) fedha kiyyaan hin hojjanne. Kun hiikkaa wantoota ati irratti obsuu hindandayiniiti.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 83, 'Zulqarnayni irraas si gaafatu “Ani isa irraa oduun isin irratti dubbisuuf jira” jedhi.[1]', '[1] zulqarneyni kan gaafa lamaa jechuudha.mootii gaariidha. dachii bahaa dhiha deemuu Rabbi isaaf mijjeesse. diinitti yaamuu tajaajila hawaasummaa kkaa kaarra jaaree irraa chfuuti hojjae.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 84, 'Nuti dachii keessatti isaaf mijeessinee jirra, Waan hunda irraa tooftaa isaaf kennine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 85, 'karaa (gara dhihaa) deeme.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 86, 'Hanga iddoo lixa aduu ga’u, isheedhaa ija dhoqqee gurraattii keessatti lixxuu arge. Ishee biratti ummata wahii arge. Nuti ni jenneeni: “Yaa Zulqarnayn! Ati isaan adabuu yookiin isaanitti toltuu hojjachuu (filannoo qabda)”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 87, 'Ni jedhe: “Nama miidhaa hojjate nuti fuulduratti isa adabna, Ergasii gara Gooftaa isaa deebifamee Innis adabbii hamaa ta’e (jahannamiin) isa adabuuf jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 88, 'Nama amanee, gaarii hojjate immoo, isaaf mindaa gaarii ta’etu jira. Nuti ajaja keenya irraa laafaatti isa ajajuuf jirra.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 89, 'Sana booda karaa hordofe (deemsa gara bahaa itti fufe).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 90, 'Hanga iddoo baha biiftuu ga’etti, isheedhaa ummata irratti baatu arge, (ummanni sunuu) kan nuti ishee gaditti waan hagoogu isaaniif hingodhin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 91, '(Dubbichi) akka kana, Wantoota isa bira jiran dhugumatti, beekumsaan marsineerra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 92, 'Ergasii karaa (kaabaa) hordofe (deemsa ittifufe).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 93, 'hanga gidduu gaara lamaanii ga’e, isaan lamaanii asitti ummata haasa’a beekuutti hin dhihaanne arge.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 94, '(Isaanis) nijedhan “Yaa Zalqarnayn! Dhugumatti, Ya’ajuujiifi Ma’ajuuj dachii keessatti badii hojjatoodha,baasii (kafaltii) siif goonuu Nuufi isaan giddutti cufaa godhuu irratti?” [1]', '[1] ya''ijuujiifii ma''ijuuj ilmaanuma namaati. garuu ummata shiftaadha. biyyatti weeraranii nama ajjeesuufii qabeenya saamuun beekaman. kanaaf akka zulqarneeyni kaarra jaaree itti cufu gaafatan, qabeenya walitti guurree siif kafalla jedhaniin. garuu zulqarneeyni waan mootii gaarii taheef akkanumatti tola jaareef homaa hinkafalchiifne.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 95, '(Innis) ni jedhe: “Waan Gooftaan kiyya isa keessatti naaf mijeessetu caala. humnaan na gargaaraa, Gidduu keessaniifi isaaniitti cufaa nan godhaa, .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 96, 'Muraa Sibiilaa naaf kennaa.” hanga iddoo gaara lamaan gidduu jiru guute “afuufaa” jedheen, hanga ibidda (diimaa) isa godhetti “sibiila baqe isa irrattin dhangalaasa naa fidaa ” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 97, '(Ya’ajuujifi Ma’ajuuj) isa irra koruu hin dandeenye; (jalaanis) isa uruu hin dandeenye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 98, '(Zulqarnayn) ni jedhe: “Kun rahmata Gooftaa kiyya irraa ta’e, Yeroo waadaan Gooftaa kiyyaa dhufe, bittinnaa’aa isa godha, Waadaan Gooftaa kiyyaa dhugaa ta’eera.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 99, 'Guyyaa (qiyaamaa) san garii isaanii garii keessa kan dhangala’u taasifnee dhiifna. Garriin (xurumbaanis) ni afuufamaa, (uumama hunda) walittiqabiinsa walitti isaan qabna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 100, 'Guyyaa san jahannamiin kaafirootaaf dhiyeessuu dhiheessina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 101, '(Isaan) warra ijjoowwan isaanii yaadannoo kiyya (Qur’aana) irraa haguuggaa keessa turanii, (isa) dhaga’uu hin dandeenye turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 102, 'Sila warri kafaran gabroota kiyya Anaa gaditti gabbaramtoota godhachuu yaaduu? Nuti jahannamiin kaafirootaf qubannoo qopheessineera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 103, '”Sila warra hojiin isaanii akkaan honga’oo ta’an isiniif himnuu?” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 104, 'Isaan warra jiruu adunyaa keessatti hojiin isaanii duraa badeedha odoo isaan dalagaa tolchinee hojjannaa yaadanuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 105, 'Isaan sun warra keeyyattoota Gooftaa isaanitiifi wal qunnamtii Isaatti kafarani. dalagaaleen isaanii baddee. Guyyaa Qiyaamaa miizaana isaaniif hin dhaabnu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 106, 'Isaan sun galanni isaanii jahannami. waan kafaranii keeyyattoota kiyyaafi ergamtoota kiyyas qishnaa godhataniif jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 107, 'Warreen amananii, gaggaarii hojjatan, Jannanni Firdaws qubannoota isaaniif taatee jirti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 108, 'Ishee keessa nituru. Ishee irraa jijjiiramuu hin barbaadan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 109, 'Jedhi: “Odoo galaanni qalama jechoonni Gooftaa kiyyaa (ittiin barraa’u) ta’ee, silaa odoo jechoonni Gooftaa kiyyaa hin dhumne galaanni dhuma ture; odoma (galaanni biraa) kan isa fakkaatu gargaarsaan finneeyyuu (galaanatu dhuma ture).”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 110, 'Jedhi: “Ani namuma akka keessaniiti. kan haqaan gabbaramaan keessan gabaramaa tokkicha qofa ta’uu wahyiin gara kiyyatti godhamuudha. Kanaaf namni Gooftaa isaatiin wal ga’uu kajeelu dalagaa gaarii haa hojjatu; gabbartii Gooftaa isaa keessattis tokkollee hin qindeessin.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 1, 'Kaaf Haa Yaa Ayn Saade', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 2, '(Kun) rahmata gooftaan kee Gabricha Isaa Zakariyyaaf (godhe) dubbachuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 3, 'Yeroo inni Rabbii Isaa waamicha dhoksaa waame (dubbadhu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 4, 'Nijedhe “Rabbii kiyya! Ani lafeen kiyya na laafe; mataan kiyyas Arrii makatee; Rabbii kiyya ani kadhaa keetiin hoonga’aa hin taane”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 5, '“Ani booda kootii firoota kiyya sodaadheen jira. Niitiin kiyyas maseentuudha. Suma biraa ilma naaf kenni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 6, '“Kan (amantii kiyya) na dhaaluufi kan sanyii Ya’aquub irraas dhaalu, Yaa Gooftaa kiyya! Jaallatamaa isa taasisi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 7, '(Rabbiin ni jedhe): “Yaa Zakariyyaa! Nuti ilma maqaan isaa Yahyaa ta’een sigammachiifna. kan ammaan dura moggoo isaaf hingodhin (kan maqaa isaa namni biroo hinbaafatin)”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 8, '(Zakariyyaan) ni jedhe: “(Yaa) Rabbii kiyya! akkamitti ilmi naaf ta’a? Odoo jaartiin too maseena taatee jirtuu, anis dulluma irraa hoonga ga’ee jiruu ?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 9, 'Ni jedhe “(Dhimmichi) akkuma kana, Rabbiin kee ‘Kun anarratti laafaadha jedhe. ani kana dura si’ii homaa hin turin si uumeen jira.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 10, '(Zakariyyaan) ni jedhe: “(Yaa) Rabbii kiyya! Mallattoo naaf godhi.” (Rabbiin) ni jedhe: “Mallattoon kee halkan sadihiif (guyyaa sadihiif) odoo fayyaa qabduu (Zikrii malee) nama dubbisuu dhabuudha (dadhabuudha).”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 11, 'Mihraabarraa ummata isaa irratti gadi ba’ee, ganamaafi galgala Rabbiin qulqulleessuu (mallattoon) itti beeksise.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 12, '“Yaa Yahyaa! Kitaabicha ciminaan qabadhu” (jenneen). Beekumsa (ogummaa) ijoollummaan isaaf kennine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 13, 'Mararfannaa Nu biraa ta’eefi qulqullinas (isaaf kenninee jirra). Inni (Rabbiin) sodaataa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 14, 'Haadhaafi abbaa isaatiifis tola oolaa ta’eera, Of tuulaa, dilaawaa hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 15, 'Nageenyi isarratti haajiraatu, guyyaa inni dhalate, guyyaa inni du’uufi guyyaa inni jiraataa tahee kaafamus.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 16, 'Kitaabicha (Qur’aana) keessatti Maryamiin yeroo maatii ishee irraa iddoo gara bahaatti achi baate dubbadhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 17, 'Isaan irraa haguuggaa godhattee, ergamaa keenya (Jibriiliin) gara isiitti eregine, Inni nama (uumaan isaa) guutuu isiitti fakkaate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 18, 'Ni jette: “Ani sirraa Rahmaanitti maganfadha. Yoo kan (Rabbiin) sodaattu taateef (naa tuqin)”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 19, '(Jibriil) nijedhe “Ani ergamaa Rabbii keetiiti; ilma qulqulluu siif kennuuf (Rabbiin na erge)”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 20, 'Ni jette: “akkamitti ilmi naaf ta’a Odoo namni tokko nan tuqin; sagaagaltuus odoon hin ta’in?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 21, 'Innis ni jedhe: “Dhimmichi akkuma kana, Gooftaan kee ‘kuni narratti laafaadha; Namootaaf raajiifi rahmata Nu irraa ta’es isa godhuufi” jedhe. (Kun) dhimma murtaa’e ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 22, 'Isa ulfoofte; kophaa ishee gara bakka fagoo isaan deemte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 23, 'Ciniinsuun gara gufuu timiraa ishee maqse, Ni jette: “Yaa gaabbii kiyya! Odoo kana dura du’ee, wan dagatamee hafe ta’ee maal qaba!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 24, 'Ishee jalaa “Hin gaddin; dhugumatti, Gooftaan kee jala keetti laga xiqqoo taasiseera” jechuun isheetti lallabe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 25, '“Muka timiraa gara keetti hurgufi; asheeta timira bilchaataa ta’e sirratti harcaafti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 26, 'Nyaadhu, dhugii; ijaanis itti gammadi. Yoo ilma namarraa tokko argite jedhiin ‘ani Rahmaaniif callisuu qodhaa (nazrii) galeen jira, hardha nama tokkos hin dubbisu”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 27, 'Isa baadhattee gara ummata ishee dhufte, [Isaan] ni jedhan: “Yaa Maryam! Dhugumatti ati waan akkaan hamtuu hojjatte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 28, 'Yaa obboleettii Haaruun! Abbaan kee nama badaa hin turre; haati teetis sagaagaltuu hin turre.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 29, '(Isiinis) gara isaatti akeekte, [Isaan] nijedhan “Akkamitti daaima siree daa’imummaa keessa jiru dubbifna?”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 30, '(daa’imichi) ni jedhe: “ ani gabricha Rabbiiti, Inni kitaaba naaf kenneera; nabiyyiis na taasisee jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 31, 'essalee jiraadhu barakeeffamaa na taasisee jira; salaataafi zakaas hangan lubbuun jiru naatti dhaamee jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 32, 'Haadha tiyyaaf tola oolaa (na godhe); of tuulaa hoonga’aa, nan taasifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 33, 'Nageenyi narratti jiraata Guyyaa ani dhaladhe, guyyaa ani du’uufi guyyaa ani kaafamuus ”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 34, '(kan waayee isaarraa dubbatame kun) Kun Iisaa ilma Maryami; inni jecha dhugaa kan isaan isa keessatti shakkaniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 35, 'Rabbiif ilma taasifachuun hin malu, Inni qulqullaa’e, Yeroo dhimma tokko murteesse, wanti Inni jedhu “ta’i” jechuu qofa; innis yoosuu ta’a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 36, '(Iisaan) “Dhugumatti, Rabbiin Gooftaa kiyyaafi Gooftaa keessani, Kanaaf Isa qofa gabbaraa, kun karaa qajeelaadha”(jedhe.)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 37, 'Gareewwan (yahuudaafi nasaaraa) gidduu isaaniitti (waa’ee Iisaa irratti) wal dhaban; warra kafaraniif halaakni tahe wal gayii guyyaa guddaa (Qiyaamaa) san keessatti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 38, 'Maaltu akkaan dhaga’oo argoo isaan taasise, (Kaafiroonni) guyyaa isaan Nutti dhufan. Garuu hardha miidhaa raawwattoonni jallina ifaa ta’e keessa jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 39, 'Guyyaa Gaabbii san isaan sodaachisi, yeroo dhimmichi murtaa’u Haala isaan daguu keessatti ta’aniin isaanII hin amanin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 40, 'Nuti Numatu dachiifi waan ishee irra jiru dhaala; garuma keenya deebifamus.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 41, 'Kitaaba keessatti Ibraahiim dubbadhu, inni nama akkaan dhugaa dubbataa, nabiyyii ture.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 42, 'Yeroo inni abbaa isaatiin jedhe “Yaa abbaa kiyya! Maaliif waan hin dhageenye, hin argineefi homaa sirraa deebisuu hin dandeenye gabbarta?”(dubbadhu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 43, '“Yaa abbaa koo! Dhugumatti, ani beekumsa irraa wanti sitti hin dhufin natti dhufee jira. na hordofi; ani karaa sirraawaan si qajeelcha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 44, 'Yaa abbaa koo! Sheyxaana hin gabbarin; sheyxaanni Rahmaanitti fincilaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 45, 'Yaa abbaa koo! ani Rahmaan irraa adabbiin si tuquun sodaadha, atis sheyxaanaaf jaalallee ta’uu keen (sodaadha)”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 46, '(Abbaan isaa) nijedhe “Yaa Ibraahiim! Ati gabbaramtoota kiyya (jibbitee) irraa garagaltaa? Yoo hin dhorgamne, ani dhagaaniin si tuma (si cafaqa), Yeroo dheeraaf narraa fagaadhu”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 47, '(Ibraahiim) nijedhe “Nageenyi sirra haa jiraatu! Ani Rabbii kiyyan araarama siif kadha, Inni akkaan rahmata naaf godhaa ta’eera”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 48, '“Isiniifi wantoota isin Rabbiin gaditti gabbartan irraan fagaadha. Gooftaa kiyya qofan gabbara, kadhaa gooftaa kiyyaatiin hoonga’aa ta’uu dhabuu koon abdadha”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 49, 'Yeroma inni isaaniifi waan isaan Rabbii gaditti gabbaran irraa fagaatu, Isihaaqiifi Ya’aquubiin isaaf kennine, Hunda isaanii nabiyyii taasifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 50, 'Rahmata keenya irraas isaaniif kennine, Gaariin dubbatamuu (faaruu) ol fuudhamaas isaaniif goone.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 51, 'Kitaaba (Qur’aana) keessatti (waa’ee) Muusaa dubbadhu, inni filatamaa ta’ee jira; ergamaa, nabiyyii ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 52, 'Nuti moggaa mirga (gaara) Xuur irraa isatti lallabnee, maqoo itti haasa’uunis (of itti) isa dhiheessine!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 53, 'Tola keenya irraa obboleessa isaa Haaruuniin nabiyyii (taasifnee) isaaf kennine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 54, 'Kitaaba (Qur’aana) keessatti (waa’ee) Ismaa’iil dubbadhu, inni beellama kabajaa ta’ee jira, Ergamaa, nabiyyii ta’ee jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 55, 'Maatii (ummata) isaas salaatafi zakaatti kan ajaju ture. Gooftaa isaa biratti jaallatamaa ture.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 56, 'Kitaaba keessatti Idriisiin dubbadhu, inni dhugaa dubbataa, nabiyyii ture.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 57, 'Iddoo ol aanaattis ol isa fuunee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 58, 'Isaan sun warra Rabbiin isaan irratti tola oole; nabiyyoota ilmaan Aadam irraa ta’anii, warra Nuuhii wajjiin (doonii irratti) yaabbachiifne irraa ta’anii, ilmaan Ibraahiimiifi Israa’iil irraas ta’anii, warra Nuti qajeelchinee filanne irraas kan ta’aniidha, Kan yeroo keeyyattoonni Rahmaan isaan irratti dubbifamtu sujuudaafi booyaa kufaniidha. [1]', '[1] asittis sujuuda qaraatiittu (tilaawaattu) barbaachisa.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 59, 'Isaan boodaas bakka bu’oota (gadhee)tu bakka bu''e. kan salaata miidhaniifi fedhaalee lubbuu isaanii hordofan. Hallayyaa jahannam quunnamuuf jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 60, 'Nama tawbatee, amanee, gaarii hojjate malee Warri sun jannata seenu; homaa hin miidhamanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 61, 'Jannatoowwan qubsumaa ishee Rahmaan gabroota Isaatiif fagootti waadaa gale (seenu). Inni waadaan Isaa dhufamaa ta’eera', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 62, 'Nagaa (wal gaafachuu) malee ishee keessatti haasa’a fokkataa hin dhagayan. Ishee keessatti isaaniif sooranni isaanii ganamaafi galgala jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 63, 'Jannatni sun ishee gabroota keenya irraa namoota Rabbiin sodaatan dhaalchifnuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 64, 'Nuti (maleykonni) ajaja Gooftaa keetiitiin ala hin buunu, Wanti fuuldura keenyaa, wanti duuba keenyaafi wanti gidduu sana jirus kan Isaati, Gooftaan kee dagataa hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 65, '(Inni) Gooftaa samii, dachiifi wantoota gidduu isaan lamaanii jiraniiti. Isa (qofa) gabbari; gabbartii isaarratti obsi. Sila Isaaf moggoo (fakkaataa) wahii ni beektaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 66, 'Namni nijedha “Sila ani ergan du’ee lubbuun jiraadhee (qabrii) baafamaa?”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 67, 'Sila namni hin yaadatuu akka Nuti kanaan dura isa uumne, ka waa argamaa hintahin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 68, 'Gooftaa keetiin kakannee! Dhugumatti, isaaniifi sheyxaanota walitti qabna, ergasii moggaa jahannamitti jilbeenfatoo taasifnee isaan fidna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 69, 'Eegasii garee hunda irraa isaan Rahmaan irratti jallinatti irra cimoo ta’an ni baafna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 70, 'Ergasii, dhugumatti, Nuti (isaan irraa) warra ishee (Ibidda) seenuu qaban ni beekna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 71, 'Isin irraa eenyulleen ishee bu''u malee hin hafu, Dirqama Rabbii keetiin murteeffameedha. [1]', '[1] kuni hiikkaan isaa hundi namaa riqicha siraax jedhamu kan hallayyaa ibiddaarra diriirfame irra ceha jechuudha. namni badii hinqabne ibidda hinseenu waan taheef.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 72, 'Sana booda warra Rabbiin sodaatan nagaa baafna; warra miidhaa hojjatan immoo ishee keessatti jilbiiffatoo taasifnee (isaan) dhiifna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 73, 'Yeroo keeyyattoonni keenya ifa ta’anii isaan irratti dubbifaman kaafiroonni mu’uminootaan nijedhan “Garee lamaan keessaa isa kamtu caalmaa sadarkaatiifi miidhagina teessoo qaba?”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 74, 'Isaaniin dura dhaloota heddu kan meeshaa mana keessaatiifi argaa ijaattis isaan caalaa babbareedoo ta’an balleessinee jirra?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 75, 'Jedhi (Yaa Muhammad!-SAW): “Nama jallina keessa jiru Rahmaan (jallina inni filate) akkaan isaaf haa dabalu; hanga waan waadaa isaaniif galame, adabbii yookiin Qiyaamaa argan, nama iddoon isaa irra badaafi raayyaa waraanaatti irra dadhabaa ta’e fuulduratti ni beeku.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 76, 'Rabbiin warra qajeelaniif qajeeluma dabala, Hojiiwwan gaggaarii haftuu taateetu Rabbii kee biratti mindaadhaan caalaadha; deebiidhaanis isatu (irra) caalaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 77, 'Sila isa keeyyattoota keenyatti kafaree hinarginee ati? kan “Ani dhugumatti, qabeenyaafi ilmaan kennamuufin jira” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 78, 'Sila (iccitii) fagoo irratti mul’atemoo Rahmaan biratti waadaa wahii godhate?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 79, 'Lakki; (kun hin ta’u) Nuti waan inni jedhu ni barreessina; azaabarraa dabaltii (isaaf malu) isaaf daballa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 80, 'Waan inni (qaba) jedhu (hunda) irraa dhaalla; inni kophaa isaa Nutti dhufa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 81, 'Rabbii achitti gabbaramtoota godhatan Akka humnaafi kabajaa isaaniif ta’aniif jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 82, 'Lakkisaa; (kun waan ta’uu miti) isaan fuulduratti gabbaruu isaanii ni mormu; isaan irrattis faallaa tahu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 83, 'Sila ati hinarginee akka Nuti kaafiroota irratti sheyxaanota erginee (badii irratti) kakaasiinsa isaan kakaafti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 84, 'Isaan (adabamuu) irratti hin jerjerin; Nuti lakkoofsa (guyyootaa) isaaniif lakkooyna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 85, 'Guyyaa warra Rabbiin sodaatan gara Rahmaanitti jiila (garee kabajamoo) taasifnee isaan walitti qabnu [yaadadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 86, 'Badii raawwattoota immoo dheebotoo taasifnee gara Jahannam oofna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 87, 'Nama Rahmaan biraa waadaa qabate malee araarsaa argachuu hin danda’anu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 88, '“Rahmaan ilma godhate” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 89, 'Dhugumatti, isin waan fokkataa fiddaniirtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 90, '(Kana) irraa samiileen babbaqaquu, dachiin dhodhooyuufi gaarreen caccabanii kufuuf dhiaatu (fiddan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 91, 'Rahmaaniif ilma moggaasuu irraa (babbaqaqutti dhiaatu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 92, 'Rahmaan ilma godhachuun isaaf hin malu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 93, 'Wanti samiileefi dachii keessa jiran hundi gabra (Isaa) qofa ta’anii gara Rahmaan dhufanu malee hin hafan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 94, 'Dhugumatti, Inni tokko tokkoon isaan beeka; lakkoofsa guutuu ta’es isaan lakkaa’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 95, 'Hundi isaanii Guyyaa Qiyaamaa kophaa isaanii gara Isaatti (Rahmaanitti) dhufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 96, 'Dhugumatti, isaan amananii, gaggaarii hojjatan, Rahmaan jaalala isaaniif taasisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 97, 'Wanti Nuti arraba kee irratti isa (Qur’aana kana) sii laaffifneef akka warra Rabbiin sodaatan ittiin gammachiiftee, ummata akkaan mormitoota ta’an immoo ittiin sodaachiftuufi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 98, 'Isaan dura dhaloota irraa meeqaatama balleessinee jirra! Sila isaan irraa tokkos argitaa? Yookiin hasaasa (qilixii) isaaniif ni dhageessaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 1, 'Xaa haa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 2, '(Yaa Muhammad!) Nuti Qur’aana akka ati rakkattuuf sirratti hin buufne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 3, 'Nama Rabbiin sodaatu yaadachiisuuf malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 4, 'Isa dachiifi samiilee ol fuudhamoo uume irraa buufamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 5, 'Rahmaan Arshii irratti (ol ta’iinsa Isaaf malu) ol ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 6, 'Wanti samiilee, dachiifi gidduu isaan lamaanii jiruufi wanti biyyee jala jiru hundi kan Isaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 7, 'Jecha yoo ol fuutes, dhugumatti Inni (Rabbiin) iccitiifi waan isa caalaa dhokates ni beeka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 8, 'Rabbiin dhugaan gabbaramaan isa malee hin jiru. Maqoonni babbareedoon isaaf tahe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 9, 'Sila oduun Muusaa sitti dhufeeraa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 10, 'Yeroo Ibidda argee maatii isaatin jedhe “as taa’aa ani ibiddaan argee, waan irraa qabsiifatanin isii irraa isinii fida. yookiin ibidda biraa nama (karaa irratti) na qajeelchu argachuun kajeelaa”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 11, 'Yeroma gara ishee dhaqe “Yaa Muusaa!” (jechuun) itti lallabamee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 12, '“Ani anumaatu Gooftaa keeti; kophee tee lamaan baafadhu, ati laga qulqulleeffamaa, Xuwaa keessa jirtaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 13, 'Ani si filadheeraa waan (sitti) beeysifamu dhageeffadhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 14, 'Ani anumaatu Allaahdha; dhugaan gabbaramaan hin jiru Ana malee! Ana gabbari. Yaadannoo kiyyaaf salaata seeraan salaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 15, 'Dhugumatti, Qiyaamaan dhuftuudha. akka lubbuun hundi waan hojjatte mindeeffamtuuf jecha. ishee dhoksuuttin dhihaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 16, 'Ishee irraa gara si hin galchin Namni isheetti hin amanin, kan fedhii isaa hordofe, (Yoo isa hordofte) ni badda.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 17, 'Yaa Muusaa! Wanti harka mirgaa kee keessa jiru sun maali?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 18, '(Muusaan) ni jedhe: “Isheen ulee tiyya; ishee irrattin hirkadha; Re’ee tiyyaaf isheenin (baala mukaa) harcaasa. Ishee keessa anaaf dhimmi biraas ni jira” .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 19, '(Rabbiin) ni jedhe: “yaa Muusaa! Ishee darbi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 20, 'Ishee ni darbeYeroma san bofa fiigdu taate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 21, '(Rabbiin) ni jedhe: “Ishee qabi; hin sodaatin; haala ishee kan jalqabaatti ishee deebifnaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 22, 'Harka kee gara cinaacha keetiitti maxxansi, adii taatee baati dhibee (tokko) malee, Mallattoo biraati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 23, 'Mallattoolee keenya isaan gugurdoo irraa si agarsiisuufi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 24, 'Gara Fir’awnaa deemi, inni daangaa dabree jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 25, '(Muusaan) ni jedhe: “Yaa Gooftaa kiyya! Qoma kiyya naaf bal’isi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 26, 'Hojii kiyyaas naaf laaffisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 27, 'Hidhaa (Cabaqa) arraba kiyya irraa hiiki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 28, 'Jecha kiyya haa hubatanii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 29, 'Maatii kiyya irraa gargaaraa (qondaala) naaf godhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 30, 'Haaruun obboleessa kiyya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 31, 'Isaan irree kiyya cimsi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 32, 'Dhimma kiyya keessattis isa hirmaachisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 33, 'Akka baay’ee si faarsinuuf.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 34, 'Akka baay’inaanis si yaadannuuf.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 35, 'Dhugumatti, Ati nu argaa taateetta.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 36, '(Rabbiin) ni jedhe: “Yaa Muusaa! Dhugumatti, kadhaa kee kennamtee jirta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 37, 'Dhugumatti, yeroo biraas si qanansiifnee turre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 38, 'Yeroo waan beeksifamu gara haadha teetii (wahyii) beeysifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 39, 'Sanduuqa keessa isa (daa’ima) kaayi; laga keessatti isa darbi; Lagichi moggaatti isa darbeeti diinni kiyyaafi diinni isaas isa fudhata. Jaalala Ana biraa ta’e si irratti darbeera; argaa ija tiyyaa (tika kiyya) irratti akka guddattuuf.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 40, '(Yaa Muusaa!) Yeroo obboleettin tee deemtee ‘Nama isa guddisu irratti isin qajeelchuu?’ jetteen [yaadadhu], gara haadha keetiitti si deebifne Akka ijji ishee tasgabbooftuufi isiin hin gaddineef jecha. Lubbuu ajjeeftee turtee yaaddoo guddaa jalaa si baraarree, mokkora cimaas si mokkorree jirra. Ergasii waggoota (baay’ee) warra Madyan keessa turtee jirta. Sana booda yeroo Ani siif murteessetti (bakka kana) dhuftee jirta; yaa Muusaa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 41, 'lubbuu tiyyaaf si filadheera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 42, 'Atiifi obboleessi keetis mallattoolee kiyyaan deemaa; zikrii kiyya keessattis isin lachanuu hin laafinaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 43, 'Isin lamaanuu gara Fir’awni deemaa; dhugumatti, inni daangaa dabree jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 44, 'Jecha laafaa (gaarii) isaan jedhaa. akka gorfamuuf yookiin akka sodaatuuf jecha”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 45, 'Isaan lamaan ni jedhan: “Gooftaa keenya! nuti adabbii cimaa nu adabuu; yookiin (nurratti) daangaa darbuu sodaanna”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 46, '(Rabbiin) ni jedhe: “Hin sodaatinaa, Dhugumatti, Ani isin lamaan wajjinin jira; nan dhaga’a; nan argas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 47, 'Isin lachanuu isa bira dhaqaa isaan jedhaa ‘Dhugumatti, nuti ergamtoota Gooftaa keetiiti; ilmaan Israa’iil nu waliin ergi; isaan hin adabin; dhugumatti, nuti mallattoon Gooftaa keetirraa sitti dhufne. Nageenyi nama qajeelfama (Rabbii) hordofe irratti taha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 48, '“nuti gara keenyatti wahyiin godhameera, adabbiin nama sobsiisee garagale irratti tahaadha”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 49, '(Fir’awn) “Yaa Muusaa! Gooftaan keessan eenyu?” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 50, '(Muusaan) ni jedhe: “Gooftaan keenya Isa (waan hunda) akkaataa uumama isaa isaaf kennee sana, eegasii isa qajeelcheedha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 51, '(Fir’awn) ni jedhe: “Haalli ummatoota darbanii hoo akkam ta’a?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 52, '(Muusaanis) ni jedhe: “Beekumsi ishee Gooftaa kiyya bira galmee keessa jira, Gooftaan kiyya hin dogoggoru; hin irranfatus”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 53, '(Inni) Isa dachii afata isiniif godhee, ishee keessatti karaalee isiniif laaffisee, samii irraa bishaan buuse sani, Isaan (bokkaan) akaakuu biqiltuulee adda addaa irraa taate ni baafne (nimagarsine).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 54, '(Isa irraa) nyaadhaa; beyladoota keessanis dheechisaa, Dhugumatti, kana keessa namoota qalbiilee (sammuu) qabaniif mallattoleetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 55, 'Ishee (dachii) irraa isin uumne; ishee keessatti isin deebifna; yeroo biraas ishee irraa isin baafna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 56, 'Dhugumatti, mallattoolee keenya hunda ishee isatti (Fir’awnitti) argisiifneerra; innis ni sobsiisee; ni dides.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 57, '(Fir’awn) ni jedhe: “Yaa Muusaa! Sila ati dachii teenya irraa sihrii teetiin nu baasuuf nutti dhuftee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 58, 'Nutis sihrii fakkaataa isaatiin siif dhufna, gidduu keenyaafi gidduu keetti beellama godhi. kan nutiifi atis irraa hin hafne, iddoo giddu galeessa ta’etti”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 59, '(Muusaanis) ni jedhe: “Beellamni keessan guyyaa ayyaanaati; namoonnis waaree walitti qabamuudha”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 60, 'Fir’awni gara galee, deemee dhara isaa walitti qabee eegasii dhufe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 61, 'Muusaan isaaniin nijedhe “Yaa badii keessan! Rabbi irratti soba hin odeessinaa; adabbiidhaan isin balleessa, Dhugumatti, namni (Rabbi irratti) soba odeesse hoonga’ee jira”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 62, 'Dubbii isaanii irratti gidduu isaaniitti wal falman, maqoo isaaniis dhokfatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 63, 'Ni jedhan: “Jarri lamaan kun falfaltoota, falfala isaanitiin dachii keessan irraa isin baasuu fedhan, karaa keessan ishee caaltuu taate dhabamsiisuu (fedhu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 64, 'Tooftaa keessan walitti qabadhaa; sana booda hiriiraan koottaa, Dhugumatti, namni hardha irra aane (mo’ate) milkaa’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 65, 'Yaa Muusaa! Ati darbachuu yookiin jalqaba nama darbuu nuti ta’uu (filadhu)” jedhaniin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 66, '(Muusaanis) “Lakkisaa; isinummaan darbaa!” jedhe, yoggus haadoowwan isaaniifi uleewwann isaaniis falfala isaanii irraa kan ka''e waan fiigdu (bofa) itti fakkeeffama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 67, 'Muusaan lubbuu isaa keessatti sodaan itti dhaga’ame.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 68, '“Hin sodaatin! Dhugumatti, ati sumatu ol''aanaa” jenneen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 69, '“Waan mirga kee keessa jiru darbi! Waan isaan dalagan ni liqimsiti, Wanti isaan dalagan (hundi) toftaa nama falfala hojjatuuti, Falfalaan bakkuma dhufe (hunda)ttuu hin milkaa’u”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 70, 'Ergasii warri falfala hojjatan sujuuda bu’anii “Gooftaa Haaruniifi Muusaatti amanne” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 71, '(Fir’awn) ni jedhe: “Odoo ani isiniif hin hayyamin isatti amantuu? Dhugumatti, inni guddaa keessan kan falfala isin barsiiseedha, harkowwaniifii miillan keessan wal faallessee mura. jirma muka timiraa irrattin isin fannisa, Isinis (yoos) eenyu keenya (anamoo Gooftaa Muusaatu) adabbiin isaa irra cimaafi turaa akka ta’e beekuuf jirtu.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 72, 'Ni jedhan: “Waan nutti dhufe kan ragaawwan ifa bahan irraa ta’eefi Isa nu uume irra si hin caalchifannu, waan murteessitu murteessi! Wanti ati murteessitus jiruma addunyaa kana qofa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 73, '“Nuti Gooftaa keenyatti amannee jirra, Akka dogoggora keenyaafi falfala irraas waan ati isatti nu dirqisiifte nuuf araaramuuf, Rabbitu caalaafi hafaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 74, 'Namni badii hojjataa ta’ee gara Rabbii isaa dhufe, isaaf dhugumatti, jahannamtu jira; ishee keessatti hin du’u, hin jiraatus.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 75, 'Namni Mu’umina ta’ee, dhugumaan hojiilee gaarii hojjataa gara Isaa dhufe isaan sun isaaniif sadarkaalee ol ta’aatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 76, 'Jannatoowwan qubsumaa tan jala ishee laggeen yaatutu (isaanif jira); ishee keessa yeroo hunda jiraatu, Kun mindaa nama qulqulleeffateeti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 77, 'Dhugumatti, gara Muusaa beeysifne “Gabroota kiyyaan halkaniin deemi! Isaaniif galaana keessatti karaa gogaa taasisi; (Fir’awn) si dhaqqabuufi (bishaaniin nyaatamuu) hin sodaattu” jechuudhaan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 78, 'Fir’awni waraana isaa waliin isaan hordofe; galaanicha irraa wanti isaan haguuge isaan haguuge.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 79, 'Fir’awni ummata isaa ni jallise (isaan) hin qajeelchine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 80, 'Yaa ilmaan Israa’iil! Dhugumatti Nuti diinota keessan jalaa isin baraarsinee, moggaa mirga gaara Xuur irratti waadaa isinii goonee, waan mi’aawaa damma fakkaatuufi foon allaattii isin irratti buufnee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 81, 'Wantoota gaggaarii Nuti isiniif kennine irraa nyaadhaa, isa keessattis daangaa hin dabrinaa (hinjallatinaa); (yoo jallattan) dallansuu kiyyatu isin irratti bu’a, Namni dallansuun kiyya isa irratti bu’e, dhugumatti, bade.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 82, 'Ani akkaan araaramaadha nama tawbatee, amanee, gaggaarii hojjatee, sana booda (hanga du’utti) karaa qajeelaa qabateef', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 83, '“Ummata kee biraa maaltu si jarjarse? Yaa Muusaa!” (jedheen).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 84, '(Muusaan) ni jedhe: “Kuunnoo isaan faana kiyya irra jiru, Yaa Gooftaa kiyya! Akka Ati (na irraa) jaallattuufiin gara kee jarjare.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 85, '(Rabbiin) ni jedhe: “Nuti dhugumatti, ummata kee siboodaa (bakka ati hin jirretti) mokkorree jirra; Saamiriyyichis isaan jallise.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 86, 'Muusaan gara ummata isaa, dallanaa, gaddaa deebi’ee nijedhe “Yaa ummata kiyya! Sila Rabbiin keessan waadaa gaarii isiniif hin seennee? (Yeroo) beellamichaatu isinitti dheeratemoo? Dallansuun gooftaa keessan irraa isinitti bu’uu feetaniiti waadaa kiyya diigdanii?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 87, '[Isaan] ni jedhan: “Waadaa siif seenne fedha keenyaan hin diigne, Garuu nuti ba’aa (faaya) bareedumaa kan warra (Fir’awn) baachifamneeti, (ibidda keessatti) ishee darbine, Akkuma nuti darbinetti, Saamiriyyichis darbe.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 88, 'Qaama, Jibicha (mirgoo), sagaleen barooduun isaaf jiru isaaniif baasee “Kanatu gabbaramaa keessaniifi gabbaramaa Muusaati; (Muusaan isa) irraanfateeti (barbaaduuf deeme)” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 89, 'Sila kan inni jecha tokkos isaaniif deebisuu dhabuufi isaan miidhuus ta’ee fayyaduu hin dandeenye ta’uu hin arganii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 90, 'Dhugumatti, sana dura Haaruun isaaniin jedhee ture.“Yaa ummata kiyya! Inni (kun) waan isin ittiin mokkoramtaniidha, Gooftaan keessan immoo Rahmaani; na hordofaa; ajaja kiyyas tole jedhaa”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 91, '[Isaan] “ Nuti isa (Jibicha) gabbaruu irraa hin deemnu Hanga Muusaan gara keenya deebi’utti” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 92, '(Muusaan) ni jedhe: “Yaa Haaruun! Yeroo jallachuu isaanii argite maaltu si dhorge?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 93, 'Ana hordofuu (maaltu si dhorge?) Moo ajaja kiyya fudhachuu didde?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 94, '(Haaruunis) nijedhe “Yaa ilma harmee tiyyaa! Areeda kiyyas ta’ee mataa kiyya na hin qabin, ‘Ati gidduu ilmaan Israa’iil addaan baafte; jecha kiyyas hin eegdu (naan) jettaan sodaadhe”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 95, '(Muusaan) ni jedhe: “Ati hoo yaa Saamiriyyii! Maal taate?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 96, '(Saamiriyyiin) nijedhe “Ani waan isaan hin beekin beekeetin, faana kottee (farda) ergamaa (Jibriil) irraa (biyyee) hammaarrii tokko fudheen ishee darbe akka kana Lubbuun tiyya naaf miidhagsite”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 97, '(Muusaanis) ni jedhe: “Deemi jireenya keessatti ‘Nan tuqinaa jechaa jiraachuun siif tahaadha.’ ammas siif beellama ati hin hanbifamnetu siif jira. Gara gabbaramaa kee isa gabbaraa turtee ilaali, Nuti dhugumatti, isa gubna; eegasii (caccabaa isaa) galaana keessatti facaasinsa facaafna.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 98, 'Rabbiin keessan Allaah kan Isa malee dhugaan gabbaramaan biraa hin jirre qofa. Inni waan hunda beekumsaan bal''ateera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 99, 'Akkuma oduu (warra Fir’awn) kanatti waan dur dabre irraa sitti odeessina, Nuti dhugumatti, nu biraa yaadannoo (Qur’aana) siif kenninee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 100, 'Namni isa (Qur’aana) irraa garagale, dhugumatti, inni Guyyaa Qiyaamaa ba’aa (dilii) baadhata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 101, 'Yeroo hunda isa (adaba ba’aa kanaa) keessa jiraatan, Guyyaa Qiyaamaa ba’aa isaanii ta’uun waa fokkate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 102, 'Guyyaa garrii (xurumbaa) keessa afuufamu (dubbadhu), Guyyaa san badii raawwattoota (ija) cuquliisa (jaamaa) taasifnee walitti qabna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 103, 'Gidduu isaaniitti “Isin (guyyoota) kudhan malee (addunyaa irra) hin turre” jechuun walitti hasaasu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 104, 'Nuti waan isaan jedhan beekna yeroo mala irra beekaan isaanii “isin guyyaa tokko malee hin teenye” jedhu .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 105, 'Gaarreen irraas si gaafatu, “Gooftaan kiyya faffacaasuu ishee faffacaasa” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 106, '“Lafa wal qixxaa’aa dirree taasisee ishee dhiisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 107, 'Ishee keessatti bu’aa bahiis hin argitu.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 108, 'Guyyaa san lallabaa jallinni isaaf hinjirre hordofu; Sagaleewwan Rahmaaniif cal jetti, Shokomsaa malee homaa hin dhageessu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 109, 'Guyyaa san manguddummaan homaa hin fayyaddu; nama Rahmaan isaaf hayyameefi jecha isaas irraa jaallateef malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 110, 'Inni waan fuuldura isaaniitiifi waan duuba isaaniitis beeka, Isaan immoo beekumsaan isa hin marsine', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 111, 'Fuulli (Rabbii) jiraataa, waan hundaan dhaabatuuf gadi jette, Dhugumatti, namni miidhaa baadhate hoonga’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 112, 'Namni mu’umina ta’ee gaggaarii irraa hojjate, miidhaa (hamtuu irratti dabaluu)s ta’ee hirdhina (mindaa isaa) hin sodaatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 113, 'Akkanatti qur''aana Afaan Arabaa goonee isa (Qur’aana) buufne; isa keessatti akeekkachiisa irraa addeessine. akka isaan sodaataniif yookiin akka gorsa isaaniif haaromsuuf', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 114, 'Egaa Allaahn, mootiin dhugaa, ol ta’eera, Odoo wahyiin isaa gara kee bu’ee hin xumuramin dura, Qur’aana (dubbisuutti) hin jarjarin, “(Yaa) Rabbii kiyya! Beekumsa naaf dabali” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 115, 'Dhugumatti, sana dura Aadamitti beeksisa goonee, dagatee ture, Nuti kutannoo isaaf hin argine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 116, 'Yeroo maleykotaan “Aadamiif sujuuda bu’aa” jenne [yaadadhu]. Ibliisa malee sujuuda bu’an. Inni ni dide.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 117, 'Ni jenne: “Yaa Aadam! Dhugumatti, kun diina keetiifi (diina) niitii teetiiti, Jannata keessaa akka isin lamaanuu hin baafne; (yoo jannataa baate) ni rakkatta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 118, 'Dhugumatti, ati ishee (jannata) keessatti beela’uu dhabuufi daaruu dhabuunis siif jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 119, 'Ammas ati ishee keessatti dheebochuu dhabuufi aduun gubachuu dhabuunis siif jira.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 120, 'Sheyxaanni gara isaatti hasaasee: nijedhe “Yaa Aadam! Gara muka (as keessa) turiinsaatiifi mootummaa hin dhabamne irratti si qajeelchuu?” [1]', '[1] hiikkaan muka yoo isa nyaatte zalaalam jannata keessa teessu, mootummaa hindhumne mootuu sigarsiisuu? jedheen sheyxaanni aadamiin.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 121, 'Isaan lamaan ishee irraa nyaatani; qaamni saalaa isaanii isaaniif mul’atte; baala jannataa irraa of irratti maxxansuu eegalan, Aadam (ajaja) Gooftaa isaa didee dogoggore.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 122, 'Eegasii Rabbiin isaa isa filatee, isaaf tawbaa qeebalee isa qajeelche.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 123, '(Rabbiin) ni jedhe: “ isin lamaanuu waliin ishee (jannata) irraa (gara dachii) gadi bu’aa, Gariin keessan gariif diina ta’aatii, Ergasii yoo Ana irraa qajeelfamni isinitti dhufe, namni qajeelfama kiyya hordofe hin jallatu; hin rakkatus.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 124, 'Namni yaadannoo (Qur’aana) kiyya irraa garagale, dhugumatti, isaaf jireenya dhiphootu jira; Guyyaa Qiyaamaas jaamaa gooneeti isa kaafna.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 125, '“Gooftaa kiyya! Odoon (addunyaa irratti) nama argu ta’ee jiruu (har’a) maaliif jaamaa gootee na kaafte?” jedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 126, '(Rabbiin) ni jedha: “Akka kanatti keeyyattoonni keenya sitti dhuftee, ishee dagatte, Atis hardha akkuma kanatti dagatamta.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 127, 'Akkuma kanatti nama daangaa dabree, keeyyattoota Gooftaa isaatti hin amanin galata galchina, azaaba Aakhiraatu irra cimaafi irra hafaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 128, 'Sila isaaniif adda hin baanee dhaloota isaaniin duraa irraa meeqaatama akka balleessine, kan isaan manneen isaanii keessa deemaa jiran, Dhugumatti kana keessa abbootii sammuutiif mallattooleetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 129, 'Odoo jechattiin Gooftaa kee irraa dabarteefi beellamni murtaa’e jiraachu baatee, silaa (adabni aaddunyaatti) isaan qabaa ta’a ture.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 130, 'Waan isaan jedhan irratti obsi, Gooftaa kee galatoomfataa faarsi baha biiftuu duraafi lixa ishee dura. Yeroo halkaniitiifi qarqara guyyaa irraas (Isa) qulqulleessi, (Kunis mindaa inni siif kennu) akka jaallattuufi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 131, 'Ija kee lamaan hin diriirsin gara waan Nuti isaaniin qananiifnee, gareewwan adda addaa isaan irraa ta’an.kan miidhagina jireenya addunyaa ta’ee, akka isa keessatti isaan mokkoruuf jecha, Kennaa Rabbii keetiitu caalaafi irra hafaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 132, 'Maatii kee salaatatti ajaji; ishee irrattis obsi, Nuti hiree si hin gaafannu, Nutu si soora. Booddeen (gaariin) warra Rabbi sodaatuufi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 133, 'Ni jedhan: “Maaliif Gooftaa isaa irraa mallattoon nutti hin dhufne?” Sila ragaan ifa taate kan kitaabota durii keessa jirtu isaanitti hin dhufnee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 134, 'Odoo Nuti isa (Rasuula -SAW) dura adabbiin isaan balleessinee, silaa ni jedhu turan: “Gooftaa keenya! Odoo ergamaa gara keenyatti ergitee, silaa odoo salphinaafi xiqqeenyi nu hin mudatin dura keeyyattoota kee hordofna turre.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 135, '(Yaa Muhammad!): jedhi “Hunduu eegaadha, Isinis eegaa, Namni warra karaa sirrii ta’eefi namni qajeele (nuufii isin keessaa) eenyuun akka ta’e beekuuf jirtu”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 1, 'Namootaaf,qormaanni isaanii isaaniif dhihaatee jira, odoo isaan daguu keessatti gara galanii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 2, 'Gorsi haaraan Rabbii isaanii irraa isaanitti hin dhufu, kan isaan taphachaatuma isa dhaggeeffatan ta’an malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 3, 'Onneewwan isaanii dagattuu taatee malee (hin dhaggeeffattu), Miidhaa hojjattoonnis marii dhooyfatan,“Sila kun namuma akka keessaniitii mitii? Sila isin odoo argitan falfalatti dhaqxuu?" (waliin jedhu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 4, '(Muhammad-SAW) ni jedhe: “Gooftaan kiyya jecha samiifi dachii keessatti (dubbatamu hunda) ni beeka. Innis dhaga’aa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 5, 'Isaan ni jedhan: “(Qur’aanni) kun abjuu laaqamaadha, Lakkii! Soba inni of irraa uumee, Lakkii! Inni weellisaadha, (Yoo dhugaa ta’e) raajii akka warri durii ittiin ergameen nutti haa dhufu”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 6, 'Gandi Nuti ishee balleessine tokkolleen isaaniin duratti hin amanne; sila isaan ni amanuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 7, 'Si dura dhiirota wahyii gara isaanii goonu malee hin ergine, Yoo kan hin beekne taatan warra beekumsaa gaafadhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 8, 'Nuti isaan (ergamoota Rabbii) qaamota nyaata hin nyaanne hin taasifnes; kan (addunyaa keessa) zalaalam jiraatanis hin taane', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 9, 'Eegasii waadicha isaaniif dhugaa goonee, isaaniifi nama feenes ni baraarsinee; daanga dabartoota immoo ni balleessine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 10, 'Dhugumatti, Nuti kitaaba yaadannoon (gorsi) keessan isa keessa jiru gara keessanitti buufnee jirra, Sila hin xiinxaltanuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 11, '(Warra) gandaa miidhaa hojjattu taatee baay''ee balleessine; erga isheetii ummata biraa uumne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 12, 'Yeroo adabbii keenya argan, yeroma san isaan ishee irraa gulufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 13, 'Hin gulufinaa, gara waan isa keessatti qanansiifamtaniifi (gara) manneen keessanii deebi’aa akka gaafatamtaniif jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 14, '(Isaan) ni jedhan: “Yaa badii keenya! nuti miidhaa hojjattoota turre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 15, '(Jechi nuti miidhaa raawwattoota taane jedhu) sun watwaata isaanii ta’uu irraa hin deemne Hanga haamamoo, dhaamoo isaan taasifnutti .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 16, 'Nuti samii, dachiifi wantoota isaan lamaan gidduu jiran taphattoota taanee hin uumne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 17, 'Odoo tapha godhachuu feenee silaa of biraa isa taasifanna; kana hojjatoo hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 18, 'Lakkii; dhugaa soba irratti darbina (ol taasifna)Sammuu isa dhoosee (isa balleessa); yoosuu inni (sobni) dhabamaadha. Isiniif waan (Rabbi) irratti uumtaniif badiitu (mirkanaa’ee) jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 19, 'Wantoonni samiileefi dachii keessa jiran hundi kan Isaati. Isaan Isa (Allaah) bira jiranis (maleykonnis) Isa gabbaruu irraa hin boonan; hin hifatanis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 20, 'Halkaniifi guyyaa (Rabbiin) qulqulleessu; hin boqatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 21, 'Sila gabbaramtoota (gabbaran), dachii irraa godhatuu? kanneen (namoota) du’aa kaasan,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 22, 'Odoo isaan lamaan (samiifi dachii) keessa Rabbiin malee gabbaramtoonni biraa jiraatanii lamaan isaaniituu ni badu ture, Rabbiin Gooftaa Arshii ta’e waan kaafiroonni (Isaan) jedhan irraa qulqullaa’e!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 23, 'Inni waan dalagu irraa hin gaafatamu; isaan immoo ni gaafatamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 24, 'Sila isaan Rabbiin ala gabbaramtoota taasifatuu? “Ragaa keessan fidadhaa” jedhiin, Kun gorsa namoota ana waliin jiraniifi gorsa namoota ana dura turaniiti, Garuu irra hedduun isaanii dhugaa hin beekanu, Kanaafuu (isa) irraa garagalu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 25, '(Yaa Muhammad!) Si dura ergamaa irraa tokkoyyuu “Ana malee dhugaan gabbaramaan hin jiru, Ana (qofa) gabbaraa” jechuun wahyii gara isaatti buufnu malee hin ergine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 26, 'Isaan “Rahmaan ilma godhate” jedhu, Inni qulqullaa’eera, Lakkii isaan (maleykoonni) gabroota (Rabbii) kabajamoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 27, 'Jechaan Isa hin dursanu; isaan ajaja Isaatiin hojjatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 28, 'Inni waan isaaniin duraatiifi waan isaaniin duubaas ni beeka, Nama Inni jaalateef malee isaan hin manguddoomanu, Isaan (ofiifuu) sodaa Isaa (Allaah) irraa rifatoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 29, 'Isaan irraa nama “Isaan alatti anatu gabbaramaadha” jedhe, isa sana jahannam isaaf galata galchina, Akkasitti miidhaa hojjattoota galata galchina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 30, 'Sila isaan kafaran akka samiifi dachiin walitti maxxantuu turanii, ergasii addaan isaan baafne hin beekanuu? Bishaan irraa lubbu qabeeyyii hunda ni uumne, Sila hin amananuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 31, 'Dachii keessatti akka isheen isaaniin hin sochoone gaarreen (lafa qabataa) taasifneerra, Ishee keessatti daandiwwan gugurdaa akka ittiin qajeelaniif isaaniif taasifneerra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 32, 'Samiilee qaaxee (jaarmaya kan gubbaa) eegamaa isa taasifnee jirra, Garuu isaan mallattoolee ishee irraa garagaloodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 33, 'Inni Isa halkaniifi guyyaa, aduufi baatii uumeedha; hunduu orbitii (isaanii) keessa daaku (deemu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 34, '(Yaa Muhammad!) Si dura ilma namaatiif jireenya waaru (zalaalam) hin taasifne, Sila yoo ati duute, isaan ni waaruu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 35, 'Lubbuun hundi du’a dhandhamtuudha. Isin qormaatuuf hamtuufi gaariin isin mokkorra, Garuma keenyatti deebifamtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 36, 'Isaan kafaran yeroo si argan “sila kun isa gabbaramtoota keessan (hamtuun) maqaa dhahu sani mitii?” (jechuun) qishnaa qofa si taasifatu, isaan faaruu Rahmaanitti isaanumaatu kafaroodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 37, 'Namni jarjara irraa uumame, Ani mallattoolee tiyya isinittin agarsiisaa, nan jerjersiifatinaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 38, '“Yoo kan dhugaa dubbattan taataniif, waadaan kun yoom? jedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 39, 'Isaan kafaran odoo yeroo ibidda fuulleen isaanii irraafi dugdawwan isaanii irraa qabuu hin dandeenyeefi tumsas hin arganne san beekanii (hin jerjerfatanu ture).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 40, 'Dhugumaatti, isheen (Qiyaaman) tasuma isaanitti dhuftee, isaan dhamaafti, Ishee (of irraa) deebisuu hin danda’anu; yeroonis isaaniif hin kennamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 41, 'Dhugumatti, ergamtoota si duraatti qishnamee (baacamee). isaan irraa warri baacan wanti isaan itti qishnaa turan isaan marse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 42, 'Jedhi: “Eenyutu halkaniifi guyyaa (adabbii) Rahmaan irraa isin eega?” Dhugumatti, isaan yaadannoo Rabbii isaanii irraa garagaloodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 43, 'Moo isaaniif gabbaramtoota Nu irraa isaan tiksantu tahee? Lubbuulee isaaniitiifuu tumsuu hin danda’anu, Isaan Nu irraa tikfamoo hintaane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 44, 'Dhugumatti, Nuti isaan kanaafi abbootii isaaniis hanga yeroon isaan irratti dheeratutti qanansiifne, Sila Nuti dachii moggaalee ishee irraa (suuta suutaan) hirdhisaa akka deemnu hin arganuu? Moo isaantu injifatoodhaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 45, '(Yaa Muhammad!) Jedhi: “Kan ani isin sodaachisuun wahyii qofaani. duudaan yaamicha hindhagayu, yeroo dinniinaman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 46, 'Qoonni adabbii Gooftaa kee irraa ta’e yoo isaan tuqe ni jedhu: “Yaa badii keenya! nuti miidhaa raawwattoota turreerra.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 47, 'Nuti Guyyaa Qiyaamatiif miizaana haqaa lafa keenya. Lubbuun takkas homaa hin miidhamtu. Yoo (waan) ulfina (hanga) firii (ija) raafuu (takka)(qabu) ta’es Nuti ishee ni fidna. Qormaataaf Nuti ga’oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 48, 'Dhugumatti, Nuti Muusaafi Haaruuniif (kitaaba) adda baasaa, ifnanaafi yaadannoo warra Rabbiin sodaataniif ta’e kenninee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 49, '(Isaan) warra Gooftaa isaanii fageenyatti sodaataniifi isaan Qiyaamaa irraa sodaataniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 50, 'Kun (Qur’aanni) gorsa barakeeffamaa Nuti buufneedha, Sila isin isaaf mormitootaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 51, 'Dhugumatti, Nuti kana dura qajeelfama isaa Ibraahiimiif kenninee jirra. Nuti isa beekoo taanee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 52, 'Yeroo inni abbaafi ummata isaatiin “Siidaawwan isin (Ibaadaaf) ishee irra teessan tun maali?” jedhe (kennineef).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 53, '[Isaan] ni jedhan: “Abbootii keenya kan ishee gabbaran agarre.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 54, '[Inni] ni jedhe: “Dhugumatti, isiniifi abbootiin keessanis jallina ifa bahaa keessa jirtan.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 55, '[Isaan] ni jedhaniin: “Sila dhugaan nutti dhufte moo ati warra taphatan irraayi?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 56, 'Ni jedhe: “Baraa, Rabbiin keessan Gooftaa samiileefi dachiiti, kan isaan uume sani, Ani kana irratti ragaa bahootarraayi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 57, '“Allaah’n kakadhee! Ani erga isin dugda gara galtanii deemtan booda dhugumatti, tooftaan ittiin taabotoota keessan (mancaasun) qopheeffadha” (of keessatti jedhe).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 58, 'caccabaa isaan godhe. guddaa isaaniif ta’e malee (isa nihanbise) Akka isaan gara isaa (taabota guddichaa) deebi''aniif jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 59, '(Isaan) ni jedhan: “Namni gabbaramtoota keenyatti kana hojjate dhugumatti, inni miidhaa raawwattoota irraayi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 60, 'Nijedhan “Dargaggeessa Ibraahiim isaan jedhamu (tokko) kan (hamtuun) isaan dubbatu dhageenyeerra”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 61, 'Ni jedhan: “ijoowwan namootaa dura isa fidaa, Akka isaan ragaa (irratti) bahaniif jecha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 62, '“Sila situ gabbaramtoota keenya irratti (yakka) kana raawwatee Yaa Ibraahiim?” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 63, '(Ibraahiimis) “Lakkii, guddaa isaaniitu kana hojjate, Yoo kan dubbatan ta’aniif isaan gaafadhaa” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 64, 'Gara lubbuulee isaanii deebi’anii “isin isinumatu miidhaa raawwattoota” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 65, 'Eegasii mataalee isaanii lafatti gadi deebisanii “ati dhugumatti, isaan kun hin dubbatanuu beektee jirta (maaliif kana jetta?)” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 66, '(Ibraahiim) ni jedhe: “Sila Rabbii achitti waan homaa isin hin fayyadneefi isin hin miine gabbartuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 67, 'Isiniifi wantoota isin Allaah’n ala gabbartaniinis ‘uffi’ (jedheera)! Sila hin xiinxaltanuu?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 68, 'Ni jedhan: “ isa gubaa; gabbaramtoota keessaniif tumsaa. Yoo kan hojjattan taataniif”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 69, 'Nijenne “Yaa ibiddaa! Ibraahiim irratti qabbanaafi nagaa ta’i".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 70, 'Hamtuu isatti fedhan, irra hoonga’oo isaan goone.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 71, 'Isaafi Luuxiin gara dachii ishee keessa aalama hundaaf barakaa gooneetti nagaya baafne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 72, 'Isihaaqiin isaaf kenninee, Ya’aquubis dabalataan (isaaf kennine) Hundaayyuu gaggaarii goone.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 73, 'Imaamota ajaja keenyaan qajeelchan isaan taasifnee jirra. toltuuwwan hojjachuu, salaata dhaabuufi zakaa baafachuu gara isaanitti wahyii goone. nuuf gabbartoota turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 74, 'Luuxiin murtii haqaafi beekumsa (amantii) isaaf kenninee jirra. (Ummata) ganda badii fokkatoo hojjattu irraa isa baraarsinee jirra. isaan ummata badoo, finciltoota turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 75, 'Rahmata keenya keessas isa seensifne. inni warra gaggaarii irraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 76, 'Nuuhiinis ‘yeroo inni sana dura (Nutti) lallabee isaaf owwaannee, isaafi maatii isaas cinqaa guddaa irraa baraarsine’ [yaadadhu]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 77, 'Namoota keeyyattoota keenya sobsiisan irraas nagaya isa baafne, isaan warra hamtuu turan. hunda isaanii bishaaniin dhidhimsiifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 78, 'Daawuudiifi Suleeymaaniinis ‘yeroo isaan lamaan lafa qonnaa (oyruu) re’oonni ummataa (halkan) dheedan keessatti murtii kennan” [yaadadhu], Nuti murtii isaanii ni beekna turre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 79, 'Ishee (murtittii) Suleeymaaniin hubachiifne, Hundaafuu (beekumsa murtii) haqaafi beekumsa (amantiis) kennineerra. Gaarreen Daawuudii waliin akka na qulqulleessan laaffifne, allaattis. Nuti hojjatoo taane', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 80, 'Uffata sibiilaa kan isiniif tahe isa barsiifne. lola keessanirraa akka isin tiiysituuf jecha, Sila isin (Nu) galatoomfattootaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 81, 'Suleeymaanifis qilleensa bubbisaa, kan ajaja isaatiin gara dachii ishee keessatti barakaa goonee yaatu (laaffifnee jirra). Nuti waan hunda beekoo taaneerra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 82, 'Sheyxaanota irraa isaan (faaya baasuuf garba keessa) isaaf lixaniifi sana malees hojii biraa hojjatantu jira. Nuti tiksoo isaanii taaneerra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 83, 'Ayyuubiinis ‘yeroo inni Gooftaa isaatti lallabee “ani rakkoon na tuqeera; Ati irra rahmata godhaa warra rahmata godhaniiti” (jedhu yaadadhu)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 84, 'Isaaf owwaannee cinqaa irraa waan isarra jiru irraa furre. maatii isaatiifi fakkaataa isaaniis isaanii wajjin isaaf kennine, Rahmata Nu biraa ta''eefi warra Rabbiin gabbaran yaadachisuuf jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 85, 'Ismaa’iil, Idriisiifi Zalkifliis (yaadadhu); hunduu obsitoota irraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 86, 'Rahmata keenya keessas isaan seensifne, isaan warra gaggaarii irraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 87, 'Zannuuniinis (Yuunusiinis yaadadhu); yeroo inni dallanaa deemee, Nuti isa irratti dhiphisuu dhabuu yaade. Dukkana keessaa “Si malee dhugaan gabbaramaan hin jiru, Ati qulqulloofte, Dhugumatti, ani miidhaa hojjataa irraa ta’een jira” (jechuun) lallabe', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 88, 'Isaaf owwaanne; cinqaa irraas isa baraarsine, Akka kanatti mu’uminoota nagaa baafna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 89, 'Zakariyyaas (yaadadhu); yeroo inni Gooftaa isaatti lallabee “Gooftaa kiyya! Kophaa (ilma malee) nan dhiisin; Ati irra caalaa dhaaltotaati” (jedhe).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 90, 'Isaaf owwaannee Yahyaa isaaf kennine, Niitii isaas (akka deessu) isaaf tolchine, Isaan (nabiyy-oonni) toltuu keessatti kan daddafan ta''an, kajeellaafi sodaan (guutamanii) kan Nu kadhatan turan, Nuuf sodaatoo turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 91, 'Ishee qaama saalaa ishee tikfattes (Maryamiinis yaadadhu). Ruuhii (uumama) keenya irraa ta’e ishee keessatti afuufne, Isheefi ilma ishees aalamootaaf mallattoo taasifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 92, 'Isheen tun amantii keessan amantii tokkittiidha, Ani Gooftaa keessanii Ana (qofa) gabbaraa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 93, 'Amantii isaanii keessatti jidduu isaaniitti adda qoodaman, Hunduu gara keenya deebi’oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 94, 'Namni mu’umina ta’ee gaggaarii irraa hojjate, hojii isaa hoonga’uun hin jiru, Nuti isaaf galmeessaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 95, 'Ganda ishee balleessine irratti (duniyatti deebi''uun) dhorgaadha; isaan hin deebi''an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 96, 'Hanga yeroo (hidhaan) Ya’ajuujiifi Ma’ajuuj banamtee isaan tabba hunda irraan dhangala’anuutti (hin deebi''anu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 97, 'Waadaan dhugaa dhihaatee jira, Yeroo san ijjoowwan warra kafaree akkuma banamtetti haftuudha, “Yaa badii keenya! Dhugumatti, nuti kana irraa daguu keessa turre (Yoom kana qofa) inumaa miidhaa raawwattoota taane" (jedhu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 98, 'Isiniifi wantoonni isin Rabbiin ala gabbartanis qoraan (ibidda) jahannami; isin ishee (Jahannam) seenoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 99, 'Isaan (taabotoonni) kunniin odoo gabbaramtoota ta’anii silaa ishee hin seenan ture, Hundi isaanii ishee keessatti waaru (hafu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 100, 'Isaaniif ishee keessatti halaaka (iyyaansa) harreetu jira; isaan ishee keessatti hin dhaga’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 101, 'Warra Nurraa milkiin isaaniif dabarte, isaan sun ishee irraa fageeffamoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 102, 'Sagalee (didichaa) ishee hin dhaga’anu, Isaan waan lubbuun isaanii jaallattu keessatti hafoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 103, '(Guyyaa Qiyaamaa) naasuun guddaan isaan hin gaddisiisu, Maleykonni isaan simatu. “Kun guyyaa keessan kan baallamamoo taataniidha.” (jedhaniin)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 104, 'Guyyaa samii marru akka mariinsa barreessan xalayaalee (galmeewwan) marutti [yaadadhu]. Akkuma uumaa duraa jalqabnetti isa deebifna. (Kun) waadaa Nu irra jiruudha. Dhugumatti, Nuti raawwattoota taanee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 105, 'Dhugumatti, Nuti kitaabota keessatti barreessine, erga ‘Lawhal Mahfuuz’ (keessatti barreessinee) booda. “dachii gabroota kiyya gaggaariitu dhaalaa” (jechuu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 106, 'Dhugumatti, (Qur’aana) kana keessa ergaa ga''aa ta’etu orma (Rabbiin) gabbaraniif jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 107, 'Aalama (hundaaf) rahmata taasifnee malee (waan) si hin ergine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 108, '(Yaa Muhammad!) Jedhi: “Ani wanti gara kiyyatti wahyii godhamu ‘dhugaan gabbaramaan keessan gabbaramaa tokkicha’ (kan jedhuu dha)Sila isin Muslimoota hin taatanuu ree?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 109, 'Yoo gara galan “Ani ifaan ifatti isin beeksise, Ani wanti waadaa isiniif galame dhihoo moo, fagoo ta’aa isaa hin beeku” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 110, 'Dhugumatti, Inni jecha ol fuudhamaa ni beeka, Waan isin dhoksitanis ni beeka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 111, 'Ani inni (an isinitti himu kun) mokkoroo isiniif ta’uufi qananii yeroo gabaabaa (isiniif) ta’aa hin beeku.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 112, '(Muhammad) ni jedhe: “(Yaa) Rabbi! (Anaafi warra ana sobsiisan giddutti) dhugaan murtii godhi, Gooftaan keenya Rahmaani, waan isin jettan irratti gargaarsifatamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 1, 'Isin yaa ilmaan namaa Gooftaa keessan sodaadhaa, sochiin (lafaa) kan Qiyaamaa waan guddaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 2, 'Guyyaa ishee argitan, dubartiin hoosiftu hundi waan hoosiftu irraa ni dagatti (Dubartiin) ulfa qabdu hundi ulfa ishee garaa darbiti. Namoota (sodaa irraa) machaa’oo agarta, Isaan waa machaa''oo miti. Garuu azaaba Rabbiitu garmalee cimaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 3, 'Namoota irraa nama waa''ee Rabbii keessatti beekumsa malee falmujjira. sheyxaana didaa ta’e hunda hordofa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 4, 'Isa (sheyxaana) irratti ‘inni nama isa jaalallee godhate kamillee ni jallisa; gara ibidda qabsiifamaa isa qajeelcha’ jechuun barreeffamee jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 5, 'Yaa namootaa! Yoo kaafamuu irraa shakkii keessa jiraattan, Nuti biyyee irraa isin uumnee; ergasii copha bishaan saalaa irraa, eegasii dhiiga ititaa irraa, ergasii foon alalfatamu kan uumaa guuttateefi hin guuttatin (irraa isin uumne); (humnaafi dandeettii keenya) isiniif ibsuuf (kana goone). Nuti waan (abbaa) feene hanga qaaxaroo maqaa dhawamaa taheetti gadaamessaalee keessa teessifna, ergasii daa’ima goonee isin baafna (dhalachiifna). Ergasii akka umrii jabinaa keessan irra geessaniif (isin jiraachifna). Isin irraa nama (umrii ijoollummaatiin) du’utu jira. isin irraa nama gara umrii gadi aanaa deebi''utu jira Erga beekkomsaatii akka homaa hin beekneef, Dachii gogduu taatee agarta; yeroo Nuti bishaan (bokkaa) ishee irratti buufne ni sochooti; ni iitoftis, akaakuu marga bareedaa irraas ni magarsiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 6, 'Sun waan Rabbiin, Isatu dhugaa ta’eefi inni du''aa kaasa. Inni waan hunda irratti danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 7, 'Qiyaamaan dhuftuudha; ishee keessa mamiin hin jiru. Rabbiin kanneen qabriilee keessa jiran (hunda) ni kaasa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 8, 'Namoota irraa kan beekumsa malee (waa''ee) Rabbii keessatti falmutu jira. (akkasuma) qajeelfamaafi kitaaba (ergaa Rabbii) ibsu malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 9, 'Morma isaa maree (namoota) karaa Rabbii irraa jallisuuf (nama falmutu jira). Isaaf addunyaa kana keessatti salphinatu jira. Guyyaa Qiyaamaa azaaba gubaa ta’e isa dhandhamsiifna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 10, '“Kun waan harki kee lamaan hojjataniif” (isaan jedhama). Dhugumatti, Allaahn gabroota (Isaa) kan miidhu hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 11, 'Namoota irraa nama amantii irraa moggaatti ta’ee (shakkiin) Rabbi gabbarutu jira. Yoo toltuun isa tuqe, isatti raga’a.Yoo rakkoon isa tuqe ammoo, fuula isaa irratti garagala. Inni addunyaafi Aakhiraa hoonga’ee jira. Sun isatu hoongoo ifa bahaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 12, 'Rabbiin ala waan isa hin miineefi isa hin fayyadne kadhata, Sun isatu jallina fagoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 13, 'Nama miidhaan isaa bu’aa isaa irra dhihoo ta’e kadhata, Jaalallee ta’uun (isaa) waa fokkate! Ammas hiriyaa ta’uun (isaa) waa fokkate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 14, 'Rabbiin isaan amananii, gaggaarii dalagan Jannatoowwan laggeen ishee jala yaatu isaan seensisa, Dhugumatti Rabbiin waan fedhu hojjata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 15, 'Namni duuniyaafi Aakhiraa keessatti Rabbiin isa (Muhammadiin-SAW) hin tumsu jechuu kan yaadu tahe, gara samii haada hidhatee of haa fannisuErgasii tooftaan isaa waan inni jibbu dhabamsiisuu haa ilaalu', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 16, 'Akka kanatti keeyyattoota ifa bahaa goonee isa buufne, Rabbiin nama fedhe qajeelcha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 17, 'Dhugumatti, isaan amanan, isaan yahuudoman, saabi’oonni, kiristaanonni, majuusonniifi isaan mushrikoota ta’an; Rabbiin Guyyaa Qiyaamaa gidduu isaaniitti murteessa, Dhugumatti, Allaah’n waan hunda irratti ragaadha.[1]', '[1] asitti Rabbiin garee hedduu dubbate, saabi''oota jechuun warra amantaa takkallee hinqabne kan amantaa malee jiraatuudha. majuusaan ammoo warra ibidda gabbaru, mushriktoonni warra taabotaafii umamtoota adda addaa gabbaruudha. Rabbiin guyyaa qiyaamaa isaan jiddutti murteessa, warra isatti amane (muimintoota) jannata naqa, kaafirtoota ibidda seensisa.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 18, 'Sila ati hingarree akka Rabbiif sujuudu wanti samiilee keessa jiruufi wanti dachii keessa jiruus, (akkasuma) aduun, jiini, urjiiwwan, gaarreen, mukkeen, lubbu qabeeyyiifi hedduun namarraa tahes (sujuuda Isaaf godhan hin arginee?) (Namoota) baay’ee azaabni isa irratti mirkanaa’ee jira, Nama Rabbiin isa salphise immoo namni isa kabaju hin jiru, Dhugumatti, Rabbiin waan fedhe hojjata. [1]', '[1] bakka tanas sujuuda qaraatii (tilaawaattu) jira.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 19, 'Gareen kun lamaan warra Rabbii isaanii keessatti wal falmaniidha, Isaan kafaran uffata ibidda irraa ta’etu isaaniif murame. mataalee isaanii gubbaas bishaan danfaatu itti naqama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 20, 'Isa sanaan wanti garaalee isaanii keessa jiruufi gogaaleen (isaanii) bayfama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 21, 'Jirma sibiila irraa ta’etu isaaniif jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 22, 'Dhawaata isaan ishee irraa ba’uu fedhaniin yaaddoodhaan ishee keessatti deebifaman, “Adaba gubaa dhandhamaa” (jedhamani).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 23, 'Rabbiin warreen amananii, gaggaarii hojjatan Jannata laggeen jala ishee yaatu seensisa, Ishee keessatti gumeewwan (kilkillee) warqeefi faaya irraa ta’an uffifamu. Uffanni isaanii ishee keessatti hariira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 24, '(Addunyaa kana keessatti) gara jecha gaarii qajeelfaman, gara karaa (Rabbii) faarfamaa ta’eetti qajeelfaman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 25, 'Dhugumatti, isaan kafaranii, karaa Rabbiitiifi masjiida kabajamaa isa namoota isa (Makkaan) keessa jiraataniifi kan biyyoota biraa irraa dhufaniif wal qixa goone irraa (namoota) dhorgan (hoonga’an). Namni isa keessatti sababa miidhaatiin jallachuu barbaade azaaba laalessaa irraa isa dhandhamsiifna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 26, 'Yeroo Ibraahiimitti iddoo manaa (Ka''abaa) mul’ifnee “homaa Natti hin qindeessin; Mana Kiyyas namoota naannawaniif, isaan (salaataaf) dhaabbataniif, isaan rukuu’a godhaniifi sujuuda bu’aniif qulqulleessi” (jennes dubbadhu.)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 27, '(Sirna) hajjii (akka raawwatan) namoota keessatti lallabi (Namoonnis sirnicha raawwachuuf) miilaafi geejjiba huqqifaman hunda irra ta’anii, daandiiwwan fagoo irraa sitti dhufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 28, 'Bu’aalee isaanii irratti akka hirmaataniif,akka maqaa Rabbii dubbataniif guyyoota beekamoo ta''an keessatti beyladoota irraa waan Rabbiin isaanii kenne irratti (dubbataniif) (beeksisi). Ishee irraa nyaadhaa; hiyyeessa rakkataa nyaachisaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 29, 'Sana booda xuriiwwan isaanii haa dhabamsiisan; qodhaawwan isaaniis haa guutanii. Mana turaan (Ka’abaan) haa naanna’anii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 30, '(Dubbiin) sanuma! Namni wantoota Rabbiin kabaje guddise, sanatu isaaf caala Gooftaa isaa biratti, beyladoonni isiniif eeyyamamte Isaan (of duratti) isiniif ibsamuuf (jiran) malee. Xurii taabotaa irraa fagaadhaa Jecha cubbuu irraas fagaadhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 31, 'Rabbiif qajeeloo haala taataniin odoo homaa Isatti hin qindeessin (fagaadhaa). Namni Rabbitti waa dabale, akka nama samii irraa kufee allaattiin isa buttee yookiin bubbeen iddoo fagootti isa gatteeti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 32, '(Dubbiin) sanuma! Namni mallattoolee (amantii) Rabbii kabaje, isheen onneewwan sodaa (Rabbii) qabaachuu irraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 33, 'Isiniif ishee (beyladoota wareegaa) keessa faaydaaleetu jira hanga beellama murtaa’eetti. Sana booda iddoon ishee (bakkiti itti qalamtu) gara Mana turaa (daangaa harama Makkaa)ti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 34, 'Ummata hundaafuu bakka qalmaa (isaaniif) taasifnee jirraa, akka horii Inni isaaniif kenne irratti maqaa Isaa faarsaniif jecha, gabbaramaan keessanis Gooftaa tokkicha, Isaaf harka kennaa, Warra Isaaf gad of qaban gammachiisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 35, 'Isaan warra yeroo Rabbiin dubbatame onneewwan isaanii sodaattu, waan isaan tuqe irratti obsitoota tahan, salaata dhaabdota tahan,kan waan isaaniif kennine irraa kennaniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 36, 'Beeyladoota (wareega Ka’abaa)ishee mallattoolee Rabbii irraa isiniif goone, Ishee keessa gaggaariitu isiniif jira, Odoo sakaalamanii jiranuu maqaa Rabbii ishee irratti faarsaa, Yeroo cinaachi ishee kufte ishee irraa nyaadhaa; hiyyeessa nama hin kadhanneefi isa kadhatu nyaachisaa, Nuti akka kanatti ishee (beeyladoota) isiniif laaffifne. Akka isin galata galchitaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 37, 'Foonoowwan isaaniitiifi dhiigowwani isaaniis Rabbiin bira hin ga’u, Garuu sodaa Rabbii kan isin biraa ta’etu Isa bira ga’a. Akka kanatti ishee isiniif laaffise, akka Rabbiin guddiftaniif, waan isin qajeelcheef jecha. Gaarii hojjattoota gammachiisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 38, 'Rabbiin isaan amanan irraa ni ittisa, nama akkaan gantuu, kafaraa ta''e hunda Rabbiin hin jaallatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 39, 'Warra lolaman sababa miidhamuu isaaniitiif (loluun) hayyamni godhameef, dhugumatti Rabbiin isaaniif tumsuu irratti danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 40, 'Isaan warra manneen isaanii irraa haqaan ala waan “Rabbiin keenya Allaahdha” jedhaniif qofa baafamaniidha, Odoo Rabbiin namoota garii isaanii gariin deebisuun jiraachuu baatee, silaa iddoon moloksee, bataskaanoleen kiristaanootaa, iddoon ibaadaa Yahuudotaafi masjiidonni maqaan Rabbii hedduu keessatti faarfamu ni diigamu turan. Dhugumatti Rabbiin nama (amantii) Isaaf tumsu, tumsuufiif jira. Rabbiin irra jabaa, injifataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 41, 'Isaan warra yoo Nuti dachii keessatti isaaniif mijeessine salaata dhaaban, zakaa kennan, toltuutti (namoota) ajajaniifi hamtuu irraa (namoota) dhorganiidha. Booddeen waan hundaa Rabbumaafi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 42, 'Yoo si sobsiisan, isaaniin duras ummanni Nuuh, Aadiifi Samuud (nabiyyoota isaanii) sobsiisanii jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 43, 'Ummanni Ibraahiimiifi ummanni Luuxis (akkasuma).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 44, 'Jiraattonni Madyanis (akkasuma), Muusaanis sobsiifamee jira, Ani kaafirootaaf yeroo gabaabaa kenneetan sana booda isaan qabe, adabbiin kiyya akkam (hamaa) dha!.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 45, 'Magaalota irraa meeqaatama odoo isheen miidhaa hojjattuu taatee jirtuu ishee balleessine. Isheen qaaxeewwan ishee irratti kukkuftuudha. Eela onteefi Gamoowwan dhedheeraa (meeqa duwwaa dhiifne).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 46, 'Sila isaan (Mushrikoonni Makkaa) dachii keessa hin deemnee? Onneewwan ittiin waa hubatan yookiin gurri ittiin waa dhagayan isaaniif ta''a. ijji (gubbaa kuni) hinjaamtu. garuu onneewwan qomaalee keessa jirtuuru jaama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 47, 'Adabatti si jarjarfatu, Rabbiin waadaa Isaa hin diigu, Dhugumatti, guyyaan tokko Rabbii kee biratti akka waggaa kumaati waan isin lakkooftan irraa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 48, 'Magaalota irraa meeqaatama tan Ani yeroo isheef kennee, haala isaan miidhaa hojjatoo ta’anii jiraniin ergasii (adabaan) ishee qabee, deebiin gara kiyya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 49, '(Yaa Muhammad!) Jedhi: “Yaa namootaa! Ani isiniif sodaachisaa ifa bahaa malee hin taane.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 50, 'Isaan amananii, gaggaarii hojjatan, isaaniif araaramaafi kennaa gaariitu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 51, 'Isaan Nu dadhabsiisuu (yaadanii) aayatoota keenya balleessuuf hojjatan, isaan sun warra jahannami.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 52, 'Nuti si dura ergamaas ta’ee nabiyyii tokko erginee ‘yeroo inni dubbise sheyxaanni dubbisa isaa keessa (gurra ummataa irratti soba) darbu malee’ kan hafu hin taane, Rabbiin waan sheyxaanni itti darbu san ni balleessa, Sana booda aayatoota isaa ni raggaasisa, Rabbiin beekaa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 53, 'Waan sheyxaanni darbu san isaan onneewwan isaanii keessa dhukkubni jiruufi warra onneewwan isaanii gogeef qormaata gochuuf (akkas taasise). Dhugumatti, miidhaa hojjattoonni wal diddaa fagoo ta’e keessa jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 54, 'Akka isaan beekumsa kennaman dhugaa Rabbii kee irraa dhufe ta’uu isaa beekanii isatti amananii, onneeWWAn isaanii isatti tasgabbii argattuuf (kana taasise). Dhugumatti, Rabbiin isaan amanan gara karaa sirrii qajeelchaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 55, 'Isaan kafaran waa’ee isaa (Qur’aanaa) irraa shakkuu irraa hin deeman. Hanga Qiyaamaan tasa isaanitti dhufutti yookiin (hanga) adabbiin guyyaa maseenaa (isa booda halkan hin jirree) isaanitti dhufutti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 56, 'Mootummaan guyyaa san kan Allaahti, Gidduu isaaniitti ni murteessa, Isaan amananii, gaggaarii hojjatan Jannata qananii keessa ta’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 57, 'Isaan kafaranii, keeyyattoota keenya sobsiisan, warri sun adabbii (jahannam kan) salphisaa ta’etu isaaniif jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 58, 'Isaan karaa Rabbii keessatti godaananii, ergasii ajjeefaman yookiin du’an, dhugumatti, Rabbiin kennaa gaarii isaanii kennuuf jira, Rabbiin Isatu irra caalaa kennitootaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 59, 'Dhugumatti, Inni isaan seensa isa jaallatan seensisa, Dhugumatti, Rabbiin beekaa, obsaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 60, '(Dubbiin) akkana Namni fakkaataa waan ittiin miidhameetiin haaloo bahatee, ergasii isa irratti itti roorrifame, dhugumatti, Rabbiin isa tumsa, Rabbiin irra namaaf dabraa, araaramaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 61, 'Sun waan Rabbiin halkan guyyaa keessa seensisuufi guyyaas halkan keessa seensisuufi, Rabbiin dhaga’aa, argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 62, 'Kun waan Rabbiin, Inni (gabbaramaa) dhugaa ta’ee, wantoonni isaan Isaa gaditti gabbaran immoo isa sobaa ta’ee, Rabbiin Isatu ol ta’aa, guddaa ta''eefi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 63, 'Sila akka Rabbiin samii irraa bishaan buusee, dachiin (isaan) magariisa taate hin arginee? Rabbiin rahmata godhaa, keessa beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 64, 'Wantoonni samiilee keessa jiraniifi wantoonni dachii keessa jiran hundi kan Isaati, Rabbiin Isatu dureessa, faarfamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 65, 'Sila akka Allaahn wantoota dachii keessa jiran isiniif mijeesse hin arginee, dooniwwan galaana keessa ajaja Isaatiin daakanillee Eeyyama Isaatiin yoo ta''e malee akka samiin dachii irratti hin kufne qaba, Rabbiin namootaaf akkaan mararfataa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 66, 'Inni Isa isin jiraachisee, sana booda isin ajjeesee, Sana booda isin jiraachisuudha, ilmi namaa akkaan (Rabbitti) kafaraadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 67, 'Ummata hundaaf seera isaan amantii ittiin geggeeffatan isaaniif taasifnee jirra. Kanaafuu (mushrikoonni) dhimma kana irratti akka siin hin falmine. Gara Gooftaa keetiitti waami. Ati karaa qajeelaa irra jirta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 68, 'Yoo siin falman “Rabbiin akkaan beekaa waan isin hojjattaniiti” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 69, 'Rabbiin Guyyaa Qiyaamaa waan isin isa keessatti wal dhabaa turtan gidduu keessanitti murteessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 70, 'Sila Rabbiin wantoota samiifi dachii keessa jiran hunda akka beeku hin beektuu? kun kitaaba (Lawhal Mahfuuz) keessa jira, kun Rabbi irratti laafaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 71, 'Rabbiin alatti waan Inni ragaa homaatuu isaaf hin buusiniifi waan isaan isa ilaalchisee beekumsa homaatuu hin qabne gabbaru. Miidhaa hojjattootaaf gargaaraan tokkos hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 72, 'Yeroo keeyyattoonni keenya kan ifa ta’an isaan irratti dubbifaman, fuula warra kafaranii irraa (ajaja Rabbii) diduu hubatta. Warra keeyyattoota keenya isaan irratti dubbisanitti utaaluutti dhihaatu, (Yaa Muhammad!) “Sila waan sana caalaa hamaa ta’e isiniif himuu? Ibidda Rabbiin isaan kafaraniif waadaa galeedha, Deebichi waa fokkate!” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 73, 'Yaa namootaa! Fakkeenyi taasifamee jiraa isa dhaggeeffadhaa, isaan isin Rabbiin alatti kadhattan (gabbartan) odoo isaaf walitti qabamaniillee tiisisa tokko hin uumanu, Yoo tiisisni waan tokko isaan harkaa bute, (waan) san isa irraa buusuu hin danda’anu, Gabbaraafi gabbaramaan dadhabeera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 74, 'Dhugaa guddina Isaa Rabbiin hin guddifne, Rabbiin jabaa, injifataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 75, 'Rabbiin maleykota irraa ergamoota filata; namoota irraas (ni filata), Rabbiin dhaga’aa, argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 76, 'Inni wantoota fuuldura isaaniitiifii wantoota duuba isaaniitis hunda ni beeka, Wantoonni hundi gara Rabbiitti deebifamti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 77, 'Yaa warra amantan! Rukuu’a bu’aa; sujuudas bu’aa; Gooftaa keessan gabbaraa; akka milkooftaniif toltuus hojjadhaa. [1]', '[1] bakka tanas sujuuda qaraatiittu jira. kanaan wajji suuraan tuni sujuuda lama qabdi.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 78, 'Qabsoo Isaaf malu (Karaa) Rabbii keessatti qabsaa’aa; Inni isin filateera; amantii keessatti dhiphina tokkollee isin irratti hin goone, Karaa abbaa keessan Ibraahiim (deemaa), Isatu (Rabbitu) kana duraafi (Qur’aana) kana keessattis Muslimoota isin moggaase, Akka ergamaan Rabbii isin irratti ragaa tahuufii isinis namoota irratti ragaa taataniif, (Kanaaf) salaata dhaabaa; zakaa kennaa; Rabbiin ciminaan qabadhaa. Inni jaalalloo keessani. Jaalallee ta''uuf waa tolee! Gargaaraa ta''uufis waa tole!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 1, 'Dhugumatti, mu’uminoonni milkaa’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 2, 'Isaan warra salaata isaanii keessatti khushuu’a qabaniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 3, 'Isaan warra wanta bu’aa hin qabne irraa garagalaniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 4, 'Isaan warra zakaas raawwataniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 5, 'Isaan warra qaama saalaa isaanii tikfatoo ta’aniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 6, 'Jaartiiwwan isaanii yookiin waan mirgi isaanii dhuunfatte irratti malee, isaan (kanarratti) komatamoo miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 7, 'Namni sanaan ala (waan biraa) barbaade, isaan sun daangaa dabroodha. [1]', '[1] kuni karaa jaartii ufiitiifii gabrittii ufii malee karaa biroo kamiiyyu fedhee bahuuf itti fayyadamuun haraam dhoowwaa tahuu ibsa. kanneen akka harkaan fedhii ufirraa baasuu fii beyladaan wajji qunnamtii godhuu fii wanni kana fakkaatu hundinuu haraam kana jala seena. dhoowwaadha badii guddoodha.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 8, 'Isaan warra amaanaa isaaniitiifi waadaa isaaniis tikfatoo ta’aniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 9, 'Isaan warra salaatoowwan isaanii irratti tikfatoo tahaniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 10, 'Isaan sun isaanuma qofatu dhaaltota (jannataati).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 11, 'Isaan warra Firdawsiin dhaalanu. isaan ishee keessatti hafoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 12, 'Dhugumatti, Nuti ilma namaa qulqulluu (cunfaa) dhoqqee irraa ta''e irraa uumne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 13, 'Sana booda coba bishaan saalaa kan iddoo tasgabbaa’aa, mijaa''aa (gadaamessa) keessatti isa taasifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 14, 'Sana booda bishaan saalaa dhiiga ititaa taasifne; ergasii dhiiga ititaa muraa foonii taasifne; ergasii foonittii (sana) lafee taasifne; ergasii lafees foon itti uffifne; sana booda uumama biraa (daa’ima) isa goone, Rabbiin irra tolchaa uumtotaa ta’e qulqullaa’e!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 15, 'Eegasii Isin sana booda du’oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 16, 'Eegasii isin Guyyaa Qiyaamaa ni kaafamtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 17, 'dhugumatti, Nuti gubbaa keessanitti samii torba uumnee jirra, Nuti uumamtoota irraa kan dagannu hin taane', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 18, 'Samii irraa bishaan (rooba) hanga (barbaachisaa ta’een) buufnee. ergasii dachii keessa isa kuufne. Dhugumatti, Nuti isa deemsisuu irratti danda’oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 19, 'Isaan iddoowwan ashaakiltii isiniif magarsine, kan mukkeen timiraafi inabaa kan ishee keessa isiniif fuduraaleen heddu jiraniifi isin ishee irraa nyaattan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 20, 'Muka gaara Xuuru siinaa irraa baatu (margitu), kan dhadhaa (dibatamu) biqilchituufi warra nyaataniifis ittoo taatus (isiniif uumne).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 21, 'Isiniif beyladoota keessa waan xiinxaltantu jira, Waan garaalee isaanii keessa jiru irraas (aannan) isin obaafna, Ammas isiniif ishee keessa bu’aalee (biraa) baay’eetu jira. Ishee irraas ni nyaattu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 22, 'Isheefi dooniiwwan irrattis baadhatamtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 23, 'Dhugumatti, Nuti Nuuhiin gara ummata isaa erginee jirra. Inni ni jedhe: “Yaa ummata kiyya! Allaah gabbaraa. Isa malee gabbaramaan biraa isiniif hin jiru. Sila isin (Allaah) hin sodaattanii?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 24, 'Qondaaltonni ummata isaa irraa kafaran ni jedhan: “Kun namuma akka keessaniiti malee waan biraa hin taane, Isin irra of caalchisuu fedha, Rabbiin odoo fedhee silaa maleykota buusa ture. kana abbootii keenya durii keessatti hin dhageenye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 25, 'Inni nama maraatummaan itti jiru malee waan biraa miti, (Kanaafuu) hanga yeroo murtaa’ee isa eegaa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 26, '(Nuuhis) ni jedhe: “Gooftaa kiyya! Waan ana sobsiisaniif isaan irratti na gargaari.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 27, 'Nuti (akkana jechuun): gara isaatti wahyii goone: “Ilaalchaafi ajaja keenyaan doonii hojjadhu, Yeroo ajajni keenya dhufee, badaa ibiddaa (jalaan bishaan) madde, waan hunda irraa gosoota lama lama (kormaafi dhalaa) ishee (doonii san) keessa seensisi, Maatii keetis (seensisi) nama isaan irraa jechi (adabbiin) keenya duraan irratti dabre malee, Waa’ee warra miidhaa hojjatanii keessatti homaa ana hin dubbisin. Dhugumatti, isaan bishaaniin nyaatamoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 28, 'Yeroo atiifi namoonni si waliin jiran doonii gubbaa baatan “Faaruun kan Rabbii Isa namoota miidhaa hojjatan irraa nu baraarseeti” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 29, 'Jedhi: “Gooftaa kiyya! Qubsuma barakaa qabu na qubsiisi; Ati irra caalaa qubsiiftotaati.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 30, 'Kana (adaba ummata Nuuh) keessa mallattooleetu jira; Nuti dhugumatti (ummata Nuuhii) qormaatoo taanee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 31, 'Sana booda, isaan duubaan dhaloota biroo uumne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 32, 'Isaan keessatti ergamaa isaan irraa ta’e erginee “Rabbiin gabbaraa; Isa malee Gooftaan biraa isiniif hin jiru, Sila isin (Allaah) hin sodaattanuu?” (jechuudhaan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 33, 'Qondaalonni mmata isaa kanneen kafaran nijedhan. kan qunnamtii Aakhiraa sobsiisaniifi jireenya addunyaa keessatti Nuti isaan duroomsine irraa tahan (nijedhan) : “Kun namuma fakkaataa keessaniiti malee waan biraatii miti. Waan isin nyaattan irraa nyaata; waan isin dhugdan irraas dhuga.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 34, 'Yoo nama akka keessaniitiif ajajamtan, dhugumatti isin yoos hoonga’oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 35, 'Sila isin erga duutanii biyyeefi lafee taatanii booda deebitanii (qabrii keessaa) baafamtu (jedhee) isin baallamaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 36, 'Wanti isin ittiin dinniinamtan (qabrii irraa kaafamuun) fagaate! fagaate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 37, 'Isheen jireenya keenya addunyaa malee kan biraatii miti, Nuti ni duuna; ni jiraannas, Nuti kaafamoo miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 38, 'Inni namicha Rabbi irratti soba odeessu malee waan biraa miti, Nuti isaaf amanoowwan hin taane.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 39, '[Inni] “Gooftaa kiyya! Waan na sobsiisaniif na tumsi” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 40, '(Rabbiinis) “Yeroo muraasa booda, isaan dhugumatti gaabbitoota ta’uuf jiru” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 41, 'Iyyiti cimtuun dhugaadhaan isaan qabatte, hoomacha isaan goone, Ummatoota miidhaa hojjattootaaf (rahmata Rabbii irraa) fageenyi haa ta’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 42, 'Ergasii, isaan booda dhaloota biroo uumne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 43, 'Ummanni kamillee beellama ishee hin dabartu; boodas hin aantu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 44, 'Sana booda ergamtoota keenya walduraa duubaan ergine, Dhawaatuma ummata tokkotti ergamaan ishee dhufuun isa sobsiisu, (badii keessatti) garii isaanii garii hordofsiifne, Oduu odeeffamu isaan taasifne, Namoota hin amanneef fageenyi haa ta’u!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 45, 'Sana booda Muusaafi obboleessa isaa Haaruuniin raajiiwwan keenyaafi ragaa ifa galaan ergine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 46, 'Gara Fir’awniifi qondaaltota isaa (ergine). ni boonan orma uftuultota tahan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 47, 'Ni jedhan: “Sila namoota lamaaf amannaa? kan nu fakkaataniifi kan ummanni isaanii nuuf gabbartoota ta''an"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 48, 'Isaan lamaan ni sobsiisan, Warra balleeffaman irraas ta’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 49, 'Akka isaan (haqatti) qajeelaniif jecha dhugumatti, Muusaaf kitaaba kenninee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 50, 'Ilma Maryamiifi haadha isaatis mallattoo taasifne, Isaan lamaanuu gara iddoo ol fuudhamaa; tasgabbiifi burqituu qabuu isaan qubsiifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 51, 'Yaa ergamtoota (kiyya)! Wantoota gaggaarii irraa nyaadhaa, Dalagaalee gaggaariis hojjadhaa, Ani waan isin hojjattan beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 52, 'Isheen tun (Rabbii tokkicha gabbaruun) tuuta teessani tuuta takka (karaa tokko taatee amantii keessani), Anis Gooftaa keessanii ana sodaadhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 53, 'Amantii isaanii gidduu isaanitti addaan cicciratani qoodamaa godhan, Gareen hundinuu waan isaan bira jirutti gammadu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 54, 'Hanga yeroo murtaa''eetti jallina isaanii keessatti isaan dhiisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 55, 'Sila sababni Nuti qabeenyaafi ilmaan irraa isaaniif daballu (isaaniif gaarii)se’uu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 56, 'Toltuuwwan isaaniif ariifachiifna (se''uu?) Lakkii; (Nuti kanaaf hin goone) Garuu isaan hin hubatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 57, 'Isaa warri sodaa Gooftaa isaanii irraa nahoo tahan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 58, 'Isaan Warri keeyyattoota Gooftaa isaaniitti amanan,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 59, 'Isaan Warri Gooftaa isaaniitti homaa hin qindeessine,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 60, 'Warri waan kennan onneewwann isaanii sodaan guutamtee, gara Gooftaa isaanii akka deebi’an amanaa kennan,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 61, 'Isaan sun hojiiwwan gaggaarii keessatti akkaan ariifatoodha; isaan isheedhaaf dorgomoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 62, 'Nuti lubbuu takkas dandeettii ishee malee ishee hin dirqisiifnu, Nu bira kitaaba dhugaa dubbatutu jira. Isaan hin miidhamanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 63, 'Dhugumatti onneewwan isaanii (Qur’aana) kana irraa haguuggaa keessa jirti. Isaaniif kana malees dalagaalee (gadhee) biraa kan isaan ishee hojjatantu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 64, 'Hanga Nuti isaan irraa warra qanani''oo (jireenya qananii daangaa dabre keessa jiraachaa turan) adabaan qabnetti, yeroma san isaan (deeggarsa kadhaaf) (sagalee ol fuudhanii) iyyu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 65, 'Har’a hin iyyinaa, isin Nu irraa tumsa hin argattanu (isaaniin jedhama).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 66, 'Dhugumatti, keeyyattoonni kiyya isin irratti dubbifamaa turaniiti, isin duuba keessanitti irraa deebi’aa turtan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 67, 'Isaan (Harama makkaatiin) warra boonan taatanii halkanis ka''abaa biratti (Qur''aana) arrabsaa irraa garagaltan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 68, 'Sila jecha (Rabbii) hin xiinxalanuu? Moo waan abbootii isaanii kan jalqabaatti hin dhufintu isaanitti dhufe?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 69, 'Ergamaa isaanii hin beekinii, isa sobsiisan moo?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 70, '“Moo maraatummaatu isatti jira” jedhu? Lakkii; inni dhugaan isaanitti dhufe, irra baay’een isaanii dhugaa jibboodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 71, 'Odoo dhugaan fedha lubbuu isaanii hordofee, silaa samii, dachiifi wantoonni isaan keessa jiran ni badu turan. Inumaayyuu; nuti kabajaa isaaniitiin isaanitti dhufne (Qur''aana kabajaan isaanii keessa jiru isaaniif kennineeti), isaan kabajaa isaanii irraa garagaloodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 72, 'Moo kafaltii isaan gaafatta? Gatii Gooftaa keetiitu caala. Inni irra caalaa warra kennaniiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 73, 'Dhugumatti, ati gara karaa qajeelaatti isaan waamta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 74, 'Isaan Aakhiraatti hin amanne karaa (qajeelaa) irraa jallatoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 75, 'Odoo rahmata isaaniif goonee, rakkoo isaan irra jirus irraa kaafnee, dhugumatti isaan dhama''anii jallina isaanii keessa jiraatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 76, 'Dhugumatti, Nuti adabaan isaan qabnee jirra, Isaan Gooftaa isaaniitiif gadi of hin qabne; Isattis hin watwaanne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 77, 'hanga balbala azaabaa cimaa qabu isaan irratti banne, yeroma san isaan isa keessatti abdii muratoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 78, 'Innis Isa dhageettii, argituuwwanifi onneewwan isiniif uumeedha. Wanti isin galateeffattan xiqqoo qofa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 79, 'Inni Isa dachii keessa isin facaaseedha. Gara Isaatti walitti qabamtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 80, 'Inni Isa jiraachisuufi ajjeesuudha, Jijjiiramni halkaniifi guyyaas kan Isaati, Sila hin hubattanii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 81, 'Fakkaatuma waan warri duraanii jedhanii jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 82, 'Ni jedhan: “Sila erga duunee biyyeefi lafee taane booda, nuti (deebinee) kaafamnaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 83, 'Dhugumatti, nuufi abbootiin keenyas kana dura kana waadaa galamnee jirra, Kun ogbarruu warra durii malee waan biraatii miti.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 84, 'Jedhi: “dachiiniifi isaan ishee keessa jiran kan eenyuti? Yoo kan beektan taatan”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 85, '“Kan Rabbiiti” jedhu “Sila isin hin gorfamtanuu?" jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 86, '“Gooftaan samii torbaniifi Gooftaan Arshii guddaa eenyu?” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 87, '“Kan Rabbiiti” jedhu “Sila isin Allaah hin sodaattanuu?” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 88, '“Inni mootummaan waan hundaa harka Isaa jiru eenyu jedhiin? innis kan tiksu; isa irratti kan hin tikfamne, yoo kan bektan taatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 89, '“Kan Allaahti” jedhu “Akkam (dhugaa) irraa garagalfamtu ree?” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 90, 'Inumaayyu, Nuti dhugaan isaanitti dhufnee jirra, isaanis sobdoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 91, 'Rabbiin ilma hin godhanne, Isa waliinis gabbaramaan tokkoyyuu hin jiru, (Odoo jiraatanii) silaa gabbaramaan hundi waan uumeen deema. Gariin isaanii garii irratti ol ta’u turan. Rabbiin waan isaan itti fakkeessan (hunda) irraa qulqullaa’e!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 92, 'Beekaan waan fagoofi dhihoo sun (qulqullaa’e), Waan isaan itti dabalan irraa ol ta’e!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 93, 'Jedhi: “Gooftaa kiyya! Yoo (adabbii) isaaniif waadaa galame natti agarsiifte,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 94, 'Gooftaa kiyya! (adaba irraa na baraarsi); ummata miidhaa hojjattoota keessas na hin taasisin.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 95, 'Dhugumatti, Nutis waan isaaniif waadaa galle si argisiisuu irratti danda’oodha', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 96, 'Hamtuu ishee irra gaariidhaan deebisi, Nuti waan isaan jedhan beekoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 97, 'Jedhi: “Gooftaa kiyya! Ani hasaasaalee sheyxaanotaa irraa Sittin maganfadha!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 98, 'Gooftaa kiyya! Isaan natti dhufuu irraa Sittin maganfadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 99, 'hanga tokkoon isaaniitti duuti dhufu ni jedha: “Gooftaa kiyya! Na deebisaai', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 100, 'Ani waaniin dhiise keessatti gaarii hojjachuun kajeela.” Lakkii! Isheen jecha inni ishee jedhu (qofa), isaan duuba hagoogiitu jira Hanga guyyaa kaafamaatti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 101, 'Yeroo garriin (xurumbaan) afuufame, guyyaa san firummaan gidduu isaanii hin jiru; walis hin gaafatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 102, 'Namni madaalliiwwan (hojii gaarii) isaa ulfaatte, isaan sun warra milkaa’oodha', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 103, 'Namni madaalliiwwan (hojii gaarii) isaa salphatte, isaan sun warra lubbuulee isaanii hoongessan. Jahannam keessa turu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 104, 'Ibiddi fuula isaanii ni gubdi, Isaanis achi keessatti soqolamoodha (fuulaa fokkatoota). [1]', '[1] soqolamoo jechuun nama hidhiin jalaa irraa gadidachaatee gadi harkifamtee ilkeen dirretti baatee fakkate jechuudha.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 105, 'Sila keeyyattoonni kiyya isin irratti dubbifamaa turtee, isin ishee sobsiisaa hin turree?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 106, 'Isaan ni jedhan: “(Yaa) Gooftaa keenya! Gogiinsa keenyatu nurra injifate; nu ummata jallatoo taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 107, 'Gooftaa keenya! Ishee irraa nu baasi, Ergasii yoo itti deebine,nutu miidhaa hojjattoota.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 108, '(Rabbiinis) "Salphadhaatii ishee (jahannam) keessa fagaadhaa, nan dubbisinaa" jedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 109, 'Dhugumatti, gareen gabroota kiyya irraa ta’e tokko “Gooftaa keenya! Amannee jirra, nuuf araaramii, rahmataas nuuf godhi, Ati irra caalaa warra rahmata godhaniiti” jedhaa turaniiti,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 110, 'Isinis hanga yaadannoo (faaruu) kiyya isin dagachiisanitti isaanitti qishnaa (baacaa) turtan, Isaanittis kolfaa turtan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 111, 'Dhugumatti, Ani har’a waan isaan obsaniif isaan milkaa’oo ta’uudhaan isaaniif galata galche.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 112, '(Rabbiin) ni jedhe: “Sila dachii keessa lakkoofsa waggaa hangamii jiraattan?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 113, '[Isaan] ni jedhan: “Nuti guyyaa tokko yookiin garii guyyaa jiraanne, Warra lakkaa’an gaafadhu.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 114, '(Rabbiin) ni jedha: “isin (yeroo) xiqqoo malee hin jiraanne Odoo kan beektan taatanii .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 115, 'Sila Nuti taphaaf isin uumne seetuu? Ammas isin gara keenyatti hindeebifamtanuu seetuu”?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 116, 'Rabbiin mootii dhugaa ta’e, ol ta’e, Isa malee Gooftaan biraa hin jiru, Inni Gooftaa Arshii kabajamaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 117, 'Namni Rabbii wajjin odoo ragaa isa irratti hin qabne, gabbaramaa biraa kadhatu (gabbaru), qormaanni isaa Gooftaa isaa bira jira, warri kaafaran hin milkaa’anu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 118, '“Gooftaa kiyya! Naaf araarami, rahmatas (naaf) godhi, Ati irra caalaa warra rahmata godhaniiti” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 1, '(Isheen tun) suuraa Nuti ishee buufnee, dirqama ishee taasifnee, ishee keessattis keeyyattoota ifa ta’an buufne akkagorfamtaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 2, 'Dubartii (heeruma dura) sagaagaltuufi dhiira (fuudha dura) sagaagalu tokko tokkoon isaanii rukuttaa dhibba isaan rukutaa, Yoo Rabbiifi Guyyaa Aakhiraatti kan amantan taataniif, amantii (adaba yookiin haddii) Rabbii keessatti isaan lamaaniif garaa laafuun isin hin qabatin, adabbii isaan lamaanii gareen mu’uminoota irraa ta’e itti haa hirmaatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 3, 'Dhiirri sagaagalaan sagaagaltuu yookiin dubartii mushrika taate malee hin fuudhu, Dubartiin sagaagaltuunis dhiira sagaagalaa yookiin dhiira mushrika ta’e malee namni biraa ishee hin fuudhu, Sun mu’uminoota irratti dhorgamee jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 4, 'Isaan dubartoota qulqulluu darbatan (kabajaa ofii eegan sagaagalummaan maqaa isaanii xureessan), ergasii ragaa afur hinfidin, rukuttaa saddeettama isaan rukutaa, Ragummaa isaaniis gonkumaa irraa hin fuudhinaa, Isaan sun isaanumatu finciltoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 5, 'Isaan sana booda tawbatanii, tolchan malee, (Isaan sanaaf) Rabbiin araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 6, 'Isaan niitiwwan isaanii sagaagalummaan maqaa xureessan kan lubbuulee isaanii malee ragaaleen isaaniif hin jirre, rageessuun tokkoo isaanii ‘inni dhugaa dubbattoota irraayi’ jechuun yeroo afur Rabbiin kakachuudhaan rageessuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 7, '(Ragaan) shaneessituun abaarsi Rabbii isa irra haa jiraatu yoo inni namoota sobaan (maqaa ishee xureessan) irraa ta’e, ( jechuun kakachuudha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 8, 'Adabbii (addunyaa) ishee irraa deebisa "Inni sobdoota irraayyi” jettee yeroo afur Rabbiin kakachaa rageessuun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 9, '(Ragaan) shanessituu abaarsi Rabbii ishee irra haa jiraatu ‘yoo inni (dhiirsi ishee) namoota dhugaa jedhan irraa ta’e" (jechuudha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 10, 'Odoo tolli Rabbiitiifi rahmanni Isaa isin irra jiraachuu baatee, (silaa Rabbiin isin adaba ture), Rabbiin akkaan tawbaa qeebalaa, ogeessa', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 11, 'Dhugumatti, isaan (Aa’ishaa iratti) soba fidan garee isin irraa ta’aniidha, Isa isiniif hamtuu hin se''inaa, Inumaa inni isiniif caalaadha, Nama isaan irraa ta’e hundaafuu, hamtuu irraa wantuma inni carraaqqatetu isaaf jira. Isa isaan irraa (soba) guddaa baadhate immoo adabbii guddaa ta''etu isaaf jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 12, 'Maaliif yeroo isa (soba kana) dhageessan, mu’uminoonni dhiiraas ta’ee kan dubaraa, lubbuulee isaaniitiif (wal jiddutti) toltuu yaadanii “Kun soba ifa bahaadha” jechuu dhaban?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 13, 'Maaliif isa irratti ragaalee afur fiduu dhiaban? Eega ragootaan hin dhufin, isaan sun Allaah biratti isaanumaat sobdoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 14, 'Odoo tolaafi rahmanni Allaah addunyaafii Aakhiraa isin irra jiraachuu baatee, silaa waan isin waa’ee isaa keessatti odeessitaniif adabbii guddaatu isin tuqa ture.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 15, 'Yeroo isin arraboota keessaniin olola isaa ooftanii, afaanoowwan keessaniinis waan beekkomsa isatti hinqabne jettan, odoo inni Rabbiin biratti guddaa ta’ee jiruu isin waan laafaa isa seetan san (adabni guddaan isin tuqa ture).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 16, 'Sila yeroo isa (soba kana) dhageessan “waa’ee kanaa dubbachuun nuuf hin malu, (Yaa Rabbi!) Ati qulqulloofte! Kun soba guddaadha” maaliif hin jenne?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 17, 'Yoo mu''imintoota taataniif akka isin (gocha) fakkataa isaatti gonkumaa hin deebine Rabbiin isin gorsa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 18, 'Allaah’n keeyyattoota Isaa isiniif ibsa. Rabbiin beekaa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 19, 'Dhugumatti, isaan gochi fokkataan isaan amanan keessatti tamsa’uu jaallatan, isaaniif addunyaafi Aakhiraa keessatti adabbii laalessaa ta’etu (isaaniif) jira. Rabbiin nibeeka; isin hin beektanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 20, 'Odoo tolaafi rahmanni Allaah isin irra jiraachuu baatee, (silaa isin adabbii ture) Rabbiin mararfataa rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 21, 'Yaa warra amantan! Tarkaanfiiwwan shayxaanaa hin hordofinaa, Namni tarkaanfiilee shayxaanaa hordofe, inni (sheyxaanni) gocha fokkataafi gocha jibbamaatti ajaja. Odoo tolli Rabbiitiifi rahmanni Isaa isin irra jiraa jiraachuu baatee, isinirraa tokkoon keessan hinqulqullaawu gonkumaa. Garuu Rabbiin nama fedhe qulqulleessa. Rabbiin dhaga’aa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 22, 'Isin irraa abbootiin tolaafi qabeenyaan (badhaadhan) firoota isaanii, hiyyeeyyiifi namoota karaa Rabbii keessatti godaananiif kennuu diduu irratti hin kakatin. Dhiifama haa godhanu; (namaafis) irra haa dabranu. Sila Rabbiin isiniif araaramuu hin jaallattanuu? Allaahaan araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 23, 'Isaan dubartoota tikfamoo, (sagaagalummaa irraa) dagatoofi mu’uminoota ta’an maqaa xureessan, addunyaafi Aakhiraattis abaaramaniiru. Isaaniif adabbii guddaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 24, 'Guyyaa Arraboonni isaanii, harkoowwan isaaniitiifi miilleen isaanii waan isaan dalagaa turan ragaa isaan irratti ba’an (adabamu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 25, 'Guyyaa san Rabbiin galata (hojii) isaanii kan dhugaa guutee isaaniif kenna. Isaan Rabbiin dhugaa, ifa baasaa ta’uu ni beeku.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 26, 'Dubartoonni badoon dhiirota badoofi, dhiironni badoonis dubartoota badoof ta’u, Dubartoonni gaggaariin dhiirota gaggaariifi, dhiironni gaggaariinis dubartoota gaggaariifi. Isaan sun waan isaan jedhan irraa qulqulleeffamoodha. Isaaniif araaramaafi kennaa gaarii ta’etu (Jannatatu) jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 27, 'Yaa warra amantan! Mana keessan hin ta’in hanga hayyamsiifattaniifi abbootii ishee nagaa gaafattanitti hin seeninaa. santu isiniif caala Akka gorfamtaniif jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 28, 'Yoo ishee keessatti nama tokkos arguu baattan, hanga isiniif hayyamamutti ishee hin seeninaa, Yoo deebi’aa isiniin jedhames deebi’aa, Santu isiniif irra qulqulluudha, Rabbiin waan isin dalagdan hunda beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 29, 'Mana namni keessa hin jiraanne kan ishee keessa meeshaan keessan jiru (hayyama malee) yoo seentan badiin isin irra hin jiru, Rabbiin waan isin mul’iftaniifi waan isin dhoksitanis ni beeka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 30, 'Mu’uminootaan “(ija keessan gadi qabadhaa)” jedhi, ijoowwan isaanii gadi qabatu; qaamoowwan saalaa isaaniis ni tikfatu, Santu isaaniif irra qulqulluudha. Dhugumatti, Rabbiin keessa beekaa waan isaan dalaganiiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 31, 'Jedhi Dubartoota mu’uminootaatiin “(ija keessan gadi qabadhaa”) jedhi, ija isaanii gadi qabatu; qaamolee saalaa isaaniis ni tikfatu“ Faaya isaanii isa ishee irraa ofiin mul’ate malee hin mul’isinaa; guftaalee isaanii qomoowwan isaaniirratti haa uffisanu; miidhagsituu isaanii dhiirsoowwan isaaniif malee akka hinmul''ifne, yookiin abbootii isaaniif, yookiin abbootii dhiirsoowwan isaanii, yookiin ilmaan isaanii, yookiin ilmaan dhiirsoowwan isaanii, yookiin obboleeyyan isaanii, yookiin ilmaan obboleeyyan isaanii, yookiin ilmaan obboleettiiwwan isaanii, yookiin dubartoota isaanii (mu’uminoota ta’an), yookiin gabroota too’annaa isaanii jala jiran, yookiin hordoftoota dhiira irraa ta’an kan fedhii hin qabne ta’aniifi yookiin ijoollee qaamoowwan saala dubartootaa irratti hin mul’atinitti (hin beekinitti) (malee miidhagina isaanii hin mul’isin). Miidhagina isaanii irraa wanti isaan dhoksan akka beekamuuf jecha miiloowwan isaaniitiin dachii hin dhiitin. hundi keessanuu gara Rabbiitti tawbaa deebi’aa Yaa mu’uminootaa! Akka milkooftaniif jecha.” (jedhiin).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 32, 'Isin irraa konfoleysota (dhiiraas ta’ee dubaratii hin fuudhin) fuusisaaGabroota keessan kan dhiiraatiifi dubartootaa irraas ta’an isaan gaggaarii (fuusisaa)Yoo hiyyeeyyii ta’anis Rabbiin tola Isaa irraa isaan duroomsaRabbiin dureessa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 33, 'Isaan waan fuudhaaf isaan barbaachisu hin argatin hanga Rabbiin tola Isaa irraa isaan duroomsutti, (uf haaqaban) kabajaa ofii haa eeggatan. Gabroota too’annaa keessan jala jiran gidduu yoo isaan keessatti toltuu beektan, isaan barreeffama (beellamaan bilisoomuu) barbaadaniif, barreessaa. Qabeenya Rabbii kan Inni isiniif kenne irraas isaaniif kennaa. Shamarran gabrootaa keessan yoo isaan kabajaa ofii eeguu fedhan isin bu’aa jireenya addunyaa barbaaduuf jecha, sagaagalummaa irratti isaan hin dirqinaa. Namni isaan dirqe, Rabbiin erga isaan dirquutii (isaanif) araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 34, 'Dhugumatti, Nuti keeyyattoota ifa ta’an gara keessanitti buufnee jirra. fakkeenya warra isin dura dabranii irraas, gorsa warra Rabbi sodaataniitis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 35, 'Rabbiin ifaa samiifi dachiiti, Fakkeenyi ifa Isaa akka foddaa ibsaan ishee keessa jiruuti, Ibsaan sun immoo birillee keessa jira, Birillichis akka urjii calaqqisaa muka barakeeffamtuu, zeytuunaa irraa taate irra qabsiifamuu, kan kallattii bahaas ta’ee, dhihattiis hin ta’in, kan zeytiin ishee odoo ibiddi isa tuquu baattellee ifuutti dhihaatu kan fakkaattuudha, (Kana jechuun) ifaa ifaa irraati ta’ee dha! Rabbiin nama fedhe gara ifaa Isaatti qajeelcha. Rabbiin namootaaf fakkeenyota taasisa. Rabbiin waan hunda beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 36, 'Manneen (masjiidoota) keessatti kabajamuufi maqaan isaa ishee keessatti dubbatamuutti (faarfamuutti) Rabbiin ajaje, ishee keessatti ganamootaafi galgalootas Isa qulqulleessu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 37, 'Dhiironni daldalas ta’ee gurgurtaan yaadannoo Rabbii irraafii, salaata dhaabuufi zakaa kennuu irraa isaan hin dagnetu (ishee keessatti Rabbi faarsa) guyyaa isa keessa onneewwaniifi ijjoonni gara gaggaltu kan sodaatan ta’anii (ishee keessatti Rabbiin qulqulleessu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 38, 'Akka Rabbiin irra gaarii waan isaan dalaganii isaaniif galata galchee, tola Isaa irraas isaaniif dabaluuf (Isa sodaatu). Rabbiin nama fedhe herrega malee soora.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 39, 'Warri kafaran dalagaaleen isaanii akka siribii dirree keessa jirtuu, kan dheebotaan bishaan isa se’uuti, hanga isa bira ga’ee homaa ta’uu isaa dhabe; Allaah of biratti argee (Rabbiin) galata isaa guutee isaaf galcheeti. Rabbiin saffisaa herregaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 40, 'Yookiin akka dukkana galaana gadi fagoo ta’e keessa jiru, kan danbaliin isa haguugeeti, kan gubbaa isaa danbaliin (biraa) jiru kan isa gubbaa duumessi jiru (haguuguuti), (Isheen kun) dukkana gariin ishee garii gubbaa jirtuudha; yeroo harka isaa baase argutti hin dhihaatu, Namni Allaahn ifaa isaaf hin taasisin, ifaan homaatuu isaaf hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 41, 'Ati hingarree Allaah wanti samiileefi dachii keessa jiran isa qulqulleessan. allaattiinis koola (qoochoo) isaanii diriirsanii (Isa qulqulleessan) (faarsan)? Hunduu dhugumatti, Isaaf sagaduufi Isa qulqulleessuus beekaniiru, Rabbiin waan isaan dalagan beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 42, 'Mootummaan samiileefi dachii kan Allaahti, Deebiin garuma Allaahti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 43, 'Sila ati hingarree Allaahn duumessa oofee, ergasii gidduu isaa walitti qabee, ergasii tuulamaa isa taasisuu? Sana booda bokkaa gidduu isaatii kan ba’u argita. Akkasumas samii irraa gaara ishee keessatti ta’e kan cabbii irraa ta’erraa (cabbii) buuseeti, nama fedheen isaan tuqa, nama fedhe irraas isa deebisa. Ifti hangaasuu isaa ija balleessutti dhihaata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 44, 'Rabbiin halkaniifi guyyaa gara gaggalcha, Dhugumatti, kana keessa namoota hubannoo qabaniif gorsatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 45, 'Allaahn wantoota lubbuu qaban hunda bishaan irraa uume, Isaan irraa warra garaa isaaniitiin deeman (looyan)tu jira, Isaan irraa warra miila lamaan deemantu jira. Isaan irraas warra (miila) afuriin deemantu jira. Rabbiin waan fedhe uuma. Rabbiin waan hunda irratti danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 46, 'Nuti dhugumatti keeyyattoota ifa ta’an buufnee jirra. Rabbiin nama fedhe gara karaa qajeelaa qajeelcha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 47, '(Munaafiqoonni) “Allaahfi ergamaatti amanne; ajajamnes” jedhan, ergasii gareen isaan irraa ta’e sana booda garagalaIsaan jarri sun, mu’uminoota miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 48, 'Yeroo akka gidduu isaaniitti murteessuuf gara Allaahfi ergamaa Isaatti waamaman, gareen isaan irraa ta’e yoosuu garagaloodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 49, 'Yoo dhugaan isaaniif jiraate immoo ariifatoo ta’anii gara isaa (ergamaa) dhufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 50, 'Sila onneelee isaanii keessa dhukkubni jiramoo, moo nishaan, moo Rabbiifi ergamaa Isaatu dabaan (haqa malee) isaan irratti murteessaa sodaatu? Lakkii; isaan isaanumatu miidha raawwattoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 51, 'Jechi Mu’uminootaa yeroo akka gidduu isaaniitti murteessuuf gara Rabbiifi ergamaa isaatti waamaman “dhageenye; ajajamnes” jechuu qofa, Isaan sun milkaa’oon isaanuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 52, 'Namni Allaahfi ergamaa Isaa tole jedhee, Allaaha sodaatee, Isa eeggate, isaan sun isaanumatu milkaa’oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 53, 'Kakuu isaanii cimaa Rabbiin kakatu Yoo (duulaaf) bahuutti isaan ajajje, akka ba’an. jedhiin “Hin kakatinaa, ajajamuu beekamaatu (isiniif caalaa dha)”. Rabbiin waan isin dalagdan keessa beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 54, 'Jedhi: “Rabbiif ajajamaa; ergamaafis ajajamaa, Yoo garagaltan, kan isa irra jiru dirqama isa irra kaa’ame qofa, Isin irras waanuma baachifamtan qofatu jira. Yoo isaaf ajajamtan ni qajeeltu, Ergamaa irra geessiinsa mul''ataa malee hinjiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 55, 'Rabbiin isin irraa warra amananii, gaggaarii hojjataniif waadaa seene, akkuma warra isaan duraa (dachii irratti) bakka buusee, dachii irratti bakka isaan buusuuf. Amantii isaaniif jaalate isaaniif mijeessuuf, erga sodaa isaaniitii nagayatti isaaniif jijjiiruuf (waadaa seene). Odoo humaa natti hin qindeessin haa nagabbaranii. Sana booda warri kafare, isaanumatu finciltoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 56, 'salaata (sirnaan) sagadaa; zakaas kennaa; ergamaafis ajajamaa Akka rahmanni isiniif godhamuuf jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 57, 'Isaan kafaran dachii keessatti dadhabsiisoo hin se’in, Teessoon isaanii ibidda, Deebichi waa hammaatee!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 58, 'Yaa warra amantan! Isaan (gabroonni) mirgi keessan dhuunfatteefi isin irraa isaan umrii saalfii (gaa’ilaa) hin ga’in yeroo sadi hayyama isin haa gaafatanu: salaata fajrii dura, yeroo walakkaa guyyaa ho’aaf uffata keessan baafattaniifi salaata ishaa’ii booda, Yeroo sadi kan isin qullaa baataniidha, Isaan kanaan ala gariin keessan garii irra yoo naanna’an, isin irras ta’ee isaan irra diliin hin jiraatu. Akka kanatti Rabbiin keeyyattoota (Isaa) isiniif addeessa, Allaahn beekaa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 59, 'Ijoolleen isin irraa ta’an yeroo umrii gaa’ilaa ga’an, akkuma warri isaaniin duraa hayyamsiifataa turanitti haa hayyamsiifatanu. Akka kanatti Rabbiin keeyyattoota Isaa isiniif ibsa, Rabbiin beekaa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 60, 'Dubartoonni manguddooman kan heeruma hin kajeelle odoo miidhagina isaanii hin saaxilin uffata isaanii (kan gubbaa) lafa kaa’uu keessatti badiin isaan irra hin jiru. Garuu tikfamuutu isaaniif irra caala. Allaahn dhaga’aa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 61, '(Namaa wajjin nyaachuu keessatti) Jaamaa irra rakkinni hin jiru, Naafa (hokkolaa) irrattis rakkinni hin jiru, Dhukkubsataa irraas rakkinni hin jiru, lubbuulee teessan irrattiis manneen keessan irraa nyaachuuf diliin isin irratti hinjiru, yookiin manneen abbootii keessanii irraa, yookiin manneen haadholii keessanii irraa, yookiin manneen obboleeyyan keessan irraa, yookiin manneen obboleettiwwan keessanii irraa, yookiin manneen wasiila (abbeeraawwan) keessanii irraa, yookiin manneen adaadota keessanii irraas, yookiin manneen eessumman keessanii irraas, yookiin manneen haboowwan (aaddee) keessanii irraa, yookiin waan furtuu isaa dhuunfattan irraa, yookiin (mana) hiriyyaa keessanii irraa (nyaachuu keessatti diliin isin irra hin jiru). Walii wajjinis ta’ee adda addaan nyaachuu keessatti badiin isin irra hin jiraatu, Yeroo manneen seentan lubbuulee teessanirratti salaammadhaa. salaamataa Rabbi biraa taate, barakeeffamtuu, qulqulluu taate (of irratti buusaa). Akka kanatti Rabbiin keeyyattoota (Isaa) isiniif ibsa akka xiinxaltaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 62, 'Mu’uminoonni isaan Rabbiifi ergamaa Isaatti amananii, yeroo isaa wajjin dhimma walitti qabaa ta’e irratti ta’an, hanga isa hayyamsiifatanitti achii hin deemneedha. isaan si hayyamsiifatan, isaan sun warra Rabbiifi ergamaa Isaatti amananiidha. Kanaafuu yeroo garii dhimma isaanitiif si hayyamsiifatan, isaan irraa nama feetef hayyami; Rabbi irraas araarama isaaniif kadhu, Rabbiin araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 63, 'Waamicha ergamaa (Rabbii) gidduu keessanitti akka waamicha gariin keessan garii waamu hin taasisinaa. Dhugumatti, Rabbiin isaan isin irraa dhokatanii luqqa’an (ba’an) ni beeka, Kanaafuu isaan ajaja isaa (nabiyyii) faallessan rakkoon wahii isaan tuquu, yookiin adabbiin laalessaan isaan tuquu of irraa haa eeganu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 64, 'Dhagayaa! Dhugumatti, wanti samiileefi dachii keessa jiran kan Rabbiiti, Dhugumatti, Inni waan isin irra jirtan ni beeka. Guyyaa gara Isaa deebi’an waan isaan dalagan itti odeessa. Rabbiin waan hunda beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 1, 'Inni furqaaniin (Qur’aana) akka aalama hundaaf dinniinaa (sodaachisaa) ta’uuf jecha gabricha Isaa irratti buuse toltuun isaa baay’atte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 2, '[Inni] Isa mootummaan samiileefi dachii Isaaf ta’e; ilma kan hin godhatin; kan mootummaa [isaa] keessatti waahelli Isaaf hin jirreefi waan hundaa uumee (akka isaaniin maluun) likkeessuu likkeesse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 3, 'Isaa (Rabbii) gaditti gooftolee godhatan kan homaa hin uumne, kan isaanuu uumamanu, kan of irraa miidhaa deebisuu ta’ee bu’aa fiduu hin dandeenye, ajjeesuu, jiraachisuufi du’a irraa kaasuus hin dandeenye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 4, 'Warri kafaran nijedhan “kun soba inni (Muhammad) of irraa uumeefi namoonni biraa irratti isa gargaaran malee waan biraatii miti”. Dhugumatti isaan miidhaafi cubbuu rawwatanii jiru', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 5, '“(Kun) hogbarruu warra durii ishee barreessisee isheen ganamaafi galgala isa irratti dubbifamtuudha” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 6, '”Isa samiileefi dachii keessatti iccitii [hunda] beekutu isa buuse” jedhi. Dhugumatti, Inni akkaan araaramaa, akkaan rahmata godhaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 7, 'Nijedhan “ergamaa kana maaltu isaaf tahe kan nyaata nyaatu kan magaalota keessa adeemu? Sila maaliif maleykaan gara isaa buufamee isaa wajjin dinniinaa hin taane”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 8, '”Yookiin immoo maaliif dilbiin (qabeenyi guddaan wahii) gara isaatti hin darbamne? Yookiin ashaakiltii ishee irraa nyaatu maaliif isaaf hin taane?” (jedhu). Miidhaa hojjatoonni “isin nama falfalli itti hojjatame malee [nama fayyaa] hordafaa hin jirtan” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 9, 'Laali Akka isaan fakkeenyota siif godhan. jallatan, karaa sirrii [qabachuu] hin dandayan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 10, 'Toltuun isaa baay’ate Isa (Rabbii) yoo fedhe waan san irra caalu, Jannatoota jala ishee laggeen yaatu siif godhee, gamoowwanis siif godhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 11, 'Dhugumatti isaan Qiyaamaa sobsiisan. Nama Qiyaamaa sobsiiseefis ibidda boba’aa qopheessinee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 12, 'Yeroo iddoo fagoo irraa isaan argite dallansuufi halaka (iyya akka harree) isheef dhagahu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 13, 'Yeroo ishee irraa iddoo dhiphootti darbaman sakaalamanii (harki isaanii morma isaaniitti hidhamee) achitti badii waammatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 14, '“Har’a badii tokko qofa hin waaminaa badii hedduu waamaa” [hin argattanu isaaniin jedhama].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 15, '”Sila kanatu caala moo Jannata zalaalam ishee warri Rabbiin sodaatan baallamamantu caala?” jedhiin. Isheen isaaniif mindaafi itti gala taateejirti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 16, 'isaaniif ishee keessatti wanta fedhan hundatu jira; Kan keessatti hafan ta’anii. [Kunis] gooftaa kee irratti waadaa kadhatamaa (kan mu’uminoonni duraan Rabbiin kadhatan) ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 17, 'Guyyaa Rabbiin isaaniifi wantoota isaan Rabbii gaditti gabbaran walitti qabee “sila gabroota kiyya kanneen isintu jallisemoo isaanumatu karaa bade?” jedhu san [yaadadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 18, '[Isaanis] nijedhan “[yaa Rabbi!] Ati qulqulloofte! Sii gaditti gargaartota (jaalalleewwan) godhachuun kan nuuf malu hin taane; Garuu Ati isaaniifi abbootii isaaniis qanansiifte hanga gorsa [kee] dagatanii ummata bade ta’anitti ”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 19, 'Dhugumatti, waan isin jettan keessatti isin sobsiisaniiru, Kanaafuu [adabbii Rabbii] deebisuus ta’ee [warra adabbiin tuquuf] tumsuu hin dandeessan. Nama isin irraa miidhaa hojjate adabbii guddaa isa dhandhamsiifna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 20, 'Siin duratti ergamoota irraa kan isaan nyaata nyaataniifi magaalota keessa deeman taasifnee malee hin ergine; garii keessan gariidhaaf mokkoroo taasifne; ni obsituu? Gooftaan kee [waan hunda] argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 21, 'Warri qunnamtii keenya hin sodaanne, “sila maaliif Maleykonni nutti hin buufamne? yookiin maaliif Gooftaa keenya hin argine?” jedhan. Dhugumatti, isaan lubbuu isaanii keessatti boonaniiru; jallina guddaas jallataniiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 22, 'Guyyaa isaan Maleykota argan, guyyaa san jallattootaaf gammachuun hin jiru. [Maleykonnis] “(gammachuun kamillee isin irratti), dhorgamiinsa dhorgamaadha[]” jedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 23, 'Nutis gara dalagaa isaan dalaganii feenee (dhufnee) dhukkee faca’aa isa goone.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 24, 'Warri Jannataa guyyaa san iddoo jireenyaa keessatti akkaan caalaa; iddoo boqonnaattis akkaan miidhagaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 25, 'Guyyaa samiin duumessaan dhodhootuufi Maleykonni buufamiinsa buufaman [yaadadhaa].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 26, 'Mootummaan dhugaa guyyaa san kan Rahmaani, Inni guyyaa kaafiroota irratti rakkisaa ta’eedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 27, 'Guyyaa miidhaa hojjataan [gaabbiidhaan] harka isaa lamaan ciniinee “yaa badii koo! odoon Ergamichaa wajjiin karaa sirrii qabadhee” jedhu [yaadadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 28, '”Yaa badii kiyya! Odoon ebaluun jaalallee taasifachuu baadheen gaabba!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 29, 'Dhugumatti, gorsa irraa na jalliseera erga inni natti dhufee booda” Sheyxaanni ilma namaaf salphisaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 30, 'Ergamichis nijedhe “Yaa Gooftaa kiyya! ummanni kiyya Qur’aana kana dhiifamaa (oodamaa) taasifatan”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 31, 'Akkuma kana nabiyyii hundaafuu jallattoota irraa diina isaaniif goone, (Karaa irratti) qajeelchuufi [Mu’uminaaf] tumsuu irratti Rabbiin kee ga’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 32, 'Isaan kafaran ni jedhan: “Maaliif Qur’aanni hundaan al tokko isarratti hin buufamin?” Akka kanatti onnee kee isaan gadi dhaabuuf jecha (adda addaan buufne), Suuta suutaan isa ibsine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 33, 'Gaaffiidhaan sitti dhufanii hin hafan, Yoo [deebii] dhugaafi kan hiikti isaa gaarii ta’e siif kennine malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 34, '[Isaan] warra fuulleen isaanii irratti gara jahannam oofamaniidha. Isaan warra iddoo hamaa karaa jallaadhaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 35, 'Dhugumatti, Nuti Muusaaf kitaaba (Tawraatiin) kenninee, Obboleessa isaa Haaruuniinis isa waliin gargaraa taasifnee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 36, '”Gara warra keeyyattoota keenya sobsiisanii deemaa” isaaniin jenne. [ergamaan lamaan sobsiifnaan] balleessuu isaan balleessine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 37, 'Ummata Nuuhis yeroma isaan ergamoota sobsiisan isaan dhidhimsiifne, namootaaf mallattoo isaan taasifne. Miidhaa raawwattootaaf azaaba laalessaa qopheessineerra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 38, '[Ummata] Aad, Samuud, warra Eelaatiifi jaarrota baay’ee jidduu sana jiranis (balleesinee jira).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 39, 'Hunda isaanitiif fakkeenyota taasifnee jirra. Hunda isaanii barbadeessuu barbadeessinee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 40, 'Dhugumatti, isaan Magaalattii Roobni hamaan itti roobe irra qaxxaamuraa turaniiru. Sila isaan kan ishee argan hin taanee [maaliif hin gorfamne]? Dhugaatti kaafama [Qiyaamaa] kan hihkajeelle tahan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 41, 'Yeroo si argan qishnaa malee waan biraa si hin taasifatanu “Isa kanaa inni Rabbiin ergamaa taasisee erge” (jedhu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 42, '”Silaa (Muhammad) gabbaramtoota keenya irraa nu jallisuutti dhihaatee ture, Odoo nuti ishee [gabbaruu] irratti obsuu baannee” (jedhu). Fuulduratti beekuuf jiru yeroo adabbii argan namni karaa bade eenyuun akka ta’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 43, 'Sila nama gabbaramaa isaa fedhuma lubbuu isaa taasifate hin arginee? Sila ati isa irratti tiksaa (eegaa) taataa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 44, 'Sila ati irra baay’een isaanii ni dhaga’u yookiin (waan itti himame) ni hubatu seetaa? Isaan akka beyladootaa malee hin taane, Inumaa isaan (horii) irra karaa jallatoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 45, 'Sila gara Gooftaa keetii hin ilaallee akkamitti Gaaddisa akka diriirse ? Odoo fedhee turaa isa taasisa ture. Ergasii Aduu (jiraachuu) isaa (gaaddisaa) irratti ragaa taasifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 46, 'Ergasii qabiinsa suuta suutaa gara keenyatti isa (gaaddisa) qabne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 47, 'Inni (Rabbiin) Isa halkan uffata, hirriba immoo boqonnaa isiniif taasise. Guyyaa yeroo olii gadi sochootan taasiseedha', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 48, 'Inni Isa rahmata (bokkaa) isaa dura qilleensa gammachiisaa godhee ergeedha. Samii irraa bishaan qulqulluu buusne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 49, 'Akka dachii duute isaan jiraachisnuufi, waan uumne irraa horiiwwaniifi namoota baay’ee isa obaasnuuf [Samii irraa rooba buufne].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 50, 'Dhugumatti, akka gorfamaniif jecha gidduu isaaniitti isa raabsinee jirra. Irra hedduun namaa kafaruu malee [amanuu] ni didan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 51, 'Odoo feenee magaalota hunda keessatti akeekkachiisaa ni ergina ture.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 52, 'Kaafirootaaf hin ajajaminii isaan (Qur’aana kanaan) qabsoo guddaa isaan irratti qabsaa’i.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 53, 'Inni Isa bahara lama, tokko mi’aayaa dhugaatiif mijaa’uu, kaan immoo soogiddoo kuraawaa ta’e, wal maddii qabee gadi dhiise. jidduu isaan lamaanitti dawoofi daangaa daangeffamaa taasiseedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 54, 'Inni Isa bishaan irraa nama uumee ergasii fira (sanyii)fi soddaa tasiseedha. Gooftaan kee danda’aa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 55, 'Rabbii gaditti waan isaan hin fayyadneefi hin miine gabbaru. Kaafirri Gooftaa isaa irratti deeggaraa [sheyxanaa] ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 56, 'Nutis gammachiisaafi akeekkachiisaa goonee malee si hin ergine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 57, 'Jedhi: “Isa irratti mindaarraa waa isin hin gaafadhu; namna karaa gooftaa isaa qabachuu fedhe malee [inni haa saddaqatu].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 58, 'Jiraataa Isa hin duune san irratti hirkadhu. Faarsuu Isaa waliin Isa qulqulleessi. Badii gabroota Isaa iccitii beekuu keessatti Isumatu ga’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 59, 'Inni isa Samiileefii Dachii, waan isaan lamaan gidduu jiran (hunda) guyyoota jaha keessatti uumee. ergasii Arshii irratti (haala isaaf maluun) ol ta’e; (Inni) Rahmaani haala keessa beekaa ta’een isa gaafadhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 60, 'Yeroo Rahmaaniif sujuuda godhaa jedhaman “Rahmaan eenyu? Waan ati nu ajajjuufiif sujuuda goonaa?” jedhu. {Kuni Rabbirraa} fagaachuu isaaniif dabale. [1]', '[1] sujuuda qaraatii qur''aanaatu as jira.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 61, 'Inni Samiilee keessatti buruuja taasisee ishee keessattis (biiftuu) ifaafi ji’a ibsaa taasise khayriin Isaa baay’ate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 62, 'Inni Isa halkaniifi guyyaa wal irraa bakka bu’aa taasiseedha, nama gorfamuu fedheef yookiin galata galchuu fedheef.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 63, 'Gabroonni Rahmaan isaan suutaan Dachii irra deemani; yeroo wallaaltonni isaan dubbisanis “Salaama” (nagaa) jedhanuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 64, 'Isaan Gooftaa isaaniitiif sujuuda godhaa; dhaabbataa bulaniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 65, 'Ammas warra jedhani: “(yaa) Gooftaa keenya! azaaba jahannam nurraa deebisi; dhugumatti adabbiin ishee nama qabataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 66, 'isheen waa hammaattee iddoo qubannaafi iddoo teessumaa ta’uun”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 67, 'Ammas (gabroonni Rabbii) isaan yeroo arjooman karaa malee hin balleessineefi hin donnoomne kan gidduu kanatti (kennaan isaanii) sirrii ta’eedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 68, 'Ammas isaan warra Rabbii wajjin waan biraa hin gabbarre (hin kadhanne), kan lubbuu Rabbiin (ajjeesuu) haraama godhe haqaan alatti hin ajjeefneefi hin sagaagalleedha. Namni (hojii gadhee) kana hojjate, adabbii qunnama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 69, 'Guyyaa Qiyaamaa adabbiin (jahannam) dachaa isaaf taasifama. Isa keessa salphifamaa ta’ee zalaalam jiraata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 70, 'Nama tawbateefi amanee dalagaa gaarii hojjate malee, Isaan san Rabbiin hamtuuwwan isaanii toltuuwwanitti jijjiiraaf. Rabbiin araaramaa, rahmata godhaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 71, 'Namni tawbateefi gaarii hojjate, inni tawbatiinsa gara Rabbii tawbate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 72, '(gabrooni Rabbii) isaan ragaa cubbuu hin baaneefi yeroo tapha bira qaxxaamuranis kabajaadhaan qaxxaamuraniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 73, 'Isaan warra yeroo keeyyattoota Gooftaa isaanitiin yaadachiifaman [kan hubataniifi fudhatan ta’anii malee] duudaafi jaamaa ta’anii ishee irratti hin kufneedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 74, 'Ammas isaan warra jedhani “Gooftaa keenya! Niitolii keenyaafi sanyiiwwan keenya irraa gammachuu ijaa kan ta’an nuuf kenni. Warra Rabbiin sodaataniif imaama (dursaa) nu taasisi”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 75, 'Isaan sun waan obsaniif jecha (Jannata keessatti) iddoo ol aanaa ta’e (gamoo) mindeeffamu. Ishee keessattis kabajaafi nageenya qunnamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 76, 'Ishee keessa zalaalam jiraatu. Isheen iddoo qubannaafi jireenyaa tahuun waa bareeddee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 77, 'Jedhi: “Odoo kadhaan (Iimaanni) keessan jiraachuu baatee, silaa Gooftaan kiyya homattuu isin hin lakkaa’u ture, Dhugumatti isin sobsiiftanii jirtu, adabbiin (isiniif qophaa’e) isin qabataa ta’a.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 1, 'Xaa Siin Miim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 2, 'Tun keeyyattoota kitaaba (dhugaa soba irraa) adda baasaa ta’eeti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 3, '(Yaa Muhammad!) Ati Mu’uminoota ta’uu dhabuu isaaniitiif [gaddaan] lubbuu kee baasuun siif sodaatama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 4, 'Odoo feenee samii irraa mallattoo isaan irratti buufnee (isheedhaaf ajajamuun) mormoowwan isaanii isheedhaaf gadi jedhoo taati ture.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 5, 'gorsi (kitaabni) haaraan Rahmaan irraa isaaniif kan dhufu hin taane isa irraa garagaloo tahan malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 6, 'Dhugumatti isaan [Qur’aana kana] sobsiisaniiru. Oduun waan isaan itti qishnaa (qoosaa) turanii isaanitti dhufuuf jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 7, 'Sila isaan gara Dachii hin ilaallee akka nuti gosoota gaggaarii hunda irraa meeqaatama ishee keessatti biqilchine?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 8, 'Sana keessa mallattootu jira, Irra hedduun isaanii kan amanan hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 9, 'Dhugumatti Gooftaan kee Isatu injifataa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 10, 'Yeroo Gooftaan kee Muusaa waame [yaadadhu] “Gara ummata miidhaa dalagdootaa deemi” [jedhee].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 11, '“Gara ummata Fir’awn [dhaqi]. Sila Rabbiin hin sodaatanii?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 12, '[Muusaan] ni jedhe: “Gooftaa kiyya! Dhugumatti, ani na sobsiisuun sodaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 13, '[Yoo na sobsiisan] qomti kiyya ni dhiphata. Arrabni kiyyas hin diriiru. Kanaafuu gara Haaruunitti ergi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 14, 'Isaaniif yakka [dhiigaatu] narra jira; kanaafuu na ajjeesuun sodaadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 15, '[Rabbiin] ni jedhe: “lakki! (si hin ajjeesanu) Isin lamaan mallattoolee keenyaan deemaa, Nuti isinii waliin dhageeffatoota.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 16, '“Fir’awnitti dhaqaatii ‘Nuti ergamaa Gooftaa aalama hundaati’ jedhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 17, '“Ilmaan Israa’iil nu waliin gadi dhiisi” jechuudhaan [ergamne jedhaa].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 18, '[Fir’awni] ni jedhe: “sila nuti mucaa xiqqaa taatee of biratti si hin guddifnee? Umrii kee irraas waggoota baay’ee nu keessa hin turree?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 19, 'Dalagaa kee ishee dalagde (ajjeechaa raawwatte) san hin hojjannee? Ati gantoota irraahi” [jedhe].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 20, '[Muusaanis] ni jedhe: “Yeroo san wallaaltota irraa ta’een ishee hojjadhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 21, 'Yeroman isin sodaadhun isin irraa dheesse; Gooftaan kiyya beekumsa naaf kenne, ergamtoota irraa na godhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 22, 'Sun tola ati narratti himattuudha Ilmaan Israa’iil gabra godhachuu keetiin”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 23, 'Fir’awn “gooftaan aalama hundaa maali?” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 24, '[Muusaan]: “gooftaa Samiilee, Dachiifi waan gidduu isaan lamaaniiti; yoo kan dhugoomsitan taatan [itti amanaa]” jedheen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 25, '[Fir’awnis] namoota maddii isaa jiraniin “Sila [waan inni jedhu] hin dhageessanuu?” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 26, '[Muusaan] “Gooftaa keessaniifi Gooftaa abbootii keessan kan jalqabaati” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 27, '[Fir’awn] “ergamaan keessan inni gara keessanitti ergame dhugumatti maraatuudha” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 28, '[Muusaan] “Gooftaa Bahaa, Dhihaafi waan gidduu isaan lamaanii jiruuti; yoo kan hubattan taataniif [itti amanaa]” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 29, '[Fir’awn] “dhugumatti, yoo ati ana malee gabbaramaa biraa godhatte, hidhamtoota irraan si taasisa” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 30, '[Muusaan] “sila odoo waan (ragaa) ifa ta’een sitti dhufeellee moo?” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 31, '[Fir’awn] “yoo warra dhugaa dubbatan irraa taate isa fidi” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 32, '[Muusaan] ulee isaa ni darbateYeroma san isheen jawwee ifa galaa taate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 33, 'Harka isaas [bobaa isaa jalaa] ni baase; Yeroma san isheen warra ilaalaniif adii taate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 34, '[Fir’awn] qondaaltota naanna’a isaa jiraniin “dhugumatti, kun saahiree (falfalaa) akkaan beekaadha” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 35, '“Sihrii isaatiin dachii keessan irraa isin baasuu fedhaa, isin immoo maalitti na ajajju” (jedhe).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 36, '[Isaanis] ni jedhan: “Isaafi obboleessa isaas tursiisi, Magaalota keessatti walitti qabdoota ergi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 37, 'Saahiroota (falfaltoota) beekumsa qaban hundaan sitti haa dhufanu.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 38, 'Saahiroonnis beellama guyyaa beekamaatiif walitti qabaman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 39, 'Namootaanis ni jedhame: “sila isin walitti qabamtanii? (Dafaa walitti qabamaa);', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 40, 'Yoo isaan kan injifatan ta’an, Saahiroota (falfaltoota) hordofuun keenya ni kajeelamaa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 41, 'Falfaltoonni yeroma dhufan, Fir’awniin “Sila yoo nuti mo’attoota taaneef mindaan nuuf jiraa? ” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 42, '[Fir’awnis] “Eeyyeen; isin yoosan [natti] dhihaattota irraa taatu” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 43, 'Muusaanis “Isin waan darbuu feetan darbaa” isaanin jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 44, 'Haadoowwaniifi uleewwan isaanii ni darban; “Jabeenya Fir’awniin kakannee! Nuti dhugumatti nutu injifattoota” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 45, 'Muusaanis ulee isaa ni darbate, Yeroma san isheen waan isaan sobaan fakkeessan hunda liqimsite.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 46, 'Falfaltoonnis [yeroma kana argan] sujuuda bu’aa ta’anii gadi kufan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 47, 'Ni jedhanis: “Gooftaa aalama hundaatti amanne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 48, 'Gooftaa Muusaafi Haaruunitti.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 49, '[Fir’awni] ni jedhe: “Odoo ani isiniif hin hayyamin isatti amantanii? inni hangafa keessan kan sihrii isin barsiiseedha. Fuulduratti [waan ta’u] beekuuf jirtu, Dhugumatti, ani Harkoowwan keessaniifi Lukoowwan keessan wal-faallessuudhaan isin irraan mummura, Dhugumatti hunduma keessan isinin fannisa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 50, 'Ni jedhan: “Rakkoon hin jiru! nuti gara Gooftaa keenyaa deebi’oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 51, 'Nuti jalqaba mu''imintootaa ta’uudhaan Rabbiin keenya badiilee teenya nuuf araaramuu ni kajeella”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 52, 'Gara Muusaatti beeysisa goone “halkaniin gabroota kiyyaan deemi (baqadhu) isin [diinota keessaniin] hordofamoodha” jechuun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 53, 'Fir’awni magaalota keessatti walitti qabdoota ergee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 54, '“Warri kun gareewwan xiqqoowaniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 55, 'Isaan nuuf dallansiisoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 56, 'Nuti hedduuwwan of eegdota” [jedhe].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 57, 'Ashaakiltiileefi burqaawwan irraa isaan baafne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 58, 'Kuusaa qabeenyaafi iddoowwan kabajamaa irraas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 59, 'Akka kanatti Ilmaan Israa’iil ishee dhaalchifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 60, 'Bariifatoo ta’anii isaan hordofan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 61, 'Yeroma gareen lamaan wal argan, gareen Muusaa “nuti [garee Fir’awniin] dhaqqabamoodha” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 62, '[Muusaan] ni jedhe: “lakkisaa! Dhugumatti, Gooftaan kiyya na wajjin jira, Inni [furmaatatti] na qajeelcha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 63, 'Gara Muusaatti beeysisa goone “ulee keetiin galaana rukuti” jechuun. [Yeroma inni dhahu] qoqqoodamee Kutaan qoodama isaa hunduu akka gaara guddaa ta’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 64, 'Bakka sanatti warra biraa dhiheessine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 65, 'Muusaafi warra isa waliin turan hundaa ni baraarsine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 66, 'Sana booda warra biroo bishaaniin dhidhimsiifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 67, 'Kana keessa mallattootu jira, Irra hedduun isaanii Mu’uminoota hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 68, 'Rabbiin kee, Isumatu injifataa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 69, 'Seenaa Ibraahim isaan irratti dubbisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 70, 'Yeroo inni abbaafi ummata isaatiin “maal gabbartu?” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 71, '“Taabotawwan gabbarra; ishee [gabbaruu] irras warra turu taane” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 72, '[Ibraahiim] ni jedhe: “sila yeroo isaan waammattan isin dhagahanii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 73, 'Yookiinis isin fayyaduu? Yookiinis isin miidhuu?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 74, '[Isaanis] “Lakkisaa; abbootii keenya akkas kan dalagan agarre” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 75, '[Ibraahiim] ni jedhe: “Sila waan gabbaraa turtan hubattanii jirtuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 76, 'Isiniifi abbootiin keessan kan duraaniis?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 77, 'Isaan anaaf diinota; garuu Gooftaa aalamootaa malee (inni jaalalloo kooti).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 78, '[Inni] isa na uume, isatu na qajeelcha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 79, 'Inni Isa na nyaachisuufi na obaasuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 80, 'Yeroo an dhukkubsadhes, Isatu na fayyisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 81, 'Isa na ajjeesuufi Sana booda na jiraachisuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 82, 'Isa guyyaa murtii badii kiyya akka naaf araaramu kajeeluudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 83, 'Gooftaa kiyya! beekumsa naaf kenni, Namoota gaggaariitti na dhaqqabsiisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 84, 'Dhaloota boodaa keessattis faaruu gaarii naaf taasisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 85, 'Dhaaltota Jannata qananii (dhaalan) irraas na taasisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 86, 'Abbaa kiyyaaf araarami, inni jallattoota irraa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 87, 'Guyyaa isaan (gabroonni) kaafaman na hin xinneessin.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 88, 'Guyyaa qabeenyiifi ilmaanis homaa hin fayyadne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 89, 'Nama onnee qulqulluudhaan Rabbitti dhufe malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 90, '[Guyyaa] Jannanni warra Rabbiin sodaataniif dhiheeffamte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 91, '[Guyyaa] Ibiddi jahannam jallattootaaf muldhifamte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 92, '[Guyyaa] “wanti isin gabbaraa turtan eessa jiru?” isaaniin jedhame.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 93, '“Rabbii gaditti (ta’anii) Sila isiniif tumsuu? Yookiin ni tumsamuu?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 94, 'Isaaniifi jallattoonni ishee keessatti darbamanii konkolaatan..', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 95, 'Waraanni Ibliis hunduu (ni darbaman).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 96, 'Isaan ishee keessatti wal falmaa ni jedhu:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 97, 'Allaahn kakannee! Nuti dhugumatti jallina ifa ta’e keessa turre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 98, 'Yeroo Gooftaa aalamtootaatti isin qixxeessinu san.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 99, 'Ficiltoota malee homtuu nu hin jallisne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 100, 'Araarsitoonni tokkollee nuuf hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 101, 'Hiriyaan garaa laafus (hin jiru)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 102, 'Odoo (addunyaatti) deebiin tokkollee nuuf jiraatee silaa Mu’uminoota irraa taana turre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 103, 'Kana keessa mallattootu jira. Irra hedduun isaanii Mu’uminoota hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 104, 'Dhugumatti Gooftaan kee isumatu injifataa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 105, 'Ummanni Nuuh ergamtoota sobsiiftee jirti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 106, 'Yeroo obboleessi isaanii Nuuh jedheen: “Sila Rabbiin hin sodaattanii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 107, 'Ani isiniif ergamaa amanamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 108, 'Rabbiin sodaadhaa, naaf ajajamaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 109, 'Ani isa (waamicha kana) irratti mindaa tokkollee isin hin gaafadhu; Mindaan kiyya Gooftaa aalama hundaa irratti malee hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 110, 'Rabbiin sodaadhaa naaf ajajamaa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 111, '[Ummanni isaas] “sila nuti odoo warri gadi aanoon si hordofanii jiranuu siif amannaa?” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 112, '[Innis] ni jedhe: “Waan isaan dalagaa turan maalittin beeka?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 113, 'Odoo beektanii qormaanni isaanii Gooftaa kiyya qofa irra malee hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 114, 'Ani ari’aa (fageesaa) Mu’uminootaa hin taane', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 115, 'Ani akeekkachiisaa ifa bahaa ta’e malee hin taane.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 116, '[Isaan] ni jedhan: “Yaa Nuuh! [waan jettu irraa] yoo dhorgamuu baatte, warra dhakaan cafaqaman irraa taata.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 117, '[Nuuh] ni jedhe: “Yaa gooftaa kiyya ummanni koo na sobsiisaniiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 118, 'Ati gidduu kiyyaafi gidduu isaaniitti murtii [haqaa] murteessi, Anaafi Mu’uminoota irraa nama na waliin ta’anis baraari.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 119, 'isaafi namoota isa waliin turan doonii guutamte keessatti isaan baraarre', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 120, 'Ergasii booda [bilisa isaan baasuutii] warra hafan ni dhidhimsiifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 121, 'Kana keessa mallattootu jira, Garuu irra hedduun isaanii Mu’uminoota hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 122, 'Dhugumatti Gooftaan kee Isatu injifataa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 123, 'Aad (ummanni huud) ergamtoota sobsiifte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 124, 'Yeroo obboleessi isaanii Huud “Sila (Rabbiin) hin sodaattanii? isaaniin jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 125, 'Ani isiniif ergamaa amanamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 126, 'Rabbiin sodaadhaa naaf ajajamaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 127, 'Ani isa (waamicha kana) irratti mindaa tokkollee isin hin gaafadhu; mindaan kiyya Gooftaa aalama hundaa irratti malee hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 128, 'Sila isin kan [nama tarutti] qishnitan taatanii iddoo ol fuudhamaa hunda irratti [gamoo] mallattoo ijaartuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 129, 'Kuusaa bishaaniitiifi gamoowwanis akka waan keessatti haftanuutti tolfattuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 130, 'Yeroo [namoota adabbiif] qabdan gara jabeeyyii taatanii qabdan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 131, 'Rabbiin sodaadhaa naaf ajajamaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 132, 'Isa waan [gaggaarii] isin beektan hundaan isin badhaase sodaadhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 133, 'Beyladootaafi ilmaaniinis isin badhaase.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 134, 'Ashaakiltiiwwaniifi burqaawwaniinis [isin qananiise].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 135, 'Ani adabbii Guyyaa guddaan isin irratti sodaadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 136, '[Ummanni Huud] ni jedhan: “Yoo nu gorsites yoo gorsitoota irraa ta’uu baattes nurratti waluma qixa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 137, 'Kun amaluma warra duriiti malee waan biraa miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 138, 'Nuti kan adabamnuu miti” [jedhan].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 139, 'Isa sobsiisan. Nutis isaan balleessine. Dhugumatti, kana keessa mallattootu jira. irra hedduun isaanii mu’uminoota hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 140, 'Dhugumatti, Rabbiin kee Isatu injifataa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 141, 'Samuud (ummanni Saalih) ergamtoota sobsiifte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 142, 'Yeroo obboleessi isaanii Saalih isaaniin jedhe: “Sila Rabbiin hin sodaattanii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 143, 'Ani isiniif ergamaa amanamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 144, 'Rabbiin sodaadhaa; ajaja kiyya fudhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 145, 'Ani isa (waamicha kana) irratti mindaa tokkollee isin hin gaafadhu; Mindaan kiyya Gooftaa aalama hundaa irra malee hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 146, 'Sila waan as jiru (qabeenya kana) keessatti nageenyaan dhiifamtuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 147, 'Ashaakiltiiwwaniifi burqaawwan keessatti,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 148, 'Oorruuwwaniifi muka tamirii ijji ishee Bilchaataa taate (keessattis ni dhiifamtuu?)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 149, 'Cocollee taatanii gaarreen irraas manoota bocattuu (soqattuu?)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 150, 'Rabbiin sodaadhaa; ajaja kiyyas fudhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 151, 'Ajaja warra daangaa dabranii hin fudhatinaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 152, 'Isaan Dachii keessatti badii raawwataniifi toltuu hin raawwannee” [jedhe].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 153, '[Isaan] ni jedhan: “Ati namoota sihriin (falfalli) baay’een itti godhame irraa isa tokkoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 154, 'Ati namuma akka keenyaati malee waan biraatii miti, Warra dhugaa dubbatan irraa yoo taate mallattoo fidi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 155, '[Saalihis] ni jedhe: “Isheen tun Gaala; isheef carraa dhugaatiitu jira; Isiniifis carraa dhugaatii guyyaa beekamaa ta’eetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 156, 'Hamtuun ishee hin tuqinaa, [Yoo akkas gootan] adabbii guyyaa guddaatu isin mudata.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 157, 'Ishee waraananii sheena’oota ta’an', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 158, 'Adabbichis isaan qabate, Kana keessa mallattootu jira. Irra hedduun isaanii Mu’uminoota hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 159, 'Dhugumatti Gooftaan kee Isatu injifataa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 160, 'Ummanni Luuxis ergamoota sobsiifte', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 161, 'Yeroo obboleessi isaanii Luux isaanin jedhu: “Sila Rabbiin hin sodaattanii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 162, 'Ani isiniif ergamaa amanamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 163, 'Rabbiin sodaadhaa; ergaa kiyyas fudhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 164, 'Ani isa (waamicha kana) irratti mindaa tokkollee isin hin gaafadhu, Mindaan kiyya Gooftaa aalama hundaa irra malee hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 165, 'Sila isin (qunnamtii saalaatiif) aalama hunda irraa dhiirotatti dhuftuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 166, 'Waan Gooftaan keessan isiniif uume jaartiiwwan teessan iraa ni dhiiftuu? Dhugumatti isin ummata daangaa dabritoota” [jedhe].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 167, '[Isaan] ni jedhan: “Yaa Luux! Yoo [waan jettu irraa] hin dhorgamin, dhugumatti warra [biyyarraa] baafaman irraa taata.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 168, '[Luuxis] ni jedhe: “Dhugumatti, ani namoota dalagaa keessan jibban irraayyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 169, 'Yaa Gooftaa kiyya! Anaafi maatii kiyya waan isaan dalagan irraa nu baraari.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 170, 'Isaafi maatii isaas walumaa galatti ni baraarre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 171, 'Dullattii warra [adaba keessatti] hafan irraa taate malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 172, 'Ergasii warra biroo ni balleessine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 173, 'Bokkaa [adabbii] isaan irratti roobsine, Roobni warra akeekkachiifamanii waa fokkate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 174, 'Dhugumatti, kana keessa mallattootu jira, Irra hedduun isaaniis Mu’uminoota hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 175, 'Dhugumatti Gooftaan kee Isatu injifataa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 176, 'Jiraattonni Aykah (bosonaa) ergamoota sobsiifte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 177, 'Yeroo Shu’ayb isaaniin jedhu: “sila Rabbiin hin sodaattanuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 178, 'Ani isiniif ergamaa amanamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 179, 'Rabbiin sodaadhaa; ergaa kiyyas fudhadhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 180, 'Ani isa (waamicha kana) irratti mindaa tokkollee isin hin gaafadhu, Mindaan kiyya Gooftaa aalama hundaa irra malee hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 181, 'Safara guutaa; [haqa namaa] hir’iftoota irraa hin ta’inaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 182, 'Madaala sirrii ta’een madaalaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 183, 'Namoota wantoota isaanii irraa hin hir’isinaa, badii hojjattoota taataniis dechii keessa badiin hin deeminaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 184, 'Isa isiniifi dhaloota duraanii uume sodaadhaa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 185, '[Isaan] ni jedhan: “Ati namoota sihriin (falfalli) baay’een itti godhame irraa isa tokkoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 186, 'Ati nama fakkii keenyaa malee (uumaa biroo) hin taane; nutis sobdoota irraa ta’uu si yaadna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 187, 'Yoo warra dhugaa dubbatan irraa taate samii irraa cittuu wahii nurratti kuffisi” [jedhaniin].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 188, '[Inni] ni jedhe: “Gooftaan kiyya waan isin dalagdan beekaadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 189, 'Isa sobsiisan, Adabbiin guyyaa gaaddisaa (duumessa gurraachaa) isaan qabate, Dhugumatti, inni adabbii guyyaa guddaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 190, 'Dhugumatti, kana keessa mallattootu jira, irra hedduun isaanii mu’uminoota hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 191, 'Gooftaan kee Isatu injifataa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 192, 'Dhugumatti, inni (Qur’aanni) buufamaa Gooftaa aalama hundaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 193, 'Ruuhii amanamaa ta’e (Jibriiltu) isaan bu’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 194, 'onnee kee irratti [buuse] Akka ati akeekkachiiftota irraa taatuuf jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 195, 'Qooqa Arabiffaa ifaa ta’een.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 196, 'Dhugumatti, inni (waa’een Qur’aanaa) kitaabota durii keessa jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 197, 'Sila beektonni Ilmaan Israa’iil isa beekuun mallattoo isaaniif (warra Makkaatiif) hin ta’uu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 198, 'Odoo garii nama Araba hin ta’inii irratti isa (Qur’aana) buufnee,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 199, 'Innis isaan irratti dubbisee, isaan kan isatti amanan hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 200, 'Akka kanatti isa (diddaa Qur’aanaa) onneewwan badi raawwattootaa keessa seensifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 201, 'Hanga adabbii laalessaa arganitti isatti hin amananu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 202, 'Inni (adabbichi) odoo isaan hin beekin tasa isaanitti dhufa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 203, '[Akka amannuuf] “yeroon nuuf kennamaa?” jedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 204, 'Sila adabbii keenya jarjarsiifatuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 205, 'Mee naaf himi! Odoo waggoota hedduuf isaan qanansiifnee,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 206, 'Sana booda wanti isaan ittiin akeekkachiifamaa turan isaanitti dhufee,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 207, 'Wanti isaan ittiin qanani’aa turan [adaba Rabbii irraa] maal isaan irraa deebisa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 208, 'Magaalotarraa tokkollee akeekkachiisaan isaaniif jiraatu malee isaan hin balleessine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 209, '[Kun] yaadachiisa; Nuti miidhaa hojjattoota hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 210, 'Sheyxaanonnis isaan [Qur’aanaan] hin buune.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 211, 'Isaaniifis hin malu, [Isa fiduu] hin danda’anus.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 212, 'Dhugumatti, isaan isa dhagahuu irraa fageeffamoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 213, 'Rabbii waliin gooftaa biraa hin kadhatin, [Yoo akkas goote] warra adabaman irraa taata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 214, 'Firoota kee dhihoo ta’an akeekkachiisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 215, 'Mu’uminoota irraa nama si hordofeef nyaara (kooluu) kee gadi qabi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 216, 'Yoo ajaja kee fudhachuu didanis “Ani waan isin hojjattan irraa qulqulluudha” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 217, '[Rabbii] injifataa, rahmata godhaa ta’e irratti hirkadhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 218, 'Isa yeroo ati dhaabbattu si argu [irratti hirkadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 219, '[Isa] sochiiwwan kee warra sagadan keessatti [argu irratti hirkadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 220, 'Dhugumatti, Inni Isatu argaa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 221, 'Sheyxaanonni eenyu irratti akka bu’an isinitti himuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 222, 'Kijibaa, badii hojjataa hunda irratti buuti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 223, 'Wanta dhagahan [waa himtuu irratti] gadi buusu. Irra baay’een isaanii kijibdoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 224, 'Walaleessitoota jallattootatu isaan hordofa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 225, 'Isaan sulula (oduu) hunda keessa akka seenan hin agartuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 226, 'Isaan waan hin dalagne kan dubbatan ta’uu [hin agartuu]?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 227, 'Warra amananiifi gaggaarii hojjatan, kan baayisanii Rabbiin faarsan, erga roorrifamii booda [walaloodhaan] of irraa deebisan [harka kaffalatan] malee [Isaan hin komatanu]. Isaan miidhaa dalaganis [eega du’anii booda] deebifama akkamii akka deebifaman beekuuf jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 1, 'Xaa Siin tun keeyyattoota Qur’aanaafi kitaaba ibsaa ta’eeti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 2, 'Mu’umintootaaf qajeelfamaafi gammachiisaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 3, '(Isaan) warra Salaata dhaaban, kan zakaa kennaniifi isaan Aakhiraatti amananiidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 4, 'Isaan Aakhiraatti hin amanin, [gadhee] dalagaalee isaanii isaaniif miidhagsine. Isaanis ni dhama’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 5, 'Isaan sun warra [addunyaa keessatti] adabbiin hamaan isaaniif jiruudha. Isaan Aakhiraatti isaanumatu hoonga’oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 6, 'Dhugumatti, ati Qur''aana [Rabbii] ogeessa, beekaa ta’e irraa qunnamta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 7, 'Yeroo Muusaan maatii isaatiin “ani ibidda argeen jira; [deemeetin] ishee irraa odeeffannoo [waa’ee karaa] isiniif fida. Yookiin immoo xombooraa qabsiifamaa wahii isiniif fida akka isin ho’ifattaniif” jedhe [yaadadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 8, 'Yeroma inni ishee bira dhaqu akkana jechuun isatti lallabame: “Inni ibidda keessa jiruufi Inni cinaa ishee jiru khayriin isaa baay’ate; Rabbiin gooftaa aalamaa ta’es qulqullaahe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 9, 'Yaa Muusaa! Dubbiin Ani Allaah injifataa, ogeessa ta’eedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 10, 'Ulee kee darbi.” [Ni darbes] yeroma akka bofaatti kan isheen sochootu argu of duuba deebi’ee dheesse, Duuba hindeebine, “Yaa Muusaa! hin sodaatin, ani ergamtoonni na biratti hin sodaatanu (jenneen).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 11, 'Nama miidhaa dalagee ergasii hamtuu boodaan toltuu bakka buuse malee. Ani [isaaf] araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 12, 'Harka kee bobaa kee keessa seensisi; isheen adii taatee baati, fokkachuudhaan maleetti. Mallattoowwan saglaniin gara fir’awniifi ummata isaa (deemi). isaan ummata finciltoota ta’anii jiru.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 13, 'Yeroma mallattoowwan keenya ifa taatee isaanitti dhuftu “kun Sihrii (falfala) ifa bahaadha” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 14, 'Ishee morman Odoo lubbuuleen isaanii mirkaneessituu, miidhaafi boonaaf jecha. booddeen badii raawwattootaa akkam akka ture ilaali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 15, 'Dhugumatti, Nuti Daawuudiifi Suleeymaaniif beekumsa kennineerra. Isaan lamaan nijedhan “faaruun hundi kan Rabbii Isa gabroota Isaa mu’uminootaa baay’ee irra nu caalchiseeti".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 16, 'Suleeymaan Daawuudiin ni dhaale, Ni jedhe: “isin Yaa ilmaan namaa! Qooqa simbiraa barsiifamneerra. Wanhundarraa kennamnee jira. dhugumatti kun tola ifa bahaadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 17, 'Suleeymaaniif waraanni isaa jinnoota, namootaafi allaattii irraa walitti qabame; isaanis walitti ittifamoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 18, 'hanga holqa mixii (Dagandaa) irra dhufanitti, mixiin takka nijette “isin Yaa tuuta mixii! manneen keessan seenaa, akka Suleeymaaniifi waraanni isaa odoo hin beekin isin hin caccabsineef ”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 19, 'Innis jecha ishee irraa kolfuun ni seeqate. Ni jedhes: “Yaa Gooftaa kiyya! Akkan ni’imaa kee ishee anaafi abbaa haadha kiyya qanansiifte galateeffadhuufi hojii gaarii ati jaalattu hojjadhu na barsiisi. Rahmata keetiinis gabroota kee gaggaarii keessa na seensisi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 20, 'Simbirroo to’atee ni jedhe: “maaliifan aduddee (Hud-hud) hin argine? Moo sila isumatu fagaattota irraa ta’e?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 21, 'Dhugumatti, adabbii cimaan isa adaba, Yookiin isan gorra’a, Yookiin immoo ragaa ifaa ta’een natti haa dhufu.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 22, '(Allaatichi) [Yeroo hanga] fagoo hin taane turee ni jedhe: “waan ati hin barin bareen jira, Saba’i irraas oduu dhugaa ta’een sitti dhufeera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 23, 'Ani Dubartii isaan bulchitun arge, Tan Waan hunda irraa kennamte, isheedhaaf sireen guddaan jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 24, 'Isheefi ummata ishee kan Rabbii achitti Aduuf sujuudanin arge. Sheyxaanni dalagaalee isaanii isaaniif miidhagse. karaa [qajeelaa] irraa isaan deebise. Isaan hin qajeelanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 25, 'Akka isaan Rabbii waan dhokataa Samiifi Dachii ifatti baasuufi waan isin dhoksitaniifi mul’iftan beekuuf sujuuda hin goone [isaan dhorgee jira].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 26, 'Allahn Isa malee dhugaan gabbaramaan hin jiruInni Gooftaa arshii guddaati.” [1]', '[1] bakka kana sujuuda qaraatii qur''aanaattu jira.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 27, '[Suleymaan] ni jedhe: “Dhugaa jetteefi warra sobdoota irraa taatee kee fuuldura ilaalla.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 28, 'Xalayaa kiyya kanaan deemii gara isaaniitti darbi eegasii isaan irraa gara galii maal akka deebisan ilaali.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 29, '[Mootittiin yeroo xalayaa gartu] ni jette: “isin Yaa qondaaltota [kiyya]! ani xalayaan kabajamaan natti darbameera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 30, 'Inni Suleymaan irraayyi, Innis [qabiyyeen isaa] ‘maqaa Rabbii akkaan mararfataa akkaan rahmata godhaa ta’eetiin’.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 31, 'Narratti hin booninaa; Muslimtoota ta’aatii natti kottaa [jedha].”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 32, 'Ni jette: “Yaa qondaaltota [kiyya]! Dhimma kiyya irratti yaada na akeekaa; Ani hangan isin hirmaattanitti dhimma kamillee murteessitu hin taane.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 33, '[Qondaalonnis] nijedhan “Nuti abbootii humnaafi abbootii lola cimaati, Ajajni gara keeti, Maal akka ajajju ilaali”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 34, 'Ni jette: “Mootonni yeroo magaalaa tokko seenan ishee balleessu. Kabajamtoota warra ishees xiqqaatoo taasisu, akkasuma dalagu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 35, 'Ani kennaa wahii gara isaaniitti ergituudha, Ergamtoonni maaliin akka deebi''an eeyduudha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 36, 'Yeroma Suleymaanitti dhufu ni jedhe: “Sila isin qabeenyaan na gargaartuu? Wanti Rabbiin naaf kenne waan isiniif kenne caala. Dhugumatti isin kennaa keessaniin gammaddu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 37, 'Gara isaanii deebi’i, Nuti waraana isaan dura dhaabbachuudandeettiin isaaniif hinjirreen isaanitti dhufna, Ishee irraa salphinaan xiqqaatoo ta’anii isaan baafna.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 38, 'Ni jedhe: “Yaa qondaaltota [kiyya]! eenyutu Isin irraa siree ishee natti fida Odoo isaan Muslimtoota ta’anii natti hin dhufe ?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 39, 'Jabaan Jinnoota irraa ta’e tokko ni jedhe: “Ani isaan sitti dhufa odoo ati iddoo keetii irraa hin ka''in dura. Ani kana irratti cimaa amanamaadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 40, 'Inni beekumsi kitaaba irraa ta’e isa bira jiru ni jedhe: “Ani [libsattee] odoo ijji kee sitti hin deebinen siif fida.” [Suleymaan] yeroma isa biratti ragga’ee argu ni jedhe: “kun tola Gooftaa kootii irraayyi. Akka ani Isa galateeffadhuufi Isatti kafaru na mokkoruuf [kana godhe]. Namni Isa galateeffate, kan inni galateeffatu lubbuma isaatiif. Namni kafare [isuma irratti]. Gooftaan kiyya dureessa, arjaadha” [jedhe]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 41, 'Ni jedhe: “siree ishee isheef wallaalchisaa [Siree ishee beekuutti] ni qajeelti moo warra hin qajeelle irraa taatii ilaalla.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 42, 'Yeroma isheen dhuftu sireen kee akka kanaa jedhame, Isheenis “inni akkuma waan isaati” jette. [Suleymaanis] “dura ishee beekumsa kennamnee, Muslimtoota taaneerra” (jedhe).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 43, 'Wanti isheen Rabbii gaditti gabbaraa turte [Islaama irraa] ishee deebise. Isheen ummata kaafirootaa irraa turte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 44, '“Gamoo seeni” isheedhaan jedhame, Yeroma isa argitu haroo isa seetee, mogolee ishee lamaan irraa saaqxe, [Suleymaan] ni jedhe: “Inni kun masaraa mucuceeffamaa daawwitii irraa ta’ee [bishaan keessaan mul’atuudha].” [Isheenis] “Gooftaa kiyya! Ani lubbuu Tiyya miidheera, Suleymaaniin wajjin Allaah Rabbii aalama hundaa ta’etti harka kenne (Islaamawe)” jette.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 45, 'Dhugumatti, gara Samuuditti obboleessa isaanii Saalih “Allaah qofa gabbaraa” jechuun erginee jirra, Yerama san isaan garee lama tan walfalmitu tahan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 46, '[Saalihis] ni jedhe: “Yaa ummata kiyya! Maaliif toltuu dura hamtuu (adabbii) jarjarsiifattu? maaliif Rabbiin araarama hin kadhanne Akka rahmanni isinii godhamuuf?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 47, '[Isaan] “Nuti siifi namoota si waliin jiraniin hooddane (milkii laallanne)” jedhan, [Saalihis] nijedhe "hooddannaan keessan Rabbiin bira, Garuu isin ummata mokkoramoodha”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 48, 'Magalattii keessa namoota sagal kan gaarii hin hojjanne lafa balleesantu ture.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 49, 'Ni jedhan Rabbiin waliif kakadhaa isaafi maatii isaa halkan keessa akka balleessinu, eegasii fira isaatiin nijenna ‘nuti ajjeechaa maatii isaa bira hin jirru; nuti dhugaa dubbattoota."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 50, 'Isaan shira shiran, Nutis shira shirre odoo isaan hinbeekin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 51, 'Booddeen shira isaanii akkam akka ta’e ilaali! Nuti isaaniifi ummata isaanii guutumatti balleessine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 52, 'Kun manneen isaaniiti sababa isaan miidhaa hojjataniin ontuu taate. kana keessa namoota beekaniif mallattootu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 53, 'Isaan amananii Rabbiin sodaataa turan nagaya baafne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 54, 'Luuxiin yeroo inni ummata isaatiin jedhe “sila odoo argitanii gocha fokkataa hojjattuu?” [yaadadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 55, '“Sila isin fedhii (qunnamtii saalaatiif) dubartii dhiiftanii dhiiratti dhuftuu? Dhugumatti isin ummata wallaaltota.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 56, 'Deebiin ummata isaas hintaane jechuu malee “Maatii Luux magaalaa keessan irraa baasaa, isaan namoota qulqulleeffatanii”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 57, 'Isaafi maatii isaa ni baraarre, niitii isaa malee warra [adabbii keessatti] hafan irraa ta’uu ishee murteessine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 58, 'Rooba [dhagaa] isaan irratti roobsine, Roobni warra dinniinamanii waafokkatee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 59, '(Yaa Muhammad) Jedhi: “Faaruun hundi kan Rabbiiti, nageenyi gabroota Isaa kan [Inni] filate irra haa jiraatu, Sila Rabbi moo wantoota isaan [Isatti] qindeessantu caala?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 60, 'Sila Inni samiileefi dachii uumee, samii irraa bishaan isiniif buusee ergasii ashaakiltiiwwan miidhagoo ta’an isaan magarsine [akka isa homaa hin uumneetii]? Mukkeen ishee biqilchuun (dandeettiin) isiniif hintaane, Sila Allaah wajjin gooftaan biraa ni jiraa? Isaan ummata Rabbitti qixxeessaniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 61, 'Sila Isa dachii tasgabbooftuu taasise, kan ishee keessattis laggeen taasise, kan isheef (gaarreen) gadi lixan taasise, kan gidduu galaanota lamaatti girdoo taasise moo [warra isaan isatti dabalantu caala]? Sila Rabbii wajjin gabbaramaan biraa ni jiraa? Dhugumatti irra hedduun isaanii hin beekanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 62, 'Sila Isa yeroo namni rakkataan (muddamaan) Isa kadhate jalaa owwaatee hamtuu saaquufi bakka bu’oota dachii isin taasisu [moo waan isaan Rabbitti dabalantu caala?] Sila Rabbii wajjin gabbaramaan biraa ni jiraa? Hangi isin gorfamtan xiqqaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 63, 'Sila isa dukkanoowwan dachii goggoyduufi galaanaa keessatti isin qajeelchu; kan qilleensa rahmata Isaa dura gammachiisaa godhee ergu (caalamoo warra isaan Rabbii achitti gabbarantu caala?) Sila Rabbii wajjiin gabbaramaan biraa ni jiraa? Allaahn waan isaan [Isatti] qindeessan irraa ol ta’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 64, 'Sila inni uumuu jalqabee ergasii isa deebisu eenyu? Ammas eenyutu dechiifi samii irraa hiree isiniif hira? Sila gabbaramaan biraa Allaah wajjin ni jiraa? Yoo kan dhugaa dubbattan taataniif ragaa keessan fidaa” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 65, '“Wanti samiileefi dachii keessaa hunduu Rabbiin malee wanta fagoo (ghaybii) hin beeku. Yoom akka kaafaman hin beekanu” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 66, 'Sila beekumsa isaaniitu waa’ee Aakhiraatti dhaqqabee? Lakkisaa isaan ishee irraa shakkii keessa jiru; dhugumatti isaan ishee irraa jaamoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 67, 'Isaan kafaran ni jedhan: “Sila yeroo [duunee] biyyee taane, nuufi abbootiin keenya, nuti kaafamoodhaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 68, 'Dhugumatti, nuufi abbootiin keenya nuun duratti kana waadaa galamnee turre. kun ogbarruu warra durii malee hin taane” [jedhan].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 69, '“Dachii keessa deemaatii booddeen badii raawwattootaa akkam akka ta’e ilaalaa” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 70, 'Isaan irratti hin gaddin, shira isaan baasanirraa dhiphina keessatti hin ta’in.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 71, '“Waadaan kun yoomi Yoo warra dhugaa taatan?” jedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 72, '“Gariin wanta isin ariifachiifattanii kan isinitti dhihaate ta’uun dhugaadha” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 73, 'Dhugumatti, Rabbiin kee namoota irratti abbaa tola guddaati, Garuu irra hedduun isaanii hin galateeffatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 74, 'Dhugumatti, Rabbiin kee waan qomoonni isaanii dhoksiteefi waan isaan ifatti mul’isan ni beeka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 75, 'Wanti fagoon samiifi dechii keessaa kamiyyuu, kitaaba ifa galaa keessa jiraatu malee hin hintaane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 76, 'Dhugumatti, Qur’aanni kun Ilmaan Israa’iil irratti irra hedduu waan isaan isa keessatti wal dhabanii isaaniif odeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 77, 'Inni mu’uminootaaf qajeelfamaafi rahmata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 78, 'Dhugumatti, Rabbiin kee murtii Isaatiin gidduu isaanitti murteessa. Inni injifataa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 79, 'Allaah irratti hirkadhu. Ati dhugaa ifa ta’e irra jirta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 80, 'Ati namoota du’an hin dhageessiftu. Namoota gurri duudes hin dhageessiftu. yeroo isaan dugda deebisuun garagalan', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 81, 'Namoota jaamaa jallina isaanii irraa kan isaan qajeelchitu hin taane. Namoota Muslimtoota ta’anii keeyyattoota keenyatti amanan malee kan dhageessiftu hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 82, 'Yeroo jechi (adabbiin) isaan irratti murtaa’e bineensa dachii irraa isaaniif baafna tan “namoonni keeyyattoota keenya kan hin dhugoomsine ta’aniiru” jettee isaanitti dubbattu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 83, 'Guyyaa ummata hunda irraa garee warra keeyyattoota keenya sobsiisan irraa ta’an walitti qabnee isaan walitti ittifaman [yaadadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 84, 'Hanga Yeroo isaan dhufan “sila isin odoo beekumsaan ishee hin marsin keeyyattoota kiyya sobsiiftanii? Moo maaluma hojjataa turtan?” jedhaan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 85, 'Waan isaan miidhaa dalaganiif jechi (adabbiin) isaan irratti argameKanaafuu isaan sababa hin dhiheeffatanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 86, 'Sila isaan hinlaallee Akka nuti halkan yeroo isa keessa boqataniifi guyyaa immoo kan keessa arganii (hojjatan) isaaniif goone. Dhugumatti, kana keessa namoota amananiif mallattooleetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 87, 'Guyyaa garrii (xurumbaa) keessa afuufamu wantoonni samii keessa jiranuufi dechii keessa jiran hunduu wantoota Rabbiin fedhe malee yeroo isaan rifatan [wanta ta’u yaadadhu] Hundumtuu salphatoo ta’anii gara Isaa (Rabbii) dhufan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 88, 'Gaarreen kan dhaabbattu ta’uu ishee sehaa argita odoo isheen akka duumessaatti deemtuu. Hojii Rabbii wanta hunda jabeessee [ilaali] Inni waan isin hojjattan keessa beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 89, 'Nama gaariin dhufe (dalage) mindaa ishee caalutu isaaf jira; isaan guyyaa san rifannaa irraa nagaa bahoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 90, 'Namni hamtuun dhufe (dalage) fuulleen isaanii ibidda keessatti gonbifamtee “sila waan dalagaa turtan malee mindeeffamtuu?” [isaaniin jedhama].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 91, 'Kan ani ajajame Gooftaa biyyattii kanaa kan ishee kabaje gabbaruu qofa. Wanti hunduu kan isaati. Muslimoota irraa ta’uuttis ajajameera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 92, 'Qur’aana dubbisuuttis (ajajameera). Namni qajeele, kan inni qajeelu lubbuma isaatiifi. Nama jallate “Ani akeekkachiiftota irraayi malee kan biraa hin taane” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 93, '“Faaruun hundi kan AllaahtiInnis fuulduratti mallattoolee Isaa isinitti agarsiisa. Isinis ishee beekuuf jirtu” jedhiin. Rabbiin kee waan isin dalagdan irraa dagataa miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 1, 'Xaa Siin Miim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 2, 'Tun keeyyattoota kitaaba ifa ba’aati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 3, 'Oduu Muusaafi Fir’awn irraa ummata amananiif dhugaadhaan sirratti dubbifna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 4, 'Fir’awn Dachii keessatti of tuulee jira. warra ishee garee garee taasiseera. Garee isaan irraa ta’e ni hacuuca. Ilmaan isaanii kan dhiiraa ni gorra''a; kan dubaraa immoo ni jiraachisa (nidhiisa). inni balleeysitoota irraa ture.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 5, 'Nuti isaan lafa irratti cunqurfaman (hacuucaman) irratti tola ooluu feena, matootii isaan goonee dhaaltotas isaan taasisuu (feena).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 6, 'Dachii keessas isaaniif mijeessuu [feena]. Fir’awniin, Haamaaniifi waraana isaan lamaanii, isaan irraa waan sodaachaa turan agarsiisuu [feena].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 7, 'Gara haadha Muusaas beeksisa goone (akkana jechuun) “isa hoosisi; yeroo isa irratti sodaatte, galaana keessatti isa darbi. Hin sodaatin; hin gaddinis. Dhugumatti, nuti isa gara keetti deebisoodha. ergamoota irraa isa taasisoodha”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 8, 'Maatiin Fir’awn isa fudhatan akka diinaafi gadda isaanitti ta’uuf. Dhugumatti Fir’awn, Haamaanifi waraanni isaan lamaanii dogongortoota turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 9, 'Jaartiin Fir’awn ni jette: “anaafi siif gammachuu ijaatii isa hin ajjeesinaa; nu fayyaduun yookiin ilma isa taasifachuun keenya ni kajeelama.” Isaanis haala hin beekneen [isheen bulan].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 10, 'Onneen haadha Muusaa duwwaa ta’e. [Ilma ishee ta’uu] isaa ifa gochuutti dhihaattee turte. Akka isheen mu’uminoota irraa taatuuf jecha odoo onnee ishee jabeessuu baannee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 11, 'Obboleettii isaatiinis “isa hordofi” jetteen; isheenis fagoo irraa isa argite. isaan hin beekan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 12, '[Gara haadhaatti deebi’uun] dura hoosiftoota biraa irraa isa dhorginee turre[Obboleettin isaas] “Maatii isa isiniif guddisuufi gaarii isaaf yaadu irratti isin qajeelchuu?” jetteen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 13, 'Gara haadha isaatti isa deebifne Akka Ijji ishee gammadduufi hin yaaddofneef, akkasumas akka waadaan Rabbii dhugaa ta’uu beektuuf jecha. Garuu irra hedduun isaanii hin beekan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 14, 'Yeroma inni jabina isaa ga’ee (umrii dargaggummaa) guutu ogummaafi beekumsa isaaf kennine. Akkuma kanatti toltuu hojjattoota mindeessina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 15, 'Yeroo ummanni ishee daguu keessa jiranitti magaalattii seenee, namoota lama kan wal lolan arge, Kuni (inni tokko) lammii isaa irraa yoo ta’u, inni kun immoo diina isaa irraa ture, Inni lammii isaa irraa ta’e isa diina isaa irraa ta’e irratti tumsa isa gaafate. Muusaan abootteen rukutee isa ajjeese. [Muusaan] ni jedhe: “kun dalagaa Sheyxaanaa irraayyi, Dhugumatti, inni diina jallisaa ifa bahaadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 16, '“Yaa Gooftaa kiyya! Ani lubbuu tiyya miidheeraa Ati naaf araarami” jedhe. Innis isaaf araarame. Dhugumatti, Inni Isumatu araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 17, '“Yaa Gooftaa kiyya! Waan narratti tola oolteen gargaaraa yakkamtootaa hin ta’u” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 18, 'Magaalattii keessatti sodaataa of eeggataa ta’ee bariisifate. Yoma san inni kaleessa gargaarsa isa gaafate isatti lallabnaan Muusaan “dhugumatti ati jallataa ifa bahaadha” isaan jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 19, 'Yeroma inni isa isaan lamaaniifuu diina ta’e qabuu fedhe, inni “Yaa Muusaa! Sila akkuma kaleessa lubbuu ajjeefte anas ajjeesuu feetaa? Ati dachii keessatti abbaa irree ta’uu malee hin feetu; toltuu hojjattoota irraa ta’uu hin feetu” jedheen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 20, 'Gurbaan tokko moggaa magaalattii irraa fiigaa dhufee “Yaa Muusaa! qondaalonni [Fir’awn] si ajjeesuuf sirratti mari’achaa jiru; ani namoota toltuu siif yaadan irraayii [magaalattii irraa] bahi” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 21, 'Sodaataafi of eeggataa ta’ee ishee irraa bahe, “Yaa Rabbii kiyya! Ummata miidhaa hojjattoota ta''an jalaa nagaya na baasi” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 22, 'Yeroma gara Madyan gara galu “gooftaan kiyya karaa sirrii akka na qajeelchun kajeela” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 23, 'Yeroma bishaan Madyan bira ga’u garee namoota irraa ta’e kan [beyladoota isaanii] bishaan obaasan argee, isaan boodas dubartoota lama kan beyladoota isaanii ittisan argee “maali haalli keessan?” (isaaniin) jedhe. Isaanis “Nuti hanga tiksitoonni obaasanii geeffatanitti hin obaafnu, Abbaan keenya jaarsa guddaadha” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 24, 'Isaan lamaaniif obaasee sana booda gara gaaddisaa deebi’ee “yaa Gooftaa kiyya! ni toltuu irraa waan Ati narratti buufte (naaf murteessite)tti haajomaadha” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 25, 'Ergasii tokkoon isaan lamaanii saalfachaa deemuun isatti dhuftee “abbaan kiyya mindaa waan nuuf obaaftee siif kafaluuf si waama” jette. Yeroma inni itti dhufee seenaa isatti himu “hin sodaatin; ummata miidhaa hojjattoota jalaa baatee jirtaa” jedheen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 26, 'Tokkoon Isaan lamaanii “Yaa abbaa kiyya! Isa nuuf ramadi. Dhugumatti, irra caalaan namoota ati ramadduu isa jabaa, amanamaadha” jette', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 27, '[Inni] ni jedhe: “Ani takkaa shamarree too tana lamaanii sitti heerumsiisuun fedha woggaa saddeet na tajaajiluu kee irratti Kudhan yoo guutte [sun tola] si biraa ta’e; sirratti jabeessuu hin fedhu. Yoo Rabbiin fedhe gaggaarii irraa ta’uu na arguuf jirta.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 28, '[Muusaanis] ni jedhe: “kun [walii galtee] gidduu kiyyaafi keetiiti, Beellama lamaan irraa kamiyyuu yoon guute, daangaa narratti dabruun hin jiru. Rabbii waan nuti jennu irratti ragaadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 29, 'Yoroma Muusaan beellama guutee maatii isaatiin deemu, cinaa [gaara] xuuritti ibidda argee, maatii isaatiin “asuma turaa; ani ibiddan argee, ishee biraa oduu wahii yookiin xonbooraa ibidda irraa ta’een akka ho’ifattanuuf isinitti dhufuun koo ni kajeelamaa” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 30, 'Yeroma ishee bira ga’u moggaa lagaa gara mirgaa irraa, dachii barakeeffamtuu keessatti, mukattii irraa “yaa Muusaa! Ani Allaah Rabbii aalama hundaati” jechuun itti lallabame.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 31, '“Ulee kee darbi” [jechuunis itti lallabame]. Yeroma akka waan bofa taateetti kan sochootu taatee ishee argu, of duuba deebi’ee dheesse; uf duuba hin mil’anne“ Yaa Muusaa! As garagali; hin sodaatin, ati warra nagaa bahan irraayi” [jedhameen]', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 32, '“Harka kee bobaa kee keessa seensisi. Fokkina tokko malee adii taatee baati. Sodaa irraa [bilisa ta’uuf] harka kee gara cinaacha keetiitti maxxansi.[] Isheen kun lamaan mallattoo lama kan Rabbii kee irraa gara Fir’awniifi qondaaltota isaatti ergamaniidha. isaan namoota finciltoota tahan.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 33, 'Innis: “Yaa Gooftaa kiyya! ani isaan irraa lubbuu (nama) tokko ajjeeseen jira. Na ajjeesuun sodaadha” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 34, '“Obboleessi kiyya Haaruun, inni arrabni isaa ana caalaatti [haasawa] ifa godha, Kanaafuu gargaaraa na dhugoomsu godhii ana waliin isa ergi, Ani na sobsiisuu isaaniin sodaadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 35, '[Rabbiinis] ni jedhe: “Nuti fuulduratti irree kee obolleessa keetiin jabeessinee isin lamaaniifis aangoo goona. Kanaafuu (hamtuun) gara keessan hin ga’anu. Mallattoolee keenyaan isin lamaaniifi namoonni isin hordofan injifatoodha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 36, 'Yeroma Muusaan mallattoolee keenya ifa taateen isaanitti dhufu “kun sihrii uumame malee waan biraatii miti, Waa’ee kanaa abbootii keenya kan durii keessatti dhageenyee hin beeknu” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 37, 'Muusaanis ni jedhe: “Rabbiin kiyya nama Isa biraa qajeelumaan dhufeefi nama booddeen ganda Aakiraa isaaf taatu beekaadha. miidhaa raawwattoonni hin milkaa’anu.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 38, 'Fir’awna nijedhe “yaa qondaaltota! Ana malee gabbaramaa biraa isiniif hin beeku,Yaa Haamaan! Dhoqqee irratti ibidda naaf bobeessii (xuubii tolchi) gamoo dheeraa naaf godhi; gara Rabbii Muusaa olbahuun koo ni kajeelama. ani sobdoota irraa ta’uun isa yaada” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 39, 'Inniniifi waraanni isaa dachii keessatti haqaan malee boonanii, gara keenyatti deebifamuu dhabuu yaadan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 40, 'Isaafi waraana isaa qabneeti galaana keessatti isaan darbine, Booddeen miidhaa hojjattootaa akkam akka ta’e ilaali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 41, 'Oggantoota gara Ibiddaatti nama waaman isaan taasifne, Guyyaa Qiyaamaa hin tumsamanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 42, 'Addunyaa tana keessatti abaarsa isaan hordofsiifne. Guyyaa Qiyaamaas isaan warra fokkisiifamoo irraayyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 43, 'Erga dhaloota duraanii balleessinee booda dhugumatti Muusaaf kitaaba kenninee jirra, beekumsa, qajeelumaafi rahmata namaaf ta’ee akka isaan ittiin gorfamanuuf.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 44, '[Yaa Muhammad] yeroo Nuti ergaa (keenya) gara Muusaatti dabarsine ati moggaa (tabbaa kan) gara dhihaa irra hin turre; hirmaattota irraas hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 45, 'Haa ta’u malee Nuti [sana booda] dhaloota baay’ee uumnee waggoonni isaan irratti dheerannaan [si ergine]. Ati jiraattota Madyan gidduus jiraataa taatee, keeyyattoota keenya isaan irratti kan dubbiftu hin taane. Haa ta’u malee Nuti [ergaa kanaan si] ergoo taanee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 46, 'Yeroo Nuti [Muusaatti] lallabne ati gaara Xuur maddii hin turre. Haa ta’u malee rahmata Rabbii kee irraa ta’een [si ergine]. ummata siin duratti akeekkachiisaan itti hin dhufin haa gorfamaniif akka akeekkachiiftuuf jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 47, 'Odoo waan harki isaanii dabarsiteef balaan isaan tuqee “yaa Rabbii keenya! maaliif ergamaa gara keenyatti hin ergine keeyyattoota kee hordofnee mu’uminoota irraas akka taanu,” jechuu baatanii [silaa si hin erginu turre].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 48, 'Yeroma dhugaan Nu biraa isaanitti dhufu “Inni maaliif fakkaataan waan Muusaan kennamee isaaf hin kennamne?” jedhan. Sila isaan duraan waan Muusaaf kennametti kafaranii hin turree? “[Tawraatiifi Qur’aanni] Sihrii lama kan wal gargaaraniidha” jedhan. “nuti hundattuu kafaroodha” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 49, '[Yaa Muhammad] “ jedhi mee kitaaba Rabbiin biraa ta’e isaan lamaan irra qajeelaa ta’e qabadhaa kottaa. [Yoo san] anis isa nan hordofaa” yoo dhugaa kan dubbattan taataniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 50, 'Yoo siif hin owwaatin, fedhiilee isaanii qofa hordofuu isaanii beeki, Nama qajeeluma Rabbi irraa ta’een alatti fedhii ofii hordofe caalaa namni jallate eenyu? (tokkoyyuu hin jiru), Rabbiin ummata miidhaa hojjattoota hin qajeelchu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 51, 'Dhugumatti nuti jecha [Qur’aana] isaaniif ifa goonee jirra, akka isaan gorfamanuuf.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 52, 'Warri isa (Qur’aana) dura kitaaba isaaniif kennine, isaan isatti ni amanu', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 53, 'Yeroo inni isaan irratti qara’amu nijedhan “Isatti amanne, inni haqa Rabbii keenya irraa ta’eedha, Nuti isa dura Muslimtoota turre”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 54, 'Isaan sun waan obsanii, hamtuu toltuudhaan deebisanii, waan Nuti isaaniif kennine irraas kennataniif jecha mindaa isaanii yeroo lama kennamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 55, 'Yeroo dhara dhaga’anis, irraa garagalan nijedhan “nuuf dalagaalee keenyatu jira; isiniifis dalagaalee keessantu jira. Nageenyi isin irra haa jiraatu. Nuti wallaaltota hin barbaannu”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 56, 'Ati nama jaallatte hin qajeelchitu, Garuu Allaahtu nama fedhe qajeelcha. Inni warra qajeelan beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 57, '[Isaan] “yoo si waliin karaa qajeelumaa hordofne dachii teenya irraa butamna (guuramna)” jedhan. Sila nuti [iddoo] kabajamaa, nagayaa, soorata Nu biraa ta’eef fuduraaleen wanta hundaa gara isheetti kan guuramu isaaniif hin mijeessinee? Haa ta’u malee irra hedduun isaanii hin beekanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 58, '[Warra] gandaa irraas kan jireenya ishee keessatti boontee ishee balleessine meeqaa meeqa? (hedduudha) Isheen sun gandoota isaanii kan isaaniin booda xiqqoo malee keessa hin jiraataminiidha. Nutis dhaaltota taaneerra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 59, 'Rabbiin kee [warra] magaalotaa hanga irra guddoo ishee keessatti ergamaa keeyyattoota keenya isaan irratti dubbisu ergutti kan balleessu hin taane. Nuti (warra) magaalotaa qubattoonni ishee miidhaa hojjattoota ta’anii malee kan balleessinu hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 60, 'Wantoota irraa kan isiniif kenname hundi mi’a (meeshaa) jireenya addunyaatiifi miidhagina ishee qofa. Wanta Allaah bira jirutu akkaan caalaafi hafaadha, Sila hin xiinxaltanuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 61, 'Sila namni Nuti waadaa gaarii (jannata) waadaa isaaf gallee inni kan isa qunnamu ta’e, akka nama qananii jireenya addunyaa isa qanansiifnee sana booda inni Guyyaa Qiyaamaa warra [jahannam irra] fidamoo irraa ta’uutii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 62, 'Guyyaa [Rabbiin] “Hiriyoonni kiyya kan isin dubbataa turtan sun eessa jiru?” jechuun isaanitti lallabu san [yaadadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 63, 'Warri jechi (adabbiin) isaan irratti mirkanaa’e “Yaa Rabbii keenya! Isaan kun warra nuti jallifneedha, Akkuma ofii jallannetti isaan jallifne, Nuti gara keetti quulqulloofnee, isaan kun nu gabbaraa hin turre” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 64, '“Shariikota keessan waammadhaa” jedhameeni, Isaan ni waammatu; jarris isaaniif hin owwaatanu, adabbii [ibiddaas] ni argan. Odoo qajeeluun isaanii argameera ta’ee [adabbii hin argan turan].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 65, 'Guyyaa [Rabbiin] isaanitti lallabee “Ergamtootaaf maal deebiftan?” jedhu [yaadadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 66, 'Guyyaa san oduuleen isaan jalaa dhokatti, Isaan walis hin gaafatanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 67, 'Namni tawbatee, [Rabbitti] amanee, gaarii hojjate milkaa’ota irraa ta’uun isaa mirkanaa’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 68, 'Rabbiin kee waan fedhe uuma; ni filatas, Isaaniif garuu filannoon hin jiru. Allaahn waan isaan itti dabalan irraa qulqullaa’ee ol ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 69, 'Rabbiin kee waan qomoowwan isaanii dhoksituufi waan isaan mul’isanis ni beeka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 70, 'Inni Allaahdha, Isa malee dhugaan gabbaramaan hin jiru. Faaruun hundi duraafii (addunyaafi) booda (Aakhiraa) keessatti kan Isaati. Murtiinis kan Isaati, Garuma Isaa qofa deebifamtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 71, '“Mee naaf odeessaa! Yoo Rabbiin halkan walitti aansee hanga Guyyaa Qiyaamaatti isinirra turaa taasise, sila Rabbiin malee gabbaramaan ifaan isiniif dhufu eenyu? Sila isin hin dhageessanuu?” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 72, 'Ammas “mee naaf odeessaa! yoo Rabbiin guyyaa walitti aansee hanga Guyyaa Qiyaamatti isinirra turaa taasise, sila Rabbiin malee gabbaramaan halkan isa keessa boqottan isiniif fidu eenyu? Sila isin hin argitanuu?” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 73, 'Rahmata Isaa irraayyi halkaniifi guyyaa akka isa (halkan) keessa boqottanii [guyyaa] tola Isaa irraa barbaaddattanii fi, akka Isa galatoomfattaniif isinii taasise.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 74, 'Guyyaa [Rabbiin] “hiriyoonni kiyya kan isin dubbataa turtan sun eessa jiru?” jechuun isaanitti lallabu san [yaadadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 75, 'Ummata hunda irraa ragaa fuuneeti “ragaa keessan fidaa” jennaan. Yeroo san dhugaan kan Rabbii qofa ta’uu beeku. Wanti isaan (kijibaan) uummatanis isaan irraa bada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 76, 'Qaaruun ummata Muusaa irraa tahe, Isaan irrattis daangaa dabre, Kuusaa qabeenyaa irraas waan furtuuleen isaa garee jajjaboo ta’anitti ulfaattu isaaf kennine. Yeroo ummanni isaa “[qabeenyaan] hin boonin; Allaahn warra boonan hin jaalatu” isaan jedhan san [yaadadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 77, '“Waan Rabbiin siif kenne keessatti mana Aakhiraa ittiin barbaadi. Addunyaa irraas qooda kee hin dagatin. Akkuma Allaahn tola gara keetti oole atis tola ooli. Dachii keessatti badii [facaasuu] hin barbaadin. Allaahn balleessitoota hin jaalatu.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 78, '[Qaaruun] “wanti an isa kennameef beekumsa na bira jiruuf jecha” jedhe. isa dura Rabbiin balleessee hin beeknee? Dhaloota baay’ee irraa nama inni humnaanis isa (Qaaruun) irra cimaa ta’e, kan qabeenya kuufachuuttiis isa irra baay’ee ta’e. Yakka hojjattoonni badii isaanii irraa hin gaafatamanu.[1]', '[1] hiikkaan hingaafataman jechuu balleessaan isaanii goddoo mul''attuu waan taateef osomaa hingaafatamne gara ibidda jahannam oofaman jechuudha. qataadaa akkasitti fassare. maddi tafsiira ibnujariir axxabarii.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 79, 'Faaya isaa keessatti (uffatee) ummata isaa irratti bahe. Isaan jireenya addunyaa fedhan “fakkaataan waan Qaaruuniif kennamee nuuf ta’uu hawwina; inni abbaa qooda guddaati” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 80, 'Isaan beekumsa kennaman ni jedhan: “yaa badii keessan! Nama amanee, gaarii hojjateef mindaa Rabbiitu irra caala. Kanas obsitoota malee eenyunuu hin kennamu.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 81, 'Isaafi ganda isaatis ni dhidhimsiifne (dachii ittiin kunne) Gareen Rabbiin alaa kan isa tumsan isaaf hin taane. Inni warra of baraarsan irraa hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 82, 'Isaan kaleessa iddoo isaa hawwan “edaa Rabbiin dhugumatti gabroota Isaa irraa nama fedheef soorata bal’isee [nama fedhetti] immoo dhiphisa! Odoo Rabbiin ni’imaa Isaa nurratti ooluu baatee, silaa nuun kuta (dhidhimsiisa) ture. Edaa dhugumatti kaafiroonni hin milkaa’anu!” jedhaa bulan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 83, 'Ganda Aakhiraa san warra dachii keessatti ol aantummaafi badii [raawwachuu] hin feeneef ishee goona, Booddeen (gaariin) warra Rabbiin sodaataniifi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 84, 'Namni gaarii dalage waan san irra caalutu isaaf jira. Namni hamtuun dhufe, [fakkii ishee argata], Warri hojii gadhee hojjatan waan hojjataa turan malee hin mindeeffamanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 85, 'Dhugumatti, Inni Qur’aana si irratti buuse, gara iddoo deebiitti (Makkaatti) si deebisa. “Rabbiin kiyya nama qajeelumaan dhufeefi nama jallina ifa bahaa ta’e keessa jiru beekaadha” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 86, 'Rahmata Rabbii kee irraa ta’een [sirratti buufne malee] ati kitaabni gara keetti buufamuu kajeelaa hin turre. Kaafirootaaf gargaaraa hin tahin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 87, 'Erga isheen gara keetti buufamtee booda keeyyattoota Rabbii irraa isaan si hin deebisin. Gara Rabbii keetiitti waami. Mushrikoota irraa hin ta’in.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 88, 'Rabbii wajjiin gabbaramaa biraa hin kadhatin (hin gabbarin). Dhugaan gabbaramaan Isa malee hin jiru. Fuula (zaata) isaa malee wanti hundi dhabamaadha. Murtiinis kan Isaati, Garuma Isaatti deebifamtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 1, 'Alif Laam Miim', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 2, 'Sila namoonni “amanne” jechuudhaan odoo hin mokkoramin dhiifamuu yaaduu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 3, 'Dhugumatti, Nuti warra isaaniin duraas mokkorree jirra. Dhugumatti, Rabbiin isaan dhugaan [amanne] jedhan beekuuf jira, sobdootas beekuuf jira. .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 4, 'Sila isaan diliilee dalagan Nu jalaa bahuu yaaduu? Wanti isaan murteessan waa fokkate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 5, 'Namni qunnamtii Allaah kajeele (haa qophaawuu), dhugumatti beellamni Rabbii dhufaadha. Inni dhagayaa, beekaadhas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 6, 'Namni qabsaa’e kan inni qabsaa’u lubbuma isaatiifi. Rabbiin Dhugumatti, aalama hunda irraa dureessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 7, 'Isaan amananii gaggaarii hojjatan badiilee isaanii isaan irraa haqna. Dhugumatti, gaarii waan isaan dalagaa turanii isaan mindeessina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 8, 'Namaaf haadhaafi abbaa isaatti tola ooluu dhaamne. Yoo waan ati beekumsa isaa hin qabne akka Natti qindeessituuf sirratti qabsaayan, isaan lamaan tole hinjedhin, Deebiin keessan garuma kiyya. Waan hojjachaa turtan isinittin odeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 9, 'Isaan amananii gaggaarii hojjatan, namoota gaggaarii keessa isaan seensifna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 10, 'Namoota irraa nama “Rabbitti amanneerra” jedhaa yeroo karaa Rabbii keessatti rakkifame, rakkina namni isa irratti raawwatu akka adabbii Rabbii taasisutu jira. Yoo injifannoon Rabbii kee irraa dhufes dhugumatti “nuti isinii wajjin turre” jedhu. Sila Allaahn waan qomaalee aalamaa keessa jiru akkaan beekaa hin taanee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 11, 'Dugumatti Allaahn warra amanan ni beeka. Munaafiqootas ni beeka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 12, 'Isaan kafaran warra amananiin “karaa keenya hordofaa; nuti cubbuulee keessan isin irraa baadhannaa” jedhan, Isaan badiilee isaanii irraa homaa hin baadhatanu. Dhugumatti, isaan kijibdoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 13, 'Dhugumatti, isaan ba’aa isaaniitiifi ba’aa biraas kan isaanii wajjin ni baadhatu. Dhugumatti, isaan waan soba uuman irraa Guyyaa Qiyaamaa ni gaafatamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 14, 'Dhugumatti, nabi Nuuhiin gara ummata isaatti ergineerra. [Inni] waggaa kuma tokkoo waggaa shantam ir''uu isaan keessa ture.Odoo isaan miidhaa hojjattoota ta’anii jiranii bishaaniin dhidhimfamuun isaan qabe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 15, 'Isaafi warra doonii (keessa turan) ni baraarsine; aalama hundaaf mallattoo ishee goone.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 16, 'Ibraahiimiin yeroo inni ummata isaatiin “Allaah gabbaraa. Isa sodaadhaa. Yoo kan beektan taataniif santu irra isiniif caala” jedhe [yaadadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 17, '“Wanti isin Rabbii gaditti gabbartan taabotuma qofa; cubbuus ni uumtu. isaan isin Rabbiin alatti gabbartan soorata isiniif kennuutti dandeettii hin qabanu. Soorata Rabbuma biraa barbaadaa. Isa gabbaraas. Galatas Isaaf galchaa. Garuma Isaa deebifamtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 18, 'Yoo sobsiiftan, dhugumatti ummanni isin duraas sobsiisanii jiru. Ergamaa irra geessuu ifa ta’e malee homaa hin jiru', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 19, 'Sila isaan akka Rabbiin uumuu eegalee ergasii isa deebisu hin ilaalanuu? Sun Allaah irratti laafaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 20, '[Yaa Muhammad!] “dachii keessa deemaatii akkaataa Rabbiin uumuu itti jalqabe ilaalaa! Sana booda Allaahn kaasiinsa boodaa ni kaasa. Dhugumatti, Rabbiin waan hunda irratti danda’aadha” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 21, 'Nama fedhe ni adaba; nama fedhes rahmata isaaf godha. Gara Isaa qofatti deebifamtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 22, 'Isin dachiifi samii keessatti kan dadhabsiiftan hin taane. Rabbiin ala jaalalleefi tumsaan isiniif hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 23, 'Isaan keeyyattoota Rabbiitiifi qunnamtii Isaatti kafaran, isaan sun rahmata kiyya irraa abdii kutatanii jiru. Isaan sun adabbii laaleessaa ta’etu isaaniif jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 24, 'Deebiin ummata isaas “Isa ajjeesaa yookiin isa gubaa” jechuu malee waan biraa hin taane. Allaahn Ibidda jalaa isa baraarsee jira. kana keessa namoota amananiif mallattooleetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 25, '[Ibraahiim] “Isin Rabbii gaditti taabota wanti godhattaniif jaalala jidduu keessanii kan jiruu duniyaa qofaafi. Sana booda Guyyaa Qiyaamaa gariin keessan garitti kafara. Gariin keessan garii abaaras. Manni keessan ibidda; tumsitoonni homaatuu isiniif hin jiru” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 26, 'Luuxis isaaf (Ibraahiimiif) ni amane. (Ibraahiimis) “ani gara Rabbii kiyyaa godaanaadha. Inni injifataa, ogeessa” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 27, 'Is-haaqiifi Ya’iquubiinis isaaf kennine. Sanyii isaa keessa nabiyyummaafi Kitaaba ni taasifne. Mindaa isaa addunyaa keessattis isaaf kennine. inni Aakhiratti gaggaarota irraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 28, 'Luuxiinis yeroo inni ummata isaatiin “isin gocha fokkataa kan aalama hunda irraa ummanni tokkollee isin dura hin hojjatin raawwattu” jedheen (erginee jirra).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 29, '“Sila isin (qunnamtii saalatiif) dhiiroowwanitti dhuftuu?! (Saamichaanis) karaa kuttuu? Iddoo Yaa’ii keessanii keessattis gochoota jibbamoo ta’an raawwattuu? Deebiin ummata isaa “yoo warra dhugaa dubbatan irraa taateef, adabbii Rabbiitiin nutti kottu” jechuu malee homaa hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 30, '(Luuxis) “Gooftaa kiyya! Ummata balleessitoota (kanneen) irratti na tumsi” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 31, 'Yeroma ergamtoonni keenya oduu gammachiisaan Ibraahiimitti dhufan “nuti dhugumatti, jiraattota magaalaa tanaa balleessoodha. waan warri ishee miidhaa hojjattoota ta’aniif” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 32, '(Ibraahiimis) “Luux ishee keessa jira” jedhe. (Maleykonnis) “nuti nama ishee keessa jiru akkaan beekna; dhugumatti, isaafi maatii isaa ni baraarsina haadha manaa isaa tan warra hafan keessatti taatu malee ” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 33, 'Yeroma ergamtoonni keenya Luuxitti dhufan isaaniif yaadda’ee qomti isaas isaaniif dhiphatte. Isaanis “hin sodaatin; hin yaadda’inis. nuti siifi maatii kee nagaa baasoodha. niitiin tee malee isheen warra (adaba keessatti) hafan irraa taate” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 34, '“Nuti jiraattota magaalaa tanaa irratti samii irraa adabbii cimaa buusoodha waan isaan finciltoota ta’aniif” jedhan', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 35, 'Dhugumatti, Nuti ishee irraa namoota sammuu qabaniif mallattoo ifa taate hanbifnee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 36, 'Gara (ummata) Madyanis obboleessa isaanii Shu’aybiin (erginee jirra) Innis “Yaa ummata kiyya! Allaah qofa gabbaraa. Guyyaa Aakhiraas kajelaa. Balleessitoota taataniis badii dachii keessa hin tamsaasinaa” jedheen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 37, 'Isa kijibsiisan. Kirkirri (sochiin) lafaas isaan qabatte, Yoosuu ganda isaanii keessatti jilbeenfatanii dhumanii bulan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 38, 'Aadiifi Samuudiinis ni balleessine; (Isaan balleessuun keenyas) gandoota isaanii irraa ifa isiniif ta’ee jira. shayxaanni hojiilee isaanii isaaniif miidhagsee, karaa haqaa irraa isaan deebse, Odoo kan argan ta’anii jiranuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 39, 'Qaaruuniin, Fir’awniifi Haamaaniinis (balleessineerra). Dhugumatti, Muusaan ragaa ifa ta’een isaanitti dhufeeti, dachii keessatti boonan. (isaan qabne) Kan Nu jalaa miliqan hin taane', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 40, 'Hundumaa badii isaatiif isa qabne. Isaan irraa namoota bubbee cirrachaa irratti erginetu jira. Isaan irraas namoota iyyansi isaan qabetu jira. Isaan irraas namoota dachii ittiin kunnetu jira. Isaan irraas namoota bishaan nyaachifnetu jira. Rabbiin kan isaan miidhu hin taane. Garuu isaan lubbuulee isaanii kan miidhan ta’aniiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 41, 'Fakkeenyi isaan Rabbii gaditti jaalalleewwan godhatanii (gabbaranii) akka birbirooftuu (saaphaphuu) mana ijaarratteeti. Dhugumatti irra laafaan manaa mana birbirooftuuti odoo kan beekan ta’anii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 42, 'Rabbiin waan hunda irraa waan isaan Isaa gaditti kadhatan ni beeka. Inni injifataa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 43, 'Fakkeenyota san namootaaf ishee ni goona; beektota malees ishee hin hubatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 44, 'Rabbiin samiifi dachii dhugaan uume. sana keessa mu’uminootaaf mallattootu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 45, '(Yaa Muhammad!) kitaaba irraa waan gara kee buufame dubbisi. Salaatas haqa isaa guutii sagadi. salaanni wantoota fokkatoofi jibbamoo ta’an irraa dhorgiti. Zikrii (faaruu) Rabbiitu (waan hunda irra) guddaadha. Rabbiin waan isin hojjattan ni beeka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 46, 'Warra kitaabaatiin falmii gaariin malee hin falminaa; isaan irraa warri miidhaa dalagan malee. Nuti “isa gara keenyatti bufameefi gara keessanittis buufametti amanneerra. Gabbaramaan keenyaafi gabbaramaan keessanis tokko. Nuti isaaf ajajamoodha” jedhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 47, 'Akkuma kana (warra si duraa irratti buufne) kitaaba gara keetti buufne. Isaan kitaaba kennineef isatti ni amanu. Isaan kana irraas (warra makkaa irraas) namoota isatti amanutu jira. Kaafiroota malee keeyyattoota keenya namni mormu hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 48, 'Ati (yaa Muhammad!) Isa dura kitaaba tokkollee kan dubbiftuufi mirga keetiinis barreessitu hin turre. Odoo akkas taatee balleessitoonni ni shakku turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 49, 'Garuu inni keeyyattoota ifa ta’an kan qomoota warra beekumsa kennamee keessa jiruudha. Miidhaa hojjattoota malee keeyyattoota keenya namni mormu hin jiru', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 50, 'Isaanis ni jedhan: “Maaliif raajiiwwan Gooftaa Isaa biraa isa irratti hin buufamin? (Atis) “raajiwwan kan jiran Allaah bira qofa. Ani immoo akeekkachiisaa ifa ta’e qofa” jedhiin', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 51, 'Sila kitaaba (Qur’aana) isaan irratti qara’amu si irratti buusuun keenya qofti isaaniif hin ga’uu? kana keessa namoota amananiif rahmataafi yaadannootu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 52, 'Jedhi: “jidduu kiyyaafi keessanitti ragaa ta’uuf Rabbiin gahaadha. Waan samiileefii dachii keessa jiru hundaa ni beeka. Isaan sobatti amananiifi Rabbitti kafaran, warri sun isaanumatu hoonga’oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 53, 'Adabatti si ariifachiisu, Odoo beellamni beekamaan jiraachuu baatee silaa adabbiin (addunyaattis) isaanitti dhufa ture. Dhugumatti akka tasaa odoo isaan hin beekin isaanitti dhufa', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 54, 'Adabbiitti si ariifachiisu. jahannam dhugumatti kaafirootatti marsituudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 55, 'Guyyaa adabbiin (Ibiddi) gubbaa isaanii irraafi miiloowwan isaanii jalaan isaan haguugu, (Maleykan ibiddaa) “Waan dalagaa turtan dhandhamaa” jedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 56, '“Yaa gabroota kiyya warra amantan! Dachiin tiyya bal’oodhaa, Anuma qofa gabbaraa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 57, 'Lubbuun hunduu du’a dhandhamtuudha. eegasii gara keenyatti deebifamtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 58, 'Isaan amananii gaggaarii hojjatan, dhugumatti jannata irraa manneen laggeen ishee jala yaatu, kan yeroo hunda ishee keessa jiraatan ta’anii isaan qubsiifna. Mindaan hojjattootaa waa tole!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 59, '[Isaan] warra obsaniifi Gooftaa isaanii irratti hirkataniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 60, 'beeyladaa irraa kan soorata isaanii hin baadhanne kan Rabbiin isiniifi isaanis sooru hedduudha inni dhagayaa beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 61, 'Dhugumatti “eenyutu samiifi dachii uumee, aduufi baatiis laaffise?” jettee yoo isaan gaafatte “Allaahdha” siin jedhu. Akkamitti (tawhiida irraa) garagalfamu ree?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 62, 'Rabbiin gabroota Isaa irraa nama fedheef hiree ni bal’isa. (Nama fedhe immoo) isatti dhiphisa. Dhugumatti, Rabbiin waan hunda beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 63, 'Dhugumatti, yoo “eenyutu samii irraa bishaan buusee, dachii erga isheen duutee booda ittiin jiraachise?” jettee isaan gaafatte “Allaahdha” jedhu. (Yaa Muhammad!) “Faaruun hunduu kan Allaahti” jedhi. Garuu irra hedduun isaanii hin hubatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 64, 'Jireenyi addunyaa kun qoosaafi tapha malee waan biraa hin taane. Dhugumatti, manni Aakhiraa odoo beekanii isheetu jireenya dhugaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 65, 'Yeroo doonii yaabbatan, amantii Isaaf qulqulleessuun Allaah qofa kadhatu. Yeroo Inni gara dachiitti nagaan isaan baase immoo yeroma san (Rabbitti) qindeessu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 66, 'Waan nuti isaaniif kenninetti kafaruufi qanani’anuuf (Rabbitti qindeessu). Garuu (waan booddeen isaanii ta’u) fuula duratti ni beeku.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 67, 'Sila isaan namoonni moggaa isaaniitii (ajjeechaafi saamichaan) kan bubbutaman osoo ta’anuu akka nuti (Makkaa) iddoo kabajamaa, tasgabbaayaa taasifne hin ilaalanuu? Sila sobatti amananii ni’imaa Rabbiitti kafaruu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 68, 'Nama Rabbirratti soba uumee odeesse yookiin dhugaan itti dhufnaan sobsiise caalaa namni miidhaa hojjate eenyu? (tokkolleen hin jiru). Sila teessoon kaafirootaa jahannam keessa hin taanee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 69, 'Warra Nu (karaa keenya) keessatti qabsaa’an karaa keenya isaan qajeelchina. Dhugumatti, Rabbiin toltuu hojjattoota waliin jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 1, 'Alif Laam Miim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 2, 'Roomaan injifatamte', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 3, 'Irra dhihoo dachii keessatti (injifataman). Isaanis mo’atamuu isaanii booda fuulduratti ni mo’atu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 4, 'Waggoota muraasa keessatti (moo’atu). ajajni duraas ta’ee boodaa kan Rabbiiti. Guyyaa san mu’uminoonni ni gammadu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 5, 'Tumsa Allaahtiin (gammadu). (Rabbiin) nama fedhee ni tumsa. Inni injifataa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 6, 'Waadaa Rabbii (Rabbiin beellame), Rabbiin waadaa isaa hin diigu. Garuu irra hedduun namootaa hin beekanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 7, 'Isaan jireenya addunyaa irraa gubbuma beeku. Isaan Aakhiraa irraa immoo dagatoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 8, 'Sila lubbuulema isaanii keessatti hinxiinxallanii? Rabbiin samiileefi dachii, akkasumas wantoota isaan lamaan gidduu jiranu, haqaafi beellama beekamaadhaan malee hin uumne (jechuu hin xiinxallanii?) irra hedduun namootaa qunnamtii Gooftaa isaaniitti kafaroodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 9, 'Sila dachii keessa deemanii booddeen warra isaaniin duraa akkam akka ta’e hin ilaallee? Humnaan isaan irra cimoo turan. Dachiis qotanii waan isaan (warri Makkaa) misoomsan irra hedduu misoomsaniiru. Ergamtoonni isaaniis ragaawwan ifa ta’aniin isaanitti dhufan. Rabbiin kan isaan miidhu hin taane. Garuu isaan lubbuulee isaanii kan miidhan ta’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 10, 'Eegasii booddeen isaan hamtuu dalaganii,(adabbii) hamaa ta’e, sababa waan isaan keeyyattoota Rabbii sobsiisaniifi isheettis kan qishnaa godhan ta’aniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 11, 'Rabbiin uuminsa ni jalqaba, Eegasii isa ni deebisa. Sana booda gara Isaa deebifamtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 12, 'Guyyaa Qiyaamaan dhaabbattu, badii raawwattoonni abdii kutatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 13, 'Warra isaan Rabbitti dabalan irraa araarsitoonni isaaniif hin argamu. Isaan qindeeffamtoota isaaniitti kafaroota (mormitoota) tahan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 14, 'Guyyaa Qiyaamaan dhaabbattu, guyyaa san (mu’uminootaafi kaafiroonni) addaan babahu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 15, 'Ammoo isaan amananii gaggaarii hojjatan, isaan caffee (jannata) keessatti gammachiifamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 16, 'Ammoo Warri kafaranii keeyyattoota keenyaafi qunnamtii Aakhiraa sobsiisan, isaan sun azaaba keessa fidamoodha', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 17, 'Yeroo dhiisifattaniifi yeroo bariisifattanis, qulqullina isaan malu Allaah (qulqulleessaa).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 18, 'Samiileefi dachii keessattis faaruun hundi kan Isaati; waaree boodaafi yeroo waareetti seentanis (isa faarsaa).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 19, '(Inni) jiraa du’aa irraa baasa; du’aas jiraa irraa baasa. Dachiis erga du''uu ishee booda jiraachisa. Akkuma kanatti (qabrirraa) baafamtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 20, 'mallattoolee isaa (Rabbii) irraayyi biyyee irraa isin (abbaa keessan) uumuun. san booda isin yeroma san namoota dachii keessa faffaca’u taatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 21, 'Mallattoolee Isaa irraayyi lubbuulee teessan irraa jaartiilee teessan isinii uumuun, akka gara isheetti boqottaniif jecha, gidduu keessanitti jaalalaafi mararfannaa godhe. kana keessa mallattooleetu jira. namoota xiinxalaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 22, 'Mallattoolee Isaa irraayyi Samiileefii dachii uumuun, arrabni (lugaaleen) keessaniifi bifooleen keessan waldhabuunis. kana keessa aalama hundaaf mallattooleetu jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 23, 'Mallattoolee (dandeettii) Isaa irraayyi, Hirribni keessan kan halkaniifi guyyaa, tola isaa irraa barbaaddachuun keessanis. kana keessa namoota dhagahaniif mallattooleetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 24, 'Mallattoolee isaarraa hangaasuu isin garsiisa Akka (bakakkaa) sodaattaniifi (roobas) kajeeltaniif, bishaan samii irraa buusuufi booda isheen duutee dachii ittiin jiraachisuun. kana keessa namoota aqlii (sammuu) qabaniif mallattooleetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 25, 'Mallattoolee isaarraa Samiifi dachiin ajaja Isaatiin dhaabbachuu, sana booda yeroo Inni dachii irraa waamicha tokko isin waame, yeroma san isin (awwaala keessaa) baatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 26, 'Wanti samiileefi dachii keessa jiru hundi kan Isaati. Hunduu Isaaf ajajamoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 27, 'Inni (Rabbiin) Isa uumiinsa jalqabu; sana booda kan isa deebisuudha. Inni isa irratti akkaan laafaadha. Dachiifi samiilee keessa sifaata ol aanaatu Isaaf jira. Inni injifataa ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 28, '(Rabbiin) lubbuulee keessan irraa fakkeenya isiniif taasise. Sila waan harki mirgaa keessan horatte (Gabroota keessan) irraa soorata isiniif kennine keessatti shariikni isin isa (sooraticha) keessatti walqixa taatanii akka lubbuulee keessan (nama gita keessanii) sodaattanitti isa sodaattan, isiniif ni jiraa? Akka kanatti namoota aqlii qabaniif keeyyattoota adda babaasna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 29, 'Garuu isaan miidhaa hojjatan beekumsaan ala fedhaalee lubbuu isaanii hordofan. Nama Rabbiin jallise eenyutu isa qajeelcha? tumsitootarraa homaa isaaniif hintaane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 30, 'fuula kee diiniif sirreessi Karaa haqaatti dabuun, Uumaa Rabbii ishee inni irratti nama uumes (qabadhaa). Uumaa Rabbiit jijjiiruun hin taane. Santu amantii qajeelaadha. Garuu irra hedduun namootaa hin beekanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 31, 'Gara Isaatti deebi’oo ta’uun (diinii Isaa qabadhaa); Isa sodaadhaa. Salaatas (haqaan) sagadaa. Mushrikoota irraa hin ta’inaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 32, 'Isaan amantii isaanii gargar qoqqoodaniifi garee garee ta’an irraas (hin ta’inaa). Gareen hunduu waan isaan bira jirutti gammadu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 33, 'Namoonni yeroo rakkoon isaan tuqu gara Isaatti tawbaa deebi’uun Gooftaa isaanii kadhatu. Sana booda yeroo inni rahmata Isa biraa ta’e isaan dhandhamsiise, yeroma san gareen isaan irraa ta’e Rabbii isaaniitti (wanta biraa) qindeessu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 34, 'Waan isaaniif kenninetti kafaruuf (kana godhu). (addunyaa irratti) qanani’aa (Dhugaa) fuuladuratti ni beektuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 35, 'Moo nuti ragaa isaanirratti nibuufnee? kan inni waan isaan (Rabbitti) qindeessaa turan dubbatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 36, 'Yeroo namoota rahmata dhandhamsiifne isheetti gammadu. yeroo sababa waan harki isaanii dabarsitee (hojjattee) tiin hamtuun wahii isaan tuqxe immoo yeroma san abdii muratu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 37, 'Sila akka Rabbiin nama fedheef soorata bal’isuufi (nama fedhetti immoo) dhiphisu hin beekanuu? kana keessa namoota amananiif mallattooleetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 38, 'Nama firaa, hiyyeessaafi kara deemaafis haqa isaa kenni. Isaan fuula Rabbii barbaadaniif (kajeelaniif) kanatu caala. Isaan sun isaanumatu milkaa’oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 39, 'Wanti dhala irraa qabeenyaalee namaa keessatti haa dhaluuf isin kennitan Rabbiin biratti hin dhalu. Garuu zakaa irraa wanti isin fuula Rabbii feetanii kennitan, (isatu isiniif dhala) Jarri sun (kennattoonni) isaantu (mindaa) dachaa argamsiisoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 40, 'Allaahn Isa isin uume San booda kan soorata isiniif kenne, Sana booda isin ajjeesa, Sana booda isin jiraachisa, Sila warra isin Rabbitti qindeessitan irraa kan wantoota kanneen irraa waan tokko dalagan ni jiruu? (Rabbiin) wantoota isaan isatti qindeessan hunda irraa qulqullaa’ee ol ta’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 41, 'sababa waan harki namaa hojjatteetiin dachiifi galaana keessattis badiin mul’ate,Garii waan isaan dalaganii akka isaan dhandhamsiisnuuf jecha, Deebi’uun isaaniis ni kajeelama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 42, '(Yaa Muhammad!) jedhi “dachii keessa deemaa; booddeen warra isiniin duraa akkam akka ta’e ilaalaa; irra hedduun isaanii mushrikoota turan”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 43, 'fuula kee amantii sirrii ta’eef sirreessi,Guyyaan Rabbirraa deebi’uun isaaf hin jirre odoo hin dhufne duratti. Guyyaa san (gara jannataafi ibiddaatti) qoodamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 44, 'Nama kafare kufriin isaa isuma irratti ta’a. Namni dalagaa gaarii hojjate, lubbuma isaaniitiif qopheeffatu', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 45, 'Isaan amananii hojiiwwan gaggaarii dalagan tola Isaa irraa akka galata galchuuf (kana hojjate). Inni kaafiroota hin jaallatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 46, 'Mallattoolee Isaa irraayyi. qilleensa erguun Isaati gammachiiftuu taasisee. Rahmata Isaa irraa isin dhandhamsiisuf, dooniinis ajaja Isaatiin akka deemtuuf, tola Isaa irraas akka barbaaddattaniifi akka Isa galateeffattaniif,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 47, 'Dhugumatti, si duras ergamtoota gara ummatoota isaaniitti erginee jirra. Isaanis ragaalee ifa ta’aniin isaanitti dhufanii jiru. Isaan daangaa dabran irraas haaloo bahanne. Mu’uminoota gargaaruun immoo haqa Nurratti ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 48, 'Rabbiin Isa qilleensa erge, isiin duumessa sochoofte. akka fedhetti samii keessa isa bittinneessa; addaan kukkutamaas isa taasisa. Roobas kan gidduu isaatii bahu argita. Yeroo ittiin (rooba sanaan) gabroota Isaa irraa nama fedhe tuqe, yeroma san isaan ni gammadu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 49, 'Odoo (roobni) isaan irratti hin bu’in dura immoo, sana dura dhugumatti abdii murattoota turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 50, 'Gara faana rahmata Rabbii ilaali, akkamitti akka (inni) dachii erga isheen duutee booda jiraachisu. Dhugumatti [Rabbiin] Sun du’aawwan ni jiraachisa. Inni waan hunda irratti danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 51, 'Dhugumatti, odoo bubbee (oyruu isaaniitti) erginee daalacha ta’ee isa arganii, silaa booda isaatii (tola kiyyatti) kan kafaran ta’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 52, '(Yaa Muhammad!) ati du’aa hin dhageessiftu. Nama duudaawwanis waamicha hindhageessiftu, yeroo isaan of duuba deebi’anii garagalan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 53, '(Yaa Muhammad!) ati jaamaawwan jallina isaa irraa kan isaan qajeelchitu hin taane. (Ati) namoota Rabbiif ajajamoo ta’anii keeyyattoota keenyatti amanan malee (warra biraa) hin dhageessiftu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 54, 'Rabbiin isa (bishaan) laafaa irraa isin uumee, eegasii laafina boodaan humna taasisee; eegasii humna boodaan laafinaafi arrii taasiseedha. Waan barbaades ni uuma. Inni beekaa danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 55, 'Guyyaa Qiyaamaan dhaabbattu, yakkamtoonni sa’aatii tokko malee (addunyaa irra) hin turre (jedhanii) kakatu. Akkuma kanatti (haqa irraa) kan gara galfaman turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 56, 'Isaan beekumsaafi iimaana kennaman nijedhan “dhugumatti, isin akkuma kitaaba Rabbii keessatti (murtaa’etti,) hanga guyyaa kaafamaatti turtaniittu. Kuni guyyaa kaafamaati. Garuu isin (dhufuu isaa) hin beektanu turtan.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 57, 'Guyyaa san warra miidhaa hojjatan rakkoo himachuun isaanii (isaan) hin fayyadu. Isaan ceephoos hin buufachiifamanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 58, 'Dhugumatti, Nuti Qur’aana kana keessatti namootaaf fakkeenya hundarraa goonee jirra. Garuu (Yaa Muhammad!) yoo ati mallattoo wahiitiin isaan itti dhufte warri kafaran “isin kijibdoota malee waan biraa hin taane” jedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 59, 'Akka kanatti Allaahn onneewwan warra haqa hin beeknee irratti cufaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 60, '(Yaa Muhammad!) Obsi Dhugumatti, waadaan Rabbii dhugaadha. Isaan (Qiyaamaa) hin dhugoomsine akka si hin xiqqeessine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 1, 'Alif Laam Miim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 2, 'Tun keeyyattoota kitaaba ogummaan guutameeti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 3, 'Isaan toltuu hojjataniif qajeelumaafi rahmata haala ta’een (buufame).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 4, 'Isaan warra salaata (haqaan) sagadaniifi zakaas kennataniidha. Isaan isaanumatu Aakhiraa dhugoomsa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 5, 'Isaan sun qajeeluma Gooftaa isaanii irraa ta’e irra jiru. Isaan sun isaanumatu milkaa’oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 6, 'Namoota irraa nama haasawa taphaa bituutu jira. beekumsaan ala karaa Rabbii irraa ittiin (nama) jallisuuf, meeshaa taphaa taasifachuuf. Isaan sana adabbii xiqqeessaatu isaaniif jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 7, 'Yeroo keeyyattoonni keenya isa irratti dubbifamte, boonaa ta’ee irraa garagala akka waan hin dhaga’iniitti, akka waan gurra isaa lamaan keessa duudummaan jiruu, Adabbii laalessaan isa gammachiisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 8, 'Isaan amananii gaggaarii hojjatan jannatoota qananiitu isaaniif jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 9, 'Ishee keessa zalaalam jiraatoo tahanii (ishee seenu). Rabbiin waadaa dhugaa isaaniif gale. Inni injifataa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 10, 'Samii utubaalee malee uumne; (isin) ishee ni agartu. Gaarreen (gadi dhaabdota) dachii keessa kaaye, akka (dachiin) isiniin hin sochooneef. Lubbu qabeeyyii hunda irraas ishee keessatti facaase. Bishaan Samii irraa buufnee, gosoota gaggaarii hundarraa ishee keessatti magarsine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 11, 'Kun uumaa Rabbiiti. Mee waan isaan Isaa gadii uuman na agarsiisaa. Dhugumatti miidhaa hojjattoonni jal’ina ifa galaa keessa jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 12, 'Dhugumatti Luqmaaniif ogummaa kenninee jirra.“Rabbiif galata galchi. Namni (Rabbiin) galateeffate kan inni galateeffatu matuma isaatiifi; Namni kafares (matuma isaa irratti) Rabbiin dureessa, faarfamaadha” (jechuun).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 13, '(yaadadhu) Yeroo Luqmaan ilma isaatiin jedhe odoo isa gorsuu “yaa ilma kiyya! Allaahiitti waa hin qindeessin; dhugumatti shirkiin miidhaa guddaadha”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 14, 'Namaaf haadhaafi abbaa isaatti (tola ooluu) dhaamnee jirra; haati isaa dadhabbii dadhabbii irratti ta’een isa baadhatte. Harma irraa gu’uun isaa waggaa lama keessatti, “Anaafi haadhaa abbaa keetiif galata galchi, Deebiin gara kiyyatti” (jechuun isa ajajne).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 15, 'Yoo isaan lamaan waan beekumsa isaa hin qabne akka Natti qindeessituuf sitti qabsaawan, tole isaaniif hin jedhin. Addunyaa keessatti haala gaariin isaan waliin jiraadhu. Karaa nama gara kiyya deebi’ee hordofi. Sana booda deebiin keessan gara kiyya; waan isin dalagaa turtan isinittin odeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 16, '(Luqmaan) “yaa ilma kiyya! isheen (badiin) yoo hanga madaala firii raafuu taatee, yoo dhagaa guddaa yookiin samiilee yookiin dachii keessa taate, Rabbiin ishee fida. keessa beekaa rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 17, 'Yaa ilma kiyya! Salaata sirritti sagadi. Toltuutti nama ajaji. Hamtuu irraa nama dhorgi. Waan si mudate irratti obsi. sun wantoota jajjaboo (murannoo gaafatan) irraayyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 18, '[Boonaan] maddii (boqoo) kee namoota irraa gara hin galchin; dachii keessas of tuulaa hin deemin. Rabbiin of tuulaa, of dhaadaa hunda hin jaallatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 19, 'Deemsa kee keessatti giddu galeessa ta’ii, sagalee kee gadi qabi. irra jibbamaan sagaleewwanii sagalee harreeti.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 20, 'Sila akka Rabbiin wantoota samiilee keessaatiifi wantoota dachii keessaas isaaniif laaffisee, tola isaa mul’attuufi dhokattuus isin irratti dhangalaase hin argitanuu? Namoota irraa nama beekumsa, ragaafi kitaaba ibsaa ta’een maletti (waa’ee) Rabbii keessatti falmutu jira', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 21, 'Yeroo “Waan Rabbiin buuse hordofaa” isaaniin jedhame “Lakkisaa; nuti waan abbootii keenya isarratti argine hordofna” jedhu. Oduma Sheyxaanni gara azaaba boba’aatti kan isaan waamullee ta’ee moo?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 22, 'Namni toltuu hojjataa fuula isaa gara Rabbiitti kenne (bute) dhugumatti funyoo cimaa qabateera; booddeen wantoota (hundaatuu) gara Rabbiiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 23, 'Namni kafare kufriin isaa si hin yaachisin. Deebiin isaanii gara keenya; waan isaan dalagan isaanitti ni odeessina. Allaahn beekaa waan qoma keessaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 24, 'Yeroo xiqqoof isaan ni qanansiifna. Sana booda gara azaaba guddaatti isaan dirqisiifna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 25, '“Samiileefi dachii eenyutu uume?” (jettee) yoo isaan gaafatte “Rabbi” jedhu. (Yaa Muhammad!) jedhi “Faaruun hundi kan Rabbiiti”, Garuu irra hedduun isaanii hin beekanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 26, 'Wantoonni samiileefi dachii keessa jiran (hundi) kan Allaahti. Rabbiin Isatu dureessa, faarfamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 27, 'Odoo wanti dachii keessa jiru muka irraa qalamiiwwan ta’ee, baharri booda isaatii kan galaanni torba jiru itti ida’amuudhaan (gargaaree ittiin barreeffameeyyuu) jechoonni Rabbii hin dhumu. Rabbiin injifataa beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 28, 'Isin uumuufi isin kaasuunis akkuma lubbuu tokkittii malee hin taane. Rabbiin dhaga’aa, argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 29, 'Sila hingarree Rabbiin halkan guyyaa keessa seensisee guyyaas halkan keessa seensisuu, aduufi ji’as haala hundumtuu hanga beellama beekamaatti deemanuun kan isaan laaffise ta’uu. Rabbiin wanta isin hojjattan hunda keessa beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 30, 'Kun waan Rabbiin Isatu dhugaa ta’eefi wantoonni Isaa gaditti isaan waammatan soba ta’eefi. Allaahn Isatu ol ta’aa, guddaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 31, 'Sila akka dooniin tola Rabbiitiin galaana keessa deemtu hin arginee? (kuni) (Rabbiin) mallattoollee Isaa irraa isinitti agarsiisuufi. kana mallattooleetu jira akkaan obsitootaafii galateeffattootaa hundaaf .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 32, 'Yeroo danbaliin akka gaaraa isaan haguuge amantaa (kadhaa) Isaaf qulqulleessanii Allaah qofa kadhatu. Yeroma inni gara dachiitti nagaan isaan baase immoo, isaan irraa nama (kadhaa isaa iirraa) of qusatutu jira. Mallattoolee keenya waadaa diigaa, kafaraa hunda malee hin mormu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 33, 'Yaa namootaa! Gooftaa keessan sodaadhaa. Guyyaa abbaan ilma isaa hin fayyadne, kan ilmis abbaa isaa homaa hin fayyadne san sodaadhaa. waadaan Rabbii dhugaadha. Jiruun addunyaa isin hin gowwoomsin. (Sheyxaanni) gowwomsaan (obsa) Rabbiitiin isin hin gowwoomsin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 34, 'Rabbiin beekumsi Qiyaamaa Isuma bira jira. Roobas ni buusa; waan gadaamessaalee keessa jirus ni beeka. Lubbuun tokkos waan boru carraaqqattu hin beektu. Lubbuun tokkos dachii kamitti akka duutus hin beektu. Rabbiin beekaa, keessa hubataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 1, 'Alif Laam Miim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 2, 'Buufamni kitaabichaa Rabbii aalamaa irraa ta''uun shakkiin isa keessa hinjiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 3, 'Sila “(Muhammadtu) of irraa isa uume” jedhuu? Akkasii miti, Dhugumatti, inni dhugaa Rabbii kee irraa ta’ee, ummata siin duratti dinniinaan itti hin dhufin akka dinniintuuf jecha (siif buufame) akka isaan qajeelaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 4, 'Allaahn isa samii, dachiifi waan gidduu isaan lamaanii jiran (hunda) guyyoota jaha keessatti uumee sana. eegasii Arshii irratti (ol ta’iinsa isaan malu) ol ta’eedha. Isaa gaditti gargaaraafi araarsaan tokkollee isiniif hin jiru. Sila hin gorfamtanuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 5, 'Inni wantoota hunda samii irraa gara dachiitti gara gaggalcha (qindeessa) Sana booda gara isaa olbaha guyyaa dheerinni isaa waan isin lakkooftan irraa waggaa kuma ta’e keessatti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 6, 'Inni sana hojjate beekaa fagoofi waan mul’atuu, kan injifataa, rahmata godhaa ta’eedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 7, '(Inni) isa waan uume hunda miidhagseefi uumama namaa dhoqqee irraa jalqabeedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 8, 'Sana booda sanyii isaa dhangala''aa bishaan laafaa irraa ta’e irraa godhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 9, 'Sana booda isa walqixxeessee ruuhii [uumaa] isaa irraa ta’e isa keessatti afuufe. Dhageettii, argaaleefi Onneewwanis isiniif taasise. Xiqquma galateeffattu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 10, '“Sila yeroo (duunee) dachii keessa fagaanne nuti uumama haaraa keessatti taanaa?” jedhan. Dhugumatti, isaan qunnamtii Rabbii isaaniitti kafaroodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 11, 'Jedhiin “Maleykaa du’aa isa isin irratti ramadametu isin ajjeesa, eegasii gara gooftaa keessanii deebifamtu”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 12, 'osoo gartee Yeroo yakkamtoonni Rabbii isaanii biratti mataalee isaanii gadi buusanii “yaa Gooftaa keenya! Arginee, dhageenyee,(addunyaatti) nu deebisi hojii gaarii hojjannaa nuti dhugoomsoodhaa” jedhan (argitee ) [silaa dubbii cimaa argita turte].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 13, 'Odoo feenee lubbuu hundaa qajeeluma ishee isheedhaaf kennina turre. Garuu jechi narraa tahe haqa tahee jira. jinnootaafi namoota walitti qabaman irraa jahannam nan guuta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 14, '“Waan qunnamtii guyyaa keessan kanaa dagattaniif (adabbii) dhandhamaa. Nutis (adabbii keessatti) isin dhiifna; waan dalagaa turtaniifis azaaba zalaalam dhandhamaa” (jedhamu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 15, 'hangi Keeyyattoota keenyatti amanu warra yeroo isheedhaan gorfaman sujuuda bu’anii, Rabbii isaanii galatomfataa faarsani. isaan hinboonanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 16, 'Cinaachoowwan isaanii ciisichoowan irraa ni fagaatti, Goftaa isaanii ni kadhatu sodaataafii kajeelaa. Waan isaaniif kennine irraa ni sadaqatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 17, 'Waan isaaniif dhokfame lubbuun tokkoyyuu hin beektu gammachuu ijaa irraa.Mindaa waan isaan hojjataa turaniif jecha,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 18, 'Sila namni mu’umina ta’e akka nama fincilaatii? Wal hin qixxaa’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 19, 'Ammoo Warri amananii gaggaarii hojjatan jannata qobsumaatu isaaniif jira, qubannoota waan isaan hojjataa turaniif jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 20, 'Isaan fincilan immoo teessoon isaanii ibidda. Dhawaatuma ishee irraa ba’uu barbaanii ishee keessatti deebifamu, “Adaba ibiddaa kan isa sobsiisaa turtan dhandhamaa” isaaniin jedhama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 21, 'Dhugumatti (Nuti) adabbii xiqqaa (kan addunyaa) isaan dhamdhamsiifna, adabbii guddaa dura, akka isaan (gara iimaanaatti) debi’aniif jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 22, 'Eenyu ka ufmiidhe Nama keeyyattoota Gooftaa isaatiin gorfamee sana booda ishee irraa garagale caalaa? Nuti yakkamtoota irraa haaloo bahatoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 23, 'Dhugumatti, Muusaaf kitaaba kennineerra, Isaan wal qunnamuu irraa shakkii keessa hin ta’in, Ilmaan Israa’iiliif qajeeluma isa taasifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 24, 'Isaan irraa imaamota ajaja keenyaan qajeelchan taasifne ,Yeroma isaan obsaniifi keeyyattoota keenya dhugoomsoo tahan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 25, 'Gooftaan kee isumatu Guyyaa Qiyaamaa gidduu isaaniitti murteessa wantoota isaan isa keessatti wal dhabaa turan keessatti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 26, 'Sila ifa isaaniif hin taanee? akka Nuti isaaniin duratti dhaloota baay’ee irraa balleessine gandoota isaanii keessa kan deeman ta’anii. sana keessa mallattooleetu jira. Sila hin dhagahanuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 27, 'Sila akka nuti bishaan gara dachii gogaa oofnee biqiloota horiiwwan isaaniitiifi lubbuulee isaaniitii irraa nyaatan ittiin biqilchinu hin ilaallee? Sila hin arganuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 28, '“ murtiin kun yoom ta’a Yoo kan dhugaa dubbattan taataniif?” jedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 29, 'Guyyaa murtii san warra kafaran iimaanni isaanii isaan hin fayyadu, isaan Yeroo kennamoos hintaane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 30, 'Isaan irraa gara gali. [Adabbii isaanitti bu’u] eegi. isaanis (baduu kee) eegoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 1, 'Yaa nabiyyichaa! Allaah sodaadhu, Kaafirootaafi munaafiqootaafis hin ajajamin. Rabbiin beekaa, ogeessa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 2, 'Waan Gooftaa kee irraa gara keetti beeksisa godhame hordofi. Rabbiin waan isin dalagdan keessa beekaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 3, 'Allaah irratti hirkadhu; hirkoo ta’uuf Rabbiin gayaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 4, 'Rabbiin nama tokkoof keessa (garaa) isaatti onnee lama hin taasifne. Niitolii keessan kan isaan irraa dugda (haadhaatti) fakkeessitan san haadholii keessan hin goone; guddifachaa keessanis ilmaan keessan hin goone. Sun jecha keessan kan isin afaanoowwan keessaniin haasoftaniidha. Rabbiin dhuguma jedha Isatu karaa sirriitti qajeelcha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 5, 'Abboota isaaniitiin isaan waamaa, Isatu Rabbiin biratti irra sirriidha. Yoo abbootii isaanii beekuu baattan, obboleewwan keessan kan amantiitiifi jaalalleewwan keessani. Waan isa dogoggortan keessatti diliin isin irra hin jiru. Garuu waan onneewwan keessan hamilteef (isin qaba). Rabbiin araaramaa, rahmata godhaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 6, 'Nabiyyiin Mu’uminootatti lubbuulee isaanii irra itti aanaadha, jaartiiwwan isaa haadholee isaaniiti. Kitaaba Rabbii keessatti, warra firooma qabantu gariin isaanii garii (dhaaluutti) haqa mu’iminootaafi godaantota caalaa. Garuu gara jaalalleewwan keessaniitti [dhaamsa dhaamuudhaan] gaarii yoo hojjattan [ni eeyyamama]. Kun kitaaba (Lawhal mahfuuz) keessatti barreeffamaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 7, 'Yeroo Nuti nabiyyoota irraa waadaa isaanii fuune: sirraas, Nuuh, Ibraahiim, Muusaafi Iisaa ilma Maryam irraas qabne [yaadadhu]. Isaan irraa waadaa cimaa qabne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 8, '(Rabbiin) warra dhugaa dubbatan dhugaa dubbatuu isaanii irraa akka isaan gaafatuuf (kana godhe). Kaafirootaaf immoo adabbii laalessaa ta’e qopheessee jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 9, 'Yaa warra amantan! Ni’imaa Rabbii kan isin irra jiru yaadadhaa. yeroo hoomaawwan (waraanaa) isinitti dhufanii, ergasii bubbeefi hoomaawwan isin hin agarre isaan irratti ergine, Rabbiin waan isin dalagdan argaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 10, 'Yeroo gubbaa keessaniifi garjalee keessan irraa isinitti dhufan, yeroo ijjoowan jallattee (hiramtee), onneewwanis kokkeewwan geessee, Rabbitti yaada fokkataa yaaddan san [yaadadhaa].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 11, 'Bakka sanitti mu’uminoonni mokkoramaniiti, kirkira cimaa kirkireeffaman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 12, 'Yeroo munaafiqootaafi isaan onneewwan isaanii keessa dhukkubni jiru “Rabbiifi ergamaan Isaas gowwoomsaa malee wanta biraa waadaa nuuf hin goone” jedhan [yaadadhaa].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 13, 'Yeroo gareen isaan irraa taate “Yaa warra madiinaa teessumti isiniif hin jiruu deebi’aa” jatte [yaadadhaa]. Gareen isaan irraa ta’e nabiyyicha hayyama gaafate “manneen keenya hadiyyoo (duwwaa)dha” jedhan, odoo isheen hadiyyoo hin ta’iin, dheefa malee isaan waan biraa hin fedhanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 14, 'Odoo (magaalattiin) moggaalee ishee (hundaan) isaan irratti seenamtee, ergasii shirkii (diin irraa gara galuu) gaafatamanii, dhugumatti ni raawwatu turan. Ishee (shirkii simachuu) irraa waa xiqqoo malee hin turanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 15, 'Dhugumatti, kana dura hin baqannu jechuun Rabbiif waadaa galanii turan. Waadaan Rabbii gaafatamaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 16, '“Yoo du’a yookiin ajjeechaa irraa baqattan ta’e baqachuun isin hin fayyadu. Yeroo san xiqqoo malee hin qanansiifamtanu” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 17, 'Jedhi: “Yoo Inni hamtuu isinitti yaade yookiin rahmata isiniif fedhe, ka Rabbi irraa isin baraaru eenyu? Rabbiin ala jaalalleefi tumsaa isaaniif hin argatanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 18, 'Dhugumatti Rabbiin nibeeka warra duubatti (namoota) deebasaniifi obboleeyyan isaaniitiin “gara keenya kottaa” jedhan. yeroo xiqqoo malee lola hin dhaqan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 19, '(Boojuu argachuu keessan) isin irratti doynoomoo ta’anii (malee lola hin dhufanu); yeroo sodaan (isaanitti) dhufe, akka isa du’aaf gaggabeetti kan ijjoowwan isaanii naannoftu ta’anii gara kee ilaalan isaan agarta. Yeroo sodaan deeme immoo qabeenya irratti bololoo ta’anii arraboota qaraan isin waraanu. Jarri sun hin amanne; Rabbiin dalagaalee isaanii jalaa balleesseera. kun Rabbi irratti laafaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 20, '(Munaafiqoonni) Tuutni kaafiraa hin deemne jedhanii yaadu. Yoo gamtaan diinaa dhufe immoo, (baadiyyaatti) bahanii tikfattoota keessatti (ta’anii) oduulee keessan irraa gaggaafachuu jaallatu. Odoo isin keessa ta’aniillee xiqqoo malee hin lolan ture.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 21, 'Dhugumatti, ergamaa Rabbii keessatti hidhannaa gaariitu isiniif tahee jira, nama Rabbiifi Guyyaa Aakhiraa sodaatee Rabbiin baay’inaan yaadatuuf.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 22, 'Mu’umintoonni yeroma gamtaalee diinaa argan “kun waan Rabbiifi ergamaan Isaa waadaa nuuf galani. Rabbiifi ergamaan Isaa dhugaa dubbataniiru” jedhu. Iimaanaafi (Rabbiif) ajajmuu malee wanta biraa isaaniif hin daballe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 23, 'Mu’uminoota irraa dhiirota waan irratti waadaa Rabbiif galan dhugoomsantu jiru; isaan irraa nama dirqama isaa raawwatetu jira; isaan irraa nama eeggataa jirutu jira. Jijjiirraa (kamillee) hin jijjiirre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 24, 'Akka Rabbiin warra dhugaa dubbatan dhugaa isaaniitiin mindeessuufi munaafiqootas yoo fedhe akka adabuuf yookiin tawbaa isaanii akka irraa qeebaluuf (kana godhan). Rabbiin araaramaa, rahmata godhaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 25, 'Rabbiin isaan kafaran dallansuu isaaniitiin odoo toltuu tokkollee hin argatin isaan deebise. Mu’uminootas Rabbiin lola (irraa) isaaniif ga’eera. Allaahn jabaa, injifataa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 26, '(Rabbiin) abbootii kitaabaa irraa warra isaan (kaafiroota) gargaaran mooraa isaanii irraa isaan buusee, onneewwan isaanii keessatti sodaa darbe. Garii isaanii ni ajjeeftu; garii isaanii immoo ni boojitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 27, 'Dachii isaanii, manneen isaanii, qabeenya isaaniitiifi dachii isin gubbaa hin ejjatiniis isin dhaalchise. Rabbiin waan hunda irratti danda’aa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 28, 'Yaa nabiyyichaa! Niitolii teetiin jedhi “jireenya addunyaatiifi miidhagina ishee kan feetan yoo taataniif, kottaa waan ittiin qananiitan isiniif kenneen, gadi dhiisuu bareedaa ta’e isin gadi dhiisa”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 29, 'Rabbiin, ergamaa Isaatiifi mana Aakhiraa kan filattan yoo taatan immoo, isin irraa warra toltuu hojjataniif Rabbiin mindaa guddaa qopheessee jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 30, 'Yaa dubartoota nabiyyichaa! Isin irraa namni badii ifa galtuu taateen dhufe (raawwate), adabbiin dachaa lama isheetti godhama. Kun Rabbi irratti laafaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 31, 'Isin irraa isheen Rabbiifi ergamaa Isaatiif ajajamtee toltuu hojjatte, mindaa ishee yeroo lama isheef kennina. soorata gaariis (jennatas) isheedhaaf qopheessine', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 32, 'Yaa dubartoota nabiyyichaa! Isin akka dubartii biraa tokkolleetii miti. yoo Rabbiin sodaattan, jecha keessan hin laaffisinaa; Akka inni onnee isaa keessa dhukkubni jiru hin kajeelleef, jecha bareedaa dubbadhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 33, 'Manneen keessan keessa taa’aa; akka mul’ifannaa bara wallaalaa duriitti miidhagina keessan hin mul’isinaa; salaatas sirnaan dhaabaa; zakaas kennaa; Rabbiifi ergamaa Isaatiifis ajajamaa,Yaa maatii nabiyyichaa! Wanti Rabbiin fedhu xurii isin irraa deemsisee qulqulleessiinsa isin qulqulleessuu dha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 34, 'Keeyyattoota (Qur’aana) Rabbiifi hadiisa irraa waan manneen keessan keessatti dubbifamu hubadhaa (ittiin gorfamaa). Rabbiin keessa beekaa, hubataa ta’eera', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 35, 'Dhiironni Muslimaatiifi dubartoonni Muslimaas, dhiironni mu’uminaatiifi dubartoonni mu’uminaas, dhiironni Rabbiif ajajamaniifi dubartoonni Rabbiif ajajamanis, dhiironni dhugaa dubbataniifi dubartoonni dhugaa dubbatanis, dhiironni obsaniifi dubartoonni obsanis, dhiironni (Rabbiin) sodaataniifi dubartoonni (Rabbiin) sodaatanis, dhiironni sadaqataniifi dubartoonni sadaqatanis, dhiironni soomaniifi dubartoonni soomanis, dhiironni qaama saalaa isaanii (haraama irraa) tikfataniifi dubartoonni tikfatanis, dhiironni hedduu Rabbiin faarsaniifi dubartoonni hedduu faarsanis, Rabbiin araaramaafi mindaa guddaa isaaniif qopheesseera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 36, 'Mu’umintichaafi mu’umintittiif yeroo Rabbiifi ergamaan Isaa dhimma tokko murteessan, ajaja isaanii irraa filannoon biraa isaaniif jiraachuun hin taane. Namni Rabbiifi ergamaa Isaa dide, dhugumatti inni jallina ifa ta’e jallateera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 37, 'Yeroo ati isa Rabbiin tola irratti oolee atis tola irratti oolteen “Niitii kee qabadhu, Rabbiinis sodaadhu” jatteen [yaadadhu]. Ammas (yeroo) waan Rabbiin isa ifa baasuuf taa’u, ati of keessatti dhoksite. Odoo Rabbiin sodaachuun irra haqa ta’uu yeroo nama sodaattes [yaadadhu]. Yeroo Zeydiin ishee irraa dhimma fixate (ishee hiike), ishee si fuusifne Akka mu’uminoota irratti niitii ilmaan guddisaa (guddifachaa) isaanii yeroo isaan dhimma irraa fixatan (fuuchuu) keessatti rakkoon hin taaneef jecha, Ajajni Rabbii raawwatamaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 38, 'Waan Rabbiin isaaf murteesse keessatti nabiyyicha irra badiin tokkoyyuu hin jiru. Sun karaa Rabbii kan warra dur dabran keessatti (raawwatamaa) tureedha. Ajajni Rabbii murtee murteeffamaa ta’eedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 39, '(Isaan) warra ergaawwan Rabbii geessaniifi Isa sodaataniidha, Isa malee waan tokkollee kan hin sodaanne. Tiksaa ta’uuf Rabbiinuu ga’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 40, 'Muhammad dhiirota keessan irraa abbaa nama tokkoos hin taane. Garuu inni ergamaa Rabbiitiifi xumura nabiyyootaati. Rabbiin waan hunda beekaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 41, 'Yaa warra amantan! Faaruu baay’ee Allaah faarsaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 42, 'Ganamaafi galgalas faaruudhaan Isa qulqulleessaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 43, 'Inni (Rabbiin) Isa rahmata isin irratti buusuudha. Maleykonni Isaas (akkasuma rahmata isiniif kadhatu); dukkanoowwan keessaa gara ifaatti isin baasuuf (isin mararfata); mu’uminootaaf akkaan rahmata godhaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 44, 'Guyyaa Isa qunnaman salaamtaan isaani ‘nagaan (isin irra haa jiraatuu)’dha, (Allaahn) mindaa gaarii ta’e isaaniif qopheesseera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 45, 'Yaa nabiyyichaa! Nuti ragaa, gammachiisaafi akeekkachiisaa goonee si erginee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 46, 'Hayyama Isaatiin gara Rabbiitti waamaafi ifaa (haqa) ibsaa ta’e goonee (si ergine).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 47, 'Mu’uminoota gammachiisi Rabbi irraa tolli guddaan isaaniif jiraachuun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 48, 'Ajaja kaafirootaafi munaafiqootaa tole hin jedhin. Rakkoo isaaniis (Rabbumatti) dhiisi. Rabbi irratti hirkadhu. Irratti hirkachuuf Rabbumatu ga’a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 49, 'Yaa warra amantan! Yeroo dubartoota mu’uminaa fuutanii, eegasii odoo isaan hintuqin (qunnamtii saalaa hin raawwatin) isaan hiiktan, “Iddaan” isin isaan irratti lakkaawwattan isiniif hin jiru. Isaan qanansiisaa, gadi dhiisuu bareedaas isaan gadi dhiisaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 50, 'Yaa nabiyyichaa! Nuti niitiwwan kee isaan ‘Mahrii’ isaaniif kennite, (boojuu irraa) waan Rabbiin sitti deebise irraa warra harki kee horatte, shamarran abbeeraa (wasiila) keetii, shamarran adaadota keetii, shamarran eessumman keetiifi shamarran haboo (obboleettii haadha) keetiis isaan si waliin godaanan, dubartii mu’uminaas yoo isheen nabiyyichaaf lubbuu ishee kennitee yoo nabiyyiinis ishee fuuchuu fedhe, mu’uminoota biraatiif odoo hin ta’in si qofaaf qulqulluu taatee (isaan fuuchuu) halaal siif goonee jirra. Isaan (mu’uminoota) irratti niitii isaaniitiifi waan harki isaanii horatte keessatti wanta isaan irratti dirqama goone dhugumatti beeknee jirra. Akka rakkoon si irratti hin taaneef (kana goone) Rabbiinis araaramaa, rahmata godhaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 51, 'Isaan irraa nama feete dhiiftee, nama feete immoo gara keetti maxxanfatta. Isaan yeroof dhiifte irraa nama feete (yoo fuutes), badiin sirra hin jiru. Ijjooleen isaanii gammaduu, gadduu dhabuufi hundi isaanii waan ati isaaniif kennite jaallachutti kanatu dhihoodha. Rabbiin waan onneewwan teessan keessa jiru ni beeka. Rabbiin beekaa, obsaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 52, 'Kana booda dubartoonni (biraa) siif halaal hin ta’anu; odoma bareedinni isaanii si dinqisiisellee bakka isaanii warra biraa jijjiiruunis, waan mirgi kee dhuunfatte malee (halaala siif hin ta’u) Rabbiinis waan hunda irratti too’ataa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 53, 'Yaa warra amantan! manneen nabiyyii hin seeninaa, yoo gara nyaataatti hayyamni isiniif godhame malee, Haala bilchina isaa hin eegneen, Garuu yeroo waamamtan seenaa; yeroo nyaattan bittinnaa’aa haasa’atti mukuu bahuun (boharuun) maleetti. Dhugumatti, (gochi) sun nabiyyii rakkisa; isin irraa ni saalfata, Rabbiin garuu dhugaa irraa hin saalfatu, Yeroo meeshaa isaan (niitolii nabiyyii) gaafattanis haguuggii (girdoo) duubaan isaan gaafadhaa. Akkas gochuu keessantu onneewwan keessaniifi onneewwan isaaniitiifis irra qulqulluudha. Ergamaa Rabbii rakkisuufi niitiwwan isaa booda (du’a) isaatii fuuchuun gonkumaa isiniif hin malu, (gochi) sun Rabbiin biratti (badii) guddaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 54, 'Waan tokko yoo mul''iftan, yookiin yoo isa dhoksitan (irratti galata galfamtan) Rabbiin waan hunda beekaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 55, 'Isaan (dubartoota) irratti abboota isaanii, ilmaan isaanii, obboleeyyan isaanii, ilmaan obboleeyyan isaanii, ilmaan obbleettiwwan isaanii, dubartoota isaaniitii (Muslimtootaatii) fi waan mirgi isaanii horatte (gabroota isaanii) biratti (miidhaagina isaanii mul’isuu) keessatti badiin isaan irra hin jiru. Allaah sodaadhaa. Rabbiin waan hunda irratti ragaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 56, 'Rabbiifi maleykonni Isaas nabiyyii irratti rahmata buusu. Yaa warra amantan! (isinis) rahmata isa irratti buusaa; nageenyas buusinsa buusaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 57, 'Isaan Rabbiifi ergamaa Isaa rakkisan, Rabbiin addunyaafi Aakhiraa keessattis isaan abaareera. adabbii xiqqeessaa ta’es isaaniif qopheesseera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 58, 'Isaan mu’uminoota dhiiraafi mu’uminoota dubartiis waan isaan hin hojjatatiniin rakkisan, dhugumatti isaan cubbuufi badii ifa ba’aa baadhataniiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 59, 'Yaa nabiyyichaa! “Niitolii keetiin, shamarran keetiifi dubartoota mu’uminootatiinis, jilbaaba (hijaaba) isaanii (qaama) isaanii irratti gadi buusaa” jedhiin. Akka beekamanii hin rakkifamneefis kanatu irra dhihoodha. Rabbiin araaramaa, rahmata godhaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 60, 'Munaafiqoonniifi warri onnee isaanii keessa dhukkubni jiruufi isaan Madiina keessatti shororkeessitoota ta’aniis yoo (badii isaanii kanarraa) hin dhorgamin, Nuti dhugumatti isaan irratti si kakaafna (moosifna); sana booda yeroo gabaabaaf malee ishee (Madiina) keessa sitti olloomanii hin jiraatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 61, 'Abaaramtoota (ta’anii malee Madiinaa keessatti sitti hin ollooman). Iddoma argamanitti qabamanii ajjeefamiinsa (hamaa) ajjeefaman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 62, 'Karaa Rabbii kan warra duraan dabran keessatti (Inni karaa godhe). Karaa Rabbiitiif jijjiirama hin argitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 63, 'Namoonni Qiyaamaa irraa si gaafatu “Dhugumatti, beekumsi ishee Rabbuma bira jira” jedhiin. Maaltu si beeksise? Qiyaamaan dhihoo ta’uun ni malaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 64, 'Rabbiin kaafiroota abaaree ibidda boba’aa isaaniif qopheessee jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 65, 'Zalaalam ishee keessa jiraatu, jaalallees ta’ee gargaaraa (isaan baraaru) hin argatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 66, 'Guyyaa fuulleen isaanii ibidda keessatti gara gaggalfamtu, “yaa hawwii keenya! Odoo ajaja Rabbiitiifi ajaja ergamaa (Isaa) fudhannee” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 67, '“Yaa Gooftaa keenya! Nuti ajaja matootii keenyaafi gurguddoota keenyaa fudhanneeti isaanis karaa nu jallisan” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 68, '“Yaa Gooftaa keenya! adabbii irraa dachaa lama isaaniif kennii, abaarsa guddaa ta’es isaan abaari.”(jedhan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 69, 'Yaa warra amantan! Akka warra Muusaa rakkifnaani hintahinaa. Rabbiin waan isaan jedhan irraa isa (Muusaa) qulqulleesse. Innis Rabbiin biratti kabajamaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 70, 'Yaa warra amantan! Rabbiin sodaadhaa; jecha sirrii dubbadhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 71, 'Dalagaalee keessanis isiniif tolcha; badiiwwan keessaniis isiniif araarama, Namni ajaja Rabbiifi ergamaa Isaa fudhate dhugumatti milkii guddaa milkaa’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 72, 'Nuti amaanaa samii, dachiifi gaarreen irra (bifa filannootiin) fidne, ishee baadhachuu didanii; ishee irraas sodaatan, Namni immoo ishee baadhate, inni akkaan of miidhaa, wallaalaa ta’ee jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 73, 'Rabbiin munaafiqoota dhiiraafi dubartii, mushrikoota dhiiraafi dubartiis adabuufi akkasumas Rabbiin mu’uminoota dhiiraafi dubartii irraa tawbaa qeebaluuf jecha (kana godhe). Rabbiin araaramaa, rahmata godhaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 1, 'Faaruun hundi kan Rabbii Isa wanti samiilee keessaafi wanti dachii keessaa hundi kan Isaa ta’eeti. Aakhirattis faaruun hundi kanuma Isaati. Inni ogeessa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 2, 'Inni waan dachii keessa seenu, waan ishee irraa bahu, waan samii irraa bu’uufi waan ishee keessa ol ba’us ni beeka. Inni mararfataa, araaramaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 3, 'Warri kafaran “Qiyaamaan nutti hin dhuftu” jedhan. “Akka isin jettanii miti, Rabbii kiyya beekaa waan fagootiin kakadhee! Isheen dhugumatti, isinitti dhufti” jedhiin. Wanti hanga madaala atamii, wanti sana irra xiqqaafi kan sana irra guddaas samii keessaafi dachii keessattis, isa irraa kan hin fagaanne ta’ee, kitaaba ifa baasaa ta’e keessa jiraatu malee (hin hafu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 4, 'Isaan amananii toltuuwwan hojjatan mindeessuuf jecha (Qiyaamaan dhufti). Warri sun araaramaafi hiree gaarii ta’etu isaaniif jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 5, 'Isaan keeyyattoota keenya dadhabsiisoo ta’anii socho’an immoo, adabbii (gosa) azaaba laalessaa irraa ta’etu isaaniif jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 6, 'Isaan beekumsi kennameef, inni Rabbii kee irraa gara keetti buufame inni dhugaa ta’uu nibeeku. gara karaa (Rabbii) injifataa, faarfamaa ta’eetti qajeelcha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 7, 'Isaan kafaran nijedhan “(duutanii) cicciramiinsa guutuu yeroo cicciramtan isin uumaa haarawa keessatti taatu jedhee namicha isinitti odeessutti isin qajeelchinuu?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 8, '“Rabbi irratti soba oddeessa moo maraatummaatu isatti jira?” (jedhu). Akkasii mitii; isaan Aakhiratti hin amanne (Aakhiraatti) adabaafi (addunyaatti) jallina fagoo ta’e keessa jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 9, 'Sila isaan gara waan dura isaaniifi waan duuba isaanii jiru samiifi dachii irraa hin ilaallee? Yoo feenes dachii isaaniin kunna; yookiin cittuu samii irraa taate isaan irratti kuffifna. sana keessa gabricha gara Rabbiitti tawbaa deebi’u hundaaf mallattootu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 10, 'Dhugumatti, Nuti Daawudiif tola Nu biraa ta’e kennineerra. “Yaa gaarreenii! isa (Daawudii) wajjin (Rabbiin) faarsaa sinbirris” (jenne). Sibiila isaaf laaffifnee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 11, '“Qoloo (uffata lolaa) babal’aas hojjadhu; dhawaa isaa keessattis hanga shallagi, Toltuuwwan dalagaa; ani wanta isin hojjattan hunda argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 12, 'Suleeymaaniifis bubbee (laaffifne) (tan) waaree dura (karaa) ji’a tokkoo deemtuufi waaree boodas (karaa) ji’a tokkoo balaliituu. Madda sibiilaas (nahaasaas) isaaf yaafnee jirra. Jinnoota irraa warra hayyama Gooftaa Isaaniitiin fuuldura isaatti hojjatantu jira. Isaan irraa kan ajaja keenya irraa dabe, adabbii ibidda boba’aa irraa ta’e isa dhandhamsiifna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 13, 'Wanta inni barbaade isaaf hojjatu, Iddoolee ibaadaa, fakkiiwwan, gabateewwan (guddinni isaa) akka naannigaa ta’eefi okkoteewwan nahaasaa kan iddoo qabattee teessu irraa (isaaf hojjatan) “Yaa maatii Daawuud (ajaja isaa guutuun) galata (Rabbii) hojjadhaa. Gabroota kiyya irraas namni Ana galatoomfataan xiqqaadha” (jenneen).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 14, 'Yeroma Nuti du’a isa (Suleeymaan) irratti murteessine,wanti du’uu isaa irratti isaan qajelche hin jiru rirma dachii kan ulee isaa nyaattu tokko malee Yeroma inni kufu, jinnoonni odoo iccitii (ghaybii) kan beekan ta’anii, silaa adabbii salphisaa ta’e keessa hin turan jechuu hubatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 15, 'Dhugumatti, (warra) ‘Saba’iif’ iddoo jireenya isaanii keessatti mallattoon ta’eera. (Isheenis) oyruu lama gama mirgaafi bitaatiin kan taateedha. “Soorata Gooftaa keessanii irraa nyaadhaa; galata Isaaf galchaa.” (Biyyattiin keessanis) biyya gaariidha. (Rabbiin keessanis) Gooftaa araaramaadha” (isaaniin jedhame).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 16, '(Ajaja Rabbii irraa) gara galaniiti lolaa hidhaa irraa isaanitti ergine, Ashaakiltii isaan lamaaniis oyruu lama kan abbaa dhandhama hadhaa’aa, birbirsaafi qurquraa irraas waan xiqqoo (kan qabdutti) isaaniif jijjiirre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 17, 'Waan isaan kafaraniif sana galata isaanii galchine. (Adaba akka kanaa) akkaan kafaraa malee ni galchinaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 18, 'Gidduu isaaniitiifi gidduu gandattii barakaa ishee keessatti gooneetti gandoota walitti dhaabbatan goone. hanga adeemsaas ishee keessatti ni safarre. “Ishee keessas halkanoowwaniifii guyyootas nagayaan deemaa.” (jenneen).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 19, 'Isaanis “Yaa gooftaa keenya! Gidduu deemsa (karaa) keenyaa addaan fageessi” jedhan. Lubbuulee isaanii miidhan, oduuwwan isaan taasifnee, bittinneessuu guutuu isaan bittinneessine. sana keessa namoota akkaan obsaniifi akkaan Rabbiin galatoomfatan hundaaf mallattooleetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 20, 'Dhugumatti, Ibliis yaada isaa isaan irratti dhugoomseera. Garee xiqqaa mu’uminoota irraa ta’e malee isa hordofaniiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 21, 'isaaf taaytaan tokkollee isaan irratti hin taane, Isa Aakhiraa dhugoomsu, isa ishee irraa shakkii keessa jiru irraa akka adda beeknuuf malee. Rabbiin kee wantoota hunda irratti tiksaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 22, '(Yaa Muhammad!) “mee isaan Rabbiin ala (gooftoleedha) jettan sana waammadhaa, Samiileefi dachii keessatti waan hanga ulfina atomiillee hin qaban. Isaan lamaan (samiifi dachii) keessattis qoodni isaaniif hin jiru. Isaaf (Rabbiif) gargaaraan isaan irraa ta’e tokkollee hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 23, 'Manguddummaan Isa (Rabbiin) biratti nama Inni isaaf hayyame malee hin fayyaddu. Yeroo onneewwan isaanii (manguddootaa) irraa sodaan deeme “Rabbiin keessan maal jedhe?” jedhanii (gaafatu). “Dhugaa (jedhe); Innis ol ta’aa, guddaadha” jedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 24, '(Yaa Muhammad!) “Eenyutu samiileefi dachii irraa isin soora?” jedhi. “Rabbuma” jedhiin. Dhugumatti nuti yookiin isin qajeeluma irra yookiin jallina ifa ta’e keessa jirra” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 25, '“Isin badii nuti hojjanne irraa hin gaafatamtanu; nutis waan isin hojjattan irraa hin gaafatamnu” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 26, '“Gooftaan keenya walitti nu qaba; ergasiis dhugaadhaan gidduu keenyatti murteessa. Inni haqaan murteessaa, beekaadha” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 27, '(Yaa Muhammad! Warra mushrikaatiin) “Warra shariikota gootanii Isatti dhaqqabsiiftan san mee natti argisiisaa? Dhorgamaa! (Inni shariika hin qabu). Dhugumatti, Inni Allaah injifataa, ogeessa” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 28, 'Nuti nama hundaaf walumaagalatti gammachiisaafi akeekkachiisaa goonee malee si hin ergine. Garuu irra hedduun namootaa hin beekanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 29, '“Yoo kan dhugaa dubbattan taatan waadaan (Qiyaamaan) kun yoomi?” jedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 30, '“Beellama guyyaa isin saa''aa takka isa irraa duubatti hin hafneefi duras hin darbinetu isiniif jira” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 31, 'Isaan kafaran “Qur’aana kanaafi (kitaaba) isa dura bu’ettis hin amannu” jedhan. osoo gartee yeroo Miidhaa raawwattoonni Gooftaa isaanii bira dhaabbatanii jecha gariin isaanii garii irratti deebisu (Silaa wanta cimaa agarta turte). Isaan dadhaboo turan isaan boonaa turaniin “odoo isin jiraachuu baattanii silaa nuti mu''imintoota taana turre” jedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 32, 'Isaan boonaa turanis isaan dadhaboo turaniin “sila nutu karaa qajeelaa irraa isin deebisee erga inni isinitti dhufee booda? Lakkisaa! Isinumatu yakkamtoota taatan” jedhuun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 33, 'Isaan dadhaboo turan isaan boonaa turaniin “Lakkisaa; mala keessan kan halkaniifi guyyaatu; yeroo akka Rabbitti kafarruufi hiriyootaas akka Isaaf taasifnu nu ajajjan santu (badii keessa nu buuse).” jedhan. (Hundi isaaniituu) yeroo adabicha argan gaabbii (sheenaa) isaanii ni dhokfatan. Mormaawwan warra kafaranii keessa dirii (sansalata) goone. Sila waan dalagaa turan malee ni mindeeffamuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 34, 'Magaalaa kamillee keessatti akeekkachiisaa tokkoyuu erginee badhaadhoon ishee “nuti waan isin ittiin ergamatan kanatti kafaroodha” jedhan malee hin hafanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 35, '“Nuti qabeenyaaleefi ilmaanis isin caalaa baay’ee qabna. Nuti kan adabamnu hin taane” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 36, '“Dhugumatti, Gooftaan kiyya soorata nama fedheef bal’isa; (kan fedhe irratti immoo) ni dhiphisa. Garuu irra hedduun namaa (kana) hin beekanu” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 37, 'Qabeenyi keessaniifi ilmaan keessan kan dhiheenya gara keenyatti isin dhiheessu hin taane. Haa ta’u malee namoonni amananii, gaggaarii dalagan isaan sun sababa waan isaan dalaganiitiin mindaa dachaa ta’etu isaaniif jira. Isaanis gamoowwan ol fuudhamoo keessa nageenyaan jiraatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 38, 'Warri dadhabsiisoo ta’anii keeyyattoota keenya keessatti sochii godhan, jarri sun adabbii (ibiddaa) keessa fidamoodha', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 39, '“Dhugumatti, Rabbiin kiyya gabroota Isaa irraa nama fedheef soorata bal’isa; (nama fedhes) isatti dhiphisa.Wanta kamirraayyuu waan isin kennattan Inni bakka isa buusa. Inni irra caalaa warra soorata kennaniiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 40, '(Yaa Muhammad!) guyyaa (Rabbiin) hunda isaanii (gabbaraafi gabbaramaas) kaasee, ergasii maleykotaan “sila isaan kun isin gabbaraa turanii?” jedhu [yaadadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 41, '(Maleykonnis) “(yaa gooftaa keenya!) (qulqullina siif malu) si qulqulleessinee; isaan odoo hin taane gargaaraan keenya Suma qofa. (Akka isaan jedhan) mitii isaan jinni gabbaraa turan. Irra hedduun isaanii isaanitti amanoodha” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 42, 'Har’a (Guyyaa Qiyaamaa), gariin keessan garii fayyaduus ta’ee miidhuu hin danda’u. Isaan lubbuu ofii miidhanii “adaba Ibiddaa ishee sobsiisaa turtan san dhandhamaa” jenna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 43, 'Yeroo keeyyatoonni keenya ifa taatee isaan irratti dubbifamtus “kun namicha waan abbootiin keessan gabbaraa turan irraa isin dhorguu fedhu malee waan biraatii miti” jedhu. “Kun soba uumamaadha malee waan biraa hin taane” jedhu. Isaan kafaran yeroma dhugaan isaanitti dhufe “kuni sihrii ifa bahaa malee waan biraa hin taane” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 44, 'Kitaabota isaan baratan tokkollee isaaniif hin kennine. Siin durattis akeekkachiisaa (ergamaa) tokkollee gara isaaniitti hin ergine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 45, 'Warri isaaniin duraas sobsiisanii jiru. Isaan kun (humnaafi qabeenyaanis) tokko kurnaffaa waan isaaniif kenninee hin geenye. Ergamtoota kiyya sobsiisanii (Nuti isaan balleessine) adabbiin kiyyas akkam ta’e? (Mee xiinxali!)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 46, '(Yaa Muhammad!) jedhi: “kan ani isin gorsu waan tokko qofatti. Innis akka cimdiifi kophaanis Allaahf dhaabattanii, ergasii saahiba keessanitti (Muhammaditti) maraatummaan tokkollee hin jiru jechuu xiinxaltaniif. iInni adabbii cimaa dura isiniif (ergame) akeekkechiisaa malee waan biraa hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 47, 'Jedhi: “mindaa irraa wanti ani isin gaafadhe (yoo jiraates) inni isinumaafi. Mindaan kiyyas Rabbi irratti malee hin taane. Innis waan hunda irratti hirmaataa argaadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 48, '“Dhugumatti, Rabbiin kiyya dhugaa ni buusa (Inni) beekaa iccitiiwwan hundaati” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 49, '“Dhugaan dhufe; sobni (taaytaa isaa) hin jalqabu; hin deebi’us” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 50, '“Yoon jalladhes, kan ani jalladhu lubbuu kiyya irratti. Yoon karaa qajeelaa qabadhes, waan Rabbiin kiyya gara kiyyatti erguuni. Inni dhagayaa, dhihaataadha” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 51, '(Yaa Mohammad SAW!) odoo yeroo isaan (ibidda arganii) rifatan agartee, (silaa waan guddaa agarta). Iddoon itti bahanis (isaaniif) hin jiru. Iddoo dhihoo irraa qabamanii jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 52, '(Guyyaa Qiyaamaa) “Isatti amannee jirra” jedhu. Iddoo fagoo (biyya addunyaa) irraa (iimaana) fudhachuun akkamitti isaaniif mijjata?[1]', '[1] hiikkaan aayata kanaa akka tafsiirri bagawii jedhetti "iimana addunyatti yeroo seenuu mijjaa qaban didan amma aakhiratti eega irraa fagaate amanuun akkamitti isaaniif taha? (hintahu jechuudha)".');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 53, 'Dhugumatti, kana dura isatti kafaranii turan. Iddoo fagoo ta’e irraa (tilmaamaan) haasawa darbatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 54, 'Gidduu isaaniitiifi gidduu waan isaan fedhaniitti akkuma san dura fakkaattota isaanii irratti godhametti haguuggiin godhamee jira. isaan shakkii cimaa keessatti ta’anii jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 1, 'Faaruun hundi kan Rabbii uumaa samiileefi dachii ta’eeti, kan maleykota ergamtoota abbootii kooluuwwan lama lamaa, sadi sadiifi afur afurii taasise. Uumama keessattis waan fedhe ni dabala. Rabbiin waan hunda irratti danda’aadha', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 2, 'Rahmata irraa wanta Rabbiin namaaf bane wanti ishee dhorgu tokkoyyuu hin jiru. Wanta Inni dhorge Isa boodaan wanti ishee gadi dhiisu (ergu) hin jiru. Inni injifataa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 3, 'Yaa namootaa! Ni’imaa Allaah tan isinirratti taate yaadadhaa. Sila Rabbiin ala uumaan biraa kan samiifi dachii irraa soorata isiniif kennu ni jiraa? Isa malee gabbaramaan haqaa hin jiru. Akkamitti isa (irraa) garagaltu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 4, '(Yaa Muhammad!) Yoo si sobsiisan, ergamtoonni si duraas (akkuma kee) sobsiifamanii jiru. Dhimmoonni hundi gara Rabbiitti deebifamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 5, 'Yaa namootaa! Dhugumatti, waadaan Allaah dhugaadha. Kanaafu jireenyi addunyaa akka isin hin gowwoomsine. Gowwoomsaan (Sheyxaanni) (obsa) Rabbiitiin akka isin hin gowwoomsine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 6, 'Sheyxaanni isiniif diinaa, isinis diina isa godhaa. Gareewwan isaas akka warra ibidda boba’aa (seenu) ta’aniif isaan waama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 7, 'Isaan kafaran adabbii cimaatu isaaniif jira. Isaan amananii, gaggaarii hojjatan immoo araaramaafi mindaa guddaatu isaaniif jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 8, 'Sila namni fokkataan hojii isaa isaaf bareechifame, kan bareedaa taasisee isa ilaalu (isa karaa qajeelaa irra jiruu wajjin wal qixa ta’aa)? Allaahn nama fedhe ni jallisa; nama fedhe immoo ni qajeelcha. Isaan irratti lubbuun kee sheenaadhaan akka hin baane. Allaahn waan isaan hojjatan beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 9, 'Allaahnis Isa qilleensa ergee, isheenis duumessa ol kaafti. gara lafa duutieetti isa oofnee dachii erga isheen duutee booda isaan jiraachifne. Kaafamni Qiyaamaas akkuma kana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 10, 'Namni jabeenya fedhe (Rabbiin bira haa barbaadu) Jabeenyi hunduu kan Rabbiiti. Haasofni gaariin gara isaa ol baha. Dalagaa gaariitu isa ol fuudha. Isaan hojii gadheef tooftaa baasan adabbii cimaatu isaaniif jiraTooftaan isaanii inuma bada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 11, 'Rabbiin biyyee irraa isin uume, ergasii bishaan irraa, ergasii cimdii isin taasise. dubartiin kamillee hin ulfooftu; hin deessus Beekumsa Isaatiin ala. Namni umrii dheereffame tokkollee, umriin isaa hin dheereffamu. Umrii isaa irraa hin hir’ifamus kitaaba keessa jiraatu malee; sun Allaah irratti laafaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 12, 'Galaanni lamaan wal qixa hin ta’anu; inni tokko mi’aawaa, dheebu kutaa, dhugaatiin isaas mijaa’aadha; inni kun immoo ashaboo akkaan kuraawaadha. Hunduma irraayyuu foon haarawa ni nyaattu; faaya ishee uffattanus ni baafattu. dooniiwwan isa (galaana) keessa baqaqsituu taatee (kan deemtu) agarta, Akka tola isaa irraa barbaaddattanuufi akka isa galatoomfattanuuf', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 13, 'Inni halkan guyyaa keessa seensisa; guyyaas halkan keessa seensisa. Aduufi ji’as ni laaffise; hunduu hanga beellama beekamaa ta’eetti (orbitii isaanii irra) yaa’u. Inni (kana hojjate) kun Rabbii keessan Allaahdha. mootummaan isaaf tahe, Isaan isin Rabbii gaditti kadhattan wanta hanga qola haphii ija timiraallee hin qabanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 14, 'Yoo isaan kadhattanis, kadhaa keessan hin dhagahan; odoo dhagahaniis isiniif hin owwaatan. Guyyaa Qiyaamaas shirkii keessan ni mormu. (Yaa Muhammad!) Akka Rabbii keessa beekaatti homtuu siif hin odeessu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 15, 'Yaa namootaa! Isin gara Allaahtti haajamoodha; Allaahn Isumatu dureessa, faarfamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 16, 'Yoo fedhe isin (dachii irraa) deemsiseeti uumama haaraa fida.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 17, 'Suni Allaah irratti ulfaataa miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 18, '(Lubbuun) badii hojjattu (tokkos) badii lubbuu biraa hin baadhattu. (Lubbuun) ba’aan (badiin) itti ulfaate tokkos akka ba’aa ishee namni biraa irraa baadhatu yoo gaafattes, odoma fira ishee ta’eellee ishee irraa homaayyuu hin baadhatamu. Kan ati akeekkachiiftu isaan Rabbii isaanii fagootti sodaatanii, Salaatas gadi dhaabaniidha. Namni (badii irraa) of qulqulleesse, kan inni of qulqulleessu matuma isaatiifi. Deebi’iinsi garuma Rabbiiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 19, 'Jaamaafi namni Ija qabu wal hin qixxaatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 20, 'Dukkanootaafi iftis (akkasuma).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 21, 'Gaaddisniifi ho’inis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 22, 'kanneen lubbuun jiraniifi isaan du’an wal qixaa miti. Allaahn nama fedhe ni dhageessisa. Ati nama awwaala keessa jiru dhageessisaa miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 23, 'Ati akeekkachiisaa malee waan biraa hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 24, 'Nuti gammachiisaafi akeekkachiisaa taatee si erginee jirra. Ummanni tokkollee kan akeekkachiisaan isaan keessatti dabru malee hintaane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 25, 'Yoo si sobsiisan, warri isaaniin duraas dhugumatti (ergamoota) sobsiisanii jiru. Ergamtoonni isaanii ragaalee ifa ta’aniin, kitaabota wanta hunda of keessatti hammataniifi kitaaba ibsaa ta’een, isaanitti dhufanii turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 26, 'Ergasiis isaan kafaran qabeen jira. adabbiin kiyya akkam ta’e!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 27, 'sila hin laallee Rabbiin bishaan samii irraa buusee, fuduraalee bifti isaa adda adda ta’e ittiin magarsine. Gaarreen irraas karaalee adaadiifi diddiimaa, bifti ishee gara gara ta’eefi akkaan gurraacha ta’anis (akka uumne hin arginee?)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 28, 'Namoota, lubbu qabeeyyiifi beyladoota irraahis akkasuma warra bifti isaanii waldhabaa tahe uume. Gabroota Isaa irraas kan Allaah sodaatan beektota qofa. Rabbiin injifataa, araaramaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 29, 'Dhugumatti, isaan kitaaba (Qur’aana) Rabbii dubbisanii, salaatas sirnaan dhaabaniifi kan waan Nuti isaaniif kennine irraa dhoksaafi ifattis kennan, daldala kasaaraa hin qabne kajeelu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 30, 'Akka Inni (Rabbiin) galatoota isaanii guutee isaaniif kennuufi tola isaa irraas isaanii dabaluuf (kajeelu). Inni araaramaa, galateeffataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 31, 'Kitaaba (Qur’aana) irraa waani Nuti gara keetti buufne isatu dhugaadha, (kitaabban) isa duraa kan dhugoomsuudha. Rabbiin gabroota isaa akkaan beekaa argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 32, 'Ergasii kitaabicha (Qur’aana kana) isaan gabroota keenya keessaa filanne dhaalchifnee jirra. Isaan irraa nama lubbuu ofii miidhutu jira; isaan irraas nama karaa giddu galeessaa filatutu jira. Isaan irraas warra hayyama Rabbiitiin hojiiwwan gaggaarii irratti dursantu jira. Sun isumatu tola guddaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 33, 'Jannata qubannaa kan ishee seenan, ishee keessattis gumeewwan warqee irraa ta’aniifi faaya uffifamantu (isaaniif jira). Uffanni isaaniis ishee keessatti hariira', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 34, 'Ni jedhu: “faaruun kan Rabbii gadda nurraa deemsiseeti. Gooftaan keenya araaramaa, galateeffataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 35, '(Inni) Isa tola Isa irraa ta’een mana jireenyaa nu qubachiiseedha. kan ishee keessatti rakkoon nu hin tuqneefi kan ishee keessattis dadhabbiin nu hin tuqne keessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 36, 'Isaan kafaran ibidda jahannamtu isaaniif jira. Isaanitti murteeffamtees hin du’anu. adabbii ishee irraas homtuu isaan irraa hin salphifamu. akka kanatti haalaan kafaraa hundaa galata galchina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 37, 'Isaan ishee keessaa waywaatu “(Yaa) Gooftaa keenya! Isa duraan hojjachaa turreen ala toltuu hojjennaa nu baasi” jechuun. “Sila (umrii dheeraa) namni gorfamuu fedhe isa keessatti gorfamuu danda’u isin hin jiraachifnee? akeekkachiisaanis isinitti hin dhufnee? (Adaba kiyya) dhandhamaa; miidhaa hojjattootaaf tumsarraa homaa hin jiru.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 38, 'Dhugumatti, Rabbiin beekaa fagoo samiifi dachiiti. Inni beekaa wantoota qoma keessa jiraniiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 39, 'Inni Isa dachii keessatti bakka bu’oota isin godhe. Namni kafare kufriin isaa isuma irratti. Kaafiroota kufriin isaanii Rabbii isaanii biratti jibbaa malee homaa isaaniif hin dabalu. Kaafiroota kufriin isaanii hoongoo malee homaa isaaniif hin dabalu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 40, '“Sila hiriyoota (shariikoota) keessan kan Rabbiin ala gabbartan mee naaf himaa? Dachii irraa waan isaan uuman mee na argisiisaa. Sila samiilee (uumuu) keessatti hirmaannaan isaaniif ni jiraa? Moo kitaaba isaaniif kenninee, kan isaan ragaa qabatamaa isa irraa ta’e irratti jiran? Lakkisaa; miidhaa hojjattoonni gariin isaanii gariif wal gowwoomsuu malee homaa waadaa waliif hin galanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 41, 'Rabbiin samiileefi dachiin akka hin deemne qaba. Odoo bakkaa deemaniis Isa malee wanti tokkoyyuu isaan lamaan hin qabu. Inni obsaa, araaramaa ta’eera', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 42, 'kakuu isaanii cimaa Rabbitti kakatan Yoo akeekkachiisaan isaanitti dhufe ummatoota kamillee caalaa qajeelaa tahan jechuun . Yeroma akeekkachiisan isaanitti dhufu (dhugaa irraa) dheefa malee homaa isaaniif hin daballe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 43, 'Dachee keessatti boonaafi shira hameenyaa (malee isaaniif hin daballe) shirri hammeenyaa abbaa isaatti malee hin marsu. Sila karaa warra durii malee waan biraa nieeganii? Karaa Rabbiitiif jijjiirama hin argitu; karaa Rabbiitiif (nama biraatti) naannessuu hin argitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 44, 'Sila isaan dachii keessa deemanii booddeen warra isaaniin duraa akkam akka ture hin ilaalanuu? humnaan isaan irra jajjaboo ta’anii turan. Rabbiin samiilee keessattiifi dachii keessattis wanti isa dadhabsiisu hin jiru. Inni beekaa, danda’aa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 45, 'Rabbiin odoo namoota waan isaan hojjataniif qabee dugda ishee (dachii) irratti lubbu qabeeyyii tokkoyyuu hin dhiisu ture. Garuu hanga yeroo beekamaatti isaan tursiisa. Yeroon isaanii hoggaa dhufe (mindeessa) Rabbiin gabroota isaa argaa ta’eera', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 1, 'Yaa Siin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 2, 'Qur’aana ogummaan guutameenin kakadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 3, 'Ati dhugumatti ergamtoota irraayyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 4, 'Karaa qajeelaa irra jirta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 5, 'Buusiinsa Rabbii injifataa, rahmata godhaa ta’e irraa (buufame).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 6, 'Akka akeekkachiiftuufi Ummata abbootiin isaanii hin akeekkachiifamin, kan dagatoo turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 7, 'Dhugumatti, irra hedduu isaanii jechi (adabbiin) irratti mirkanaa’era; isaan hin amananu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 8, 'Nuti mormoota isaanii irratti sakaallaalee goone; isheen hanga lafee areedaatti (geessi). isaan (mataa) ol fudhamoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 9, 'Dura isaaniitti cufaa, duuba isaanittis cufaa goonee isaan haguugne. Kanaafuu isaan hin argan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 10, 'Isaan akeekkachiiftus, isaan akeekkachiisuu baattus isaan irratti wal qixa; isaan hin amananu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 11, 'Kan ati akeekkachiiftu nama gorsa hordofee Rahmaaniinis fagootti sodaate qofa. Araaramaafi mindaa gaariin isa gammachiisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 12, 'Nuti numatu du’aa jiraachifna. Waan isaan hojjatanii dabarsaniifi hambaalee isaanii ni barreessina. Waan hundayyuu kitaaba ifa bahaa keessatti galmeessinee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 13, 'Isaaniif fakkeenya godhi warra gandaa kan yeroo ergamtoonni isheetti dhuftee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 14, 'Yeroo Nuti (ergamoota) lama gara isaaniitti erginee, isaan lamaanuu sobsiisanii, ergasii sadaffaadhaan (isaan) jajjabeessinee, “nuti gara keessanitti ergamoodha” jedhan (fakkeenya godhiif).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 15, 'Isaanis “isin namuma akka keenyaati malee waan biraa miti. Rahmaan homa tokkoyyuu hin buufne; isin kan sobdan malee waan biraa hin taane” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 16, '(Ergamtoonnis) “Rabbiin keenya ni beeka nuti gara keessanitti ergamoodha” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 17, '“ homtuu nurra hin jiru geessiinsa ifa ta’e geessuu malee .”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 18, '(Ummannis) “Nuti isiniin hooddanne (milkii ilaallanne) yoo (waamicha keessan irraa) hin dhorgamin, dhagaan isin tumna. Adabbiin laalessaa ta’es nurraa isin tuqa” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 19, '“Hooddannaan (milkii ilaallachuun) keessan isinumaa wajjin” jedhan. Sila yoo gorfamtanis (ni hooddattuu)? Akkasii miti Isinumatu ummata daangaa dabritoota” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 20, 'Kutaa fagoo magaalattii irraa namichi tokko fiigaa dhufee ni jedhe: “yaa ummata kiyya! Ergamtoota hordofaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 21, 'Namoota mindaa (baasii) isin hin gaafanneefi ofii isaanitiifis qajeelfamoo ta’an hordofaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 22, 'Ani maaltu naaftahe kan Isa na uume hin gabbarre? siniis gara Isaa deebifamtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 23, 'Sila ani Isaa gadittiin gabbaramtoota biraa godhadhaa? kan Yoo Rahmaan miidhaa wahiitiin na fedhe jaarsummaan isaanii homaa ana hin fayyadne isaaniis ana hin baraaran.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 24, 'Ani yeroo san jallina ifa galaa keessa ta’eera', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 25, 'Ani Rabbii keessanitti amanee na dhagayaa” [jedhe] (Achumaan dhagaan tumanii isa ajjeesan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 26, '“Jannata seeni” jedhameen. Innis ni jedhe: “ummanni kiyya odoo beekaniin hawwa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 27, 'Waan Rabbiin kiyya naaf araarameefi kabajamtoota irraa na godhe (odoo beekaniin hawwa).”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 28, 'Booda isaatii ummata isaa irratti hoomaa waraanaa samii irraa hin buufne! Kan buufnus hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 29, 'Isheen iyya tokko malee waan biraa hin taane. Yeroma san isaan dhaamoo (dhabamoo)dha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 30, 'Yaa gaabbii gabrootarratti! Ergamaan kamillee isaanitti dhufee isatti qishinan (baacan) malee hin hafanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 31, 'Sila isaan dura ummata irraa meeqaatama akka balleessine hin arginee? Isaan gara isaaniitti hin deebi’anuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 32, 'Dhugumatti, hundi isaaniituu (murtiif) nubiratti dhihaatoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 33, 'Isaaniif mallattoodha Dachii duutuun Nuti ishee jiraachifneefi firii (adda addaa) ishee irraa baafnee (magarsine) isa irraa nyaatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 34, 'Ishee keessatti oyruu muka timirootaafi inabootaa irraa ta’e taasifneerra, Ishee keessaa burqaalee irraas maddisiifnee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 35, 'Fuduraa isaatiifi waan harki isaanii hojjatte irraa akka nyaataniif (kana goone), Sila hin galateeffatanuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 36, 'Inni cimdii hunda ishee uume qulqullaa’eera, waan dachiin biqilchitu irraa, lubbuulee isaanii irraafi wantoota isaan hin beekne irraa (kanta''an).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 37, 'Isaaniif mallattoodha halkan Isarraa guyyaa baafna. Yeroma san isaan dukkana keessatti ta’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 38, 'Aduun hanga buufata isheef taheetti deemti, Sun murtee (Rabbii) injifataa, beekaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 39, 'Baatii buufataalee isaa goonee jirra. hanga inni akka damee meexxii dullattiitti deebi’utti (deemsifne).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 40, 'Aduun baatii dhaqqabuun isheef hin ta’u; halkanis guyyaa hin dursu, Hunduu sarara keessa (daaku).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 41, 'mallattoodha isaaniif, Nuti sanyii isaanii doonii guutame keessatti fe’uun keenya .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 42, 'Fakkaataa isaa (doonii Nuuh) irraas waan isaan yaabbatan isaaniif uumneerra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 43, 'Odoo feenee bishaaniin isaan dhidhimsina turre. Birmataan tokkos isaaniif hin jiru, Isaan hin baraarfamanus.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 44, 'Rahmata nurraa ta’eef hanga yeroo (muraasaa) akka qanani’aniif (dhiifne) malee (ni dhidhimsina turre).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 45, 'Yeroo ''''waan fuuldura keessaniifi duuba keessan jiru sodaadhaa akka rahmanni isiniif godhamuuf” isaanin jadhame (irraa gara galu)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 46, 'Mallattoolee Rabbii irraa mallattoon tokko isaanitti dhuftee ishee irraa gara galan malee hin hafan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 47, 'Yeroo “waan Rabbiin isiniif kenne irraa kennadhaa” isaaniin jadhame, warri kafaran warra amananiin “sila nama Rabbiin odoo fedhee isa nyaachisu nyaachifnaa? Isin jallina ifa ta’e keessa malee hin jirtanu” jedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 48, 'Ni jedhu: “ baallamni kun yoomi Yoo warra dhugaa dubbatu taatan?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 49, 'Iyyansa tokkittii kan haala isaan wal falmaa jiranuun isaan qabdu malee homaa hin eeganu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 50, '(Yeroo san) dhaamsa (walii dabarsuu) hin danda’an; gara maatii isaaniis hin deebi’anu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 51, 'Garriin (xurunbaan) ni afuufama; yoosuu isaan qabroota irraa gara Gooftaa isaanii bahu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 52, 'Jedhan “Yaa badii keenya! Hirriiba keenya irraa eenyutu nu dammaqse? Kun waan Rahmaan waadaa nuuf gale; ergamtoonnis dhugaa dubbatan” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 53, 'Isheen iyyaansa (afuuffii) tokko malee waan biraatii hintaane. Yeroo san isaan hundi nu bira fidamoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 54, '“Har’a lubbuun tamillee homaa hin miidhamtu. Waan dalagaa turtan malee hin mindeeffamtanu” (isaaniin jedhama).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 55, 'Warri jannataa har’a dalagaan qabamanii gammachuun guutamoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 56, 'Isaaniifi niitiiwwan isaaniis gaaddisoowwaa keessatti, sireewwan irratti hirkatoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 57, 'Isaaniif ishee keessatti fuduraaleetu jira. Wanti isaan yaammatan hunduu isaaniif jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 58, 'Salaamtaan Rabbii abbaa rahmataa irraa isaaniin jedhama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 59, '“Isin yaa yakkamtootaa! Har’a (Mu’uminootaan) adda ba’aa” (isaaniin jedhama).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 60, '“Yaa ilmaan Aadam! Sheyxaana hin gabbarinaa; inni isiniif diina ifa ba’aadha” jechuun waadaa gara keessanitti hin dabarsinee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 61, '“Ana gabbaraa; kanatu karaa qajeelaadha” (isiniin hin jennee)?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 62, 'Dhugumatti (sheyxaanni) isin irraa uumama baay’ee jalliseera. Sila isin sammuu hin qabdanuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 63, '“Isheen tun jahannama ishee waadaa isiniif galamaa turteedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 64, 'Waan kafaraa turtaniif har’a ishee seenaa” (jedhamaani).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 65, 'Har’a afaanoowwan isaanii ni cufna; harkoowwan isaanii Nutti dubbatti; miilloowwan isaaniis waan isaan hojjataa turan ragaa baati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 66, 'Odoo feenee ijaalee isaanii haqna turre. Gama karaatti wal dorgomu; akkamitti argu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 67, 'Odoo feenee iddoowwan isaanii irratti gara uumama biraatti isaan jijjiirras turre. Isaan duratti deemuus ta’ee duubatti deebi’uu hin danda’anu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 68, 'Nama umrii dheeressine uumaa kessatti isa gadi dabsina Sila qalbiin hin yaadanuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 69, 'Nuti isa (Nabiyyii) walaloo hin barsiifne; isaafis hin malu. Inni yaadannoofi Qur’aana ifa galaa malee waan biraa miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 70, 'Akka inni nama jiraa ta’e akeekkachiisuufi kaafiroota irratti jechi (adabbii) mirkanaa’uuf (isa buufne).[1]', '[1] ka qalbiin isaa iimaanaan jiratte jechuutu itti fedhame.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 71, 'Sila waan harkoowwan keenya dalagde irraa beyladoota isaaniif uumnee isaan ishee horatoo ta’an hin ilaallee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 72, 'Ishee isaaniif laaffifne. Gariin isheerraa yaabbii isaaniitiif oolu; garii isheerraa immoo ni nyaatu', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 73, 'Isaaniif ishee keessa faayidaaleefii dhugaatiiwwantu jira. Sila (Rabbiin) hin galateeffattanuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 74, 'Rabbiin ala gabbaramtoota godhatan Akka tumsamaniif jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 75, 'Isaan (isaaniif) tumsuu hin danda’an. Isaan (kaafiroonni) isaaniif (sanamaaf) garee khidmaaf dhufanuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 76, 'Jechi isaanii si hin yaaddessin. Nuti waan isaan dhoksaniifi waan isaan ifa godhanis ni beekna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 77, 'Sila namni akka Nuti bishaan saalaa irraa isa uumne hin arginee? Yeroo san inni mormaa ifa ba’aa ta’ee argama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 78, 'Fakkeenya Nuuf godheeti, uumama isaa dagatee “erga isheen bututtee lafee eenyutu jiraachisa?” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 79, '“Isa yeroo jalqabaa ishee uumetu jiraachisa” jedhi. Inni uumama hunda beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 80, '(Inni) Isa muka magariisa irraa ibidda isiniif godheedha. Yeroo san isin isa irraa qabsiifattu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 81, 'Sila Inni samiileefi dachii uume fakkaataa isaanii uumuu irratti danda’aa mitii? Eeyyeen (danda’aa dha!) Inni akkaan uumaadha, akkaan beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 82, 'Ajajni Isaa, yoo waan tokko fedhe “tahi” isaan jechuma qofa; yoosuu taha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 83, 'Inni mootummaan waan hundaa harka Isaa jiru qulqullaa’e! Garuma Isaatti deebifamtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 1, '(Maleykota) hiriiruu hiriiraniin (kakadha.)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 2, '(Maleeykota) oofiinsa oofaniinis', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 3, '(Isaan Qur’aana) dubbisiinsa dubbisaniinis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 4, 'Dhugaan gabbaramaan keessan tokkicha', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 5, '(Inni) Gooftaa samii, dachiifi wantoota jidduu isaan lamaanii jiraniiti. Gooftaa bahoowwanitis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 6, 'Nuti samii addunyaa faaya urjiileetiin miidhagsineerra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 7, 'Sheyxaana fincilaa ta’e hunda irraas tiksuu (tiksineerra)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 8, 'Gara garee ol aanaa hin dhaggeeffachiifamanu. Gama hunda irraa (urjiin) darbataman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 9, 'Ari’amuuf jecha (darbatamu) Isaaniif adabbii addaan hin cinnetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 10, 'Warra (wahyii) butiinsa butee, qaanqeen uraa (fulla''aa) ta’e isa hordofe malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 11, 'Mee Isaan gaafadhu, Uumuu keessatti kan irra cimu isaani moo warra uumne kan biraati? Nuti dhoqqee walitti qabattuu irraa isaan uumne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 12, 'Dhugumatti, (diduu isaanii) dinqisiifattee jirta; isaan immoo ni qoosu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 13, 'Yeroo gorfamanis hin gorfamanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 14, 'Yeroo mallattoo arganis ni baacu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 15, '“Kun Sihrii ifa galaadha malee waan biraatii miti” jadhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 16, '“Sila erga duunee, biyyeefi lafee taanee booda, nuti kaafamoodhaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 17, 'Abbootiin keenya kan jalqabaatis moo?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 18, '(Yaa Muhammad!) “eeyyeen; xiqqaatoo taatanii (kaafamtu)” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 19, 'Isheen iyyansa tokko qofa; yeroo san isaan ni ilaalu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 20, '“Yaa badii keenya! Kun guyyaa murtiiti” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 21, '“Kun Guyyaa murtii kan isin sobsiisaa turtaniidha” (jedhama).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 22, '“Isaan miidhaa dalagan, hiriyoota (fakkaatoo) isaaniitiifi waan isaan gabbaraa turanis walitti qabaa” (malaykotaan jedhama.)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 23, '“Rabbiin ala (warra gabbaraa turan walitti qabaa); gara karaa ibidda jahiim isaan qajeelchaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 24, 'Isaan dhaabaa; dhugumatti, isaan ni gaafatamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 25, 'Sila maal taataniiti waliif hin tumsine?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 26, 'Dhugumatti isaan har’a harka kennoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 27, 'Gariin isaanii garii irratti gara galanii, wal gaafatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 28, 'Ni jedhu: “dhugumatti, isin mirga irraan [gaarii fakkeessuun] nutti dhufaa turtan.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 29, 'Ni jedhuun: “isinumatu mu’uminoota hin ta’ini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 30, 'Nuti isin irratti aangoo hin qabnu turre. Garuu isinumatu ummata daangaa dabroo taatan.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 31, 'Jechi Rabbii keenyaa nurratti mirkanaa’eera; dhugumatti nuti (adabbii) dhandhamoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 32, 'Ofii keenyaa jallanneeti isin jallifne” [jedhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 33, 'Isaan guyyaa san adabbii keessatti waliin hirmaatoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 34, 'Nuti warra badii hojjatan irratti akka kana dalagna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 35, 'Isaan yeroo “Rabbiin malee gabbaramaan dhugaa hin jiru” isaanin jedhamu ni boonu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 36, '“Sila nuti weellisaa maraataa (kanaaf) gabbaramtoota keenya dhiifnaa?” jedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 37, 'Lakki! Inni dhugaan dhufeeti ergamtootas dhugoomse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 38, 'Isin adabbii laalessaa dhandhamuuf jirtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 39, 'Waan dalagaa turtan malee hin mindeeffamtan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 40, 'gabroottan Rabbii qulqulluu malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 41, 'Warri sun hiree (kennaa) beekamaa ta’etu isaaniif jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 42, 'kabajamoo ta’anii fuduraaleen isaaniif taatuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 43, 'Jannata qananii keessatti (kabajamoodha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 44, 'Haala walitti gara galoo ta’aniin sireewwan irratti ta’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 45, 'Kubbaayyaa farsoo qulqulluu irraa ta’een isaan irra naanna’ama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 46, 'Adii, warra dhuganiif mi’ooytuu kan taate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 47, 'Ishee keessa dhukkubni hin jiru; isaan ishee irraa hin machaa’anis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 48, 'Isaan bira dubartoota ija isaanii gabaabsan, kan ijji babaldhaa ta’etu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 49, 'Isaan (qulqullina keessatti) akka hanqaaquu eegamaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 50, 'Gariin isaanii garii irratti, gara galaniiti wal gaafatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 51, 'Jedhaan isaan irraa ta’e ni jedha: “ani (addunyaa irratti) hiriyaan qaba ture.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 52, 'Kan “sila ati warra (du’a booda kaafamni akka jiru) amanan irraayii?” jedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 53, '“Sila erga duunee biyyeefi lafee (nyaatame) taanee booda kaafamnee mindeeffamnaa?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 54, 'Ni jedhe: “Sila isin (ana waliin deemtanii ) gadi hin ilaaltanii?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 55, 'Gadi millatee walakkaa jahiimitti isa arge.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 56, 'Ni jedhe: “Rabbiin kakadhee! Na balleessitee oolte!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 57, 'Odoo tolli Gooftaa kiyyaa na tiksuu baatee, silaa anis warra (ibidda) seenan irraa ta’een ture.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 58, '(Warri jannataa ni jedhu): “sila nuti lamuu wahii duunaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 59, 'Du’a keenya kan jalqabaa malee; nuti adabamoos miti.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 60, 'Kun isumatu milkii guddaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 61, 'Fakkaataa kanaatiif hojjattoonni haa hojjatanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 62, 'Qubannaaf sanatu caala moo, (muka hadhaawaa) zaqquumtu caala?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 63, 'Dhugumatti Nuti miidhaa raawwattootaaf mokkoroo ishee taasifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 64, 'Isheen muka hundee ibidda jahannam keessaan baatuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 65, 'Firiin ishee akka mataalee sheyxaanotaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 66, 'Isaan ishee irraa nyaatanii garaalee isaanii ishee irraa guuttatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 67, 'Sana booda isaaniif (dhugaatii) bishaan danfaa irraa makametu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 68, 'Sana booda deebiin isaanii gara ibidda jahannam ta’a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 69, 'Isaan abbootii isaanii jallattoota argan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 70, 'Isaan faanoowwan isaanii irra deemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 71, 'Isaan duras irra baay’een ummattoota durii jallatanii jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 72, 'Dhugumatti isaan keessatti dinniintota erginee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 73, 'Booddeen warra dinniinamee akkam akka ta’e ilaali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 74, 'Gabroota Rabbii qulqulleeffamoo malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 75, 'Dhugumatti Nuuh nutti lallabee ture; Nuti warri waamicha owwaate waa tolle!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 76, 'Badii guddaa (bishaanin liqimfamuu) irraa isaafi maatii isaa baraarsine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 77, 'Hortee isaa isaanuma (warra badii jalaa) hafan taasifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 78, 'Isaaf dhaloota boodaa keessatti (yaadannoo gaarii) dhiifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 79, 'Nageenyi aalama keessatti Nuuh irra haa jiraatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 80, 'Nuti akka kanatti toltuu hojjattoota mindeessina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 81, 'Inni gabroota keenya mu’uminootaa irraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 82, 'Sana booda warra kaan ni dhidhimsiifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 83, 'Ibraahiimis hordoftoota (karaa) isaa ( Nuuh) irraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 84, 'Yeroo Rabbii isaa bira onnee qulqulluun dhufe (dubbadhu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 85, 'Yeroo abbaa isaatiifi ummata isaatiin “maal gabbartu?” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 86, '“Sila kijibaani, gooftoota Allaahn ala godhachuu feetanii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 87, 'Rabbii aalama hundaa irratti yaanni keessan maali?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 88, 'Achumaan urjiiwwan keessa ilaalcha tokko ilaale.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 89, 'Ani dhukkubsataadha” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 90, 'Isa irraa gara galanii deeman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 91, 'Ergasii inni gara gabbaramtoota isaanii maqee “sila hin nyaattanuu?” jedheen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 92, 'Maal taatanii hin dubbanne?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 93, 'Ergasii isaan irratti mirgaan rukuttaa irratti raawwate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 94, '(Mushrikoonni) saffisaan gara isaa gara galan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 95, '(Ibraahiim) ni jedhe: “sila waanuma (ofii keessanii) boccan gabbartuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 96, 'Odoo Allaahn isiniifi waan isin dalagdanis uume jiruu.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 97, '(Mushrikoonni) ni jedhan: “jaarmaya isaaf ijaaraa; ergasii ibidda boba’aa keessatti isa darbaa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 98, 'Isaan shira isatti baasuu fedhanii Nuti immoo warra jalaa (moo’amoo) isaan taasifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 99, 'Innis ni jedhe: “Ani gara Rabbii kiyyaa deemaadha; Inni na qajeelcha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 100, '(Yaa) Rabbii (kiyya)! (Ilmaan) gaggaarii naaf kenni.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 101, 'Ilma obsaadhaan isa gammachiifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 102, 'Yeroma isa waliin deemuu irra ga’u ni jedhe: “yaa ilma kiyya! Ani manaama keessatti kan si gorra’un arge. Waan siif mul’atu ilaali.” (Ilmis) ni jedhe: “Yaa abbaa kiyya! Waan ajajamte dalagi. Yoo Rabbiin fedhe obsitoota irraa ta’uu na argita.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 103, 'Yeroo isaan lamaanuu (fedha Rabbiitiif) harka kennan, (abbaan ilma isaa kana) adda isaa irratti ciibse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 104, 'Nutis “Yaa Ibraahiim!” jechuun itti lallabne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 105, '“Abjuu (kee) dhugoomsiteetta. Nuti akka kanatti toltuu hojjattoota mindeessina.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 106, 'Dhugumatti, kun mokkoroo ifa galaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 107, 'Gorra’amaa guddaadhaan isa furre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 108, 'Isaaf (yaadannoo gaarii) warra boodaa keessatti dhiifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 109, 'Nageenyi Ibraahiim irra haa jiraatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 110, 'Akka kanatti toltuu hojjattoota mindaa isaaniif kennina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 111, 'Inni gabroota keenya mu’uminootaa irraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 112, 'Is-haaqiin isa gammachiifne, nabiyyii warra gaggaarii irraa kan tae.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 113, 'Isa irrattiifi Is-haaq irrattis barakaa goone. 
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 114, 'Muusaafi Haaruun irrattis dhugumatti tola oollee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 115, 'Isaan lamaaniifi ummata isaanis rakkina guddaa irraa baraarsinee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 116, 'Isaaniif tumsinee, isaanumatu injifattoota ta’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 117, 'Kitaaba ifa ta’e isaaniif kennine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 118, 'Karaa qajeelaa isaan qajeelchine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 119, 'Isaan lamaaniif dhaloota boodaa keessatti (yaadannoo gaarii) dhiifnee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 120, 'Nageenyi Muusaafi Haaruun irra haa jiraatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 121, 'Nuti akka kanatti toltuu hojjattoota mindeessina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 122, 'Isaan lamaanuu gabroota keenya mu’uminoota irraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 123, 'Ilyaasis ergamtoota irraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 124, 'Yeroo ummata isaatiin jedhe [yaadadhu]:“Rabbiin hin sadaattanuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 125, 'Sila ‘Ba’al’ gabbartanii (Gooftaa) warra waa uumu hunda irra caalaa ta’e dhiiftuu?[1]', '[1] ba''la maqaa taabota isaan gabbaruu turaniiti.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 126, 'Allaah Goftaa keessaniifi Gooftaa abbootii keessan isaan jalqabaa ta’e.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 127, 'Isa sobsiisan. Kanaafuu isaan dhugumatti (adabaaf) dhiheeffamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 128, 'Gabroota Rabbii qulqulleeffamoo malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 129, 'Isaaf dhaloota boodaa keessatti (yaadannoo gaarii) dhiifnee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 130, 'Nageenyi Ilyaas irra haa jiraatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 131, 'Nuti akka kanatti toltuu hojjattoota mindeessina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 132, 'Inni gabroota keenya mu’uminoota irraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 133, 'Luuxiis ergamtoota irraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 134, 'Yeroo isaafi maatii isaa hunda (adaba jalaa) baraarsine [yaadadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 135, 'Jaartii (niitii isaa) kan warra (adabbiif) hafan keessa taate malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 136, 'Sana booda kan biraa hunda ni balleessine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 137, 'Isin ganamfatoo taatanii isaan irra dabartu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 138, 'Halkanis (irra qaxxaamurtu); sila sammuu hin qabdanii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 139, 'Dhugumatti, (nabi) Yuunusis ergamtoota irraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 140, 'Yeroo gara doonii (fe’isaan) guutamee sokke [yaadadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 141, '(Namoota doonii waliin) carraa kaasee, warra carraan itti ba’e irraa ta’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 142, 'Haala komatamaa ta’een qurxummiin isa liqimse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 143, 'Odoo inni warra Rabbiin qulqulleessan [1] irraa ta’uu baatee;', '[1] yeroo qurxummiin isa liqimsite " laa ilaaha illaa anta subhaanaka innii kuntu mina zzaalimiin " jedhee Rabbi kadhate.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 144, 'Silaa hanga guyyaa kaafamaniitti garaa isaa (qurxumichaa) keessa jiraata ture.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 145, 'Isaa dhukkubsataa lafa dirreetti isa darbine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 146, 'Muka buqqee irraa ta’e isa irratti biqilchine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 147, 'Gara (namoota) kuma dhibbaa yookiin sanarra dabalaniitti isa ergine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 148, 'Ni amannaan hanga yeroo murtaa’eetti isaan qanansiifne', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 149, '(Yaa Muhammad!) isaan gaafadhu: “Sila Gooftaa keetiif ilmoon dubaraa ta’aniiti, isaaniif immoo ilmaan dhiiraa ta’anii?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 150, 'Moo isaanii argani malaykota dubara uumnee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 151, 'Dhagaayaa! Isaan soba isaanii irraa ni jedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 152, '“Rabbiin ni dhale” (jedhu) Dhugumatti, isaan kijiboodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 153, 'Sila Inni ilmaan dubaraati ilmaan dhiiraa irra filatee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 154, 'Maal taatan? Akkamitti murteessitan?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 155, 'Sila hin gorfamtanuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 156, 'Moo ragaa ifa ta’etu isiniif jira?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 157, 'Yoo kan dhugaa jettan taataniif kitaaba keessaniin koottaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 158, 'Gidduu Isaatiifi gidduu malaykotaatti firummaa godhan. Malaykoonni dhugumatti akka isaan (kun) dhiaatuuf jiran sirritti beekanii jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 159, 'Waan isaan (kaafirtoonni), isaan jedhan irraa Rabbiin qulqullaa’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 160, 'Gabroota Rabbii isaan qulqulleeffamoo malee (ni dhihaatu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 161, 'Isiniifi wantoonni isin gabbartan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 162, 'Isin isa irratti (nama amane kamillee) jallistootaa miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 163, 'Namoota ibidda jahannam seenun (itti murtaa’e) malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 164, 'Nurraa (maleykaan) tokkollee iddoon beekamaan isaaf ta’u malee hin hafu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 165, '.Nuti (maleykonni), dhugumatti, hiriira galoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 166, 'Nuti dhugumatti Rabbiin qulqullessoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 167, 'Isaan (mushrikoonni) ni jedhu:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 168, '“Odoo yaadannoo warra durii keessaa tokko nu bira jiraatee,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 169, 'Silaa dhugumatti gabroota Rabbii qulqulleeffamoo taana turre.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 170, '(Qur’aanni itti dhufnaan) isatti kafaran. Fuula dura beekuuf jiraatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 171, 'Dhugumatti, jechi keenya gabroota keenya ergamtootaaf dabreera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 172, 'Isaan isaanumatu tumsamoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 173, 'Waraanni keenyas injifattoonni isaanuma (jechuunis dabarte).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 174, '(Yaa Muhammad!) Yeroo murtaa’eef isaan dhiisii irraa garagali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 175, 'Ati itti eegi, fuula dura (waan isaaniif qophaa’e) ni argu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 176, 'Sila adabbii keenya jarjarfatanii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 177, 'Yeroo (adabbiin) qe’ee isaaniitti bu’e, bariisaan warra dinniinamanii fokkateera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 178, '(Yaa Muhammad!) hanga yeroo murtaa’eetti isaan irraa garagali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 179, 'Itti eegi, fuula dura (waan isaaniif qophaa’e) ni argu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 180, 'Goftaan kee, Gooftaan injifannaa, waan isaan jedhaniin irraa qulqullaa’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 181, 'Nageenyis ergamtoota irra haa jiraatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 182, 'Faaruun hundi kan Allaah, Gooftaa aalama hundaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 1, 'Saad Qur’aana abbaa yaadannoo ta’eenin (kakadha)!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 2, 'Dhugumatti isaan kafaran of tuulummaafi mormii keessa jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 3, 'Isaan dura (dhaloota) jaarraa meeqaatama balleessinee jirra. Yeroo baqaaf hin taane walitti lallaban.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 4, 'Sodaachisaan isaan irraa ta’e isaanitti dhufuun isaan dinqisiisee, kaafirtoonni ni jedhan: “kun falfalaa, sobaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 5, 'Sila gabbaramtoota (hunda) gabbaramaa tokko qofa taasisee? Dhugumatti, kun waan dinqisiisaadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 6, 'Gurguddoon isaan (mushrikoota) irraa ta’an deemaniiti “deemaa gooftolee keessan (gabbaruu) irratti obsaa; dhugumatti, inni kun wanta nurraa barbaadamuudha" (waliin jedhan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 7, 'Amantii gara dhumaa (kiristaanummaa) keessatti kana hin dhageenye. Kun waanuma haara’a uumame malee homaa miti."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 8, 'Sila yaadannoon (Qur’aanni) kun nu hunda gidduu isa qofarratti buufamee?” Dhugumatti, isaan yaadannoo kiyya irraa mamii keessa jiru. Garuu hanga ammaatti adabbii (kiyya) hin dhandhamnee (kanaaf kafaran).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 9, 'Furtuuwwan rahmata Rabbii keetii kan injifataa, arjoomaa ta’ee isaan bira jiraa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 10, 'Moo mootummaa samii, dachiifi wantoota gidduu isaanii jirantu kan isaaniitii? Oggas, karaalee keessaan (gara samii) ol haa ba’anii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 11, 'Isaan bakka sana (dirree badrii) keessa jiran humna waraana xiqqoo (dha). Akkuma warri gamtaa durii injifataman saniiti (injifatamuuf jiru).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 12, 'Isaaniin dura ummanni Nuuh, Aadiifi Fir’awni abbaa shikaalaa tae (ergamaa isaanii) sobsiisaniiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 13, 'Samuud, ummanni Luuxiifi warri bosonaas (sobsiisanii jiru) Isaan hunduu gareewwan (dhugaa irratti duulanii dha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 14, 'Hundi isaanii ergamtoota sobsiisan malee hin hafne. Kanaafuu adabbiin (kiyya) isaan irratti mirkanaa’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 15, 'Isaan kun iyyansa tokko kan deebi’uun isheef hin jirre malee homaa hin eegan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 16, 'Ni jedhan: “Yaa Rabbii keenya! (Adaba irraa) qooda keenya guyyaa qormaataa dura nuuf arifachiisi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 17, 'Waan isaan jedhan irratti obsi. Gabricha keenya Daawuudiin abbaa jabeenyaa kan ta’e yaadadhu. Inni akkaan tawbataa ture.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 18, 'Nuti gaarreen isa waliin galgalaafi ganama kan Rabbiin faarsan ta’anii laaffifnee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 19, 'Allaattiinis walitti qabamtuu taatee (isa waliin akka faarsan mijeessinee jirra). Hunduu gara Isaa deebi’oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 20, 'Mootummaa isaa jabeessinee jirra. Hikmaa (nabiyyummaa) fi haasa’a adda baasuus isaaf kennineerra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 21, 'Sila oduun wal falmitootaa kan yeroo dadaa koranii gamoo (isaa) seenan si dhaqqabeeraa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 22, 'Yeroo isaan daawud irratti seenanu, isaan irraa rifate“Hin sodaatin; (nuti) wal falmitoota lama kan gariin keenya garii irratti daangaa dabreedha. Kanaaf gidduu keenyatti dhugaan murteessi. Hin jallisinii, gara karaa sirrii nu qajeelchi” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 23, 'kun obboleessa kiyya, Isaaf hoolota dhaltuu sagaltamii sagaltu jira. Anaaf immoo hoolaa dhaltuu takka qofatu jira. “Ishee naaf kenni” jedheeti, kadhaa keessatti natti jabeesse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 24, '(Daawuud) ni jedhe: “dhugumatti, hoolaa tee gara hoolota isaatti dabalachuuf si gaafachuudhaan miidhaa sirratti dalagee jira. Dhugumatti, irra hedduun warra wajjin hojjatanii gariin isaanii garii irratti miidhaa dalagu; isaan amananii, toltuu dalagan malee Isaanis baay’ee xiqqoodha.” Daawuud akka isa qoranne beekeeti, Rabbii isaa araarama kadhatee, rukuu’as bu’ee, (gara Gooftaa isaatti) deebi’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 25, '(Nutis) sana isaaf araaramne. Dhugumatti, isaaf Nu biratti dhihaannaafi iddoo deebii (jannata) gaarii ta’etu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 26, 'Yaa Daawuud! Nuti dachii keessatti bakka bu’aa si taasifnee jirra. gidduu namootaatti dhugaan murteessi. fedha lubbuu hin hordofin karaa Rabbii irraa si jallisaa. Dhugumatti, isaan karaa Rabbii irraa jallatan, waan guyyaa herregaa dagataniif isaaniif adabbii cimaa ta’etu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 27, 'Samii, dachiifi wantoota gidduu lamaan isaanii jiran, taphaaf hin uumne. Sun sehaa warra kafaraniiti. Isaan kafaraniif laga ibidda irraa ta’etu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 28, 'Sila isaan amananii, toltuuwwan dalagan akka warra dachii keessatti balleessa dalaganii ni goonaa? Moo Warra Allaah sodaatan akka warra yakkamoo ni taasifnaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 29, '(Kun) kitaaba gara keetti isa buufneedha. Barakeeffamaadha. akka isaan keeyyattoota isaa xiinxalaniifi akka warri sammuulee qaban ittiin gorfamuuf jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 30, 'Daawuudiif Suleeymaaniin kennine. Gabricha akkam tole! Inni akkaan tawbataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 31, 'Waaree booda faradoon leenjifamoon, fiigichatti cimoo ta’an yeroo isa irra fidaman (dubbadhu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 32, 'Ni jedhe: “ani jaalala qabeenyaa (fardaa) yaadannoo Gooftaa kiyyaa caalaa jaaladhe. hanga aduun (dukkana halkaniitiin) dhokattutti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 33, 'Isaan kana gara kiyya deebisaa” (jedhee), battalumatti lukaafi morma isaanii mummuruutti seene.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 34, 'Dhugumatti Suleeymaaniin mokkorre. Siree isaa irratti qaama (laafaa) darbine. Eegasii ( tawbaa) deebi’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 35, 'Ni jedhe: “Gooftaa kiyya! Naaf araarami; aangoo ana booda eenyuufillee hin malles naaf kenni. Dhugumatti, Ati situ akkaan kennaadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 36, 'Qilleensa isaaf laaffifnee, ajaja isaatiin laaftuu taatee gara inni fedhetti deemti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 37, 'Shayxaanotas isaan akkaan ijaaraniifi bishaan keessa akkaan lixan hunda (isaaf laaffifne).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 38, 'Warri biroos kan diriin walitti hidhaman (isaaf laaffifne).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 39, '“Kun kennaa keenyaa, kenni! yookiin dhorgadhu! Herreegaan maletti” (janneen).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 40, 'Dhugumatti, isaaf Nu bira dhihaannaafi deebii gaarii ta’etu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 41, 'Gabricha keenya Ayyuubiin dubbadhu yeroo inni Gooftaa isaatti lallabee “shayxaanni rakkinaafi adabaan na tuqee jira” (jedhe).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 42, '(Rabbiin): “Dachii miila keetiin rukuti, Kun (bishaan) qabbanaa’aa dhiqataafi dhugaatiif oolu” (jedheen).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 43, 'Maatii isaa (deebifnee) isaaf kenninee, fakkaataa isaaniis (isaaf daballe). Rahmata nubiraa taheefii, gorsa warra sammuu qabaniif jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 44, '“Harka keetiinis harcummee qabii (niitii kee) isaan rukuti; Waadaa (kee) hin cabsin” (jenneen). (isa mokkorreeti) obsaa ta’uu isa agarre. Gabricha akkam gaarii ta’e! inni akkaan tawbaa deebi’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 45, 'Gabroota keenya Ibraahiim, Is-haaqiifi Ya’aquubiin kanneen (Ibaadaa irratti) cimoofi ija xiinxaltu qaban san dubbadhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 46, 'Dhugumatti, Nuti haala gaariidhaan isaan qulqulleessine. (Isheenis) ganda (Aakhiraa) yaadachuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 47, 'Dhugumatti isaan Nu biratti filatamoo gaggaarii irraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 48, 'Ismaa’il, Yasa’iifi Zulkifliinis dubbadhu; (isaan) hunduu filatamtoota irraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 49, 'Kuni (isaaniif) faaruudha. Isaan Rabbiin sodaataniif deebii gaariitu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 50, 'Jannata qubsumaa kan balballoonni isaaniif banaa ta’antu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 51, 'Ishee keessa (siree irratti) hirkatanii jiraatu. Ishee keessatti fuduraalee baay’eefi dhugaatiis ni waammatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 52, 'Dubartoota (nama biraa ilaaluu irraa) ija gabaabsan, kan umriin isaanii wal qixa ta’etu isaan bira jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 53, 'Kun waan guyyaa herregaatiif beellama godhamtaniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 54, 'Kun kennaa keenyaa, dhumti isaaf hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 55, 'Kun (kan mu’uminootaati) Daangaa dabartootaaf immoo deebii hamaa ta’etu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 56, 'Jahannama ishee seenantu jira. Afatichi waa fokkate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 57, 'Kuni bishaan danfaafi malaadhaa, haa dhandhamanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 58, '[Adabbiin] biraa fakkaataa isaa [kan duraa] ta’e gosa baay’eetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 59, 'Kuni garee isinii waliin ibidda seenaniidha” (maleykaan jettiin) “Simannaan gaariin isaaniif hin ta’in, isaanis (numaa waliin) ibidda seenoodha” (matootiin jedhan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 60, '(Hordoftoonnis) ni jedhu: “Isinis simannaan gaariin isiniif hin godhamin. Isintu karaa kan nuuf godhee (isin hordofne).” Iddoon teessumaa waa fokkatee!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 61, 'Ni jedhu: “Gooftaa keenya! nama kana karaa nuuf godhe ibidda keessatti adabbii dachaa ta’e isaaf dabali.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 62, '(Matootiin warra ibiddaa) Ni jedhu: “Maaliif namoota (duniyatti) warra baay’ee badii hojjatan irraa lakkaa’aa turre (asitti) hin argine?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 63, '(Nutu) qishnaa isaan godhate moo, ijoowantu isaan irraa nu dabe?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 64, 'Dhugumatti, sun dhugaadha; (inni) wal mormii warra ibiddaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 65, '“Ani akeekkachiisaadha; Rabbii tokkicha injifataa ta’e malee dhugaan gabbaramaan hin jiru” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 66, 'Gooftaa samiilee, dachiifi waan gidduu isaan lamaanii jiruu, injifataa, araaramaa ta’e malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 67, 'Jedhi: “inni (Qur’aanni ) oduu guddaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 68, 'Isin isa irraa garagaltani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 69, 'Yeroo isaan (waa’ee Aadam keessatti) falman ani waa’ee jiraattoota olii (maleykotaa) irraa beekumsa hin qabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 70, 'Ani sodaachisaa ifa galaa ta’uu malee beeksifni (biraa) gara kiyya hin godhamu.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 71, 'Yeroo Gooftaan kee malaykotaan “Ani nama dhoqqee irraa uumuufan jira” jedhe [yaadadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 72, '“yeroo isa sirreessee, ruuhii kiyya (kan Ani uume) irraa isa keessatti afuufe isaaf sujuuda bu’aa” (jedheen).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 73, 'Malaykonni hundi isaanii sujuuda bu’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 74, 'Ibliis malee (sujuuda dide) boonee, kaafiroota irraa ta’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 75, '(Rabbiin) ni jedhe: “Yaa Ibliis! Waan Ani harka kiyyaan uumeef sujuuduu maaltu si dhorge? Ni boonte moo, of tuultota irraa taate?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 76, '(Ibliis) ni jedhe: “Anatu isarra caala; ana ibidda irraa na uumte, isa immoo suphee (horofa) irraa isa uumte.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 77, '(Rabbiin) ni jedhe: “ishee irraa ba’i; ati (rahmata irraa) fageeffamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 78, 'Hanga guyyaa murtiitti abaarsi kiyya sirra haa jiraatu.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 79, '(Ibliis) ni jedhe: “hanga guyyaa (du’a irraa) kaafamaniitti na tursiisi.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 80, '(Rabbiinis) “dhugumatti, ati warra tursiifaman irraayi” jedheen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 81, '“Hanga guyyaa yeroo beekamaatti.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 82, '(Ibliis) ni jedhe: “jabeenya keetiin kakadhee! Isaan hunda nan jallisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 83, 'Gabroota kee irraa isaan qulqulleefamoo malee.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 84, '(Rabbiin) ni jedhe: “Egaa dhugaan (Ana irraayi), Ani dhugumaan jedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 85, 'Jahannamiin siifi isaan irraa namoota si hordofan hundaaniin guuta.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 86, '(Yaa Muhammad!) jedhi: “(Qur’aana) kana irratti mindaa isin hin gaafadhu. Ani warra of dirqan irraayis miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 87, 'Inni gorsa aalama hundaati malee waanbiraa miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 88, 'Dhugumatti, oduu isaa yeroo booda beekuuf jirtu.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 1, 'Buufamuun kitaabichaa Rabbii injifataa, ogessa ta’e irraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 2, 'Nuti dhugaan kitaaba gara keetti buufneerra. Rabbiin gabbari amantii Isaaf qulqulleessaa ta’ii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 3, 'Dhaga’aa! Amantiin qulqulluun kan Allaah qofa. Warri Isa malee gargaartota godhatan “gara Rabbiitti akka sirritti nu dhiheessaniif malee isaan hin gabbarru” (jedhu) Rabbiin waan isaan isa keessatti wal dhabaa turan gidduu isaaniitti ni murteessa. Rabbiin nama kijibaa, akkaan kafaraa ta’e hin qajeelchu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 4, 'Rabbiin odoo ilma godhachuu fedhee, silaa waan ofii uumu gidduu kan fedhe filata ture. Qulqullina isaaf malu (sana irraa) qulqullaa’e Inni Allaah tokkicha hunda mo’ataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 5, 'Samiifi dachii dhugaan uume. Halkan guyyaa irratti mara; guyyaas halkan irratti mara. Aduufi baatiis ni laaffise. Hunduu yeroo murtaa’eef deemu. Dhaga’aa! Inni injifataa, araaramaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 6, 'Lubbuu tokko irraa isin uumee, ergasii ishee irraa cimdii ishee taasisee; beeyladoota irraas cimdiiwwan saddeet isiniif buuse; Garaa haadha keessanii keessatti uumama boodaan uumama godhee dukkana sadi keessatti isin uuma. Kun Rabbii gabbaramaa keessan ta’eedha. Mootummaan kan Isaatii. Isa malee dhugaan gabbaramaan hin jiru. Akkamumatti (Isarraa) gara galfamturee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 7, 'Yoo kafartanis, dhugumatti Rabbiin isin irraa dureessa. Garuu gabroota Isaatiif kufrii hin jaallatu. Yoo (Isa) galateeffattan isa isiniif ni jaallata. (Lubbuun) dilii hojjattu tokko dilii (nama) biraa hin baadhattu. Ergasii deebiin keessan gara Gooftaa keessaniiti. Inni waan isin dalagaa turtan isinitti odeessa. Inni beekaa waan qoma keessaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 8, 'Ilmi namaa yoo rakkoon wahii isa tuqe, gara Isaa deebi’uun Gooftaa isaa kadhata. Ergasii yeroo (Rabbiin) ni’imaa Isa biraa ta’e isaaf kenne, Isa (Rabbii) dura kadhachaa ture irraanfata, karaa Isaa irraa (namoota) jallisuuf jecha Rabbiif hiriyaa taasisa. “Kufrii keetti xiqqo bashannani; dhugumatti ati warra ibiddaa irraayi” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 9, 'Sila namni Rabbiif jecha yeroo halkanii sujuudaafi (salaataaf) dhaabbataa, Aakhiraa sodaataa, rahmata Rabbii isaa kajeelaa (Rabbiif) ajajamu (isa hin amanneen wal qixxaataa?) Jedhi: “sila isaan beekaniifi isaan hin beekne wal qixxaatuu?” isaan gorfaman warra sammuu qaban qofa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 10, 'Jedhi: “Yaa gabroota kiyya kan amantan! Gooftaa keessan sodaadhaa. Isaan addunyaa kana keessatti toltuu hojjataniif (Aakhiratti) toltuun (qophaa’ee) jira. Dachiin Rabbii bal’oodha. Warri obsan mindaan isaanii kan isaaniif kennamu lakkoofsa maleedha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 11, '“Ani amantii Isaaf qulqulleessee, Rabbi gabbaruuttin ajajame” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 12, '“Jalqaba Muslimtootaa ta’uttis nin ajajame.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 13, '“Ani yoon ajaja Gooftaa kiyyaa dide adabbii guyyaa guddaan sodaadha” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 14, 'Jedhi: “Ani Rabbuma qofaan, amantii kiyya Isaaf qulqulleessaa ta’ee gabbara.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 15, 'Isaan ala waan feetan gabbaraa“warri hoonga’an isaan Guyyaa Qiyaamaa lubbuulee isaaniitiifii maatii isaaniis hoonga’aniidha. Dhagayaa kun isumatu hoongoo ifa galaadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 16, 'Isaaniif gubbaa isaanii irraa haguuggaa ibidda irraa ta’eetu jira; jala isaanii irrallee haguuggaa (ibiddaatu jira) Sana Rabbiin gabroota Isaa ittiin sodaachisa“Yaa gabroota kiyya! Anuma qofa sodaadhaa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 17, 'Isaan gabbaramoota sobaa ishee gabbaruu irraa fagaatanii, gara Rabbii deebi’an, isaaniif gammachuutu jira. Gabroota kiyya gammachiisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 18, '(Isaan) warra jecha dhageeffatanii, ergasii irra bareedaa isaa hordofaniidha. Isaan sun warra Rabbiin isaan qajeelche. Isaan sun isaanumatu warra qalbiiwwan qabaniidha..', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 19, 'Sila namni jechi adabbii isa irratti mirkanaa’e (nama hamtuu irraa fagaate waliin wal qixaa)? Sila ati nama ibidda keessa jiru ni baraartaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 20, 'Garuu warra Rabbii isaanii sodaatan, isaaniif kutaalee isaan gubbaa kutaaleen (biraa) ijaaramtuun jirtu, kan isaan jala laggeen dhangalaatutu jira. Waadaa Rabbiiti Rabbiin waadaa Isaa hin diigu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 21, 'Sila Rabbiin bishaan (rooba) samii irraa buusee, ergasii burqaalee godhee dachii keessa gadi isa liccisiise hin agarree? Ergasii isaan (bishaaniin) midhaan bifti isaa gara garaa biqilchee, ergasii goggogee daalacha ta’u argita. Ergasii caccabaa godha. Dhugumatti, kana keessa warra sammuu qabaniif gorsatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 22, 'Sila namni Rabbiin qoma isaa Islaamaaf bal’isee, ifaa (beekumsa) Gooftaa isaa irraa ta’erra jiru (akka nama Islaama’uu dideetii)? Yaa badii namoota onneen isaanii zikrii Rabbii irraa gogdee! Isaan sun jallina ifa ta’e keessa jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 23, 'Rabbiin haasawa gaarii, kitaaba (miidhagina keessatti) wal fakkaatu, kan oduun isaa lama lamaan deemtu, kan isa irraa gogaaleen warra Gooftaa isaanii sodaatanii suukannooftu, ergasii gogaaleen isaaniitiifi onneewwan isaanii gara yaadannoo Rabbiitti laafu buusee jira. Kun qajeelfama Rabbiiti; isaan nama fedhe qajeelcha. Nama Rabbiin jallise qajeelchaan isaaf hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 24, 'Sila namni Guyyaa Qiyaamaa fuula isaatiin adabbii hamaa san (qaama) isaa irraa eegu (akka nama jannata seenuutii?) Miidhaa dalagtootaan ni jedhama: “Waan oomishaa turtan dhandhamaa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 25, 'Warri isaaniin duraa sobsiisaniiti, adabbiin gara isaan hin beekneen isaanitti dhufe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 26, 'Rabbiin jiruu addunyaa keessatti salphina isaan dhandhamsiise. Adabbii Aakhiraatu irra guddaadha odoo beekanii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 27, 'Dhugumatti, Nuti namaaf Qur’aana kana keessatti fakkeenya hunda irraa goone akka isaan gorfamaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 28, 'Qur’aana afaan Arabaa haala ta’een, kan jallinna tokko hin qabne ta’ee akka Rabbiin sodaataniif jecha (isaanif buufne).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 29, 'Rabbiin ‘nama tokko kan shariikkan (isa irratti) wal hin taane waliin qabaniifi kan namni tokko qofti qabu fakkeenya godhe Isaan kun lamaan fakkeenyaaf walqixaa? Faaruun hundi kan Rabbiiti. Garuu irra hedduun isaanii hin beekanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 30, 'Dhugumatti, (Yaa Muhammad) ati ni duuta; isaanis ni du’u!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 31, 'Ergasii isin (hunduu) Guyyaa Qiyaamaa Gooftaa keessan biratti wal mormitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 32, 'Sila nama Rabbi irratti sobe, kan yeroo dhugaan isatti dhufu sobsiise irra namni miidhaa hojjate ni jiraa? Sila teessoon kaafirootaa jahannam keessa hin taanee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 33, 'Inni dhugaan dhufeefi kan isa dhugoomses, isaan sun isaanuma warra Rabbiin sodaatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 34, 'Isaaniif waan isaan fedhantu Rabbii isaanii bira jira. Sun galata warra toltuu hojjataniiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 35, 'Akka Rabbiin hamtuu waan dalaganii isaan irraa haqee mindaa isaanii gaarii waan isaan hojjatanii isaanii galata galchuuf (isaaniif laaffise).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 36, 'Sila Rabbiin gabricha Isaatiif ga’aa mitii? Warra Rabbii gaditti (gabbaraniin) si sodaachisu. Nama Rabbiin jallise qajeelchaan isaaf hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 37, 'Nama Rabbiin qajeelches wanti isa jallisu hin jiru. Sila Rabbiin injifataa, haaloo baafataa hin taanee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 38, '“Samiileefi dachii eenyutu uume?” (jettee) odoo isaan gaafattee “Rabbuma” jedhu. “Mee naaf odeessaa? Wanti isin Rabbiin ala waammattan (gabbartan) odoo Rabbiin hamtuu naan fedhee, sila isaan (na) rakkisuu isaa san ni deebisuu? Yookiin odoo rahmataan na fedhee, isaan rahmata Isaa qabuu ni danda’uu?” jedhiin: “Rabbumatu naaf ga’a; warri hirkatan Isa irratti hirkatu.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 39, '“Yaa ummata kiyya! Karaa irra jirtan irratti dalagaa; anis dalagaadha. Fuulduratti beekuuf jirtu” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 40, '“Nama adabbiin isa xiqqeessu itti dhufuufi kan adabbiin dhaabbataan isa irratti bu’u eenyu akka ta’e (beekuuf jirtu).”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 41, 'Nuti namootaaf kitaaba (Qur’aana) dhugaan sirratti buufne. Namni qajeele lubbuma isaatiifi. Namni jallates isheedhuma irratti jallata. Ati isaan irratti dirqama (qajeelchuu) hin qabdu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 42, 'Rabbiin lubbuu yeroo du’a isheetti ni ajjeesa; ishee duuti hin ga’inis hirriiba ishee keessatti (ajjeesa). Ergasii ishee du’a itti murteesse ni qaba. Ishee biraa (kan du’a itti hin murteessin) hanga beellama beekamaatti gadi dhiisa. Dhugumatti, kana keessa warra xiinxalaniif mallattooleetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 43, 'Sila Rabbii gadittii manguddoota godhatanii? “Odoma isaan homaa hin qabneefi sammuus hin qabne (godhatanii?)” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 44, '“Araarri hunduu kanuma Rabbiiti. Mootummaan samiifi dachii kan Isaati. Ergasii gara Isaatti deebifamtu” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 45, 'Yeroo Rabbiin kophaa Isaa faarfamu onneewwan warra Aakhiratti hin amannee ni sunturroofti. Yeroo warri Isaan (Rabbiin) alaa faarfaman yeruma san gammadu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 46, 'Jedhi: “Yaa Rabbii uumaa samiileefi dachii! Beekaa fagoofi dhihoo! Ati nimurteeysita gidduu gabroota keetiitti waan isaan irratti wal dhabaa turan keessatti”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 47, 'Odoo wanti dachii keessa jiru hundi isaan miidhaa dalaganiif ta’ee fakkaataan isaas isaa waliin (isaanif ta’e), adabbii Guyyaa Qiyaamaa hamaa san irraa isaan of bitu turan. Waan isaan hin yaadintu Rabbi irraa isaaniif mul’ate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 48, 'Hamtuuwwan waan isaan hojjatanii isaaniif mul’ate. Wanti isaan itti qishnaa turanis isaanitti marse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 49, 'Namni yeroo rakkoon isa tuqe nu kadhata. Ergasii yeroo Nuti ni’imaa Nu biraa ta’e isaaf kennine, “beekumsuma kiyyaafiin kenname” jedha. Lakkisaa! isheen sun mokkora. Garuu irra hedduun isaanii hin beekanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 50, 'Warri isaaniin duraas ishema jedhanii jiru. Wanti isaan hojjachaa turan homaa isaan irraa hin deebifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 51, '(Galata) hamtuuwwan isaan hojjataniitu isaan tuqe. Kanneen irraa warri miidhaa dalaganis hamtuuwwan waan isaan dalaganii isaan tuquuf jira. Isaan Rabbi duraa hin bahan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 52, 'Sila akka Rabbiin nama fedheef kenna bal’isee, (kan fedhetti immoo) dhiphisu hin beekanuu? Dhugumatti, kana keessa ummata amananiif mallattooleetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 53, '(Yaa Muhammad!) jedhi: “Yaa gabroota kiyya kan lubbuulee isaanii irratti daangaa dabartan! Rahmata Rabbii irraa abdii hin muratinaa. Dhugumatti Rabbiin balleessa hundaa ni araarama. Inni araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 54, 'Gara Rabbii keessanii deebi’aa, Isaafis ajajamaa. Odoo adabbiin isinitti hindhufin dura, Sana booda hin tumsamtanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 55, 'Irra gaarii waan Goftaa keessan irraa gara keessanitti buufamee hordofaa, azaabni tasa odoo isin hinbeekin isinitti dhufuu dura.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 56, 'Lubbuun “Yaa sheenaa kiyya kanin karaa Rabbii keessatti daangaa dabree, warra qishinan irraa ta’ee!” akka hin jenneef (hordofaa).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 57, 'Yookiin “odoo Rabbiin na qajeelchee sila warra Rabbiin sodaatan irraan ta’a ture” akka hin jenneef.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 58, 'Yookaan yeroo adabbii (Rabbii) argite, “carraan (addunyaatti deebi’uu) tokko odoo naaf ta’ee, toltuu dalagdoota irraan ta’a ture” akka hin jenneef.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 59, 'Lakkii; dhugumatti keeyyattooleen kiyya sitti dhufaniiti, ati isaan sobsiiftee, boontee, kaafiroota irraa taate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 60, 'Guyyaa Qiyaamaa warra Rabbi irratti soban kan fuulleen isaanii gurracha ta’e argita. Sila warra boonaniif teessoon jahannam keessa hin taanee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 61, 'Rabbiin warra Isa sodaatan milkii isaaniitiin (jahannam irraa) isaan baraara; hamtuun isaan hin tuqu; isaan hin gaddanus.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 62, 'Rabbiin uumaa waan hundaati. Inni waan hunda irrattis tiksaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 63, 'Furtuuwwan samiileefii dachii kan Isaati. Isaan keeyyattoota Rabbiitti kafaran, isaan sun hoonga’oon isaanuma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 64, '(Yaa Muhammad!) “Yaa wallaaltotaa! Sila Rabbiin ala (waan biraa) gabbaruutti na ajajjuu?” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 65, 'Dhugamatti, gara keetiifi gara warra si dura turaniittis “yoo Rabbii wajjiin waan biraa gabbarte dalagaan kee ni bada; warra hoonga’an irraas taata” jechuun wahyiin buufameera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 66, 'Rabbiin qofa gabbari; galateeffattoota irraas ta’i.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 67, 'Isaan Rabbiin guddina isaaf malu hin guddifne. Guyyaa Qiyaamaa dachiin guutuun qabaa Isaa keessa taati; samiileenis mirga Isaatiin maramtuudha. Inni qulqullaa’e; waan isaan Isa waliin gabbaran irraas ol ta’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 68, 'Garrii (Xurumbaa) keessatti ni afuufama. Warri samiilee keessaatiifi warri dachii keessaa hunduu, kaneen Allaahn (hafuu isaanii) fedhe malee, (rifannootaan) ni dhumu. Ergasii yeroo biraas isa keessatti afuufama. Yeroma san isaan dhaabbatanii ilaaloo ta’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 69, 'Dachiin ifa Gooftaa isiitiin ifti. kitaabban ni kaayamu. Nabiyyootaafi ragooleenis ni fidamu. Gidduu isaaniitti haqaan murteeffama isaan hinmiidhamanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 70, 'Lubbuun hundi waanuma hojjate galata galfamti. Inni waan isaan hojjatan akkaan beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 71, 'Isaan kafaran gara jahannam gareen ta’anii oofamu; hanga ishee bira ga’anii balballeen ishee banamteeti, waardiyoonni ishee “sila ergamtoonni isinitti hin dhufnee kan isin irraa ta’an kan keeyyattoota Gooftaa keessanii isin irratti dubbisaniifi wal ga’ii guyyaa keessanii kana kan isin sodaachisan?” isaaniin jedhan. [Isaan] “eeyyee (dhufaniiru), garuu jecha adabaatu kaafiroota irratti mirkanaa’e” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 72, '“Balbaloota jahannam ishee keessatti hafoo ta’aatii seenaa” jedhama. Teessoon warra boonanii akkam fokkataa dha!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 73, 'Warri Rabbii isaanii sodaatan gareedhaan gara jannataatti oofamu. hanga isaan isitti dhufanii balballoowwan isii banamteetti, waardiyoonni isii “nageenyi isin irra haa jiraatu; toltan;isii seenaa keessatti hafoo ta’aatii ” isaanin jetti (isii seenan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 74, 'Ni jedhan: “faaruun hundi kan Rabbii Isa waadaa Isaa dhugaa nuuf godhee, dachii (jannataas) nu dhaalchiseeti. Jannata keessaa iddoo barbaanne qubanna. Mindaan hojjattootaa waa tole!”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 75, 'Maleykota kan naannoo Arshii marsanii, faaruu Gooftaa isaanii waliin Isa qulqulleessan argita. Gidduu isaaniitti (uumamaatti) dhugaan murteeffama. “faaruun kan Rabbii Gooftaa aalamaati” jedhame.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 1, 'Haa Miim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 2, 'Buufamni kitaabichaa Rabbii injifataa, beekaa ta’e irraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 3, 'Araaramaa dilii, qeebalaa tawbaa, (abbaa) adabbii cimaa, abbaa arjummaa (irraayyi). Isa malee dhugaan gabbaramaan hin jiru; deebiin gara Isaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 4, 'Keeyyattoota Rabbii keessatti warra kafaran malee eenyulleen hin falmu. Dachii keessa gara gaggaluun isaanii si hin dagin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 5, 'Isaan dura ummanni Nuuhiifi gareewwan isaan boodaas sobsiisanii jiru. Ummanni hundi ergamaa isaanii qabuuf yaadaniiru. Sobaan falmanii dhugaa balleessufis yaalan. isaan qabe. adabbiin kiyya akkam ta’e laata!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 6, 'Akkuma kanatti jechi Rabbii keetii isaan kafaran irratti ‘dhugumatti. isaan warra ibiddaati (ta’uun’ mirkanoofte).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 7, 'Isaan (malaykonni) Arshii baadhataniifi isaan naannawa isaa jiranis Gooftaa isaanii faarsuun qulqulleessu; Isattis ni amanu; isaan amananiifis (akkana jechuun) araarama kadhatu: “Rabbii keenya! Ati rahmataafi beekumsaan waan hunda wal geessee jirta; isaan tawbataniifi karaa kee hordofaniif araarami. adabbii jahiim irraas isaan tiksi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 8, '(Yaa) Rabbii keenya! Jannata qubannaa kan waadaa isaaniif galte isaan seensisi; namoota tolan kan abbootii isaanii irraa tahanis, warreen isaaniitiifi ilmaan isaanii irraa ta’anis (seensisi). Ati sumatu injifataa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 9, 'Hamtuulee irraas isaan eegi. Nama hamtuu irraa eegde dhugumatti guyyaa san rahmata isaaf gootee jirta. Suni isumatu milkii guddaadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 10, 'Warri kafaran itti lallabama “jibbaa Rabbii, kan yeroo gara iimaanaa waamamtanii isin kafartan (Inni isin jibbutu) jibbaa mataa keessanii (kan har’a of jibbitan) irra guddaadha”. jechuun itti lallabama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 11, 'Ni jedhan: “yaa Gooftaa keenya! Yeroo lama nu ajjeefteeti yeroo lama nu jiraachifte. Amma balleessaalee keenya fudhanneerraa, karaan (rakkoo hamaa kana irraa) ittiin baanu wahii jiraa?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 12, 'Kun waan isin yeroo Rabbiin kophaa Isaa waamamu kafartanii, yeroo Isatti qindeeffame immoo amantaniifi. Murtiin kan Rabbii ol ta’aa, guddaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 13, 'Inni Isa mallattoolee Isaa isinitti argisiisuufi samii irraa hiree (rooba) isiniif buusuudha. Nama gara Isaa deebi’u malee eenyunuu hin gorfamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 14, 'Rabbiin gabbaraa amantii isaaf qulqulleessoo tahaatii. Odoo kaafirtoonni jibbanillee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 15, '(Rabbiin Isa) sadarkaa ol fuudhu; dhuunfataa ‘Arshiiti.’ wahyii ajaja Isaa irraa ta’e gabroota Isaa gidduu nama fedhe irratti buusa. Akka guyyaa wal qunnamtii akeekkachiisuuf.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 16, 'Guyyaa isaan hundi mul''atan, isaanirraa homaatuu Rabbi irraa hin dhokatu. “Har’a mootummaan kan eenyuuti? Kan Rabbii tokkicha, hunda injifataa ta’eeti.” (jedhama).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 17, 'Har’a (Guyyaa Qiyaamaa) lubbuun hundi waan hojjatte mindeeffamti. Har’a miidhaan hin jiru. Dhugumatti Rabbiin saffisaa herregaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 18, 'Guyyaa dhihaattuu (Qiyaamaa),isaan akeekkachiisi. yeroo onneewwan kokkeewwan bira geessu, yaada guutaman san. Miidhaa raawwattootaaf firri yookiin manguddoon fudhatama qabu tokkolleen hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 19, '(Rabbiin) gantuu ijootaa ni beeka. waan qomoowwan dhoksitus.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 20, 'Rabbiin dhugaan murteessa. Warri Isaa gaditti isaan gabbaran homaa hin murteessanu. Rabbiin Isumatu dhagayaa, argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 21, 'Sila dachii keessa deemanii booddeen warra isaan dura turanii akkam akka taate hin ilaalanuu? Humnaafi dachii keessatti faana dhiisuun isaan irra ciccimoo turan, Rabbiin badiilee isaaniitif isaan qabe (adabbii) Rabbii irraa wanti isaan tiksu tokkollee isaaniif hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 22, 'Kun waan isaan, ergamtoonni isaanii ragaawwan ifa ta’aniin isaanitti dhufnaan, isaan (itti) kafaraniifi. Rabbiin isaan ni qabe. Inni jabaa, adabbii cimaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 23, 'Dhugumatti, Muusaa keeyyattoota keenyaafi ragaa mul''ataan ergineerra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 24, 'Gara Fir’awn, Haamaaniifi Qaaruunitti (erginee) “falfalaa, akkaan sobaadha” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 25, 'Yeroo inni dhugaa Nu biraa ta’een isaanitti dhufe, ni jedhan: “ilmaan dhiiraa warra isaa waliin amananii ajjeesaa; dubartoota isaanii dhiisaa.” shirri kaafirootaa dhabama keessatti malee hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 26, 'Fir’awni nijedhe “Muusaa nan ajjeesaa na dhiisaa, Gooftaa isaa haa waammatuu.” “Ani amantii keessan jijjiruu yookiin dachii keessatti badii mul’isuu isaan sodaadha”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 27, 'Muusaan ni jedhe: “ Ani Rabbii kiyyaafi Rabbii keessanittiin maganfadhe nama boonaa guyyaa herregaatti hin amanne hunda irraa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 28, 'Namichi mu’uminni maatii fir’awni irraa ta’e kan iimaana isaa dhoksu, ni jedhe: “sila isin namicha ajjeeftuu? waan Gooftaan kiyya Rabbuma jedheef, odoo Gooftaa keessan irraa ragaawwan ifa ta’aniin isinitti dhufee jiruu. Yoo sobaa ta’e sobni isaa isuma irratti; yoo nama dhugaa ta’e gariin waan inni isin sodaachisee isin tuqa. Rabbiin nama inni daangaa dabraa, akkaan sobaa ta’e hin qajeelchu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 29, 'Yaa ummata kiyya! Har’a mootummaan keessani, (isin) dachii keessatti ol aantummaa qabaatoodha, yoo adabbiin Rabbii nutti dhufe eenyu nuu tumsa?” (jedheen). Fir’awni “ani waanuman ofii kiyyaa amanu malee isinin hin akeeku; karaa sirraawaa malees isin hin qajeelchu” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 30, 'Inni amane ni jedhe: “Yaa ummata kiyya! Ani fakkaataa guyyaa ummata duriin isin irratti sodaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 31, 'Fakkaataa aadaa ummata Nuuh, Aad, Samuudiifi warra isaan boodaan (isin irratti sodaadha). Rabbiin gabrootaaf miidhaa hin fedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 32, 'Yaa ummata kiyya! Ani (adabbii) guyyaa wal waamiinsaan isin irratti sodaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 33, '(adabbii) guyyaa, kan Rabbi irraa tiksaan isiniif hin jirre taatanii of duuba deebitanuun (isin irratti sodaadha). Nama Rabbiin jallise qajeelchaan tokkolleen isaaf hin jiru.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 34, 'Yuusuf kana dura ragaawwan ifa ta’aniin isinitti dhufee ture. Isin waan inni isinittiin dhufe irraa shakkii keessa ta’uu irraa hin deemne. hanga inni du’etti “Rabbiin isa booda ergamaa hin ergu” jettan. Akka kanatti Rabbiin nama daangaa dabraa, shakkaa ta’e jallisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 35, '(Isaan) warra keeyyattoota Rabbii keessatti, ragaan isaanitti dhufuun maletti falmaniidha; jibbaan (isaanii) Rabbi birattiifi isaan amanan birattis guddate! Akka kanatti Rabbiin (onnee) warra boonaa, of tuulaa hunda irratti cufa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 36, 'Fir’awni ni jedhe: “yaa Haamaan! Akkan karaa ol ga’u gamoo naaf ijaari.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 37, 'Karaawwan samiilee (ol ba’eetan), gara Gooftaa Muusaa ilaala. Ani sobaa ta’uu isaan yaada.” Akka kanatti Fir’awniif hamtuun dalagaa isaa miidhagfamee, karaa (Rabbii) irraas dhorgame. Shirri Fir’awni hoongoo keessatti malee hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 38, 'Inni amane ni jedhe: “Yaa ummata kiyya na hordofaa, Karaa qajeelaan isin qajeelchaa, .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 39, 'Yaa ummata kiyya! Jiruun addunyaa tun qananii (yerooti). Aakhiraan isheetu ganda qubannaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 40, 'Namni hamtuu hojjate, fakkaattuu isiitiin malee galata hin galfamu. Namni toltuu dalage, dhiiras ta’ee dubartii irraas,odoo amanee jiruu, isaan sun jannata seenan. ishee keessatti herrega malee kennamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 41, 'Yaa ummata kiyya! Maali! kan Ani gara nageenyaatti isin waamu, isin immoo gara ibiddaatti na waamtuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 42, 'Na waamtu Akka ani Rabbitti kafaruufi waan waa’ee isaa beekumsa hin qabne isatti qindeessuuf. Ani immoo gara (Rabbii) injifataa, araaramaa ta’eettin isin waama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 43, 'Dhugumatti, wanti isin itti na waamtan sun addunyaa keessattis ta’ee Aakhiraa keessatti waamichi homaatuu isaaf hinjiru. deebiin keenya gara Rabbiiti. daangaa dabroonni isaan warroota ibiddaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 44, 'Waanin ani isiniin jedhu kana yaadachuuf jirtu. Ani dhimma kiyya gara Rabbiittin hirkifadha. Rabbiin gabroota Isaa argaadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 45, 'Rabbiin hamtuuwwan waan isaan itti wal mari’atanii jalaa isa baraarse. Maatii Fir’awnitti adabbii hamaatu bu''e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 46, 'Ibidda (jahannam) kan ganamaafi galgala ishee irra fidamantu (isaanitti bu''e). Guyyaa Qiyaamaan dhaabattu “maatii Fir’awni adabbii akkaan cimaa seensisaa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 47, 'Yeroo ibidda keessatti wal mormanii, isaan dadhaboon isaan boonaniin jedhan “nuti isiniif hordofoo tahuu turre, sila isin nurraa deebisoodhaa qooda ibidarraa tahe?” (jedhan san) (yaadadhu.)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 48, 'Isaan boonan nijedhan “nuti hunduu isheedhuma keessa jirra; Rabbiin dhugumatti gidduu gabrootaatti murteesseera”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 49, 'Isaan ibidda keessa jiran waardiyyoota jahannamiin nijedhan “Gooftaa keessan nuuf kadhaa (hanguma) guyyaa tokko (kan addunyaa) adabbii akka nurraa salphisu”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 50, '(Waardiyyoonni) nijedhan “sila ergamtoonni keessan ragaa ifa ta’een isinitti hin dhufnee?” (Warri ibiddaatis) “eeyyeen; (nutti dhufaniiru)” jedhan. (Waardiyyoonni) ni jedhan “Kadhadhaa! Kadhaan kaafirootaa dhabama keessatti malee hin taane” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 51, 'Dhugumatti, Nuti ergamtoota teenyaafi isaan amananiifis nitumsina jiruu addunyaa keessattiifii guyyaa ragoonni dhaabbatanis (guyyaa qiyaamaas).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 52, 'Guyyaa miidhaa raawwattoota rakkoo himachuun isaanii isaan hinfayyanne, abaarsi isaaniif taha;manni hammaataan isaaniif taha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 53, 'Dhugumatti, Muusaaf qajeelfama kenninee, Ilmaan Israa’iilis kitaaba dhaalchifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 54, 'qajeelfamaafi gorsa Warra qalbiilee qabaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 55, 'Obsi waadaan Rabbii dhugaadha. Dilii teetiif araarama kadhu; Gooftaa keetiis ganamaafi galgala galataan qulqulleessi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 56, 'Dhugumatti, isaan keeyyattoota Rabbii keessatti, odoo ragaan tokkollee isaanitti hin dhufin morman, qomoowwan isaanii keessa boona, itti ga’uu hin dandeenye malee homaatuu hin jiru. Rabbitti maganfadhu. Inni Isumatu dhagayaa, argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 57, 'Samiifi dachii uumuutu namaa uumuu irra guddaadha. Garuu irra hedduun namootaa hin beekanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 58, 'Jaamaafi (inni) argaan wal qixaa miti; isaan amananii, toltuu dalaganiifi inni hamtuu dalagu (wal qixaa miti); hangi isin gorfamtan xiqqoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 59, 'Qiyaamaan dhuftuudha; ishee keessa mamiin hin jiru. Garuu irra hedduun namootaa hin amananu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 60, 'Gooftaan keessan ni jedhe: “Na kadhaa; isiniifiin awwaadhaa. Dhugumatti, isaan gabbartii tiyya irraa boonan, salphattoota ta’anii, jahannam seenuuf jiru.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 61, 'Rabbiin Isa halkan akka ishee keessa boqattaniif, guyyaa immoo garsiisaa (ibsaa) kan isiniif godhe. Dhugumatti, Rabbiin namoota irratti abbaa tolaati. Garuu irra hedduun namootaa hin galatoomfatanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 62, '(Inni kana isiniif godhe) kun Allaah, Gooftaa keessani; Uumoo waan hundaati. Isa malee haqaan gabbaramaan hin jiru. Akkamitti irraa gara galfamtan?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 63, 'Akkanatti warri keeyyattoota Rabbii morman irraa gara galfamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 64, 'Rabbiin Isa dachii (jireenyaaf) mijooftuu, samiilee immoo ijaarsa (gubbaa) isiniif godhee, isin uumee, suuraa keessan bareeche, wantoota gaggaarii irraa isiniif kenne (Inni kana godhe) kun Allaah, Gooftaa keessani. Allaahn Gooftaa aalama hundaa ta’e barakaan Isaa guddate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 65, 'Inni jiraataadha. Isa malee dhugaan gabbaramaan hin jiru. Amantii Isaaf qulqulleessaa Isa kadhaa. Faaruun kan Rabbii, Gooftaa aalama hundaa ta’eeti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 66, 'Jedhi “Ani wantoota isin Rabbii gaditti waamtan (gabbartan) gabbaruu iraa dhorgameera erga ragaawwan ifa ta’an Gooftaa kiyya irraa natti dhufanii booda. Gooftaa aalama hundaatiif harka kennuttiis ajajameera” (jedhi).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 67, 'Inni Isa isin uume biyyee irraa, ergasii bishaan saalaa irraa, ergasii dhiiga ititaa irraa. ergasii daa’ima godhee isin baasa (dhalachiisa). Ergasii akka jabina keessan geessan (isin jiraachisa.) Ergasii akka jaarsa taatan isin godha. Isin irraa nama san dura du’uutu jira. Akka beellama beekamaa geessaniifi, akka sammuu horattaniif (isin jiraachisa).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 68, 'Inni Isa jiraachisuufi ajjeesu. Yeroo waan tokko murteesse “argami” isaan jedha; yoosuu argama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 69, 'Sila isaan keeyyattoota Rabbii keessatti morman akka itti irraa deebifaman hin arginee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 70, 'Isaan kitaabaafi waan Nuti ergamtoota keenya ittiin ergine sobsiisan, (hin arginee?) (fuul duratti) beekuuf jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 71, 'Yeroo sakaallaaleen sibiilaa mormoowwan isaaniitti kaayame, Sansaloonni (itti diramee) niharkifaman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 72, 'Bishaan danfaa keessa (harkifamanii) ergasii ibidda keessatti gubamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 73, 'Ergasii isaaniin jedhama “Isaan Rabbitti qindeessaa turtan sun eessa jiran?”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 74, 'Rabbiin ala (gabbaraa kan turtan) nijedhan “Nu jalaa badaniiru Lakkisaa nuti asiin dura homaa gabbaraa hin turre!” Akka kanatti Rabbiin kaafiroota jallisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 75, '“Kun waan dachii irratti haqaan ala gammadaa turtaniifi waan daangaa dabroo taataniifi”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 76, '“Balbalaalee jahannam ishee keessatti hafoo ta’aa seenaa; (isheen) teessoo warra boontotaa ta’uun waa fokkate!” (isaaniin jedhama).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 77, 'Obsi Dhugumatti, waadaan Rabbii dhugaadha. Yoo garii waan waadaa isaaniif gallee si agarsiifne (waa tole); yookiin yoo si ajjeefne, garuma keenya deebifamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 78, 'Dhugumatti, si dura ergamtoota erginee jirra. Isaan irraa warra seenaa isaanii siif himnetu jira. Isaan irraas warra seenaa isaanii siif hin himintu jiru. Ergamaan tokko hayyama Rabbiitiin ala keeyyata tokkoon dhufuu hin danda’u. Yeroo ajajni Rabbii dhufe, (dhimmichi) dhugaan murteeffama. Kijibdoonni achitti ni hoonga’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 79, 'Rabbiin Isa beyladoota, (garii ishee) yaabbattanii, (garii immoo) nyaattaniif isinii uumeedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 80, 'Isiniif isaan keessa bu’aa adda addaatu jira. Akka dhimmoota qomoota keessan keessatti yaaddan ittiin bakkaan ga’attaniif (isinii uume). isaan irrattiifi dooniiwwan irratti baadhatamtanii (dachiifi bishaan keesa adeemtu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 81, 'Inni mallattoolee Isaa isin agarsiisa. Mallattoowwan Rabbii irraa kam mormitu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 82, 'Sila dachii keessa deemanii, booddeen warra isaan duraa akkam akka ta’e hin ilaallee? Isaan irra bay’ee, humnaanis irra ciccimoo, dachii keessatti faana dhiisuunis isaan caalu turan. wanti isaan dachii keessatti hojjachaa turan (adabbii) irraa isaan hin duroomsine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 83, 'Yeroo ergamtoonni isaanii ragaalee ifa ta’aniin isaanitti dhufan, beekumsa irraa waan isaan bira jirutti gammadanii (boonan). Wanti isaan itti qishnaa turan isaanitti qubate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 84, 'Yeroo adabbii keenya argan ni jedhan: “Rabbitti amanne; tokkichoomsine waan Isatti qindeessaa turrettis kafarre.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 85, 'Amanuun isaanii kan isaan fayyadu hin taane erga adabbii keenya arganii booda (Sun) karaa Rabbii kan gabroota Isaa keessatti dabreedha. Kaafiroonni achitti hoonga’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 1, 'Haa Miim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 2, '(Qur’aanni kun) Rabbii mararfataa, rahmata godhaa ta’e irraa buufamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 3, 'Kitaaba keeyyattoonni isaa adda baafamteedha dubbifamaa Afaan Arabaa ta’ee, namoota akeekkataiif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 4, 'Gammachiisaafi sodaachisaa ta’ee (buufamee dha); irra hedduun isaanii irraa gara galan. Isaan hin dhagayan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 5, 'Ni jedhan: “onneewwan teenya haguuggaa keessa jirti waan isin itti nu waamtan irraa. Gurroowan keenya keessa duudummaatu jira. Gidduu keenyaafi gidduu kee haguuggiitu jira. Ati (waan feete) dalagi; nutis (waan feene) dalagoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 6, 'Jedhi: “ani namuma fakkaataa keessaniiti; gara kiyyatti beeksisaatu godhama (akkana jechuudhaan) ‘dhugaan gabbaramaan keessan gabbaramaa tokkicha qofa; gara Isaa qajeelaa, araaramas Isa kadhadhaa, warra (Isatti) qindeessaniif adabatu jira".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 7, 'Isaan warra zakaa hin kennine, kan Aakhiratti kafaraniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 8, 'Isaan amananii, toltuuwwan hojjatan isaaniif mindaa adda hin cinnetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 9, 'Jedhi: “Sila isin Isa dachii guyyaa lama keessatti uumetti kafartanii, hiriyyaalee Isaaf gootanii? Sun Gooftaa aalamootaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 10, 'Ishee (dachii) keessatti gaarreen lafa qabatoo ta’an; gubbaa isiitti godhee, ishee keessatti barakaa godhe. Ishee keessatti soora ishee murteesse guyyuma afur keessatti. kadhattootaaf qixa haala taheen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 11, 'Ergasii gara samii ol ta’e, haala isheen aara taatee jirtuun. isheefi dachiinis “jaalattanii yookiin jibbitanii kottaa” jedhe. Isaanis “jaalannee dhufne” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 12, 'Samii torba godhee isheewwan xumuree Guyyaa lama keessatti. samii hunda keessatti, dhimma ishee beeksisa itti godhe. Samii addunyaas ifaadhaaleen (urjiileen) miidhagsinee, tika cimaas (tiksine). Kun murtii (Rabbii) injifataa, beekaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 13, 'Yoo isaan gara galan “ani isin sodaachiseera iyyansa (hamaa), akka iyyansa ummata Aadiifi Samuudin” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 14, '(adabbii) yeroo ergamtoonni fuuldura isaaniitiifi duuba isaaniitiin itti dhufanii “Rabbiin malee (waan biraa) hin gabbarinaa” (isaaniin jennaan), “Gooftaan keenya odoo fedhee malaykota buusa ture; Nuti waan isin itti amantanitti kafarree jirra” jedhanii san (isin sodaachise).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 15, 'Aad immoo dachii keessatti haqaan malee boonanii “humnaan namni nurra cimaa eenyu?” jedhan. Sila Rabbiin, Inni isaan uume sun inni humnaan isaan irra cimaa ta’uu hin arginee? Keeyyattoota keenya mormaa turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 16, 'Guyyoota (isaaniif) hamaa keessatti bubbee cimaa isaan irratti ergine, Akka jiruu addunyaa keessatti adabbii salphinaa isaan dhandhamsiifnuuf jecha. (Haa ta’uu malee) adabbii Aakhiraatu irra salphisaadha. Isaan hin tumsamanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 17, 'Samuudiinis isaan qajeelchineeti, qajeelloo irra jallina filatani; duuti adabbii salphisaa isaan qabatte waan isaan hojjataa turaniif .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 18, 'Isaan amananii, Rabbiin sodaatoo tahan nagaya baafne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 19, 'Guyyaa diinotiin Rabbii gara ibiddaatti walitti qabamanii isaan ittifaman san [yaadadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 20, 'Yeroo ishee bira dhufan, dhageettiin isaanii, agartuuwwan isaanitiifi gogaaleen isaanii waan isaan dalagaa turan ragaa isaan irratti ba’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 21, 'Gogaalee isaanitiin “Maalif ragaa nurratti baatu?” jedhan. [Isaan] ni jedhu: “Rabbii Isa waan hunda dubbachiisetu nu dubbachiise, inni kan yeroo jalqabaa isin uume, kan gara Isaatti deebifamtan.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 22, 'Isin kan of dhoksitan hin taane dhageettiin keessan, agartuuleen keessaniifi gogaaleen keessan ragaa isin irratti ba’uurraa. Haa ta’u malee, Rabbiin hedduu waan isin dalagdanii hinbeekuu yaaddan. [1]', '[1] sun dogoggora keessani Rabbiin waan dalaydan hunda nibeeka.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 23, 'Sun yaada keessan, kan isin Gooftaa keessanitti yaaddaniidha. Isin balleessee, warra hoonga’an irraa taatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 24, 'Yoo obsan, ibiddi teessoo isaaniiti, yoo ceephoo buufachuu barbaadan, isaan warra ceephefamu irraayii miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 25, 'Nuti hiriyoota (Sheyxaanaa) isaaniif ramadneeti, wantoota fuuldura isaaniitiifi wantoota booda isaanii isaaniif bareechan. Jechi (adabbiin) isaan irratti mirkanaa’e akkuma ummatoota isaaniin duraa kan jinniifi nama irratti mirkanaa’e, Isaan dhugumatti hoonga’oo ta’aniiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 26, 'Isaan kafaran “Qur’aana kana hin dhaga’inaa; (yeroo dubbifamu) isa keessatti wacaa akka injifattaniif ” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 27, 'Isaan kafaran adabbii cimaa isaan dhandhamsiifna. Dhugumatti, hamtuu isaan dalagaa turaniifis (adabaan) isaanii galata galchina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 28, 'Sun waan mindaan diinotii Rabbii ibidda ta’eefi. Isaaniif ishee keessa mana jireenya turaatu jira. Waan keeyyattoota keenya mormaa turaniif galata galfaman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 29, 'Isaan kafaran nijedhan “Gooftaa keenya! Isaan jinnootaafi namoota irraa nu jallisan lamaan nutti agarsiisi; faana keenya jala isaan goona, akka warra jalaa keessa irraa ta’aniif” (jedhan.)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 30, 'Isaan “gabbaramaan keenya Allaahdha” jedhanii, ergasii achirratti gadi dhaabbatan, (yeroo isaan du’an) malaykonni isaan irratti bubu’aniiti, “hin sodaatinaa; hin gaddinaas; jannata waadaa isiniif galameen gammadaa. (isaaniin jetti).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 31, 'Nuti jiruu addunyaa keessatti jaalalloo keessan turre; Aakhirattis akkasuma. Isiniif ishee (jannata) keessa waan lubbuuleenn teessan feetutu jira. Isiniif ishee keessa waan barbaaddantu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 32, 'Afeerraa (Rabbii) araaramaa, rahmata godhaa irraa ta’eedha” (isaaniin jedhu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 33, 'Namni jecha bareedu eenyu Nama gara Rabbiitti waame caalaa? kan hojii gaggaarii hojjatee “ani Muslimoota irraayi” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 34, '(Hojiin) gaariiniifi hamtuun wal hin qixxaa’an. Ishee toltuu taateen deebisi. Yoos inni gidduu keetiifi gidduu isaa diinummaan jirtu akka jaalalloo firaa ta’uu (agarta).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 35, 'Warra obsan malee eenyulleen ishee hin argatu. Abbaa qooda guddaa qabu malee eenyulleen ishee hin argatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 36, 'Yoo waswaasaan shayxaana irraa ta’e si jallise, Rabbitti maganfadhu. Inni Isumatu dhaga’aa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 37, 'Mallattoolee Isaa irraayyi Halkan, Guyyaan, Aduufi Baatiinis, Aduufii baatiifis hin sujuudinaa Rabbii isaan uume qofaaf sagadaa, Yoo kan (dhugaan) Isa gabbartan taatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 38, 'Yoo boonan, isaan (malaaykoonni) Rabbii kee bira jiran halkaniifi guyyaa Isa qulqullessu; isaan hin hifatanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 39, 'Mallattoolee Isaa irraayi Ati dachii gogduu taate arguun. yeroo Nuti ishee irratti bishaan (rooba) buufne ni sochooti, ni tullooftis. Dhugumatti, Inni ishee jiraachise, warra du’e jiraachisaadha. Inni waan hunda irratti danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 40, 'Dhugumatti, isaan keeyyattoota keenya bakka irraa dabsan nu jalaa hindhokatan. Sila isa ibidda keessatti darbamu caala moo, isa nagaa ta’ee Guyyaa Qiyaamaa dhufutu caala? Waan feetan dalagaa; Inni waan isin dalagdan hunda argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 41, 'Isaan yaadannotti (Qur’aanatti) kafaran erga inni itti dhufee booda. (nidhabamsiifamu). Inni kitaaba injifataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 42, 'Sobni fuuldura isaatiis ta’ee duuba isaatiin itti hin dhufu.(Rabbii) ogeessa faarfamaa ta’e irraa buufame.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 43, 'Waan ergamtoota si duraatiin jedhameen ala wanti siin jedhamu hin jiru. Gooftaan kee abbaa araaramaatiifi abbaa adabbii laaleessaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 44, 'Odoo Qur’aana afaan ajamii (Arabiffaan ala) goonee, sila “maaliif keeyyattoonni isaa sirritti hin ibsamin jedhu, akkamitti (Qur''aanni) afaan Ajamiin (ergamaan) Arabaan tahe?” (jedhu turan). (Yaa Muhammad!) jedhiin: “Inni warra amananiif qajeelfamaafi qoricha. Isaan hin amanin gurra isaanii keessa duudummaatu jira. Innis isaan irratti jaamummaadha. Isaan sun (akka nama) iddoo fagoo irraa waamamuuti.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 45, 'Dhugumatti, Muusaaf kitaaba kennineeti, isa keessatti wal dhabame. Odoo jechi Gooftaa kee biraa dabarte jiraachuu baattee gidduu isaaniitti murtiin ni kennama ture. Isaan isa irraa shakkii mamsiisaa keessa jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 46, 'Namni toltuu hojjate lubbuu isaatiifi. Namni hammaates isimarratti. Gooftaan kee gabroota miidhaa hintaane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 47, 'Beekumsi yerottii (Qiyaamaa) garuma Isaatti deebifama. firiin kamillee qola ishee keessaa hin baatu, dubartiin kamuu hin ulfooftu, hin deessus Beekumsa isaatiin malee. Guyyaa “shariikonni kiyya eessa jiru?” (jedhee) Inni itti lallabu ni jedhu: “(Yaa Rabbi!) si beeksifna nurraa kan (Ati shariika qabaachuu) ragaa ba’u hinjiru.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 48, 'Wanti isaan duraan (addunyaa irratti) kadhachaa (gabbaraa) turan isaan irraa bade. Karri itti dheessan isaaniif hin jiruu ni mirkaneeffatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 49, 'Namni toltuu (qabeenya) kadhachuu irraa hin hifatu. Yeroo hamtuun (hiyyummaan) isa tuqe akkaan abdii murataa, mufataa ta’a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 50, '(namni) Yoo rahmata Nu irraa ta’e isa dhandhamsiifne erga rakkoon isa tuqee booda nijedha “kun anaaf mala; ani Qiyaaman ni dhaabbatti jedhee hin yaadu; yoon gara Gooftaa kiyyaa deebifames, Isa bira gaariitu naaf jira” (jedha). Dhugumatti, warra kafaran waan isaan hojjatan isaanitti odeessina, adabbii ulfaataa isaan dhandamsiisiifna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 51, 'Yeroo Nuti nama irratti tola oolle, (galatoomfachurraa) gara gala cinaacha isaatiin fagaata. Yeroo hamtuun isa tuqe yeruma san abbaa kadhaa hedduu ta’a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 52, 'Jedhi: “Mee naaf himaa! Yoo (Qur’aanni) Rabbi biraa ta’ee, ergasii isin isatti kafartan? Nama isa mormii fagoo ta’e keessa jiru caalaa jallaan eenyu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 53, 'Nuti mallattoowwan keenya moggaa (samii)fi lubbuu isaanii keessatti isaan agarsiifna Dhugaa ta’uun isaa (Qur’aanaa) hanga isaaniif ifa ta’utti. Inni waan hunda irratti to’ataa ta’uun Gooftaa keetiif hin ga’uu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 54, 'Mee dhagayaa! isaan (kun) Gooftaa isaanii qunnamuu irraa mamii keessa jiru. Dhaga’aa! Inni waan hundaan marsee jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 1, 'Haa Miim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 2, 'Ayn Siin Qaaf.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 3, 'Akka kanaan gara keetiifi gara isaan siin duraa wahyii godha Rabbiin injifataa ogeessa ta’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 4, 'Wanti samiileefi wanti dachii keessaa hundi kan Isaati. Inni ol ta’aa, guddaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 5, 'Samiileen (torban) wal gubbaa baqaquutti dhihaatti. Maleeykonni faaruu Gooftaa isaaniitiin Isa qulqulleessu. warra dachii keessa jiruufis araarama kadhatu. Dhaga’aa! Rabbiin Isumatu araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 6, 'Warri Isaan alatti jaalallee godhatan, Rabbiin isaan to’ata. Ati isaan irratti itti gaafatamaa miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 7, 'Akka kanatti Qur’aana Afaan Arabaa gara keetti beeksisa goone Akka (warra) haadhoo magaalaa (Makkaa) fi waarra moggaa ishee sodaachiftuuf, guyyaa wal ga’ii kan shakkii hin qabnes akka dinniintuuf. Gariin jannata keessa (seenu); gariin immoo ibidda keessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 8, 'Rabbiin odoo fedhee ummata tokko isaan taasisa; garuu nama fedhe rahmata Isaa keessa galcha. Miidhaa raawwattoota jaalallees ta’ee tumsaan isaaniif hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 9, 'Moo Isaan ala gargaaraawwan taasifatu? Rabbiin Isumatu gargaaraadha. Isumatu du’aa jiraachisa. Inni waan hunda irratti danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 10, 'Wanti isin irratti wal dhabdan hunduu murtiin isaa garuma Rabbiiti. Inni sun Allaahdha Gooftaa kiyya; Isa irratti irkadhe; garuma Isaattin deebi’a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 11, '(Inni) uumaa samiifi dachiiti. Lubbuulee teessan irraa qindiiwwaa (haadholee manaa) isiniif godhe; beyladoota irraas cimdii (kormaafi dhalaa isiniif taasise). kanaan isin baay’isa. Fakkaataan Isaa (Allaah) hin jiru. Inni dhaga’aa, argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 12, 'Furtuuleen samiileefi dachii isaaf taate. Nama fedheef hiree bal’isa; (kan fedhe immoo itti) dhiphisa. Inni waan hunda beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 13, 'Amantii irraa karaa isiniif godhe waan Nuuhiif dhaameefi isa gara keetti wahyii goone, waan Ibraahiimiif dhaamne, Muusaafi Iisaaf (dhaamne). [Inni] amantii sirriitti hojjadhaa, isa keessattiis addaan hin babahinaa (jechuudha). Wanti ati itti waamtu mushrikoota irratti guddateera! Rabbiin nama fedhe gara isaatti filata; nama tawbabate gara Isaatti qajeelcha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 14, 'Erga beekumsi isaanitti dhufee booda sababaa jibbaa gidduu isaanii jiruuf malee adda hin babaane. Odoo jechi Gooftaa kee biraa hanga yeroo beekamaatti dabre jiraachuu baatee, silaa gidduu isaaniitti murtaa’a ture. Warri isaan booda kitaaba dhaalchifaman isa irraa shakkii cimaa keessa jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 15, 'Kanaafuu (tokkummaa) (sanatti) waami, Akkuma ajajamtetti (haqa irratti) gadi dhaabbadhu. Fedhiilee isaanii hin hordofin “Kitaaba irraa waan Rabbiin buusetti amaneera jedhi; gidduu keessanitti haqa murteessuus ajajameera. Allaahn Gooftaa keenyaafi Gooftaa keessani. Nuuf hojiilee keenyatu jira; Isiniifis hojiilee keessantu jira. Gidduu keenyaafi keessanitti mormiin hin jiru. Rabbiin (Guyyaa Qiyaamaa) gidduu keenya walitti qaba. Deebiin garuma Isaatti” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 16, 'Warri (diin) Rabbii keessatti falman erga Isaaf (Rabbiif) owwaatamee booda, ragaan isaanii Gooftaa isaanii biratti kuftuudha. Dallansuun (Rabbii) isaan irratti tahaadha; adabbiin cimaanis isaaniif jira', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 17, 'Rabbiin Isa kitaabaafi madaala haqaan buuseedha. Qiyaaman dhihoo ta’uun ni kajeelamaa maaltu si beeksise?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 18, 'Isaan isheetti hin amanin ishee jarjarfatu. Isaan amanan (garuu) ishee irraa sodaatu; haqa ta’uu ishees ni beeku. Dhagayaa! Isaan Qiyaamaa keessatti falmanu jallina fagoo keessa jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 19, 'Rabbiin gabroota Isaatiif akkaan rahmata godhaNama fedhes ni sooraInni jabaa injifataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 20, 'Nama mindaa Aakhiraa fedha ta’e mindaa isaa keessatti isaaf daballa. Nama mindaa addunyaa fedha ta’es ishee irraa isaaf kennina. Aakhiraatti immoo qoodni isaaf hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 21, 'Sila shariikota amantii irraa waan Rabbiin isa hin hayyamin karaa isaaniif godhantu jiraa? Odoo jechi murtiin (Guyyaa Qiyaamaati jedhu) jiraachuu baatee gidduu isaaniitti ni murteeffama ture. Miidhaa hojjattoonni, isaaniif adabbii laalessaatu jira', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 22, 'Miidhaa raawwattoota waan hojjatan irraa odoma isaanitti bu’uu taa’uu kan sodaatan ta’uu argita. Isaan amananii, toltuuwwan hojjatan immoo caffeewwan jannataa keessa jiraatu; isaaniif Gooftaa isaanii bira waan fedhantu jiraKun isumatu tola guddaadha', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 23, 'Kun isa Rabbiin gabroota Isaa isaan amananii, toltuu hojjatan ittiin gammachiisuudha“Isa (Qur’aana) irratti jaalala firummaa malee mindaa isin hin gaafadhu
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 24, 'Moo Rabbi irratti soba uume jedhuu? Rabbiin yoo fedhe onnee kee irratti cufa. Rabbiin dhara haqee haqa jecha Isaatiin mirkaneessa. Inni waan qoma keessa jiru beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 25, 'Inni Isa gabroota Isaa irraa tawbaa qeebalu; Kan hamtuuwwan irra dabruufi kan waan isin dalagdan beekuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 26, 'Isaan amananii toltuuwwan dalaganiif ni owwaata. Tola Isaa irraas isaaniif dabala. Kaafiroonni isaaniif adabbii cimaatu jira', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 27, 'Rabbiin gabroota Isaatiif kennaa odoo bal’isee, silaa dachii keessatti daangaa dabru turan. Garuu waan fedhe likkiin buusa. Inni gabroota Isaa keessa beekaa, argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 28, 'Inni Isa erga abdii kutatanii, bokkaa buusuufi rahmata Isaa babal’isuudha. Inni gargaaraa, faarfamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 29, 'Mallattooleewwan isaa irraayyi, Samiilee dechiifi lubbu qabeeyyii isaan lamaan keessa facaase uumuun. yeroo fedhetti walitti isaan qabuu irratti danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 30, 'Hamtuu irraa wanti isin tuqe waanuma harki keessan hojjatteefi; baay’ee irraa dhiifama godha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 31, 'Isinis dachii keessatti Rabbi duraa bahoo miti. Rabbiin ala jaalalleefi tumsaanis isiniif hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 32, 'Mallattoolee isaa irraayi Dooniiwwan akka tabbaa kan galaana keessa yaa’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 33, 'Yoo fedhe qilleensa cal’isiiseeti dugda isaa irra tattaa’oo ta’u turan. Kana keessa warra akkaan obsanii, galatoomfatan hundaaf mallattooleetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 34, 'Yookiin waan isaan hojjataniin isaan balleessa; baay’ee irraa dhiifama godha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 35, 'Akka beekaniif Isaan keeyyattoota keenya keessatti falman bakki itti goran isaaniif hinjiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 36, 'Wahirraa wanti isin kennamtan kamiyyuu qananii jireenya addunyaati. Waan Rabbiin bira jiruutu caalaafi hafaadha isaan amananii, Gooftaa isaanii irratti hirkataniif .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 37, 'Isaan warra dilii gurguddaafi gochaalee fokkatoos irraa fagaatanii, yeroo dallananis dhiifama godhaniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 38, 'Isaan warra Gooftaa isaaniitiif owwaatanii, salaataas sirnaan sagadanii, kan dhimmi isaanii jidduu isaaniitti wal marii ta’ee, waan nuti isaaniif kennine irraa arjoomaniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 39, 'Isaan warra yeroo miidhaan isaan qunname (haqaan) haaloo bahataniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 40, 'Galanni hamtuu hamtuma akka isheeti. Namni dhiifama godhee, (hariiroos) tolche galanni isaa Rabbi irra jira. Inni (Allaahn) miidhaa hojjattoota hin jaallatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 41, 'Namni erga miidhamee booda haaloo bahate, isaan sun diliin isaan irra hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 42, 'Komiin kan jiru isaan namoota miidhanii, haqaan ala dachii keessatti daangaa dabran irratti. Isaan sun adabbii laalessaatu isaaniif jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 43, 'Namni obsee irra dabre, sun dhimmoota gurguddoo irraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 44, 'Nama Rabbiin jallise, Isa booda qajeelchaan isaaf hin jiru. Miidhaa raawwattoota, yeroo adabbii argan (gaabbanii) kan “karaan (gara dachii) ittiin deebi’amu jiraa?” jedhan argita.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 45, 'Ishee (jahannam) irra kan fidaman isaan argita Salphina irraa sodaan guutamanii ija laafaan ilaalaa. Isaan amanan nijedhan “hoonga’oonni isaan Guyyaa Qiyaamaa lubbuu isaaniitiifi maatiilee isaanii hoonga’aniidha” jedhu. Dhagayaa! Miidhaa hojjattoonni adabbii yeroo hundaa keessa jiraatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 46, 'Gargaartonni kamiyyuu kan Rabbiin ala isaaniif tumsan isaaniif hin jiru. Nama Rabbiin isa jallise karaan (ittiin qajeelu) isaaf hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 47, 'Rabbii keessaniif owwaadhaa Guyyaan namni isa deebisuu danda’u hin jirre sun Rabbi irraa odoo isinitti hin dhufin dura. Guyyaa san hirkoon homaatuu isiniif hin jiru. Mormiinis isiniif hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 48, 'Yoo (dhugaa irraa) garagalan, tiksaa goonee isaan irratti si hin ergine. Ergaa geessuu malee homaa sirra hinjiru. Nuti yeroo nama rahmata Nu biraa ta’e dhandhamsiifne, isheetti gammada. Yoo hamtuun waan harkoowwan isaanii hojjatteef isaan tuqxe (abdii muratan), namni akkaan kafaraadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 49, 'Mootummaan samiileefi dachii kan Rabbiiti. Waan fedhe uuma. Nama fedheef dubara kenna; nama fedheef immoo dhiirota kenna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 50, 'Yookiin dhiiraafi dubara makaa kenna. Nama fedhe immoo maseena godha. Inni beekaa, danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 51, 'Namaaf hintaane Rabbiin isa dubbisuun yoo wahyiin tahe malee, yookiin dahoo duubaan, yookiin ergamaa ergee hayyama Isaatiin waan fedhe itti buusuun malee. Inni ol aanaa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 52, 'Akkuma kana (Qur’aana) ruuhii ajaja keenya irraa ta’e gara keetti wahyii goone. Kitaabaafi iimaanni maal akka ta’an kan beektu hin turre. Garuu ifaa gabroota keenya irraa nama feene ittiin qajeelchinu isa goone. Ati gara karaa qajeelaatti ni qajeelchita.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 53, 'Karaa Rabbii wanti samiilee keessa jiruufi wanti dachii keessa jiru hundi kan Isaa ta’ee (ni qajeelchita). Dhagayaa! Dhimmi hundi garuma Rabbiitti deebi’a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 1, 'Haa Miim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 2, 'Kitaaba addeessaa ta’eenin kakadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 3, 'Nuti Qur’aana Arabiffaa isa taasifne Akka isin hubattaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 4, 'Inni haadha kitaabaa Nu bira jiru keessatti tahaadha, ol aanaa ogummaan guutameedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 5, 'Sila gorsa isin irraa dabsinaa Ummata daangaa dabritoota waan taataniif?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 6, 'Nabiyyoota meeqaatama erginee jirra Warra duraa keessatti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 7, 'Nabiyyiin tokkollee isaanitti dhufee yoo isatti qishinan (baacan) malee hin hafne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 8, 'Humnaan isaan irra cimoo warra ta’an balleessinee jirra. Fakkeenyi warra jalqabaa dabreera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 9, 'Odoo samiileefi dachii eenyutu uume jettee isaan gaafattee “Isa injifataa beekaa ta’etu isaan uume” jedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 10, '(Rabbiin) Isa dachii afaa isiniif godhee, ishee keessattis akka qajeeltaniif karaalee isiniif godhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 11, 'Ammas (Rabbiin) Isa samii irraa bishaan madaalaan buusee, dachii duutuu isaan jiraachifne. Akkuma kana baafamtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 12, 'Isa cimdii hunda uumee, dooniileefi beyladoota irraa waan yaabbattan isiniif godhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 13, 'Akka dugda isaanii irratti baatanii, ergasii ni’imaa Gooftaa keessanii yeroo (duuyda) isaarratti (geejjibaarratti) ol baatan yaadattanii “Inni kana nuuf laaffise qulqullaa’e; nuti isa danda’oo hin turre” jettaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 14, 'Nuti gara Gooftaa keenyaa deebi’oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 15, 'Gabroota Isaa irraa qooda Isaaf taasisani. Namni dhugumatti kafraa ifa bahaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 16, 'Sila waan uumu irraa ilmaan dubaraa (ofiif) taasifatee, isin immoo ilmaan dhiiraatiin isin filee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 17, 'Yeroo tokkoon isaanii waan “Rahmaaniif” fakkeenya taasiseen gammachiifame, fuulli isaa gurraacha ta’a dallansuun guutamaa tahee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 18, 'Nama faaya (miidhaginaa) keessatti guddifamu, kan falmii keessatti hinibsine (godhatee)?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 19, 'Maleeykota isaan gabroota Rahmaan ta’an dubara taasisan. uumama isaanii bira jiran moo? Ragaan isaanii fuuldura nibarreeffamti, nigaafataman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 20, '“Odoo Rahmaan fedhee isaan hin gabbarru turre” jedhan. sana irratti beekumsa homaatuu hin qaban isaan kijiboo malee hintaane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 21, 'Moo (Qur’aana) kana dura kitaaba isaaniif kennine, kan isaan isa qabatoo tahan?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 22, 'Lakkii! Isaan “nuti abboota keenya amantii wahii irratti argine, nutis faanoowwan isaanii irra qajeeloodha” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 23, 'Akkasumas (Yaa Muhammad!) siin dura magaalaa kam keessattuu sodaachisaa erginee, qanani’oon ishee “Nuti abbootii keenya amantii wahii irratti argine; nuti faanuma isaanii irra hordoftoota” jedhan malee hin hafne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 24, '(Ergamichis) “odoo ani waan abbootii keessan irratti argitan irra qajeelaatiin isinitti dhufeelleemoo (isaanuma hordoftuu)?” jedhe. (Mushrikoonnis) “nuti waan isin ittiin ergamtanitti kafaroodha” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 25, 'Kanaafuu isaan irraa haaloo ba’anne. Booddeen sobsiiftotaa akkam akka ta’e ilaali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 26, 'Yeroo Ibraahiim abbaa isaatiifi ummata isaatiin jedhe [yaadadhu] :“Dhugumatti ani waan isin gabbartan irraa qulqulluudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 27, 'Isa na uume malee. Inni na qajeelcha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 28, 'Jechattii isa booda haftuu ishee godhe Akka isaan deebi’aniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 29, 'Dhugumatti, isaan kanaafi abbootii isaaniis qanansiise hanga dhugaafi ergamaan ifa baasaan isaanitti dhufutti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 30, 'Dhugaan isaanitti dhufnaan immoo “kuni falfala; nuti isatti kafaroodha” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 31, 'Ni jedhan: “Qur’aanni kun nama guddaa ganda lamaan irraa ta’etti maaliif buufamuu dhabe?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 32, 'Sila isaantu Rahmata Gooftaa keetii qoodaa? Nutu jiruu addunyaa keessatti waan ittiin jiraatan gidduu isaaniitti qoode.garii isaanii garii irra sadarkaaleen ol fuune Akka gariin isaanii garii tajaajilaa godhatuuf jecha. Rahmata Gooftaa keetiitu waan isaan walitti qaban irra caala.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 33, 'Odoo namni (gara addunyaa jallachuun) ummata tokko ta’uu baatee, silaa namoota Rahmaanitti kafaraniif ijoo manneen isaanii meeta irraa taasifna turre. sadarkaawwan irrattii ol ba’anis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 34, 'Manneen isaaniitiifis hulaaleefi sireewwan irratti hirkatanis (meeta irraa isaaniif goona turre).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 35, 'Faayaas (ni goonaaf) Kun hunduu qananii jiruu addunyaa qofa. Aakhiraan Gooftaa kee biratti warra Rabbiin sodaataniifi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 36, 'Nama gorsa (Qur’aana) Rahmaan irraa gara gale, sheeyxaana isaaf ramadna; inni isaaf hiriyaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 37, 'Isaanis karaa (Rabbii) irraa isaan dhorgu; isaan immoo qajeeloo uf sehan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 38, 'Hanga nutti dhufee “yaa gaabbii kiyya! Odoo gidduu kiyyaafi gidduu kee fageenyi baha lamaanii (bahaafi dhihaa) jiraatee” jedha. Hiriyichi waa fokkate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 39, 'Har’a isin hin fayyadu waan lubbuu keessan miitaniif, ibidda keessatti waliin jiraachuun keessan (homaa isin hinfayyadu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 40, 'Sila ati duudaa dhageessiftaa yookiin jaamaa qajeelchitaa, nama jallina ifa ta’e keessa jiru(s niqajeelchitaa)?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 41, '(Yaa Muhammad!) yoo si deemsifnellee, Nuti isaan irraa haaloo bahatoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 42, 'Yookiin isa waadaa isaaniif galle yoo sitti agarsiifne, Nuti isaan irratti danda’oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 43, 'Isa gara keetti wahyii godhame san qabadhu. Ati karaa qajeelaa irra jirta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 44, 'Inni (Qur’aanni) siifi ummata keetiifis gorsa. Fuula dura ni gaafatamtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 45, 'Ergamtoota keenya irraa nama si dura ergine gaafadhu “Sila Rahmaan malee gooftolii gabbaraman taasifnee jirraa?”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 46, 'Dhugumatti, Muusaa raajiiwwan keenyaan gara Fir’awniifi qoondaaltota isaatti erginee, “ani ergamaa Gooftaa aalama hundaati” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 47, 'Yeroo raajiiwwan keenyaan isaanitti dhufu, isaan yeroo san isheetti kolfu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 48, 'Raajii irraa ishee obboleettii ishee irra caaltu malee isaan hin agarsiifnu. Akka isaan (gara keenya) deebi’aniif adabaan isaan qabne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 49, '“Ati yaa kan sihrii hojjattu! Gooftaa kee waan waadaa siif galeen nuuf kadhu. Nuti ni qajeella” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 50, 'Yeroo adabbii isaan irraa saaqnu yoggusuma isaan waadaa diigan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 51, 'Fir’awnis ummata isaa keessatti lallabee, “yaa ummata kiyya! sila mootummaan Misraa anaaf hin turree? Laggeen kunis ana jala hin yaatuu? Sila hin agartanuu?” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 52, '“Isa laafaa (tuffatamaa), dubbii adda baasuutti hindhihaanne kana irra anatu caala.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 53, '(Yoo akkas ta’e) maaliif gumeewwan warqee (dahaba) irraa hojjataman isa irratti hin buufamne? Yookiin maleykonni isa wajjin qindaawanii maaliif hin dhufne?” (jedhe).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 54, 'Ummata isaa gowwoomse ajaja isaa fudhatan. Isaan ummata fincilaa turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 55, 'Yeroo isaan Nu dallansiisan, haaloo isaanitti baanee, hunda isaaniituu dhidhimsiifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 56, 'Dhaloota boodaatiif hangafaafi fakkeenya isaan taasifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 57, 'Yeroo ilmi Maryam (Iisaan) fakkeenya godhamu ummanni kee (kaafiroonni) isarraa kolfu (gammadu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 58, '“Gooftolee keenya moo isatu caala?” jedhan. Waan kana falmiif malee siif hin godhanu. Dhugumatti, isaan ummata mormitoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 59, 'Inni (Iisaan) gabricha Nuti isa irratti tola oollee malee waan biraa miti, Ilmaan Israa’iliif fakkeenya isa taasifne .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 60, 'Odoo feenee maleeykota isin irraa bakka bu’an dachii keessa goona turre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 61, 'Inni Qiyaamaaf mallattoo dhaa, ishee hin shakkinaa; ana hordofaa. Kanatu karaa qajeelaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 62, 'Sheyxaanni (dhugaa hordofuu irraa) akka isin hin dhorgine. Inni isiniif diina ifa ba’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 63, 'Iisaan yeroo ragaalee ifa ta’aniin dhufe, ni jedhe: “Dhugumatti, ani beekumsaanin isinitti dhufe; ammaas akkan garii waan isin keessatti wal dhabdanii isiniif ibsuufin (dhufe.) Rabbiin sodaa dhaa; anaafis ajajamaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 64, 'Allaahn Isumatu Gooftaa kiyyaafi Gooftaa keessani. Isa (qofa) gabbaraa; kanatu karaa qajeelaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 65, 'Gareewwan gidduu isaaniitti (dhimma kana irratti) wal dhabaniiru. Isaan miidhaa dalaganiif adabbii guyyaa laalessaa irraa halaakni isaaniif tahe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 66, 'Sila ni eeganii Qiyaamaa malee daguudhaan isaanitti dhufuu isaanii hinbeeynee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 67, 'Jaalalleewwan guyyaa san gariin isaanii gariif diina isaan Rabbiin sodaatan malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 68, 'Yaa gabroota kiyya! Har’a sodaan isin irra hin jiru; isin hin gadditanus.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 69, 'Isaan keeyyattoota keenyatti amananii, Muslimoota ta’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 70, 'Isiniifi jaartiiwwan teessanis gammadaa jannata seenaa” (isaaniin jedhama).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 71, 'Qoriiwwan warqee irraa ta’aniifi kubbaayyaaleen isaan irra naanna’ama. Ishee keessas waan lubbuuleen feetuufi ijoowwan itti gammaddutu jira. Isin ishee (jannata) keessatti hafoodha” (jedhamaani).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 72, 'Jannatni sun ta ishee dhalchifamtani waan hojjachaa turtaniini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 73, 'Isiniif ishee keessa fuduraalee baay’eetu jira. ishee irraa nyaattan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 74, 'Yakkamtoonni adabbii jahannam keessatti hafu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 75, '(Adabichi) Isaan irraa hin salphifamu; isaanis isa keessatti abdii muratoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 76, 'Nuti isaan hin miine; garuu isaan (ofumaaf) miidhaa hojjattoota ta’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 77, '(Waardiyaa ibiddaatiin) “yaa Maalik! Gooftaan kee haa nufixu (nuuf gaafadhuu)” (jedhanii) lallabu. (Maalikis) “isin ishee keessa turoodha” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 78, 'Dhugumatti, Nuti haqaan isinitti dhufne. Garuu irra baay’een keessan haqa jibbitoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 79, 'Moo Tooftaa baasanii?, nutis tooftaa itti baafne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 80, 'Moo Nuti iccitii isaaniitiifi maqoo isaanii hin dhageenyu sehanii? Lakkisaa! (ni dhageenya); ergamtoonni keenyas isaan biraa barreessu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 81, '(Yaa Muhammad!) jedhi: “yoo Rahmaaniif ilmi jiraatee, silaa anatu jalqaba warra (isa)(ilma san) gabbaraniiti.” [1]', '[1] garuu Rabbiin ilma hinqabu, kanarraa qulqullaawwe.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 82, 'Rabbiin samiileefi dachii, Gooftaan arshii waan isaan ittiin (Isa) wassafan (ibsan) irraa qulqullaa’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 83, 'Isaan dhiisi (dhara keessa) seenanii haa taphatanii Hanga guyyaa isaanii, isa waadaa galaman qunnamanitti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 84, 'Inni Isa samii keessatti gabbaramaa, dachii keessattis gabbaramaati. Inni ogeessa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 85, 'Inni mootummaan samiilee, dachiifi waan isaan lamaan gidduu kan Isaa ta’e toltuun isaa baay''ate. beekumsi Qiyaamaas Isa biratti tahe, gara Isaatti deebifamtan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 86, 'Manguddummaa seenuu hin danda’anu Warri Rabbii gaditti waammatan, namoota dhugaa beekanii ragaa bahan malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 87, 'Eenyuutu isaan uumee odoo isaan gaafattee “Allaahdha” jedhu. Akkamumatti irraa garagalfamuree?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 88, 'Jechi inni (nabi Muhammad SAW!) “yaa Gooftaa kiyya! Dhugumatti, isaan kun ummata hin amanne” jedhe (sunis Allaah bira jira).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 89, '(Yaa Muhammad!) isaan irraa gara galii “nagaan (isin irra haa jiraatu)” jedhiin; (waan isaan mudatu) fuula dura beekuuf jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 1, 'Haa Miim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 2, 'Kitaaba addeessaa ta’eenin (kakadha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 3, 'Nuti halkan barakeeffamtuu keessa isa buufne. Nuti dinniinoo taaneerra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 4, 'Ishee (halkanittii) keessa dhimmi murteeffame hundi adda baafama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 5, 'Ajaja nu biraa ta’e (ibsina) Nuti ergitoota taaneerra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 6, 'Rahmata Gooftaa kee irraa ta’eef (buufne). Inni Isumatu dhaga’aa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 7, '(Rahmata) Gooftaa samiilee, dachiifi waan gidduu isaan lamaanii irraa ta’eeti. Yoo kan dhugoomsitan taataniif (kana hubadhaa).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 8, 'Isa malee dhugaan gabbaramaan hin jiru. Ni jiraachisa; ni ajjeessas. (Inni) Gooftaa keessaniifi Gooftaa abbootii keessan kanneen duraati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 9, 'Dhugumatti isaan shakkii keessa taphatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 10, 'Guyyaa samiin aara ifa ba’aan dhuftu (waan isaan mudatu) eegi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 11, '(Aarri kun) namoota haguuga. Kun adabbii laalessaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 12, '(Kaafiroonni yeroo adabicha argan) “Gooftaa keenya! Adabicha nurraa kaasi nuti ni amannaa” (jedhu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 13, '(erga adabaatii) gorfamuun akkamitti isaaniif jiraata, Odoo ergamaan ifa baasaan isaanitti dhufee jiruu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 14, 'Ergasii isa irraa gara galanii “(Inni) barsiifamaa maraataadha” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 15, 'Nuti yeroo gabaabaaf adabbii saaqoodha; Isin (kufriitti) deebi’oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 16, 'Guyyaa qabaa guddaa qabnu Nuti haaloo bahatoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 17, 'Dhugumatti, Nuti isaan dura ummata Fir’awni mokkorree jirra. Ergamaan kabajamaanis isaanitti dhufe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 18, '“gabroota Rabbii gara kiyya kennaa! Ani isiniif ergamaa amanamaadhaa,” jechuun (isaanitti dhufe).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 19, '“Rabbi irratti hin booninaa; ani ragaa ifa ta’een isinitti dhufaadha” jedheen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 20, '“Ani Gooftaa kiyyaafi Gooftaa keessanittin maganfadhe akka (dhagaan tumtanii nan) ajjeefne', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 21, 'Yoo naaf hin amanne narraa fagaadhaa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 22, 'Gooftaa isaa ni kadhate: “Isaan kun ummata yakkamtoota” (jedhe).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 23, '(Rabbiin ni jedhe): “Gabroota kiyyaan halkaniin deemi. isin hordofamtoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 24, 'Galaana akkuma banametti dhiisi. isaan waraana bishaaniin dhidhimfamoodha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 25, 'Ashaakiltiifi burqituuwwan meeqaatama dhiisan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 26, 'Oyruufi iddoo jireenyaa gaggaariis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 27, 'Qananii ishee keessatti gammadaa turanis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 28, 'Akka kanatti ummata biraa ishee dhaalchifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 29, 'Samiifi dachiin isaan irratti hin boonye; kan tursiifanis hin turre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 30, 'Dhugumatti, Ilmaan Israa’iil adabbii salphisaa irraa nagaya baafne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 31, 'Fir’awni irraa (ni baraarsine). Inni boonaa, daangaa dabritoota irraa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 32, 'Nuti beekumsaan aalama hunda irra isaan filanne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 33, 'Raajiiwwan irraas waan mokkorriin ifa ta’e isa keessa jiru isaaniif kennine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 34, 'Dhugumatti, isaan kun (Qureeyshonni) ni jedhu:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 35, '“isheen tun hintaane Du’a teenya kan jalqabaa malee. Nuti (kana booda) kaafamoo miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 36, 'Yoo warra dhugaa dubbatu taataniif, abbootii keenya fidaa.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 37, 'Sila isaantu caala moo ummata Tubba’iifi warra isaan duraati? isaan balleessine, Isaan yakkamtoota turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 38, 'Samiilee, dachiifi waan isaan lamaan gidduu jirus taphatoo taanee hin uumne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 39, 'Dhugaan malee isaan lachan hin uumne. Garuu irra hedduun isaanii hin beekanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 40, 'Guyyaan murtii beellama isaan hundaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 41, 'Guyyaa jaalalleen jaalallee irraa homaa hin deebifne, kan isaanis (kaafiroonnis) hin tumsamneedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 42, 'Nama Rabbiin rahmata godheef malee. Inni Isumatu injifataa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 43, 'Mukni ‘Zaqquum’', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 44, 'Nyaata dilaawaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 45, 'Akka cumaa (siicoo) zaytiitti garaa keessatti danfa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 46, 'Akka danfuu bishaan ho’aatti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 47, '(Ni jedhama): “Isa qabaatii gara walakkaa ibidda boba’aa harkisaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 48, 'Ergasii mataa isaa gubbaatti adabbii bishaan danfaa irraa ta’e dhangalaasaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 49, 'Dhandhami; ati simatu cimaa, arjaa (of fakkeessuu) turtee!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 50, 'Inni kun waan isa mamaa turtan sani” (isaaniin jedhama).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 51, 'Warri Rabbiin sodaatan iddoo nagayaa keessatti tahu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 52, 'Ashaakiltiifi burqituuwwan keessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 53, 'Walitti gara galoo ta’anii (uffata) hariira haphiifi hariira furdaa irraa ta’e uffatu .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 54, 'Akkuma kana dubra babbareedoo ija babala’aa isaan fuusifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 55, 'Isii keessattis fuduraalee hunda waammatu nagaa tahoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 56, 'Ishee keessatti du’a jalqabaa malee du’a hin dhandhaman. Rabbiin azaaba ibidda boba’aa irraa isaan tikse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 57, 'Tola Gooftaa kee irraa ta’eef, Sun isumatu milkii guddaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 58, 'isa (Qur’aana) afaan keetiin laaffifne Akka gorfamaniif jacha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 59, '(Waan isaan mudatu) eegi; isaanis eegoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 1, 'Haa Miim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 2, 'Buufamiinsi kitaabaa (Qur’aanaa) Rabbii Injifataa, ogeessa ta’e irraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 3, 'Samiileefi dachii keessa Dhugumatti mu’uminootaaf mallattooleetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 4, 'Uumama keessaniifi lubbu qabeeyyii irraa waan Inni (Rabbiin dachii keessa) facaasu keessas namoota dhugaan amananiif raajiiwwantu jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 5, 'Wal dhabuu halkanii, guyyaatiifi اhiree (rooba) irraa waan Rabbiin samirraa (duumeessarraa) buusee, dachii eega du''uu (goggogina) isheetii ittiin jiraachise (magarseefi) qilleensa gara gaggalchuu keessa warra xinxalaniif mallattooleen taatuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 6, '(Yaa Muhammad!) tunniin keeyyattoota Rabbiitii, dhugaan sirratti ishee dubbifna. Sila erga Rabbiifi keeyyattoota Isaatii oduu akkamii amanu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 7, 'Cufa nama akkaan kijibaa, dilaawaa ta’eetiif laga ibiddaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 8, 'Keeyyattoota Rabbii kan isa irratti dubbifaman dhaga’aa; ergasii akka waan ishee hin dhaga’iniitti boona isaa itti fufa. adabbii laalessaan isa gammachiisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 9, 'Yeroo keeyyattoota keenya irraa waa beeke qishina (qoosaa) ishee godhata. Warra san adabbii xiqqeessaa ta’etu isaaniif jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 10, 'Fuuldura isaanii jahannamtu jira. Wanti isaan horatanis ta’ee wanti isaan Rabbiin ala jaalalleewwan godhatanis homaa isaan irraa hin deebisanu. Isaaniif adabbii guddaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 11, '(Qur’aanni) kun qajeelfama. Isaan keeyyattoota Gooftaa isaaniitti kafaran, adabbii gubaa laalessaa irraa ta’etu isaaniif jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 12, 'Rabbiin Isa galaana isiniif laaffise sani akka dooniwwan ajaja Isaatiin isa keessa deemtu, akka tola Isaa irraa barbaaddattaniif, akka Isa galateeffattaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 13, 'Waan samiilee keessa jiruufi waan dachii keessa jiru hunda (laaffisuu) Isa irraa ta’e isiniif laaffise. Kana keessa ummattoota xiinxalaniif mallattooleetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 14, '(Yaa Muhammad!) Warra amananiin, “warra guyyoota Rabbii hin sodaanneef dhiifama godhaa” jedhi. Akka Inni namootaaf waan isaan dalaganiin mindaa kennuuf (dhiifama godhaa).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 15, 'Namni toltuu hojjate lubbuma isaatiifi. Namni badii dalages isheedhuma irratti. Ergasii gara Gooftaa keessanii deebifamtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 16, 'Dhugumatti, ilmaan Israa’iliif kitaaba, seeraafii nabiyyummaas kennineerra. Wantoota gaggaarii irraas isaaniif kenninee, aalama (yeroo isaanii) hunda irras isaan caalchifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 17, 'Shari’aa irraas waan ifa ta’e isaaniif kannine. Erga beekumsi isaanitti dhufee booda malee (waan birootiif) wal hin dhabne, jibbansa gidduu isaanii jiruuf jecha. Dhugumatti, Gooftaan kee Guyyaa Qiyaamaa gidduu isaanitti murteessa waan isaan isa keessatti wal dhabaa turan keessatti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 18, 'Ergasii seera ajaja (keenya) irraa ta’e irra si keenyee, ishee hordofi. Fedhaalee lubbuu warra homaa hin beeknee hin hordofin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 19, 'Isaan homaa (adabbii) Rabbii irraa si hin duroomsan. Miidhaa hojjattoonni gariin isaanii jaalalleewwan gariiti. Rabbiin immoo jaalallee warra Isa sodaataniiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 20, '(Qur’aanni) kun namootaaf beekumsa ifa ba’aadha. Warra dhugoomsaniif qajeelfamaafi rahmata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 21, 'Sila warri hamtuulee hojjatan, akka warra amananii toltuu hojjatanii gochuu keenya yaadanii? jiraa isaaniitiifi du’aa isaaniitis walqixxeessinaa (yaadanii) Wanti isaan murteessan waa fokkate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 22, 'Rabbiin samiileefi dachii haqaan uume, akka lubbuun hundi waan hojjatteen mindeeffamtuuf, Odoo isaan hin miidhamne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 23, 'Sila agartee nama gabbaramaa isaa fedhii isaa godhate, kan Rabbiinisa jallisee beekumsarratti, dhageettii isaatiifi onnee isaa irratti cufee, ija isaa irrattis haguuggaa godhe. Erga Rabbiin (jallisee) booda eenyutu isa qajeelcha? Sila hin gorfamtanuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 24, 'Nijedhan “Jireenya keenya kan addunyaa malee isheen (jiruun biraa) hin jirtu. ni duuna; (gariin keenyas) ni jiraanna, zamana malee wanti nu balleessu hin jiru”. Waan kanatti beekumsa homaatuu isaaniif hintaane. Isaan se’oo malee hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 25, 'Yeroo keeyyattoonni keenya ifa ba’anii isaan irratti dubbifaman, ragaan isaanii waa hintaane “yoo kan dhugaa dubbattan taataniif abbootii keenya fidaa” jechuu malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 26, '(Yaa Muhammad!) Jedhi: “Rabbumatu isin jiraachisee, ergasii isin ajjeesa; ergasii Guyyaa Qiyaamaa keessatti walitti isin qaba. mamiin Isa keessa hin jiru. Garuu irra hedduun namaa hin beekanu.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 27, 'Mootummaan samiifi dachii kan Rabbiiti. Guyyaa Qiyaaman dhaabbattu, guyyaa san warri dharaa ni hoonga’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 28, '(Guyyaa san) ummata hunda jilbiiffatanii argita. Ummanni hunduu gara kitaaba isheetti waamamti. “Har’a waan dalagaa turtan mindeeffamtu” (isaaniin jedhama).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 29, 'Kun kitaaba keenya kan isin irratti dhugaan dubbatuudha. Dhugumatti, Nuti waan isin dalagaa turtan galmeessuu turre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 30, 'Isaan amananii, toltuuwwan dalagan immoo Gooftaan isaanii rahmata Isaa keessa isaan seensisa. Kun isumatu milkii ifa galaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 31, 'Isaan kafaran immoo “sila keeyyatoonni Kiyya isin irratti dubbifamaa hin turree?, boontanii, ummata badoo taatan” (jedhamaan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 32, 'Yeroo “waadaan Rabbii dhugaadha; Qiyaamaan (akka dhuftu) mamiin ishee keessa hin jiru” jedhame, “Qiyaamaan maal akka taate hin beeknu; mamii mamoo malee hintaane. Nuti dhugoomsoo hin taane” jettan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 33, 'Hamtuun waan dalaganii ifa isaaniif bahe; wanti isaan itti qishnaa (qoosaa) turanis isaanitti bu''e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 34, 'Ni jedhamaani: “ Har’a isin daganna (isin dhiifna) akkuma isin qunnamtii guyyaa keessan kanaa dagattanitti; teessoon keessanis ibidda; tumsitoonni isiniif hin jiranu.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 35, 'Kun waan isin keeyyattoota Rabbii qishnaa (qoosaa) taasiiftaniifi, waan jiruun addunyaa isin gowwoomsiteefi, Har’a ishee (ibidda) irraa hin baafamanu; isaan ceephoos hin buufachiifamanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 36, 'Faaruun kan Rabbiiti Gooftaa samiileefi Gooftaa dachii, Gooftaa aalamootaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 37, 'Samiileefi dachii keessatti boonni Isumaafi. Inni injifataa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 1, 'Haa Miim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 2, 'Buufamiinsi kitaabaa (Qur’aanaa) Rabbii injifataa, ogeeysa ta’e irraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 3, 'Samii, dachiifi waan isaan lamaan gidduu jiranis dhugaafi yeroo beekamaa ta’eef malee hin uumne. Isaan kafaran waan ittiin sodaachifaman irraa garagaloodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 4, '(Yaa Muhammad!) jedhi: “wantoota Rabbiin ala gabbartan naaf himaa? Dachii irraa waan isaan uuman natti agarsiisaa. Moo samiilee keessatti shariikummaan isaaniif jira? mee kitaaba (Qur’aana) kana dura (bu’e) yookiin hambaa beekumsa durii wahii naaf dhiyeessaa Yoo dhugaa dubbattoota taataniif.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 5, 'Nama Rabbiin ala waan hanga Guyyaa Qiyaamaatti homaa isaaf hin owwaanneefi [1] isaan kadhaa isaanii irraa dagatoo ta’an gabbaru caalaa jallataan eenyu?', '[1] hiikkaan kanaa homa gonkumaa isaaniif awwaachuu hin dandayan jechuudha.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 6, 'Yeroo ilmi namaa walitti qabamu diinota isaaniif ta’u. Ibaadaa isaaniittis kafaroo ta’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 7, 'Yeroo keeyyatoonni keenya ifa ta’anii isaan irratti dubbifaman, isaan kafaran dhugaan nijedhan yeroo isaanitti dhufe “kun Sihrii ifa galaadha”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 8, 'Moo “(Muhammadtu SAW) sobaan isa uume” jedhu? (Yaa Muhammad!) jedhi “yoo ani sobaan isa uume (adabbii) Rabbii irraa homaa naaf tumsuu hin dandeessanu. Inni (Rabbiin) waan isin keessa galtan beekaadha. Anaafi isin giddutti ragaaf Inni ga’aadha. Inni araaramaa, rahmata godhaadha”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 9, '(Yaa Muhammad!) jedhi: “Ani ergamtoota irraa isa jalaqabaatii (kan fakkii hinqabnee) miti. Waan anaafi isin irratti dalagamuuf jiru hin beeku. Waan gara kiyyatti wahyii godhamu malee (wanta biraa) hin hordofu. Ani sodaachisaa ifa bahaadha malee waan biraatii miti.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 10, 'Jedhi “Mee naaf himaa! Yoo (Qur’aanni kun) Rabbi biraa ta’ee itti kafartan, raga bahaan Ilmaan Israa’ilii irraa ta’e fakkaataa isaa irratti ragaa bahee, yoo amanee isin immoo boontan, (isin miidhaa hin hojjannee)? Rabbiin miidhaa raawwattoota hin qajeelchu”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 11, 'Isaan kafaran isaan amananiin ni jedhu: “Odoo inni (Qur’aanni) waan gaarii ta’ee silaa gara isaatti nu hin dursanu ture.” Isaan eega hin qajeelinii “kun dhara duriiti” jechuuf jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 12, 'Isa (Qur’aana) duras kitaaba Muusaa kan qajeelfamaafi rahmata ta’etu (ture). Kuni kitaaba dhugoomsaa, Afaan Arabaatiin (bu’ee) dha. akka warra miidhaa hojjatan sodaachisee, toltuu hojjattoota immoo gammachiisuuf.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 13, 'Isaan “Gooftaan keenya Allaahdha” jedhanii ergasii (sana irratti) gadi dhaabbatan, sodaan isaan irra hin jiru; isaan hin gaddanis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 14, 'Isaan sun warra jannataati; ishee keessa yeroo hunda jiraatu; mindaa waan dalagaa turaniif (isaanif kenname).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 15, 'Namaaf abbaafi haadha isaatti tola ooluu dhaamne. Haati isaa rakkoon isa baadhattee (ulfooftee), rakkoon isa deesse, Ulfaafi harma gu’uun isaa ji’oota soddoma; hanga jabina isaa ga’ee, waggaa afurtama ga’u nijedhe “Gooftaa kiyya! Ani ni’imaa kee kan Ati ana, haadhaafi abbaa kiyya irratti oolte galateeffachuufi dalagaa gaarii Ati jaallattu hojjachuu na qabsiisi. Sanyii (hortee) kiyyas gaarii taasisi. Ani gara kee tawbaa deebi’eera. Ani Muslimtoota irraayi” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 16, 'Isaan sun warra irra gaggaarii wantoota isaan dalaganii nuti irraa qeeballee, hamtuu isaanii dhiifama goonufi. (Fuula duras) namoota Jannataa keessatti ta’u. (Kun) waadaa dhugaa kan isaaniif galamaa ture.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 17, 'Inni abbaafi haadha isaatiin “isin lachaniifuu ish (uffi)! akka ani kaafamu natti himtuu Kanuma dhaloonni baay’een naan dura dabrtee jirtu, ?” jedhe. Haala isaan lamaan birmachuu Rabbii gaafachaa, “yaa badii kee!amani Beellamni Rabbii dhugaadhaa” (jedhanii gorsanuu) “kun ogbarruu warra duriiti malee waa biraa miti” jedha;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 18, 'Isaan sun warra jechi (adabbii) isaan irratti mirkanaa’eedha, ummattoota isaan dura dabran kan jinnootaafi namoota irraa ta’an keessatti. Isaan hoonga’oota ta’aniiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 19, 'Hundaafuu sadarkaatu jira waan dalagan irraa, hojii isaanii isaanii guutuuf (mindeessa) isaan hin miidhaman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 20, 'Guyyaa isaan kafaran ibidda irra fidaman: “(wantoota) gaggaarii keessan jireenya keessan kan addunyaa keessatti dabarfattan. isitti qananiitan. Har’a adabbii salphisaa mindeeffamtu waan dachii keessatti dhugaan ala boonaa turtaniifi waan fincilaa turtaniif jecha (isaaniin jedhama).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 21, 'obboleessa Aad (Huud) yaadadhu, yeroo Ahqaafitti ummata isaa dinniine. Isa duraafi isa boodas sodaachiftoonni dabartee turte. “Allaah malee waan biraa hin gabbarinaa; ani adabbii guyyaa guddaan isin irratti sodaadha” (jechuun).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 22, '(Ummanni isaas) ni jedhan: “Sila ati gooftolii keenya irraa akka gara nu galchituuf nutti dhuftee? waan nuun sodaachiftuun nutti koottu Yoo warra dhugaa dubbatan irraa taateef.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 23, '(Huud) ni jedhe: “Beekumsi (adabbittii) Allaah bira jira. Ani waanuman ittiin ergame qofan isinitti geessa. Garuu ani ummata wollaaloo ta’uun isin arga.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 24, 'Yeroo isa (adabicha) (duumessa fakkaatee) gara laggeen isaanii garagalee dhufaa ta’uu argan: “kun duumessa nuuf roobu” jedhan. “Lakkisaa! Inni waan isa jarjarfachaa turtan sanii; bubbee adabbiin laalessaan isa keessa jiruudha” (jedhaman).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 25, 'Waan hunda ajaja Rabbii isheetiin balleessiti. Manneen isaanii malee wanti tokkos kan hin mul’anne ta’an. Akka kanatti namoota badii hojjatan mindeessina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 26, '(Yaa Qureyshotaa!) dhugumatti, Nuti waan isiniif hin mijeessin isaaniif mijeessinee turre. Dhageettii, agartuuleefi qalbiilees isaaniif goonee. Dhageettiin, agartuuleefi qalbiileen isaanii homaa isaan irraa hin deebifne. waan aayatoota keenya mormaa turaniif. Wanti isaan qishnaa itti godhaa turan isaanitti qubate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 27, 'Dhugumatti, magaalota (ummatoota) moggaa keessan jiran gidduu (heddu) balleessinee jirra. Mallattoolee (keenyas) karaa adda addaatiin isaan argisiifne akka isaan deebi''aniif..', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 28, 'Maaliif wantoonni isaan akka Rabbiitti isaan dhiheessituuf gabbaramoo godhatan isaan hin tumsin? Lakkisaa! (yeroo san) gonkumaa isaan irraa fagaatan. Kun kijiba isaanitiifi waan isaan sobaan haasa’aa turaniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 29, '(Yaa Muhammad!) Yeroo garee jinnoota irraa ta’e gara keetti garagalchine [yaadadhu] kan Qur’aana dhageeffatan ta’anii, Yeroo isa bira dhufan “cal’isaa (dhageeffadhaa)” (waliin) jedhan. Yeroo inni xumuramu immoo dinniintota ta’anii gara ummattoota isaanii deebi’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 30, 'Ni jedhan: “Yaa ummata keenya! Nuti kitaaba Muusaa booda bu’e dhageenyee jirra, kan waan isa duraa dhugoomsaa ta’e, kan gara dhugaafi gara karaa sirrii qajeelchu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 31, 'Yaa ummata keenya! Waamaa Rabbii (nabi Muhammadiin) tole jedhaa; isattis amanaa. Inni (Rabbiin) badiilee keessan irraa isiniif araarama; adabbii laalessaa irraas isin baraara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 32, 'Namni waamaa Rabbii tole hin jenne, dachii keessatti dadhabsiisaa miti; isaan (Allaahn) alas gargaaraan biraa isaaf hin jiru. Warri sun jallina ifa ta’e keessa jiru.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 33, 'Sila Rabbiin, Isa samiileefi dachii uumee, isaan uumuu keessatti dadhabbiin itti hin dhaga’amin, du’aa kaasuu irratti danda’aa akka ta’e hin arginee? Eeyyeen; Inni waan hunda irratti danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 34, 'Guyyaa isaan kafaran ibidda irratti fidaman “sila kun dhugaa mitii?” (isaanin jedhama). Isaanis “Eeyyeen; Gooftaa keenyatti kakannee! (Dhugaa dha)” jedhu. Innis “Waan (Rabbitti) kafaraa turtaniif adabbii kana dhandhamaa” (isaaniin) jedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 35, '(Yaa Muhammad!) Akkuma ergamtoota irraa warri murannoo obsetti, obsi. Isaanitti hin ariifatin. Guyyaa waan waadaa isaaniif galame argan akka waan guyyaa irraa sa’aatii tokko malee hin jiraatiniitti of lakkaa’u. (Qur’aanni) (ergaa) ga’aadha. Sila finciltoota malee namni biraa ni badaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 1, 'Warra kafaranii, karaa Rabbii irraa [namoota] deebisan [Rabbiin] hojiiwwan isaanii balleesseera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 2, 'Warra amananii, dalagaa gaggaarii hojjatanii, waan Muhammad irratti buufametti amanan, ‘inni dhugaa Gooftaa isaanii irraa ta’e’ , (Rabbiin) diliilee isaanii isaan irraa haqe, haala isaaniis tolche.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 3, 'Kun waan warri kafaran dhara (bu’ura hin qabne) hordofaniifi, warri amanan immoo dhugaa Gooftaa isaanii irraa ta’e hordofaniifi. Akka kanatti Rabbiin fakkeenyota isaanii ilma namaatiif ibsa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 4, 'Yeroo warra kafare qunnamtan mormoota dhawaa. hanga yeroo isaan dadhabsiiftanitti (isaan baay’ee ajjeeftanitti), hidhaa jabeessaa. Sana booda isaan irratti tola oolaa yookiin waa irraa fudhaa, hanga lolli qara (ho’a) ishee dhiiftutti (kana godhaa). Dubbiin kana, Rabbiin odoo fedhee isaan irraa haaloo bahata. Garuu (isaaniin loluutti wanni isin ajajeef) garii keessan gariin mokkoruuf jecha. Warra karaa Rabbii keessatti ajjeefaman hojii isaanii hin balleessu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 5, 'Fuulduratti isaan ni qajeelcha; haala isaaniis ni tolcha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 6, 'Jannata isaan seensisa; ishee isaanitti beeksisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 7, 'Yaa warra amantan! Yoo (diin) Rabbii tumsitan, Inni isinii tumsa. Faannaan keessanis gadi dhaaba.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 8, 'Warri kafaran badiin isaaniif ta’aadha. (Rabbiin) dalagaalee (hojii) isaanii ni balleessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 9, 'Kun waan isaan waan Rabbiin buuse (Qur’aana) jibbaniifi. Kanaafuu (Rabbiin) dalagaa isaanii balleesse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 10, 'Sila dachii keessa deemanii hin ilaallee booddeen warra isaan duraa akkam akka ta’e? Rabbiin isaan barbadeesse. Kaafirootaaf fakkaattuun ishee taatuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 11, 'Kun waan Allaahn gargaaraa warra amananii ta’eefi kaafiroonni immoo gargaaraan isaaniif hinjiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 12, 'Rabbiin warra amananii, hojiiwwan gaggaarii hojjatan jannatoowwan laggeen ishee keessa yaa’u seensisa. Warri kafaran immoo (addunyaa irratti) qanani’aniiti, akkuma beelladoonni nyaatanitti nyaachaa (jiraatan). Ibiddi bakka jireenya isaaniiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 13, 'Baay’ee magaalotaa, kan magaalaa tee ishee (of irraa) si baafte (Makkaan) irra ciccimoo ta’an balleessinee jirra. Homaa tumsaan isaaniif hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 14, 'Sila inni ragaa (ifa ba’aa) Gooftaa isaa irraa ta’e irra jiru akka nama dalagaan hamtuun isaa isaaf miidhagfamee nitahee? kan fedha lubbuu isaanii hordofan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 15, 'Fakkeenyi jannata warra Rabbiin sodaatan waadaa galamanii (akka kana): ishee keessa laggeen bishaan hin xiraahin irraa ta’etu jira, (akkasuma) laggeen aannan dhandhamni isaa hin jijjiiramin irraa ta’e, laggeen daadhii namoota dhuganiif mi’aayaa ta’e irraa ta’eefi laggeen damma qulqulleeffame (nadhii) irraa (ta’etu jira). Ammas isaaniif ishee (jannata) keessa fuduraalee hundaafi araarama Gooftaa isaanii irraa ta’etu jira. (Sila isaan kun) akka namoota ibidda keessa yeroo hunda jiraataniifi bishaan danfaa obaafamanii, inni marrimaan isaanii cicciruutii? (lakki jarru sun akka jara kanaatii miti).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 16, 'Isaan irraa namoota si dhaggeeffatee hanga yeroo si biraa gadi bahanii nijedhan warra beekkumsa kennamaniin “reefu maal jedhe?”. Isaan sun warra qalbiilee isaanii irratti Rabbiin cufee, fedhiilee isaanii hordofan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 17, 'Isaan qajeelan (Rabbiin) qajeeluma isaaniif dabalee, sodaa isaanii isaaniif kenne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 18, 'Sila ni eeganii Qiyaaman tasa isaanitti dhufuu malee? Mallattooleen ishee dhufe. Yeroo isheen isaanitti dhufte gorfamuun isaanii akkamitti isaaniif ta’a?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 19, 'Rabbiin malee dhugaan gabbaramaan biraa hinjiruu beeki; dilii teetiif araarama (Rabbii) kadhu; mu’uminoota dhiiraafi dubartootaatiifis (kadhu). Rabbiin sochii keessaniifi qubannoota keessanis ni beeka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 20, 'Warri amanan “odoo suuraan (jihaada ajajju) buufamtee maal qaba?” jedhu. Yeroo Suuraan heera tumtu buufamtee ishee keessatti lolli dubbatame, warra onneewwan isaanii keessa dhukkubni jiru - ilaalcha nama machii du’aa isa gaggabsee- kan gara kee ilaalan argita. Badiin isaaniif haa ta’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 21, 'Ajaja fudhachuufi jecha gaariitu (isaaniif caala). Yeroo dhimmichi murtaa’e odoo Rabbitti dhugaa haasa’anii irra isaaniif caala ture.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 22, 'Sila yoo duubatti deebitan dachii keessatti badii hojjachuufi firooma keessan muruu kajeeltanii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 23, 'Isaan sun warra Rabbiin isaan abaaree gurra isaaniis duuchee ijoowwan isaanii jaamseedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 24, 'Sila Qur’aana hin xiinxalanii? Moo onneewwan isaanii irra cufaa isheetu jira?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 25, 'Isaan duubatti garagalan erga karaan qajeelaan isaaniif ibsame booda, sheyxaanatu (hojii gadhee) isaanitti bareechee hamilee isaanitti godhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 26, 'Kun waan isaan warra waan Rabbiin buuse jibbaniin “dhimma garii keessatti ajaja keessan fudhanna” jedhaniif. Rabbiin iccitii isaanii ni beeka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 27, 'Akkam tahuu taa’an Yeroo maleeykonni isaan ajjeeftu, fuulleen isaaniitiifi dugdowwan isaanii tumaadhaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 28, 'Kun waan isaan waan Rabbiin dallansiisu hordofaniifii jaalala Isaa (Rabbii) jibbaniifi. (Rabbiin) dalagaalee isaanii balleesse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 29, 'Sila warri onneewwan isaanii keessa dhukkubni jiru Rabbiin jibbansa (garaa isaanii keessa jiru) hin baasuu yaadanii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 30, 'Odoo feenee isaan sitti argisiifneeti, mallattoolee isaanitiin isaan beekta. Ergaa jechootaatiinis isaan ni beekta. Rabbiin dalagaalee keessan ni beeka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 31, 'Isin mokkorra Hanga beeknutti (adda baafnutti) nqabsaa’otaafi obsitoota isin irraa tahan. oduulee keessanis nimokkorra (adda baafna).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 32, 'Isaan kafaranii karaa Rabbii irraa (nama) dhorgan, erga karaan qajeelaan isaaniif ifa ta’e booda ergamaa (Rabbii) didan, homaa Rabbiin hin miidhanu (Rabbiin) dalagaalee isaanii balleessuuf jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 33, 'Yaa warra amantan! Rabbiif ajajamaa; ergamaa (Isaatifis) ajajamaa; dalagaawwan keessan hin balleessinaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 34, 'Isaan kafaranii (namoota) karaa Rabbii irraa dhorgan, ergasii kafaroo ta’anii du’an, Rabbiin isaaniif hin araaramu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 35, 'Hin dadhabinaa; gara araaramaatti hin waaminaa. isintu injifatoodha. Rabbiin isin waliin jira; dalagaalee keessan isin irraa hin hir’isu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 36, 'Jireenyi addunyaa taphaafi dagduudha, Yoo amantanii Rabbiin sodaattan mindaalee keessan isiniif kenna; qabeenya keessan isin hin gaafatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 37, 'Yoo ishee isin gaafatee (gaafii) isinitti bay’ise isin ni dhorgattu turtan; Innis (Rabbiinis) gadoo keessan ni baasa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 38, 'Isin warri kun dhaga’aa! Karaa Rabbii keessatti arjoomuuf waamamtu. Isin irraa nama doynoomuutu jira. Namni doynoome kan inni dooynoomu lubbuma isaa irratti. Rabbiin dureessa; isin hiyyeeyyiidha. Yoo garagaltan, (Rabbiin) namoota biraa kan isin hin ta’in bakka keessan buusa. Isaan ergasii akka keessan hin ta’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 1, '(Yaa Muhammad!) Nuti siif banne baniinsa mul''ataa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 2, 'Akka Rabbiin dilii tee irraa waan dabreefi waan dhufus siif araaramuuf, akka ni’imaa Isaa sirratti guutufi, akka karaa qajeelaa si qajeelchuf jecha (injifannoo ifa ta’e siif kenne).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 3, 'Rabbiin tumsa cimaa sii tumsuuf (si injifachiise).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 4, 'Inni Isa tasgabbii onneewwan mu’uminootaa keessatti buuse, akka isaan iimaana isaanii wajjiin iimaana dabalataniifi, Waraanni samiifi dachii kanuma Rabbiiti, Rabbiin beekaa ogeessa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 5, 'Mu’uminoota dhiiraafi dubartootaa jannata isa jala laggeen yaa’an seensisuufi, kan yeroo hunda ishee keessa jiraatan. diliilee isaanii isaan irraa haquufi, kun Rabbiin biratti milkii guddaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 6, 'Munaafiqoota dhiiraafi dubartootaa azzabuufi, mushrikoota dhiiraafi dhalaas, isaan Rabbi irratti hamtuu yaadan, isaan irratti marsaan hamtuun taatuudha. Rabbiin isaan irratti dallane.isaan abaare, Jahannamiinis isaaniif qopheesse, waa hammaattee deebii tahuun isii!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 7, 'Waraanni samiifi dachii (hundi) kan Allaahti. Rabbiin injifataa, ogeessa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 8, '(Yaa Muhammad!) Nuti ragaa, gammachiisaafi sodaachisaa goonee si ergine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 9, '(Yaa Namootaa!) Akka isin Allaahfi ergamaa isaatti amantaniifi, isa guddiftanii, kabajjaniifi akkasumas ganamaafi galgala Isa faarsitaniif (isiniif ergine).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 10, 'Isaan ahdii siif seenan, kan isaan ahdii seenan Rabbiifi. Harki Rabbii harkoowwan isaanii gubbaadha. Namni waadaa diige, kan inni waadaa diige lubbuma isaa irratti. Nama waan irratti Rabbiif waadaa gale guute, Inni mindaa guddaa isaa kennuuf jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 11, 'Shanaanota irraa namoonni duubatti hafan “qabeenyalee keenyaafi maatiilee keenyatu nu qabe; Rabbiin araarama nuuf kadhu” siin jechuuf jiru. Waan onneewwan isaanii keessa hin jirre arraboota isaanitiin jedhu. (Yaa Muhammad) eenyutu waan Allaahn barbaade irraa isiniif waa gochuu dandaya? “yoo Inni miidhaa isin irra geessuu yookiin bu’aa isiniif kennuu fedhe, Rabbiin waan isin hojjattan beekaa ta’eera” jedhi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 12, 'Dhugumatti, Ergamaan Rabbiitiifi mu’uminoonni gara maatii isaanii gonkumaa hindeebi''anii yaaddanii turtan. Sun onneewwan keessan keessatti miidhagfame, yaada hamtuu yaaddan, ummata mancaafamoo taatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 13, 'Namni Rabbiifi ergamaa Isaatti hin amanin (kaafira). Nuti kaafirootaaf ibidda boba’aa qopheessinee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 14, 'Mootummaan samiileefi dachii kan Rabbiiti, Nama fedheef ni araarama; nama fedhes ni adaba. Rabbiin araaramaa, mararfataa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 15, 'Isaan duubatti hafan “yeroo gara boojuu, ishee fudhachuuf deemtan isin hordofnaa nu dhiisaa” jedhu. Jecha Rabbii jijjiiruu fedhu. “Nu hin hordoftan! Rabbiin duraanis akkasuma jedhe” jedhiin. “Isin nu waanyitu (hassaddu)” jechuuf jiru. Waa xiqqoo malee hin hubatanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 16, 'Shanaanota irraa isaan duubatti hafaniin jedhi: “gara namoota lolatti cimoo ta’aniitti waamamuuf jirtu; isaaniin loltu yookiin harka kennu. yoo tole jettan, Rabbiin mindaa gaarii isiniif kenna. Yoo akkuma duraan garagaltanitti ammas garagaltan, Inni adabbii laalessaa isin adaba.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 17, '(Lola irraa hafuudhaan) jaamaa irra badiin hin jiru. Hokkolaa irras badiin hin jiru. Dhukkubsataa irras diliin hin jiru. Nama Rabbiifi ergamaa isaatif ajajame, (Rabbiin) jannatoowwan laggeen ishee jala yaatu isa seensisa. Nama irraa garagale immoo adabbii laalessaa isa adaba.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 18, '(Yaa Muhammad!) Rabbiin mu’uminoota yeroo isaan muka jalatti waadaa siif galan irraa jaallateera. Waan onneewwan isaanii keessa jirus beekeera. Tasgabbii isaan irratti buuse. injifannoo dhihoo ta’e (sulhii hudeebiyaa) isaaniif galata galche.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 19, 'Boojii baay’ee ta’e kan isaan fudhatanis (galata galche). Rabbiin injifataa, ogeessa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 20, 'Rabbiin boojuu baay’ee kan ishee fudhattan waadaa isiniif galeera. Ishee kana immoo isiniif jarjarse. Harkoowwan namootaa isin irraa qabe. (Kanas kan godhe) akka isheen mu’uminootaaf mallattoo taatuufi, karaa qajeelaa isin qajeelchuufi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 21, '(Injifannoofi boojuu) biraa kan isin irratti hindandayin, kan Rabbiin dhugumatti ishee marsetu jira. Rabbiin waan hunda irratti danda’aa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 22, 'Isaan kafaran odoo isinin lolaniiyyuu, dugdota garagalan. eegasii tiksaafi tumsaa hin argatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 23, 'Karaa Rabbii kan dhugumatti duraan dabarte (karaa godhe). Karaa Rabbiitiif jijjiirama hin argitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 24, 'Innis Isa harka isaanii isin irraa, harka keessanis isaan irraa qabeedha Laga Makkaa keessatti. erga isaan irratti isin moosisee booda. Rabbiin waan isin hojjattan argaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 25, 'Isaan warra kafaranii, masjiida kabajamaa (seenuu) irraa isin dhorganii, horii wareegaas hidhamaa tahee akka iddoo qalma isaanii hin geenye (dhorgan). Odoo dhiirotiin mu’uminoota ta’aniifi dubartoonni mu’uminoota ta’an kan isin hin beekne jiraachuu baatanii; isin isaan irra ejjachuun (ajjeesuun) jiraachuu baatee; odoo hin beekin isaan irraa rakkinni (diliin) isin tuquun jiraachuu baatee (Rabbiin isiniif hayyama ture). Rabbiin nama fedhe rahmata Isaa keessa seensisuuf (hin hayyamini). Odoo (mu’uminootaafi kaafiroonni) addaan bahanii silaa isaan irraa warra kafaran adabbii laalessaa ta’een adabna turre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 26, 'Yeroo warri kafare qalbii isaanii keessa haaloo, hinaaffaa wallaaltotaa godhee, Rabbiin tasgabbii isaa ergamaa isaatiifi mu’uminoota irratti buusee. jecha sodaa (Isaa) isaan qabachiise [yaadadhu]. Isaanumatu ishee haqa godhatee, warra ishee ta’e. Rabbiin waan hunda beekaa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 27, 'Rabbiin ergamaa Isaatiif manaama haqaan dhugoomsee jira. Yoo Rabbiin fedhe masjiida kabajamaa niseentu, nagayaan mataalee keessan haaddachaa, (gariinis) gabaabsachaa, odoo hin sodaanne. Inni (Rabbiin) waan isin hin beekin beekeeti sanaa asitti injifannoo dhihoo (araara hudeeybiyaa) godhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 28, 'Inni Isa ergamaa Isaa erge qajeelloofi amantii dhugaatiin. amantii hunda irratti ol isa taasisuuf. Ragaaf Rabbiin ga’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 29, 'Muhammad ergamaa Rabbiiti. Warri isaan wajjii kuffaara irratti ciccimoo, gidduu isaanitti immoo wal mararfatoodha. rukuu’aafi sujuuda kan baay’isan argita Tolaafi jaalala Rabbii barbaadan. Mallattooleen isaanii fuulleen isaanii keessa jira kan faanaa sujuudaa irraa ta’e. Sun fakkeenya isaanii kan Tawraat keessaati. Fakkeenyi isaanii kan Injiil keessa jiru immoo akka midhaan lakkuu isaa baasee isa jabeessee, furdatee, jirma isaa irratti dhaabbateeti. facaafattoota jaalachiise. (Wanni akkanatti isaan jabeessef) akka isaaniin kaafirtoota dallansiisuufi. Rabbiin isaan irraa warra amananii gaggaarii hojjatan araaramaafi mindaa guddaa waadaa isaaniif galee jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 1, 'Yaa warra amantan! Rabbiifi ergamaa Isaa dura hin dabrinaa. Rabbiin sodaadhaa. Rabbiin dhagayaa, beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 2, 'Yaa warra amantan! Sagaleewwan keessan sagalee Nabiyyichaa irra ol hin kaasinaa. haasa’a isa irratti ol hin fuudhinaa, akka gariin keessan garii irratti ol fuudhutti. Akka dalagaawwan keessan odoo isin hin beekne hin banneef jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 3, 'Isaan sagaleewwan isaanii ergamaa Rabbii biratti gadi qabatan, isaan sun warra Rabbiin onneewwan isaanii sodaa Rabbiitif qorate. Isaaniif araaramaafi mindaa guddaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 4, 'Isaan duuba manneenii irraa si waaman, hedduun isaanii hin hubatanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 5, 'Odoo hanga ati isaanitti gadi baatutti obsanii silaa (sanatu) isaaniif caala taha ture. Rabbiin araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 6, 'Yaa warra amantan! Yoo jallaan oduun isinitti dhufe dubbii adda baafadhaa, akka wallaalumaan namoota miitanii, ergasii waan hojjattan irratti hin gaabbineef.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 7, 'Isin keessa ergamaa Rabbiittu jiraa beekaa. Dhimmoota baay’ee keessatti odoo isin tole jedhee nirakkattu ture. Garuu Rabbiin iimaana gara keessanitti jaallachiise, onneewwan keessan keessatti isa miidhagsee, kufrii, fincilaafi dilii gara keessanitti jibbamaa godhe. Isaan sun (warri iimaana jaalatanii kufrii jibban) isaanumatu qajeeloodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 8, 'Tolaafi ni’imaa Rabbi irraa ta’een (kana godhe). Rabbiin beekaa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 9, 'Yoo gareen mu’uminoota irraa ta’an lama wal waraanan, gidduu isaanii araarsaa. Yoo takkaan isaan lameeni taan irratti daangaa darbite, ishee daangaa darbite san hanga isheen gara ajaja Rabbii deebitutti waraanaa. Yoo isheen (ajaja Rabbiitif) bulte gidduu isaanitti haqaan tolchaa; wal qixxeessas. Rabbiin warra wal qixxeessan jaallata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 10, 'Mu’uminoonni obboleeyyani; gidduu obboleeyyan keessanii tolchaa. Rabbiin sodaadhaa Akka mararfatamtanuuf jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 11, 'Isin yaa warra amantan Dhiironni dhiirota biraatti hin qoosin. Isaan irra caaluun isaanii (tuffatamtootaa) ni mala. Dubartoonnis dubartoota biraa (hinqoosin). Isaan irra caaluun isaanii (tuffatamtootaa) ni mala. lubbuulee teessan wal hin xureessina; maqaa qoosaatiin wal hin arrabsinaa. Erga amanuutii maqaan faasiquummaa (amantiin alaa) waa fokkatee! Namni hin tawbatin, isaanumatu miidhaa raawwattoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 12, 'Yaa warra amantan! Hedduu seehaa (mamii) irraa fagaadhaa; gariin seehaa diliidha. Wal hin basaasinaa. Gariin keessanis garii hin hamatin. Tokkoon keessan foon obboleessa isaa odoo du’ee jiruu nyaachuu ni fedhaa? jibbitanii jirtan. (isa jiraa hoo maalif nyaachuu feetan?) Rabbiin sodaadhaa. Rabbiin akkaan tawbaa qeebalaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 13, 'Isin Yaa namootaa! Nuti dhiiraafi dubartii irraa isin uumne, sabootaafi gosoota isin taasifne akka wal beektaniif jecha. Rabbiin biratti irra kabajamaan keessan, irra Rabbiin sodaataa keessani. Rabbiin beekaa keessa hubataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 14, 'Shanaanoon “nuti amanneerra” jette. jedhiin isin hin amanne garuu islaamoyne jedhaa, hanga silaa iimaanni onneewwan keessan keessa hin seenne. yoo ajaja Rabbiifi ergamaa Isaa fudhattan, hojiiwwan keessan irraa homaa isinduraa hin hir’isu. Rabbiin araaramaa, mararfataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 15, 'Mu’uminoonni isaan Rabbiifi ergamaa Isaatti amananii, ergasii hinshakkini, qabeenyaalee isaanitiifi lubbuulee isaaniitiin karaa Rabbii keessatti qabsaa’aniidha. Isaan isaanumatu warra dhugaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 16, 'Jedhi: “Amantii keessan Rabbiin beysiistuu? Rabbiin waan samiilee keessa jiruufi waan dachii keessa jiru ni beeka. Rabbiin waan hunda beekaadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 17, 'Islaamawuu isaaniitiin sirratti galata himatu “Islaamummaa keessaniin ana irratti galata hin himatinaa, Rabbiin waan imaanatti isin qajeelcheef isin irratti galata himata” jedhiin. Yoo warra dhugaa taatan (kan galata himatu Rabbi tahuu beekaa).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 18, 'Rabbiin fagoo samiileefi dachii keessaa ni beeka. Rabbiin waan isin dalagdan (hunda) argaadha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 1, 'Qaaf Qur’aana guddaanin (kakadha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 2, 'Dhugumaatti, sodaachisaan isaan irraa ta’e isaanitti dhufuu dinqisiifatan. Kaafiroonni “kun waan dinqisiisaadha” jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 3, '“Sila yeroo duunee biyyee taane (ni kaafamnaa)? Sun deebii fagoodha.”(jedhu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 4, 'Dhugumatti, waan dachiin isaan irraa hir’iftu beeknee jirra. kitaabni tiksaan nu biratti tahee jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 5, 'Dhugumatti isaan dhugaa sobsiisan yeroo inni isaanitti dhufu. Isaan dubbii wal makataa keessa jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 6, 'Sila gara samii gubbaa isaanii jirtuu hin ilaallee? akkamitti akka ishee ijaarreefi ishee miidhagsine, uraan homaatuu isiif hintaane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 7, 'Dachii diriirsinee gaarreen dhaabbatoo ishee keessatti gadi suuqnee, akaakuu (biqiltootaa) babbareedoo hunda irraa ishee keessatti magarsine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 8, 'Gabricha tawbatuuf hubannaafi gorsa akka ta’uuf (kana goone).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 9, 'Samii irraas bishaan barakaa qabu buufne. isaan ashaakiltiiwwaniifi firiiwwan haamamanis biqilchine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 10, 'Hundee timiraa dhedheeroo, kan daraaraa dachaa (ni magarsine).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 11, 'Hiree Gabrootanniitiif (buufne). Isaan (bishaan saniin) dachii duutuu jiraachifne. Baafamuunis akkuma kana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 12, 'Isaaniin dura ummanni Nuuh kijibsiifte, warri eelaatiifi Samuudis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 13, 'Aad, Fir’awniifi obboleeyyan Luuxis (kijibsiisan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 14, 'Warri bosonaatiifi ummanni Tubba’is Hunduu ergamtoota sobsiisan, adabbiin (kiyya) isaanitti mirkanaa’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 15, 'Sila Nuti uumaa duraatiin ni dadhabnee? Lakkii! Isaan uumaa haarawa irraa shakkii wal makate keessa jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 16, 'Nuti dhugumatti, nama uumneerra. Waan lubbuun isaa itti hasaastus ni beekna. Nuti (beekumsa keenyan) hidda dhiigaa (dhamaa) irra gara isaatti dhihoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 17, 'Yeroo (maleeykonni) jecha fuudhan lamaan mirgaafi bitaa isaa irra taa’anii jecha fuudhan (yaadachiisi).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 18, 'Jecha tokkoyyuu hin dubbatu Tiksaan itti dhihaataan isa bira jiraatu malee .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 19, 'Machiin du’aa dhugaan dhuftee jirti. “Kun waan ati irraa dheessaa turteedha” (jedhamaan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 20, 'Xurumbaan ni afuufama; sun guyyaa sodaachisaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 21, 'Lubbuun hundi haala ishee wajjin oofaafi ragaa bahaan jiranuun dhufte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 22, '“Ati kana irraa daguu keessa turte. Nuti haguuggaa kee sirraa kaafne. ijji kee har’a qara” (jedhamaan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 23, 'Qindiin (maleeyakaan) isaa ni jedha: “kun waan (galmaa’ee) na bira dhihaataa tahee jiruudha.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 24, 'Akkaan kafaraa haqa didaa hunda jahannamitti darbaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 25, '(Kaafira) toltuu dhorgaa, daangaa dabraafi shakkaa ta’e (jahannamitti darbaa).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 26, 'Isa Rabbii wajjin gabbaramaa biraa taasise azaaba cimaa keessa isa buusaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 27, 'Hiriyaan isaa (kan sheyxaanaa) ni jedha: “Gooftaa keenya! Ani isa hin jallifne. Garuu isumatu jallina fagoo ta’e keessa ture.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 28, 'Rabbiin ni jedha,“Ana biratti wal hin falminaa, Ani dursee sodaachisa kiyya gara keessanitti ergeera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 29, 'Ana biratti jechi hin jijjiiramu; Ani gabroota kiyya miidhaa miti.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 30, 'Guyyaa Nuti jahannamiin “sila guutamteettaa?” jennuun, isheen immoo “dabalanni jiraa?” jettu (isaan sodaachidi.)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 31, 'Jannanni dhiheeffamte namoota Rabbi sodaataniif haala hin fagaatiniin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 32, 'Kun waan waadaa galamtaniidha Cufa nama akkaan gara Rabbii deebi’aa tikfataa ta’eetiif, (jedhama).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 33, '“Nama fagotti Rahmaan sodaatee, onnee gara Rabbii deebituun dhufeefi (nidhihaatti).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 34, 'Nagayaan ishee seenaa; sun guyyaa hafiinsaati” (jedhama).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 35, 'Isaaniif waan fedhantu ishee keessa jira, Nu bira daballis jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 36, 'Meeqaa meeqa balleessinee Isaan dura dhalootarraa? (baayyee), isaantu (warra balleeysineetu) humnaan isaan (ammaa kana) irra ciccimoodha. Biyya keessa fiigan (qoratan) “iddoo baqaan jiraa?” jechaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 37, 'San keessa yaadannootu jira, Nama onnee qabuuf yookin gurra itti kennuuf,haala yeroo (gorsa) irratti hirmaataa taheen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 38, 'Dhugumatti, Nuti samiileefi dachii, wantoota gidduu isaanii jiran guyyoota jaha keessatti uumne; dadhabbirraa homtuu Nu hin tuqne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 39, 'Waan isaan jedhanu irratti obsi. galata Rabbii keetiitiin baha aduu duraafi lixa (ishee) dura faarsi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 40, 'Halkan irraas Isa qulqulleessi; salaata boodas (isa qulqulleessi).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 41, 'Guyyaa lallabaan iddoo dhihoo irraa lallabu dhaggeeffadhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 42, 'Guyyaa dhugaan iyyansa dhagayan, sun guyyaa (qabrii irraa) ba’iinsaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 43, 'Nuti, Numatu jiraachisa; Numatu ajjeesas; deebiin (dhumaas) garumma keenya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 44, 'Guyyaa dachiin isaan irraa ariitiidhaan babbaqaqxu (deebiin garuma keenya). Sun walitti qabuu Nurratti laafaa ta’eedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 45, 'Nuti akkaan beekoo waan isaan jedhaniiti. Ati isaan irratti moosifamaa hin taane. Nama adabbii (kiyya) sodaatu Qur’aanaan gorsi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 1, '(Qilleensa) bubbisiinsa bubbiftuunin kakadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 2, '(Duumessa bishaan) ulfaataa baadhattuunis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 3, '(Dooniwwan) haala salphaan (bishaan gubbaa) yaa’aniinis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 4, '(Maleykota) ajaja (Rabbii) raabsaniinis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 5, 'Wanti isin beellamamtan dhugaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 6, 'Murtiin argamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 7, 'Samii abbaa miidhaginaatiin 9karaa urjiitiin) kakadhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 8, 'Isin yaada wal dhadhabaa keessa jirtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 9, 'Kan namni haqa irraa garagalfamu ittiin garagalfamuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 10, 'Sobdoonni abaaramaniiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 11, 'Isaan sun wallaaluma keessatti kan of dagataniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 12, '“Guyyaan galataa yoomi?” (jechuun) gaafatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 13, '(Inni) Guyyaa isaan ibidda irra fidamanii (qoratamaniidha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 14, '“Adaba keessan dhandhamaa, kun ka isa jarjarsiifachaa turtani ” (isaaniin jedhama).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 15, 'Isaan Rabbiin sodaatan, jannataafi burqituuwwan keessa jiraatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 16, 'Waan Gooftaan isaanii isaaniif kenne fudhatoodha, Isaan sana dura toltuu hojjattoota turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 17, 'Halkan irraa xiqqaa qofa kan rafan turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 18, 'Yeroo hiraabaa (obboroo) isaan araarama kadhatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 19, 'qabeenya isaanii keessa kadhataafi kan hin kadhanneefis haqni jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 20, 'Dachii keessa mu''imintootaaf mallattooleetu jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 21, 'Lubbuulee keessan keessas (akkasuma), Sila hin argitanuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 22, 'Samii keessa jira Sooranni keessaaniifi wanti isin waadaa galamtanis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 23, 'Gooftaa samiifi dachiitiin kakadhee! Inni dhugaa fakkiidhuma waan isinuu dubbattanuuti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 24, 'Seenaan keessummaa Ibraahiim kabajamoo ta’anii sitti dhufeeraa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 25, 'Yeroo isa irratti seenanii “Nagaa (si irratti buufna)” jedhan. [Inni] “nageenyi (isin irras haa jiraatu); ummata wallaalamoo” jedheen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 26, 'Gara maatii isaa deebi’eeti mirgoo (jibicha) gabbataan dhufe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 27, 'Isaanitti dhiyeesseeti “sila hin nyaattanuu?” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 28, 'Ergasii (yeroo nyaachuu dhabuu isaanii argu) isaan irraa sodaan isa qabe. Isaan “hin sodaatin” jedhaniin. Ilma beekumsa qabuunis isa gammachiisan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 29, 'Sana booda niitin isaa sagalee ol fuudhamaan haasa’aa dhufte. Fuula ishee dhooyte “Ani dullattii maseena hoo (akkamittin daha)!” jette.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 30, '(Maleykonni) ni jedhan: akka kana Rabbiin kee jedhe inni isaatu ogeessa beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 31, '(Ibraahiim) ni jedhe: “Yaa ergamootaa! dubbiin keessan maali?”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 32, '[Isaan] ni jedhan: “Nuti gara ummata yakkamtootaa ergamne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 33, 'Dhagaa dhoqqee gubataa irraa ta’e isaan irratti erguuf (dhufne).”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 34, 'Rabbii kee biratti daanga dabartootaaf kan milikitoomfamte haala taateen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 35, 'Mu’uminoota irraa namoota ishee keessa jiran ni baafne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 36, 'ishee keessatti homaa hin argine Mana Muslimtootaa irraa ta’e tokko malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 37, 'Warra adabbii laalessaa sodaataniif ishee keessatti mallattoo hambifnee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 38, '(Seenaa) Muusaa keessas yeroo ragaa ifa ba’aan gara Fir’awnitti isa ergine (mallattoo goonee jirra).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 39, '(Fir’awnis) humna waraanaa isaa waliin (dhugaa irraa) gara galee, “(Muusaan) falfalaadha; yookiin maraataadha” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 40, 'Isaafi waraana isaas qabnee. galaana keessatti isaan darbine haala inni komatamaa ta’een.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 41, '(Seenaa) Aad keessas, yeroo qilleensa maseenaa isaan irratti ergine (mallattootu jira).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 42, 'Waan isa irra dhufte tokkoyyuu akka lafee dhumee isa gootu malee hin dhiiftu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 43, '(Seenaa) Samuud keessas, yeroo hanga murtaa’e tokko qanani’aa isaaniin jedhame (mallattootu jira).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 44, 'Ajaja Gooftaa isaanii irraa ni boonan. iyyansi (dhumti) isaan qabatte Odoo isaan ilaalanuu .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 45, 'Ergasii dhaabbachuu hin dandeenye; tumsamoos hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 46, 'Ummata Nuuhis san dura (ballessinee jirra). isaan ummata finciltoota turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 47, 'Samiis humnaan ishee ijaarre. Dhugumatti, Nuti (ishee) bal’isoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 48, 'Dachiis diriirsinee jirra; (Nuti) diriirsitoonni waa tolle!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 49, 'Akka isin gorfamtaniif waan hunda irraa qindiiwwan uumne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 50, 'Gara Rabbii baqadhaa. Ani Isa irraa isiniif sodaachisaa ifa bahaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 51, 'Allaah wajjini gabbaramaa biraa hin taasisinaa. Ani Isa irraa isiniif sodaachisaa ifa bahaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 52, 'Akkasuma, ergamaan tokkos warra isaan dura turanitti hin dhufne, yoo isaan “falfalaadha; yookiin maraataadha” jedhaniin malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 53, 'Sila isa (sobsiisuu kana) waliif dhaamanii? Lakkisaa, isaanumatu ummata daangaa dabroodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 54, 'Isaan irraa garagali; ati komatamaa miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 55, 'Yaadachiisi; yaadachiifni mu’uminoota ni fayyaddii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 56, 'Jinniifi ilma namaa haa na gabbaraniif malee hin uumne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 57, 'Hiree homaatuu isaan irraa hin fedhu. Akka Ana nyaachisanis hin fedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 58, 'Rabbiin Isatu akkaan hiree kennaa, abbaa humna cimaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 59, 'Miidhaa raawwattootaaf qooda adabaa kan akka adabbii fakkaattota isaaniitu jiraafii akka Nan jarjarfanne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 60, 'Warra kafaraniif guyyaa isaanii kan beellama godhaman keessatti badiin isaaniif mirkanaa’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 1, '(Gaara) Xuuriin kakadhe. [1]', '[1] gaarri xuur kuni gaara Rabbiin nabi muusaa irratti dubbise.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 2, 'Kitaaba barreeffamaanis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 3, 'Xalaayaa bal’ifamaa keessatti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 4, 'Mana jiraachifamaanis. [1]', '[1] inni mana samii keessatti tahe. malaaykaan isatti xawaafti.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 5, 'Ijoo (gombisaa) ol fuudhamaanis. [1]', '[1] kana jechuun samii duniyaati.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 6, 'Galaana bishaaniin guutameenis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 7, 'Dhugumatti, adabbiin Gooftaa keetii argamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 8, 'Deebisaan tokkolleen isaaf hintaane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 9, 'Guyyaa samiin socho’iinsa (hamaa) sochootu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 10, '(Guyyaa) gaarreenis deemicha deemtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 11, 'Warra kijibsiisaniif guyyaa san ibiddaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 12, '(Isaan) warra soba keessa taphataniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 13, 'Guyyaa humnaan gara ibidda jahannam oofamiinsa oofaman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 14, '(Isaaniin jedhama): “Isheen kun ibidda kan ishee sobsiisaa turtaniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 15, 'Sila kun falfala moo isinumatu hin argitanu?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 16, 'Ishee seenaa (dhandhamaa); obsaa yookaan hin obsinaa isinirratti waluma qixa. Wanti isin mindeeffamtan waanuma hojjachaa turtan qofa” (jedhaman).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 17, 'Dhugumatti, isaan Rabbiin sodaatan jannatootaafi qananii keessa jiraatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 18, 'Waan Gooftaan isaanii isaaniif kennetti gammadoo ta’anii (keessa jiraatu); Gooftaan isaanii azaaba gubaa jalaa isaan baraarse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 19, '“Waan hojjataa turtaniif jecha gaarii haala ta’een nyaadhaa; dhugaa” (isaaniin jedhama).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 20, 'Sireewwan tarree galfaman irra hirkatoo ta’anii (jiraatu). Dubartoota adaadii ija babal’aa isaan fuusifna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 21, 'Isaan amananii ilmaan isaaniis iimaanaan isaan hordofan, maatii isaanii isaanitti dhaqqabsiifna (Galata) dalagaa isaanii irraas homaayyuu hin hir’ifnu. Namni hunduu waan hojjateen qabamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 22, 'Mudraaleefi foon waan isaan fedhan irraa ta’e isaaniif daballa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 23, 'Ishee keessatti geeba (xoofoo farsoo jannataa) walitti daddabarsu (waliif kennu) ishee keessa sobaafi diliin hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 24, 'Isaan irra naanna’u Ijoollee dhiiraa isaanii. (bareedinni isaanii) akka waan isaan faaya eegamaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 25, 'Gariin isaanii garii irratti gara galaniiti wal gaggaafatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 26, 'Ni jedhu: “Nuti kana dura maatii keenya keessatti (Rabbi irraa) sodaatoo turre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 27, 'Rabbiin nu qanansiisee, adabbii summaa’aa jalaas nu baraarse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 28, 'Nuti kana dura Isa kadhataa turre. Inni Isumatu tola oolaa, mararfataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 29, 'Yaadachiisi! Ati ni’imaa Gooftaa keetiitiin, raagaafi maraataa miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 30, 'Moo “Weellisaadha; dhufuu du’aa isa irratti eegna” jedhanii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 31, '“Eegaa! Anis isin waliin warra eegu irrayii” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 32, 'Sila sammuu isaaniitu kanatti isaan ajaja moo? Lakkii, isaanumatu ummata jallatoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 33, 'Moo Sila isatu isa (Qur’aana) uume jedhu?” lakkii, isaan hin amanan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 34, 'haasaa fakkaataa isaatiin haa dhufanu Yoo kan dhugaa dubbatan ta’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 35, 'Sila isaan odoo wanti isaan uume hin jirre uumaman? moo isaanumatu uumoo dha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 36, 'Moo samiifi dachii uuman? Lakki, isaan hin dhugoomsanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 37, 'Moo Kuusaa Gooftaa keetiitu isaan bira jira, moo isaantu injifattoota?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 38, 'Moo kortoo (samii geessu) kan isa keessaan (maleykota) dhagayantu isaaniif jira! Dhaggeeffataan isaanii ragaa ifa ta’een haa dhufu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 39, 'Moo Isaaf ilmaan dubaraa jiraataniiti isiniif immoo ilmaan dhiiraa jiru?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 40, 'Moo mindaa isaan gaafatteeti kaffaltiin isaa isaanitti ulfaate?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 41, 'Moo isaan bira iccitiin fagoo jiraateeti isaan barreeffatan?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 42, 'Lakkii! Tooftaa baasuu fedhani, Warri kafare isaanuma kan tooftaan itti baafamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 43, 'Moo Rabbiin malee gabbaramaa biraa qabu? Rabbiin waan isaan itti qixxeessan irraa qulqullaa’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 44, 'Yoo samii irraa cittuu wahii kan gadi kuftu arganis “duumessa kuufamaadha” jedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 45, 'Hanga guyyaa isaanii kan isa keessa dhuman qunnamanitti isaan dhiisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 46, 'Guyyaa tooftaan isaanii homaa isaan hin fayyadneefi isaanis hin tumsamne (hanga qunnamanitti).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 47, 'Dhugumatti, isaan miidhaa raawwataniif sana dura adabbiitu jira. Garuu irra hedduun isaanii hin beekanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 48, 'Murtii Gooftaa keetiitiif obsi. Ati tika keenya jala jirta. Yeroo kaatu Faaruu Gooftaa keetiitiin Isa qulqulleessi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 49, 'Halkanis Isa faarsi; yeroo urjiiwwan seenanis (faarsi).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 1, 'Urjiin kakadhe; yeroo inni bu’e (seene).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 2, 'Hiriyaan keessan (Muhammad SAW) hin jallanne; hin dogoggorres.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 3, 'Fedha lubbuu irraas hin haasa’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 4, 'Inni (wanti inni dubbatu) wahyii buufamu qofa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 5, '(Jibriil) kan humni isaa cimaatu isa barsiise.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 6, 'Abbaa humnaa ta’ee (bifa Rabbiin irratti isa uumeen) ol ta’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 7, 'Inni moggaa (samii) isa ol aanaa irratti (ol ta’e).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 8, 'Ergasii dhihaatee gadis bu’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 9, 'Hanga (fageenya) qabannaa gooboo (dagaanaa) lamaanii yookiin sana irra dhihoo ta’e. [1]', '[1] Kun fakkii dhihaatinsa Jibriil nabi Muhammaditti dhihaateeti ibsa.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 10, 'Gara gabricha Isaatti (Rabbiitti) waan wahyii godhe wahyii godhe. [1]', '[1] Rabbiitu gabricha isaa nabi muhammaditti wahyii godhe.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 11, 'Onneen (Nabiyyii-SAW) waan arge keessatti homaa hin sobne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 12, 'Sila ergasii waan inni (yeroo mi’iraajaa) arge irratti isa mormituu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 13, 'Dhugumatti yeroo biraas isa argeera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 14, 'Qurquraa dhumaa (samii torbaffaa) biratti arge.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 15, 'Ishee bira jannata qubsumaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 16, 'Yeroo wanti haguugu mukattii qurquraa haguugu (arge).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 17, 'Ijji gamaa gamana hin jallanne, irras hin dabarre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 18, 'Dhugumatti, inni mallattoolee Gooftaa isaa gurguddoo irraa argeera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 19, 'Mee (taabota) Laatiifi Uzzaa (jedhaman) naaf himaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 20, 'Manaatiin kan sadaffaa duubatti haftuu taates (naaf himaa)?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 21, 'Sila isiniif dhiirri ta''eeti dubartiin isaaf taatee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 22, 'Isheen kun oggas qooda jalloodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 23, 'Isheen maqoota isiniifi abbootiin keessan moggaaftani malee homaa miti. Rabbiin ragaa isheef hin buufne. Se’aafi waan lubbuuleen isaanii feetu feetu malee waan biraa hin hordofan. Dhugumaan qajeellloon Rabbii isaanii irraa isaanitti dhufee jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 24, 'Moo namaaf waanuma hawwetu jira?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 25, 'Aakiraafi tanduraatis Rabbiif taate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 26, 'meeqaa meeqaatu Maleeykota irraa samii keessa jiru? kan manguddummaan isaanii homaa hin fayyadne, erga Rabbiin nama fedhuuf hayyamee, jaallate malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 27, 'Isaan Aakhiratti hin amanne moggaasa dubartootaa maleeykota moggaasu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 28, 'Isa irratti beekumsa homaatuu hin qaban. Shakkii malee homaa hin hordofanu. Shakkiin immoo dhugaa irraa homaa hin duroomsu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 29, 'Nama yaadannoo keenya irraa garagalee, jiruu addunyaa malee hin fedhin irraa garagali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 30, 'Kun beekumsa irraa daangaa isaaniiti. Rabbiin kee Isumatu nama karaa Isaa irraa jallate akkaan beekaadha. Inni nama qajeeles akkaan beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 31, 'Wanti samiilee keessa jiruufi wanti dachii keessa jirus kan Rabbiiti. Isaan hamtuu dalagan waan isaan dalaganiin isaaniif galata galchuuf isaan toltuu hojjatanis ishee caaltuu taate isaan mindeessuuf (uume).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 32, 'Isaan sun warra dogoggora xixiqqoo malee dilii gugurdoofi sagaagalummaa irraa fagaataniidha. Gooftaan kee araaramni Isaa bal’aadha. Inni akkaan isin beeka yeroo dachii irraa isin uumeefi yeroo isin garaa haadha teessanii keessatti ulfa taatanii jirtan . Lubbuulee keessan hin qulqulleessinaa. Inni nama (Isa) sodaatu akkaan beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 33, 'Mee isa gara gale naaf himi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 34, 'Kan xiqqoo kennee, ergasii dhoorgate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 35, 'Sila beekumsi fagoottu isa bira jiraa? inni (isa) beekee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 36, 'Moo wanta barreeffamoota Muusaa keessa jirutu itti hin himaminii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 37, 'Kan Ibraahiim isa (ajaja Rabbii) guutees.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 38, '(Isheen sun) lubbuun dilii baadhattu ba’aa lubbuu biraa hin baadhattuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 39, 'Namaaf waan hojjate malee hintaane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 40, 'Hojiin isaa uf duratti ni mul''ata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 41, 'Achii booda mindaa guutuutu isaaf kennamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 42, 'Xumurri (waan hundaas) gara Rabbii keetiitti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 43, 'Inni Isumatu kofalchiise; boochises.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 44, 'Inni Isumatu ajjeese; jiraachises.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 45, 'Inni cimdii lama, kormaafi dhalaa, uume.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 46, 'Bishaan hormaataa irraa (uume), yeroo (gadaamessaa keessatti) nagamtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 47, 'Uumuun boodaas isuma (Rabbuma) irra jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 48, 'Inni Isa duroomseefi hiyyoomseedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 49, 'Inni Isumatu Gooftaa Shi’iraati', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 50, 'Isumatu Aadii duraa balleesse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 51, '(Ummata) Samuudis hin hambifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 52, 'Ummata Nuuhis sana dura (balleesse) Isaan isaanumatu akkaan miidhaa raawwattootaafi daangaa darbitoota turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 53, 'Ganda gombifamtuus gadi kuffise.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 54, 'Wanti haguuge ishee haguuge.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 55, 'Ni’imaa Rabbii keetii irraa kamiin shakkita?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 56, 'Kun (Muhammad SAW) sodaachisaa sodaachistoota durii irraa ta’eedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 57, 'Dhihaattuun (Qiyaamaa) dhihaatteetti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 58, 'Rabbiin ala isheef mul’iftuun hin jirtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 59, 'Sila haasa’a kana (Qur’aana) irraa dinqisiifattanii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 60, 'Ni kolfituu! Hin boochanuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 61, 'Haala isin dagamoo taataniin (irraa garagaltuu)?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 62, 'Allaah’f sujuudaa; (Isuma qofa) gabbaraa [1]', '[1] bakka kanatti sujuuda qaraatii qur''aanaattu godhama.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 1, 'Qiyaamaan kaloofte; jiinis lamatti addaan dhoohe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 2, 'Yeroo mallattoo argan gara galaniiti “(kun) sihrii ittifufaa” jedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 3, '(Qur’aana) sobsiisanii fedha lubbuu isaanii hordofu. Wanti hunduu galma ga’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 4, 'Dhugumatti, oduu irraa wanti isa keessa sodaachisni jiru isaanitti dhufeera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 5, 'Beekumsi ga’aan (isaanitti dhufeera). Akeekkachiistonni homaa isaan hin fayyadu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 6, 'Isaan irraa garagali Guyyaa waamaan gara waan rifachiisaa ta’eetti (isaan) waamu (yaadachiisi).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 7, '(Guyyaa san) ijji isaanii sodaan guutamteeti, awwaala (isaanii) irraa ba’an akka awwaannisa faca’ee fakkaatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 8, 'Gara waamaatti ori’u Kaafiroonni “Kun guyyaa (rakkisaa) cimaadha.” jedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 9, 'Isaaniin dura ummanni Nuuh sobsiifteera. Gabricha keenya (Nuuh) sobsiisan, “inni maraataa dhajedhan" rakkifame.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 10, '“Ani injifatamaa dhaa naaf tumsi” (jedhee) Gooftaa isaa kadhate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 11, 'Bishaan dhangala’aa ta’een hulaalee samii itti banne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 12, 'Burqituuwwan dachii burqisiifnee bishaan (samiifi dachii) murtii dhugumaan murtaa’e irratti walitti dhufan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 13, 'Doonii abbaa xawulaafi mismaaraa irratti isa yaabbachiifne (feene).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 14, 'Tika keenyaan deemti Galata isa itti kafaramee (haa taatuuf kana goone).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 15, 'Dhugumatti, Nuti mallattoo akka taatuuf ishee dhiifne. Namni ittiin gorfamu jiraa laata?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 16, '(Yeroo san) adabbiin kiyyaafi sodaachisni kiyyas akkam ture laata?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 17, 'Dhugumatti, Qur’aanas hubachuudhaaf laaffifneerra gorfamaan jiraa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 18, '(Ummanni) Aad (Huudiin) sobsiifte. adabbiin kiyyaafi akeekkachiifni kiyyaas akkam ta’e ree?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 19, 'Nuti qilleensa qorraa isaanitti ergine guyyaa hamaa itti fufaa ta’e keessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 20, 'Nama ni buqqifti (Yeroo san) jirma teemiraa kan dachii irraa buqqa’e fakkaatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 21, '(Yeroo san) adabbiin kiyyaafi akeekkachiisni kiyyas akkam ture laata?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 22, 'Dhugumatti, Qur’aana hubachuuf laaffifnee jirra. gorfamaan jiraa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 23, '(Ummanni) Samuudis akeekkachiisa (kiyya) sobsiisaniiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 24, 'Ni jedhan: “nama nurraa ta’e tokko hordofnaa? Nuti yuggas jallinaafi maraatuu keessa jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 25, 'Sila yaadachiifni kun nu hunda gidduu isa (Nabi Saalih) qofa irratti buufamee? Lakkisaa! Inni akkaan sobaa, boonaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 26, 'Sobaan boonaan eenyuun akka ta’e boru beekuuf jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 27, 'Dhugumatti, Nuti gaala dhaltuu isaaniin mokkoruuf ergoodha. Kanaaf (Yaa Saalih!) Isaan eegi; obsis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 28, 'Bishaan (gaalattii fi) isaan gidduutti qoodamus isaanitti himi. Dhugaatiin (garee) hundaayyuu dhufamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 29, 'Hiriyaa isaaniitti lallabaniiti, (waraana isaa) fudhatee waraane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 30, '(Yeroo san) adabbiin kiyyaafi akeekkachiisni kiyyaa akkam ture laata?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 31, 'Nuti iyya tokkittii isaan irratti ergine. Ergasii akka caccabaa mooraa horiin irra deemee tahan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 32, 'Dhugumatti, Qur’aana hubachuuf laaffifneerra. Egaa namni gorfamu jiraa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 33, 'Ummanni “Luux” dinniina sobsiisaniiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 34, 'Nuti isaan irratti bubbee cirrachaa erginee jirra. Maatii Luux malee, (yeroo) bariisaa isaan baraarsine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 35, 'Qananii Nu biraa ta’eef (baraarsine). Akka kanatti nama galata Nuuf galche galateessina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 36, 'Dhugumatti, inni (Luux) qabaa keenya isaan akeekkachiisee jira. Isaan garuu dinniinicha falmaniiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 37, 'Keessummaa isaa irraa (badii itti hojjachuuf) isa gaafatan. ijoowwan isaanii jaamsinee “adaba kiyyaafi dinniina (kiyyas) dhandhamaa” (jenneen).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 38, 'Dhugumatti, adabbiin cimaan bariidhaan isaanitti ganamfate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 39, 'Adaba kiyyaafi dinniina (kiyyas) dhandhamaa” (isaaniin jenne).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 40, 'Dhugumatti, Qur’aana hubachuuf laaffifneerra. Egaa namni gorfamu jiraa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 41, 'Dhugumatti, maatii Fir’awnitti akeekkachiisonni dhufeera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 42, 'Mallattoolee keenya hunda sobsiisaniiti, qabaa Isa injifataa, danda’aa ta’ee isaan qabne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 43, '(Yaa Qureeyshotaa!) Sila kaafiroota keessantu isaan kanneen irra caala moo kitaabota keessa (adabbii irraa) baraaramuutu isiniif jira?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 44, 'Hinumaayyuu “Nuti tuuta injifattoota” jedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 45, 'Tuutni isaanii cabsameeti dugda gara galuuf jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 46, 'Dhugumatti, Qiyaamaan beellama isaaniiti. Qiyaamaan irra ulfaattuufi akkaan hadhooftuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 47, 'Dhugumatti, yakkamtoonni jallinaafi ibidda qabsiifamaa keessatti ta’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 48, 'Guyyaa fuulleen isaanii irratti ibidda keessa harkifaman, “tuqiinsa Saqar (gubaa ibiddaa) dhandhamaa” (jedhamaan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 49, 'Nuti waan hunda likki likkiin isa uumne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 50, 'Ajajni keenya waantaane takka malee akkuma liphsuu ijaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 51, 'Dhugumatti, Nuti fakkaattota keessan balleessinee jirra. Namni gorfamu jiraa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 52, 'Wanti isaan hojjatan hunduu galmeewwan keessa jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 53, 'Wanti xiqqaafi guddaan hundi barreeffamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 54, 'Warri Rabbiin sodaatan jannatootaafi laggeen keessa jiraatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 55, 'Teessoo dhugaa (jannata) keessa Mootii danda’aa bira jiraatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 1, 'Ar-Rahmaan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 2, 'Qur’aana barsiise.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 3, 'Nama uume.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 4, 'Haasaawa isa barsiise.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 5, 'Aduufi jiini qixa murtaa’een deemu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 6, 'Urjiifii muknis (Allaahf) sujuudu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 7, 'Samii ol ishee fuudhe; miizaana ni kaaye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 8, 'Akka isin madaala keessatti daangaa hin dabrineef jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 9, 'Madaala sirriitti qajeelchaa; madaalamaa hin hir’isinaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 10, 'Dachii uumama hundaaf ishee kaaye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 11, 'Ishee keessatti fuduraaleefi mukkeen temiraa kan qolola (qola) habaaboo qabantu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 12, 'Midhaan baalaafi urgaa qabantu jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 13, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 14, '(Rabbiin) ilma namaa dhoqqee akka okkoteetti iyyu (suphee) irraa uume.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 15, 'Jaannii immoo boba’aa ibiddaa kan aara hin qabne irraa uume.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 16, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 17, '(Rabbiin) Gooftaa baha lamaaniifi Gooftaa dhiha lamaaniiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 18, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 19, 'Galaanota lamaan gadi lakkise. wal qunnaman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 20, 'Gidduu isaanii dahootu jira; walitti hin miidhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 21, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 22, 'Isaan lamaan irraa faayaafi burjaanaatu baha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 23, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 24, 'Dooniiwwan tolfaman kan akka gaarreenii galaana keessa yaa’an kan Isaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 25, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 26, 'Wanti ishee (dachii) gubbaa jiru hundi ni dhabama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 27, 'Fuulli Gooftaa keetii nihafa, kan saahiba guddinaafi ulfinaa tahe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 28, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 29, 'Wanti samiileefi dachii keessa jiru hundi Isa kadhata. Guyyaa hunda Inni hojiitti jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 30, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 31, 'Yaa ulfaattota lamaanii (jinniifi namaa) fuulduratti isiniif raawwanna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 32, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 33, 'Yaa garee jinniifi namaa! Yoo moggaawwan samiileefi dachii qaxxaamuruu dandeessan, qaxxaamuraa, Dandeettiin malee hin qaxxaamurtan. (dandeeytii ammoo hin qabdan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 34, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 35, 'Isin lamaan irratti boba’aa Ibidda irraa ta’eefi sibiila baqetu ergama. Ergasii waliif hintumsitan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 36, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 37, 'Yeroo samiin dhodhootee diimtuu akka dhadhaa taate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 38, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 39, 'guyyaa san dilii isaa irraa hin gaafatamu Ilmi namaas ta’ee jinniin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 40, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 41, 'Yakkamtoonni mallattoo isaaniitiin beekamu. Sammuuleefi miillan ni qabamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 42, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 43, '“Tun jahannam ishee yakkamtoonni sobsiisaa turaniidha” (jedhama).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 44, 'Gidduu isheetiifi gidduu bishaan akkaan danfaa ta’ee naanna’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 45, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 46, 'Nama fuulduree Gooftaa isaa dhaabbachuu sodaateef jannata lamatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 47, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 48, 'Kan dameewwan dhedheeroo qaban.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 49, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 50, 'Isaan lamaan keessa madda yaa’an lamatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 51, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 52, 'Isaan lamaan keessa fuduraalee hunda irraa cimdiitu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 53, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 54, 'Afata hariira furdaan guutame irratti hirkatanii taa’u. Fuduraaleen jannata lamaanii dhihoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 55, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 56, 'Isaan keessa (dubartoota bareeda) ija isaanii (dhirsa isaanii irratti) gabaabsan, kan isaansan dura namniifi jinniin hin tuqintu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 57, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 58, 'Faayaafi burjaana fakkaatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 59, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 60, 'Sila mindaan toltuu toltuu malee ni tahee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 61, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 62, 'Isaan lamaan malees jannata lamaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 63, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 64, 'Magariisa gurraacha’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 65, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 66, 'Isaan lamaan keessa burqituuwwan dhangala’an lamatu jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 67, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 68, 'Isaan lamaan keessa fuduraalee, timiraafi rummaanatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 69, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 70, 'Isaan keessa gaggaarii, babbareedoo ta’antu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 71, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 72, 'Dubartoota manneen keessatti (dhirsa irratti) gabaabfamantu jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 73, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 74, 'Isaan dura namaafi jinniinis isaan hin tuqne', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 75, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 76, 'Afata magariisaafi boraatiiwwan babbareedoo irra hirkatanii (taa’u).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 77, 'Tolaalee Rabbii keesanii keessaa kamiin kijibsiiftu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 78, 'Maqaan Gooftaa keetii guddate, abbaa guddinnaafi ulfinaa (kan tahe).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 1, 'Yeroo argamtuun (Qiyaamaan) buute.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 2, 'Argama isheetiif kijibsiiftuun hin jirtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 3, 'Gadi qabduu, ol fuutuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 4, 'Yeroo dachiin raafama cimaa raafamte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 5, '(Yeroo) gaarreenis facaafamiinsa facaafamte,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 6, 'Dhukkee facaafamtuu taate,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 7, '(Yeroo) Isinis garee sadi taatan,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 8, '(Gareen tokko) warra mirgaati; warri mirgaa akkam (milkaa’oo dha)!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 9, '(Gareen lammaffaan) warra bitaati; warri bitaa akkam (hoonga’oo dha)!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 10, '(toltutti) dursitoonni (jannatatti) surditoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 11, 'Isaan (Rabbitti) dhiheeffamoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 12, 'Jannatoota qananii keessatti ta’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 13, 'Warra duraa irraa baay’eedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 14, 'Warra boodaa irraa immoo xiqqoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 15, 'Sireewwan dhawamte irratti ta’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 16, 'Fuulaan walitti garagalanii ishee irratti irkatoo tahanii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 17, 'Ijoollee (ijoollummaan) yeroo hunda jiraatantu isaan irra naanna’a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 18, 'Kubbaayyaa, quluufi geeba (xoofoo) farsoo irraa ta’een.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 19, 'Isii irraa hin bowwaafatan; hin machaa’anis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 20, 'Fuduraalee irraa waan isaan filataniin (irra naanna’u).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 21, 'Foon allaattii irraas waan isaan fedhaniin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 22, 'Dubra adaadii ija babal’ootu (isiniif jira.)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 23, 'Akka faaya eegamaa kan fafakkaatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 24, 'Mindaa waan hojjataa turaniif jecha (kana isaaniif goone).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 25, 'Isii (jannata) keessatti wacaafi wal yakkuu hin dhaga’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 26, '“Nagayaa nagayaa waliin jechuu malee” (hin dhaga’an).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 27, 'Warri mirgaa; warra mirgaa (waa’een isaanii akkam tola!).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 28, '(Isaan) mukkeen qurquraa kan qoree hin qabne keessa jiraatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 29, 'Muuza firiidhaan guutame (keessa jiraatu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 30, 'Gaaddisa diriirfamaa (keessa).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 31, 'Bishaan dhangala’u (biratti).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 32, 'Fuduraalee baay’ee (keessa).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 33, 'Kan maddi isaanii hin cinneefi kan irraa hin dhorgamne (keessa).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 34, 'Firaasholee ol fuudhamtuu (keessa jiraatu.)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 35, 'Dhugumatti, Nuti (dubartoota jannataa) uuminsa isaan uumne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 36, 'Dubroota isaan goone.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 37, 'Jaallattoota (abbaa manaa), kan hiriyoota ta’an (isaan goone).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 38, 'Warreen mirgaatiif (qophaa’an).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 39, 'Hedduun (isaanii) warra duraa irraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 40, 'Warra boodaa irraahis baay’eedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 41, 'Warra bitaa; warri bitaa akkam (fokkatu)!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 42, 'Ibidda laalessaafi bishaan danfaa keessa jiraatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 43, 'Gaaddisa aara gurraacha irraa ta’e keessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 44, '(Gaaddiisa) qabbanaa’aa hin ta’iniifi gaariis hin ta’in.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 45, 'Dhugumatti, isaan sana dura qanansiifamoo turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 46, 'Dilii guddaa itti fufu turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 47, '“Sila yeroo duunee biyyeefi lafee taane, dhugumatti nuti kaafamoodhaa?” jedhaa turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 48, '“Abbootiin keenya kan jalqabaas moo?” (jechuu turan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 49, '“(Yaa Muhammad!) jedhiin isaan jalqabaatii fii isaan boodaas (ni kaafamu)”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 50, 'Beellama guyyaa beekamaa keessatti walitti qabamuuf jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 51, 'Ergasii isin yaa jallattoota sobsiiftotaa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 52, 'Muka Zaqquum irraa nyaatoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 53, 'Ishee irraas garaa keessan guuttatoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 54, 'Isa irrattis bishaan danfaa dhugoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 55, 'Dhugaatii akka gaala dheebotee dhugdu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 56, 'Kun keessummummaa isaanii kan guyyaa murtiiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 57, 'Nuti isin uumnee; maaliif hin dhugoomsine?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 58, 'Waan (maniyyii) dhangalaaftan san mee naaf himaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 59, 'Sila isintu isa uumamoo? Nutu uumoo dha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 60, 'Nutu du’a gidduu keessanitti murteesse. Nuti dadhabsiifamoo miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 61, 'Fakkaataa keessan jijjiiree, waan isin hin beekne keessatti isin uumuu irratti (dadhaboo miti).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 62, 'Dhugumatti, akkaataa uumama jalqabaa beektanii jirtu; maaliif hin gorfamne?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 63, 'Mee waa’ee waan facaaftanii naaf himaa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 64, 'Isintu isa biqilcha moo Nutu biqilchoo dha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 65, 'Odoo feenee caccabaa goona. kan dinqisiifattan taatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 66, '“Nuti dhugumatti hoonga’oodha”(jettu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 67, '“Lakkisaa; nuti dhorgamoodha” (waliin jettu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 68, 'Mee waa’ee bishaan dhugdanii san Naaf himaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 69, 'Sila duumessa irraa isintu isa buusee? Moo Nutu (isa) buusoo dha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 70, 'Odoo feenee soogiddoo (kuraawaa) isa taasifna. Sila maaliif (Rabbiin) hin galatoomfanne?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 71, 'Mee waa’ee ibidda qabsiifattanii san naaf himaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 72, 'Sila muka ishee isintu biqilchee? Moo Nutu biqilchoo dha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 73, 'Nuti isii (bidda tana) gorsaafi qananii imaltootaa goone.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 74, 'Maqaa Gooftaa kee Isa guddaa faarsi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 75, 'Seensa urjiiwwaniitiniin kakadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 76, 'Inni odoo beektanii kakuu guddaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 77, 'Inni Qur’aana kabajamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 78, 'Kitaaba akkaan eegamaa (Lawhal Mahfuuz) keessa jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 79, 'Warra qulqulluu malee (eenyulleen) isa hin tuqu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 80, 'Gooftaa aalama hundaa irraa buufamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 81, 'Sila haasa’a kanaa kan isin laaffiftan?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 82, '(Galata) rizqii (rooba) keessanii kijibsiisuu gootanii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 83, 'sila Yeroo (lubbuun) kokkee geesse, (maaliif hin deebiftanuu)?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 84, 'Odoo yeroo san isin ilaaltanuu,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 85, 'Nuti isin caalaa gara isaatti dhihoo jirra garuu Isin hin argitan malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 86, 'Yoo (kaafamtanii) kan galata hin galfamne taatan (lubbuu san deebisaa).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 87, 'Yoo kan dhugaa dubbattan taatan maaliif hin deebiftanu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 88, 'Yoo inni (namni du’e sun) namoota Rabbitti dhiyeeffaman irraa ta’e,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 89, '(Isaaf) haara galfii, gammachuufi jannata qananiitu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 90, 'Yoo inni warra mirgaa irraa ta’e immoo,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 91, 'Warra mirgaa irraa waan taateef nagaan siif haa jiraatu” (isaan jedhama)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 92, 'Yoo sobsiiftota jallattoota irraa ta’e immoo,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 93, 'Isaaf afeerraa bishaan danfaa irraa ta’etu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 94, 'Jahiim seenuutu isaaf jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 95, 'Inni (wanti suuraan ibsite) kun haqa mirkanaa’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 96, 'Maqaa Gooftaa kee guddaa ta’ee faarsi (qulqulleessi).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 1, 'Wanti samiileefi dachii keessa jiru hundi Rabbiin qulqulleesse. Inni injifataa, Ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 2, 'Mootummaan samiileefi dachii kan Isaati. Inni ni jiraachisa; ni ajjeesas. Inni waan hunda irratti danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 3, 'Inni duruma jira; kan boodaatis; mul’ataadha; dhokataadha Inni waan hunda beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 4, 'Inni Isa samiileefi dachii guyyoota jaha keessatti uumee; ergasii ‘Arshii’ irratti (ol ta’iinsa isaaf malu) ol ta’eedha. Waan dachii keessa gadi seenu nibeeka, waan ishee irraa ba’us, waan samii irraa bu’us, waan ishee keessa ol ba’us (ni beeka). Inni eessallee yoo jiraattan isin waliin jira. Rabbiin waan isin dalagdan hunda ni arga.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 5, 'Mootummaan samiileefi dachii kan Isaati. Dhimmoonni gara Rabbiitti deebifamti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 6, 'Halkan guyyaa keessa galcha; guyyaas halkan keessa galcha. Inni beekaa waan qomoota keessa jiruuti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 7, 'Rabbiifi ergamaa Isaatti amanaa; waan Inni isa keessatti bakka bu’oota isin taasise irraas kennadhaa. Isin irraa isaan amananii, arjooman, isaaniif mindaa guddaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 8, 'Sila maaltu isinii jiraaf Rabbitti amanuu diddan? Odoo ergamaan akka gooftaa keessanitti amantaniif isin waamuu, odoo waadaa keessan isin irraa fuudhee jiruu, yoo mu’uminoota taatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 9, 'Inni Isa gabricha Isaa irratti keeyyattoota ifa ba’aa ta’an buuseedha, dukkanoowwan irraa gara ifaatti isin baasuuf jecha. Allaah’n isin mararfataa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 10, 'Karaa Rabbii keessatti kan hin arjoomne maaltu isiniif tahe? Dhaalli samiileefi dachiis kan Allaah qofa. Isin irraa namni injifannoo (Makkaa) dura arjoomeefi lole (isaan sana booda arjoomaniifi lolan wajjiin) wal hin qixxaatu. Isaan sun warra sana booda arjoomaniifi lolan irra sadarkaa guddaa qabu. Hundaa Rabbiin (mindaa) gaarii waadaa galeefii jira. Rabbiin iccitii waan isin dalagdanii beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 11, 'Namni Rabbiif liqii gaarii liqeessee eenyu laata? kan Inni (Rabbiin) dachaa isaaf taasisu, kan mindaan gaariin isaaf ta’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 12, 'Guyyaa mu’uminoota dhiiraafi dubartootaa argitu kan ifaan isaanii fuuldura isaanitiifi mirgaalee isaanii irra deemu “gammachuun keessan ar’a, oyruu jala isii laggeen yaatuudha isii keessatti hafoo taatanii (isii seentu); Sun milkii guddaadha” (isaaniin jedhama).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 13, 'Guyyaa munaafiqoonni dhiirotaafi dubartootaa isaan amananiin “nu eegaa! Ifaa keessan irraa qabsiifannaa!” jedhan, “Gara booda keessaniitti deebi’aa! Ifaa (achii) barbaadaa” jedhama. Gidduu isaaniitti jogola (dahoo) balbala qabu kan keessoo isaa keessi rahmanni, ala isaa immoo kallattii isaatiin azaabn jiru taasifama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 14, '(Munaafiqoonni) isaan (mu’uminoota) waamaniiti “Nuti isin waliin hin turree?” (jedhuun). nijedhniin “Eeyyeen! Garuu isin lubbuulee keessan jalliftanii, badii keenya eegaa turtanii, (amantiis) shakkitanii, hawwiin sobaa isin gowwoomsitee hanga ajajni Rabbii dhufutti, gowwoomsaan (sheyxaanni) (obsa) Rabbiitiin isin gowwoomse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 15, 'Har’a isiniifi isaan kafaran irraas kafaltiin (furtuun) hin fuudhamu. Teessoon keessan ibidda. Isheen isiniin maltuu teessani. Deebiin waa fokkate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 16, 'Warra amananiif hin dhihaannee, yeroon qalbiin isaanii zikrii Rabbiitiifi dhugaa irraa waan bu’eef laaftu? Akka warra isaaniin dura kitaaba kennamanii tahuu dhabutti (hin dhihaannee?),kan yeroon isaanirratti dheerattee, qalbiileen isaanii goggogdee. baay’een isaan irraa tahe jallatoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 17, 'Beekaa! Rabbiin dachii erga isheen duutee booda jiraachisa. Dhugumatti, keeyyattoota (keenya) isiniif addeessinee jirra akka isin hubattaniif jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 18, 'Dhiiroliin sadaqaa kennatan, dubartoonni sadaqaa kennatte, kanneen liqaa gaarii Rabbiif liqeessan, (mindaan isaanii) dachaa isaaniif taasifamaa. galanni gaariin isaaniif tahe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 19, 'Isaan Rabbiifi ergamoota Isaatti amanani, isaantu warra dhugaan amananiidha. Wareegamtoonni Gooftaa isaanii biratti mindaa isaanitiifi ibsaa isaaniitu isaaniif jira. Isaan kafaranii keeyyattoota keenya sobsiisan immoo isaan sun warra ibiddaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 20, '(Beekaa) Jireenyi addunyaa tapha, gammachuu (yeroo gabaabaa), miidhagina, dhaaddannoo gidduu keessaniitiifi qabeenyaafi ilmaan baay’ifatuu qofa. Akka fakkeenya bokkaa, margi isaa qotee bulaa dinqisiisee, kan ergasii gogee daalachaa’aa ta’uu argitee, ergasii caccabaa ta’eeti. Aakhiratti adabbii cimaa, araaramaafi jaalala Rabbi irraa ta’etu jira. Jireenyi addunyaa meeshaa daguuti malee waan biraatii miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 21, 'Wal dorgomaa Gara araarama Gooftaa keessan irraa ta’eefi jannata bal’inni ishee akka bal’ina samiifi dachii ta’eetti. Isaan Rabbiifi ergamtoota Isaatti amananiif qophoofte. Kun tola Rabbiiti. isa nikenna nama fedheef. Rabbiin abbaa tola guddaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 22, 'Rakkoo irraa wanti dachiifi lubbuu keessan keessatti isin tuqe kamillee, odoo ishee hin uumin dura kitaaba keessatti (galmeessinu) malee hin hafu. kun Rabbi irratti laafaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 23, 'Akka waan isin jalaa dabre irratti hin yaaddofneefi, waan (Rabbiin) isiniif kennettis (garmalee) hin gammadneefi (kana godhe). Rabbiin nama boonaa, dhaaddataa hunda hin jaallatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 24, 'Isaan warra doynoomanii, namallee doynummatti ajajaniidha. Namni (amantii irraa) garagale Rabbiin dureessa faarfamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 25, 'Dhugumatti, ergamtoota keenya ragaawwan ifa ta’aniin erginee, kitaabaafi miizaana isaan waliin buufnee akka namoonni haqaan dhaabbataniif jecha. Sibiilas buufneerra kan isa keessa humna cimaafi namootaaf bu’aawwan jiru goonee. Rabbiin nama Isaafi ergamtoota Isaa fagootti (ghaybiitti) tumsanu mul’isuuf (kana godhe). Rabbiin jabaa, injifataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 26, 'Dhugumatti, Nuuhiifi Ibraahiimiin erginee jirra. Sanyii isaan lamaanii keessatti nabiyyummaafi kitaaba goonee jirra. Isaan irraa namoota qajeelantu jira; baay’een isaan irraa ta’an immoo finciltoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 27, 'Ergasii faana isaanii irra ergamtoota keenya hordofsiifne. Iisaa ilma Maryamis hordofsiifnee, Injiiliin isaaf kenninee jirra. Onneewwan warra isa (Iisaa) hordofanii keessattis namaaf rifatuufi gara laafummaa goone. Moloksummaa ishee ni eegalan. Jaalala Rabbii barbaaduuf (eegalan) malee Nuti isaan irratti hin barreessine. (Garuu) dhugaa eeggachuu ishee hin eegganne. Isaan irraa warra amananiif mindaa kennina. Baay’een isaanii immoo finciltoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 28, 'Yaa warra amantan! Rabbiin sodaadhaa. Ergamaa Isaatti (Muhammadittis SAW) amanaa! (Rabbiin) rahmata Isaa irraa dachaa lama isiniif kenna; ifaa ittiin deemtanis isiniif taasisa; isiniifis ni araarama. Rabbiin araaramaa, mararfataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 29, 'Akka beekaniifi Abbootiin kitaabaa (Yahuudonniifi Kiristaanonni) qananii Rabbii irratti homaa akka hin dandeenye, qananiin harka Rabbii akka jiruufi Inni nama fedheef akka kennu (haa beekanuuf kana ibse). Rabbiin abbaa tola guddaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 1, 'Dhugumatti Rabbiin dhaga''eera jecha ishee siin falmituu waa''ee abbaa manaa ishee keessatti, tan gara Rabbiitti himannaa dhiyeeffattuu (dhagayeera). Rabbiin falmii keessan lamaan ni dhaga''a. Rabbiin dhagayaa, argaadha.[1]', '[1] intalti sun kowla binti sa''ilabaa jedhamti. jaarsa isii owsi binu ssaamit Nabitti himatte. kana Rabbiin dubbate.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 2, 'Isaan isin keessaa dubartoota (haadhotii manaa) isaanii irraa ‘Zihaara’ godhan (‘ati anaaf akka dugda haadha kiyyaati’ jechuun kakatan), isaan (haadhotiin manaa) haadholii isaanii miti. Haadholiin isaanii hintaane isaanuma isaan da''an san malee. dhugumatti Isaan jecha fokkataafi soba dubbatu. Rabbiinis dhiifama godhaa araaramaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 3, 'Isaan dubartoota isaanii irraa "Zihaara" godhanii ergasii waan jedhanitti deebi''an, odoo wal hin tuqin dura morma (gabraa) bilisa baasuutu isaan irra jira. Kana akka isin ittiin gorfamtaniif (Rabbiin jaje). Rabbiin waan isin hojjattan keessa beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 4, 'Namni hin argatin, odoo wal hin tuqin dura ji''oota walitti aanan lama soomuutu isaan irra jira. Namni (kana) hin danda''in, miskiinoota (hiyyeeyyii) jaahaatama nyaachisuu qaba. Kun akka Rabbiifi ergamaa Isaatti amantaniifi. isheen tun daangaalee Rabbiiti. Kaafirootaf adabbii laaleessaa ta''etu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 5, 'warren Rabbiifi ergamaa Isaa faallessan akkuma warri isaaniin duraa salphatan salphataniiru, Nuti dhugumaan ragaalee ifaa buufnee jirra. Kaafirootaaf adabbii xiqqeessaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 6, 'Guyyaa Rabbiin hunda isaanii kaasee waan isaan hojjatan isaanitti himu [yaadadhu]. Rabbiin beekee galmeessera isaan isa dagatan. Rabbiin waan hunda irratti ragaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 7, 'Sila Rabbiin waan samiilee keessa jiruufi waan dachii keessa jiru kan beeku ta''uu hin argituu? Maqoon (iccitiin) gidduu namoota sadiitti tahee Inni afraffaa isaanii ta''u malee hin hafu, giddu namoota shaniitti tahee Inni jahaffaa isaanii ta''u malee hinhafu, (giddu namoota) sanaa gadiis ta''ee kan sanarra hedduu iddoma isaan ta’anitti isaan waliin ta’u malee hinhafu. Ergasii, Guyyaa Qiyaamaa waan isaan dalagan (hunda) isaanitti odeessa. Rabbiin waan hunda irratti beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 8, 'Sila ati hin laallee gara warra maqoo (badaa) irraa dhorgamanii, ergasii gara waan irraa dhorgamaniitti deebi''anii, kan maqatanii (dhooysaan maruyatanii) badii, miidhaafi ergamicha faallessuu irratti (hin ilaallee?) Yeroo sitti dhufanis waan Rabbiin ittiin nagaa si hin gaafatiniin nagaa si gaafatu. Lubbuulee isaanii keessatti (Gidduu isaaniitti) (dhuguma Muhammad yoo nabiyyii ta’eef) Rabbiin maaliif waan nuti jennuun nu hin adabne? " jedhu. Jahannam isaaniif geessuudha; ishee seenu. Deebichi (isaanii) waa fokkate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 9, 'Yaa warra (Rabbitti) amantan! Yeroo iccitii dubbattan badii, miidhaafi faallaa ajaja ergamaa Rabbii irratti hin mari''atinaa. toltuufi sodaa Rabbii irratti mari''adhaa. Rabbii gara Isaatti oofamtan sodaadhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 10, 'Iccitiin (badaan) sheyxaana qofa irraayi. (Sheyxaanni) warra amanan ittiin gaddisiisuf (kana hojjata). Waan tokkollee isaan miidhaa hintaane hayyama Rabbiitiin malee. Mu’uminoonnis Rabbiin qofa irratti haa hirkatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 11, 'Yaa warra (Rabbitti) amantan! Yeroo teessumaalee keessa waliif babal''isaa isiniin jedhame waliif babal''isaa; Rabbiin isiniif bal''isaa. Yeroo ka''aa jedhames ka''aa. Rabbiin isin irraa warra amananiifi isaan beekumsi kennameef sadarkaalee isaan ol kaasa. Rabbiin waan isin hojjattan keessa Beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 12, 'Yaa warra (Rabbitti) amantan! Yeroo ergamaa (Rabbii) wajjiin maqoo gochuu feetan, maqoo keessan dura sadaqaa dursaa (kennaa). Kun isiniif irra caalaafi (dilii keessaniifis) irra qulquleessaadha. Yoo (waan sadaqaa kennitan) hin argatin immoo Rabbiin Araaramaa Rahmata Godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 13, 'Sila maqoo keessan (kan Nabiyyii SAW wajjiin gootan) dura sadaqaalee dursuu sodaattanii? Yoo raawwachuu baattanis Rabbiin dhiifama isiniif godheera. Salaata dhaabaa; zakaas kennaa; Rabbiifi ergamaa Isaatiif ajajamaa. Rabbiin waan isin hojjattan keessa beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 14, 'Sila gara Isaan namoota Rabbiin itti dallane (Yahuudota) jaalallee godhatanii hin agarree? Isaan isin irraayis miti; isaan irraayis miti; kijiba irratti kakatu odoo beekanuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 15, 'Rabbiin adabbii cimaa isaanif qopheessee jira. Isaan wanti isaan hojjachaa turan waa fokkate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 16, 'Kakuulee isaanii gaachena taasifatan. karaa Rabbii irraa (namoota) deebisan. Isaaniif adabbii xiqqeessaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 17, 'Qabeenyaaleen isaaniifi ijoolleen isaaniis (adabbii) Rabbii irraa wama tokko isaan hin duroomsanu. Isaan sun warra Ibiddaati; isaan ishee keessatti hafoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 18, 'Guyyaa Rabbiin hunda isaanii (murtiif) kaasu sana akkuma isiniif kakatan Isaafis (Rabbiifis) kakatu. Waan (haqa) wahii irra jiran of se''u. Dhagayaa! isaan isaanumatu sobdoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 19, 'Sheyxaanni isaan irratti moo''ee faaruu Rabbii isaan dagachiisee. raIsaan garee sheyxaanati. Dhaga''aa! Gareen sheyxaanaa isaanumatu hoonga’oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 20, 'Isaan Rabbiifi ergamaa isaa faallessan, isaan sun warra gadi aanoo keessa ta’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 21, 'Rabbiin Barreesse "dhugumatti, Anaafi Ergamtoonni Kiyya ni mo''anna" (jechuun). Rabbiin Jabaa, Injifataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 22, 'Hin argitu Ummata Rabbiifi Guyyaa Aakhiraatti amanan, namoota Rabbiifi ergamaa Isaa morman kan jaallatanu hin argitu. odoma abbootii isaanii tahanillee, yookiin ilmaan isaanii, yookiin obboleeyyan isaanii, yookiin firoota isaanii (ta''anillee). Isaan sana (Rabbiin) onneelee isaanii keessatti iimaana barreessee jira. qilleensa (tumsa) Isa irraa ta''eenis isaan jabeesseera. Jannatoota laggeen ishee jala yaatu isaan seensisa achi keessaatti hafoo haala ta''aniin. Rabbiin isaan irraa jaallateera; isaanis Isa irraa jaalataniiru. Isaan tuuta Rabbiiti. Dhagayaa! cifraan (gareen) Rabbii isaantu milkaawoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 1, 'Wantoonni samiilee keessaafi wantoonni dachii keessaa (hundi) Rabbiin qulqulleesse. Inni Injifataa Ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 2, 'Inni Isa abbootii kitaabaa irraa isaan kafaran godaansa jalqabaatiif gandoota isaanii irraa baaseedha. Bahuu isaanii isin hin yaadne turtan. Isaanis da''annoowwan isaanii Rabbi irraa nu dhowwa jechuu yaadani. Rabbiin bakka isaan hin yaadin irraan isaanitti dhufee, onneelee isaanii keessatti sodaa darbe. Manneen isaanii harkoowwan isaaniifi harkoowwan mu’uminootaatiin diigan. Yaa warra sammuulee mee xiinxalaa!!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 3, 'Odoo Rabbiin (Madiinaa keessaa) baqa isaan irratti barreessuu baatee, silaa addunyaa keessatti isaan adaba ture. Isaaniif Aakhiraa keessatti adabbii ibiddaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 4, 'Kun sababa isaan (ajaja) Rabbiifi ergamaa Isaa didaniifi. Nama (ajaja) Rabbii dide (Rabbiin isa adaba) Rabbiin adabbiin isaa cimaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 5, 'Muka timiraa irraa wanti isin murtan yookiin akkuma hundee ishee irra dhaabattetti dhiiftan eeyyama Rabbiitiini. (wanti Rabbiin kana godheef) finciltoota salphisuufi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 6, 'Waan Rabbiin isaan (qabeenya isaanii) irraa ergamaa Isaa irratti deebise isin isa irratti fardaafi gaalas hin gulufsiifne. Garuu Rabbiin ergamtoota Isaa abbaa fedhe irratti moosisa. Rabbiin waan hunda irratti danda''aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 7, 'Wanti Rabbiin (qabeenya) warra magaalaa irraa ergamaa Isaa irratti deebise Rabbiifi, ergamaafi, fira dhihoo (ergamaa)fi, yatiimotaafi, hiyyeeyyiifi nama imala irra jiruuf (haqa godhame). akka jidduu dureeyyii isin irraa ta''aniitti kan naanna''u hin taaneef jecha. Waan Ergamichi (Kiyya) isiniif kenne qabadhaa. Waan inni irraa isin dhowwes dhowwamaa. Rabbiin sodaadhaa. Rabbiin adabbiin Isaa cimaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 8, 'Hiyyeeyyii godaantotaa warra manneeniifi qabeenya isaanii irraa baafamaniif tola Rabbiifi jaalala isaa barbaacha, akkasumas Rabbiifi ergamaa Isaatii tumsuuf jecha (baafamaniif kennama). Isaan sun isaanumatu warra dhugaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 9, 'Warri isaaniin dura biyyattii qubsuma godhataniifi Iimaana (qabatan), namoota gara isaanii godaanan ni jaallatu. Waan (Muhaajirootaaf) kenname irrattis qoma isaanii keessatti jibbaa tokkollee hin arganu. lubbuu isaanii irra (muhaajiroota) dursu osoo rakkoon isaanitti jiraatellee. Namni doynummaa lubbuu isaa tikfaman, isaan isaanumaatu milkaa’oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 10, 'Warri booda isaaniitii dhufan nijedhan "Yaa Gooftaa keenya! Nuufi obboleeyyan keenya warra iimaanaan nu dursaniif araarami. onneewwan Keenya keessa jibbaa warra amananiif hin taasisin. Gooftaa keenya! Ati mararfataa rahmata oolaadha".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 11, 'Sila gara warra munaafiqa ta''anii hin ilaallee? Obboleeyyan isaanii kan warra kitaabaa irraa ta''anii kafaraniin ni jedhu "Yoo isin baafamtaniif isinii wajjiin baana; waa''ee keessan keessattis yoomuu, eenyuuniyyuu hin ajajamnu; yoo isin lolamtanis dhugaatti isin gargaarra". Rabbiinis akka isaan kijibdoota ta''an ragaa ba''a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 12, 'yoo isaan baafamani isaanii wajjiin hin ba''anu; yoo isaan lolaman isaanii hin tumsanu; odoma isaanii tumsaniiyyuu dugda duuba gara galu (ni dheessu); ergasii his hin tumsamanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 13, 'Dhugumatti, isintu gama sodaatamuutiin onnee isaanii keessatti Rabbi irra cimaadha. Kun waan isaan ummata hin hubanne ta''aniifi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 14, 'Waliin ta''anii isin hin waraanan Yoo magaalota da''annaan marfamte keessa ta''an yookiin dallaa duubaan ta''e malee. Diinummaan isaanii gidduu isaaniitti cimaadha. tokkummaa qaban isaan seeta onneewwan isaanii qoqqoodamtuudha. Kun waan isaan namoota hin xiinxalline ta''aniifi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 15, '(Fakkeenyi isaanii) akka warra isaaniin dura yeroo dhihootti adabbii sani. dalagaa isaanii dhandhaman. Isaaniif adabbii laalessaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 16, 'Akka fakkii sheyxaanaa yeroo inni ilma namaatiin kafari jedhe. yeroo inni kafare "ani sirraa qulqulluudha; ani Rabbii Gooftaa aalamaan sodaadha" jedheeti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 17, 'Xumurri isaan lamaaniituu ibidda keessa ta''uudha tahe keessatti hafoo ta''anii. Kun galata zaalimtootaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 18, 'Yaa warra amantan! Rabbiin sodaadhaa. Lubbuun tamuu waan boruuf durfatte haa laaltu. Rabbiin sodaadhaa Rabbiin waan isin hojjattan hunda keessa beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 19, 'Akka warra Rabbiin dagatanii lubbuulee isaanii isaan dagachiisee hin ta''inaa, Isaan isaanumatu finciltoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 20, 'Warri ibiddaafi warri Jannataa wal hin qixxaatan. Warri Jannataa isaanumatu milkaa''oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 21, 'Odoo Qur''aana kana gaara irratti buufnee, silaa isa nigarta sodaataa dhodhoohaa sodaa Rabbiirraa. Fakkeenyota tana namootaaf taasifna akka isaan xiinxalaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 22, 'Inni Allaahn Isa gabbaramaan dhugaa isa malee hin jirre. (Inni) Beekaa fagoofi dhihooti. Inni akkaan rahmataa godhaa akkaan mararfataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 23, 'Inni Allaahii Isa gabbaramaan dhugaa isa malee hin jirre, mootii, hir''ina irraa qulqulluu, abbaa nagayaa, nageenya arjoomaa, Qeexaa (toohataa), injifataa, guddaa (ol ta''aa), boonaadha. Rabbiin qulqullaa''e Waan isaan qindeessan hunda irraa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 24, 'Inni Rabbii, Uumoo (waan hundaa), (waan hin jirre) Argamsiisaa, kan bocaa bareechaa ta''eedha. Isaaf maqoolee gaggaariitu jira. Wantoonni samiileefi dachii keessaa Isa qulqulleessu (faarsu). Inni Injifataa ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 1, 'Yaa warra amantan! Diina kiyyaafi diina keessan jaalalleewwan hin godhatinaa. kan isin gara isaaniitti jaalala dhaqqabsiiftan (hingodhatinaa). dhugaa irraa waan isinitti dhufetti kafaranii jiran. Ergamichaafi isinis baasanii jiranuu, sababa isin Rabbii Gooftaa keessan ta''etti amantaniif qofa. Yoo karaa Kiyya keessatti qabsaa''uufi jaalala Kiyya barbaacha kan baatan taataniif (jaalalloo hin godhatinaa). kan gara isaaniitti iccitiin jaalala dhaqqabsiiftan (hingodhatinaa). Ani waan isin dhoksitaniifi waan isin ifa gootan ninbeeka. Isin irraa namni kana hojjate dhugumatti karaa qajeelaa irraa jallateera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 2, 'Yoo isin arganiif diinota isiniif ta''u. Harkoowwaniifi arraboowwan isaanii hamtuun gara keessanitti diriirsu. osoo kafartanii jaalatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 3, 'Firoonni keessaniifi ilmaan keessanis homaa isin hin fayyadanu; Guyyaa Qiyaamaa (Rabbiin) jidduu keessan addaan isin baasa. Rabbiin waan isin hojjattan argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 4, 'Dhugumatti, Ibraahimiifi warra isa wajjiin turan keessatti hidhannoon gaariin isiniif ta''eera. Yeroo (isaan) ummata isaaniitiin jedhan "nuti isiniifi waan isin Rabbiin alatti gabbartan irraa qulqullaawoodha; isinitti kafarre; gidduu keenyaafi gidduu keessanitti diinummaafi jibbansi abadii ifa ba''eera hanga Rabbii tokkichatti amantanutti" (jedhan) (kana keessatti hidhannoon gaariin isiniif jira). Jecha Ibraahiim malee kan abbaa isaatiin "araaraman siif kadhaa (adabbii) Rabbii irraa immoo homaa siif hin fayyadu" "Gooftaa keenya! Sirratti hirkanne; gara Keetti deebine; deebiin garuma kee qofa" (jedhan san hordofaa).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 5, '"Gooftaa keenya! warra kafaraniif mokkoroo nu hin godhin. Gooftaa keenya! Nuuf araarami; Ati injifataa ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 6, 'Dhugumatti, isaan keessa hidhannoo gaariitu isiniif jira nama Rabbiifi Guyyaa Aakhiraa kajeeluuf. Namni (kanarraa) garagale (ofuma miidha) Rabbiin inni dureessa faarfamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 7, 'Rabbiin gidduu keessaniifi gidduu warra isin isaan irraa diinomfattanii (nyaapha godhattanii) jaalala taasisuun ni kajeelama. Rabbiin Danda''aadha. Ammas Rabbiin araaramaa rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 8, 'Rabbiin isin hindhoowwu isaan sababaa amantiitiin isin hin waraaniniifi manneen keessan irraa isin hin baasiniif tola ooluufi haqaa isaanitti hojjachuu isin hin dhorgu. Rabbiin warra haqa dalagan jaalata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 9, 'Kan Rabbiin isin dhorgu warra sababaa amantiitiin isin waraananiifi manneen keessan irraa isin baasan, akkasumas isin baasuu irratti gargaaran isin isaan jaalalloo godhachuu (irraa isin dhoowwa). Namni isaan jaalalloo godhate, isaan isaanumaatu zaalimoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 10, 'Yaa warra amantan! Yeroo dubartoonni mu’uminaa godaantuu ta''anii isinitti dhufan (amantiif godaanuu isaanii baruuf) isaan qoradhaa. Iimaana isaanii Rabbiin beekaa. Yoo mu’uminoota ta''uu isaanii bartan gara warra kafaraniitti isaan hin deebisnaa. Isaan (dubartoonni) isaaniif halaalii miti; isaanis (dhiironni) isaaniif halaalii miti. Isaaniif (dhirsota isaanii kan kaafiraatiif) waan isaan baasan kennaa. Yeroo mahrii isaanii isaaniif kennitan isaan fuuchuun diliin isin irra hin jiru. Waadaalee fuudhaa kan niitiwwan keessan kaafiraa hin qabatinaa (nikaan diigameera). Isinis waan isaan (niitolii keessan kan kufrii irra jiran) irratti baaftan gaafadhaa; isaanis (dhirsotiin kaafiraa kan niitolii isaanii amanan) waan baasan haa gaafatani. Kun murtii Rabbiiti (Isatu) gidduu keessanitti murteessa. Rabbiin beekaa ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 11, 'Yoo tokkoon niitolee keessan irraa taate gara kaafirootaa isin jalaa baatee ergasii loltanii boojitan isaan niitoleen isaanii deemaniif fakkaataa waan isaan baasanii kennaafii. Rabbii isa itti amantan sodaadhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 12, 'Yaa Nabiyyichaa! Yeroo dubartoonni mu’uminaa waadaa sii galuuf gara kee dhufan, (wanni irratti waadaa galan) Rabbitti homaa qindeessuu dhiisuu, hatuu dhiisuu, Zinaa godhuu dhabuu, ijoollee isaaniis ajjeesuu dhiisuu, cubbuu harka isaaniitiifi miila isaanii gidduutti uumanii odeessuu dhabuufi akka waan gaarii keessatti ajaja kee hin faallessine waadaa isaan irraa fuudhi. Rabbiinis araarama isaaniif kadhu. Rabbiin araaramaa rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 13, 'Yaa warra amantan! Ummata Rabbiin irratti dallane jaalallee hin godhatinaa. Akkuma kaafiroonni warra qabrii irraa abdii muratan isaanis Aakhiraa irraa dhugumatti abdii murataniiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 1, 'Wantoonni samiilee keessaafi wantoonni dachii keessaa (hundi) Rabbiin qulqulleesse. Inni injifataa ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 2, 'Yaa warra amantan! Maaliif waan hin hojjanne jettu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 3, 'Waan hin hojjanne haasa''uun keessan jibbaansi isaa Rabbiin biratti guddate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 4, 'Rabbiin warra karaa Isaa keessatti akka ijaarsaa wal qabataa ta''anii hiriiraan lolan ni jaalata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 5, 'Yeroo Muusaan ummata isaatiin jedhe "yaa ummata (kiyya) maaliif na rakkiftan! Odoo akka ani Ergamaa Rabbii kan gara keessanitti (ergame ta''uu) sirriitti beektanuu?" [jedhe yaadadhaa]. Yeroma isaan jallatanu Rabbiin onneewwan isaanii jallise. Rabbiin ummata finciltoota hin qajeelchu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 6, 'Yeroo Iisaa ilma Maryam jedhe "yaa ilmaan Israa''iil! Ani Ergamaa Rabbii kan isinitti ergameedha. kan waan Tawraatiin keessatti na dura bu''e dhugoomsuufi ergamaa na booda dhufu kan maqaan isaa Ahmad ta''een (isin) gammachiisu ta''ee" (jedhe yaadadhaa). Yeroma inni ragaawwan ifaan isaanitti dhufe "kun ''sihrii'' (falfala) ifa galaa dha" jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 7, 'Nama Rabbi irratti kijiba uumee odeesse caalaa namni miidhaa hojjate eenyu odoo gara Islaamaa waamamuu?. Rabbiin ummata miidhaa raawwattoota hin qajeelchu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 8, 'Ifa Rabbii afaanoowwan isaaniitiin dhaamsuu fedhu.Rabbiin ifa Isaa ni guuta Odoma kaafiroonni jibbaniiyyuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 9, 'Inni Isa ergamaa Isaa qajeelfamaafi amantii haqaatiin ergeedha amantiiwwan biraa hunda irratti ol taasisuuf jecha, odoo mushrikoonni jibbanuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 10, 'Yaa warra amantan! Mee daldala azaaba laalessaa irraa isin baraarsu irratti isin qajeelchuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 11, 'Rabbiifi ergamaa Isaatti amantu, akkasumas karaa Rabbii keessatti qabeenyaaleefi lubbuulee keessaniin qabsooftu, kanatu (waan hunda) isiniif caala Yoo kan beektan taataniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 12, '(Yoo kana dalagdaniif Rabbiin) badiilee keessan isiniif araarama. Jannatoota laggeen jala ishee yaatus isin seensisa. Manneen babbareedaa Jannata qubannaa keessattis (isiniif qopheessee jira). Kun milkii guddaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 13, 'Waan biraas kan isin jaalattan (isiniif kenna) (Isheenis) tumsa Rabbi irraa ta''eefi banamuu (Makkaa) dhihoo ta''eedha. Mu’uminoota gammachiisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 14, 'Yaa warra amantan! tumsitoota Rabbii ta''aa, Akkuma Iisaa Ibnu Maryam hawaariyyootaan "(waamicha ani) gara Rabbiitti (godhu irratti) namni na tumsu eenyu?" jennaan hawaariyoonnis "nutu tumsitoota Rabbiiti" jedhan san. Ilmaan Israa''iil irraa gartokkeen amananii gartokkeen kafaran. Isaan amanan san diinota isaanii irratti jabeessinee injifatoo ta''an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 1, 'Wanti samiilee keessaafi wanti dachii keessaa Rabbi qulqulleessa. (inni) mootii, qulqulluu, injifataa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 2, 'Inni Isa ummata wallaalaa keessatti ergamaa isaan irraa ta''e ergeedha, kan keeyyattoota Isaa isaan irratti qara''u, (shirkii irraayis) isaan qulqulleessuufi kitaabaafi ogummaa isaan barsiisu ergeedha. Isaanis (ergamuu isaatiin) dura jallinna ifa ta''e keessa turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 3, '(Ummata) biroos kan isaan irraa ta''anii isaanitti hin dhaqqabiniifis (isa erge) Inni injifataa ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 4, 'Kun tola Rabbiiti Isa abbaa fedheef kenna. Rabbiin abbaa tola guddaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 5, 'Fakkeenyi warra Tawraatiin baachifamanii ergasii isii hin baadhatinii (ittiin hin hojjatinii) akka fakkeenya harree kitaabota gurguddaa baadhattuuti. Fakkeenyi ummata keeyyattoota Rabbii sobsiisanii akkaan waa fokkatee! Rabbiin ummata miidhaa raawwattoota hin qajeelchu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 6, 'Jedhi "isin Yaa warra yahuudomtan! Namni biraa odoo hafuu isin qofatu jaalalloo Rabbiiti kan jettan yoo taataniif, yoo nama dhugaa dubbatu taataniif du''a hawwaa".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 7, 'yoomuu isa hin hawwanu Sababa waan harki isaanii dabarsiteef jecha. Rabbiin miidhaa raawwattoota beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 8, 'Jedhi "dhugumatti, duuti inni isin isa irraa baqattan sun inni isin argataadha. Ergasii gara beekaa fagoofi dhihoo ta''eetti deebifamtanii waan isin dalagaa turtan isinitti hima".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 9, 'Yaa warra amantan! Yeroo guyyaa Jimaataa keessatti salaataaf lallabame gara zikrii Rabbii deemaa; gurgurtaa dhiisaa. kanatu isiniif caala Yoo kan beektan taataniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 10, 'Yeroo salaatattiin xumuramte immoo dachii keessa faca''aa; tola Rabbii irraa barbaaddadhaa. baay''inaan Rabbiin faarsaa Akka milkooftaniif jecha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 11, 'Yeroo daldala yookiin tapha argan gara isaaniitti faffaca''u dhaabiitti si dhiisanii; Jedhiin "wanta Rabbiin bira jirutu taphaafi daldala irra caala. Rabbiin Irra caalaa arjootaati" jedhiin', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 1, 'Munaafiqoonni yeroo sitti dhufan "ati Ergamaa Rabbii ta''uu kee ragaa baana" jedhu. Dhugumatti Rabbiin ati Ergamaa isaa ta''uu ni beeka. Munaafiqoonni kijibdoota ta''uu Rabbiin ragaa ba''a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 2, 'Kakuulee isaanii gaachana godhatanii karaa Rabbii irraa (namoota) deebisan. Isaan wanti isaan dalagaa turan fokkate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 3, 'Kun sababa isaan amananii ergasii kafaraniifi, onneewwan isaanii irratti cufame, isaan hin hubatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 4, 'Yeroo isaan argite qaamoleen isaanii si dinqisiifti. Yoo isaan haasa''anis dubbii isaanii ni dhageeffata. Isaan akka mukkeen hirkifameeti. Iyya hundaa isaan irratti (iyyame) jechuu yaadu. Isaanumatu diinota; kanaafuu isaan eeggadhu. Rabbiin isaan haa abaaruu akkamitti (amantii irraa) deebi''u!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 5, 'Yeroo "kottaa Ergamaan Rabbii araarama isiniif haa barbaadu" isaaniin jedhame mataalee isaanii naannessu, Kan isaan boonaa gara galan ni argita.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 6, 'Araarama isaanii barbaaddus isaanii barbaaduu dhiiftus isaan irratti wal qixa; Rabbiin isaaniif hin araaramu. Rabbiin ummata finciltoota hin qajeelchu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 7, 'Isaan warra "namoota Ergamaa Rabbii bira jiranu isaan irratti hin arjoominaa hanga isaan faffaca''anutti " jedhanuudha. Kuusaaleen samiileefi dachii kan Rabbiiti; garuu munaafiqoonni hin hubatanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 8, 'Nijedhan "Yoo gara Madiinaa deebine, dhugumatti, (nuti) injifattoonni ishee irraa salphattoota baasuuf jira". Injifannoon kan Rabbiiti, kan Ergamaa Isaatiifi kan mu’uminootaati; garuu munaafiqoonni hin beekan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 9, 'Yaa warra amantan! Qabeenyaaleen keessaniifi ilmaan keessan zikrii Rabbii irraa isin hin dagin, Namni kana dalage isaan isaanumatu hoonga''oota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 10, 'Waan nuti isiniif kennine irraa kennadhaa Odoo tokkoon keessan duuti itti dhuftee hinjenneen dura. "Gooftaa kiyya! Odoo hanga beellama gabaabaatti na tursiiftee, silaa dhugumatti, sadaqadheen warra gaggaarii irraayis ta''a"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 11, 'Rabbiin lubbuu tokko yeroo beellamni ishee dhufe hin tursiisu. Rabbiin keessa Beekaa waan isin dalagdaniiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 1, 'Wanti samiilee keessaafi wanti dachii keessaa hundi Rabbiin qulqulleessa. Mootummaan kan Isaati; faarunis kan Isaati. Inni waan hunda irratti danda''aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 2, 'Inni Isa isin uume Isin irraa Kaafirris ni jira; isin irraa Mu''uminnis ni jira. Rabbiin waan isin dalagdan argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 3, 'Samiileefi dachii dhugaan uume. Isinis bocee boca keessan bareeche, Deebiin garuma isaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 4, 'Wantoota samiileefi dachii keessa jiru hunda ni beeka; akkasumas waan isin dhoksitaniifi waan isin ifa gootan ni beeka. Rabbiin waan qomoowwan keessaa beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 5, 'Sila oduun warra duraan kafaranii isinitti hin dhufnee! adabbii kufrii isaanii dhandhaman, Isaaniif ibidda laalessaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 6, 'Kunis sababa ergamooleen isaanii ragaa iftuudhaan isaanitti dhufnaan "sila namatu nu qajeelchaa?" jedhanii kafaranii irraayis garagalaniifi. Rabbiinis of ga''e. Rabbiin dureessa faarfamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 7, 'Isaan kafaran (erga du''anii) hin kaafamanii dubbatan jedhiin "Lakkii! Gooftaa kiyyatti kakadhee ni kaafamtu; ergasii wanti dalagdan hunduu isinitti himama. Sun Rabbirratti laafaa dha".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 8, 'Rabbiifi Ergamaa Isaatti amanaa. akkasumas ifaa isa Nuti buufnetti (amanaa). Rabbiin waan isin hojjattan hunda keessa beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 9, 'Guyyaa wal gahichaatiif guyyaa (Rabbiin) walitti isin qabu san [yaadadhaa]. Sun guyyaa wal gowwoomsuuti. Namni Rabbitti amanee toltuu dalage (Rabbiin) diliilee isaa isarraa harcaasa. Jannatoowwan jala ishee laggeen yaatu isa seensisa haala isii keessatti abaditti hafoo ta''aniin. Sun milkii guddaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 10, 'Isaan kafaranii keeyyattoota keenya sobsiisan, isaan warra ibiddaati ishee keessatti hafoodha. (Isheen) deebii ta''uun waa fokkatte!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 11, 'Hamtuu irraa wanti tokkollee eeyyama Rabbiitiin malee nama hin tuqu. Nama Rabbitti amane qalbii isaa ni qajeelcha. Rabbiin waan hunda beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 12, 'Rabbiif ajajamaa; Ergamichaafis ajajamaa, Yoo gara galtan wanti Ergamaa Keenya irra jiru (ergaa itti kenname) dhaqqabsiisuu mul''ataa qofa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 13, 'Rabbiin, dhugaan gabbaramaan isa malee hin jiru. Mu''uminoonnis Rabbi irratti qofa haa hirkatanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 14, 'Yaa warra amantan! niitolii keessaniifi ilmaan keessan irraa warra isiniif diinaatu jira; kanaafuu, isaan eeggadhaa. Yoo dhiifama gootanii irra dabartaniifii araaramtan (sanatu isiniif caala). Rabbiin araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 15, 'Qabeenyaaleen keessaniifi ilmaan keessan mokkoroodha. Rabbiin Isa bira mindaa guddaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 16, 'Hanga dandeessan Rabbiin sodaadhaa; dhagayaa; (Isaafis) ajajamaa; arjoomaas; sanatu lubbuulee teessaniif caala. Namni don''ummaa lubbuu isaa (irraa) tikfame, isaan isaanumatu milkaa''oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 17, 'Yoo liqii gaarii Rabbiif liqeessitan, dachaa isiniif godha; isiniif araaramas. Rabbiin galateeffataa obsaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 18, '(Rabbiin) beekaa fagoofi dhihoo injifataa, ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 1, 'Yaa Nabiyyichaa! Yeroo dubartoota hiiktan, ''Iddaa'' isaaniitiin isaan hiikaa Iddaas lakkaa''aa. Rabbii Gooftaa keessan sodaadhaa. manneen isaanii irraa isaan hin baasinaa 
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 2, 'Yeroo beellama isaanii ga''an haala gaariin isaan qabadhaa yookiin haala gaariin isaaniin adda ba''aa, Isin irraa warra haqaa (nama) lama ragaa godhaa (Warri ragaa baatanus) Rabbiif jedhaatii ragaa sirreessaa. Namni Rabbiifi Guyyaa Aakhiraatti kan amanu ta''e kanaan gorfama. Namni Rabbiin sodaatu (Rabbis) karaa bahiinsaa isaaf godha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 3, 'Bakka inni hin yaadin irraayis isa soora. Nama Rabbi irratti hirkatuuf Inni isaaf ga''aadha, Rabbiin ajaja isaa bakkaan ga''aadha. Dhugumatti Rabbiin waan hundaafuu yeroo murtaawaa taasiseera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 4, 'Dubartoota keessan irraa isaan xurii laguu (haydii) irraa guddatan yoo shakkitan iddaan isaanii ji''a sadi Isaan haydii arguu hin jalqabinis (akkasuma). Warri ulfa ta''an immoo baallamni isaanii ulfa isaanii da''uudha. Nama Rabbiin sodaatu (Rabbiin) dhimma isaa irraa laafina isaaf godha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 5, 'Kun ajaja Rabbii kan gara keessanitti isa buuseedha. Nama Rabbiin sodaatu (Rabbiin) badiilee isaa isa irraa harcaasa mindaas isaaf guddisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 6, 'Dandeettii keessan irraa bakka qubattanu isaan qubsiisaa. Isaan irratti dhiphisuuf jecha isaan hin rakkisinaa. Yoo warra ulfaa ta''an hanga ulfa isaanii da''anitti isaan qallabaa. Yoo isiniif hoosisan mindaalee isaanii isaaniif kennaa. Jidduu keessanitti haala gaariin mari''adhaa. Yoo wal rakkiftan tan biraa isaaf hoosisti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 7, 'Abbaan dandeettii qabu dandeettii isaa irraa haa qallabu. Namni hireen isaa isa irratti dhiphifame, waan Rabbiin isaaf kenne irraa haa qallabu. Rabbiin lubbuu kamiyyuu waan isheedhaaf kenne malee hin dirqisiisu. Rabbiin dhiphina booda bal''ina godhuuf jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 8, 'Magaalota irraa heddutu ajaja Rabbii isheefi ergamtoota isaa faallessitee qormaata cimaa ishee qormaannee adabbii fokkataas ishee adabne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 9, 'Sababa kanaan adabbii dalagaa ishee dhamdhamte Booddeen dubbii ishees hongoo ta''e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 10, 'Rabbiin adabbii cimaa isaaniif qopheesse. Yaa warri sammuulee qabdan, warri amantan Rabbiin sodaadhaa. Dhugumatti Rabbiin gara keessanitti gorsa buuseera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 11, 'Ergamaa (erge) kan keeyyattoota Rabbii ibsituu taate isin irratti dubbisu, Warra amananii gaggaarii hojjatan dukkanoota keessaa gara ifaatti akka baasuuf jecha. Nama Rabbitti amanee gaarii dalage jannatoota jala ishee laggeen yaatu isa seensisa. ishee keessatti zalaalam hafoodha. Dhugaatti Rabbiin isaaf hiree bareecheera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 12, 'Rabbiin Isa samii torbaniifi dachii irraayis fakkiidhuma isaanii uumeedha. Ajajni jidduu isaaniitti bu''a(. Wanti inni kana uumeefis) akka isin Rabbiin waan hunda irratti danda''aafi Rabbiin beekumsaan wantoota cufa marsuu isaa beektanuufi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 1, 'Yaa Nabiyyichaa! Maaliif waan Rabbiin halaala siif godhe haraama goota haadholee manaa tee jaalachiisuu barbaachaaf ? Rabbiin araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 2, 'Dhugumatti, Rabbiin karaa kakuulee keessan ittiin hiiktan isiniif murteesseera. Rabbiin gargaaraa keessani. Inni beekaa ogeessa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 3, 'Yeroo Nabiyyichi gara garii niitolee isaatti iccitii wahii himu [yaadadhaa]. Yeroo isheen isa odeessitee Rabbiinis isa isatti beeksisu, garii isaa (isheetti) beeksisee, garii irraa gara gale. Yeroo inni isa isheetti himu “eenyutu kana sitti hime” jette. "Beekaa, keessa hubataatu natti hime" jedheen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 4, 'Yoo tawbaa gara Rabbii deebitaniif (isiniif araarama) Onneen lamaan keessanii dhugumaan jallattee jirti. Yoo isa irratti wal gargaartan Rabbiin isatu gargaaraa isaati Jibriiliifi gaggaariin Mu''umintootaas, Maleykonnis booda sanaatii gargaartota isaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 5, 'Yoo inni isin hiike, Gooftaan isaa niitolee kan isin irra caalan bakka isaaf buusuun ni kajeelama. (kan) Muslimoota, mu’uminoota, ajajamtoota, toobbattoota, (Rabbiin) gabbartoota, soomantoota, kan beeraa (gursummeeyyii)fi durba ta''an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 6, 'Yaa warra amantan! Lubbuulee teessaniifi maatiiwwan keessan ibidda qabsiisaan isii namootaafi dhagaalee ta''e, irraa eegaa. Isirra maleeykota gara jabeeyyii, ciccimoo ta''antu jiru. Waan Rabbiin isaan ajaje hin faallessanu, waan ajajaman ni hojjatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 7, '"Yaa warra kafartan! Guyyaa har’aa (Qiyaamaa) kana rakkina hin himatinaa; wanti isin galata galfamtan waanuma dalagaa turtan qofa" (jedhamu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 8, 'Yaa warra amantan! gara Rabbiitti tawbadhaaTawbaa qulqulluu. Gooftaan keessan diliiwwan keessan isin irraa haxaawee Jannatoota jala ishee laggeen yaatu isin seensisuun ni kajeelama. Guyyaa Rabbiin Nabiyyiifi warra isaa wajjin amanan hin hoongessine san, ifaan isaanii fuuldura isaaniitiifi mirgoowwan isaanii deema. Nijedhan "Yaa Gooftaa keenya! Ifaa keenya nuuf guuti; nuufis araarami; Ati waan hunda irratti danda''aa dha".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 9, 'Yaa Nabiyyichaa! Kaafirootaafi munaafiqoota irratti qabsaa''ii. isaan irrattis cimi. Teessoon isaaniis ibidda Jahannami. Deebiin waa hammaatee!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 10, 'Rabbiin isaan kafaraniif niitii Nuuhiifi niitii Luux fakkeenya godhe. Gabroota keenya gaggaarii keessaa gabroota lama jala turan. isaan ganan. Isaan lamaanis (Nuuhifi Luux) (adabbii) Rabbii irraa homaa isaan hin duroomsine. "Isin lamaan ibidda warra seenan wajjin seenaa" jedhameen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 11, 'Ammas Rabbiin isaan amananiif niitii Fir''awni fakkeenya godhe. Yeroo isheen "yaa Gooftaa kiyya! Si biratti Jannata keessatti mana naaf ijaari; Fir''awniifi dalagaa isaa irraa na baraarsi; ummata miidhaa hojjatoota irraas na baraarsi" jette.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 12, 'Maryam Intala Imraan, ishee qaama saalaa ishee tiksites (fakkeenya godheera). Ruuhii (uumaa) keenya irraa ta''e isa keessatti afuufne. Jechoota Gooftaa isheetiifi kitaabota Isaas ni dhugoomsite. Warra Rabbiif ajajamu irraas taate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 1, '(Rabbiin) Inni mootummaan (waan hundaa) harka Isaa jiru tolli isaa baay''ate. Inni waan hunda irratti danda''aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 2, '(Rabbiin) Isa du''aafi jireenya uumeedha eenyuu keessantu irra toltuu akka hojjatu isin qoruuf jecha. Inni injifataa, araaramaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 3, '(Rabbiin) Isa samii torba wal jalaa gubbaan uumeedha; uumaa Rahmaan keessatti wal dhabbii irraa homaa hin argitu. Mee agartuu kee (gara samii) deebisii dhoohaa irraa waan ta''e ni argitaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 4, 'Ergasii yeroo baay''ee ija deddeebisi; ijji (kee) hoonga''aa dadhabaa ta''ee gara kee deebi''a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 5, 'Dhugumatti, samii addunyaa ibsaawwaniin (urjiiwwaniin) miidhagsineerra. Sheyxaanotaafis furguuggee ishee goone. Isaaniif adabbii ibidda boba''aa qopheessineerra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 6, 'Isaan Gooftaa isaaniitti kafaraniif adabbii jahannamtu jira. Deebi’ichi waa fokkate!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 7, 'Yeroo ishee keessatti darbaman isheedhaaf (sagalee akka) halaaka harree dhaga''u,haala isheen danfuutti jirtuun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 8, 'Dallansuu irraa kan ka''e ciccituutti dhihaatti; dhawaata gareen wahii ishee keessatti darbamuun waardiyyaan ishee "sila akeekkachiisaan (nabiyyiin) isinitti hin dhufnee?" (jechuun) isaan gaafata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 9, 'Nijedhu "Eeyyeen; dhugumatti akeekkachiisaan nutti dhufeera; sobsiifneeti ''Rabbiin homaa hin buufne; isin jallina guddaa keessa jirtu'' jenneen".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 10, 'Nijedhan "Odoo kan dhageenyu yookiin kan xiinxallinu taanee, silaa warra ibidda boba''aa keessaa hin taanu turre".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 11, 'Dilii isaanii ni amanan. Warra ibidda (boba''aa)tiif (rahmata Rabbii irraa) fagaachuun haa tahu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 12, 'Warra Gooftaa isaanii fagootti sodaataniif araaramaafi mindaa guddaatu isaaniif jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 13, 'Haasa''a keessan gadi qabaa yookiin ol qabaa; Inni beekaa waan qoma keessaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 14, 'Sila Inni uumee (iccitii isaanii) hin beekuu! inni keessa argaafi beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 15, 'Inni Isa dachii laaffifamtuu isiniif godheedha; naannoo ishee keessa deemaatii soorata Isaa irraas nyaadhaa. Deebiin garuma Isaatti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 16, 'Sila isa samii olii sodaa dhabdanii? dachii isiniin cichisiisuu, achumaan isheen sossooti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 17, 'mmoo isa samii olii sodaa dhabdanii? bubbee cirracha qabu isin irratti erguu. Akeekkachiisni Kiyya akkam akka ta''e beekuuf jirtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 18, 'Dhugumatti, warri isaaniin duraa sobsiisaniiru; (adabbiin) najibbuu akkam tureree!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 19, 'Sila gara simbirroota gubbaa isaaniitti koola (qoochoo) isaanii babal''isanii walitti dachaasanii hin ilaalanuu? Rahmaaniin malee homtuu isaan hin qabu. Inni waan hunda argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 20, 'Sila innin sun ka Rahmaaniin achitti waraanaa isiniif ta''ee isin tumsuu eenyuma? Kaafiroonni gowwummaa keessatti malee hintaane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 21, 'Inni isin sooru sun eenyu Odoo Inni soorata Isaa (isinirraa) qabee? Dhugumatti, isaan diddaafi (haqa) irraa baqachuu itti fufan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 22, 'Sila nama fuula isaa irratti gonbifamee deemu moo isa dhaabbatee karaa qajeelaa irra deemutu irra qajeelaadha?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 23, 'Jedhi: "Inni Isa isin uumee dhageettii, agartuuwwaniifi onneewwan isiniif godheedha; hangi isin galatoomfattan waa xiqqaate!"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 24, 'Jedhi: "Inni Isa dachii keessa isin facaaseedha; garuma Isaatti oofamtus."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 25, 'Nijedhu "Yoo kan dhugaa dubbattan taataniif, beellamni kun yoomi?".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 26, 'Jedhi: "Dhugumatti, beekumsi isaa Rabbiin bira qofa jira. Ani immoo akeekkachiisaa ifa galaa qofa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 27, 'Yeroma dhihoo ta''ee isa (beellamicha) argan fuulleen warra kafaranii fokkatte "Inni kun isa waammataa turtanii dha" jedhame', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 28, 'Jedhi "Mee naaf himaa! yoo Rabbiin anaafi nama ana wajjin jiru balleesse yookiin rahmata nuuf godhe, namni kaafiroota adabbii laalessaa irraa baraaru eenyu?".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 29, 'Jedhi "Inni Rahmaani Isatti amanne; Isa irrattis hirkanne. Namni jallina ifa ta''e keessa jiru eenyu akka ta''e beekuuf jirtu".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 30, 'Jedhi: "Mee naaf himaa! odoo bishaan keessan dachii keessa gadi lixaa ta''ee eenyu bishaan yaa''u isiniif fida?"', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 1, 'Nuun Qalamaafi waan (malaykonni) barreessaniinin kakadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 2, 'Ati ni''imaa Gooftaa keetiitiin maraataa hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 3, 'Dhugumatti, siif mindaa hin cinnetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 4, 'Ati amala (naamusa) guddaa irra jirta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 5, 'Fuulduratti arguuf jirta; isaanis arguuf jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 6, 'Eenyuu keessanitti maraattummaan jirtii (arguuf jirtu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 7, 'Gooftaan kee Isatu nama karaa Isaa irraa jallate akkaan beeka; qajeeltotas inni beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 8, 'Kijibsiiftotaaf hin ajajamin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 9, 'Odoo ati (ejjannoo kee) laaffiftee [Isaan] laaffisanii jaalatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 10, 'Akkaan kakataa salphataa hundaaf hin ajajamin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 11, 'Akkaan hamataa, faradaan akkaan deemaa kan ta''eef (hin ajajamin).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 12, 'Toltuu kan akkaan dhorgu, daangaa dabraa, dilaawaafis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 13, 'Gara jabeessa, sana booda immoo diqaalaa kan ta''eef (hin ajajamin).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 14, 'Waan abbaa qabeenyaafi ilmaanii ta''eef (boonee kafare).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 15, 'Yeroo keeyyattoonni Keenya isa irratti dubbifamtu, "(kun) ogbarruu warra duriiti" jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 16, 'Funyaan irratti isa mallatteessina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 17, 'Nuti akkuma abbootii ashaakiltii yeroo isaan bariidhaan ishee funaannachuuf kakatan qormaannetti, isaanis (mushrikoota Makkaas) qormaanneerra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 18, 'Siinoo hin baasanu (yoo Rabbiin fedhe hin jedhan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 19, 'Odoo isaan rafanuu, naanna''aan (adabbiin) Rabbii kee biraa ta''e ishee irra naanna''e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 20, 'Akka halkan dukkanaa (cilee) taatee bulte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 21, 'Bariidhaan walitti lallaban.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 22, '"Yoo kan funaannattan taataniif oyruu keessan irratti bariifadhaa" (waliin jedhan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 23, 'Walitti hasaasaa (gara oyruu) deeman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 24, '"Har’a hiyyeessi tokkoyyuu isinirratti akka ishee hin seenne" (jechuun hasaasan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 25, '(Hiyyeeyyii) dhowwuu irratti danda''oo ta''anii bariisifatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 26, 'Yeroo ishee arganu ni jedhan: "nuti karaa badoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 27, 'Inumaayyuu nuti hoongeffamoodha."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 28, 'Irra filatamaan isaanii "sila maaliif siinoo hin baafne (yoo Rabbiin fedhe hin jenne) isiniin jedhee hin turree?" jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 29, '"Gooftaan keenya qulqullaa''e; dhugumatti, nuti miidhaa hojjattoota taaneerra" jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 30, 'Kan wal komatan ta’anii gariin isaanii garii irratti garagale.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 31, 'Ni jedhan: "yaa badii keenya! Nuti dhugumatti, daangaa dabritoota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 32, 'Gooftaan keenya kan ishee caaltu bakka nuuf buusuu kajeella. Nuti gara Gooftaa keenyaa kajeeloodha” (jedhan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 33, 'Adabni (addunyaa) akkanuma; adabbii Aakhiraatu irra guddaadha Odoo kan beekan tahanii (irraa of tiksu turan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 34, 'Dhugumatti, warra Rabbiin sodaataniif Gooftaa isaanii bira Jannata qananiitu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 35, 'Sila Nuti muslimoota akka yakkamtootaa ni goonaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 36, 'Maalumatu isiniif jira? Akkamitti murteessitu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 37, 'Dhugumatti, kitaaba (samii bu''e) kan isa keessaa dubbiftantu isiniif jiraa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 38, 'Kan isa keessa wanti isin filattan jiru (qabduu)?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 39, 'Sila kakuulee nurratti taheetu kan Guyyaa Qiyaamaa keessatti bakka ga''aa ta''etu isiniif jira moo ‘wanti isin murteessitan isiniif jira’ jechuun?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 40, 'Eenyuu isaaniitu sanaaf wabiidhaa isaan gaafadhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 41, 'Sila shariikota (kan murtee isaanii dhugoomsu)tu isaaniif tahee? Yoo kan dhugaa dubbatan ta''aniif shariikota isaaniitiin haa dhufanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 42, 'Guyyaa mogolee irraa saaqamee (munaafiqoonni) gara sujuudaa waamamanii hin dandeenye san [yaadadhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 43, 'Ijjoonni isaanii sodaattuu taatee xiqqeenyis isaan haguuga. Dhugumatti, isaan odoo fayyaa qabanuu (addunyaa irratti) sujuudatti waamamaa turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 44, 'Anaafi nama haasa''a (Qur''aana) kana sobsiisu walitti nu dhiisi; Nuti suutaan karaa isaan hin beekne irraa isaan qabna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 45, 'Yeroon isaaniif kenna. Tooftaan Kiyya cimaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 46, 'Sila mindaa isaan gaafatteeti kaffaluuf itti ulfaatemoo (maali)?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 47, 'Sila (iccitii) fagoottu isaan biratti tahee, kan isaan barreessan?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 48, 'Murtii Gooftaa keetiitiif obsi. Akka saahiba qurxummii hintahin yeroo lallabe inni dallansuun guutame.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 49, 'Odoo ni''imaan Gooftaa isaa irraa taate isa dhaqqabuu baattee, silaa komatamaa ta''eeti dirree biqiltuu hin qabne irratti darbama ture.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 50, 'Gooftaan isaa isa filateeti gaggaarii irraa isa godhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 51, 'Isaan kafaran ijoowwan isaaniitiin lafaan si dhahuutti dhihaatan. yeroo yaadachiisa dhaga''an "inni maraataa dha" (siin)jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 52, 'Innis aalama hundaaf yaadachiisa malee hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 1, 'Mirkaneessituun,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 2, 'Mirkaneessituttiin maali?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 3, 'Mirkaneessituttiin maal akka taate maaltu si beeksise?!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 4, '(Ummanni) Samuudiifi Aad rukuttuu qalbii (Qiyaamaa) sobsiisaniiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 5, 'Samuud iyya daangaa darbaadhaan balleeffaman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 6, 'Aad immoo qilleensa sagalee cimaa akkaan bubbisuun balleeffaman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 7, 'Halkan torbaafi guyyaa saddeetiif walitti aansee isaan irratti erge. Ishee keessatti ummata kan jirma timiraa hundeen buqqifame fakkaatanii kukkufan argita.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 8, 'Sila isaan irraa haftee wahii ni argitaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 9, 'Fir''awn, warri isa duraatiifi (gandoonni) gombifamtoonnis diliidhaan dhufan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 10, 'Ergamaa Gooftaa isaanii faallessinaan qabaa cimtuu isaan qabe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 11, 'Nuti yeroo bishaan daangaa dabru doonii keessatti isin yaabbachiifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 12, 'Akka ishee isiniif gorsa goonuufi gurri waa hubattus akka ishee hubattuuf (kana goone)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 13, 'Yeroo Garrii ykn Faaggaa (xurumbaa) keessa afuuffaan tokkittiin afuufamte,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 14, 'Dacheeniifi gaarreenis ol fuudhamanii caccabiinsa tokkittii caccaban,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 15, 'Guyyaa san argamtuun (Qiyaamaan) ni argamti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 16, 'Samiinis ni baqaqxi; isheen guyyaa san laaftuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 17, 'Maleeykonnis daangawwan ishee irratti ta''u. Arshii Gooftaa keetiis guyyaa san (maleeykota) saddeettu gubbaa isaaniitti baadhatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 18, 'Guyyaa san (murtiidhaaf) ni dhiyeeffamtuu, (iccitiin) dhokattuun isin irraa taate hin dhokattu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 19, 'Namni kitaaba isaa mirga isaatiin kenname ni jedha: “hoodhaa kitaaba kiyya dubbisaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 20, 'Ani qormaata koo qunnamuu dhugoomseen ture.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 21, 'Inni jireenya jaalatamtuu keessa ta''a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 22, 'Jannata ol fuudhamtuu keessa (ta''a).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 23, 'Kan firiiwwan ishee dhihoo ta''an;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 24, '"Waan guyyoota darban keessa dabarfattaniif jecha gammadoo ta’aatii nyaadhaa; dhugaa" (isaaniin jedhama).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 25, 'Ammoo Namni kitaaba isaa bitaa isaatiin kennames ni jedha: "yaa badii kiyya! Odoon kitaaba kiyya kennamuu baadhee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 26, 'Qormaanni kiyya maal akka ta''es (odoon) beekuu baadhee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 27, 'Odoo isheen xumura (jiruu) kiyyaa taateen hawwa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 28, 'Qabeenyi kiyya homaa narraa hindeebifne (fayyadne).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 29, 'Taaytaan kiyyas narraa bade” (jedha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 30, 'Isa qabaatii isa hidhaa (sakaalaa).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 31, 'Ergasii ibidda isa seensisaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 32, 'Ergasii sansalata dheerinni isaa dhundhuma torbaatama ta''e keessa isa seensisaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 33, 'Inni Rabbii Guddaatti hin amanu ture.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 34, 'Hiyyeeyyii nyaachisuu irrattis (namoota) hin kakaasu ture.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 35, 'Har’a asitti firri isaaf hin jiru. [1]', '[1] firrii (jaalallee)');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 36, 'Nyaannis malaa (warra ibiddaa) irraa malee hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 37, 'Warra dilaawoo malee isa hin nyaatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 38, 'Waan isin argitaniin kakadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 39, 'Waan isin hin argineenis (niin kakadha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 40, 'Inni (Qur''aanni) jecha ergamaa kabajamaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 41, 'Inni jecha weellisaatii miti; xiqquma qofa amantu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 42, 'Jecha raagaatiis miti; xiqqoo qofa gorfamtanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 43, 'Gooftaa aalama hundaa irraa buufamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 44, 'Odoo garii jechootaa (kan Nuti hin jedhin) Nurratti dubbatee,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 45, 'Silaa Nuti mirgaan isa qabna turre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 46, 'Ergasii hidda onnee isarraa murra turre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 47, 'Isin irraa namni isarraa dhorgu tokkollee hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 48, 'Innis (Qur''aanni) warra Rabbiin sodaataniif gorsa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 49, 'Dhugumatti isin irraa namoonni (Qur''aana) sobsiisan akka jiran Nuti ni beekna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 50, 'Inni (Qur''aanni) kaafiroota irratti gaabbiidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 51, 'Inni (Qur''aanni) dhugaa mirkanaa’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 52, 'Maqaa Gooftaa kee guddaa ta’ee faarsi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 1, 'Adaba (kaafiroota irratti) argamaa ta''e kadhataan kadhate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 2, 'Kan kaafirootatti (argamu kadhate); wanti isa (adabicha) deebisu hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 3, 'Rabbii Abbaa kortoowwanii ta''e irraa (argama).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 4, 'Malaykonniifi Jibiriil gara Isaa ol koru guyyaa shallagni isaa waggoota kuma shantama ta''e keessatti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 5, 'Obsa gaarii obsi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 6, 'Isaan (adabicha) fagoo taasisanii isa ilaalu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 7, 'Nuti immoo dhihootti isa argina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 8, 'Guyyaa Samiin akka meeta baqee taatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 9, '(Guyyaa) Gaarreenis akka jibrii hiddamee taatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 10, '(Guyyaa) firri fira hin gaafanne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 11, 'Isaan agarsiifamu Namni dilaawaan odoo ilmaan isaatiin adabbii guyyaa sanii uffuree jaalata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 12, 'Niitii isaatiifi obboleessa isaatiinis (odoo bilisa ba’ee jaalata);', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 13, 'Firoota isaa kan ofitti isa maxxanfattuunis;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 14, 'Nama dachii keessaa hunda (kennee) ergasii (fidaan sun) nagaa isa baasuu (jaalata).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 15, 'Dhorgamaa! isheen lazaadha (maqaa hulaa ibiddaati).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 16, 'Buqqiftuu gogaa sammuuti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 17, 'Nama (amantii irraa) duubatti deebi''ee, gara gale ni waamti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 18, '(Qabeenya) walitti qabee (zakaa odoo hin kennin) lakkaa’u (hunda waamti).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 19, 'Dhugumatti, namni obsa dhabeessa ta''ee uumame.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 20, 'Yeroo hamtuun isa tuqe mufataa (gammachuu dhaba).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 21, 'Yeroo wanti gaariin isa tuqe immoo dhorgataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 22, 'Warra sagadan malee;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 23, 'Isaan salaata isaanii irratti gadi dhaabbatan (dawwaman malee);', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 24, 'Isaan qabeenya isaanii keessa mirgi beekamaan jiru,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 25, 'Hiyyeessa Kadhataafi kan hin kadhanneef,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 26, 'Isaan Guyyaa Murtii dhugoomsan,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 27, 'Isaan adabbii Gooftaa isaanii sodaatan(malee kan biroo obsa dhabaa dha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 28, 'Adabbiin Gooftaa isaanii (nama tuquu dhabuun isaa) amanamaa miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 29, 'Isaan qaama saalaa isaanii tiiksan,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 30, 'Niitolii isaanii yookiin waan mirgi isaanii horatan irratti malee; (kanarratti) isaan komatamoo miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 31, 'Namni sanaan ala (fedhii guutachuu) barbaade immoo, isaan warra daangaa dabroodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 32, 'Ammas isaan amaanaa isaaniitiifi waadaa isaanii eegan,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 33, 'Isaan ragaa isaaniitiin dhaabbatan,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 34, 'Isaan salaata isaanii irratti tiikfatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 35, 'Warri sun jannata keessatti kabajamoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 36, 'Warra kafareef maaltu jiraayi sirratti xiyyeefatu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 37, 'Garee gareen mirgaafi bitaa irra guutanii.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 38, 'Sila namni isaan irraa ta''e hundi jannata qananii seensifamuu kajeelaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 39, 'Haa dhorgamanu! Nuti waanuma isaan beekan irraa isaan uumne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 40, 'Gooftaa Bahootaatiifi Dhihootaatiin kakadhaa! Nuti dhugumatti danda’oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 41, 'Namoota isaan irra caalan bakka buusuu irratti (danda''oo dha). Nuti dadhabsiifamoo hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 42, 'Hanga Guyyaa isaaniif beellamame san qunnamanitti, (cubbuu keessa) seenanii haa taphatanii isaan dhiisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 43, 'Guyyaa qabroota irraa arifataa ba''an isaan akka waan gara taabotootaatti dhangala''an fakkaatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 44, 'Ijjoonni isaanii xiqqaattuu salphinni isaan haguugdi. Sun guyyaa isaan isa sodaachifamaa turaniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 1, 'Nuti Nuuhiin gara ummata isaatti ergineerra "odoo adabbiin laalessaan isaanitti hin dhufin dura ummata kee sodaachisi" jechuun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 2, '(Nuuhis) ni jedhe: "yaa ummata kiyya! Ani isiniif akeekkachiisaa ifa bahaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 3, 'Rabbiin gabbaraa; Isa sodaadhaa; anaafis ajajamaa" jechuun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 4, '"Diliilee keessan irraa isiniif araarama; hanga yeroo murtaa''eettis isin tursiisa. Beellamni Rabbii yeroo dhufe booda hin aanfamu. Odoo kan beektan taatanii (silaa isa malee hin gabbartanu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 5, '(Nuuhiin) ni jedhe: "Gooftaa kiyya! Ani ummata kiyya halkaniifi guyyaan waame.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 6, 'Waamichi kiyya (dhugaa irraa) baqa malee homaa isaaniif hin daballe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 7, 'Akka Ati isaaniif araaramtuuf dhawaata ani isaan waamuun qubbeen isaanii gurroowwan isaanii keessa kaa’anii uffata isaanii haguuggatanii (badii) itti fufan; booniinsa boonan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 8, 'Ergasii ani lallabeen isaan waame.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 9, 'Achi boodas ani ifan isaaniif godhe; hasaasuus isaanittin hasaase.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 10, 'Nin jedhe ‘Gooftaa keessan araarama kadhaa; Inni Akkaan Araaramaadhan’.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 11, 'Rooba baay''ee deddeebi''aa isin irratti erga. (rooba guddaa isiniif roobsa).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 12, 'Qabeenyaafi ilmaanis isiniif dabala. Ashaakiltii isiniif godha laggeenis isiniif taasisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 13, 'Maaltu isiniif jiraayi guddina Rabbii hin sodaanne?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 14, 'Dhugumatti, sadarkaa sadarkaadhaan isin uumeera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 15, 'Sila isin hin arginee akkamitti Rabbiin samii torban wal jalaa gubbaatti akka uume ?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 16, 'Isaan keessatti ji''a ibsaa taasisee; aduus madda ifaafi ho''aa (siraaja) taasise.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 17, 'Rabbiin biqilchuu (uumuu) dachii irraa isin biqilche.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 18, 'Ergasii ishee keessatti isin deebisa, baasuus isin baasa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 19, 'Rabbiin dachii afata isiniif godhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 20, 'Akka isin ishee irraa karaalee babal''aa seentaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 21, 'Nuuhiin ni jedhe: "Gooftaa kiyya! Isaan ajaja kiyya didanii, nama qabeenyi isaatiifi ilmaan isaa hoonga’iinsa malee homaa isaaf hin daballe hordofan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 22, 'Shira gurguddaa shiran.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 23, '‘Gabbaramtoota keessan hin dhiisinaa; waddi, suwaa''i, yaghuus, ya''uuqiifi nasriinis hin dhiisinaa'' (waliin) jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 24, 'Dhugumatti, (namoota) baay''ee jallisaniiru. Miidhaa raawwattootaaf jallinna malee hin dabalin.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 25, 'Diliiwwan isaanii irraa kan ka''e, bishaaniin nyaachifaman, ibidda seensifaman. Rabbiin alatti tumsitoota isaaniif hin arganne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 26, 'Nuuhiin ni jedhe: "Gooftaa kiyya! Kaafiroota irraa nama tokkollee dachii irratti hin dhiisin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 27, 'Yoo Ati isaan hambifte gabroota Kee jallisu; dilaawoo akkaan kaafira ta''e malees hin dhalan (hin horan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 28, 'Gooftaa kiyya! Anaaf, araarami abbaafi haadha kiyyaafis, nama mu’umina ta''ee mana kiyya seeneefis, mu''uminootaafi mu''umintittiifis (araarami). Kaafirootaaf badii malee hin dabalin.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 1, '(Yaa Muhammad SAW!) Wahyiin natti godhameera jedhi Gareen jinnii irraa ta''an (Qur''aana) dhageeffatanii NI jedhan: “nuti Qur''aana dinqisiisaa dhageenye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 2, '[Inni] gara karaa sirriitti qajeelcha; isatti amanneerra. Gooftaa keenyatti tokkollee hin qindeessinu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 3, 'Inumaa kabajaan Gooftaa keenyaa dhugumatti guddateera; niitiis ta''ee ilmoo hin godhanne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 4, 'Gowwoonni keenya Rabbi irratti soba dubbatu turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 5, 'Nuti immoo namoonniifi jinnoonni Rabbi irratti soba hin dubbatanu jechuu yaanne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 6, 'Ammas dhiironni nama irraa ta''an dhiirota jinnii irraa ta''anitti maganfatanii boona isaaniif (jinnootaaf) dabalaa turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 7, 'Akkuma isin yaaddan isaanis Rabbiin nama tokkollee (erga du''ee) hin kaasu jechuu yaadaa turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 8, 'Nutis samiitti ga''uu (feeneti) kan isheen eegdota jajjaboofi qaanqeen (urjii furguuggamtuu) guutamte ishee argine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 9, 'Nuti ishee irraa teessuma (haasa''a) dhageeffachuuf teenyu qabna turre. Namni amma dhageeffate immoo qaanqee (urjii) isa eeggatu isaaf arga.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 10, 'Nuti nama dachii keessa jirutti hamtuun yaadame moo Gooftaan isaanii qajeeluma isaaniin fedhee hin beeknu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 11, 'Nuti nurraa gaggaariin ni jiran. Ammas nurraa kan sanaan ala ta''antu jiru. Nuti warra karaalee adda addaati turre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 12, 'Nuti beeknee jirra dachii keessatti Rabbiin jalaa hin baanu; dheessuudhaanis Isa hin dadhabsiifnuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 13, 'Nuti yeroma Qajeelfama dhageenye isatti amanne. Namni Gooftaa isaatti amane hir’achuu (mindaa) ta''ee dabaltii (adabaa) hin sodaatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 14, 'Nuti, nurraa muslimoonni ni jiran; jallattoonnis nurraa ni jiru; Namni Islaamaye warri sun karaa qajeelaa barbaadanii jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 15, 'Jallattoonni immoo Jahannamiif qoraan ta''an.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 16, 'Odoo isaan karaa qajeelaa irra gadi dhaabbatanii, bishaan baay''ee (samii irraa) isaan obaafna turre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 17, 'Isa keessatti isaan qormaatuuf jecha (obaafna ture). Namni yaadannoo Gooftaa isaa (Qur''aana) irraa garagale, (Rabbiin) adabbii jabaa isa seensisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 18, 'Masjiidonni kan Rabbiiti; Rabbii wajjiin homaa hin waammatinaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 19, 'Yeroo gabrichi Rabbii (Muhammad SAW!) Isa waammachuuf dhaabbatu (jinnoonni) isa irratti tuuta ta''utti dhihaatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 20, '(Yaa Muhammad SAW!) jedhi: "wanti ani gabbaru Gooftaa kiyya qofa; Isattii waan tokkollee hin qindeessu."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 21, 'Jedhi: "Ani dhugumatti, miidhaas ta''ee qajelluma isiniif (fiduu) hin danda''u."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 22, 'Jedhi: "Ani (adabbii) Rabbii irraa wanti tokkollee ana hin baraarsu. Isa malees hirkoo hin argadhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 23, 'Rabbi irraa (wahyii)fi ergaawwan Isaa geessuu malee (hin danda''u). Namni Rabbiifi Ergamaa Isaa faallesse, dhugumatti ibidda jahannam kan zalaalam ishee keessatti hafutu isaaf jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 24, 'Hanga waan ittiin sodaachifaman arganitti namni tumsaadhaan akkaan dadhabaafi lakkoofsaan daran xiqqaa eenyuun akka ta''e beekuuf jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 25, '“Wanti isin sodaachifamtan dhihoo ta''uu yookiin Rabbiin kiyya beellama yeroo (dheeraa) isaaf godhaa hin beeku” jedhiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 26, '(Rabbiin) Beekaa fagooti; fagoo Isaa irratti nama tokkollee hin mul''isu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 27, 'Ergamaa irraa nama jaalate malee (kan biraatti hin mul''isu) Inni fuuldura isaatiifi duuba isaatiin eegdota (malaykota) seensisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 28, 'Ergaawwan Gooftaa isaanii dhugumatti bakkaan ga''uu isaanii’ akka ifa baasuuf (eegdota kaa''e) waan isaan bira jiru hundatti marsee waan hundaayyuu lakkoofsaan walitti qabe (beeke) ‘', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 1, 'Ati Yaa mammarataa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 2, 'halkan dhaabbadhu Xiqqo malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 3, 'Walakkaa isaa (dhaabbadhu) yookiin xiqqoo isa irraa hir’isi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 4, 'Yookiin isa irratti dabali Qur''aana suutaan dubbisiinsa dubbisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 5, 'Nuti jecha ulfaataa sirratti buusuuf jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 6, 'Ka''umsi halkanii isheen (arrabaafi qalbii) wal simachiisuutti akkaan jabaafi dubbisuufis qajeelaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 7, 'Guyyaa keessa (dhimma jireenyaatiif) sochii dheeraatu siif jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 8, 'Maqaa Gooftaa keetii faarsi; gara isaattis citiinsa citi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 9, '(Inni) Gooftaa bahaafi dhihaati. Isa malee gabbaramaan dhugaa hin jiru; hirkoo isa taasifadhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 10, 'Waan isaan jedhan irratti obsi; fageenya gaarii isaan irraa fagaadhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 11, 'Anaafi sobsiiftota warra qananii walitti Na dhiisi; beellama xiqqoos isaaniif qabi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 12, 'Nu bira sakaallaa ulfaataafi ibiddatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 13, 'Nyaata nama hudhuufi adabbii laalessaa ta''etu (jira).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 14, 'Guyyaa dachiifi gaarreen hurgufamaniifi gaarreen tuulaa cirracha yaa''uu taatu keessa (sakkaalamu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 15, 'Nuti gara keessanitti Ergamaa ragaa isin irratti ba''u erginee jirra, akkuma gara Fir''awn Ergamaa ergineetti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 16, 'Fir''awnnis Ergamicha faallessee (didee) qabaa cimaa isa qabne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 17, 'Yoo kafartaniif, (adabbii) Guyyaa ijoollee arrii taasisuu akkamitti eeggattu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 18, 'Samiin isaan (guyyaa sanaan) dhodhootuudha. Baallamni Isaa raawwatamaa ta''e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 19, 'Isheen tun gorsa. Nama fedhe gara Gooftaa isaatti karaa godhata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 20, '(Yaa Muhammad SAW!) Dhugumatti Gooftaan kee ni beeka akka atiifi warri sii wajjin ta''an irraa gareen wahii, lama sadaffaa halkanii, walakkaa isaatiifi tokko sadaffaa isaatii gadis dhaabbattan(nibeeka). Rabbiin halkaniifi guyyaa ni shallaga. Akka isin isa safartanii waliin hin geenye beekee tawbaa keessan isin irraa qeebale. Qur''aana irraas (salaata keessatti) waan isiniif laafe qara''aa. Isin irraa dhukkubsataan akka jiru, warri biraa immoo tola Rabbii barbaacha dachii keessa akka deeman, warri biraas karaa Rabbii keessatti akka lolan beekeeti (isin irrraa salphise). Kanaafuu, isa (Qur''aana) irraa waan isiniif laafe qara''aa. salaata dhaabaa; zakaas kennaa. Liqii bareedaas Rabbiif liqeessaa. Toltuu irraa waan lubbuu keessaniif dura dabarfattan Rabbiin biratti inni caalaafi kan mindaa guddaa qabu ta''eeti isa argitu. Rabbiin araarama kadhaa; Rabbiin araaramaa, rahmata godhaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 1, 'Yaa mammarataa!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 2, 'Ka''ii akeekkachiisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 3, 'Gooftaa kee guddisi', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 4, 'Uffata kee qulqulleessi', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 5, 'Taabotaan oodi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 6, 'Baay''ifannaa barbaachaaf hin arjoomin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 7, 'Gooftaa keetiif obsi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 8, 'Yeroo xurumbaa keessa afuufame.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 9, 'Sun, guyyaan gaafasii guyyaa rakkisaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 10, 'Kaafiroota irratti (guyyaa) laafaa miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 11, 'Nama ani kophaa isa uumee wajjin (walitti) Na dhiisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 12, 'Kan Ani qabeenya bal''aas isaaf godhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 13, 'Ilmaan dhiiraa kan isa biratti argamanis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 14, 'Bal''isuus kan Ani isaaf bal''ise;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 15, 'Ergasii akka Ani isaaf dabalu kan kajeela;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 16, 'Haa dhorgamu! Inni keeyyattoota Keenya mormaa ture.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 17, 'Dhugumatti, rakkoo guddaattin isa dirqa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 18, 'Inni ni xiinxale; ni tilmaames.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 19, 'Abaarame! Akkamumatti tilmaame?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 20, 'Ergasiis abaarame! Akkamumatti tilmaame?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 21, 'Ergasii ni ilaale', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 22, 'Ergasii fuula guure; akkaan jijjiirame.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 23, 'Ergasii gara gale; ni boone.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 24, 'Ni jedhes: "(Qur''aanni) kun falfala (nama biraa) irraa waraabame qofa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 25, 'Kun jecha namaa malee hin taane."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 26, 'Saqar isa seensisuufin jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 27, 'Saqar maal akka ta''e maaltu si barsiise?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 28, '(Foon) hin hambiftu (lafees) hin dhiiftu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 29, 'Gogaa gubduudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 30, 'Ishee irra (waardiyyaa) kudha sagaltu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 31, 'Eegdota Ibiddaa malaykota malee kan biraa hin goone. Lakkoofsa isaaniis isaan kafaraniif qormaata malee hingoone, warri kitaaba kennaman akka mirkaneeffatan, warri amanan iimaana akka dabalatanuuf, warri kitaaba kennamaniifi mu''uminoonnis akka hin shakkinee, fi akka warri onnee isaanii keessa dhukkubni jiruufi kaafiroonni ‘Rabbiin (lakkoofsa) kanaan fakkeenya maalii fedhe’ jedhaniif (kana goone). Akka kanatti Rabbiin nama fedhe jallisee nama fedhe immoo qajeelcha. (Baay''ina) waraana Gooftaa keetii Isa malee homtuu hin beeku. Isheen namaaf gorsa malee waan biraatii miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 32, 'Haa dhorgamu! Ji''attin kakadha!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 33, 'Halkaniinis; yeroo inni deeme.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 34, 'Bariidhaanis yeroo inni ife.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 35, 'Isheen (saqar) tokkoo (rakkoolee) gurgurddooti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 36, 'Namaaf akeekkachiiftuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 37, 'Nama isin irraa (hojii gaariidhaan) fuulduratti deemuu, yookiin duubatti hafuu fedheef (akeekkachiistuu dha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 38, 'Lubbuun hundi waan hojjatteen qabamtuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 39, 'Warra mirgaa malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 40, '(Isaan) jannata keessatti wal gaggaafatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 41, 'Yakkamtoota irraa (wal gaafatu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 42, '"Maaltu Saqar keessa isin seensise?" (isaanin jedhu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 43, 'Ni jedhan: "nuti warra salaatan irraa hin turre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 44, 'Hiyyeeyyii kan nyaachifnus hin turre;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 45, 'Warra (hamtuu) keessa seenuu wajjin seenaa turre;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 46, 'Guyyaa galataa kan sobsiifnu turre;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 47, 'Hanga (duuti) mirkanaayaan nutti dhufutti (haala kana irra turre)" (jedhu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 48, 'Jaarsummaan (araarri) warra araarsanii isaan hin fayyadu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 49, 'Maaltu isaaniif jiraayi gorsa (Qur''aanaa) irraa gara galoo ta''u?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 50, '(Yeroo akeekkachiisa Rabbii irraa dheessan) akka harree diidoo dammaqanii (gugatanii) fakkaatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 51, 'Leenca irraa kan baqatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 52, 'Inumaa namni isaan irraa ta''e hundi kitaabota banamoo kennamuu fedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 53, 'Haadhoowwamanii (hin kennamanu) isaan Aakhirumaayyuu hin sodaatanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 54, 'haadhoowwamanii inni (Qur''aanni) gorsa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 55, 'Nama fedheetu isaan gorfama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 56, 'Yoo Rabbiin fedhe malee hin gorfamanu. Inni (Rabbiin) kan sodaatamuu haqa godhatuufi Abbaa Araaramaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 1, 'Miti Guyyaa Qiyaamaatiinin kakadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 2, 'Lubbuu of komattuu taateenis nan kakadha; (mindaa galfamuuf jirtu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 3, 'Sila namni lafee isaa walitti hin qabnuu yaadaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 4, 'Eeyyeen (walitti ni qabna) (Nuti) qubbeen isaatuu (akka turanitti deebifnee) sirreessuu irratti danda''oodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 5, 'Dhugumatti namni fuuldura isaa (Qiyaamaa) sobsiisuu fedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 6, '"Guyyaan Qiyaamaa yoomii?"gaafata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 7, '(Guyyaan sun) yeroo ijji dhamaatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 8, '(Yeroo) jiini ifa dhabu (gaddiddaa’u)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 9, 'Aduufi jiinis walitti qabamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 10, 'Guyyaa san namni "bakki baqaa eessa?" jedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 11, 'Dhorgamaa! (Guyyaa san) iddoon baqaa hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 12, 'Guyyaa san bakki qubannaa gara Gooftaa keetiiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 13, 'Namni guyyaa san wanti inni durseefii booda aanse itti himama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 14, 'Dhugumatti, namni lubbuu isaa irratti ragaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 15, 'Odoma rakkoo adda addaa dhiyeeffateeyyuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 16, 'Isa (qabachuu)tti ariifachuuf jecha arraba kee isaan hin sochoosin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 17, 'Isa (onnee kee keessatti) walitti qabuufi isa dubbisuun kee nurra jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 18, 'Yeroo Nuti isa qaraane qiraatii isaa hordofi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 19, 'Ergasii isa ibsuun Nurra jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 20, 'Miti isin ariifattuu (duuniyaa) jaalattu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 21, 'Aakhiraa ni dhiiftu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 22, 'Fuulleen gariin Guyyaa san iftuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 23, 'Gara Gooftaa ishee ilaaltuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 24, 'Fuulli gariin Guyyaa san akkaan suntuurtuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 25, 'Balaan guddaan ishee irratti raawwatamuu yaaddi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 26, 'Miti Dhaga’aa! Yeroo (lubbuun ba''uuf) kokkee geesse,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 27, '(Yeroo) "eenyutu isa yaala?" jedhame,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 28, '(Namni du''aa jiru sun) inni (addunyaa kana irraa) adda ba''uu dha’ jechuu yeroo mirkaneeffate;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 29, '(Yeroo) mogoleen mogoleetti maramte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 30, 'Guyyaa san oofamiinsi gara Gooftaa keetiiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 31, 'Hin amanne; hin salaanne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 32, 'Garuu kijibsiisee irraa gara gale.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 33, 'Ergasii boonaa gara maatii isaa deeme.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 34, 'Badiin siif haa ta’u! Ammas badiin!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 35, 'Sana booda badiin siif haa ta’u! Ammas badiin!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 36, 'Sila namni akkanumaan dhiifamuu yaadaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 37, 'Sila inni bishaan saalaa kan dhangalaafamu irraa ta''ee hin turree?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 38, 'Ergasii dhiiga ititaa ta''eeti (nama godhee) uumee guute.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 39, 'Isa irraas cimdii lama, dhiiraafi dhalaa, taasise.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 40, 'Sila (Rabbiin akkas godhe) sun du''aa jiraachisuu irratti danda''aa mitii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 1, 'Sila barri hangi ta''e nama irra kan inni waan yaadatamu hin ta''in hin dhufnee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 2, 'Nuti nama, isa qormaatuuf jecha bishaan saalaa walitti makamaa ta''e irraa uumnee; Dhaga''aafi argaas isa goone.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 3, 'Nuti haala (inni) galateeffataa yookiin mormaa ta''een karaa isa qajeelchine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 4, 'Nuti kaafirootaaf sansalata, sakaallaawwaniifi ibidda boba''aa qopheessinee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 5, 'Warri gaggaariin khamrii makaan ishee kaafuuriin ta''e irraa dhugu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 6, '(Kun) burqaa gabroonni Rabbii ishee dhuganiidha. (Karaa fedhanitti) dhangalaafachuu ishee dhangalaafatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 7, 'Qodhaa (nazrii) isaanii ni guutu; guyyaa hamtuun isaa babal''atu ni sodaatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 8, 'Nyaata ofii jaallachuu wajjin hiyyeessa, yatiimaafi booji''amaas nyaachisu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 9, '(Ni jedhu): "wanti nuti isin nyaachifnuuf Fuula Rabbii qofaafi; isin irraa mindaas ta''ee galata wahii hin barbaannu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 10, 'Nuti Gooftaa keenya irraa Guyyaa fuula guuraa hammaataa ta''e sodaanna.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 11, 'Rabbiini hamtuu guyyaa gaafasii irraa isaan tikseeti (fuula isaaniis) ifaafi gammachuu qunnamsiise.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 12, 'Sababa isaan obsaniif jannataafi hariira galata isaaniif galche.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 13, 'Ishee keessatti sireewwan irratti hirkatanii (jiraatu), ishee keessatti aduufi qorra hamaa hin argan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 14, 'Haala gaaddisni ishee isaan irratti gadi dhihoo, firiiwwan ishees isaaniif laaffifamuu laaffifamteen (jannata seenu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 15, 'Meeshota meeta irraa ta''aniifi kubbaayyawwan qaruuraa irraa ta''een isaan irra naanna''ama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 16, 'Qaruuraalee meeta irraa ta''een likki godhan likkii godhiinsa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 17, 'Ishee keessattis khamrii makaan ishee zinjibila ta''e obaafamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 18, 'Burqaa ishee (jannata) keessa jirtu Salsabiil jedhamtee kan waamamtu (irraa obaafamu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 19, 'Ijoollee ishee keessatti hafoo ta’antu isaan irra naanna''a; yeroo isaan argitu faaya bibittinneeffame sitti fakkaatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 20, 'Yeroo achi keessa ilaalte qananiifi mootummaa guddaa argita.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 21, 'Gubbaa isaanii irra uffata hariira qal''aa magariisa fi hariira furdaatu jira; gumeelee meeta irraa ta''es ni faayamu. Gooftaan isaanii dhugaatii qulqulleessaa isaan obaasa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 22, '"kun galata isiniif ta''eera. Dalagaan keessanis galateeffatamaa dha" (isaaniin jedhama).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 23, 'Dhugumatti, Nuti Qur''aana buusiinsa sirratti buusnee jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 24, 'Murtii Gooftaa keetiitiif obsi; isaan irraa nama dilaawaa yookiin kafaraa ta''eef hin ajajamin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 25, 'Ganamaafi galgalas maqaa Gooftaa keetii faarsi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 26, 'Halkan irraallee Isaaf sujuudi (salaati); halkan dheeraas Isaaf (salaata laylii) salaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 27, 'Jarri kun (addunyaa) arifattuu jaalatu; guyyaa ulfaataa duuyda duuba isaaniitti dhiisu (dagatu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 28, 'Nuti isaan uumnee qaama isaaniis jabeessine; yeroo feene (isaan balleessinee) fakkaatuma isaanii bakka buusinsa bakka buufna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 29, 'Tuni gorsa; namni fedhe gara Gooftaa isaatti karaa godhata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 30, 'Yoo Rabbiin fedhe malee isin homaa hin feetan. Rabbiin beekaa ogeessa ta’eera.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 31, 'Nama fedhe rahmata Isaa keessa seensisa. Miidhaa raawwattoota immoo isaaniif adabbii laalessaa qopheesse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 1, '(Maleykota) wal hordoftuu ta''anii ergamaniinin kakadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 2, '(Bubbeewwan) humnaan bubbisuu bubbisaniinis;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 3, '(Bubbeewwan rooba) faffacaasuu facaasaniinis;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 4, '(Keeyyatoota haqaafi dhara) adda baasuu adda baasanittis;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 5, '(Malaykota) ergaa buuftotattis;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 6, 'Sababaa dhabamsiisuuf yookiin akeekkachiisuuf jecha (kan buusanittin kakadha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 7, 'Wanti (Qiyaamaan) isin sodaachifamtan argamaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 8, 'Yeroo urjiiwwan (ifti ishee irraa) haqamte,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 9, 'Yeroo samiileenis babbanamte;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 10, 'Yeroo gaarreenis (bakka irraa) bubuqqifamte,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 11, 'Yeroo Ergamoonnis beellamaan walitii qabamte;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 12, 'Guyyaa kamiif beellamaman?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 13, 'Guyyaa addaan bahiinsaatiif (beellamaman).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 14, 'Guyyaan Addaan bahiinsaa maal akka ta''e maaltu si beeksise?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 15, 'Kijibsiiftotaaf guyyaa san badiin mirkanaa''e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 16, 'Sila Nuti warra duraanii hin balleessinee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 17, 'Ergasiis warra boodaa isaan hordofsiifna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 18, 'Yakkamtootas akkanuma goona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 19, 'Kijibsiiftotaaf guyyaa san badiin mirkanaa''e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 20, 'Sila Nuti bishaan dadhabaa (maniyyii) irraa isin hin uumnee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 21, 'Bakka mijaa''aa keessas isa goone.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 22, 'Hanga yeroo beekamaatti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 23, 'Ni shallagnes; nuti shallagdoota akkaan tole.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 24, 'Kijibsiiftotaaf guyyaa san badiin mirkanaa''e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 25, 'Sila Nuti dachii kan hunda walitti qabdu hin taasifnee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 26, 'Jiraafi du''aas (walitti qabdi)?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 27, 'Gaarreen ragga''oo dhedheeraa ishee keessatti goone. Bishaan mi''aawaas isin obaafne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 28, 'Kijibsiiftotaaf guyyaa san badiin mirkanaa''e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 29, '(Isaaniin ni jedhama): "gara waan sobsiisaa turtanii deemaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 30, 'Gara gaaddisa abbaa damee sadihii deemaa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 31, 'Gaaddiseessaa miti; boba''aa ibiddaa irraas hin duroomsu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 32, 'Isheen qaanqeewwan akka gamoo darbatti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 33, 'Inni (qaanqechi) gaalota bobboora fakkaata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 34, 'Kijibsiiftotaaf guyyaa san badiin mirkanaa''e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 35, 'Kun Guyyaa isaan hin dubbanneedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 36, 'Rakkoo haa himataniif isaaniif hin eeyyamamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 37, 'Kijibsiiftotaaf guyyaa san badiin mirkanaa''e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 38, 'Kun guyyaa adda foo''amiinsaati; Isiniifi warra duraas walitti qabne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 39, 'Yoo tooftaa wahii qabaattan tooftaa Natti baafadhaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 40, 'Kijibsiiftotaaf guyyaa san badiin mirkanaa''e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 41, 'Dhugumatti, warri Rabbiin sodaatan gaaddisootaafi burqituuwwan keessa jiraatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 42, 'Asheeta irraa waan fedhan (keessa taa''u).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 43, '"Sababaa waan dalagaa turtaniitiif gammachuun nyaadhaa; dhugaa" (jedhamu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 44, 'Nuti akka kanatti warra toltuu hojjatan mindeessina.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 45, 'Kijibsiiftotaaf guyyaa san badiin mirkanaa''e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 46, '(Addunyaa irratti) "nyaadhaa; xiqqoo qanani''aa; dhugumatti isin badii hojjattoota” (isaaniin jedhama).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 47, 'Kijibsiiftotaaf guyyaa san badiin mirkanaa''e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 48, 'Yeroo ‘salaataa’ isaaniin jedhames hin salaatanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 49, 'Kijibsiiftotaaf guyyaa san badiin mirkanaa''e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 50, 'Isaan ala haasawa kamitti amanu ree?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 1, '[Warri hin amanin] maal irraa wal gaaggaafatan?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 2, 'Oduu guddaa irraa [wal gaafatu)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 3, 'Isa isaan isa keessatti wal dhaban [irraayi].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 4, 'Haa dhowwamanu! fuula dura beekuuf jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 5, 'Ammas haa dhowwamanu! fuula dura beekuuf jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 6, 'Sila Nuti dachii firaasha hin goonee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 7, 'Gaarreenis shikaaloowwan [hin goonee]?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 8, 'Cimdiis goonee isin uumne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 9, 'Hirriba keessan boqonnaa goone.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 10, 'Halkan uffata goone.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 11, 'Guyyaas yeroo jireenyaa (keessa hojjatan) goone.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 12, 'Gubbaa keessanitti [samii] jajjaboo torba ijaarre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 13, 'Ifaa boba''aas uumne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 14, 'Duumessa irraas bishaan dhangala''aa baay''ee buufne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 15, 'Isaan fuduraafi marga baasuuf jecha [buufne].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 16, 'Ashaakiltii damee wal keessa seensifattes.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 17, 'Guyyaan fooyamaa yeroo beellamamaa ta''e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 18, '[Guyyaan sun] guyyaa Garriin (xurumbaan) afuufamee isinis garee gareen dhuftanuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 19, '[Guyyaa] samiinillee banamtee hulaalee taatuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 20, 'Gaarreenis deemsifamtee siribii (siribduu) taate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 21, 'Dhugumatti jahannam keellaa taateetti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 22, 'Warra daangaa dabraniif iddoo deebiiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 23, 'Yeroo dheeraaf ishee keessa turu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 24, 'Ishee keessatti qabbanas ta''ee dhugaatii hin dhandhamanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 25, 'Bishaan akkaan danfaafi malaa malee [dhugaatii biraa hin argatanu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 26, 'Mindaa wal madaalu [mindeeffaman].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 27, 'Isaan qormaata hin sodaatanu turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 28, 'Keeyyattoota keenyas kijibsiisuu kijibsiisan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 29, 'Wanta cufaayyuu haala barreeffameen walitti qabne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 30, '“Dhandhamaa; azaaba malees isiniif hin daballu” [isaaniin jedhama].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 31, 'Warra Rabbiin sodaataniif milkiitu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 32, 'Ashaakiltiifi inabatu [jira].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 33, 'Dubartoota harma guntuttuu hiriyaa ta''antu [jiru].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 34, 'Geeba (xoofoo) guutamtuu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 35, 'Achi keessatti dubbii badaafi wal kijibsiisuu hin dhaga''anu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 36, 'Mindaa Gooftaa kee irraa ta’e kennaa ga’aa [mindeeffaman].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 37, 'Gooftaa samii, dachiifi waan gidduu isaanii jiru, mararfataa kan ta''e [irraa mindeeffaman]. Isaa wajjin dubbachuu hin danda''anu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 38, 'Guyyaa Jibriiliifi Maleykonni haala hiriiraniin dhaabbatan nama Rabbiin eeyyameefi dhugaa dubbate malee hin haasawanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 39, 'Sun guyyaa [dhufaatiin isaa] haqaati. Namni fedhe [hojii gaarii hojjachuun] gara Gooftaa isaatti deebii tolfata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 40, 'Nuti adabbii dhihoo tahe isin sodaachifne. kan guyyaa namni waan harki lamaan isaa dabarfatte argu, kan kaafirri jedhu "yaa hawwii kiyya! odoon biyyee ta’ee maal qaba".', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 1, '[Maleykaa lubbuu kaafiraa] humnaan buttuunin (kakadha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 2, '[Kan lubbuu mu’uminaa] luqqisuu suuta luqqiftuunis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 3, '[Kan ajaja Rabbii geessuuf] adeemuu demaniinis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 4, 'Maleykota] dorgommii wal dorgomaniinis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 5, '(Kan) ajaja Rabbii gara dachii geessaniininis (nan kakadha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 6, 'Guyyaa sochootuun [afuuffiin xurumbaa nama] sochooftu;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 7, 'Hordoftuutu (afuuffii biraatu) ishee hordofa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 8, 'Onneewwan guyyaa san rifattuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 9, 'Ijji ishee salphattuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 10, 'Ni jedhu: "sila nuti dhugumatti haala jireenya duriitti ni deebifamnaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 11, 'Sila erga lafee dhumte taanee moo?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 12, 'Yoo akkas ta''e sun deebii hoongooti" jedhan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 13, 'Isheen iyya (afuuffii) tokko qofa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 14, 'Yeroma san isaan gubbaa dachii irratti ta''u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 15, 'Sila haasofni waa’ee Muusaa sitti dhufee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 16, 'Yeroo Gooftaan isaa laga qulqulleffamaa "Xuwaa" jedhamu keessatti isatti lallabe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 17, 'Gara Fir''awn deemi; inni daangaa darbee jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 18, 'Jedhiin: "sila gara (shirkii irraa) qulqulleffachuutti fedha qabdaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 19, 'Akka sodaattuuf gara Gooftaa keetii si qajeelchutti (fedha qabdaa)."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 20, '[Muusan] mallattoo guddaa isa (Fir''awniin) agarsiise.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 21, 'Inni (Fir’awn) sobsiisee faallesse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 22, 'Ergasii ariifataa gara gale.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 23, 'Sana booda walitti qabee lallabe:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 24, '“Ani gooftaa keessan isa ol aanaadha” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 25, 'Sana booda Rabbiin adabbii [badii] boodaatiifi jalqabaatiifis isa qabe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 26, 'Dugumatti, kana keessa nama Rabbiin sodaatuuf gorsatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 27, 'Sila uumaa keessantu irra jabaata moo samii dha? Inni (Rabbiin) ishee ni ijaare.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 28, 'Ijaarsa ishee ol fuudhee, ishee wal qixxeesse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 29, 'Halkan ishee dukkaneessee guyyaa ishee ibse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 30, 'Dachii sana booda sirreesse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 31, 'Ishee irraa bishaan isheetiifi biqiltuu ishee ni baase.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 32, 'Gaarreenis dachii irra ni dhaabe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 33, 'Isiniifi beelladoota keessan qanansiisuuf [kana godhe].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 34, 'Yeroo balaan guddoon (Qiyaamaan) dhufte,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 35, 'Guyyaa namni waan hojjate hunda yaadatu,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 36, '(Guyyaa) ibiddi jahannam namuma arguuf mul''atte,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 37, 'Namni daangaa dabree,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 38, 'Jireenya addunyaa kanaa filate,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 39, 'Dhugumatti, jahannam teesson isaa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 40, 'Namni Gooftaa isaa dura dhaabbachuu sodaatee, lubbuu isaa waan isheen hawwitu irraa dhorge,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 41, 'Dhugumatti, jannanni bakka qubannaa isaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 42, '[Yaa Muhammad SAW!] Qiyaamaa irraa, yoom argamtii ishee si gaafatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 43, 'Ati beekumsa ishee irraa maal keessa jirta?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 44, 'Beekumsi ishee kan dhumaa garuma Gooftaa keetiiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 45, 'Ati akeekkachiisaa nama ishee sodaatuuti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 46, 'Isaan guyyaa ishee argan akka waan isaan galgala tokko yookiin ganama tokko malee (addunyaa irra) hin turin itti fakkaata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 1, 'Fuula guuree gara gale.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 2, 'Sababa jaamaan isatti dhufeef.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 3, 'Maaltu si beeksise? Qulqullaa’uun isaa ni kajeelama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 4, 'Yookiin gorfameeti gorsi isa fayyaddi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 5, 'Nama duroome immoo,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 6, 'Ati [akka amananuuf jecha] gara isaa gara galta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 7, 'Haala qulqullaa''uu dhiisuun isaa homaa sirra hin jirreen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 8, 'Nama fiigaa sitti dhufe immoo,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 9, 'Kan Rabbiin sodaatu ta’ee,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 10, 'Ati isa irraa dagatta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 11, 'Dhorgami! Isheen gorsa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 12, 'Nama fedhetu isa (Qur''aana) yaadata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 13, 'Galmeewwan kabajamtuu keessa jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 14, 'Ol fuudhamtuu, qulqulleeffamtuu (keessa jira).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 15, 'Harka barressitootaa (maleykotaa) jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 16, 'Kabajamoo, ajajamtoota (harka jira).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 17, 'Namni abaarame! Sila maaltu isa kafarsiise?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 18, '(Rabbiin) waan akkamii irraa isa uume? (hin xiinxaluu?)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 19, 'Bishaan saalaa irraa isa uumeeti, ergasii isa sirreesse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 20, 'Ergasii karaa (inni ittiin dhalatu) isaaf laaffise.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 21, 'Ergasii isa ajjeeseti isa awwaalchise.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 22, 'Ergasii yeroo fedhe isa kaasa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 23, 'Dhugumatti, (namni) waan Rabbiin isa ajaje ammallee hin raawwanne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 24, 'Namni gara nyaata isaa haa ilaalu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 25, 'Nuti bishaan buusiinsa baay’inaan buufne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 26, 'Ergasii dachii dhodhoosiinsa dhodhoofne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 27, 'Achumaan Ishee keessatti firii magarsine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 28, 'Inabaafi margas,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 29, 'Zeytunaafi muka timiraas,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 30, 'Ashaakiltiilee muka baay’atanis,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 31, 'Fuduraafi kaloo [akka nuti uumne haa ilaalu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 32, 'Isiniifi beylada keessanis qanansiisuuf.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 33, 'Yeroo gurra duuchituun (Qiyaamaan) dhufte,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 34, 'Guyyaa namni obboleessa isaa irraa dheessu,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 35, 'Haadha isaatiifi abbaa isaa irraas,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 36, 'Niitii isaatiifi ijoollee isaa irraas (baqatu san dhufti).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 37, 'Nama Isaan irraa ta’e hundaaf guyyaa sana dhimma isa duroomsutu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 38, 'Fuulli gariin guyyaa san ni ifti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 39, 'Kolfituu, gammadduudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 40, 'Fuulli gariin immoo guyyaa san dhukkeetu (quttootu) irra jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 41, 'Gurraachinni ishee haguuga.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 42, 'Isaan sun warra Rabbitti kafaranii, balleessa hojjataniidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 1, 'Yeroo aduun maramte,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 2, 'Yeroo urjiin harcaate,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 3, 'Yeroo gaarreen bakkaa oofamte,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 4, 'Yeroo gaalli rimaan baatii kudhanii dhiifamte (tiksitee malee hafte),', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 5, 'Yeroo bineensonni bosonaa walitti qabamte,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 6, 'Yeroo galaanni qabsiifamte (akka ibiddaatti boba''an),', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 7, 'Yeroo lubbuuleen hundi qindeeffamte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 8, 'Yeroo durbi jirtuun awwaalamte gaafatamte,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 9, 'Balleessa kamiif akka ajjeefamte;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 10, 'Yeroo galmeen (hojii) raabsamte,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 11, 'Yeroo samiin buqqifamtee maramte,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 12, 'Yeroo ibiddi qabsiifamte,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 13, 'Yeroo jannanni dhiheeffamte,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 14, 'Lubbuun waan dalagatte beekteetti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 15, '(Urjiiwwan) guyyaa badanii halkan mul''ataniinin kakadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 16, '(Urjiiwwan) yaa’aa seenaa ta’aniinin (kakadha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 17, 'Halkaniinis yeroo inni dukkanaa’en (kakadha),', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 18, 'Bariittillee yeroo inni hafuura baafate (ife) (kakadha),', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 19, 'Inni (Qur''aanni) kun jecha Ergamaa kabajamaati [1]', '[1] Qur''aanni kuni jecha Rbbiiti jibriil fuudhee nabi muhammaditti geessuudha.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 20, '(Ergamaa) abbaa humnaa ta''e, kan Gooftaa Arshii biratti iddoo jabaa qabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 21, 'Bakka sanatti ajajni isaa fudhatamaafi amanamaa kan ta''e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 22, 'Saahibni keessan (Muhammad SAW!) maraataa miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 23, 'Dhugumatti, inni moggaa ol aanaa (samii) ifa galaa (gara Bahaa) keessatti isa argee jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 24, 'Inni (Nabiyyiin) beekumsa fagoo irratti don''aa miti (hin dhoksu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 25, 'Inni (Qur''aanni) jecha sheeyxaana darbamaa miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 26, 'Mee eessuma deemtu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 27, 'Inni aalama hundaaf gorsa malee hintaane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 28, 'Nama isin irraa qajeeluma fedheef (gorsa ta''a).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 29, 'Yoo Rabbiin aalama hundaa fedhe malee isin homaa hin feetanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 1, 'Yeroo samiin dhodhoote,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 2, 'Yeroo urjiiwwan harcaate,,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 3, 'Yeroo galaanonni walitti makaman,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 4, 'Yeroo qabroonni gara gaggalfamtee du’aa ishee keessa jiru ol baafte,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 5, '(Yeroo san) lubbuun hundi waan dabarfatte (hojjattee)fi baada aansite ni beekti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 6, 'Ati Yaa nama! Gooftaa kee kan Arjaa ta''etti (amanuu irraa) maaltu si dage?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 7, 'Isa si uumee, ergasii si guutee, si sirreesse,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 8, 'Boca fedhe keessatti walitti si qabe (sanarraa maaltu si gowwoomse)?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 9, 'Dhorgamaa! Dhugumatti, guyyaa murtii ni sobsiiftu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 10, 'Isin irra to’attootatu jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 11, 'Kabajamoo, barreessitoota kan ta’an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 12, 'Waan isin dalagdan ni beeku.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 13, 'Dhugumatti, warri toltuu hojjatan qananii keessa jiraatu', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 14, 'Warri hamtuu hojjatan immoo ibidda keessa jiraatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 15, 'Guyyaa murtii ishee seenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 16, 'Isaan ishee irraa hin fagaatanu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 17, 'Sila guyyaan murtii maal akka ta''e maaltu si beeksise?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 18, 'Ergasii guyyaan murtii maal akka ta''e maaltu si beeksise?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 19, '(Inni) guyyaa lubbuun takka lubbuu biraatiif homaa gochuu hin dandeenye. Guyyaa san wanti (hundi) kan Rabbiiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 1, 'Salaabiiwwaniif (warra safara hir’isuuf) badiin haa ta’u!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 2, 'Isaan yeroo namoota irraa safaratan guuchisiifatan,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 3, 'Kan Yeroo namootaaf safaran yookiin miizaanan immoo hir’isan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 4, 'Sila isaan sun kaafamuu isaanii hin yaadanii?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 5, 'Guyyaa guddaadhaaf.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 6, 'Guyyaa namni Gooftaa aalamaatiif dhaabbatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 7, 'Dhugumatti, galmeen badii hojjattootaa Sijjiin keessa ta''a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 8, '"Sijjiin" maal akka ta''e maaltu si beeksise?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 9, 'Kitaaba barreeffamaadha (dalagaa yakkamtootaatu irratti barreeffama).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 10, 'Kijibsiiftotaaf Guyyaa san badiin mirkanaa’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 11, 'Isaan guyyaa murtii sobsiisaniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 12, 'Daangaa darbitoota dilaawoo cufa ta’e malee namni isa kijibsiisu hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 13, 'Yeroo keeyyattoonni Keenya isaan irratti qara''amte "ogbarruu warra duriiti" jedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 14, 'Haa dhorgamanu! Dhugumatti wanti isaan hojjataa turan onnee isaanii haguuge.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 15, 'Haadhoorgamanii! Isaan guyyaa san Gooftaa isaanii irraa haguugamoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 16, 'Ergasii isaan ibidda seenoodha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 17, 'Ergasii "inni kun isa isin sobsiisaa turtan" jedhama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 18, 'Dhugumatti, galmeen toltuu hojjattootaa Illiyyiin keessatti ta''aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 19, '"Illiyyiin" maal akka ta''e maaltu si beeksise?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 20, 'Kitaaba barreeffamaadha (hojii warra Rabbitti amaneetu irratti barreeffame).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 21, 'Warra Rabbitti dhiheeffamantu isa arga.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 22, 'Dhugumatti, toltuu hojjattoonni qananiilee keessa jiraatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 23, 'Sireewwan irra (taa''anii) ilaalu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 24, 'Fuula isaanii keessatti ifina qananii ni beekta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 25, 'Farsoo qadaadamaa irraa obaafamu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 26, 'Dhumti isaa miskiidha; sana keessatti warri wal dorgoman wal haa dorgoman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 27, 'Makaan isaas ‘Tasniim’ irraayi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 28, '(Tasniim) laga warri Rabbitti dhiheeffaman dhuganiidha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 29, 'Dhugumatti, isaan dilaawan isaan amananitti kolfaa turan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 30, 'Yeroo isaan bira dabran wal akeeku.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 31, 'Yeroo gara maatii isaanii deebi''an gammadaa deebi’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 32, 'Yeroo isaan argan "dhugumatti, isaan kun jallattoota" jedhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 33, 'Haala to''attoota ta''anii isaan irratti hin ergaminiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 34, 'Har’a (guyyaa kaafamiinsaa) isaan amanantu kaafirootatti kolfa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 35, 'Sireewwan irra (ta''anii) ilaalu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 36, '"Sila kaafiroonni waan dalagaa turan mindeffamaniiruu?” [jedhu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 1, 'Yeroo samiin dhodhoote', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 2, '(Yeroo isheen ajaja) Gooftaa ishee dhaggeeffatte; (wanti kana godhu waan itti argameef) dhugaa qabdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 3, 'Yeroo dachiin diriirfamte,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 4, 'Waan ishee keessa jiru darbitee, duwwaa taate,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 5, '(Yeroo isheen ajaja) Gooftaa ishee dhaggeeffatte; (wanti kana godhu waan itti argameef) dhugaa qabdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 6, 'Ati Yaa nama! Ati gara Rabbii keetii (dhaqqabuuf) hojiin laffa''aadha laffa''iinsa, isa qunnamaadhasi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 7, 'Namni kitaaba isaa mirga isaatiin kenname;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 8, 'Qormaata salphaa qoramuuf jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 9, 'Gammadaa gara maatii isaa deebi’a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 10, 'Namni kitaaba isaa dugdaisaa duubaan kenname immoo;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 11, 'Badii yaamuuf jira (Yaa badii tiyya jedhee).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 12, 'Ibidda boba’aa seena.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 13, 'Inni maatii isaa keessatti gammadaa ture.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 14, 'Inni (gama Rabbii) hindeebi’uu yaade.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 15, 'Lakki! (ni deebi’a) Gooftaan isaa isa argaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 16, 'Miti! Diimina galgalaattin kakadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 17, 'Halkaniifi waan inni walitti qabeenis (nan kakadha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 18, 'Ji''attis yeroo inni guuteenin (kakadha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 19, 'Isin sadarkaa tokko irraa gara sadarkaa biraatti ceetu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 20, 'Maaltu isaaniif jiraayi hin amanne?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 21, 'Yeroo Qur''aanni isaan irratti qara''amu hinsujuudan. [1]', '[1] as sujuuda qaraatii qur''aanaattu jira.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 22, 'Dhugumaatti, warri kafaran ni sobsiisu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 23, 'Rabbiin beekaa waan isaan (onnee isaanii keessatti) walitti qabaniiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 24, 'Adaba laalessaadhaan isaan gammachiisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 25, 'Isaan amananii gaggaarii hojjatan malee isaaniif mindaa hin cinnetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 1, 'Samii abbaa orbitii urjiitiin (nan kakadha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 2, 'Guyyaa beellamamaanis,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 3, 'Ragaa ba''aafi warra ragaan itti ba''amuunis (nan kakadhaa),', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 4, 'Warri handaqa abaaraman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 5, '(Warri) ibidda boba’aa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 6, 'Yeroo isaan ishee irra taa''an,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 7, 'Isaan waan mu''imintootatti hojjatan irratti hirmaattota.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 8, 'Rabbii injifataa, faarfamaatti amanuu malee homaa isaan irraa hinjibbine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 9, '(Rabbiin) Isa mootummaan samiifi dachii Isaaf ta''eedha. Rabbiin waan hunda irratti ragaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 10, 'Isaan mu''imintoota dhiiraafi dubartootaa rakkisanii ergasii gara Rabbii isaanii kan hin deebi''in (hin tawbatin) isaaniif adabbii jahannamtu jira; ammas isaaniif adabbii gubaatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 11, 'Isaan amananii gaggaarii hojjatan, isaaniif ashaakiltiiwwan laggeen jala ishee yaatutu jira. Sun milkii guddaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 12, 'Qabaan Gooftaa keetii haalaan cimaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 13, 'Inni Isumatu [uumama] jalqaba; (du''a boodas) ni deebisa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 14, 'Inni akkaan araaramaa, akkaan jaalataadha', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 15, '(Inni) abbaa Arshiiti; guddaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 16, 'Waan fedhe akkaan hojjataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 17, 'Sila oduun waraanaa si ga''eeraa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 18, '(Waraana) Fir''awniifi Samuud.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 19, 'Dhugumatti, isaan kafaran kijibsiisuu keessa jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 20, 'Rabbiin immoo duuba isaanii irraan marsaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 21, 'Dhugumatti, inni Qur''aana guddaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 22, 'Luuhii tiikfamaa keessa jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 1, 'Samiifi (urjii) halkan dhufaa ta’eenin (kakadha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 2, '(Urjii) halkan dhufaa ta’e maaltu si beeksise?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 3, '(Inni) urjii ifti isaa dukkana uraa ta’eedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 4, 'Lubbuun hundi tiksaan ishee irra jiraatu malee hin hafu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 5, 'Namni maal irraa akka uumame haa ilaalu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 6, 'Bishaan utaalaa irraa uumame.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 7, 'Jidduu dugdaatiifi qomaatii kan ba’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 8, 'Inni isa deebisuu irratti danda’aadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 9, 'Guyyaa iccitiiwwan ifa ba''an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 10, '(Gaafas) humnas ta’ee tumsaan isaaf hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 11, 'Samii abbaa deddeebiitiinin (kakadha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 12, 'Dachii dhodhootuunin (kakadha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 13, 'Inni (Qur''aanni) jecha adda baasaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 14, 'Inni qoosaa miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 15, 'Dhugumatti, isaan shira shiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 16, 'Anis shiran baasa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 17, 'Kaafirootaaf yeroo kenni. Ammas xinnoo yeroo kenniif.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 1, 'Maqaa Gooftaa kee olaanaa ta''ee qulqulleessi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 2, 'Isa (waan hunda) uumee guute.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 3, 'Isa murteessee qajeelche.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 4, 'Isa marga baase,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 5, 'Goggogaa gurraacha isa taasise.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 6, 'Si qaraasisuuf jirraa hin dagattu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 7, 'Waan Rabbiin fedhe malee Inni mul’ataafi dhokataas ni beeka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 8, 'Nuti karaa laaftuu taateef si laaffifna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 9, 'Yoo yaadachiisni fayyadde yaadachiisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 10, 'Namni Rabbiin sodaatu gorfamuuf jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 11, 'Hoonga''aan ishee irraa fagaata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 12, 'Inni ibidda guddoo seenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 13, 'Ergasii ishee keessatti hin du''u; hin jiraatus.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 14, 'Dhugumatti, namni of qulqulleeffate milkaa’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 15, 'Maqaa Gooftaa isaa dubbatee kan salaate.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 16, 'Inumaa isin jiruu addunyaa filattu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 17, 'Odoo Aakhiraan caaltuufi haftuu taatee jirtuu [addunyaa filattu].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 18, 'Kun barreeffamoota duraanii keessa jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 19, 'Barreeffamoota Ibraahiimifi Muusaa [keessa jira].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 1, 'Sila oduun haguugduu (Qiyaamaa) sitti dhufeeraa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 2, 'Fuulleen (gariin) guyyaa san xiqqaattuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 3, 'Hojjattuu ifaajjuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 4, 'Ibidda gubduu seenti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 5, 'Burqituu danfituu irraa obaafamti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 6, 'Adaamii malee nyaanni isaaniif hin jiru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 7, 'Hin gabbisu; beela irraas hin duroomsu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 8, 'Fuulleen gariin guyyaa san qananiituudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 9, 'Dalagaa ishee jaalattuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 10, 'Jannata ol fuudhamtuu keessa jiraatti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 11, 'Ishee keessatti waca hin dhaga''anu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 12, 'Ishee keessa burqituu yaatutu jirti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 13, 'Ishee keessa sireewwan ol fuudhamtuutu jirti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 14, 'Kubbaayyaawwan kaa’amtuutu jirti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 15, 'Boraatiiwwan tarree galfamantu (isaaniif jira).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 16, 'Afaawwan diriirfamanis (isaaniif jirti).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 17, 'Sila gara gaalaa akkamitti akka uumamte hin ilaalanuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 18, 'Gara samii akkamitti akka ol fuudhamte (hin ilaalanuu)?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 19, 'Gara gaarreenis akkamitti akka dhaabamte (hin ilaalanuu)?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 20, 'Gara dachiis akkamitti akka diriirfamte (hin ilaalanuu)?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 21, 'Yaadachiisi; ati yaadachiisaa qofa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 22, 'Isaan irratti dirqisiisaa hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 23, 'Nama gara galee kafare malee,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 24, 'Rabbiin adabbii guddaa isa adaba.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 25, 'Deebiin isaanii garuma Keenya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 26, 'Ergasii qormaanni isaanii Nurra jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 1, 'Bariinin (kakadha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 2, 'Halkan kurnaniinis,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 3, 'Cimdiifi qarattis;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 4, 'Halkanittis; yeroo inni deeme.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 5, 'Sila sana keessa abbootii sammuutiif kakuun quubsaan hin jiruu? (ni jira)!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 6, 'Sila akkam akka Gooftaan kee Aaditti hojjate hin arginee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 7, 'Iramiin warra dhedheerootti,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 8, 'Ishee fakkiin ishee biyyoota keessatti hin uumamin san.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 9, 'Samuudittis warra laga (Hijri) keessatti dhagaa uran (mana irraa tolfatan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 10, 'Fir''awniinis abbaa shikaalaatti;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 11, 'Isaan biyyoota keessatti daangaa dabran.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 12, 'Kan ishee keessatti badii baay''isan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 13, 'Gooftaan kee akaakuu adabbii isaan irratti buuse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 14, 'Gooftaan kee keellatti tahaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 15, 'Ammoo Namni yeroo gooftaan isaa isa qorate, isa kabajee, isa qanansiise nijedha “Gooftaan kiyya na kabaje”.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 16, 'Yeroo inni hiree isaa itti xiqqeessee isa qorate immoo “Gooftaan kiyya na xiqqeesse” jedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 17, 'Haa dhorgamu! Dhugumatti, isin yatiima hin kabajjan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 18, 'Hiyyeessa nyaachisuu irrattis hin kakaaftan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 19, 'Qabeenya dhaalaa, nyaata [halaalaafi haraama] walitti qabate nyaattu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 20, 'Jaalala baay’ee qabeenya jaalattu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 21, 'Dhorgamaa! Yeroo dachiin waliin dhawamiinsa jabaa waliin dhawamte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 22, '(Yeroo) Gooftaan kee dhufee maleykonnis hiriira hiriiran [dhufan].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 23, 'Guyyaa san jahannamis ni fidama Guyyaa san namni ni yaadata Yaadannoon (guyyaa sanii) maal isaaf godha ree?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 24, 'Ni jedha: "odoon jiruu kiyyaaf dabarfadheen hawwa."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 25, 'Guyyaa san adabbii Isaa eenyunuu hin adabu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 26, 'Hidhaa Isaas eenyunuu hin hidhu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 27, '“Ati Yaa lubbuu tasgabbooftuu!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 28, 'Gara Gooftaa keetii deebi''i Jaallatuu, jaallatamtuu tahaadhaa .', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 29, 'Gabroota kiyya keessas seeni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 30, 'Jannata kiyyas seeni” (jedhamti)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 1, 'Miti Biyya (Makkaa) kanaanin kakadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 2, 'Ati biyyia kana qubataadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 3, 'Abbaafi waan inni dhaleenis (nan kakadha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 4, 'Dhugumatti, Nuti nama cinqii[] keessatti uumne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 5, 'Sila inni tokkolleen isa irratti hin danda''uu yaadaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 6, '“Qabeenya guddaan balleesse" jedha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 7, 'Sila inni tokkolleen isa hin arguu yaadaa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 8, 'Sila Nuti ija lama isaaf hin taasifnee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 9, 'Arrabaafi hidhii lameenis;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 10, 'Karaa lama (gaariifi badaa) isaaf ibsine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 11, 'Sila maaliif tulluu hin dabrine?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 12, 'Tulluttiin maal akka taate maaltu si beeksise?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 13, '(Inni) Gabra bilisoomsuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 14, 'Yookiin guyyaa beelaa keessa nyaachisuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 15, 'Yatiima fira ta’an;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 16, 'Yookiin hiyyeessa harkaan lafa qabate (deege).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 17, 'Ergasii warra amananii, obsa waliif dhaamaniifi rahmata waliif dhaaman irraa maaliif hin taane?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 18, 'Isaan sun warra mirgaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 19, 'Isaan keeyyattoota keenyatti kafaran immoo isaan warra bitaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 20, 'Isaan irratti ibiddi cufamtuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 1, 'Aduufi ifa isheetiinin (kakadha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 2, 'Ji’aanis; yeroo inni ishee hordofe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 3, 'Guyyaanis yeroo inni ishee (aduu) mul’ise;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 4, 'Halkaniinis yeroo inni ishee haguuge;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 5, 'Samiifi kan ishee ijaareenis;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 6, 'Dachiifi kan ishee diriirseenis;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 7, 'Lubbuufi kan ishee uumeenis;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 8, 'Kan jall’ina isheefi qajeeluma ishee ishee barsiise.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 9, 'Namni ishee qulqulleesse dhugumatti milkaa’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 10, 'Namni ishee xureesses dhugaatti hoonga’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 11, 'Samuud daangaa dabruu isheetiin kijibsiifte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 12, 'Yeroo irra jallaan ishee ka’u (kijibsiifte).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 13, 'Ergamaan Rabbiis isaaniin “gaala Rabbiitiifi dhugaatii ishee (eeggadhaa)” jedhe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 14, 'Isa kijibsiisanii, ishee waraanan, Rabbiin isaanii Sababa badii isaanii isaan balleessee, ishee wal qixxeesse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 15, 'Haaloo ishee hin sodaatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 1, 'Halkaniin (nan kakadha); yeroo (inni) haguuge.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 2, 'Guyyaanis yeroo inni mul''ate;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 3, 'Isa kormaafi dhalaa uumeenis;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 4, 'Dhugumatti, dalagaan keessan adda adda (wal dhaba).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 5, 'Ammoo Namni kennatee Rabbiin sodaate,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 6, 'Islaamummaas dhugoomse,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 7, '(Karaa) laaftuuf isa laaffisuuf jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 8, 'Ammoo Nama don’oomee of ga’e,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 9, 'Islaamummaa sobsiise,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 10, '(Karaa) jabduuf isa laaffisuuf jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 11, 'Yeroo inni (ibiddatti) kufu qabeenyi isaa isa hin fayyadu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 12, 'Karaa qajeelaa ifa galchuun (mul''isuun) Nurra jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 13, 'Aakhiraafi addunyaan keenya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 14, 'Ibidda qabsiifamaa ta''e isin sodaachise.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 15, 'Hoonga’aa malee ishee hin seenu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 16, 'Kan sobsiisee gara gale (malee).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 17, 'Namni Rabbiin sodaatu immoo ishee irraa fageeffamuuf jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 18, 'Kan qabeenya isaa qulqulleeffachuuf kennu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 19, 'Haala isa bira nama tokkoof galanni galfamu hin jirreen (kan kennatu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 20, 'Fuula Gooftaa isaa ol aanaa ta''e barbaachaaf malee (hin kennu).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 21, 'Dhugumatti, inni fuulduratti jaalachuuf jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 1, 'Waareenin (kakadha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 2, 'Halkaniinis yeroo inni callise.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 3, 'Gooftaan kee si hin dhiifne; si hin jibbines.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 4, 'Aakhiraatu addunyaa irra siif caala.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 5, 'Dhugumatti, Rabbiin kee fuula dura (kenna guddaa) siif kenna; ni jaallattas.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 6, 'Sila yatiima ta’uu si argee si hin hirkifnee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 7, 'Dogoggoraas ta’uu si argee si qajeelche.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 8, 'Hiyyeessas taatee si argee si duroomse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 9, 'Yatiima hin hacuucin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 10, 'Kadhataas hin xixin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 11, 'Ni''imaa (qananii) Gooftaa keetiis odeessi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 1, 'Sila Nuti qoma kee siif hin bal''ifnee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 2, 'Ba’aa (badii) kee sirraa buufne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 3, 'Isa dugda keetti ulfaate (sirraa buufne).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 4, 'Maqaa keetis siif ol kaafne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 5, 'Rakkinaa wajjin laafinatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 6, 'Dhugumatti, rakkina wajjin laafinatu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 7, 'Yeroo (dalagaa wahii) raawwatte xaari (ta biraa ittifufi).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 8, 'Gara Gooftaa keetii qofa kajeeli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 1, 'Tiiniifi Zaytuuniiniin (kakadha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 2, 'Gaara (Tulluu) xuuri Siiniinaatiinis.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 3, 'Biyya nagaa kanaanis (nin kakadha).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 4, 'Dhugumatti, Nuti nama dhaabbii irra gaarii ta''e keessatti isa uumne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 5, 'Ergasii bakka warra jalaa hundarra gadi aanaa ta''etti isa deebifne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 6, 'Isaan amananii gaggaarii dalagan malee isaaniif mindaa addaan hin cinnetu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 7, 'Kana booda maaltu galata [guyyaa Qiyaamaa] si kijibsiisisa (kijibsiisutti si kaase)?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 8, 'Sila Rabbiin irra murteessaa murteessitootaa hin taanee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 1, 'Maqaa Gooftaa keetii Isa (waan hunda) uumeetiin dubbisi.[1]', '[1] Aayatoowwan tuni dura waan qur''aanarraa nabi muhammad s.a.w. irratti buufameeti.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 2, '(Isa) nama dhiiga ititaa irraa uume.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 3, 'Haala Gooftaan kee hunda irra arjaa ta’een qara''i.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 4, 'Isa qalamaan (barreessuu) barsiise sani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 5, 'Nama, waan inni hin beekne barsiise.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 6, 'Dhugumatti, namni daangaa dabra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 7, 'Sababa duroomuu of arguutiin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 8, 'Deebiin garuma Gooftaa keetiiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 9, 'Sila isa dhorgu san argitee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 10, 'Gabricha yeroo inni salaatu (kan dhorgu argitee)?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 11, 'Yoo inni qajeeluma irra jiraate hoo mee naaf himi!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 12, 'Yookiin immoo sodaa Rabbiitti yoo ajaje hoo?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 13, 'Yoo inni (Abuu Jahal) kijibsiisee irraa gara gale hoo mee naaf himi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 14, 'Sila inni Rabbiin niargaa hin beekuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 15, 'Haa dhorgamu; yoo inni (Abuu Jahal) dhorgamuu baate, sammuu qabna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 16, 'Sammuu sobduu, dogoggortuu taate (qabna).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 17, 'Garee isaa haa waammatu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 18, 'Nutis waardiyyaa keenya waammachuuf jirra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 19, 'Dhorgami! Isaan hin ajajamin, Sujuudis, gara Rabbiittis dhihaadhu.[1]', '[1] Asitti sujuuda qaraatii qur''aanaattu bu''ama. kun sujuuda xumuraati.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (97, 1, 'Dhugumatti, Nuti halkan sadarkaa qabdu keessa isa (Qur''aana) buufne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (97, 2, 'Halkan sadarkaa qabdu maal akka taate maaltu si beeksise?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (97, 3, 'Halkan sadarkaa qabdu ji''a kumarra caalti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (97, 4, 'Maleykonniifi Jibriil ishee keessa eeyyama Gooftaa isaaniitiin waayee hundaan bu''u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (97, 5, 'Isheen hanga baha fajriitti nagaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 1, 'Warri abbootii kitaabaafi mushrikoota irraa kafaran jallina isaanii kan gadidhiisan hintaane hanga ragaan isaanitti dhufetti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 2, '(Ragichis) ergamaa Rabbi irraa ta’e kan kitaabota qulqulleeffame dubbisu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 3, 'Ishee keessa barreeffamoota sirriitu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 4, 'Isaan kitaaba kennaman adda hinfacaane eega ragaan ifaan isaanitti dhufue booda malee.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 5, 'Rabbiin qofa gabbaruu, qajeelanii amantii Isa qofaaf qulqulleessuu, salaata dhaabuufi zakaa kennuutti malee homaa hin ajajamne. Kun amantii qajeelaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 6, 'Warri abbootii kitaabaafi mushrikoota irraa kafaran ibidda jahannam keessatti hafoo ta’anii jiraatu. Warri sun isaanumatu irra hamtuu uumamaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 7, 'Isaan amananiifi gaggaarii hojjatan, isaan sun isaanumatu irra caalaa uumamaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 8, 'Mindaan isaanii Gooftaa isaanii biratti jannata qubsumaa, kan jala ishee laggeen yaatu, zalaalam ishee keessa jiraatu. Rabbiin isaan irraa jaalateera; isaanis Isa irraa jaalataniiru. Kun nama Gooftaa isaa sodaatuuf qofa ta’a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 1, 'Yeroo dachiin sochii ishee sosochoote,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 2, '(yeroo) dachiin ba''aa ishee baafte,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 3, 'Namni "sila isheen maal taate?" jedhe,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 4, 'Guyyaa san (dachiin) oduu ishee ni odeessiti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 5, '[Kunis] Waan Gooftaan kee isheetti beeksisa godheef.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 6, 'Guyyaa san namoonni hojii isaanii agarsiifamuuf jecha garee gareen (bakka dhaabbii irraa) deebi’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 7, 'Namni (hanga) madaala atomii toltuu dalage isuma arga.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 8, 'Namni (hanga) madaala atomii hamtuu dalages isuma arga.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 1, '(Faradoo jihaadaa) harganaa guluftuunin (kakadha),', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 2, '(Isaan yeroo gulufan kottee isaaniitiin) ibidda qabsiisaniin,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 3, '(Isaan) bariidhaan (diina irratti) weerara adeemsisanitti;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 4, 'Isaan dhukkee ol kaasanitti;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 5, 'Isaan (weeraraan) gamtaa diinaa walakkeessaniin [kakadha].', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 6, 'Dhugumatti, namni (hedduun) Gooftaa isaa mormaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 7, 'Inni kana irratti ragaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 8, 'Inni (namni) qabeenya jaalachuutti cimaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 9, 'Sila inni yeroo wanti qabroota keessa jiran hundi baafaman sana hin beekuu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 10, 'Yeroo wanti qomoota keessa jiran (hundi) ifa baafaman (hin beekuu?)', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 11, 'Dhugumatti, Gooftan isaanii guyyaa san isaan beekaadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 1, 'Qalbii rukuttuun (Qiyaamaan).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 2, 'Qalbii rukuttuun maali?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 3, 'Qalbii rukuttuun maal akka taate maaltu si beeksise?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 4, 'Guyyaa namni akka billaacha faffacaafamee ta’u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 5, '(Guyyaa) gaarreen akka jirbii iddamee (qaasasame) ta''u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 6, 'Namni madaalli (hojii) isaa ulfaatte,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 7, 'Inni jireenya jaalatamtuu keessa ta''a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 8, 'Namni madaalli (hojii) isaa salphatte immoo,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 9, 'Qubannoonni isaa “Haawiyaa”dha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 10, 'Isheen (Haawiyaan) maal akka taate maaltu si beeksise?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 11, '(Isheen) ibidda gubduudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 1, '(Qabeenya) Baay’ifachuun (ibaadaa irraa) isin jaataneesse (shaagale).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 2, 'Hanga awwaala dhaqxanitti (duutanitti).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 3, 'Dhorgamaa! Fuula dura beekuuf jirtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 4, 'Ergasiis dhorgamaa! Fuula dura beekuuf jirtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 5, 'Dhugumatti, odoo beekumsa mirkanaa’aa beektanii (hin shaagalamtanu ture).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 6, 'Dhugumatti ibidda ni argitu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 7, 'Ergasii argaa mirkanaa’aa arguuf jirtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 8, 'Ergasii guyyaa san qananiilee irraa gaafatamuuf jirtu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (103, 1, 'Yeroonin kakadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (103, 2, 'Dhugumatti, namni hunduu hoongoo keessa jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (103, 3, 'Isaan amanan, gaggaarii dalagan, haqa walii dhaamaniifi obsa walii dhaaman malee (warri hafan hoongoo guddaa keessa jiru).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 1, 'Hamattuufi arrabsituu hundaaf badiin mirkanaa’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 2, 'Isa qabeenya walitti qabee lakkaa''e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 3, 'Qabeenyi isaa isa hambisaa yaada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 4, 'Haa dhorgamu! [Ibidda] caccabsituu keessatti darbamuuf jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 5, 'Caccabsituun maal akka taate maaltu si beeksise?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 6, '(Isheen) ibidda Rabbii kan qabsiifamtuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 7, 'Ishee onneewwan irratti (laalaan ishee) mul’attuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 8, 'Dhugumatti, isheen isaan irratti cufamtuudha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 9, 'Utubaalee diriirfamaa keessatti (itti cufama).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (105, 1, 'Sila Gooftan kee Abbootii Arbaa irratti akkam akka dalage hin arginee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (105, 2, 'Sila shira isaanii dhabama hin goonee? (godheera).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (105, 3, 'Simbira garee gareedhaan isaanitti erge.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (105, 4, 'Dhagaalee xuubii (suphee gubamte) irraa taate isaan darbatti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (105, 5, 'Akka alalaa (okaa) nyaatamee isaan taasise.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (106, 1, 'Qurayshota barsiisuuf,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (106, 2, 'Fe’annaa gannaafi bonaa isaan barsiisuuf jecha (warra arbaa balleesse).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (106, 3, 'Gooftaa mana kanaa haa gabbaranu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (106, 4, 'Isa beela irraa isaan nyachiseefi sodaa irraa isaan tasgabbeesse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 1, 'Isa qormaata sobsiisu argitee?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 2, 'Sun isa yatiima humnaan deebisu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 3, 'Hiyyeessa nyaachisuu irrattis (namoota) hin kakaasu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 4, 'Warra salaataniif badiin mirkanaa’e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 5, 'Isaan sun warra salaata isaanii irraa dagatoo tahan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 6, 'Isaan warra (dalagaa namatti) agarsiifatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 7, 'Isaan meeshaa ergisaa dhorgataniif (badiin mirkanaa’e).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (108, 1, 'Nuti dhugumatti, tola guddaa siif kennineerra. [1]', '[1] kowsar laga jannatarraa tahe kan nabiif kennamuudhas jedhame.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (108, 2, 'Gooftaa keetiif sagadii isaaf qali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (108, 3, 'Dhugumatti, kan si jibbu isuma kan qaccee cite (kheyrii hunda irraa cite).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 1, 'Jedhi: "isin yaa warra Rabbitti kafartan!', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 2, 'Ani waan isin gabbartan hin gabbaru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 3, 'Isinis waan ani gabbaru kan gabbartan hin taane.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 4, 'Anis waan isin gabbartan (fuula duras) kan gabbaruu miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 5, 'Isinis waan ani gabbaru (fuula duras) kan gabbartanii miti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 6, 'Isiniif amantiin keessan jira; anaafis amantiin kiyya jira."', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (110, 1, 'Yeroo tumsi Rabbiitiifi banamiinsi (Makkaa) dhufe,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (110, 2, 'Namootas garee gareedhaan diinii Rabbii keessa kan seenan argite,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (110, 3, 'Gooftaa kee faarsuu wajjin qulqulleessi; araarama isa kadhadhu, inni akkaan tawbaa qeebalaa tahe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (111, 1, 'Harki Abuu Lahab lamaan badde [Innis] bade.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (111, 2, 'Qabeenyi isaatiifi wanti inni hores isa hin fayyanne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (111, 3, 'Ibidda abbaa bobayaa (belbelaa) taate seenuuf jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (111, 4, 'Niitiin isaas baadhattuu qoraanii taatee (seenti).', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (111, 5, 'Morma ishee keessa haada quncee temiraa irraa ta''etu jira.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (112, 1, 'Jedhi: "Inni Allaah (gabbaramaa dhugaa) tokkicha. [1]', '[1] sadarkaa suuraa tanaa keessatti hadiisa abiisaiid alkhudrii kan bukaariin odeesse keessatti Nabiin s.a.w. "Rabbii lubbuun tiyya harka isaa keessa jirtuun kakadhee isiin 1/3 tokko sadaffaa qur''aanaatti qixxaatti" jedhe.');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (112, 2, 'Allaahn hirkoo waa hundaati.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (112, 3, 'Hin dhalle hin dhalannes.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (112, 4, 'Hiriyaan tokkoos isaaf hin taane.”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (113, 1, 'Jedhi: "Gooftaa bariittin maganfadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (113, 2, 'Hamtuu waan Inni uumee irraa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (113, 3, 'Hamtuu dukkanaa yeroo dukkanaa’e irraas,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (113, 4, 'Hamtuu (dubartii sihrii) guduunfaalee keessatti tuftu irraas,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (113, 5, 'Hamtuu haasidii yeroo inni hassadu (waanyu) irraas (Rabbittin maganfadha).”', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 1, 'Jedhi: "Gooftaa namaattin maganfadha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 2, 'Mootii namaatti,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 3, 'Gabbaramaa namaatti,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 4, 'Hamtuu hasaassii (sheyxaana) dhokatuufi mul’atuu irraa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 5, 'Isa qomoota namaa keessa waswaasu irraa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 6, 'Jinniifi nama irraa kan ta’e (irraan maganfadha).”', '');
